local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["quest:4881"] = {n="Auftragsmordplan",s="In Tausend Nadeln gehen Zentauren gegen Kanati Grauwolke am Weißgipfelposten vor. Abgefangene Befehle enthüllen ihren Plan, den Taurenjäger anzugreifen.",h="In Tausend Nadeln gehen Zentauren gegen Kanati Grauwolke am Weißgipfelposten vor.",kw={"auftragsmordnotiz","auftragsmordplan","zentauren","der große aufzug","horde","kanati grauwolke","tausend nadeln","weißgipfelposten"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr den Weißgipfelposten als kleinen Vorposten südwestlich des Großen Aufzugs sehen. Kanatis Überleben ist wichtig für die Wacht der Horde über Tausend Nadeln.",["race:Tauren"]="Als Tauren wisst Ihr, dass der Hass auf die Zentauren tief im Gedächtnis der Tauren verwurzelt ist. Die Verteidigung Kanati Grauwolkes am Weißgipfelposten setzt den Kampf fort, Kalimdors Ebenen und Canyons vor den Angriffen der Zentauren zu schützen."},sec={{t="Ein Jäger in Feindesland",b="Kanati Grauwolke ist ein Taurenjäger, der am Weißgipfelposten im umkämpften Gebiet Tausend Nadeln lagert. Der kleine Posten liegt südwestlich des Großen Aufzugs, zwischen verfeindeten Zentaurenclans und gefährlichen Wildtieren. Die einheimischen Zentauren sehen sein Lager als dreistes Eindringen in ihr Territorium. Sie wollen Grauwolke töten und eine weitere Ausbreitung der Horde durch den Canyon verhindern."},{t="Die abgefangenen Befehle",b="Abgefangene Zentaurenbefehle nennen Kanati Grauwolke als ihr Ziel. Der Erlass verurteilt seine Dreistigkeit und befiehlt einer Angriffstruppe, am Weißgipfelposten zusammenzukommen, das Lager zu zerstören und jeden zu töten, der ihm folgen könnte. Mit den Befehlen in der Hand könnt Ihr Kanati rechtzeitig warnen, damit er sich auf den Überfall vorbereiten kann."}},faq={{q="Was ist der Auftragsmordplan?",a="Die einheimischen Zentauren planen einen koordinierten Hinterhalt gegen Kanati Grauwolke, den Taurenjäger, der am Weißgipfelposten in Tausend Nadeln lagert. Sie wollen ihn töten, damit die Horde im Canyon nicht Fuß fassen kann.",al={"auftragsmordplan überblick","worum geht es in dieser quest","plan der zentauren"}},{q="Wer ist Kanati Grauwolke?",a="Kanati Grauwolke ist ein Taurenjäger, der am Weißgipfelposten südwestlich des Großen Aufzugs in Tausend Nadeln lagert. Sein Lager liegt nahe dem Gebiet der Zentauren, was ihn zur Zielscheibe macht.",al={"wer ist kanati","kanati grauwolke","weißgipfelposten npc"}},{q="Warum wollen die Zentauren Kanati töten?",a="Die Zentauren sehen Kanatis Lager am Weißgipfelposten als unerträgliches Eindringen in Tausend Nadeln. Sie planen, ihn zu töten, das Lager zu zerstören und künftige Späher der Horde davon abzuhalten, sich in der Region niederzulassen.",al={"warum kanati töten","motiv der zentauren","warum greifen zentauren an"}},{q="Wo liegt der Weißgipfelposten?",a="Der Weißgipfelposten ist ein kleines Taurenlager auf dem Grund des Canyons in Tausend Nadeln, südwestlich des Großen Aufzugs.",al={"weißgipfelposten lage","wo ist kanatis lager","wo ist der weißgipfelposten"}},{q="Können Spieler der Allianz diese Quest abschließen?",a="Reisende der Allianz können die Auftragsmordnotiz bergen, aber sie können Kanati Grauwolke die Warnung nicht überbringen. Er ist ein Tauren der Horde, daher kann nur die Horde sie ihm bringen.",al={"kann die allianz das machen","allianz auftragsmordnotiz","allianz quest abgeben"}},{q="Was geschieht, nachdem Kanati gewarnt wurde?",a="Als Kanati die Warnung erhält, weigert er sich zu fliehen und bereitet sich darauf vor, die Angreifer abzuwehren. Die Verteidigung des Weißgipfelpostens beginnt, sobald die Kriegsschar der Zentauren eintrifft.",al={"was geschieht als nächstes","nächste quest","kanati beschützen"}}},fp="18,144,25.352.0,22.301.1,31.214.0,24.170.0,39.199.0,25.108.0,41.172.0,36.166.1"}
P.entries["quest:489"] = {n="Sucht Befreiung!",s="In Dolanaar verlangt der Zirkel des Cenarius, dass Ihr Wiedergutmachung leistet. Abenteurer wurden dazu verleitet, Zenn Faulhufs Willen auszuführen, und nun schickt Euch der Zirkel los, um ihn zum Verzehr verderbter Teufelszapfen zu überlisten.",h="In Dolanaar verlangt der Zirkel des Cenarius, dass Ihr Wiedergutmachung leistet.",kw={"dolanaar","teufelszapfen","kyra starsong","satyr","sucht befreiung","shayla nightbreeze","syral messerblatt","teldrassil","zenn faulhuf"},ang={["class:Druid"]="Als Druide ist Euch das Gleichgewicht Teldrassils heilig. Raubtiere und Aasfresser für einen von Dämonen befleckten Ausgestoßenen zu jagen, verstößt gegen die Grundsätze des Zirkels des Cenarius zum Schutz der Natur.",["race:NightElf"]="Für die Kaldorei ist es zutiefst beschämend, einem Satyr zu helfen. Die Brennende Legion machte die Satyrn während des War of the Ancients zu uralten Feinden, weshalb Wiedergutmachung vor dem Zirkel des Cenarius für die Ehre ihrer Kultur bedeutsam ist."},sec={{t="Ein Irrweg wird berichtigt",b="Direkt vor Dolanaar bringt der einsame Satyr Zenn Faulhuf Vorübergehende mit List dazu, seinen Willen auszuführen. Abenteurer, die unwissentlich Nachtsäbler, Strigideulen und Webholzspinnen töteten, um seine verdrehten Gelüste zu befriedigen, haben sich die scharfe Missbilligung des Zirkels des Cenarius zugezogen. Der Zirkel duldet keinen Schaden an der Natur, schon gar nicht durch seine eigenen Verbündeten."},{t="Der Preis der Sühne",b="Syral Messerblatt, Wächterin Kyra Starsong oder Wächterin Shayla Nightbreeze warnt Euch, Wiedergutmachung zu leisten, wenn Ihr in Teldrassil weiterhin willkommen sein wollt. Die Wächter von Dolanaar weisen Euch an, Faulhufs niederträchtige Völlerei gegen ihn zu wenden, statt ihm mit Stahl entgegenzutreten. Sammelt die dampfenden, verderbten Teufelszapfen vom Waldboden und bietet dem ahnungslosen Satyr dann eine Kostprobe seiner eigenen üblen Medizin an."},{t="Eine quakende Vergeltung",b="Ihr bringt Zenn Faulhuf die giftigen Zapfen und gebt Euch als treuer Laufbursche mit einer süßen Nascherei aus. Der Satyr ahnt nichts von der druidischen Falle. Gierig verschlingt er sie und wird augenblicklich in einen hilflosen Frosch verwandelt, gedemütigt vor der Wildnis, die er beflecken wollte."}},faq={{q="Warum ist der Zirkel des Cenarius zornig auf mich?",a="Ihr seid Zenn Faulhufs früheren Anweisungen gefolgt und habt unwissentlich Nachtsäbler, Strigideulen und Spinnen getötet. Der Zirkel des Cenarius betrachtet dieses sinnlose Töten als Schändung Teldrassils und verlangt Sühne.",al={"warum zirkel zornig","sucht befreiung warum","warum brauche ich befreiung"}},{q="Wer kann mir diese Quest geben?",a="Syral Messerblatt vor der nördlichen Behausung, Wächterin Kyra Starsong im Gasthaus oder Wächterin Shayla Nightbreeze an der westlichen Straße bieten sie Euch an, nachdem Ihr Faulhuf geholfen habt.",al={"questgeber","wer startet sucht befreiung","wo gibt es sucht befreiung"}},{q="Was sind Teufelszapfen?",a="Teufelszapfen sind verderbte Kiefernsamen von den verdrehten Ästen in Teldrassil. Grüne Dämpfe quellen aus ihren Hüllen, und Druiden wenden ihre üble Magie gegen ahnungslose Übeltäter.",al={"teufelszapfen","was ist ein teufelszapfen","woher kommen teufelszapfen"}},{q="Warum soll ich Zenn Faulhuf die Teufelszapfen anbieten?",a="Der Zirkel erwartet, dass Ihr Faulhuf eine Lektion erteilt. Er hält die verderbten Zapfen für eine harmlose Nascherei von jemandem, der einst seinen Willen ausführte.",al={"warum zenn zapfen geben","faulhufs nascherei","teufelszapfen trick"}},{q="Warum lebt ein Satyr so nahe bei Dolanaar?",a="Zenn Faulhuf lebt in einer Senke auf einer Lichtung direkt vor Dolanaar und verbirgt seine Bosheit hinter geheuchelter Freundlichkeit. Satyrn in ganz Kalimdor sind uralte Diener der Brennenden Legion, und seine Gegenwart zeigt, wie weit die Verderbnis in den jungen Weltbaum hineinreicht.",al={"warum ist zenn bei dolanaar","satyr in dolanaar","zenn faulhuf hintergrundgeschichte"}},{q="Kann ich diese Quest überspringen oder abbrechen, ohne mein Ansehen zu ruinieren?",a="Ja. Der Zirkel des Cenarius tadelt Euch dafür, Faulhuf geholfen zu haben, doch die Quest unvollendet zu lassen schadet weder Eurem Ansehen noch Eurem Ruf bei den Nachtelfen von Darnassus.",al={"rufverlust","kann ich sucht befreiung abbrechen","sucht befreiung scheitern"}}},fx={["680beeda"]={q="Warum lassen die Wächterinnen mich mit Zenn Faulhuf befassen, anstatt es selbst zu tun?",a="Ihr habt dies selbst heraufbeschworen, indem Ihr zuvor Zenn Faulhufs Befehle ausgeführt und den Wald geschändet habt. Der Rat des Waldes hat von Euren Verfehlungen erfahren, und die lokalen Wächterinnen erwarten von Euch, dass Ihr Euer Unrecht wiedergutmacht. Da Zenn Euch bereits vertraut, Gegenstände für ihn zu besorgen, seid Ihr in der einzigartigen Lage, den Satyr mit korrumpierten Zapfen, die als unschuldiger Snack getarnt sind, anzusprechen, ohne Argwohn zu erregen.",al={"warum kümmern sich wachen nicht um zenn","warum muss ich zenn austricksen","warum schicken mich die wächterinnen"}}},fp="16,204,22.347.0,22.386.0,22.267.1,47.213.0,27.187.0,19.183.0,41.140.1,49.256.0,65.168.0"}
P.entries["quest:490"] = {n="Bounty: Gnarlpine Furbolg",s="Vor Darnassus gilt weiterhin das Kopfgeld der Allianz auf die Gnarlpine-Furbolgs. Verderbnis breitet sich in Teldrassil aus, und Shayla Nightbreeze bittet Jäger, die Hauer der Bestien zurückzubringen.",h="Vor Darnassus gilt weiterhin das Kopfgeld der Allianz auf die Gnarlpine-Furbolgs.",kw={"lichtung von ban'ethil","kopfgeld","verderbnis","darnassus","furbolg","gnarlpine","gnarlpine-hauer","schildwachen","shayla nightbreeze","sternenhauch","teldrassil"},ang={["class:Druid"]="Als Druide seht Ihr, wie die Gnarlpine ihre Harmonie mit der Natur verloren haben. Ihre Feindseligkeit gefährdet nun das Gleichgewicht der Lichtung, die zu bewahren Ihr geschworen habt.",["faction:Alliance"]="Die Schildwachen rufen Abenteurer der Allianz dazu auf, die Heimat der Nachtelfen vor Verderbnis zu schützen, indem sie gefährliche Furbolglager auf den Ästen räumen.",["race:NightElf"]="Die Gnarlpine waren einst friedliche Nachbarn und Verbündete der Kaldorei. Ihre Verderbnis bedroht nun Teldrassil."},sec={{t="Ein Erlass der Schildwachen",b="Vor Darnassus überbringt Shayla Nightbreeze den Befehl der Schildwachen, ein Kopfgeld auf die Gnarlpine-Furbolgs auszusetzen. Einst lebten sie friedlich in den uralten Wäldern. Nun hat Verderbnis ihnen den Verstand geraubt und sie zu bösartigen Bedrohungen für Reisende und die heilige Natur Teldrassils gemacht."},{t="Säuberung der Lager",b="Jäger dezimieren die Gnarlpine auf den Ästen des Weltbaums und sammeln ihre Hauer als Beweis. Die Lichtung von Ban'ethil liegt südlich der Straße westlich von Dolanaar und ist eine ihrer beiden großen Hochburgen. Die andere ist das zerstörte Sternenhauch im Osten."}},faq={{q="Wer setzt das Kopfgeld auf die Gnarlpine-Furbolgs aus?",a="Shayla Nightbreeze setzt das Kopfgeld an der Straße vor Darnassus aus, der Hauptstadt Teldrassils.",al={"wer vergibt kopfgeld auf gnarlpine-furbolgs","wo gibt es das gnarlpine-kopfgeld","shayla nightbreeze aufenthaltsort"}},{q="Warum werden die Gnarlpine-Furbolgs gejagt?",a="Verderbnis hat den Gnarlpine den Verstand geraubt und sie zu aggressiven Bedrohungen für Reisende, Nachtelfensiedlungen und die heimische Tierwelt Teldrassils gemacht.",al={"warum gnarlpine töten","warum sind gnarlpine feindselig","was ist mit den gnarlpine-furbolgs geschehen"}},{q="Wo sind die Gnarlpine-Furbolgs zu finden?",a="Die Gnarlpine versammeln sich auf der Lichtung von Ban'ethil, westlich von Dolanaar und südlich des Hauptwegs, sowie in Sternenhauch weiter östlich.",al={"gnarlpine-furbolgs fundorte","wo sind gnarlpine auf teldrassil","wo sind furbolgs zu finden"}},{q="Welcher Beweis ist nötig, um das Kopfgeld zu erhalten?",a="Shayla Nightbreeze verlangt Hauer der Gnarlpine als handfesten Beweis dafür, dass die Bedrohung durch die Furbolgs auf den Ästen des Weltbaums beseitigt wurde.",al={"beweis für gnarlpine-kopfgeld","welchen beweis will shayla","gnarlpine-hauer als beweis"}},{q="Wer hat das Kopfgeld auf die Gnarlpine genehmigt?",a="Die Schildwachen genehmigten das Kopfgeld durch direkte Befehle zur Sicherung der Äste Teldrassils. Sie sind die militärischen Beschützer der Nachtelfen.",al={"wer hat das gnarlpine-kopfgeld angeordnet","wer hat das furbolg-kopfgeld genehmigt"}},{q="Waren die Gnarlpine den Nachtelfen schon immer feindlich gesinnt?",a="Die Furbolgs waren einst mit den Nachtelfen verbündet und lebten friedlich an ihrer Seite. Verderbnis hat ihren Geist verdreht und diesen Frieden zerstört.",al={"waren furbolgs schon immer feinde","waren furbolgs früher freundlich"}}},fp="25,187,27.290.0,23.256.0,47.93.0,43.154.0,41.126.0,43.139.0,43.139.0,53.133.0"}
P.entries["quest:4904"] = {n="Endlich frei",s="Lakota Windweise ist auf dem Rückweg zu Thalia Bernhaut am Freiwindposten. Nachdem sie Arnak Grimtotem abgewiesen hatte, wurde sie in seine Festung über Tausend Nadeln verschleppt und braucht nun Schutz auf dem Heimweg.",h="Lakota Windweise ist auf dem Rückweg zu Thalia Bernhaut am Freiwindposten.",kw={"arnak grimtotem","düsterwolkengipfel","eskorte","endlich frei","freiwindposten","lakota windweise","thalia bernhaut","tausend nadeln"},ang={["faction:Horde"]="Die Horde hält den Freiwindposten als unverzichtbare Festung im Süden Kalimdors. Die Gesetzlosigkeit der Grimtotem und die Entführungen am Düsterwolkengipfel bedrohen die Straße.",["race:Tauren"]="Der Klan der Grimtotem zeigt durch Entführungen und Mord seine Missachtung für Frieden und Einigkeit unter den Tauren, selbst unter den Augen des Freiwindpostens."},sec={{t="Eine brutale Entführung",b="Arnak Grimtotem wollte Lakota Windweise zu seiner Braut machen. Als sie ihn abwies, kehrte er nachts zurück und griff ihr Zuhause an. Lakotas Bruder versuchte, sie zu verteidigen, doch Arnak streckte ihn nieder. Dann verschleppte er Lakota auf den Düsterwolkengipfel."},{t="Flucht vom Düsterwolkengipfel",b="Der Düsterwolkengipfel erhebt sich über Tausend Nadeln, und hohe Holzbrücken verbinden seine Felsnadeln. Krieger der Grimtotem bewachen die Höhen. Während Lakota hinabsteigt, wehrt Ihr Banditen ab, die sie ergreifen wollen, bevor sie den Grund des Canyons erreicht."},{t="Eine bittere Heimkehr",b="Lakota erreicht den Grund des Canyons und begibt sich in die Sicherheit des Freiwindpostens. Dort empfängt Thalia Bernhaut sie erleichtert, auch wenn sie um Lakotas Bruder trauert. Thalia übergibt seine verbliebenen Habseligkeiten jenen, die Lakota lebend nach Hause gebracht haben."}},faq={{q="Warum wurde Lakota Windweise gefangen genommen?",a="Arnak Grimtotem wollte Lakota Windweise zu seiner Braut machen. Nachdem sie ihn abgewiesen hatte, griff er ihr Zuhause bei Nacht an. Er streckte ihren Bruder nieder, als dieser sie zu verteidigen versuchte, und verschleppte Lakota dann auf den Düsterwolkengipfel.",al={"warum ist lakota gefangen","wer hat lakota entführt","warum hat arnak lakota verschleppt"}},{q="Wo liegt der Düsterwolkengipfel?",a="Der Düsterwolkengipfel ist eine Gruppe hoch aufragender, durch Brücken verbundener Felsnadeln im Norden von Tausend Nadeln. Er liegt direkt südöstlich des Großen Aufzugs und südlich der Hügel der Klingenhauer.",al={"düsterwolkengipfel lage","wie zum düsterwolkengipfel gelangen","wo ist lakota"}},{q="Wer ist Arnak Grimtotem?",a="Arnak Grimtotem ist ein skrupelloses Mitglied des Stammes der Grimtotem, das auf dem Düsterwolkengipfel stationiert ist. Er entführte Lakota und tötete ihren Bruder. Die Obrigkeit der Horde am Freiwindposten hat ihn zum Tode verurteilt.",al={"arnak hintergrund","wer ist arnak","gesucht arnak"}},{q="Mit wem solltet Ihr nach der Rettung sprechen?",a="Nachdem Lakota den Grund des Canyons erreicht hat, kehrt zum Freiwindposten auf den hohen Klippen zurück und sprecht mit Thalia Bernhaut.",al={"wo endlich frei abgeben","wer ist thalia bernhaut","endlich frei abgeben"}},{q="Warum greifen die Grimtotem während der Flucht an?",a="Arnaks Banditen der Grimtotem patrouillieren auf den Höhen des Düsterwolkengipfels. Sie überfallen jeden, der Lakota, die er gefangen halten will, in die Freiheit zu helfen versucht.",al={"warum erscheinen banditen","grimtotem banditen eskorte"}},{q="Was geschieht mit Lakotas Bruder?",a="Lakotas Bruder wurde getötet, als er sie während der Entführung gegen Arnak Grimtotem verteidigte. Thalia übergibt seine Erbstücke später jenen, die Lakota retten.",al={"lakotas bruder","wer starb bei lakotas rettung","was geschah mit lakotas bruder"}}},fx={aa9c9984={q="Warum braucht Lakota Windweise Eure Hilfe bei der Flucht?",a="Lakota wurde von Arnak Grimtotem gewaltsam entführt, nachdem sie seinen Heiratsantrag abgelehnt hatte, und ihr Bruder wurde bei dem Versuch, sie zu verteidigen, getötet. Hoch oben auf dem Düsterwolkengipfel, umgeben von feindseligen Grimtotem-Kriegern, gefangen, kann sie sich nicht allein den Weg nach unten freikämpfen. Verzweifelt versucht sie, Arnaks erzwungener Brautwerbung zu entkommen und zu Thalia Bernhaut beim Freiwindposten zurückzukehren, weshalb sie Eure bewaffnete Eskorte benötigt, um einen Pfad durch die Banditen zu schlagen, die die Mesas bewachen.",al={"warum lakota windweise helfen","lakota motiv","warum braucht lakota eskortierung"}}},fp="12,209,18.226.0,30.242.0,19.246.0,33.206.0,36.173.0,23.198.0,41.116.0,46.146.0,33.146.0"}
P.entries["quest:491"] = {n="Zauberstab an Bethor",s="Auf Burg Fenris soll der Gewebte Zauberstab zu Bethor Eismacht in die Unterstadt gelangen. Drei Magierlehrlinge fertigten ihn als Zeichen ihrer Verbundenheit, doch Thule Rabenklaue versteckte ihn, nachdem er sich für die Geißel entschieden hatte. Seine Rückkehr bringt ein Stück von Bethors sterblicher Jugend ins Magieviertel zurück.",h="Auf Burg Fenris soll der Gewebte Zauberstab zu Bethor Eismacht in die Unterstadt gelangen.",kw={"bethor eismacht","insel fenris","burg fenris","magieviertel","silberwald","thule ravenclaw","unterstadt","gewebter zauberstab"},ang={["class:Mage"]="Für einen Magier erinnert der Gewebte Zauberstab an eine arkane Tradition: Magierlehrlinge vereinen ihre Foki als Zeichen der Verbundenheit. Die Geißel zerstörte diese Unschuld, als sie Dalaran und Lordaeron zerriss.",["race:Undead"]="Als Mitglied der Verlassenen mögt Ihr in alten Artefakten Erinnerungen an sterbliche Hoffnungen und frühere Freunde sehen. Bethors Andenken erinnert an jene, die die Tyrannei des Lichkönigs dem freien Willen vorzogen."},sec={{t="Zeichen einer zerbrochenen Gemeinschaft",b="Bevor Lordaeron fiel, vereinten drei junge Magier ihre Übungszauberstäbe zu einem einzigen: dem Gewebten Zauberstab. Er stand für ihre Freundschaft und ihre gemeinsamen Hoffnungen in den magischen Künsten.\n\nDann schwor Thule Rabenklaue dem Lichkönig die Treue und schloss sich der Geißel an. Ihre Gemeinschaft zerbrach. Er begann, ihre einstige Freundschaft zu verachten, konnte den Zauberstab jedoch weder zerstören noch seinen früheren Gefährten überlassen."},{t="In der Burg verborgen",b="Thule Rabenklaue brachte den Gewebten Zauberstab zur Insel Fenris und versteckte ihn auf einem staubigen Regal in Burg Fenris. Dort lag er jahrelang unberührt, während seine Verzauberung schlummerte.\n\nBethor merkte an, dass der Gebrauch seiner Magie den Aufenthaltsort des Zauberstabs sofort verraten hätte. Seine Rückkehr ins Magieviertel der Unterstadt schenkt Bethor ein Andenken an seine sterbliche Jugend, geborgen aus dem Versteck eines Verräters, der seine Freunde weder lieben noch loslassen konnte."}},faq={{q="Was ist der Gewebte Zauberstab?",a="Der Gewebte Zauberstab ist ein magisches Werkzeug, das Thule Rabenklaue, Bethor Eismacht und ein dritter Magierlehrling vor langer Zeit fertigten. Jeder steuerte einen seiner ersten Übungszauberstäbe bei, und die drei wurden als Zeichen ihrer Freundschaft und ihrer gemeinsamen arkanen Studien miteinander verwoben.",al={"gewebter zauberstab","was ist der zauberstab","thule zauberstab geschichte"}},{q="Warum stahl Thule Rabenklaue den Zauberstab?",a="Als Thule Rabenklaue sich dem Lichkönig zuwandte, zerbrach seine Verbindung zu den anderen Magiern. Er begann zu hassen, wofür der Zauberstab stand, wollte sich jedoch weder davon trennen noch ihn Bethor und ihrem anderen Gefährten überlassen. Er versteckte ihn auf der Insel Fenris.",al={"warum nahm thule ihn","warum den zauberstab stehlen","thule gestohlener zauberstab"}},{q="Wer ist Bethor Eismacht?",a="Bethor Eismacht ist ein mächtiger Magier der Verlassenen, der im Magieviertel der Unterstadt lebt. Bevor Lordaeron fiel, war er Thule Ravenclaws Weggefährte und Freund. Später unterwarf Thule seinen Willen der Geißel.",al={"wer ist bethor","bethor eismacht geschichte","bethor unterstadt"}},{q="Warum nutzte Thule die Magie des Gewebten Zauberstabs nicht?",a="Bethor hätte die Verzauberung des Zauberstabs durch das arkane Geflecht hindurch gespürt, wenn Thule ihn benutzt hätte. Thule ließ seine Macht auf einem vergessenen Regal in Burg Fenris unberührt und behielt den Zauberstab aus Trotz und Besitzgier.",al={"hat thule den zauberstab benutzt","macht des zauberstabs","warum ihn nicht benutzen"}},{q="Wer war der dritte Lehrling, der den Zauberstab miterschuf?",a="Gunther Arkanus war der dritte Lehrling, der seinen Zauberstab mit denen von Bethor und Thule verband, lange bevor Thule sie verriet.",al={"dritter lehrling","drei magier zauberstab","dritter magier"}},{q="Wo befand sich der Zauberstab, bevor er gefunden wurde?",a="Thule Rabenklaue versteckte den Zauberstab auf einem staubigen Regal in einer verborgenen Nische in Burg Fenris auf der Insel Fenris. In dieser Festung hatte er den Stützpunkt für seine Unternehmungen im Dienste der Geißel eingerichtet.",al={"wo war der zauberstab","verborgene nische zauberstab","burg fenris zauberstab"}}},fp="14,266,31.403.0,18.430.1,23.237.0,39.232.0,23.206.0,44.211.0,54.120.0,45.160.0"}
P.entries["quest:492"] = {n="Eine neue Seuche",s="In Brill wird „Eine neue Seuche“ erstmals an einem gefangenen Zwerg getestet. Apotheker Johaan schickt Euch mit seinem Gebräu aus Reagenzien aus ganz Tirisfal in den Keller der Taverne Zur Galgenschlinge.",h="In Brill wird „Eine neue Seuche“ erstmals an einem gefangenen Zwerg getestet.",kw={"eine neue seuche","apotheker johaan","brill","gefangener gebirgsjäger","galgenschlinge","seuche","gift","königliche apothekervereinigung","tirisfal"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie erbarmungslos die Verlassenen mit Eindringlingen der Allianz umgehen, die in Lordaeron aufgegriffen werden.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie die Verlassenen durch kalte alchemistische Kriegsführung nach dem Sieg streben, selbst gegen Freund oder Feind.",["race:Dwarf"]="Als Zwerg seht Ihr, wie weit die Gebirgsjäger aus Eisenschmiede vordringen, um Tirisfal zu beobachten, und dabei Tod und heimliche Verhöre riskieren.",["race:Undead"]="Als Untoter seht Ihr den kompromisslosen Überlebenskampf der Verlassenen und die tödliche Arbeit der Königlichen Apothekervereinigung."},sec={{t="Ein tödliches Gebräu",b="Apotheker Johaan hat seine Forschung bis zu einem gefährlichen Versuch vorangetrieben. Die Königliche Apothekervereinigung dient Fürstin Sylvanas Windläufer und sucht nach einer Seuche, die Lebende tötet und untote Körper unversehrt lässt. Johaan hat gebraut, was er ein „spezielles Getränk“ nennt. Er schickt Euch los, um es einem gefangenen Feind der Verlassenen zu geben."},{t="Der Keller der Galgenschlinge",b="In Brill hält die Todeswache Gefangene in einem feuchten Keller unter der Taverne Zur Galgenschlinge fest. Sie warten auf ihr Verhör oder ihre Beseitigung. Ein Gefangener ist ein Zwergengebirgsjäger, ein Späher aus Eisenschmiede, der beim unerlaubten Eindringen in Tirisfal gefasst wurde. Trotzig und durstig nimmt er das Getränk begierig an, ohne zu ahnen, was Johaan hineingemischt hat."},{t="Eine schaurige Vorführung",b="Der gefangene Gebirgsjäger trinkt aus der Flasche und vergleicht das Getränk wehmütig mit Rhapsody-Malzbier. Er prahlt damit, dass Zwergendampfpanzer kommen, um ihn zu retten. Das Gift tötet ihn fast augenblicklich. Johaans letzte Worte enthüllen, dass dieses tödliche Gebräu nur ein Vorgeschmack auf das ist, was die Dunkle Fürstin für den Rest von Azeroth vorsieht."}},faq={{q="Wer ist Apotheker Johaan?",a="Apotheker Johaan ist ein Mitglied der Königlichen Apothekervereinigung und in Brill in Tirisfal stationiert. Er leitet die ersten Arbeiten an einer Seuche für die Kriegsführung der Verlassenen und lässt Abenteurer tödliche Reagenzien in der umliegenden Wildnis sammeln.",al={"apotheker johaan","wer vergibt eine neue seuche","johaan brillanz"}},{q="Warum wird ein Zwerg in Brill gefangen gehalten?",a="Gebirgsjäger aus Eisenschmiede erkunden die nördlichen Königreiche, um die Bewegungen der Verlassenen zu beobachten und die Pestländer zu untersuchen. Die Todeswache fasste diesen Späher in Tirisfal und sperrte ihn in den Tavernenkel­ler, bis die Apotheker eine Verwendung für ihn fanden.",al={"zwerg im keller","gefangener gebirgsjäger","warum ist ein zwerg in tirisfal"}},{q="Was geschieht, wenn Ihr dem Gefangenen das Getränk gebt?",a="Der Zwerg nimmt den Krug freudig entgegen, durstig nach seiner Gefangennahme. Das giftige Gebräu tötet ihn kurz nach dem Trinken und zeigt die Wirkung von Johaans neuester Seuchenrezeptur.",al={"stirbt der zwerg","wirkung des getränks","tod des gebirgsjägers"}},{q="Was ist das Ziel der Forschung zu New Plague?",a="Die Verlassenen suchen auf Befehl von Fürstin Sylvanas Windläufer nach einer neuen Seuche. Sie wollen eine Waffe schaffen, die sowohl die willenlose Geißel als auch die lebenden Völker vernichten kann, die ihr Gebiet bedrohen.",al={"warum eine neue seuche erschaffen","ziel der königlichen apothekervereinigung","seuche der dunklen fürstin"}},{q="Wo befindet sich der Gefangene Gebirgsjäger?",a="Der Gefangene Gebirgsjäger wird unten im Keller der Taverne Zur Galgenschlinge festgehalten, im Zentrum von Brill in Tirisfal.",al={"gefangenen zwerg finden","keller der galgenschlinge","wo ist der gebirgsjäger"}},{q="Geht diese Questreihe nach diesem Zwerg weiter?",a="Johaans vierteiliger Auftrag endet mit dem Tod des Gebirgsjägers. Die Forschung zu New Plague geht in ganz Lordaeron weiter, mit weiteren Versuchen in Unterstadt und im Grabmal.",al={"nächste quest","eine neue seuche folgequest","nach dem tod des gebirgsjägers"}}},fx={["38956767"]={q="Warum will Apotheker Johaan den Gebirgsjäger vergiften?",a="Apotheker Johaan führt praktische Versuche für die neue Seuche der Gesellschaft der Königlichen Apotheker durch. Nachdem er seine Gebräue mit lokalem Gift und Blut verfeinert hat, benötigt er ein lebendes Subjekt, um dessen Tödlichkeit aus erster Hand zu beobachten. Ein gefangener Feind der Dunklen Fürstin, der hilflos im Keller der Taverne sitzt, bietet die perfekte Gelegenheit, zu testen, ob sein Gebräu sterbliche Feinde schnell auslöschen kann.",al={"warum will johaan das erledigt haben","johaan motiv gefangener gebirgsjäger","warum gift an zwerg testen"}}},fp="12,197,19.322.0,23.309.0,24.309.1,25.222.0,39.236.0,50.171.1,47.192.0,42.124.0,49.178.0"}
P.entries["quest:4921"] = {n="In der Schlacht vermisst",s="Am Wegekreuz sucht Mankrik nach seiner Frau, die seit einem Hinterhalt der Borstennacken in einem Taurenlager vermisst wird. Verwundet und außerstande, selbst nach ihr zu suchen, bittet er Reisende, im Brachland nach einer Spur von ihr zu suchen.",h="Am Wegekreuz sucht Mankrik nach seiner Frau, die seit einem Hinterhalt der Borstennacken in einem Taurenlager...",kw={"borstennacken","das wegekreuz","goldstraße","in der schlacht vermisst","mankrik","mankriks frau","stacheleber","taurenlager"},ang={["class:Druid"]="Ein Tauren-Druide, der auf der Goldstraße vorbeizog, fand Mankrik, als dieser zusammenbrach. Der Druide versorgte seine schweren Wunden und hielt ihn am Leben.",["faction:Horde"]="Mankriks Bitte zeigt, welche Gefahr von den Borstennacken-Stachelebern für Siedler und Patrouillen der Horde ausgeht, die durch das Brachland ziehen.",["race:Orc"]="Mankrik kämpfte erbittert in orkischer Kampfeswut, um seine Gefährtin zu verteidigen, doch die Schar der Stacheleber überwältigte ihn.",["race:Tauren"]="Der Hinterhalt ereignete sich in einem kleinen Taurenlager. Ein umherziehender Tauren-Druide versorgte Mankriks Wunden an der Goldstraße und rettete ihm das Leben."},sec={{t="Hinterhalt im Lager",b="Mankrik, ein Orc-Krieger am Wegekreuz, kämpfte an der Seite seiner Frau in einem kleinen Taurenlager. Plötzlich wurden sie von Borstennacken-Stachelebern überrannt. Seine Frau hielt allein drei Angreifer ab, doch frische Verstärkung schnitt sie im Kampf von Mankrik ab."},{t="Eine verzweifelte Suche",b="Mankrik stellte sich den vorrückenden Stachelebern in blindem Zorn entgegen, doch ihre Überzahl brachte ihn bald zu Fall. Ein vorbeiziehender Tauren-Druide fand ihn dem Tode nahe auf der Goldstraße und versorgte seine Wunden. Noch immer zu schwer verletzt, um nach seiner Frau zu suchen, bittet Mankrik Reisende am Wegekreuz, im ganzen Brachland nach ihr zu suchen und jede Spur von ihr zurückzubringen."}},faq={{q="Wer ist Mankrik?",a="Mankrik ist ein Orc-Krieger, der sich am Wegekreuz im Brachland erholt. Stacheleber trennten ihn von seiner Frau, und er bittet Reisende, im Buschland nach einer Spur von ihr zu suchen.",al={"wer ist mankrik","wer vergibt diese quest","mankriks hintergrundgeschichte"}},{q="Was geschah während der Schlacht mit Mankriks Frau?",a="Mankrik und seine Frau kämpften gemeinsam in einem kleinen Taurenlager, als Borstennacken-Stacheleber sie aus dem Hinterhalt angriffen. Sie hielt allein drei Angreifer ab, bevor frische Verstärkung sie überwältigte und von Mankrik trennte.",al={"was geschah mit mankriks frau","wo ist seine frau","angriff auf mankriks frau"}},{q="Wie überlebte Mankrik den Hinterhalt der Stacheleber?",a="Ein umherziehender Tauren-Druide fand Mankrik auf der Goldstraße, nachdem die Stacheleber ihn überwältigt hatten. Der Druide versorgte seine lebensgefährlichen Wunden und rettete ihn.",al={"wer rettete mankrik","wie überlebte mankrik","druide auf der goldstraße"}},{q="Wer griff Mankrik und seine Frau an?",a="Borstennacken-Stacheleber überrannten ein kleines Taurenlager und griffen Mankrik und seine Frau an. Trotz ihrer erbitterten Gegenwehr wurden die beiden von der Überzahl überwältigt.",al={"wer griff sie an","stacheleber im brachland","borstennacken-angreifer"}},{q="Wo sollten Reisende nach Mankriks Frau suchen?",a="Mankrik wurde auf der Goldstraße gefunden, nachdem er nahe einem kleinen, von Borstennacken überrannten Taurenlager gefallen war. Reisende können in den von Stachelebern heimgesuchten Gebieten im ganzen Brachland nach seiner Frau suchen.",al={"wo nach ihr suchen","wo nach mankriks frau suchen"}},{q="Wo ist Mankrik jetzt zu finden?",a="Mankrik erholt sich am Wegekreuz im Brachland. Er wartet auf Neuigkeiten oder irgendeine Spur seiner vermissten Frau.",al={"warum wegekreuz","wo ist mankrik jetzt"}}},fp="14,201,18.238.0,18.333.0,15.176.0,50.218.0,44.151.0,34.144.0,47.180.0,31.106.0"}
P.entries["quest:493"] = {n="Reise in das Vorgebirge des Hügellands",s="Renferrel schickt seine Forschung nach Süden nach Tarrens Mühle, wo Apotheker der Verlassenen ihre Seuchenstudien vorantreiben. Ihr bringt seine Aufzeichnungen aus dem Silberwald zu Apotheker Lydon im Vorgebirge des Hügellands.",h="Renferrel schickt seine Forschung nach Süden nach Tarrens Mühle, wo Apotheker der Verlassenen ihre...",kw={"hillsbrad","lydon","new plague","renferrel","royal apothecary society","silberwald","sylvanas","tarrens mühle"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Herrschaft der Verlassenen in Hillsbrad zu sichern und den Einfluss der Horde in den Östlichen Königreichen zu stärken, trotz der Bedenken von Orcs und Tauren gegenüber heimtückischen Giften.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass Renferrel und Lydon hochgiftige, mutierte Pflanzen aus ganz Lordaeron untersuchen und sammeln.",["race:Undead"]="Als Verlassener helft Ihr Eurem Volk, sein Überleben zu sichern und sich an den Lebenden und der Geißel zu rächen."},sec={{t="Eine eigene Seuche",b="Seit ihrer Befreiung aus der Kontrolle des Lichkönigs arbeitet Fürstin Sylvanas Windläufer an einer New Plague, die sowohl die Lebenden als auch die Geißel vernichten könnte. Die Royal Apothecary Society arbeitet unter dem unerbittlichen Druck der Bansheekönigin daran, sie zu erschaffen. Ihre Forscher sind über ganz Lordaeron verstreut und tauschen deshalb chemische Daten und Versuchsergebnisse aus, um ihre Arbeit zu beschleunigen."},{t="Der Weg nach Süden",b="Apotheker Renferrel arbeitet vom Grabmal im Silberwald aus. Er schickt Euch mit seinen jüngsten Forschungsergebnissen für Apotheker Lydon nach Süden. Euer Weg führt aus den Kiefernwäldern hinaus und über offene Weiden im Vorgebirge des Hügellands. Tarrens Mühle liegt am Fuße des Alteracgebirges, ein Außenposten, von dem aus die Verlassenen ihre Forschung betreiben."}},faq={{q="Was enthalten Renferrels Forschungsergebnisse?",a="Renferrels Aufzeichnungen dokumentieren seine Experimente mit heimischen Pflanzen, Tieren und biologischen Giften. Sie ergänzen die Arbeit der Royal Apothecary Society an der New Plague.",al={"was sind die forschungsergebnisse","renferrels forschung","was wird überbracht"}},{q="Warum hat es die Royal Apothecary Society so eilig?",a="Fürstin Sylvanas Windläufer verlangt schnelle Ergebnisse. Die Verlassenen stehen feindseligen Überresten der Menschen, dem Scharlachroten Kreuzzug und umherstreifenden Angehörigen der Geißel gegenüber. Sie glauben, eine biologische Waffe könne ihr Überleben sichern und Arthas rächen.",al={"warum eile bei der seuche","warum unter druck","sylvanas druck"}},{q="Wer ist Apotheker Lydon?",a="Apotheker Lydon ist ein hochrangiger Forscher der Royal Apothecary Society, der in Tarrens Mühle stationiert ist. Renferrel und seine Kollegen respektieren ihn. Er beaufsichtigt biologische Experimente im Vorgebirge des Hügellands und verfeinert Seuchenstämme mithilfe örtlicher Vorräte und Gefangener.",al={"wer ist lydon","apotheker lydon hintergrund"}},{q="Wo liegt Tarrens Mühle?",a="Tarrens Mühle liegt im nördlichen Vorgebirge des Hügellands, südlich des Alteracgebirges und östlich des Silberwalds. Folgt den Hauptstraßen vom Silberwald nach Süden und biegt dann an der Wegkreuzung nach Osten ab, um dorthin zu gelangen.",al={"tarrens mühle lage","weg nach tarrens mühle","wo liegt hillsbrad"}},{q="Warum müssen die Verlassenen ihre Forschungsergebnisse durch Boten zu Fuß austauschen?",a="Renferrel bittet Euch, seine schriftlichen Forschungsergebnisse vom Grabmal zu Lydon in Tarrens Mühle zu bringen. Er möchte, dass die weit verstreuten Forscher der Gesellschaft Entdeckungen schnell austauschen, nennt aber keinen Grund für den Einsatz von Fußboten statt magischer Mittel.",al={"warum bote zu fuß","warum zustellung durch kuriere"}},{q="Was geschieht, nachdem Lydon die Forschungsergebnisse erhalten hat?",a="Nachdem Apotheker Lydon Renferrels Aufzeichnungen erhalten hat, studiert er sie und lässt die Ergebnisse in seine eigenen Mixturen einfließen. Später bittet er Abenteurer, verbesserte Stämme an der örtlichen menschlichen Bevölkerung zu testen.",al={"was folgt nach der übergabe","lydons reaktion"}}},fx={c31bc166={q="Warum will Apotheker Renferrel seine Ergebnisse übermittelt haben?",a="Die Gesellschaft der Königlichen Apotheker steht unter starkem Druck von Lady Sylvanas, eine A New Plague zu entwickeln, um das Überleben der Verlassenen zu sichern. Renferrel weiß, dass ihre alchemistischen Durchbrüche nur dann schnell gelingen können, wenn die Apotheker ihre Forschung bündeln, anstatt isoliert zu arbeiten. Indem er seine neuesten Entdeckungen an Apotheker Lydon in Tarrens Mühle sendet, hofft er, den kollektiven Fortschritt der Gesellschaft zu beschleunigen.",al={"warum erkenntnisse an lydon senden","renferrel motiv","warum seuche-forschung übermitteln"}}},fp="30,201,21.357.0,14.315.0,36.158.0,51.211.0,24.244.0,21.202.0,61.235.0,43.197.1"}
P.entries["quest:494"] = {n="Zeit zum Zuschlagen",s="An Hillsbrads Grenze schickt Lesch eine Warnung nach Osten, nach Tarrens Mühle. Ihre verschlüsselten Worte führen von stiller Beobachtung zu den Plänen der Verlassenen gegen die menschlichen Siedler.",h="An Hillsbrads Grenze schickt Lesch eine Warnung nach Osten, nach Tarrens Mühle.",kw={"todespirscherin lesch","hochexekutorin darthalia","hillsbrad","vorgebirge des hügellands","aufklärung","tarrens mühle","varimathras"},ang={["class:Rogue"]="Als Schurke erkennt Ihr die verdeckte Beobachtung und die verschlüsselten Nachrichten der Todespirscher. Sie sind Unterstadts Elitegilde von Meuchelmördern und Spähern.",["faction:Horde"]="Als Mitglied der Horde werdet Ihr tiefer in den Konflikt zwischen den Verlassenen und den menschlichen Siedlungen im Süden hineingezogen.",["race:Undead"]="Als Agenten der Verlassenen helft Ihr, Lordaerons Ostgrenze gegen die verbliebenen Menschen der Allianz zu sichern, wenn Ihr Leschs Depesche überbringt."},sec={{t="Eine Wache an der Grenze",b="Todespirscherin Lesch beobachtet das Tal von einer Anhöhe nahe der Grenze zwischen dem Silberwald und dem Vorgebirge des Hügellands aus. Unter ihr ziehen menschliche Siedler und Milizen durch das Tal. Die Todespirscher beobachten feindliche Siedlungen für Unterstadt, bevor dessen Truppen ausrücken. Lesch hält ihren Posten und bittet vorbeiziehende Reisende der Horde, ihre gesammelten Erkenntnisse die Straße hinunter nach Tarrens Mühle zu bringen."},{t="Ein verschlüsselter Ruf",b="Leschs Nachricht ist verschlüsselt: „Der Schrei des Raben aus dem Westen ruft.“ Nach Osten entlang der Straße getragen, teilt sie Hochexekutorin Darthalia mit, dass Hillsbrads menschliche Verteidigung verwundbar ist. Für Darthalia und den Schreckenslord Varimathras bedeutet das Signal, dass die Zeit gekommen ist, die Streitkräfte der Verlassenen zu sammeln und ihre Feldzüge gegen Hillsbrads menschliche Verteidiger zu beginnen."}},faq={{q="Was bedeutet die Nachricht von Todespirscherin Lesch?",a="„Der Schrei des Raben aus dem Westen ruft“ ist ein verschlüsselter Bericht aus Leschs Aufklärung. Er teilt Hochexekutorin Darthalia mit, dass Hillsbrads westliche Zugänge schlecht bewacht sind und einem sofortigen Angriff offenstehen.",al={"bedeutung des rabenschreis","was bedeutet der rabenschrei","leschs nachricht"}},{q="Wer ist Hochexekutorin Darthalia?",a="Hochexekutorin Darthalia befehligt die Streitkräfte der Verlassenen im Vorgebirge des Hügellands. Von Tarrens Mühle aus leitet sie Angriffe gegen die Menschen von Süderstade und arbeitet eng mit Varimathras in Unterstadt zusammen.",al={"wer ist darthalia","darthalias rolle"}},{q="Warum schickt Lesch einen Kurier, statt selbst zu gehen?",a="Lesch beobachtet Hillsbrads westlichen Rand. Verlässt sie ihren Posten, entsteht dort eine Lücke in der Überwachung durch die Verlassenen, also bittet sie vorbeiziehende Reisende der Horde, ihre dringenden Depeschen zu überbringen.",al={"warum bleibt lesch","warum kuriere"}},{q="Wohin soll diese Nachricht gebracht werden?",a="Die Nachricht ist für Tarrens Mühle bestimmt, die wichtigste Festung der Horde in der Region. Bringt sie auf der Hauptstraße durch das Vorgebirge des Hügellands nach Osten.",al={"wohin gehen","ziel der nachricht"}},{q="Warum ist Varimathras in Hillsbrads Angelegenheiten verwickelt?",a="Varimathras ist Sylvanas Windläufers oberster Stellvertreter und ihr Schreckenslord-Berater. Vom Königsviertel in Unterstadt aus beaufsichtigt er große Teile der militärischen und strategischen Planung der Verlassenen, während Hochexekutorin Darthalia seine Feldzugsbefehle in der Region ausführt.",al={"varimathras hillsbrad","warum varimathras"}},{q="Was geschieht, nachdem diese Nachricht eingetroffen ist?",a="Als Darthalia erfährt, dass Hillsbrad verwundbar ist, genehmigt sie heftige Angriffe. Champions der Horde werden ausgesandt, um die Bauernhöfe, Milizen und Infrastruktur von Hillsbrad zu zerschlagen.",al={"was geschieht als nächstes","nach zeit zum zuschlagen"}}},fx={ce3697ce={q="Warum möchte Todespirscherin Lesch, dass diese Nachricht überbracht wird?",a="Todespirscherin Lesch ist nahe der Grenze auf einer verdeckten Aufklärungsmission stationiert, um die menschliche Siedlung Hillsbrad zu überwachen. Nachdem sie beobachtet hat, dass die Stadt verwundbar ist, muss ihre verschlüsselte Einschätzung umgehend zu Hochexekutorin Darthalia nach Tarrens Mühle gebracht werden, damit die Führung der Verlassenen ihre koordinierte Offensive einleiten kann.",al={"warum nachricht senden","bewegungsgrund todespirscherin lesch","bewegungsgrund zeit zum zuschlagen"}}},fp="14,156,23.386.0,14.351.1,43.214.0,31.197.0,54.186.0,44.145.0,51.247.0,44.170.0"}
P.entries["quest:496"] = {n="Elixier des Leidens",s="In Tarrens Mühle bereitet Apotheker Lydon ein Gebräu zu, das die Lebenden töten soll. Er benötigt tierische Reagenzien aus dem umliegenden Vorgebirge.",h="In Tarrens Mühle bereitet Apotheker Lydon ein Gebräu zu, das die Lebenden töten soll.",kw={"apotheker lydon","krabblersekret","elixier des leidens","graubärenzunge","vorgebirge des hügellands","königliche apothekervereinigung","tarrens mühle"},ang={["faction:Horde"]="Als Verbündete der Horde schreckt Ihr womöglich vor den skrupellosen biologischen Experimenten der Verlassenen zurück. Tarrens Mühles Grenzstellung gegenüber Süderstade hängt von ihrer alchemistischen Kriegsführung ab.",["race:Undead"]="Als Agenten der Verlassenen könnt Ihr die Königliche Apothekervereinigung ihrem Ziel näherbringen, eine verheerende Waffe für das Überleben Eures Volkes gegen die lebende Menschheit zu schaffen."},sec={{t="Ein giftiges Unterfangen",b="Tarrens Mühle ist eine Festung der Verlassenen im Vorgebirge des Hügellands und eine Forschungsstation der Königlichen Apothekervereinigung. Apotheker Lydon arbeitet dort, umgeben von einer grünen Landschaft, die er verabscheut. Er sehnt sich danach, menschliche Siedlungen vergiftet und erobert zu sehen. Für sein experimentelles Elixier des Leidens benötigt er starke, virulente Zutaten von Kreaturen aus der Umgebung."},{t="Reagenzien sammeln",b="Apotheker Lydon schickt Jäger in die Wildnis um Tarrens Mühle, um Graubärenzungen und den seltenen Ichor von Mooskriechern zu beschaffen. Unheilige Alchemie veredelt diese tierischen Substanzen zur Grundlage einer tödlichen Mischung. Sie soll lebende Eindringlinge in ganz Hillsbrad töten."}},faq={{q="Wer ist Apotheker Lydon?",a="Apotheker Lydon gehört der Königlichen Apothekervereinigung an und ist in Tarrens Mühle stationiert. Er verabscheut Hillsbrads lebendige Landschaft und arbeitet an starken Giften gegen die menschliche Bevölkerung.",al={"apotheker lydon","wer vergibt elixier des leidens","lydon tarrens mühle"}},{q="Warum benötigt Lydon Bärenzungen und Krabblersekret?",a="Apotheker Lydon benötigt Graubärenzungen und den Ichor von Mooskriechern für seine tödlichen Gebräue. Ihre biologischen Eigenschaften liefern die alchemistische Grundlage für sein Elixier des Leidens.",al={"warum bärenzungen","wofür ist krabblersekret","hintergrund der elixierzutaten"}},{q="Wohin führt diese Quest als Nächstes?",a="Sobald Apotheker Lydon die Zutaten erhält, mischt er daraus ein erstes Versuchsgebräu. Dann verlangt er, dessen tödliche Wirkung an lebenden Versuchsobjekten zu testen.",al={"nächste quest elixier des leidens","was geschieht nach elixier des leidens"}},{q="Welches Ziel verfolgt die Königliche Apothekervereinigung in Hillsbrad?",a="Unter dem Befehl von Fürstin Sylvanas Windläufer sucht die Königliche Apothekervereinigung nach einer alchemistischen Seuche, die Menschheit und Geißel gleichermaßen auslöschen soll. Tarrens Mühle ist ein Grenzposten, wo sie biologisches Material sammeln und Prototypen gegen örtliche Streitkräfte der Allianz testen.",al={"warum sind apotheker in hillsbrad","giftziele der verlassenen","hillsbrad seuche"}},{q="Wo sind die benötigten Kreaturen zu finden?",a="Graubären durchstreifen die zentralen Felder und Wälder des Vorgebirges des Hügellands. Mooskriecher lauern im Gestrüpp und in bewaldeten Gebieten unmittelbar vor Tarrens Mühle.",al={"wo sind graubären","wo sind mooskriecher","fundorte von bären und spinnen"}},{q="Warum ist Lydon so schlecht gelaunt?",a="Apotheker Lydon ekelt sich vor Lebenskraft, sauberer Luft und gedeihender Natur. Freude findet er an Tod, Verfall und dem Destillieren tödlicher Gifte.",al={"warum ist lydon unzufrieden","lydon saubere luft"}}},fx={["7bd4a2da"]={q="Warum will Apotheker Lydon, dass dies erledigt wird?",a="Apotheker Lydon verabscheut die unberührte, lebendige Landschaft des Vorgebirges des Hügellands und sehnt sich danach, die lokalen Menschen ausgelöscht zu sehen. Er betreibt intensive Forschung, um tödliche chemische Wirkstoffe für die Gesellschaft der Königlichen Apotheker zu entwickeln, und strebt danach, ein Gebräu zu erschaffen, das stark genug ist, um weitverbreiteten Tod in der gesamten Region zu säen.",al={"warum will lydon das erledigt haben","lydon motiv","warum elixier des leidens herstellen"}},f22d779c={q="Warum braucht Apotheker Lydon Euch, um die Zutaten zu sammeln?",a="Lydon ist von der akribischen theoretischen Arbeit des Mischens und Verfeinerns neuer Tötungsmittel in seinem Labor in Tarrens Mühle in Anspruch genommen. Da seine Forschung ständige Aufsicht erfordert, fehlt ihm die Zeit, persönlich die umliegende Wildnis zu durchstreifen, Bären zu jagen und schwer fassbare Kriecher aufzuspüren.",al={"warum kann lydon sie nicht sammeln","warum braucht lydon mich","warum abenteurer anheuern"}}},fp="19,131,18.356.0,18.262.0,24.190.0,51.170.0,32.161.1,62.262.0,43.145.0,32.132.0"}
P.entries["quest:4966"] = {n="Kanati Grauwolke schützen",s="Am Weißgipfelposten in Tausend Nadeln steht Ihr Kanati Grauwolke bei, während Galak-Attentäter näher rücken. Ihre Befehle fordern den Tod des Tauren.",h="Am Weißgipfelposten in Tausend Nadeln steht Ihr Kanati Grauwolke bei, während Galak-Attentäter näher rücken.",kw={"assassination plot","attentäter","zentauren","galak","kanati grauwolke","tausend nadeln","weißgipfelposten"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass der Weißgipfelposten einen wichtigen Aussichtspunkt in Tausend Nadeln bietet. Wachen wie Kanati am Leben zu halten, hilft, die Unternehmungen der Horde im gesamten Canyon abzusichern.",["race:Tauren"]="Als Taure wisst Ihr, dass die Fehde mit den Zentauren tief verwurzelt ist. Einen Stammesgenossen vor einem Attentat zu schützen, ist eine Frage des Überlebens und der Ehre."},sec={{t="Ein aufgedeckter Hinterhalt",b="Am Weißgipfelposten findet Kanati Grauwolke Befehle der Zentauren, die ihn als Ziel nennen. Die Galakzentauren bekämpfen seit Langem die nomadischen Tauren und ihre Verbündeten der Horde. Überfälle auf Nachschubwege genügen ihnen nicht. Sie wollen auch jene töten, die sich in ihren Canyons niederlassen."},{t="Verteidigung des Weißgipfelpostens",b="Kanati vermutet, dass die Galak bald zuschlagen werden, und ihre Zahl könnte größer sein, als er zunächst dachte. Deshalb bittet er Reisende am Posten, ihm beizustehen. Als die Attentäter angreifen, hält Kanati an der Seite seiner Verbündeten stand. Ihre Klingen und Zauber können den Hinterhalt vereiteln, bevor die Zentauren ihn töten."}},faq={{q="Wer ist Kanati Grauwolke?",a="Kanati Grauwolke ist ein Taure mit einem Jagdlager am Weißgipfelposten in Tausend Nadeln. Das Lager liegt nahe den Canyons, die örtliche Zentaurenklans für sich beanspruchen.",al={"wer ist kanati","kanati grauwolke hintergrund","wer ist der questgeber"}},{q="Warum wollen die Zentauren ihn ermorden?",a="Die Galakzentauren sehen die Tauren und ihre Lager der Horde als Feinde, die in ihr Canyongebiet vordringen. Sie wollen Kanati töten und sein Jagdlager sowie alle vertreiben, die ihm folgen könnten.",al={"warum greifen zentauren kanati an","grund für das attentat der zentauren","assassination plot warum"}},{q="Wo findet diese Verteidigung statt?",a="Der Hinterhalt findet am Weißgipfelposten statt, einem kleinen Außenposten der Horde an den Canyonpfaden von Tausend Nadeln.",al={"wo ist diese quest","kanati schützen ort","wo findet der hinterhalt statt"}},{q="Welcher Zentaurenklan greift Kanati Grauwolke an?",a="Die Attentäter gehören zum Stamm der Galak, einem Zentaurenklan, der die Canyons und Schluchten von Tausend Nadeln bewohnt.",al={"welcher stamm greift an","wer sind die attentäter","welche zentauren"}},{q="Was geschieht, nachdem die Attentäter besiegt sind?",a="Nachdem die Galak-Attentäter getötet wurden, ist Kanati am Leben und der Weißgipfelposten bleibt sicher. Er dankt jenen, die ihm während des Überraschungsangriffs beigestanden haben.",al={"was geschieht als nächstes","folgequest","nach kanatis verteidigung"}},{q="Kämpft Kanati Grauwolke in der Schlacht mit?",a="Ja. Kanati kämpft an der Seite jener, die seinem Hilferuf folgen, und hilft, die Attentäter zurückzuschlagen, die gekommen sind, um ihn zu töten.",al={"hilft kanati","kanati im kampf","ist kanati passiv"}}},fx={e12a4220={q="Warum braucht Kanati Grauwolke Eure Hilfe bei der Verteidigung des Postens?",a="Obwohl Kanati ein fähiger Tauren-Krieger ist, der an Eurer Seite kämpft, erkennt er, dass die Zentauren mehr Attentäter entsandt haben, als er allein bewältigen kann. Der Weißgipfelposten ist isoliert und hat kaum unmittelbare Verstärkung, was Eure Anwesenheit zum entscheidenden Faktor macht, um den Hinterhalt abzuwehren, anstatt überwältigt zu werden.",al={"warum braucht kanati hilfe","warum ich kanati schützen","kann kanati alleine kämpfen"}},["792f0095"]={q="Wer sind die Zentauren, die Kanati Grauwolke angreifen?",a="Die Angreifer sind Assassinen des Galak-Zentaurenstamms, die ausgesandt wurden, um tief in den Weißgipfelposten vorzudringen. Erzürnt darüber, dass Kanati Grauwolke es gewagt hat, ein Jagdlager in ihren Schluchten zu errichten, schickten sie ein eigens dafür abgestelltes Angriffsteam, um den Taurenjäger in seinem eigenen Lager zu töten und jeden zu vertreiben, der ihm folgen könnte.",al={"wer sind die assassinen","kanati vor assassinen schützen","welche zentauren greifen an"}}},fp="24,134,18.262.0,25.295.0,24.147.0,46.198.0,35.108.0,44.114.0,46.149.1,42.102.0"}
P.entries["quest:498"] = {n="Die Rettung",s="In Tarrens Mühle braucht Krusk Eure Hilfe, nachdem Banditen des Syndikats die zur Burg Durnholde entsandten Orc-Späher gefangen genommen haben. Thrall schickte sie los, um der wachsenden Bedrohung nachzugehen und einen Gegenstand aus der Burg zu holen.",h="In Tarrens Mühle braucht Krusk Eure Hilfe, nachdem Banditen des Syndikats die zur Burg Durnholde entsandten...",kw={"drull","burg durnholde","gol'dir","hillsbrad","krusk","syndikat","tarrens mühle","tog'thar"},ang={["class:Warrior"]="Als Krieger steht Ihr Euren Mitstreitern bei und befreit sie aus der Gefangenschaft ehrloser menschlicher Banditen.",["faction:Horde"]="Als Mitglied der Horde beteiligt Ihr Euch an einem frühen Versuch, der Ausbreitung des Syndikats in den umkämpften Hügeln Lordaerons entgegenzuwirken.",["race:Orc"]="Als Orc erinnert Euch der Anblick Eurer gefesselten Krieger in Durnholde an die schmerzliche Geschichte der Internierung. Ihre Befreiung ist eine persönliche Angelegenheit."},sec={{t="Eine gescheiterte Spähmission",b="Kriegshäuptling Thrall schickte Orc-Krieger ins Vorgebirge des Hügellands, um der wachsenden Bedrohung durch das Syndikat nachzugehen und einen Gegenstand aus Burg Durnholde zu holen. Gol'dir führte sie zu den Festungsruinen, doch das Syndikat überwältigte die Späher in einem Hinterhalt. Krusk konnte sich befreien und humpelte über den Fluss zurück nach Tarrens Mühle. Die menschlichen Banditen nahmen Drull, Tog'thar und Gol'dir gefangen."},{t="Ketten in den Ruinen",b="Durnholde birgt bittere Erinnerungen für die Orcs. Aedelas Schwarzmoor hielt dort einst Orcs in Internierungslagern gefangen, wo sie in Lethargie versetzt und in die Gladiatorensklaverei gezwungen wurden. Nun liegen Drull und Tog'thar innerhalb der rissigen Steinmauern der Burg in Eisen. Befreit sie von den Kerkermeistern des Syndikats, die die Schlüssel zu ihren Fesseln besitzen, und findet dann heraus, was aus ihrem Kommandanten Gol'dir geworden ist."}},faq={{q="Warum wurden überhaupt Orcs in die Burg Durnholde geschickt?",a="Thrall schickte Gol'dir und seine Späher los, um die Banditen des Syndikats zu untersuchen und einen Gegenstand aus Burg Durnholde zu holen.",al={"warum waren sie dort","warum durnholde","krusks mission"}},{q="Wer sind die Gefangenen, die gerettet werden sollen?",a="Drull und Tog'thar sind Orc-Späher, die von der Horde unter Gol'dirs Kommando entsandt wurden. Banditen des Syndikats überwältigten sie und legten ihnen innerhalb der Ruinen Ketten mit Eisenkugeln an.",al={"wer ist drull","wer ist togthar","wer sind die geiseln"}},{q="Wo ist Gol'dir, der Anführer des Trupps?",a="Nachdem Drull und Tog'thar befreit wurden, erfährt Krusk, dass das Syndikat Gol'dir von der Hauptgruppe getrennt und an einen anderen, unbekannten Ort gebracht hat.",al={"wo ist goldir","goldir finden","was ist mit goldir geschehen"}},{q="Wer hält die Späher gefangen?",a="Das Syndikat hält die Späher gefangen. Dieses aristokratische Verbrechernetzwerk operiert von den Ruinen von Lordaeron und Alterac aus, und seine Kerkermeister bewachen die Gefangenen in Durnholde.",al={"wer hat sie gefangen genommen","wer sind die kerkermeister","wer herrscht über durnholde"}},{q="Wohin führt diese Questreihe?",a="Die Befreiung der Späher führt zur Suche nach Gol'dir und zum Versuch, das Syndikat aufzuspüren und zu unterwandern. Die Spur führt tiefer in die Machenschaften des Syndikats.",al={"what comes next","nach der rettung","rettungsquestreihe"}},{q="Warum hat Burg Durnholde eine besondere Bedeutung für die Horde?",a="In Durnholde zog Aedelas Schwarzmoor Thrall als Gladiator auf und befehligte nach dem Zweiten Krieg die Internierungslager der Allianz. Thrall führte einen Aufstand an und verwüstete die Burg.",al={"geschichte von durnholde","warum ist durnholde der horde wichtig"}}},fx={["95bc386b"]={q="Warum muss Krusk die Gefangenen retten?",a="Krusk war Teil genau jener Aufklärungseinheit, die in der Burg Durnholde in einen Hinterhalt geriet. Während es ihm gelang, sich freizukämpfen und zurück nach Tarrens Mühle zu fliehen, wurden seine Kameraden Drull und Tog'thar lebend gefangen genommen. Er fürchtet, dass das Syndikat plant, sie zu Sklaven zu machen – ein unerträgliches Schicksal in genau der Festung, in der einst Orks in Gefangenschaft gehalten wurden – und er kann seine Mitkrieger nicht der Gefangenschaft und Folter überlassen.",al={"warum drull und tog'thar retten","krusk motiv","warum krusk helfen"}}},fp="10,195,26.366.0,19.389.1,58.115.0,35.163.0,37.153.1,34.169.0,33.161.1,58.184.0"}
P.entries["quest:499"] = {n="Elixier des Leidens",s="In Tarrens Mühle testet Apotheker Lydon ein Gift für die Königliche Apothekervereinigung. Er will herausfinden, wie schnell es tötet, bevor es breiter eingesetzt wird.",h="In Tarrens Mühle testet Apotheker Lydon ein Gift für die Königliche Apothekervereinigung.",kw={"apotheker lydon","elixier des leidens","vorgebirge des hügellands","gift","königliche apothekervereinigung","tarrens mühle","kröte","umpi"},ang={["class:Druid"]="Als Druide könnte Euch die beiläufige Vergiftung einer harmlosen Amphibie für die Kriegsführung der Verlassenen zutiefst verstören.",["faction:Horde"]="Als Verbündeter der Horde erlebt Ihr bei Eurem Besuch in Tarrens Mühle die rücksichtslosen alchemistischen Methoden der Königlichen Apothekervereinigung aus erster Hand.",["race:Undead"]="Für die Verlassenen sind Tests tödlicher Gifte unerlässlich, um Fürstin Sylvanas' Befehl zu erfüllen, sowohl die Geißel als auch die Lebenden auszurotten."},sec={{t="Ein giftiger Versuch",b="Apotheker Lydon arbeitet in Tarrens Mühle und stellt chemische Waffen für die ehrgeizigen Ziele der Dunklen Fürstin her. Seine Seuche soll die lebenden Menschen der Allianz und die untoten Schrecken der Geißel vernichten. Sobald er die nötigen Reagenzien hat, mischt Lydon daraus ein übles Gebräu namens Elixier des Leidens. Er will dessen Wirkung sehen, bevor die Vereinigung es breiter einsetzt."},{t="Umpis Schicksal",b="Apotheker Lydon wählt die Kreatur neben sich für einen Versuch aus. Er bittet Euch, Umpi sein frisches Gift zu geben, seinem harmlosen Krötenassistenten, der zu seinen Füßen sitzt. Eine Dosis tötet die Amphibie auf der Stelle. Das Ergebnis zeigt Lydon, dass seine Formel wie beabsichtigt wirkt."}},faq={{q="Wer ist Apotheker Lydon?",a="Apotheker Lydon ist ein Alchemist der Königlichen Apothekervereinigung, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Er verbringt seine Tage damit, Gifte und Mixturen zu verfeinern, die die Feinde der Verlassenen auslöschen sollen.",al={"lydon","wer ist lydon","apotheker lydon tarrens mühle"}},{q="Wer ist Umpi?",a="Umpi ist eine Kröte neben Apotheker Lydons Arbeitstisch in Tarrens Mühle. Lydon nennt die Kröte scherzhaft seinen Assistenten.",al={"was ist umpi","umpi die kröte","wer ist der assistent"}},{q="Welchen Zweck hat das Elixier des Leidens?",a="Das Elixier des Leidens ist eine experimentelle chemische Waffe zur Erprobung von Giftstoffen, die für Fürstin Sylvanas Windläufer lebende Menschen und die untote Geißel ausrotten sollen.",al={"was bewirkt das elixier","warum elixier des leidens herstellen"}},{q="Was geschieht, wenn Ihr Umpi den Trank verabreicht?",a="Lydon bittet Euch, Umpi von dem frisch gemischten Elixier kosten zu lassen. Der Versuch zeigt, ob es die beabsichtigte Wirkung hat.",al={"stirbt umpi","was geschieht mit der kröte"}},{q="Wo findet dieser Versuch statt?",a="Der Versuch findet an Lydons Braustation in Tarrens Mühle statt, einer Stadt der Verlassenen im nördlichen Vorgebirge des Hügellands.",al={"wo befindet sich lydon","wo ist umpi zu finden"}},{q="Warum testet die Königliche Apothekervereinigung Gifte an kleinen Tieren?",a="Apotheker der Verlassenen testen chemische Verbindungen an kleinen Kreaturen und Ungeziefer, um ihre Wirkungsgeschwindigkeit und Tödlichkeit zu ermitteln, bevor sie größere Ziele oder lebende Gefangene heranziehen.",al={"warum an kröten testen","apothekervereinigung tierversuche"}}},fx={ac622650={q="Warum will Apotheker Lydon das Elixier des Leidens testen?",a="Apotheker Lydon versucht zu überprüfen, ob sein frisch gebrautes Gebräu seine beabsichtigte tödliche Wirkung erzielt. Die Gesellschaft der Königlichen Apotheker arbeitet unermüdlich unter Lady Sylvanas daran, Seuchen zu entwickeln, die sowohl die Geißel als auch die lebende Menschheit vernichten können, und Feldversuche wie dieser bestätigen, ob ihre dunklen Formeln wie geplant voranschreiten.",al={"warum elixier des leidens testen","apotheker lydon motiv","warum will lydon das erledigt haben"}}},fp="19,151,12.352.0,16.257.1,24.211.0,12.112.0,47.163.0,46.117.1,32.116.0,68.175.0"}
P.entries["quest:5"] = {n="Bibbers' knurrender Magen",s="In Rabenflucht hungert Bibbers voller Angst und hat nur Unkraut und Insekten zu essen. Er bittet Euch, nach Osten nach Dunkelhain zu reisen, um Küchenchef Gruals berühmte Schwärzliche Krebsküchlein zu besorgen.",h="In Rabenflucht hungert Bibbers voller Angst und hat nur Unkraut und Insekten zu essen.",kw={"küchenchef grual","krebsküchlein","dunkelhain","knurrender magen","bibbers","rabenflucht","scarlet raven tavern"},ang={["faction:Alliance"]="Wenn Ihr Bibbers helft, lernt Ihr die gefährdeten Siedlungen und die Überlebenden näher kennen, die in den schattigen Winkeln des Dämmerwalds ausharren.",["profession:Cooking"]="Küchenchef Gruals Schwärzliche Krebsküchlein zeigen, wie Köche im Dämmerwald ungewöhnliche Zutaten aus der Umgebung verwenden, wenn die üblichen Lieferungen ausbleiben."},sec={{t="Hunger in Rabenflucht",b="In den verfallenen Straßen von Rabenflucht hausen unersättliche Untote und lauernde Bestien. Bibbers hält sich dort seit Wochen versteckt und zieht durch baufällige Hütten unter einem Himmel, der sich nie aufzuhellen scheint. Er hat nur Maden im Schmutz und wildes Unkraut zu essen gefunden. Hunger und Angst zehren an ihm, fern von den Annehmlichkeiten des Alltags."},{t="Eine Bitte um Krebsküchlein",b="Bibbers sehnt sich nach einem Hauch von Sicherheit: den gewürzten Bratlingen aus der Scarlet Raven Tavern in Dunkelhain. Er bittet Euch, die heimgesuchte Straße zu überqueren und mit Küchenchef Grual zu sprechen. Wenn der Küchenchef zustimmt, Schwärzliche Krebsküchlein zuzubereiten, könnte eine warme Mahlzeit Bibbers' knurrenden Magen beruhigen."}},faq={{q="Wer ist Bibbers?",a="Bibbers ist ein verängstigter, paranoider Mann, der sich in der verfallenen Ortschaft Rabenflucht im westlichen Dämmerwald versteckt. Die Untoten dort versetzen ihn in Schrecken, und er fürchtet, zu verhungern oder abgeschlachtet zu werden.",al={"bibbers","wer ist bibbers","wo ist bibbers"}},{q="Wo kann ich Küchenchef Grual finden?",a="Küchenchef Grual arbeitet in der Küche der Scarlet Raven Tavern in Dunkelhain, im Osten des Dämmerwalds.",al={"küchenchef grual fundort","grual finden","scarlet raven küchenchef"}},{q="Warum isst Bibbers Maden?",a="Bibbers sitzt seit Wochen im verfallenen Rabenflucht fest, durch umherstreifende Untote und räuberische Worgen von der Zivilisation abgeschnitten. Ohne Vorräte sucht er nach Insekten und Blattwerk, um zu überleben.",al={"bibbers isst insekten","warum isst er maden","rabenflucht nahrung"}},{q="Welches Gericht möchte Bibbers?",a="Bibbers möchte Schwärzliche Krebsküchlein, eine örtliche Spezialität, die Küchenchef Grual in der Scarlet Raven Tavern zubereitet.",al={"bibbers nahrung","krebsküchlein quest","was möchte bibbers essen"}},{q="Was geschieht nach dem Gespräch mit Küchenchef Grual?",a="Küchenchef Grual erklärt sich bereit, für Bibbers zu kochen, doch ihm fehlen frische Zutaten. Er bittet Euch, klebrige Spinnenbeine für die Schwärzlichen Krebsküchlein zu sammeln.",al={"nach bibbers' knurrendem magen","folgequest bibbers' knurrender magen","küchenchef grual aufgabe"}},{q="Können Spieler der Horde diese Quest abschließen?",a="Nein. Bibbers und Dunkelhain stehen auf der Seite der Allianz, daher können ihm nur Abenteurer der Allianz helfen.",al={"bibbers nur für die allianz","horde bibbers' knurrender magen"}}},fx={["6935fdd7"]={q="Warum kann Bibbers sich nicht selbst Essen aus Dunkelhain holen?",a="Bibbers ist zu Tode verängstigt und hat Wochen damit verbracht, in den verlassenen Ruinen von Raven Hill zu kauern. Umgeben von umherstreifenden Untoten, wilden Tieren und den Schrecken, die den Dämmerwald heimsuchen, ist er zu versteinert, um sich allein auf die Straßen nach Dunkelhain zu wagen. Er ist auf durchreisende Abenteurer wie Euch angewiesen, die die Stärke und den Mut haben, den gefährlichen Weg durch die Finsternis zu wagen.",al={"warum braucht bibbers mich","warum kann bibbers nicht nach dunkelhain","bibbers warum ich"}}},fp="21,166,22.312.0,21.260.0,15.171.0,28.103.0,28.184.0,28.98.0,44.137.1,38.99.0"}
P.entries["quest:500"] = {n="Crushridge-Kopfgeld",s="Von Süderstade aus warnt Marshal Redpath, dass sich Crushridge-Oger nahe den Ruinen von Alterac niedergelassen haben. Er bietet jedem ein Kopfgeld, der sie im Alteracgebirge jagt.",h="Von Süderstade aus warnt Marshal Redpath, dass sich Crushridge-Oger nahe den Ruinen von Alterac...",kw={"alterac","kopfgeld","crushridge","knöchelknochen","oger","redpath","süderstade"},sec={{t="Oger vor der Tür",b="Marshal Redpath schickt Euch nach Norden, nachdem Berichte eingetroffen sind, dass Crushridge-Oger im Alteracgebirge nahe der zerstörten Stadt Alterac einen Hügel aufgeworfen haben. Sie haben auch die Ruinen eingenommen. Redpath fürchtet, dass sie es sich dort gemütlich machen, dann ins Vorgebirge hinabziehen und bis vor Süderstades Tür gelangen könnten. Er bietet ein Kopfgeld dafür, sie zu jagen und die Schmutzigen Knöchelknochen zurückzubringen, die sie bei sich tragen."}},faq={{q="Warum will Marshal Redpath die Crushridge-Oger jagen lassen?",a="Redpath fürchtet, dass die Crushridge-Oger es sich in ihrem Hügel und den Ruinen von Alterac gemütlich machen, dann ins Vorgebirge Richtung Süderstades Tür hinabziehen könnten.",al={"warum crushridge-oger töten","redpaths beweggrund","grund für ogerkopfgeld"}},{q="Wo sind die Crushridge-Oger?",a="Die Crushridge-Oger sind im Norden im Alteracgebirge. Sie haben nahe der zerstörten Stadt Alterac einen Hügel aufgeworfen, und Redpaths Späher berichten, dass sie auch die Ruinen besetzt halten.",al={"oger standort","crushridge-oger wo","wo knöchelknochen finden"}},{q="Was soll Marshal Redpath zurückgebracht werden?",a="Marshal Redpath will, dass ihm neun Schmutzige Knöchelknochen, die die Crushridge-Oger bei sich tragen, nach Süderstade zurückgebracht werden.",al={"was redpath bringen","oger nachweis","schmutzige knöchelknochen"}}},fp="17,165,17.367.0,58.151.0,31.161.0,44.112.0"}
P.entries["quest:501"] = {n="Elixier der Schmerzen",s="In Tarrens Mühle sucht Apotheker Lydon Berglöwenblut für ein tödliches Gebräu. Seine Arbeit dient dem Bestreben der Königlichen Apothekervereinigung, die New Plague zu perfektionieren.",h="In Tarrens Mühle sucht Apotheker Lydon Berglöwenblut für ein tödliches Gebräu.",kw={"apotheker lydon","elixier der schmerzen","vorgebirge des hügellands","berglöwenblut","new plague","königliche apothekervereinigung","tarrens mühle"},ang={["faction:Horde"]="Als Verbündeter der Horde erlebt Ihr die finsteren Methoden der Alchemisten von Tarrens Mühle. Ihr helft, das Blut wilder Tiere zu sammeln, um die Stützpunkte der Horde gegen menschliche Bedrohungen in der Nähe zu stärken.",["race:Undead"]="Als Reisender der Verlassenen sammelt Ihr Reagenzien für Apotheker Lydon im Dienst der Dark Lady und der Königlichen Apothekervereinigung, die ihren Platz in Lordaeron beanspruchen."},sec={{t="Bitterer Ausblick in Tarrens Mühle",b="Apotheker Lydon findet in Tarrens Mühle wenig Trost. Hillsbrads blühende Wiesen und die frische Bergluft sind ihm ein Ärgernis. Wie viele in der Königlichen Apothekervereinigung verschreibt er sich Fürstin Sylvanas Windläufer und der New Plague. Die Vereinigung arbeitet daran, diese künstlich erschaffene Seuche zu perfektionieren, die die Lebenden töten und ihren Feinden Vergeltung bringen soll."},{t="Zutaten für das Elend",b="Apotheker Lydon sucht Zutaten für eine giftige Mischung unter den Tieren, die das Vorgebirge und die Hänge zum Alteracgebirge durchstreifen. Er glaubt, dass Berglöwenblut enthält, was er für ein Elixier der Schmerzen braucht. Also schickt er Beauftragte in die Wildnis, um zehn Phiolen zu beschaffen. Das Blut soll die fortlaufenden chemischen Versuche der Vereinigung entlang der umkämpften Südfront unterstützen."}},faq={{q="Wer vergibt die Quest Elixier der Schmerzen?",a="Apotheker Lydon, ein Alchemist der Verlassenen in Tarrens Mühle, vergibt den Auftrag. Tarrens Mühle liegt im Vorgebirge des Hügellands.",al={"questgeber elixier der schmerzen","wer startet elixier der schmerzen","apotheker lydon quest"}},{q="Warum braucht Apotheker Lydon Berglöwenblut?",a="Lydon glaubt, dass Berglöwenblut benötigt wird, um eine tödliche Mischung zu brauen. Er hofft, dass das Elixier die chemischen Seuchenexperimente der Königlichen Apothekervereinigung gegen ihre lebenden Feinde voranbringt.",al={"warum berglöwenblut","löwenblut zweck","wofür ist das blut"}},{q="Wo sind die Berglöwen zu finden?",a="Berglöwen durchstreifen die offenen Felder und sanften Hügel des Vorgebirges des Hügellands sowie die höher gelegenen Anhöhen in Richtung Alteracgebirge.",al={"wo sind berglöwen","berg löwen fundorte hillsbrad","löwenblut farmen"}},{q="Was ist die New Plague, die Lydon erwähnt?",a="Die New Plague ist eine biologische Waffe, die die Königliche Apothekervereinigung der Verlassenen auf Befehl von Fürstin Sylvanas Windläufer entwickelt. Sie soll sowohl die Geißel als auch die Lebenden ausrotten.",al={"was ist die new plague","königliche apothekervereinigung seuche","verlassene seuche"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Nachdem Ihr zehn Phiolen Berglöwenblut übergeben habt, beginnt Apotheker Lydon, sein frisch gebrautes Elixier zu testen.",al={"elixier der schmerzen nächste quest","folgequest elixier der schmerzen","was folgt auf elixier der schmerzen"}},{q="Warum verachtet Lydon Hillsbrads Landschaft?",a="Als untoter Diener der Dark Lady verabscheut Lydon Hillsbrads blühende Pflanzen, die frische Luft und das fortwährende Leben. Er will, dass die giftigen Schöpfungen der Vereinigung die lebende Welt ersticken.",al={"warum hasst lydon hillsbrad","warum grübelt lydon","lydon fenster zitat"}}},fp="14,159,31.343.0,22.364.0,35.121.0,51.194.0,38.144.0,38.189.0,44.110.0,43.183.0"}
P.entries["quest:502"] = {n="Elixier der Schmerzen",s="In Tarrens Mühle ist das Elixier der Schmerzen für einen Versuch an Farmer Rays Hund Stanley bereit. Apotheker Lydon bereitet den Trank für die Royal Apothecary Society vor.",h="In Tarrens Mühle ist das Elixier der Schmerzen für einen Versuch an Farmer Rays Hund Stanley bereit.",kw={"apotheker lydon","elixier der schmerzen","farmer ray","die felder von hillsbrad","royal apothecary society","stanley","tarrens mühle"},ang={["class:Hunter"]="Als Jäger seht Ihr, wie wenig sich die Alchemisten der Verlassenen um Tiere scheren, die in ihre Versuche geraten. Sie verfüttern ein experimentelles Gebräu an den zutraulichen Hund eines Bauern.",["faction:Horde"]="Als Verbündeter der Horde werdet Ihr in die düsteren chemischen Versuche der Verlassenen gegen die benachbarten menschlichen Bauernhöfe von Hillsbrad hineingezogen.",["race:Undead"]="Als Untoter erlebt Ihr das rücksichtslose Vorgehen der Royal Apothecary Society. Sie strebt nach biologischen Waffen für das Überleben der Verlassenen, ungeachtet aller Kollateralschäden."},sec={{t="Die Wissenschaft der Apotheker",b="Apotheker Lydon dient von Tarrens Mühle aus der Royal Apothecary Society und Fürstin Sylvanas Windläufer. Er sammelt frisches Blut von einheimischen Wildtieren und braut daraus das instabile Elixier der Schmerzen. Die Gesellschaft sucht im Feld nach Belegen dafür, wie ihre experimentellen Gifte und Mutagene auf lebende Körper wirken."},{t="Versuch an Stanley",b="Lydon schickt seine Agenten zum nördlichen Hof auf den Feldern von Hillsbrad, jenseits der menschlichen Verteidiger. Farmer Ray hält dort seinen Hund Stanley. Ein Agent gießt den Trank in eine offene Hand und bietet ihn als gewöhnlichen Leckerbissen an. Stanley weiß nicht, was ihm da gegeben wird."},{t="Gewaltsame Mutation",b="Das Elixier der Schmerzen bereitet Stanley sofort Qualen und löst eine gewaltsame Verwandlung aus. Das Mutagen verformt ihn zu einem wilden, rasenden Wolf, statt ihn mit einem einfachen Gift zu töten. Die Bestie greift alles in ihrer Nähe an und zeigt damit die Kraft von Lydons Formel."}},faq={{q="Welchen Zweck hat das Elixier der Schmerzen?",a="Apotheker Lydon braute das Elixier der Schmerzen für die Bemühungen der Royal Apothecary Society, biologische Waffen und mächtige Mutagene für Fürstin Sylvanas und die Verlassenen zu erschaffen.",al={"elixier der schmerzen ziel","warum elixier der schmerzen herstellen","lydon elixier zweck"}},{q="Wer ist Stanley?",a="Stanley ist Farmer Rays Haushund. Er lebt vor dem großen Bauernhaus am nördlichen Ende der Felder von Hillsbrad.",al={"wer ist stanley","farmer ray hund","stanley der hund"}},{q="Was geschieht, wenn Ihr Stanley das Elixier füttert?",a="Lydon will sehen, wie Stanley sein „Leckerbissen“ schmeckt. Die Wirkung des Elixiers zeigt sich, nachdem Stanley es gefressen hat.",al={"stanley verwandlung","was macht das elixier mit dem hund","stanley wolf"}},{q="Wo befindet sich Stanley?",a="Stanley streift vor dem großen Haus auf dem nördlichen Hof auf den Feldern von Hillsbrad umher, südwestlich von Tarrens Mühle.",al={"stanley finden","stanley aufenthaltsort","wo ist farmer rays hund"}},{q="Wer vergibt die Quest zur Erprobung des Elixiers?",a="Apotheker Lydon bittet Euch in Tarrens Mühle, der Siedlung der Verlassenen im Vorgebirge des Hügellands, das Elixier zu testen. Das tut er, nachdem Ihr die benötigten Reagenzien gesammelt habt.",al={"elixier der schmerzen questgeber","wer vergibt elixier der schmerzen","apotheker lydon quest"}},{q="Warum wird der Trank an einem Bauernhund statt an Menschen getestet?",a="Ein Haustier auf den Feldern von Hillsbrad ermöglicht einen unauffälligen, leicht zugänglichen Versuch. Der Test kann stattfinden, ohne sofort die Stadtmiliz oder bewaffnete Wachen zu alarmieren.",al={"warum am hund testen","warum stanley","warum hund vergiften"}}},fx={["0d6659fd"]={q="Warum will Apotheker Lydon das Elixier der Schmerzen testen?",a="Apotheker Lydon glaubt, dass dieses Gebräu der Beginn von etwas Monumentalem für Lady Sylvanas und die Gesellschaft der Königlichen Apotheker sein könnte. Nachdem er frisches Berglöwenblut mit seinen eigenen abscheulichen Zusätzen gemischt hat, benötigt er praktische Feldtests, um zu beweisen, ob seine Berechnungen zutreffen, und um zu sehen, wie lebendes Fleisch auf das Gebräu reagiert.",al={"warum elixier der schmerzen testen","apotheker lydon motiv","warum will lydon das erledigt haben"}},fad857e3={q="Wen sollt Ihr mit dem Elixier als Ziel angreifen?",a="Euer Ziel ist Stanley, ein kleiner Haushund von Bauer Ray. Stanley lebt auf dem nördlichen Gehöft in den umkämpften Feldern von Hillsbrad südwestlich von Tarrens Mühle. Anstatt die menschlichen Bauern direkt anzugreifen, hat Lydon dieses ahnungslose Haustier als entbehrliches Subjekt ausgewählt, um die flüchtigen Wirkungen des Elixiers zu beobachten.",al={"wem gebe ich das elixier","elixier der schmerzen ziel","wer ist das ziel"}}},fp="14,159,18.293.0,18.259.0,16.244.1,42.171.0,15.112.0,46.112.1,25.107.0,39.161.0,56.152.0"}
P.entries["quest:503"] = {n="Gol'dir",s="In Tarrens Mühle hat Krusk herausgefunden, wo Gol'dir festgehalten wird. Die Dokumente weisen nach Norden zu einem großen Stützpunkt des Syndikats, vielleicht im Alteracgebirge, und Gol'dir ist schon zu lange gefangen.",h="In Tarrens Mühle hat Krusk herausgefunden, wo Gol'dir festgehalten wird.",kw={"alterac","borhuin","gol'dir","schlüssel","krusk","strahnbrad","syndikat","tarrens mühle"},sec={{t="Eine Spur nach Norden",b="In Tarrens Mühle studiert Krusk die Dokumente, die Ihr nach Infiltration zurückgebracht habt. Sie weisen auf einen großen Stützpunkt des Syndikats im Norden hin, vielleicht im Alteracgebirge. Gol'dir wird schon zu lange festgehalten, und Krusk will ihn befreit sehen."},{t="Das Gasthaus in Strahnbrad",b="Mitglieder des Syndikats bevölkern das Gasthaus in Strahnbrad, wo Gol'dir im obersten Raum festgehalten wird. Ein Verrosteter Eisenschlüssel öffnet das Schloss. Jailor Borhuin trägt ihn bei sich und könnte sich in jedem Gebäude der Stadt aufhalten."},{t="Was Gol'dir erzählt",b="Gol'dir erzählt, dass Kriegshäuptlingsbefehle ihn an der Spitze einer Expedition aus Durotar entsandten, doch die Pläne gingen schief. Das Syndikat hielt ihn in Strahnbrad fest, wo man ihn zwang, Lasten zu schleppen und zu graben.\n\nGol'dir tut seine Leiden ab. Wichtige Informationen müssen denjenigen erreichen, der die Gruppe jetzt anführt."}},faq={{q="Wer hält Gol'dir gefangen?",a="Das Syndikat hält Gol'dir in einem großen Stützpunkt im Norden gefangen.",al={"wer hat goldir gefangen genommen","wer hält goldir gefangen","goldirs kerkermeister"}},{q="Wo ist Gol'dir eingesperrt?",a="Gol'dir ist im obersten Raum des Gasthauses in Strahnbrad eingesperrt, dessen Räume voller Mitglieder des Syndikats sind.",al={"goldir aufenthaltsort","wo ist goldir","goldir finden"}},{q="Wie wird Gol'dirs Schloss geöffnet?",a="Ein Verrosteter Eisenschlüssel öffnet Gol'dirs Schloss. Jailor Borhuin trägt ihn bei sich und könnte sich in jedem Gebäude in Strahnbrad aufhalten.",al={"verrosteter eisenschlüssel","wie goldirs schloss öffnen","goldir schlüssel"}},{q="Was geschah vor diesem Schritt der Questreihe?",a="Vor diesem Schritt habt Ihr während Infiltration Dokumente beschafft, die darauf hinweisen, wo Gol'dir festgehalten wird.",al={"vorherige quest","welche quest kommt vor goldir","questreihe vor goldir"}}},fp="7,180,20.220.0,21.172.0,17.296.1,31.57.0,28.98.0,29.107.0,40.97.0"}
P.entries["quest:504"] = {n="Crushridge-Kriegstreiber",s="In den Ruinen von Alterac erwartet die Crushridge-Kriegstreiber eine härtere Jagd. Marshal Redpath aus Süderstade schickt Euch gegen sie aus, um die Oger vom Land der Allianz fernzuhalten.",h="In den Ruinen von Alterac erwartet die Crushridge-Kriegstreiber eine härtere Jagd.",kw={"alterac","crushridge","oger","redpath","ruinen","süderstade","kriegstreiber"},sec={{t="Eine härtere Lektion",b="Marshal Redpath schickt Euch nach Crushridge Bounty in die Ruinen von Alterac. Ihr sollt zahlreiche Crushridge-Kriegstreiber zur Strecke bringen und die Crushridge-Oger hart treffen. Redpath glaubt, dass nichts anderes die Rohlinge lehren wird, sich vom Gebiet der Allianz fernzuhalten."}},faq={{q="Wer schickt Euch gegen die Crushridge-Kriegstreiber aus?",a="Marshal Redpath in Süderstade schickt Euch gegen die Crushridge-Kriegstreiber aus.",al={"wer vergibt crushridge-kriegstreiber","questgeber crushridge-kriegstreiber","marshal redpath quest"}},{q="Wo sind die Crushridge-Kriegstreiber?",a="Sie sind in den Ruinen von Alterac, hoch in den Bergen.",al={"wo sind crushridge-kriegstreiber","kriegstreiber fundort","crushridge-kriegstreiber fundort"}},{q="Warum will Marshal Redpath die Kriegstreiber niederstrecken lassen?",a="Redpath glaubt, dass nichts anderes die Crushridge-Oger lehren wird, sich vom Land der Allianz fernzuhalten.",al={"warum kriegstreiber töten","zweck von crushridge-kriegstreiber","redpath grund oger"}},{q="Was kommt vor dieser Quest?",a="Sie folgt auf Crushridge Bounty, Redpaths ersten Aufruf zur Jagd auf die Crushridge-Oger.",al={"voraussetzung für crushridge-kriegstreiber","vorherige quest kriegstreiber","questreihe vor crushridge-kriegstreiber"}}},fp="21,157,15.256.0,46.72.0,36.56.0,54.95.0,29.80.0"}
P.entries["quest:5041"] = {n="Vorräte für das Wegekreuz",s="Thork braucht nach Überfällen der Grimmhauer-Stacheleber Vorräte zurück im Wegekreuz. Die gestohlenen Kisten enthalten Proviant, den der Außenposten braucht, während sich der Konflikt im Brachland ausbreitet.",h="Thork braucht nach Überfällen der Grimmhauer-Stacheleber Vorräte zurück im Wegekreuz.",kw={"brachland","karawane","kisten","das wegekreuz","stacheleber","grimmhauer","vorräte","thork"},ang={["faction:Horde"]="Für die Horde verbindet das Wegekreuz die Hauptstädte in Durotar und Mulgore. Die Rückholung geraubter Fracht hält den Grenzaußenposten versorgt.",["race:Orc"]="Als Orc helft Ihr, die wachsenden Siedlungen der neuen Horde zu bewachen, indem Ihr ihre Versorgungslinien vor Stachelebern schützt."},sec={{t="Eine Lebensader unter Belagerung",b="Thork braucht nach dem Überfall auf eine Versorgungskarawane Proviant zurück im Wegekreuz. Der Außenposten verbindet Reisewege, Handel und Verteidigung der Horde im gesamten Brachland. Seine Waren kommen aus Durotar und Mulgore. Ohne diese Güter drohen Engpässe bei Proviant, Werkzeugen und Waffen, die das tägliche Leben in der rauen Wildnis gefährden."},{t="Diebische Stacheleber",b="Grimmhauer-Stacheleber haben die Kisten an sich genommen. Diese schweineartigen Bestien machen der Horde die Vorherrschaft im zentralen Kalimdor streitig. Sie schleppten die Fracht in ihre Dornenbuschlager und bewahren sie dort auf. Thork schickt vertrauenswürdige Krieger ins Gebiet der Grimmhauer, um Vorräte für die Horde zurückzuholen."}},faq={{q="Wer vergibt diese Quest?",a="Thork erteilt den Auftrag. Er ist der Offizier der Horde, der die Verteidigung und den Betrieb des Wegekreuzes überwacht.",al={"questgeber","thorks quest","wer startet vorräte für das wegekreuz"}},{q="Warum wurden die Vorräte überhaupt gestohlen?",a="Grimmhauer-Stacheleber überfielen eine Versorgungskarawane auf dem Weg zum Wegekreuz und schleppten die Kisten in nahe gelegene Lager.",al={"karawanenüberfall","warum gestohlen","was geschah mit den vorräten"}},{q="Wo sind die gestohlenen Kisten zu finden?",a="Vorratskisten des Wegekreuzes liegen in den Lagern der Grimmhauer östlich und nordöstlich des Wegekreuzes auf dem Boden verstreut.",al={"fundorte der kisten","wo sind die vorräte","kisten finden"}},{q="Warum ist es Thork so wichtig, diese Vorräte zurückzuholen?",a="Thork braucht die Vorräte, um den Betrieb und die Sicherheit des Wegekreuzes zu gewährleisten. Durch den Verlust von Karawanen fehlt Soldaten und Reisenden an diesem abgelegenen Außenposten das Nötigste.",al={"warum wichtig","bedeutung des wegekreuzes","bedeutung der vorräte"}},{q="Was kommt vor dieser Quest?",a="Diese Quest folgt auf „Disrupt the Attacks“. Dort schlugen Abenteurer gegen die Streitkräfte der Grimmhauer zu, um deren Angriffe auf die Reisewege der Horde abzuschwächen.",al={"voraussetzung","vorherige quest","disrupt the attacks"}},{q="Wer sind die Grimmhauer?",a="Die Grimmhauer sind ein wilder, auf sein Revier bedachter Stamm von Stachelebern, der im Brachland heimisch ist. Sie überfallen Karawanen und bekämpfen die Präsenz der Horde auf ihrem angestammten Land.",al={"grimmhauer-stacheleber","wer sind die stacheleber","grimmhauer"}}},fx={["1af261a6"]={q="Was sind die Vorratskisten des Wegekreuzes?",a="Diese Kisten enthalten lebenswichtige Vorräte und Materialien für die Siedlung Das Wegekreuz, die vor Kurzem von marodierenden Razormane-Stachelebern von einer Versorgungskarawane geplündert wurden. Die Siedlung liegt im ariden Herzen des Brachlands und ist stark auf diese regelmäßigen Lieferungen angewiesen, um ihre Verteidiger und das tägliche Leben zu versorgen.",al={"vorratskisten des wegekreuzes","was ist in den vorratskisten","gestohlene kisten thork"}}},fp="27,168,22.305.0,17.263.0,21.101.0,48.108.0,37.117.0,55.158.0,29.126.0,22.158.0"}
P.entries["quest:5042"] = {n="Agamaggans Kraft",s="In Camp Taurajo bietet Quetschzahn Reisenden der Horde Kraft aus Blutsplittern an. Der gefangene Razormane-Schamane verehrt den uralten Eberhalbgott Agamaggan und hasst den rivalisierenden Bristleback-Stamm.",h="In Camp Taurajo bietet Quetschzahn Reisenden der Horde Kraft aus Blutsplittern an.",kw={"agamaggan","brachland","blutsplitter","bristleback","camp taurajo","quetschzahn","stacheleber","razormane"},ang={["class:Warrior"]="Als Krieger schöpft Ihr aus der rohen Lebenskraft, die Quetschzahn vom Ebergott kanalisiert, um Euch in Kämpfen überall in Kalimdor körperlich überlegen zu machen.",["faction:Horde"]="Die Wachen von Camp Taurajo halten Quetschzahn unter Verschluss, doch die Befehlshaber der Horde nutzen den Rachedurst des alten Schamanen gegen feindliche Stacheleber.",["race:Tauren"]="Als Tauren helft Ihr, Camp Taurajo zu erhalten, und behaltet Quetschzahn misstrauisch im Auge. Eure Schamanen erkennen Agamaggan als uralten Schutzgeist des Landes an, doch der Fanatismus der Stacheleber hat sein Andenken verdorben."},sec={{t="Macht des Great Boar",b="Stacheleber verehren Agamaggan, einen uralten Eberhalbgott. Sie sagen, sein vergossenes Blut habe die roten Blutsplitter geformt, die im Brachland verstreut sind. Die Kristalle sind ihnen heilig, und ihre Macht stärkt die Kämpfer an der Front. Quetschzahn, ein betagter Razormane-Schamane, der in Camp Taurajo gefangen gehalten wird, bietet diese Kraft den Champions der Horde an. Er sagt, Eure Feinde werden vor Euch kauern, wie sie es vor den mächtigsten Champions der Razormane tun."},{t="Rache eines verbitterten Schamanen",b="Quetschzahn bietet seine Kraft aus Groll an. Orcs und Tauren nahmen den alten Stacheleber gefangen und sperrten ihn ein, dessen Razormane-Stamm mit den rivalisierenden Bristleback im Krieg liegt. Er kann seine Ketten nicht sprengen und sie selbst abschlachten, also tauscht er Agamaggans Gaben gegen Hilfe im Kampf gegen sie. Wer Bristleback-Stämme vernichtet und die heiligen Blutsplitter aus ihren Ländern nimmt, verdient sich seinen Segen."}},faq={{q="Was gewährt Agamaggans Kraft?",a="Agamaggans Kraft verleiht dem Empfänger durch die Macht der Blutsplitter größere körperliche Stärke. Sie gewährt die brutale Kraft der wildesten Razormane-Kämpfer.",al={"was bewirkt agamaggans kraft","agamaggans kraft stärkungszauber","kraftsegen brachland"}},{q="Wer ist Quetschzahn?",a="Quetschzahn ist ein gefangener Razormane-Stacheleber, der in Camp Taurajo im Südlichen Brachland festgehalten wird. Er hasst die rivalisierenden Bristleback und tauscht Geheimnisse und Segnungen der Stacheleber gegen Blutsplitter.",al={"wer ist quetschzahn","eingesperrter stacheleber taurajo","gefangener taurajo"}},{q="Was sind Blutsplitter?",a="Blutsplitter sind rötliche, kristallartige Mineralien, die überall im Brachland vorkommen. Der Überlieferung der Stacheleber zufolge entstanden sie dort, wo das Blut ihres Schutzhalbgottes, des Great Boar Agamaggan, während des uralten War of the Ancients niederfiel.",al={"was sind blutsplitter","blutsplitter hintergrundgeschichte","woher kommen blutsplitter"}},{q="Warum hilft Quetschzahn der Horde?",a="Quetschzahn hilft der Horde, weil er die rivalisierenden Bristleback-Stacheleber hasst. In Camp Taurajo eingesperrt und von seinem eigenen Volk verlassen, gewährt er Champions der Horde Agamaggans Segen, wenn sie seine Rivalen abschlachten und deren heilige Blutsplitter nehmen.",al={"warum hilft quetschzahn uns","quetschzahns beweggründe","warum der horde helfen"}},{q="Könnt Ihr diesen Segen mehrmals erhalten?",a="Ja. Nach Eurer ersten Prüfung für Quetschzahn wirkt er weiterhin Agamaggans Kraft und andere Segnungen, wenn Ihr ihm vier weitere Blutsplitter bringt.",al={"ist agamaggans kraft wiederholbar","wiederholbare blutsplitter","weitere blutsplitter abgeben"}},{q="Was unterscheidet die Stämme der Bristleback und Razormane?",a="Die Bristleback und Razormane sind rivalisierende Stacheleberstämme, die um das Brachland kämpfen. Quetschzahn gehört zu den Razormane, verachtet die Bristleback und prahlt damit, dass sein Stamm stärker sei.",al={"bristleback gegen razormane","stacheleberstämme brachland","warum hasst quetschzahn die bristleback"}}},fx={["3f27ba18"]={q="Warum benötigt Quetschzahn Euch, um Blutsplitter zu sammeln, anstatt es selbst zu tun?",a="Quetschzahn kann nicht selbst nach Blutsplittern jagen, da er in einem Käfig im Camp Taurajo gefangen gehalten wird. Während er davon träumt, Rache an den Leuten zu nehmen, die ihm den Rücken gekehrt haben, bleibt er ein Gefangener der Horde. Da er sein Gefängnis nicht verlassen kann, ist er auf Euch angewiesen, um seine Feinde im gesamten Brachland zu jagen, und bietet freudig die alten Segnungen seines Schutzpatrons für jeden Splitter, den Ihr erntet.",al={"warum benötigt quetschzahn mich","warum kann quetschzahn die splitter nicht selbst besorgen","quetschzahn warum ich"}}},fp="20,195,23.436.0,27.373.0,37.164.0,19.184.0,22.221.0,36.242.0,45.146.0,68.185.0"}
P.entries["quest:5043"] = {n="Agamaggans Beweglichkeit",s="In Camp Taurajo bietet Quetschzahn ein Blutsplitter-Ritual an. Der gefangene Quilboar kanalisiert die Macht seines uralten Ebergottes und segnet jene, die ihm Splitter aus dem Brachland bringen, mit schnellen Bewegungen und sicherem Zielen.",h="In Camp Taurajo bietet Quetschzahn ein Blutsplitter-Ritual an.",kw={"agamaggan","beweglichkeit","brachland","blutsplitter","quetschzahn","quilboar","taurajo"},ang={["class:Hunter"]="Als Jäger schätzt Ihr unfehlbares Zielen und schnelles Pirschen, hochgeschätzte Tugenden für Scharfschützen, die Kalimdors offene Weiten durchqueren.",["class:Rogue"]="Als Schurke hört Ihr Quetschzahn vielleicht über die Schnelligkeit von Schurken spotten, die keine Quilboar sind. Sein Ritual lässt Euch die heilige Schnelligkeit des Tieres gegen die Stämme des Buschlands wenden.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass ihre Streitkräfte Quetschzahns Anwesenheit und seinen Handel mit Blutsplittern dulden, weil die verbliebene Macht des Ebergottes ihren hart umkämpften Feldzug durch das Brachland unterstützt.",["race:Tauren"]="Als Tauren achtet Ihr die Urahnen, die im Krieg der Ahnen starben. Mit einem eingesperrten Quilboar in Taurajo zu handeln, mag dennoch Unbehagen wecken."},sec={{t="Die Macht der Blutsplitter",b="Karmesinrote Blutsplitter ragen aus dem Boden des Brachlands, besonders nahe den Lagern der Quilboar und großen Dornenranken. Die Überlieferung der Quilboar besagt, dass die Kristalle aus Agamaggans vergossenem Blut entstanden. Der Große Eber-Urahn fiel im Krieg der Ahnen im Kampf gegen die Brennende Legion. Obwohl er in Camp Taurajo eingesperrt ist, kann der ältere Quilboar Quetschzahn die göttliche Macht der Steine für jeden kanalisieren, der ihm Splitter bringt."},{t="Segen der Eberspäher",b="Jäger und Späher der Quilboar schätzen erbarmungslose Treffsicherheit und atemberaubende Schnelligkeit im Buschland. Für vier Blutsplitter ruft Quetschzahn die Macht des gefallenen Halbgottes an. Er verleiht dem Bittsteller die Instinkte und die geschmeidige Anmut der besten Pirscher seines Volkes. Quetschzahn grunzt Außenseiter an, hält aber seinen Pakt ein und webt Agamaggans Macht in einen vorübergehenden Mantel der Beweglichkeit."}},faq={{q="Wer bietet Agamaggans Beweglichkeit an?",a="Quetschzahn, ein Razormane-Quilboar, bietet das Ritual aus einem Käfig in Camp Taurajo im südlichen Brachland an. Obwohl die Horde ihn gefangen hält, handelt er mit Reisenden, die ihm Blutsplitter bringen.",al={"wer vergibt die quest","questgeber","wo ist quetschzahn"}},{q="Was sind Blutsplitter?",a="Blutsplitter sind kristalline Steine, die überall im Brachland zu finden sind. Sie werden hauptsächlich von erschlagenen Quilboar und aus Mineralvorkommen nahe Dornendickichten gesammelt. Der Überlieferung der Quilboar zufolge entstanden sie vor langer Zeit, als das Blut des Großen Eber-Urahnen Agamaggan die Erde tränkte.",al={"überlieferung der blutsplitter","was ist ein blutsplitter","rote kristalle im brachland"}},{q="Warum hilft ein gefangener Quilboar Mitgliedern der Horde?",a="Quetschzahn dient seinem Gott Agamaggan und versucht zu überleben. Er schnaubt jene an, die keine Quilboar sind, tauscht jedoch Agamaggans Segen gegen Blutsplitter und wirkt im Käfig seiner Feinde mit der heiligen Essenz seines Gottes.",al={"warum uns helfen","quetschzahns beweggründe","warum spricht quetschzahn"}},{q="Könnt Ihr diesen Segen mehr als einmal erhalten?",a="Ja. Ihr könnt den Segen erneut erhalten, indem Ihr Quetschzahn vier frische Blutsplitter bringt. Er ruft den Segen des Großen Ebers jedes Mal aufs Neue an.",al={"ist das wiederholbar","lässt sich das wiederholen","wiederholbarer stärkungszauber"}},{q="Wer war Agamaggan?",a="Agamaggan war ein gewaltiger Eber-Urahn, der im mythischen Zeitalter der Vorzeit durch Kalimdor streifte. Im Krieg der Ahnen vor zehntausend Jahren kämpfte er gegen die Dämonen der Brennenden Legion und fiel. Sein Blut nährte die messerscharfen Dornen des Brachlands, machte sie undurchdringlich und ließ das Volk der Quilboar entstehen.",al={"wer ist agamaggan","ebergott","großer eber"}},{q="Welche anderen Segen gewährt Quetschzahn?",a="Quetschzahn bietet Rituale an, die andere Aspekte Agamaggans ehren. Für Blutsplitter kann er Euch mit größerer Körperkraft, geistiger Weisheit, schnellerem Laufen oder Haut segnen, die so dick wie razorhide ist.",al={"andere blutsplitterquests","andere stärkungszauber","quetschzahns belohnungen"}}},fx={f192776b={q="Warum benötigt Quetschzahn Euch, um ihm Blutsplitter zu bringen?",a="Quetschzahn kann die Splitter nicht selbst sammeln, da er von der Horde im Camp Taurajo gefangen gehalten wird. Eingesperrt in seinem Käfig ist er auf Außenstehende angewiesen, die bereit sind, die durch das Brachland streifenden Stacheleber zu erschlagen, die heiligen Steine aus ihren Überresten zu bergen und sie zu seiner Zelle zurückzubringen.",al={"warum benötigt quetschzahn mich","warum nach blutsplittern fragen","warum kann quetschzahn keine splitter besorgen"}}},fp="19,204,25.386.0,27.372.0,31.196.0,22.259.0,48.201.0,45.141.0,18.301.0,46.196.0"}
P.entries["quest:5044"] = {n="Weisheit von Agamaggan",s="In Camp Taurajo bietet Quetschzahn Zauberwirkern der Horde Zugang zu Agamaggans Macht. Der gefangene Stacheleber verlangt dafür Blutscherben.",h="In Camp Taurajo bietet Quetschzahn Zauberwirkern der Horde Zugang zu Agamaggans Macht.",kw={"brachland","blutscherben","ebergott","camp taurajo","geomant","quetschzahn","stacheleber","weisheit von agamaggan"},ang={["class:Mage"]="Als Magier könnt Ihr erkennen, wie Agamaggans Essenz urtümliche geomantische Macht in reinen Intellekt umwandelt.",["class:Priest"]="Als Priester findet Ihr die Verbindung zwischen Agamaggans göttlichem Blut und Ritualen, die den Geist stärken, vielleicht einen faszinierenden Teil urtümlicher Verehrung.",["class:Shaman"]="Als Schamane erkennt Ihr vielleicht, wie die Geomantie der Stacheleber elementare Anrufungen widerspiegelt, während die Scherbenrituale des Ebergottes ihre ganz eigene Wildheit bewahren.",["faction:Horde"]="In Camp Taurajo hält die Horde Quetschzahn gefangen. Das gibt Euch die Gelegenheit, die einheimische Magie des Brachlands gegen die Stämme der Stacheleber einzusetzen."},sec={{t="Blutscherben und uralte Macht",b="In Camp Taurajo hält die Horde Quetschzahn gefangen. Der Stacheleber tauscht die magischen Geheimnisse seines Volkes gegen Blutscherben, karminrote Kristalle, die aus Agamaggans vergossenem Blut entstanden sein sollen. Der gewaltige Eber-Halbgott fiel im Krieg der Ahnen. Quetschzahn sagt, die Geomanten und Schamanen seiner Stämme nutzen die Scherben, um göttliche Macht in ihre Rituale zu leiten."},{t="Segen des Geistes",b="Manche Scherbenopfer verleihen körperliche Widerstandskraft oder Schnelligkeit. Quetschzahns Weisheitsritual hingegen schärft den Geist und die arkanen Fähigkeiten. Für vier Blutscherben ruft er Agamaggans Geist an, damit dieser Euch Schläue bei Euren Konfrontationen gewährt. Dann erinnert er Euch daran, dass Ihr sterblich seid."}},faq={{q="Wer ist Agamaggan?",a="Agamaggan ist ein uralter Eber-Halbgott, der vor zehntausend Jahren im Krieg der Ahnen gegen die Brennende Legion kämpfte. Er fiel im Brachland, wo sein Blut den Boden tränkte und riesige Dornenranken und kristalline Blutscherben entstehen ließ.",al={"agamaggan hintergrund","wer ist der ebergott","uralter eber"}},{q="Warum ist Quetschzahn bereit, der Horde zu helfen?",a="Quetschzahn ist ein gefangener Stacheleber, der in einem Käfig in Camp Taurajo festgehalten wird. Sein Stamm hasst die Horde zutiefst, doch ihm sind Blutscherben und sein eigenes Überleben wichtiger als Treue. Im Tausch gegen Scherben gewährt er heilige Stammessegen.",al={"warum quetschzahn helfen","quetschzahn beweggrund","gefangener stacheleber"}},{q="Was sind Blutscherben?",a="Blutscherben sind rote Mineralgebilde, die überall in den Gebieten der Stacheleber im Brachland vorkommen. Einer Legende der Stacheleber zufolge entstanden die Kristalle aus Blutstropfen, die Agamaggan im Sterben vergoss.",al={"blutscherben hintergrund","was sind blutscherben","rote scherben brachland"}},{q="Kann ich dieses Ritual mehrmals wiederholen?",a="Ja. Sobald Ihr Quetschzahn zum ersten Mal Blutscherben gezeigt und sein Vertrauen gewonnen habt, nimmt er jeweils vier an, wann immer Ihr den Segen erneuern möchtet.",al={"ist weisheit von agamaggan wiederholbar","wiederholbare blutscherben","erneut abgeben"}},{q="Verehren die Schamanen der Stacheleber andere Gottheiten?",a="Die Stacheleber verehren Agamaggan über alle anderen und glauben, direkt von ihm abzustammen. Ihre Schamanen und Geomanten schöpfen Naturmagie und Macht über die Erde aus seinem Vermächtnis und seinen Überresten.",al={"religion der stacheleber","götter der geomanten","verehrung der stacheleber"}},{q="Wo könnte laut Quetschzahn unser nächstes Treffen stattfinden?",a="Nach dem Ritual bittet Quetschzahn Euch, beim nächsten Treffen von Eurer Schläue zu erzählen, ob in diesem Leben oder im nächsten. Seine Worte zeugen vom unaufhörlichen Blutvergießen im Brachland.",al={"quetschzahn nächstes leben","quetschzahn dialog"}}},fx={daf5c556={q="Warum benötigt Quetschzahn Euch, um ihm Blutsplitter zu bringen?",a="Quetschzahn wird unter den wachsamen Augen der Horde in einem Käfig im Camp Taurajo gefangen gehalten. Da er nicht durch das Brachland streifen kann, um selbst Blutsplitter zu sammeln, handelt er mit seinem Wissen über die Stacheleber-Geomantie und den uralten Segnungen des Großen Ebers im Austausch für Splitter, die von Reisenden gesammelt werden, die durch das Lager ziehen.",al={"warum benötigt quetschzahn mich","warum blutsplitter zu quetschzahn bringen","warum kann quetschzahn keine blutsplitter besorgen"}}},fp="19,146,30.363.0,20.278.0,17.242.0,45.224.0,22.178.0,40.137.0,41.188.0,57.193.0"}
P.entries["quest:5045"] = {n="Steigerung des Geistes",s="In Camp Taurajo bietet Euch Quetschzahn einen alten Segen aus Agamaggans Macht an. Bringt Blutscherben von seinen Rivalen, den Borstennacken, und er wird Euren Willen und Geist stärken.",h="In Camp Taurajo bietet Euch Quetschzahn einen alten Segen aus Agamaggans Macht an.",kw={"agamaggan","brachland","blutscherben","borstennacken","camp taurajo","quetschzahn","klingenhauer","steigerung des geistes"},ang={["class:Priest"]="Als Priester seht Ihr die Zwiesprache der Stacheleber mit Agamaggan vielleicht als ursprünglichen Ausdruck von Glauben und Geist, der den geordneten Andachtsformen östlicher Kirchen ebenbürtig ist.",["class:Shaman"]="Als Schamane versteht Ihr, wie uralte Blutlinien und Mineralien der Erde die Geister des Landes an einen sterblichen Krieger binden können.",["faction:Horde"]="Als Wanderer der Horde im Brachland könnt Ihr Quetschzahns Hass auf die Borstennacken zu Eurem Vorteil nutzen."},sec={{t="Willenskraft der Klingenhauer",b="In einem Käfig in Camp Taurajo kennt Quetschzahn die Geomantie und Ahnenmagie der Stacheleber. Er ist stolz auf die Hingabe seines Volkes an seinen Schöpfer, den Großen Eber Agamaggan. Für Quetschzahn trägt ein ungebrochener Geist einen Krieger weiter, wenn die Kraft versagt und die Niederlage naht."},{t="Die Macht der Blutscherben",b="Quetschzahn bittet Euch um Blutscherben, um Euren Geist zu stärken. Diese Kristalle bergen Agamaggans uraltes Blut, das vor zehntausend Jahren in die rote Erde sickerte. Bringt Scherben, die im ganzen Brachland gesammelt wurden, besonders von seinen Feinden, den Borstennacken. Dann kann Quetschzahn ihre Macht in einen Segen lenken, der Euren Willen stärkt."}},faq={{q="Wer ist Quetschzahn?",a="Quetschzahn ist ein Ältester der Klingenhauer-Stacheleber, der in einem hölzernen Käfig in Camp Taurajo gefangen gehalten wird. Obwohl die Horde ihn gefangen hält, gewährt er im Austausch gegen Blutscherben heilige geomantische Riten und setzt Reisende gegen die rivalisierenden Borstennacken ein.",al={"quetschzahn hintergrund","wer ist der eber im käfig","taurajo gefangener"}},{q="Was sind Blutscherben?",a="Blutscherben sind rote Mineralkristalle, entstanden aus dem Blut von Agamaggan, einem uralten Halbgott, der während des War of the Ancients im Brachland starb. Schamanen und Geomanten der Stacheleber nutzen ihre fortwirkende Magie für Segen und Riten.",al={"was sind blutscherben","blutscherben hintergrund","agamaggan blut"}},{q="Warum hilft Quetschzahn Abenteurern der Horde?",a="Quetschzahn hasst die rivalisierenden Borstennacken-Stacheleber. Er tauscht Segen gegen Blutscherben, um mächtige Reisende dazu anzutreiben, überall im Brachland Borstennacken zu töten, und führt die Fehde seines Stammes hinter Käfigstäben fort.",al={"warum hilft quetschzahn","warum hilft stacheleber der horde"}},{q="Was bewirkt der Segen Steigerung des Geistes?",a="Quetschzahns Segen Steigerung des Geistes stärkt den Geist und die Entschlossenheit eines Kriegers. Er schöpft aus Agamaggans fortdauernder Lebenskraft, um die Hoffnung in schweren Kämpfen am Leben zu erhalten.",al={"steigerung des geistes verstärkung","was ist steigerung des geistes"}},{q="Wer ist Agamaggan?",a="Agamaggan ist der gewaltige Eber und Uralte, der vor zehntausend Jahren während des War of the Ancients gegen die Brennende Legion kämpfte. Die Stacheleber verehren ihn als ihren Schöpfer und glauben, dass die dornigen Ranken und roten Blutscherben des Brachlands aus seinem gefallenen Körper erwuchsen.",al={"agamaggan","der große eber"}},{q="Ist dieser rituelle Tausch nur einmal möglich?",a="Nein. Bringt Quetschzahn vier Blutscherben, und er wird das Ritual erneut vollziehen, um Euren Segen zu erneuern, bevor Ihr Euch ins Ödland wagt.",al={"steigerung des geistes wiederholen","ist steigerung des geistes wiederholbar"}}},fx={["21d8d0f0"]={q="Warum braucht Quetschzahn Euch, anstatt Splitter selbst zu sammeln?",a="Quetschzahn ist ein Gefangener der Horde, der sicher in einem Käfig in Camp Taurajo festgehalten wird. Da er weder selbst durch die Ebenen streifen noch gegen seine rivalisierenden Stacheleber kämpfen kann, muss er sich auf vorbeiziehende Abenteurer verlassen, die ihm die heiligen Blutsplitter bringen, die er für die Durchführung seiner uralten Rituale benötigt.",al={"warum quetschzahn mich braucht","warum quetschzahn splitter nicht selbst beschaffen kann","warum mich fragen"}}},fp="13,184,26.281.0,25.330.0,19.223.0,22.235.0,44.205.0,40.168.0,17.253.0,32.136.0"}
P.entries["quest:5046"] = {n="Klingenhaut",s="In Camp Taurajo bietet Quetschzahn allen ein Ritual an, die ihm Blutscherben bringen. Der gefangene Borstennacken tauscht Agamaggans Lebensessenz gegen einen Segen, der vor dem Kampf die Haut härtet.",h="In Camp Taurajo bietet Quetschzahn allen ein Ritual an, die ihm Blutscherben bringen.",kw={"agamaggan","brachland","blutscherben","camp taurajo","quetschzahn","borstennacken","razorhide"},ang={["class:Warrior"]="Als Krieger profitiert Ihr von magischer Rüstung und gehärteter Haut, wenn Ihr die gefährlichen Dornendickichte des Südlichen Brachlands betretet.",["faction:Horde"]="Als Mitglied der Horde erlebt Ihr, wie Camp Taurajo dem Vordringen der Borstennacken standhält. Quetschzahns Verehrung für Agamaggan gibt Reisenden die Möglichkeit, sich seine Rituale zunutze zu machen.",["race:Tauren"]="Als Tauren wisst Ihr, dass die Jäger von Camp Taurajo Quetschzahns Käfig genau im Auge behalten. Die Rituale der Borstennacken berühren heiligen Boden der Earthmother, doch ihre wilden Praktizierenden teilen Geheimnisse selten ohne Gegenleistung."},sec={{t="Segen des Ebergottes",b="Die Borstennacken führen ihre Macht auf Agamaggan zurück, den Großen Eber, der vor Jahrtausenden im Kampf gegen die Brennende Legion starb. Sein Blut versickerte im Brachland und erstarrte zu kristallinen Scherben, in denen noch immer uralte Macht lebt. Die Horde und die Borstennacken bleiben geschworene Feinde. Doch Quetschzahn, der in Camp Taurajo in einem Käfig gefangen gehalten wird, teilt womöglich heiliges Wissen im Tausch gegen diese Fragmente."},{t="Die Haut härten",b="Borstennacken werden mit dicker Haut und schützenden Stacheln geboren. Ihre Krieger rufen Agamaggan an, um ihre Haut gegen Klingen und Klauen zu härten. Quetschzahn kann das Ritual für Außenstehende vollziehen und dabei die Kraft von vier Blutscherben kanalisieren, um ihre Abwehr zu stärken und ihre Knochen in der Wildnis vor Brüchen zu bewahren."}},faq={{q="Wer bietet das Ritual Razorhide an?",a="Quetschzahn, ein Borstennacken, der in einem Holzkäfig in Camp Taurajo im Südlichen Brachland gefangen ist, bietet das Ritual Razorhide an. Sobald Ihr zeigt, dass Ihr mit Blutscherben umzugehen wisst, tauscht er weitere gegen Segen ein.",al={"wer gewährt razorhide","quetschzahn quest","wer startet razorhide"}},{q="Was sind Blutscherben?",a="Blutscherben sind Kristalle, die überall im Brachland zu finden sind. Die Borstennacken glauben, dass sie während des War of the Ancients aus Agamaggans vergossenem Blut entstanden und noch immer mächtige urtümliche Magie bergen.",al={"was sind blutscherben","blutscherben hintergrund","blut von agamaggan"}},{q="Warum hilft ein gefangener Borstennacken Reisenden der Horde?",a="Quetschzahn wird von den Tauren in Camp Taurajo gefangen gehalten. Er behält seine raue Art und seine Treue zu Agamaggan, doch sein Hunger nach Blutscherben bewegt ihn dazu, Außenstehende die Rituale der Borstennacken zu lehren.",al={"warum hilft quetschzahn","warum ist quetschzahn in taurajo","freundliche borstennacken"}},{q="Welche Art von Schutz bietet Razorhide?",a="Razorhide ist ein Schutzzauber der Borstennacken, der vor dem Kampf angerufen wird. Er härtet die Haut und stärkt die Knochen mit Agamaggans übernatürlicher Widerstandskraft.",al={"was bewirkt razorhide","razorhide hintergrund","schützender segen"}},{q="Könnt Ihr Razorhide mehr als einmal erhalten?",a="Ja. Quetschzahn kann Razorhide erneut anrufen, wann immer Ihr ihm vier Blutscherben bringt.",al={"ist razorhide wiederholbar","razorhide wiederholen","wie oft lässt sich razorhide machen"}},{q="Wo lassen sich Blutscherben finden?",a="Blutscherben lassen sich bei Geomanten, Jägern und Kriegern in den Lagern, Dornengestrüppen und Felsklüften der Borstennacken im gesamten Brachland erbeuten.",al={"blutscherben fundorte","wo gibt es blutscherben","blutscherben farmen"}}},fx={f8770fb0={q="Wofür verwendet Quetschzahn die Blutsplitter?",a="Blutsplitter enthalten die kristallisierte Kraft und das Lebensblut des Stacheleber-Ahnen, dem Großen Eber Agamaggan. Quetschzahn kanalisiert die verbliebene göttliche Energie, die in vier dieser Steine gefangen ist, um die Gunst des Gottes zu beschwören, was Euer Fleisch härtet und Euch die übernatürliche Widerstandskraft verleiht, auf die sich Stacheleber-Krieger vor dem Marsch in die Schlacht verlassen.",al={"wofür werden blutsplitter verwendet","warum blutsplitter razorhide","zweck von blutsplittern razorhide"}}},fp="9,186,25.376.0,18.292.0,32.203.0,22.179.0,54.187.0,49.147.0,41.85.0,32.137.0"}
P.entries["quest:505"] = {n="Auftragsmörder des Syndikats",s="Süderstades neuer Magistrat vermutet, dass die Auftragsmörder des Syndikats seinen Vorgänger getötet haben. Seine Hinweise deuten auf einen Ort nördlich von Tarrens Mühle, wo er die Bande erschlagen sehen will.",h="Süderstades neuer Magistrat vermutet, dass die Auftragsmörder des Syndikats seinen Vorgänger getötet haben.",kw={"alterac","wegelagerer","henry maleb","magistrat","süderstade","syndikat","tarrens mühle","dieb"},sec={{t="Ein Magistrat ermordet",b="Magistrat Henry Maleb hat nun das Amt in Süderstade inne. Der vorherige Magistrat wurde ermordet, und die Mörder wurden nie gefunden. Maleb ist sich fast sicher, dass das Syndikat sie angeheuert hat.\n\nDie Bande besteht aus Dieben, angeführt von schurkischen Adligen aus dem gefallenen Königreich Alterac. Malebs letzte Hinweise deuten auf einen Ort nördlich von Tarrens Mühle, die von der Horde besetzt ist. Er bittet Euch, die Mitglieder des Syndikats im dortigen Lager zu erschlagen."}},faq={{q="Warum will Magistrat Henry Maleb die Mitglieder des Syndikats erschlagen sehen?",a="Süderstades vorheriger Magistrat wurde ermordet, und die Mörder wurden nie gefunden. Magistrat Henry Maleb ist sich fast sicher, dass das Syndikat sie angeheuert hat.",al={"warum syndikatsmitglieder töten","motiv des syndikats","wer hat den magistrat getötet"}},{q="Wer führt das Syndikat an?",a="Schurkische Adlige aus dem gefallenen Königreich Alterac führen das Syndikat an, dessen Mitglieder Diebe sind.",al={"wer führt das syndikat","anführer des syndikats","syndikat alterac"}},{q="Wo liegt das Lager des Syndikats?",a="Das Lager des Syndikats liegt nördlich von Tarrens Mühle, die von der Horde besetzt ist. Malebs letzte Hinweise führten dorthin.",al={"wo sind die wegelagerer des syndikats","lager des syndikats standort","wo sind die diebe des syndikats"}}},fp="19,155,21.404.0,57.153.0,24.99.0,28.103.0"}
P.entries["quest:5052"] = {n="Blutsplitter von Agamaggan",s="Im ganzen Brachland bergen die Blutsplitter von Agamaggan noch die Macht eines gefallenen Ebergottes. Die Stacheleber sagen, sein Blut sei in die Erde gesickert und zu roten Steinen erstarrt. In Camp Taurajo handelt der gefangene Quetschzahn aus eigenen Beweggründen mit dieser Macht und bietet sie der Horde an.",h="Im ganzen Brachland bergen die Blutsplitter von Agamaggan noch die Macht eines gefallenen Ebergottes.",kw={"agamaggan","brachland","blutsplitter","bristleback","camp taurajo","quetschzahn","stacheleber","razorfen"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass Blutsplitter rohe, ursprüngliche Erd- und Geistermagie bergen. Sie zeugen davon, wie tiefgreifend Titanengeschmiedete und urtümliche Geister Kalimdor geprägt haben.",["faction:Horde"]="Um Camp Taurajo zu sichern, muss die Horde die aggressiven Stämme der Bristleback und Razorfen niederhalten. Der Groll eines eingesperrten Stachelebers kann die Stärke ihres Halbgottes gegen sie wenden.",["profession:Mining"]="Im ganzen Brachland können Bergleute Blutsplitter finden, die neben Zinn- und Kupfererz eingebettet sind. Sie holen das kristallisierte Blut eines Ancient Guardian aus den Adern.",["race:Tauren"]="Als Tauren seht Ihr die Stacheleber als aggressive Rivalen im Kampf um das schwindende Wasser und Wild der Ebenen. Dennoch gebührt Agamaggans Opfer im uralten Krieg Euer spiritueller Respekt."},sec={{t="Das Erbe des Ebergottes",b="Die Überlieferungen der Stacheleber erzählen, wie Agamaggan vor zehntausend Jahren im Krieg der Ahnen fiel. Sein Blut ließ riesige Dornenlabyrinthe auf den Ebenen entstehen, sank dann ins Erdreich und sickerte in die Mineralien. Mit der Zeit erstarrte es zu blutroten Steinen.\n\nDie Stacheleber verehren die Splitter als heilige Überreste ihres Schöpfers. Sie sammeln sie aus Mineraladern und an heiligen Stätten und nutzen sie dann als Totems im Kampf und bei der Hexerei."},{t="Groll aus dem Holzkäfig",b="Die Tauren halten Quetschzahn in einem Käfig in Camp Taurajo gefangen. Er hegt einen bitteren Groll gegen seinesgleichen und sagt, sein Stamm habe ihn verraten und verstoßen.\n\nSeiner Freiheit und der Magie seines Volkes beraubt, handelt er mit Euch um Blutsplitter. Ihre Macht lässt ihn trotz seiner Gefangenschaft auf Agamaggans Magie zugreifen und sie dann an Champions der Horde weiterleiten. Es bereitet ihm Freude, diese Macht gegen die Stacheleber zu richten, die ihn verstoßen haben."},{t="Razorfens heilige Wurzeln",b="Quetschzahn spricht voller Ehrfurcht von Razorfen, dem heiligsten Heiligtum der Stacheleber im Süden. Die Stämme sagen, das gewaltige Dornengestrüpp im Kral der Klingenhauer und in den Hügeln der Klingenhauer sei aus Agamaggans kolossalem Skelett und seinen Hauern gewachsen.\n\nSie glauben, die Hügel der Klingenhauer lägen im klaffenden Schlund des Halbgottes. Es ist eine heilige Schwelle, die jeden verschlingt und zermalmt, der sie ohne die Gunst des Ebergottes betritt."}},faq={{q="Was sind Blutsplitter?",a="Blutsplitter sind rote Steine, die entstanden, als Agamaggans Blut während des Krieges der Ahnen in die Erde sickerte. Sie bergen Überreste der göttlichen Magie der Stacheleber und finden sich in Mineraladern oder werden von Stachelebern als Totems getragen.",al={"was ist ein blutsplitter","blutsplitter hintergrund","woher kommen blutsplitter"}},{q="Warum ist Quetschzahn bereit, der Horde zu helfen?",a="Quetschzahn wird in Camp Taurajo gefangen gehalten und sagt, sein eigenes Volk habe ihm den Rücken gekehrt. Verbittert über seine Verbannung und von der heiligen Macht seines Volkes abgeschnitten, bietet er an, Champions der Horde gegen die Stacheleber zu stärken, die ihn verschmähten.",al={"warum hilft quetschzahn","ist quetschzahn freundlich","warum gefangenen stachelebern helfen"}},{q="Welche Stärkungszauber gewährt Quetschzahn?",a="Quetschzahn tauscht Blutsplitter gegen vorübergehende urtümliche Gaben zu Agamaggans Ehren. Sie können Beweglichkeit, Stärke, Intelligenz, Willenskraft und Rüstung verbessern sowie schnellere Bewegung durch das Brachland ermöglichen.",al={"blutsplitter stärkungszauber","was gibt es für blutsplitter","quetschzahns gaben"}},{q="Wo liegt Razorfen, und welche Bedeutung hat es?",a="Razorfen liegt im äußersten Süden des Brachlands. Die Stacheleber verehren es als ihre heiligste Stätte und glauben, sein hoch aufragendes Dornengestrüpp sei aus Agamaggans gefallenem Leib gewachsen und die Hügel der Klingenhauer seien der kolossale Schlund des Halbgottes.",al={"was ist razorfen","warum ist razorfen heilig","hügel der klingenhauer hintergrund"}},{q="Wer war Agamaggan?",a="Agamaggan war ein Ancient Guardian, ein titanischer Ebergott, der vor zehntausend Jahren im Kampf gegen die Brennende Legion starb. Sein vergossenes Blut ließ das gewaltige, messerscharfe Dornengestrüpp des Brachlands entstehen und schenkte den Stachelebern das Leben und ihre mystische Kraft.",al={"wer ist agamaggan","ebergott","gott der stacheleber"}},{q="Können Bergleute im Brachland Blutsplitter finden?",a="Ja. Agamaggans Blut durchdrang die Gesteine und Mineralien des Brachlands, sodass Bergleute manchmal neben gewöhnlichem Zinn- und Kupfererz auch Blutsplitter finden.",al={"blutsplitter abbauen","lassen sich blutsplitter abbauen","erz blutsplitter"}}},fx={["2869bf9b"]={q="Warum benötigt Quetschzahn Euch, damit Ihr für ihn Blutsplitter sammelt?",a="Quetschzahn sitzt in einem Käfig im Camp Taurajo unter der strengen Bewachung der Horde fest. Nachdem er von seinen heiligen Relikten und seinem Volk getrennt wurde, ist er physisch nicht in der Lage, sich in das Brachland zu wagen und die Splitter selbst zu sammeln. Indem er Euch rekrutiert, erhält er wieder Zugang zu den Steinen von Agamaggans Kraft, während er gleichzeitig einen externen Champion gegen genau die Stämme wendet, die ihn verraten haben.",al={"warum ich quetschzahn","warum kann quetschzahn keine splitter besorgen","warum benötigt quetschzahn hilfe"}}},fp="25,254,21.406.0,24.411.0,23.371.0,22.223.0,45.231.0,36.181.0,48.202.0,18.238.0,44.140.0"}
P.entries["quest:506"] = {n="Blackmoores Vermächtnis",s="Gol'dir ist bereits frei und überbringt Krusk in Tarrens Mühle eine Nachricht. Aliden Perenolde, Anführer des Syndikats, besuchte ihn und sprach davon, Orcs zu versklaven, die sich widersetzen. Perenolde brachte Elysa mit, die den Anhänger trägt, den der Kriegshäuptling begehrt.",h="Gol'dir ist bereits frei und überbringt Krusk in Tarrens Mühle eine Nachricht.",kw={"aliden","blackmoore","elysa","goldir","krusk","vermächtnis","anhänger","perenolde","syndikat","tarrens mühle"},sec={{t="Ein Besuch beim Gefangenen",b="Gol'dir hat nach einem Besuch von Aliden Perenolde, dem Anführer des Syndikats, eine Nachricht für Krusk. Perenolde nannte sich selbst Herrscher des Landes und sprach davon, Orcs zu versklaven, die sich ihm widersetzen. Sein Vater und Mentor, der verachtete Blackmoore, hatte dasselbe geplant.\n\nGol'dir schickt Euch, diese Nachricht Krusk in Tarrens Mühle zu überbringen. Er wird folgen, sobald er seine eigenen Angelegenheiten vor Ort geregelt hat."},{t="Elysas Anhänger",b="Perenolde brachte auch seine Geliebte mit, ein zierliches Mädchen namens Elysa. Um ihren Hals hing der Anhänger, den der Kriegshäuptling begehrt."},{t="Krusks Antwort",b="Krusk reagiert mit Zorn auf Perenoldes Drohung. Er schwört, dass sich die Orcs niemals unterwerfen werden, und erklärt den Widerstand ebenso zum Ziel wie die Wiederbeschaffung des Schmuckstücks, das der Kriegshäuptling begehrt. Krusk sagt, dass das Erreichen eines der beiden Ziele auch das andere in Reichweite bringen wird."}},faq={{q="Wer vergibt diese Quest?",a="Gol'dir gibt Euch diese Quest, nachdem Ihr ihn aus den Fängen des Syndikats befreit habt.",al={"wer vergibt blackmoores vermächtnis","questgeber","goldir"}},{q="Wer soll die Nachricht erhalten?",a="Bringt die Nachricht zu Krusk in Tarrens Mühle.",al={"wohin gehen","mit wem sprechen","abgabeort"}},{q="Was offenbarte Aliden Perenolde Gol'dir?",a="Aliden Perenolde, Anführer des Syndikats, sagte Gol'dir, er wolle Orcs versklaven, die sich ihm widersetzten. Sein Vater und Mentor, der verachtete Blackmoore, hatte dasselbe geplant.",al={"perenoldes plan","pläne des syndikats","was sagte perenolde"}},{q="Was bemerkte Gol'dir während des Besuchs noch?",a="Perenolde brachte seine Geliebte mit, ein Mädchen namens Elysa, das den Anhänger, den der Kriegshäuptling begehrt, um den Hals trug.",al={"elysas halskette","anhänger des kriegshäuptlings","geliebte"}},{q="Was geschah vor dieser Quest?",a="Ihr habt Gol'dir aus den Fängen des Syndikats befreit.",al={"vorherige quest","was geschah zuvor"}}},fp="19,229,23.372.0,15.118.0,14.233.1,21.64.0,28.39.0,44.168.0,46.110.0,28.37.0"}
P.entries["quest:5061"] = {n="Wassergestalt",s="Ihr bringt den wiederhergestellten Anhänger des Seelöwen nach Darnassus zurück. Der Ritus lehrt Druiden der Allianz, ihre Geister auf tiefe Gewässer einzustimmen.",h="Ihr bringt den wiederhergestellten Anhänger des Seelöwen nach Darnassus zurück.",kw={"wassergestalt","die enklave des cenarius","darnassus","dendrite sternenschauer","mathrengyl bärenfährte","mondlichtung","anhänger des seelöwen","seelöwe"},ang={["class:Druid"]="Für Euch als Druide markiert dieser Ritus einen Schritt in Eurer Verbundenheit mit der Natur. Die Wassergestalt lässt Euch unter Wasser schnell vorankommen und unter der Oberfläche unbegrenzt atmen.",["faction:Alliance"]="Als Druide der Allianz bereiten Euch Eure Prüfungen darauf vor, Seen, Flüsse und Küsten mühelos auszukundschaften.",["race:NightElf"]="Als Nachtelf kehrt Ihr aus den zeitlosen Wäldern von Mondlichtung in die junge Krone von Teldrassil zurück. Dies bekräftigt Eure Pflicht, Azeroths Wildnis inmitten eines sich wandelnden Gleichgewichts zu schützen."},sec={{t="Ein heiliger Bund mit den Tiefen",b="Für Initianden des Zirkels des Cenarius verbindet die Gestaltwandlung den Geist eines Druiden mit den wilden Aspekten von Azeroth. Junge Nachtelfendruiden bestehen Prüfungen in den dunklen Küstentiefen und in Mondlichtung. Dort überreicht ihnen Dendrite Sternenschauer den zusammengesetzten Anhänger des Seelöwen. Sie tragen dieses heilige Zeichen zurück nach Teldrassil, als Beweis ihrer Achtung vor den Gesetzen von Luft, Wasser und Atem."},{t="Rückkehr nach Darnassus",b="Mathrengyl Bärenfährte erwartet Eure Rückkehr in der Enklave des Cenarius. Eure Prüfungen an den Küsten von Dunkelküste und Westfall haben Eure Ausdauer und Einstimmung auf die Probe gestellt. Legt den vervollständigten Anhänger vor, um Bearwalker zu zeigen, dass Euer Geist und Körper bereit sind, ihre sterbliche Hülle abzustreifen. Dann könnt Ihr die flinke, atmende Gestalt des Seelöwen annehmen."}},faq={{q="Was ist der Zweck dieser Quest?",a="Die Übergabe des wiederhergestellten Anhängers des Seelöwen an Mathrengyl Bärenfährte in Darnassus schließt die Ausbildung eines Druiden der Allianz in der Wassergestalt ab. Der Anhänger beweist, dass Ihr bereit seid, diese Wassergestalt zu erlernen.",al={"warum diese quest machen","zweck der wassergestalt","was bringt diese quest"}},{q="Wer schickt Euch nach Darnassus zurück?",a="Dendrite Sternenschauer schickt Euch von Mondlichtung zurück nach Teldrassil, nachdem Ihr die Trial of the Sea Lion abgeschlossen habt. Starblaze ist ein Ältester des Zirkels des Cenarius.",al={"wer vergibt diese quest","questgeber","dendrite sternenschauer"}},{q="Wer schließt Eure Ausbildung in Darnassus ab?",a="Mathrengyl Bärenfährte nimmt Euren Anhänger in der Enklave des Cenarius in Darnassus entgegen und lehrt Euch den Aspekt des Wassers. Er ist dort der Druidenlehrer.",al={"questabgabe","bei wem wassergestalt abgeben","mathrengyl bärenfährte"}},{q="Was ist der Anhänger des Seelöwen?",a="Der Anhänger des Seelöwen ist ein heiliger Talisman, der aus zwei Prüfungsanhängern zusammengesetzt wird, die aus den Wassertiefen vor Dunkelküste und Westfall geborgen wurden. Er beweist, dass ein Druide die Ausdauer und Geduld gemeistert hat, die Meeresgeschöpfe benötigen.",al={"was ist der anhänger","geschichte des anhängers des seelöwen"}},{q="Erfüllen Druiden der Horde genau diese Quest?",a="Nein. Auch Taurendruiden stellen sich Prüfungen in Mondlichtung, um ihren Aspekt des Wassers zu erlangen. Danach kehren sie zu Turak Runentotem auf den Tafelbergen von Donnerfels zurück, statt nach Darnassus.",al={"können tauren das machen","ist diese quest nur für die allianz","hordenversion"}},{q="Wo in Darnassus befindet sich Mathrengyl Bärenfährte?",a="Mathrengyl Bärenfährte befindet sich in der Enklave des Cenarius, im nordwestlichen Bezirk von Darnassus hoch auf den Ästen von Teldrassil.",al={"wo ist mathrengyl","standort des druidenlehrers in darnassus"}}},fx={d3754c26={q="Warum schickt Dendrite Sternenschauer Euch zurück nach Darnassus?",a="Dendrite Sternenschauer hat Euch durch die heiligen Prüfungen der Mondlichtung geführt, doch es ist die Pflicht Eures örtlichen Mentors Mathrengyl Bärenfährte, die letzten Lektionen zu erteilen. Indem Ihr mit dem zusammengesetzten Anhänger des Seelöwen zurückkehrt, liefert Ihr den Beweis für Eure Einsatzbereitschaft und Disziplin, was es Mathrengyl ermöglicht, Eure Ausbildung abzuschließen und Euch die Meisterschaft über den aquatischen Aspekt zu gewähren.",al={"warum schickt dendrite dich zurück","dendrite sternenschauer motiv","warum zurück nach darnassus"}}},fp="12,138,29.371.0,19.334.0,34.205.0,32.154.0,41.144.0,36.225.0,36.165.0,44.119.0"}
P.entries["quest:5062"] = {n="Hochheiliges Feuer",s="Am Boiling Pool suchen Jäger Brandpulveragave für eine heilige Flamme, die Arikara aus den Schluchten von Tausend Nadeln rufen soll.",h="Am Boiling Pool suchen Jäger Brandpulveragave für eine heilige Flamme, die Arikara aus den Schluchten von...",kw={"arikara","boiling pool","düsterwolkengipfel","die anhöhe der ältesten","brandpulveragave","magatha grimmtotem","motega feuermähne","hochheiliges feuer","tausend nadeln"},ang={["class:Shaman"]="Als Schamane seht Ihr, wie elementare Macht natürliche Pflanzen wie die Brandpulveragave durchdringt.",["faction:Horde"]="Als Mitglied der Horde besteht Ihr Prüfungen für die Ältesten und stärkt die Bande über Kalimdors trockene Ebenen hinweg.",["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr die untergetauchten, stacheligen Büschel der Brandpulveragave im gesamten Boiling Pool aufspüren.",["race:Tauren"]="Als Taurenjäger ehrt Ihr die Geister durch rituelle Jagd. Auf der Anhöhe der Ältesten stellt Ihr Euch als Teil eines Ritus zum Erwachsenwerden auch der Politik der Ältesten."},sec={{t="Den Geist entfachen",b="Motega Feuermähne bittet Euch, das hochheilige Feuer des Lebens vorzubereiten, eine uralte Flamme, die Arikara ruft. Die ungeheuerliche Windnatter lässt sich auf dem Schluchtenboden nicht aufspüren. Ihr müsst sie stattdessen zum Feuer locken. Gewöhnliches Anzündholz nährt die Flamme nicht. Sie braucht seltene Brandpulveragave, die an den brühend heißen Gewässern von Tausend Nadeln wächst."},{t="Der Boiling Pool",b="Brandpulveragave wächst nahe dem Boiling Pool, unterhalb des Düsterwolkengipfels. Ihr trotzt brühend heißem Wasser und Dampfelementaren, die durch die Nebel ziehen, um ihre stacheligen Blätter zu sammeln. Viele Büschel liegen unter der Wasseroberfläche. Das heiße Seewasser stellt jeden Jäger auf die Probe, der ausgesandt wird, um sie zu sammeln."},{t="Der Segen der Ältesten",b="Rohe Agave kann die Ritualfeuerschale nicht entzünden. Ihr tragt die geernteten Pflanzen aus den Ebenen zur Anhöhe der Ältesten in Donnerfels. Dort mahlt und verzaubert Magatha Grimmtotem die Blätter zu einem mächtigen Ritualpulver. Sie ist begierig darauf, dass jemand die rachsüchtige Bestie herausfordert."}},faq={{q="Was ist das hochheilige Feuer des Lebens?",a="Das hochheilige Feuer des Lebens ist eine Ritualflamme, mit der die rachsüchtige Geisterschlange Arikara beschworen wird. Ohne sie bleibt die Bestie verborgen und unerreichbar.",al={"hochheiliges feuer","was bewirkt das feuer","warum das hochheilige feuer entzünden"}},{q="Wo wächst Brandpulveragave?",a="Brandpulveragave wächst im und um den Boiling Pool in Tausend Nadeln, nahe dem Düsterwolkengipfel. Viele stachelige Pflanzen liegen unter dem heißen Seewasser.",al={"wo agave finden","brandpulveragave fundort","boiling pool agave"}},{q="Warum muss Magatha Grimmtotem die Agave verzaubern?",a="Rohe Brandpulveragave kann das hochheilige Feuer nicht entzünden. Magatha Grimmtotem verzaubert ihre Blätter zu Pulver, das die ruhende Flamme erwecken kann.",al={"warum magatha","wer verzaubert die agave","was macht magatha"}},{q="Wer ist Arikara?",a="Arikara ist eine Windnatter, die geboren wurde, um an jenen Rache zu üben, die schreckliche Verbrechen begehen. Motega Feuermähne sieht ihre Anwesenheit als unmittelbare Gefahr, der sich Jäger rasch stellen müssen.",al={"was ist arikara","arikara geschichte","windnatter boss"}},{q="Wer vergibt die Quest Hochheiliges Feuer?",a="Motega Feuermähne vergibt sie in Tausend Nadeln, nachdem Ihr ihm bei seinen ersten Aufgaben zur örtlichen Schlangenbedrohung geholfen habt.",al={"questgeber hochheiliges feuer","wo hochheiliges feuer beginnen"}},{q="Warum lächelt Magatha, als sie von Arikara hört?",a="Für Magatha Grimmtotems Lächeln wird keine Erklärung gegeben. Sie lächelt, nachdem sie Arikara als ein Wesen beschrieben hat, das geboren wurde, um abscheuliche Taten zu bestrafen, und Ihr fragt Euch, was sie denkt.",al={"magatha lächelt","magathas reaktion","warum lächelt magatha"}}},fx={["74be6845"]={q="Warum schickt Motega Feuermähne Euch aus, um Brandpulveragave zu sammeln?",a="Motega Feuermähne erkennt, dass Arikara eine tödliche Bedrohung ist, die unverzüglich beseitigt werden muss. Um die rachsüchtige Windschlange herbeizurufen und zur Strecke zu bringen, muss das Sacred Fire des Lebens entzündet werden, doch dies erfordert ein verzaubertes Pulver, das aus seltener Brandpulveragave hergestellt wird. Da Motega die Verzauberung nicht selbst durchführen kann, schickt er Euch aus, um das Kraut zu sammeln und es zu Magatha Grimmtotem nach Donnerfels zu bringen, damit das Ritual fortgesetzt werden kann.",al={"warum will motega das","motega feuermähne motiv","warum brandpulveragave beschaffen"}},["64ef07c3"]={q="Wofür wird die Brandpulveragave verwendet?",a="Brandpulveragave ist eine seltene Pflanze, die im Siedenden Tümpel in Tausend Nadeln gefunden wird. Sobald sie geerntet ist, verzaubert Magatha Grimmtotem die Agave, um ein heiliges Pulver herzustellen. Dieses Pulver ist notwendig, um das ruhende Sacred Fire des Lebens zu entfachen, die zeremoniellen Flammen, die benötigt werden, um die Geisterschlange Arikara aus ihrem Versteck zu rufen.",al={"zweck von brandpulveragave","wofür ist brandpulveragave gut","verwendung von brandpulveragave"}}},fp="11,127,19.339.0,16.271.0,20.258.1,32.148.0,31.147.0,45.134.0,15.181.0,32.123.0,49.172.0"}
P.entries["quest:5064"] = {n="Grimmtotemspionage",s="Am Freiwindposten schickt Euch Klippenbehüter Langhorn los, um die Pläne der Grimmtotem zu ergründen. Drei unbekannte Kuriere besuchten den Düsterwolkengipfel, und bewachte Notizen liegen verstreut in ihrem Dorf. Ihre Worte könnten die Taurensiedlungen in Tausend Nadeln bedrohen.",h="Am Freiwindposten schickt Euch Klippenbehüter Langhorn los, um die Pläne der Grimmtotem zu ergründen.",kw={"klippenbehüter langhorn","düsterwolkengipfel","freiwindposten","grimmtotem","geheimnotizen","spionage","tauren","tausend nadeln"},ang={["class:Rogue"]="Als Schurke könnt Ihr Euch verstohlen bewegen, um die drei Truhen von den Hängebrücken und aus den stark bewachten Gebäuden des Düsterwolkengipfels zu bergen.",["faction:Horde"]="Als Mitglied der Horde seid Ihr auf den Freiwindposten als wichtigen Durchgangspunkt im Süden Kalimdors angewiesen. Die Machenschaften der Grimmtotem auf dem Düsterwolkengipfel gefährden die anfälligen Versorgungslinien zwischen dem Brachland und Tanaris.",["race:Tauren"]="Als Tauren trifft Euch der Verrat der Grimmtotem in einer Gesellschaft, die auf Harmonie und Familienehre gründet. Ihre geheimen Treffen mit unbekannten Verschwörern bedrohen, was Cairne Bluthuf aufgebaut hat."},sec={{t="Augen im Wind",b="Der Freiwindposten klammert sich an hohe Felsnadeln, wo seine Verteidiger ihre feindseligen Vettern beobachten. Die Grimmtotem hegen seit Langem Groll gegen die Horde und halten sich in ihren Festungen auf dem Düsterwolkengipfel auf. Dann bemerkte Klippenbehüter Langhorn eine Veränderung. Im Laufe mehrerer Wochen trafen drei unbekannte Agenten ein und kamen heimlich mit den Clananführern zusammen. Er vermutet, dass sie Befehle überbrachten oder Bündnisse gegen die Präsenz von Donnerfels in der Schlucht vorschlugen."},{t="Infiltration des Düsterwolkengipfels",b="Der Düsterwolkengipfel ist ein befestigtes Dorf auf steilen Tafelbergen, die durch hölzerne Hängebrücken verbunden sind. Dichte Patrouillen feindseliger Krieger und Schamanen der Grimmtotem bewachen den Zugang. Langhorns Späher fanden die Nachrichten der Agenten in getrennten Truhen verschlossen, zwischen den zentralen Behausungen und auf den äußeren Felsvorsprüngen. Ihr durchquert die Siedlung, um alle drei Notizen zu bergen und die vertraulichen Worte des Clans unter seinen wachsamen Augen an Euch zu nehmen."},{t="Düstere Vorzeichen",b="Klippenbehüter Langhorn liest die drei Notizen, die Ihr zurückbringt, und die Sorgen am Freiwindposten wachsen. Die Nachrichten zeigen, dass sich die Grimmtotem für einen bevorstehenden Vorstoß mit auswärtigen Agenten abstimmen. Langhorn kennt den vollständigen Plan nicht. Er beginnt mit Vorbereitungen, um die Posten in der Schlucht vor plötzlichem Verrat zu schützen."}},faq={{q="Wer schickt Agenten zu Treffen mit den Grimmtotem?",a="Klippenbehüter Langhorn weiß nur, dass drei Agenten unbekannter Herkunft in den letzten Wochen den Düsterwolkengipfel besuchten. Ihre Hintermänner bleiben unbekannt, ihre Identität liegt in bewachten Notizen verborgen.",al={"wer besuchte die grimmtotem","geheimagenten der grimmtotem","wer schickte die notizen"}},{q="Wo liegt der Düsterwolkengipfel?",a="Der Düsterwolkengipfel liegt im Westen von Tausend Nadeln, südöstlich des Großen Aufzugs. Ein markierter Pfad mit einem blauen Totem führt die Steilhänge zum Dorf hinauf, wo Holzbrücken mehrere hohe Felsnadeln verbinden.",al={"wo liegt der düsterwolkengipfel","wie zum düsterwolkengipfel gelangen","zugang zum düsterwolkengipfel"}},{q="Warum sind die Grimmtotem anderen Tauren feindlich gesinnt?",a="Die Grimmtotem halten Tauren allen anderen Völkern für überlegen und lehnen Cairne Bluthufs Bündnis mit der Horde ab. Einige leben unter einem brüchigen Frieden in Donnerfels, während die Clans auf dem Düsterwolkengipfel sowohl der Horde als auch der Allianz offen feindlich gegenüberstehen.",al={"warum hassen die grimmtotem die horde","grimmtotem gegen donnerfels","sind die grimmtotem böse"}},{q="Wer vergibt die Quest Grimmtotemspionage?",a="Klippenbehüter Langhorn gibt Euch diesen Auftrag am Freiwindposten in Tausend Nadeln, nachdem Ihr Euch bei früheren Aufgaben für den Posten als zuverlässig erwiesen habt.",al={"wer startet grimmtotemspionage","questgeber für grimmtotemspionage"}},{q="Welche Quests müssen zuvor abgeschlossen werden?",a="Bevor Langhorn Euch diesen Auftrag anvertraut, schließt Ihr 'Message to Freiwindposten' und 'Pacify the Centaur' ab.",al={"voraussetzungen für grimmtotemspionage","wie grimmtotemspionage freischalten","questreihe grimmtotemspionage"}},{q="Was geschieht, wenn Ihr die drei Geheimnotizen abgebt?",a="Als Klippenbehüter Langhorn die drei Notizen liest, ist er erschüttert und nennt die Nachrichten düster. Er sagt, der Freiwindposten müsse seine Verteidigung gegen die Machenschaften der Grimmtotem vorbereiten.",al={"abschluss von grimmtotemspionage","was steht in den notizen"}}},fx={e48c00e3={q="Warum möchte Klippenbehüter Langhorn, dass dies erledigt wird?",a="Klippenbehüter Langhorn hat beobachtet, wie in den letzten Wochen drei mysteriöse Agenten den Düsterwolkengipfel besuchten, um sich heimlich mit dem Grimmtotem-Clan zu beraten. Die Grimmtotem sind berüchtigt für ihre Treulosigkeit und Unzuverlässigkeit, und ihre geheimen Treffen signalisieren, dass sich in den Nadeln ein stilles Komplott zusammenbraut. Langhorn muss diese bewachten Nachrichten abfangen, bevor das Schema, das sie aushecken, den Freiwindposten unvorbereitet treffen kann.",al={"warum grimtotem spying","klippenbehüter langhorn motive","warum die grimtotem ausspionieren"}},["219e0f02"]={q="Gegen wen werdet Ihr am Düsterwolkengipfel ausgesandt?",a="Ihr werdet direkt in das Herz des Düsterwolkengipfels geschickt, ein befestigtes Dorf, das vom Grimmtotem-Clan bewohnt wird. Im Gegensatz zu den friedlichen Stämmen unter Cairne Bluthuf bewacht dieser aggressive und geheimnisvolle Tauren-Clan sein Territorium über die Spitzen von Tausend Nadeln hinweg erbittert. Das Infiltrieren ihrer Siedlung bedeutet, ihren Wachen zu trotzen und ihre bewachten Truhen zu plündern, um herauszufinden, was sie verbergen.",al={"wer ist am düsterwolkengipfel","wen infiltriert ihr","ziel von grimtotem spying"}},c76c115b={q="Warum vertraut Klippenbehüter Langhorn diese Mission Euch an?",a="Ihr habt Eure Loyalität und Stärke bereits unter Beweis gestellt, indem Ihr den Freiwindposten unterstützt und Euch mit der örtlichen Zentaurenbedrohung auseinandergesetzt habt. Das Infiltrieren eines stark befestigten Grimmtotem-Plateaus ist eine heikle und tödliche verdeckte Operation, kein offener Angriff für die Standardwachen des Postens. Langhorn benötigt einen bewährten, fähigen Außenstehenden, der sich einschleichen, die Dokumente sichern und überleben kann.",al={"warum schickt langhorn dich","warum ich grimtotem spying"}}},fp="16,266,16.408.0,34.389.0,13.300.1,49.182.0,36.202.0,46.254.0,37.151.0,54.108.0,53.164.1"}
P.entries["quest:507"] = {n="Lord Aliden Perenolde",s="Krusk schickt Euch nach Norden zu Lord Aliden Perenoldes Herrenhaus am Lordameresee. Sobald Perenolde tot ist, kann Euch seine Geliebte Elysa vom Anhänger des Kriegshäuptlings erzählen.",h="Krusk schickt Euch nach Norden zu Lord Aliden Perenoldes Herrenhaus am Lordameresee.",kw={"alteracgebirge","dandreds senke","elysa","krusk","lord aliden perenolde","der lordameresee","syndikat","tarethas anhänger"},sec={{t="Der Herr des Syndikats",b="Nach Blackmoore's Legacy schickt Krusk Euch los, um Perenoldes Verderbtheit ein Ende zu setzen. Sein Herrenhaus steht bei Dandreds Senke, an den Ufern des Lordameresees im Norden. Sobald Perenolde tot ist, befragt seine Geliebte Elysa zu Tarethas Anhänger. Der Kriegshäuptling begehrt ihn."},{t="Eine verängstigte Geliebte",b="Elysa ist entsetzt, als Ihr sie erreicht. Sie ruft weinend, dass sie Eurem Volk niemals etwas Böses wollte. Perenolde habe sie gegen ihren Willen festgehalten, sagt sie, und sie fleht Euch an, sie zu verschonen."}},faq={{q="Wer schickt Euch los, um Lord Aliden Perenolde zu töten?",a="Nachdem Ihr Blackmoore's Legacy abgeschlossen habt, schickt Krusk Euch los, um Lord Aliden Perenolde zu töten.",al={"wer vergibt die quest lord aliden perenolde","wo gibt es die quest lord aliden perenolde"}},{q="Wo befindet sich Lord Aliden Perenolde?",a="Perenolde befindet sich im Obergeschoss seines Herrenhauses bei Dandreds Senke, an den Ufern des Lordameresees im Norden.",al={"wo ist perenolde","lord aliden perenolde standort","dandreds senke herrenhaus"}},{q="Wer ist Lord Aliden Perenolde?",a="Lord Aliden Perenolde führt das Syndikat an.",al={"wer ist aliden perenolde","perenolde geschichte"}},{q="Welchen Gegenstand sollt Ihr beschaffen, nachdem Ihr Perenolde getötet habt?",a="Sobald Perenolde tot ist, befragt seine Geliebte Elysa zu Tarethas Anhänger, den der Kriegshäuptling begehrt.",al={"welchen anhänger will thrall","was hat perenolde"}},{q="Was folgt auf diese Quest?",a="Taretha's Gift folgt als Nächstes in der Questreihe.",al={"was folgt auf lord aliden perenolde","nächste quest nach perenolde"}}},fp="21,159,25.250.0,21.165.1,44.84.0,39.99.0,29.42.0,59.100.0,28.39.0"}
P.entries["quest:508"] = {n="Tarethas Geschenk",s="Elysa gibt Tarethas Geschenk ab und bittet um Frieden. Nach dem Schritt mit Lord Aliden Perenolde bringt Ihr den Anhänger zu Krusk in Tarrens Mühle.",h="Elysa gibt Tarethas Geschenk ab und bittet um Frieden.",kw={"aliden perenolde","elysa","vorgebirge des hügellands","krusk","tarethas geschenk","tarethas halskette","tarrens mühle","thrall"},sec={{t="Der Anhänger",b="Elysa will keine Erinnerung an Lord Aliden Perenolde behalten. Sie gibt Euch den Anhänger und bittet nur darum, in Frieden gelassen zu werden. Er gehörte einst Taretha Foxton, Thralls Kindheitsfreundin. Ihr bringt ihn zu Krusk in Tarrens Mühle und gebt ihn damit den Orcs zurück."},{t="Krusks Urteil",b="Krusk findet es seltsam, dass der Kriegshäuptling für ein Schmuckstück solche Mühen auf sich nimmt. Er behauptet nicht, Thrall zu verstehen, folgt aber dennoch seinen Befehlen. Krusk lobt Eure Arbeit und erwartet, dass Thrall sich freuen wird, davon zu hören."}},faq={{q="Wer übergibt Tarethas Halskette?",a="Elysa gibt die Halskette ohne Widerrede ab. Sie will keine Erinnerung an Lord Aliden Perenolde behalten und bittet nur darum, in Frieden gelassen zu werden.",al={"wer gibt den anhänger","wo gibt es tarethas halskette","wer startet tarethas geschenk"}},{q="Wem muss die Halskette zurückgegeben werden?",a="Bringt sie zu Krusk, der in Tarrens Mühle wartet.",al={"wer gibt tarethas geschenk ab","wohin den anhänger bringen","krusks standort"}},{q="Wem gehörte der Anhänger?",a="Der Anhänger gehörte Taretha Foxton, Thralls Kindheitsfreundin. Seine Rückgabe gibt den Orcs ein Andenken an sie.",al={"warum will thrall den anhänger","bedeutung von taretha foxtons halskette","was ist tarethas geschenk"}},{q="Was kommt davor in der Questreihe?",a="Der Schritt mit Lord Aliden Perenolde kommt davor. Dies ist der letzte Teil der Questreihe.",al={"vorherige quest","voraussetzung für tarethas geschenk"}}},fp="14,139,11.235.0,15.231.1,34.125.0,38.44.0,21.114.0,36.95.0"}
P.entries["quest:5088"] = {n="Arikara",s="Von Donnerfels aus warnt Magatha Grimmtotem, dass Arikara womöglich Jagd auf High Chieftain Cairne Bluthuf macht. Sie schickt Abenteurer der Horde aus, um die uralte Windnatter an den Begräbnisnadeln von Tausend Nadeln zu beschwören und zu erschlagen.",h="Von Donnerfels aus warnt Magatha Grimmtotem, dass Arikara womöglich Jagd auf High Chieftain Cairne Bluthuf...",kw={"arikara","cairne bluthuf","düsterwolkengipfel","brandpulver","magatha grimmtotem","motega feuermähne","tausend nadeln","weißgipfelposten","windnatter"},ang={["class:Shaman"]="Als Schamane erkennt Ihr die Reibungen zwischen elementarem Ritual und politischer Intrige. Motega scheut davor zurück, Magathas spirituelle Autorität infrage zu stellen.",["faction:Horde"]="Als Mitglied der Horde zieht Ihr nach Tausend Nadeln, um jede Bedrohung für Cairne Bluthuf abzuwehren, den ehrwürdigen High Chieftain, dessen Schutz Ihr geschworen habt.",["race:Tauren"]="Als Tauren erkennt Ihr die Spannung zwischen den Riten der Ahnen und den politischen Veränderungen unter Cairne Bluthufs Führung. Die Grimmtotem sind in die Angelegenheit verstrickt."},sec={{t="Eine Bestie im Rauch",b="Magatha Grimmtotem verzaubert verfeinertes Brandpulver, um Arikara zu rufen. Sie warnt, dass sich uralte Traditionen der Tauren unter dem neuen Bündnis der Horde zu schnell gewandelt hätten. Diese Veränderungen, so sagt sie, hätten den wilden Windnattergeist zur Rache getrieben. Also schickt sie Euch nach Süden in den Canyon von Tausend Nadeln. Dort sollt Ihr das Pulver auf einen rituellen Scheiterhaufen inmitten der hochgelegenen Begräbnisstätten am Düsterwolkengipfel werfen."},{t="Zweifel am Weißgipfelposten",b="Nachdem Ihr Arikara auf der Begräbnisnadel erschlagen und ihre Haut erbeutet habt, bringt Ihr die Überreste zu Motega Feuermähne am Weißgipfelposten. Motega ist verwirrt. Er kann kaum glauben, dass ein Urgeist Groll gegen Cairne Bluthuf hegen würde. Doch er stellt seine Zweifel zurück, statt Magatha, die mächtigste Schamanin des Stammes, offen infrage zu stellen, und belohnt Euch für den Schutz des Häuptlings."}},faq={{q="Wer ist Arikara?",a="Arikara ist eine mächtige Windnatter, die auf dem Düsterwolkengipfel in Tausend Nadeln beschworen wird. Magatha sagt, die Abkehr von den überlieferten Lehren der Tauren habe die Bestie zur Rache getrieben.",al={"was ist arikara","arikara hintergrundgeschichte","wer ist die natter"}},{q="Warum will Magatha Grimmtotem Arikara tot sehen?",a="Magatha sagt, Arikara mache Jagd auf Cairne Bluthuf, den High Chieftain der Tauren. Sie schickt Euch aus, die Natter mit verzaubertem Brandpulver zu vernichten, bevor sie den Anführer von Donnerfels bedrohen kann.",al={"magathas beweggründe","warum arikara töten","warum arikara beschwören"}},{q="Wo befindet sich das heilige Feuer, um sie zu beschwören?",a="Das unentzündete heilige Feuer des Lebens befindet sich auf einer abgelegenen Felsnadel am Düsterwolkengipfel in Tausend Nadeln, wo die örtlichen Tauren ihre Toten bestatten.",al={"arikara aufenthaltsort","wo arikara beschwören","heiliges feuer des lebens standort"}},{q="Warum steht Motega Feuermähne der Jagd skeptisch gegenüber?",a="Magatha fürchtet, Arikara könnte Cairne nachstellen, und bittet Euch, Motega einen Beweis für die Jagd zu bringen. Motegas Reaktion folgt, wenn Ihr die Überreste abliefert.",al={"motegas reaktion","warum ist motega verwirrt","cairne arikara ergibt das sinn"}},{q="Ist Cairne tatsächlich durch Arikara in Gefahr?",a="Magatha sagt, sie fürchte, Arikara könnte Cairne nachstellen. Ihre Warnung fordert zum Handeln auf, belegt die Gefahr jedoch nicht unabhängig.",al={"wurde cairne wirklich gejagt","wollte arikara cairne","lügt magatha"}},{q="Welche Quest geht dieser in der Reihe voraus?",a="Diese Geschichte folgt auf „Sacred Fire“. Dort sammeln Abenteurer Brandpulveragaven am Boiling Pool in Tausend Nadeln, damit Magatha Grimmtotem sie zu Brandpulver verzaubern kann.",al={"arikara voraussetzung","quest vor arikara","sacred fire quest"}}},fx={["4b4aa583"]={q="Wofür ist Arikaras Schlangenhaut?",a="Die Schlangenhaut dient als unwiderlegbarer physischer Beweis dafür, dass der rachsüchtige Geist beschworen und getötet wurde. Magatha Grimmtotem schickt Euch, um ihre Überreste direkt zu Motega Feuermähne am Weißgipfelposten zu bringen, um zu zeigen, dass die vermeintliche Bedrohung, die den Großhäuptling Cairne Bluthuf verfolgte, ausgelöscht wurde.",al={"arikaras schlangenhaut","schlangenhaut arikara","warum arikara häuten"}}},fp="7,218,20.415.0,24.384.1,15.170.0,45.198.0,47.142.0,45.149.1,42.133.1,41.171.0"}
P.entries["quest:509"] = {n="Elixier der Pein",s="In Hillsbrad ist das Elixier der Pein Teil von Lydons Arbeit gegen die Lebenden und die Geißel. In Tarrens Mühle sammelt Ihr Morastschnauzenkappen für die Experimente der Royal Apothecary Society unter Fürstin Sylvanas.",h="In Hillsbrad ist das Elixier der Pein Teil von Lydons Arbeit gegen die Lebenden und die Geißel.",kw={"apotheker lydon","elixier der pein","hillsbrad","mudsnout blossom","nethander-siedlung","neue seuche","royal apothecary society","tarrens mühle"},ang={["faction:Horde"]="Als Abgesandter der Horde in Tarrens Mühle unterstützt Ihr Eure verbündeten Verlassenen und werdet dabei mit ihren beunruhigenden chemischen Experimenten konfrontiert.",["profession:Herbalism"]="Als Kräuterkundiger oder Sammler erkennt Ihr den Mudsnout Blossom vielleicht als seltenen, außergewöhnlich giftigen Pilz, der auf unbestelltem Boden wächst, den Gnolle durch ihre Besiedlung verunreinigt haben.",["race:Undead"]="Als Verlassener helft Ihr der Royal Apothecary Society, Lordaeron gegen die Menschheit und den Lich King zu verteidigen."},sec={{t="Eine Seuche entsteht",b="Die Geißel verwüstet den Norden, während sich die Allianz an Städte wie Süderstade klammert. In Tarrens Mühle entwickelt Apotheker Lydon auf Befehl der Dunklen Fürstin eine Seuche gegen beide. Er findet Alchemie mühsam, sammelt aber dennoch starke organische Gifte aus dem Umland. Daraus braut er Elixiere, die die Vernichtung von Sylvanas' Feinden beschleunigen sollen."},{t="Die Felder der Nethander-Siedlung",b="Die Nethander-Siedlung liegt südlich von Tarrens Mühle und östlich des Flusses. Das verlassene Menschengehöft ist von bösartigen Mudsnout-Gnollen überrannt, und zwischen Unrat und vernachlässigtem Erdreich wachsen Morastschnauzenkappen. Diese übelriechenden Pilze enthalten konzentrierte organische Gifte, die von der Royal Apothecary Society geschätzt werden. Ihr könnt Euch durch die Gnollrudel kämpfen oder leise an ihren baufälligen Lagern vorbeischleichen, um die Pilze zu sammeln."}},faq={{q="Wer ist Apotheker Lydon?",a="Apotheker Lydon ist ein Alchemist der Royal Apothecary Society, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Er dient Fürstin Sylvanas Windläufer, verfeinert tödliche Mischungen und entwickelt eine Seuche, um die Lebenden und die Geißel zu besiegen.",al={"lydon","wer ist lydon","apotheker lydon hintergrund"}},{q="Wofür werden Morastschnauzenkappen verwendet?",a="Morastschnauzenkappen sind übelriechende Pilze aus der Nethander-Siedlung. Lydon nutzt ihre starken natürlichen Gifte, um das Elixier der Pein zu brauen, als Teil der Forschung der Verlassenen zur chemischen und biologischen Kriegsführung.",al={"morastschnauzenkappen","wofür sind die pilze","verwendung der kappen"}},{q="Wo liegt die Nethander-Siedlung?",a="Die Nethander-Siedlung ist ein überwuchertes Gehöft südlich von Tarrens Mühle und östlich des großen Flusses, der an Süderstade vorbeifließt. Aggressive Mudsnout-Gnollen haben das Gehöft für sich beansprucht und bewachen die Felder, auf denen die Pilze wachsen.",al={"lage der nethander-siedlung","wo ist die nethander-siedlung","wo sind die gnolle"}},{q="Warum wollen die Verlassenen eine neue Seuche erschaffen?",a="Fürstin Sylvanas und die Verlassenen suchen eine Waffe, um sowohl die Geißel als auch die feindlichen lebenden Völker der Allianz auszulöschen. Die Royal Apothecary Society arbeitet daran, mit einer eigenen Seuche die Souveränität und das Überleben der Verlassenen in Lordaeron zu sichern.",al={"warum eine seuche erschaffen","grund für die seuche der verlassenen","sylvanas seuche"}},{q="Warum beklagt sich Lydon darüber, diese Elixiere brauen zu müssen?",a="Lydon ist überdrüssig und morbide; er bemerkt, dass Menschen und Geißel einander bereits ohne Hilfe abschlachten. Dennoch gehorcht er Fürstin Sylvanas' Wunsch, ihre gegenseitige Vernichtung zu beschleunigen, und braut weiter tödliche Mischungen.",al={"lydons einstellung","warum ist lydon zynisch"}},{q="Was geschieht nach dem Sammeln der Kappen?",a="Nachdem Lydon die Morastschnauzenkappen erhalten hat, braut er die giftige Mischung. Bald benötigt er weitere Zutaten und Feldversuche, um das Elixier so tödlich wie möglich zu machen.",al={"nächste quest","was folgt auf elixier der pein"}}},fx={["744a331d"]={q="Wer bewacht die Morastschnauzenkappen in der Nethander-Siedlung?",a="Die Felder der Nethander-Siedlung wurden von Morastschnauzen-Gnollen überrannt. Diese schmutzigen Kreaturen züchten oder bewachen erbittert die beißend riechenden Pilze, die auf dem Gehöft wachsen, was jeden Sammelgang zu einem gefährlichen Unterfangen in ihrem beanspruchten Territorium macht.",al={"wer bewacht morastschnauzenkappen","feinde in der nethander-siedlung","morastschnauzen-gnolle"}}},fp="15,206,22.353.0,29.397.0,24.228.0,36.200.0,33.213.0,48.241.0,59.221.0,43.162.0"}
P.entries["quest:510"] = {n="Furchteinflößende Pläne",s="Laut den Papieren des Syndikats sollen Vorräte bald Süderstade erreichen, wo Magistrat Henry Maleb sie erwartet.",h="Laut den Papieren des Syndikats sollen Vorräte bald Süderstade erreichen, wo Magistrat Henry Maleb sie...",kw={"alteracgebirge","furchteinflößende pläne","magistrat henry maleb","süderstade","syndikat","syndikatsdokumente"},sec={{t="Die Vorratsliste",b="Die Papiere des Syndikats führen Nahrung, Waffen und Kleidung auf. Sie fordern auch Masken, Öl und Gift an. Die Vorräte werden bald für ein wichtiges Unternehmen gegen Süderstade benötigt. Magistrat Henry Maleb soll sie dort erhalten."},{t="Malebs Urteil",b="Magistrat Henry Maleb findet die Dokumente beunruhigend. Ihr Wortlaut und die vergangenen Taten des Syndikats führen ihn zu einem düsteren Urteil: Die Halsabschneider sind gegen die Stadt in den Krieg gezogen."}},faq={{q="Was steht in den Dokumenten des Syndikats?",a="Die Dokumente führen Nahrung, Waffen und Kleidung sowie Masken, Öl und Gift auf. Ihnen zufolge werden die Vorräte bald für ein wichtiges Unternehmen gegen Süderstade benötigt.",al={"was sind die furchteinflößenden pläne","inhalt der syndikatsdokumente","was steht in den plänen"}},{q="Wer sollte diese Pläne sehen?",a="Magistrat Henry Maleb in Süderstade.",al={"wem die pläne bringen","furchteinflößende pläne abgeben","wohin gehören die pläne"}}},fp="16,108,15.222.0,15.175.1,36.167.0,27.37.0"}
P.entries["quest:511"] = {n="Verschlüsselter Brief",s="Unter den Papieren des Syndikats ist ein Brief unlesbar. Ihr bringt ihn zu Meister der Lehren Dibbs in Süderstade.",h="Unter den Papieren des Syndikats ist ein Brief unlesbar.",kw={"alterac","verschlüsselter brief","vorgebirge des hügellands","meister der lehren dibbs","süderstade","dokumente des syndikats"},sec={{t="Ein unlesbarer Brief",b="Unter den Dokumenten des Syndikats ist ein Brief in einer Geheimschrift verfasst, die niemand lesen kann. Ihr bringt ihn zu Meister der Lehren Dibbs in Süderstade."},{t="Was Dibbs davon hält",b="Meister der Lehren Dibbs hat diese Art von Geheimschrift noch nie gesehen. Er muss noch viel lernen, bevor er sie verstehen kann."}},faq={{q="Woher stammt der Brief?",a="Der Brief ist einer von mehreren auf einem Tisch zwischen den Dokumenten des Syndikats, und sein Inhalt lässt sich nicht entziffern.",al={"herkunft des briefs","wo brief finden","verschlüsselter brief anfang"}},{q="Zu wem wird der Brief gebracht?",a="Ihr bringt den Brief zu Meister der Lehren Dibbs in Süderstade.",al={"wer liest den brief","wer kann ihn entziffern","dibbs brief"}}},fp="16,101,24.129.0,22.115.1,32.101.0,27.54.0"}
P.entries["quest:512"] = {n="Tod der Edlen",s="In Süderstade fürchtet Magistrat Henry Maleb, dass das Syndikat den Untergang der Stadt plant. Er schickt Euch nach Norden zu den Ruinen von Strahnbrad im Alteracgebirge, wo er das Hauptquartier seiner Anführer vermutet.",h="In Süderstade fürchtet Magistrat Henry Maleb, dass das Syndikat den Untergang der Stadt plant.",kw={"alteracgebirge","siegelring von alterac","henry maleb","tod der edlen","süderstade","strahnbrad","syndikat"},sec={{t="Jagd auf die Anführer des Syndikats",b="Nach Foreboding Plans will Magistrat Henry Maleb die Anführer des Syndikats niederstrecken lassen, bevor ihre Pläne Wirklichkeit werden. Seine Halsabschneider unterstehen ehemaligen Adligen aus Alterac, die sich unter gewöhnlichen Agenten verbergen könnten. Ihre Siegelringe verraten sie. Maleb bittet Euch, ihm sieben Siegelringe von Alterac nach Süderstade zu bringen.\n\nEr glaubt, dass das Syndikat sein Hauptquartier in den Ruinen von Strahnbrad eingerichtet hat, im Norden des Alteracgebirges."},{t="Malebs Hoffnung",b="Maleb glaubt, dass das Syndikat ohne seinen Adel nicht mehr entschlossen handeln könnte. Seiner Ansicht nach blieben nur gewöhnliche Schläger übrig."}},faq={{q="Wer schickt Euch nach Strahnbrad?",a="Magistrat Henry Maleb in Süderstade schickt Euch nach Norden, um gegen die Anführer hinter dem Syndikat vorzugehen.",al={"questgeber","wer vergibt tod der edlen","henry maleb quest"}},{q="Wo befinden sich die Adligen des Syndikats?",a="Maleb glaubt, dass das Syndikat sein Hauptquartier in den Ruinen von Strahnbrad eingerichtet hat, im Norden des Alteracgebirges.",al={"wohin gehen","strahnbrad standort","adlige des syndikats standort"}},{q="Wie könnt Ihr die Adligen von gewöhnlichen Mitgliedern des Syndikats unterscheiden?",a="Die Adligen verbergen sich möglicherweise unter gewöhnlichen Agenten des Syndikats, doch ihre Siegelringe verraten sie.",al={"adlige erkennen","wer lässt ringe fallen","woran adlige erkennen"}},{q="Was kommt in der Questreihe davor?",a="Foreboding Plans kommt davor.",al={"vorausgesetzte quest","vorherige quest","tod der edlen vorquest"}}},fp="12,204,31.420.0,12.131.1,28.99.0,39.112.0,66.90.0,36.35.0"}
P.entries["quest:513"] = {n="Elixier der Pein",s="In Unterstadt wartet das Elixier der Pein auf seine letzte Behandlung. Apotheker Lydon schickt sein frisch zerstampftes Morastschnauzengemisch aus Tarrens Mühle zu Apothekermeister Faranell, der ein Kolloid der Fäulnis hinzufügen muss. Die Königliche Apothekervereinigung entwickelt eine neue Seuche für die Verlassenen.",h="In Unterstadt wartet das Elixier der Pein auf seine letzte Behandlung.",kw={"das apothekarium","apotheker lydon","kolloid der fäulnis","elixier der pein","apothekermeister faranell","morastschnauzengemisch","neue seuche","unterstadt"},ang={["faction:Horde"]="Als Mitglied der Horde seid Ihr darauf angewiesen, dass das Gebiet der Verlassenen den Norden Lordaerons sichert. Die Forschung der Königlichen Apothekervereinigung hilft, diese verwundbaren Grenzen zu verteidigen.",["race:Undead"]="Als Untoter helft Ihr mit jeder Lieferung rohen Pflanzenmaterials an Faranell, die Verlassenen zu verteidigen und ihr Überleben gegen die Lebenden und die Geißel zu sichern."},sec={{t="Ein Kurier zur Hauptstadt",b="Die Königliche Apothekervereinigung schickt Entdeckungen regionaler Forscher zur Veredelung nach Unterstadt. In Tarrens Mühle hat Apotheker Lydon einheimische Morastschnauzenkappen zu einem Gemisch zerstampft. Nur das Labor der Hauptstadt verfügt über die fortschrittlichen Reagenzien, die nötig sind, um seinem Werk tödliche Wirkung zu verleihen."},{t="Die Eile des Meisters",b="Apothekermeister Faranell arbeitet im Apothekarium unter Druck. Die Geißel droht aus dem Norden, während aggressive menschliche Bevölkerungen aus dem Süden vordringen. Fürstin Sylvanas Windläufer hat eine wirksame neue Seuche gefordert, um die Verlassenen zu verteidigen. Lydons Gemisch könnte Faranell den Durchbruch bei der Giftentwicklung ermöglichen, den die Dunkle Fürstin erwartet."}},faq={{q="Warum muss ich das Morastschnauzengemisch nach Unterstadt bringen?",a="Apotheker Lydon in Tarrens Mühle fehlen die Reagenzien, um diese Phase seines Experiments abzuschließen. Apothekermeister Faranell verfügt im Apothekarium über ein Kolloid der Fäulnis und muss das Morastschnauzengemisch damit behandeln, bevor die Mischung weiterentwickelt werden kann.",al={"warum nach unterstadt","morastschnauzengemisch ziel","warum zu faranell bringen"}},{q="Wer ist Apothekermeister Faranell?",a="Apothekermeister Faranell leitet die Königliche Apothekervereinigung von seinem Labor tief in Unterstadt aus. Er beaufsichtigt die bedeutenden chemischen und alchemistischen Forschungen der Verlassenen und untersteht direkt Fürstin Sylvanas Windläufer.",al={"wer ist faranell","apothekermeister faranell hintergrund","apothekarium leiter"}},{q="Was ist die neue Seuche, von der die Apotheker ständig sprechen?",a="Die neue Seuche ist ein Projekt der Verlassenen auf Befehl von Fürstin Sylvanas. Sie soll sowohl die Lebenden als auch die untote Geißel vernichten und den Verlassenen eine absolute Waffe gegen ihre Feinde geben.",al={"was ist die neue seuche","seuchenprojekt der verlassenen","warum eine neue seuche entwickeln"}},{q="Wo finde ich Apothekermeister Faranell?",a="Faranell lebt im Apothekarium, dem südwestlichen Viertel von Unterstadt. Das Viertel widmet sich der Alchemie, dem Brauen von Giften und chirurgischen Experimenten.",al={"wo ist faranell","faranell standort","apothekarium standort"}},{q="Was versucht Apotheker Lydon herzustellen?",a="Lydon stellt das Elixier der Pein her, ein hochwirksames Gift, das aus der Pflanzenwelt von Hillsbrad und Fäulnismitteln gebraut wird. Es soll die Wirksamkeit neuer Stämme im Feld beweisen.",al={"was stellt lydon her","elixier der pein zweck","lydons experiment"}},{q="Warum hat es die Königliche Apothekervereinigung so eilig?",a="Die Verlassenen sind von allen Seiten bedroht. Die Geißel aus Northrend droht sie zu überrennen, während menschlicher Widerstand aus dem Süden sie bedrängt. Sie brauchen dringend eine entscheidende biologische Waffe.",al={"warum die eile","faranell beschäftigt","unterstadt bedrohung"}}},fx={c9de6b5a={q="Warum schickt Apotheker Lydon Euch, anstatt selbst zu gehen?",a="Apotheker Lydon ist im Vorgebirge des Hügellands stationiert und führt wichtige Feldforschung für die Königliche Apothekergesellschaft durch. Die Vorbereitung toxischer Verbindungen und die Überwachung lokaler Entwicklungen erfordern seine ständige Aufmerksamkeit in Tarrens Mühle, daher müssen vertrauenswürdige Kuriere seine Rohmischungen zur Spezialveredelung in die Unterstadt bringen.",al={"warum schickt ihr mich","warum geht lydon nicht selbst in die unterstadt","warum kann lydon das nicht ausliefern"}}},fp="15,281,24.279.0,20.327.0,62.237.0,34.220.0,56.191.0,44.154.0,42.170.0,46.193.0"}
P.entries["quest:514"] = {n="Brief an Stormpike",s="In Süderstade vertraut Euch Meister der Lehren Dibbs einen verschlüsselten Brief für Eisenschmiede an. Er hofft, dass Ausgrabungsleiter Sturmlanze ihn lesen kann.",h="In Süderstade vertraut Euch Meister der Lehren Dibbs einen verschlüsselten Brief für Eisenschmiede an.",kw={"verschlüsselter brief","hall of explorers","eisenschmiede library","brief an stormpike","meister der lehren dibbs","ausgrabungsleiter sturmlanze","süderstade"},sec={{t="Ein Kollege in Eisenschmiede",b="Dibbs schickt Euch nach Eisenschmiede, um Ausgrabungsleiter Sturmlanze zu finden. Er befindet sich in der Library in der Hall of Explorers. Sagt ihm, dass Dibbs Euch geschickt hat, und zeigt ihm den Brief. Dibbs glaubt, dass niemand nördlich der Schwarzfelsspitze ihn besser lesen kann als Sturmlanze."},{t="Sturmlanzes Begrüßung",b="Als Sturmlanze erfährt, dass Dibbs Euch geschickt hat, fragt er, wie es dem alten Bücherwurm geht. Verschlüsselung sei sein Spezialgebiet, sagt er, und beginnt dann, den Brief zu untersuchen."}},faq={{q="Wer schickt Euch mit dem Brief nach Eisenschmiede?",a="Meister der Lehren Dibbs in Süderstade schickt Euch mit dem Brief nach Eisenschmiede. Er hofft, dass sein dortiger Kollege ihn entschlüsseln kann.",al={"wer hat mir diese quest gegeben","questgeber","wer startet brief an stormpike"}},{q="Wo befindet sich Ausgrabungsleiter Sturmlanze?",a="Ausgrabungsleiter Sturmlanze befindet sich in der Library in der Hall of Explorers in Eisenschmiede.",al={"sturmlanze standort","wo ist sturmlanze","ausgrabungsleiter sturmlanze library"}},{q="Warum glaubt Dibbs, dass Sturmlanze den Brief lesen kann?",a="Dibbs glaubt, dass Sturmlanze den Brief lesen kann, wenn es irgendjemand nördlich der Schwarzfelsspitze kann.",al={"warum sturmlanze","warum zu sturmlanze schicken","sturmlanze verschlüsselung"}}},fp="19,127,24.241.0,19.148.1,43.115.0,38.82.0,53.84.0"}
P.entries["quest:5147"] = {n="GESUCHT: Arnak Grimmtotem",s="Am Freiwindposten fordert ein Kopfgeld der Horde den Tod von Arnak Grimmtotem. Die Behörden suchen den gewalttätigen Verbannten der Grimtotem wegen Mordes und Entführung auf den Tafelbergen über der Schlucht.",h="Am Freiwindposten fordert ein Kopfgeld der Horde den Tod von Arnak Grimmtotem.",kw={"arnak grimmtotem","kopfgeld","klippenbehüter langhorn","düsterwolkengipfel","freiwindposten","lakota windweise","ausgestoßener","tausend nadeln"},ang={["faction:Horde"]="Der Freiwindposten ist die Lebensader der Horde durch Tausend Nadeln. Indem Ihr Abtrünnige auf dem Düsterwolkengipfel ausschaltet, sichert Ihr die Höhen entlang der Schluchtsohle.",["race:Tauren"]="Als Tauren, der Cairne Bluthuf treu ergeben ist, könnt Ihr die Jagd nach Arnak als Stammesjustiz betrachten. Er ist ein Verwandtenmörder, der die Traditionen der Tauren durch die Entführung von Lakota Windweise entehrt hat."},sec={{t="Ein grausiges Verbrechen",b="Die Tauren der Horde und die zurückgezogen lebenden Grimtotem liegen seit Langem im Streit. Arnak verschärfte diesen Zwist, indem er einen Tauren ermordete und dessen Schwester Lakota Windweise entführte. Als Ausgestoßener gebrandmarkt, erregte er die Aufmerksamkeit von Klippenbehüter Langhorn am Freiwindposten. Langhorn bewilligte ein öffentliches Kopfgeld, das Arnaks Tod fordert."},{t="Düsterwolkengipfel",b="Arnak hat auf den hohen nördlichen Tafelbergen des Düsterwolkengipfels Zuflucht gesucht. Nahe dem Eingang zu den Hügeln der Klingenhauer erstrecken sich Lager der Grimtotem über die hohen Felsen, verbunden durch Seilbrücken. Lakota Windweise wird dort gefangen gehalten und wartet auf Rettung. Wer sie erreichen will, muss die Brücken der Grimtotem überqueren."}},faq={{q="Wer ist Arnak Grimmtotem?",a="Arnak Grimmtotem ist ein ausgestoßener Tauren, der einen Tauren ermordet und Lakota Windweise entführt hat. Wegen seiner Verbrechen setzte der Freiwindposten ein Kopfgeld auf ihn aus.",al={"wer ist arnak","arnak grimmtotem hintergrund","wer ist der gesuchte tauren"}},{q="Wo ist Arnak Grimmtotem zu finden?",a="Arnak befindet sich hoch oben auf den nördlichen Tafelbergen des Düsterwolkengipfels in Tausend Nadeln. Sucht den gewundenen Pfad südlich des Großen Aufzugs auf und überquert dann die hohen Holzbrücken in Richtung der Hügel der Klingenhauer.",al={"wo ist arnak","arnak grimmtotem fundort","arnak finden"}},{q="Wer ist Lakota Windweise?",a="Lakota Windweise ist eine Tauren, die Arnak auf dem Düsterwolkengipfel gefangen hält. Arnak ermordete ihren Bruder bei ihrer Entführung, und sie sitzt auf dem Tafelberg fest, bis ihm das Handwerk gelegt wird.",al={"wer ist lakota","lakota windweise geschichte"}},{q="Wer zahlt das Kopfgeld aus?",a="Klippenbehüter Langhorn am Freiwindposten verwaltet das Kopfgeld. Er belohnt Reisende, die Arnaks abgetrennten Huf als Beweis dafür bringen, dass der abtrünnige Tauren seiner gerechten Strafe zugeführt wurde.",al={"arnak bei wem abgeben","kopfgeld abgeben","klippenbehüter langhorn belohnung"}},{q="Arbeitet Arnak offiziell für den Stamm der Grimtotem?",a="Der Steckbrief bezeichnet Arnak als Ausgestoßenen und zeigt damit, dass er außerhalb des Stammesrechts handelte. Er hat in der Festung der Grimtotem auf dem Düsterwolkengipfel Zuflucht gesucht.",al={"gehört arnak zu den grimtotem","arnak stammesstatus"}},{q="Welcher Beweis ist nötig, um das Kopfgeld einzufordern?",a="Jäger müssen Arnak’s Hoof abtrennen und zu Klippenbehüter Langhorn am Freiwindposten bringen, um Arnaks Tod zu bestätigen und das Kopfgeld zu erhalten.",al={"was zu klippenbehüter langhorn bringen","arnak beweis","arnaks hoof"}}},fx={f1e95c6b={q="Warum setzt der Freiwindposten ein Kopfgeld auf Arnak Grimmtotem aus?",a="Klippenbehüter Langhorn und die Verteidiger des Freiwindpostens haben das Kopfgeld ausgesetzt, um Arnaks Verbrechen im Canyon ein Ende zu setzen. Als Ausgestoßener selbst unter seinem eigenen Volk gebrandmarkt, beging Arnak den brutalen Mord an einem Mit-Tauren und entführte die Schwester des Opfers, Lakota Windweise. Da die Sicherheit von Reisenden und lokalen Stämmen durch seine ungezügelte Gewalt bedroht ist, möchte der Freiwindposten ihn dauerhaft beseitigt wissen, um die Gerechtigkeit in Tausend Nadeln wiederherzustellen.",al={"kopfgeld arnak grimtotem warum","warum arnak töten","warum wird arnak gesucht"}}},fp="24,175,16.320.0,18.307.0,23.146.0,35.190.0,23.182.0,29.172.0,52.145.0,43.130.0"}
P.entries["quest:515"] = {n="Elixier der Pein",s="In Unterstadt bereitet Faranell Lydons Mischung für einen tödlichen Zweck vor. Die Königliche Apothekervereinigung braucht Reagenzien von der Küste und alchemistische Tränke, um ihre neue Seuche einsatzbereit zu machen.",h="In Unterstadt bereitet Faranell Lydons Mischung für einen tödlichen Zweck vor.",kw={"daggerspine","elixier der pein","faranell","lydon","mudsnout","tarrens mühle","torn fin","umpi","unterstadt"},ang={["faction:Horde"]="Tarrens Mühle ist ständig in Grenzscharmützel mit der Allianz aus Süderstade verwickelt. Lydons Giftexperimente sollen das regionale Machtgleichgewicht verschieben.",["race:Undead"]="Jedes verfeinerte Reagenz bringt die Königliche Apothekervereinigung der Erfüllung von Lady Sylvanas' Wunsch nach einer ultimativen Waffe gegen die Lebenden näher."},sec={{t="Ein Kolloid der Fäulnis",b="Apotheker Lydon schickte seine Mischung aus Mudsnout Blossom aus der von Gnollen beherrschten Nethander-Siedlung ins Apothekarium in Unterstadt. Apothekermeister Faranell führt die Königliche Apothekervereinigung an und erkannte sofort das finstere Potenzial der Mischung. Ihre giftigen Eigenschaften gefielen ihm, also fügte er sein eigenes Kolloid der Fäulnis hinzu. Dann benannte er die Katalysatoren, die daraus eine Waffe machen konnten."},{t="Katalysatoren von der Küste",b="Um die verseuchenden Wirkstoffe der Mischung zu aktivieren, braucht Lydon in Tarrens Mühle ganz bestimmte Reagenzien. Faranell verlangt einen stärkenden Trunk aus starkem Trollblut, um die chemische Reaktion zu nähren und zu stabilisieren. Außerdem braucht er organische Bestandteile von Hillsbrads Südküste: Schuppen der schlangenartigen Daggerspine-Naga und Augen der an der Küste lebenden Torn-Fin-Murlocs."},{t="Grausamkeit in Tarrens Mühle",b="Zurück in Tarrens Mühle verbringt Lydon die Wartezeit damit, sein untotes Versuchsobjekt Umpi zu vergiften, mit Krankheiten anzustecken und anschließend wiederzubeleben. Faranells angereicherte Mischung und die Katalysatoren von der Küste bringen Lydon der Vollendung eines qualvollen neuen Fäulnisstamms für Hillsbrads lebende Siedlungen näher."}},faq={{q="Warum braucht die Seuche ein stärkendes Trollblutelixier?",a="Stärkendes starkes Trollblut erhält und nährt aggressive biologische Wirkstoffe und hilft ihnen, rasch zu mutieren. Seine Eigenschaften halten die giftigen Kulturen lange genug am Leben, damit sie mit den anderen Geweben reagieren können.",al={"warum trollblut","zweck von starkem trollblut","trollblutelixier seuche"}},{q="Wo findet man Daggerspine-Schuppen?",a="Daggerspine-Schuppen stammen von feindseligen Naga an Hillsbrads östlichen Stränden, entlang der Küste östlich von Süderstade.",al={"daggerspine-schuppen fundort","wo sind nagaschuppen","woher schuppen bekommen"}},{q="Woher bekommt man Fetzenflossenaugen?",a="Fetzenflossenaugen stammen von Murlocstämmen an Hillsbrads Westküste, gleich westlich von Süderstade.",al={"fetzenflossenauge fundort","wo sind torn-fin-murlocs","murlocaugen hillsbrad"}},{q="Wer ist Umpi?",a="Umpi ist der Frosch, den Apotheker Lydon als seine Assistentin in Tarrens Mühle hält. In seinen Mußestunden erprobt Lydon tödliche Gifte und Krankheiten an ihr und erweckt sie anschließend wieder zum Leben.",al={"wer ist umpi","umpi hillsbrad","lydons assistentin umpi"}},{q="Warum ist Apothekermeister Faranell an diesem örtlichen Vorhaben beteiligt?",a="Apothekermeister Faranell führt die Königliche Apothekervereinigung an und beaufsichtigt die Erforschung biologischer Wirkstoffe und Seuchen. Apotheker im Außendienst wie Lydon schicken vielversprechende Entdeckungen zur Verfeinerung und Genehmigung an Faranell in Unterstadt.",al={"warum faranell","rolle von apothekermeister faranell","anführer der königlichen apothekervereinigung"}},{q="Was ist die Morastschnauzenmixtur?",a="Lydons Morastschnauzenmixtur ist ein unverfeinertes giftiges Gemisch aus Morastschnauzenkappen, widerlichen Pilzen aus der von Gnollen heimgesuchten Nethander-Siedlung im Vorgebirge des Hügellands. Als Lydon ihre ungewöhnliche Virulenz erkannte, schickte er sie nach Unterstadt, wo Faranell zerfallene Kolloide hinzufügte, um einen tödlicheren Ansteckungsstoff zu schaffen.",al={"morastschnauzenmixtur","gnollgift","morastschnauzengemisch"}}},fx={["45c57bb0"]={q="Wofür sind die Säbelflossenschuppen und Fetzenflossenaugen?",a="Apothekermeister Faranell gibt an, dass sowohl die reptilienartigen Schuppen der Säbelflossen-Naga als auch die Augen der Fetzenflossen-Murlocs notwendige Reagenzien sind, um die kontaminierenden Wirkstoffe zu aktivieren, die in der Morastschnauzenmixtur schlummern. Zusammen mit seinem eigenen Kolloid des Verfalls und dem wiederherstellenden Trollblut liefern diese aquatischen Ernten von der Küste den reaktiven Katalysator, den Apotheker Lydon benötigt, um seine tödliche Verbindung zum Leben zu erwecken.",al={"verwendung von säbelflossenschuppen","warum fetzenflossenaugen benötigt","warum säbelflossenschuppen"}},ff4494e7={q="Wer sind die Säbelflossen und Fetzenflossen entlang der Küste?",a="Die südliche Küstenlinie des Vorgebirges des Hügellands wurde von feindseligen aquatischen Stämmen überrannt, die Süderstade flankieren. Im Osten sind die Säbelflossen-Naga von Das große Meer aus an die Strände vorgedrungen und beanspruchen das Territorium mit schlangenartiger Wildheit. Im Westen wohnen die Fetzenflossen-Murlocs, Plünderer, die an den Untiefen festhalten. Ihre Biologie macht sie zu unwissentlichen Quellen für Reagenzien für die alchemistische Kriegsführung der Verlassenen.",al={"hillsbrad naga murlocs","wer sind die säbelflossen","wer sind die fetzenflossen"}}},fp="15,186,18.366.0,24.346.0,22.295.1,63.203.0,39.109.0,37.92.0,12.168.0,65.242.0,29.297.0"}
P.entries["quest:5151"] = {n="Hyperkondensator-Dingsda",s="In Tausend Nadeln wartet Wizlo Lagerputzer nach einem Zentaurenüberfall am Weißgipfelposten. Er braucht seine Erfindung aus den Trümmern zurück, wo ein eingesperrter Panther sie um den Hals trägt.",h="In Tausend Nadeln wartet Wizlo Lagerputzer nach einem Zentaurenüberfall am Weißgipfelposten.",kw={"zentauren karawane","wütender panther","gobliningenieurskunst","hyperkondensator-dingsda","pantherkäfigschlüssel","tausend nadeln","weißgipfelposten","wizlo lagerputzer"},ang={["class:Hunter"]="Der wütende Panther in der zerstörten Karawane ist eine furchterregende Bestie, wild genug, um eine ganze Kriegsschar von Zentaurenmarodeuren in Angst zu versetzen.",["faction:Horde"]="Vom Weißgipfelposten aus bekämpfen Späher und Reisende der Horde die räuberischen Zentaurenclans, die die Wege durch das zentrale Kalimdor bedrohen.",["profession:Engineering"]="Wizlos verzweifelte Jagd nach einer Erfindung, an deren Zweck er sich nicht recht erinnern kann, zeigt die chaotische Vorgehensweise der Gobliningenieurskunst voller Versuch und Irrtum."},sec={{t="Überfall in den Nadeln",b="Unter den Sandsteinnadeln von Tausend Nadeln bewachen Zentauren den Schluchtboden. Knapp nördlich vom Weißgipfelposten überrannten sie eine Handelskarawane, töteten die Reisenden und plünderten die Wagen. Nur Wizlo Lagerputzer, ein Goblintüftler, entkam. Er humpelte zurück in Sicherheit."},{t="Ein ungewöhnlicher Wächter",b="Die Zentauren ließen einen zerstörten Wagen unberührt, obwohl sie fast jeden anderen wertvollen Fetzen plünderten. In seinem Transportkäfig bleibt ein wilder, wütender Panther gefesselt, an dessen Hals Wizlos geschätztes Hyperkondensator-Dingsda befestigt ist. Die Zentauren fürchteten die Bestie und ließen den Käfig geschlossen. Nun vertraut Wizlo dessen Schlüssel Söldnern an, die bereit sind, sich dem Raubtier zu stellen und seine Erfindung zurückzuholen."},{t="Der Ehrgeiz des Tüftlers",b="Wizlo Lagerputzer nennt das Hyperkondensator-Dingsda seine großartigste Schöpfung, obwohl er noch nicht sagen kann, was es tut. Selbst nachdem Leben riskiert wurden, um es von einem eingesperrten Raubtier zurückzuholen, gibt er zu, noch daran tüfteln zu müssen, um seinen Zweck zu verstehen."}},faq={{q="Wer ist Wizlo Lagerputzer?",a="Wizlo Lagerputzer ist ein Goblintüftler und Händler, der am Weißgipfelposten Zuflucht suchte, nachdem Zentauren seine Karawane auf dem Schluchtboden von Tausend Nadeln überfallen und zerstört hatten.",al={"wer ist wizlo","wizlo lagerputzer hintergrundgeschichte","questgeber wizlo"}},{q="Warum trägt der Panther das Dingsda um den Hals?",a="Das Dingsda wurde während des Transports oder des Zentaurenüberfalls am Hals des gefangenen Panthers befestigt. Die Zentauren fürchteten die Bestie und ließen den Käfig unberührt, wodurch der Panther zum Wächter des Geräts wurde.",al={"warum hat der panther das dingsda","panther halskette","halsband dingsda"}},{q="Wo liegt die zerstörte Karawane?",a="Die zerstörte Karawane liegt knapp nördlich vom Weißgipfelposten in Tausend Nadeln, zwischen zertrümmerten Wagen und Lagern feindseliger Zentauren.",al={"karawane fundort","wo ist der pantherkäfig","käfig fundort"}},{q="Warum plünderten die Zentauren den Käfig nicht?",a="Wizlo sagt, der wütende Panther sei so wild gewesen, dass selbst die skrupellosen Zentaurenmarodeure ihn fürchteten. Sie ließen ihn in seinem Käfig eingeschlossen, statt zu wagen, ihn zu öffnen.",al={"warum ließen die zentauren den panther zurück","zentauren fürchten panther","warum ist der käfig unberührt"}},{q="Was tut das Hyperkondensator-Dingsda eigentlich?",a="Wizlo nennt das Hyperkondensator-Dingsda seine großartigste Erfindung, doch nach dessen Rückgabe gibt er zu, es noch untersuchen und daran tüfteln zu müssen, um seine Funktion herauszufinden.",al={"was tut das dingsda","hyperkondensator funktion","was ist das dingsda"}},{q="Wer kontrolliert den Weißgipfelposten?",a="Der Weißgipfelposten ist eine mit der Horde verbündete Taurensiedlung. Zwischen den Tafelbergen der Schlucht gelegen, überwacht er die Aktivitäten der Zentauren und bietet Reisenden der Horde Zuflucht.",al={"weißgipfelposten fraktion","gehört der weißgipfelposten zur horde"}}},fx={["64badd6f"]={q="Warum möchte Wizlo Lagerputzer den Hyperkondensator-Dingsda zurückhaben?",a="Wizlo ist der einzige Überlebende einer Karawane, die in den Canyon-Ebenen von Zentauren überrannt wurde. Er betrachtet den Hyperkondensator als seine beste Erfindung und gibt sogar zu, dass er noch herausfinden muss, was genau er eigentlich bewirkt. Verzweifelt darauf bedacht, das wertvolle Gerät aus dem Wrack seiner Expedition zu retten, ist er bereit, jeden zu belohnen, der mutig genug ist, es zurückzuerobern.",al={"wizlo lagerputzer motiv","warum hyperkondensator bergen","warum will wizlo das dingsda haben"}},["01614ead"]={q="Welches Biest bewacht das Hyperkondensator-Dingsda?",a="Das Gerät hängt um den Hals eines ungewöhnlich wilden, in einen Käfig gesperrten Panthers, der in der zerstörten Karawane gefangen ist. Das Biest war so bösartig, dass die plündernden Zentauren es nicht wagten, seinen Eisenkäfig zu berühren, als sie den Rest der Vorräte stahlen, weshalb das Raubtier inmitten der Trümmer nördlich des Postens zurückgelassen wurde.",al={"wer bewacht das gizmo","panther ziel","was ist der panther"}},["6ff4273d"]={q="Warum benötigt Wizlo Lagerputzer Eure Hilfe?",a="Wizlo entkam dem Gemetzel der Zentauren nur knapp mit dem Leben und ist Ingenieur, kein Krieger. Die Tauren am Weißgipfelposten halten ihre eigene Wache gegen die feindseligen Stämme und haben daher wenig Interesse oder Arbeitskräfte, um einem exzentrischen Goblin dabei zu helfen, zurückgelassene Bastelprojekte aus einem von Plünderern umgebenen Käfigmonster zurückzuholen.",al={"warum braucht wizlo mich","warum abenteurer fragen","warum kann wizlo gizmo nicht holen"}}},fp="20,184,21.263.0,20.388.0,19.253.1,27.172.0,43.205.0,37.125.0,37.160.0,47.158.1,29.147.0"}
P.entries["quest:516"] = {n="Berens List",s="Im südlichen Silberwald geht Schattenpriester Allister gegen die Geißel vor, die sich in einer verborgenen Höhle sammelt. Die Verlassenen hoffen, zuzuschlagen, bevor die Untoten ihre Offensive beginnen.",h="Im südlichen Silberwald geht Schattenpriester Allister gegen die Geißel vor, die sich in einer verborgenen...",kw={"mühlenbern","berens list","placker der ravenclaw","beschützer der ravenclaw","geißel","schattenpriester allister","silberwald","das grabmal"},ang={["class:Priest"]="Als Priester folgt Ihr den Befehlen von Schattenpriester Allister und helft, die Herrschaft des Grabmals zu sichern, indem Ihr rivalisierende untote Schrecken vernichtet.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, den Norden Lordaerons zu stabilisieren, indem Ihr verborgene Nester der Geißel entlang der Grenzen des Silberwalds aushebt.",["race:Undead"]="Als Verlassener helft Ihr, Euer Volk vor dem anhaltenden Zugriff des Lichkönigs zu schützen, indem Ihr Überreste der Geißel in Berens List ausmerzt."},sec={{t="Ein Präventivschlag",b="Schattenpriester Allister hat gehört, dass sich Diener des Lichkönigs tief im südlichen Silberwald sammeln. Ihre wachsende Zahl bedroht die Operationen der Verlassenen in der gesamten Region. Deshalb entsendet Allister Späher, um zuerst zuzuschlagen und die Geißel in ihrem abgelegenen Unterschlupf zu vernichten, bevor sie sich zum Angriff formieren kann."},{t="Die verborgene Höhle",b="Südlich von Mühlenbern, der mit Dalaran verbündeten Siedlung, führt eine verborgene Höhle in die Hügel hinein. Die zerklüfteten Hänge machen die Höhle leicht zu übersehen, und der Zugang führt um die Südseite der Hügel herum. Darin hausen Placker und Beschützer der Ravenclaw. Die Vernichtung dieser Überreste der Geißel hilft den Verlassenen, ihre Stellung im Wald zu halten."}},faq={{q="Was ist Berens List?",a="Berens List liegt in den Hügeln des südlichen Silberwalds, südlich von Mühlenbern. Darin hausen Untote der Ravenclaw.",al={"berens list","wo liegt berens list","was ist diese höhle"}},{q="Wer erteilt den Auftrag für Berens List?",a="Schattenpriester Allister entsendet Abenteurer der Horde vom Grabmal aus, nachdem er erfahren hat, dass feindliche Untote von der Höhle aus eine Offensive vorbereiten.",al={"wer gibt den auftrag für berens list","questgeber berens list","schattenpriester allister quest"}},{q="Warum greifen die Verlassenen die Untoten dort an?",a="Die Untoten in Berens List dienen dem Lichkönig als Teil der Geißel. Die Verlassenen haben sich aus seiner Kontrolle befreit und kämpfen dafür, seine verbliebenen Diener aus ihren Landen zu vertreiben.",al={"warum untote töten","warum gegen ravenclaw kämpfen","sind verlassene nicht untot"}},{q="Wie findet Ihr den Höhleneingang?",a="Die Höhle liegt in den Hügeln südlich von Mühlenbern. Folgt der Südseite der steilen Hügelkämme, um ihren Eingang zu erreichen.",al={"wie gelangt man zu berens list","lage des höhleneingangs","wo ist der höhleneingang"}},{q="Welche Feinde hausen in Berens List?",a="In der Höhle hausen Knechte der Geißel, darunter Placker der Ravenclaw und Beschützer der Ravenclaw. Sie scheinen sich für einen Angriff auf nahe gelegene Siedlungen zu sammeln.",al={"berens list gegner","was ist in berens list"}},{q="Welche Rolle spielt Dalaran bei diesem Auftrag?",a="Dalaran spielt bei dem Auftrag keine direkte Rolle. Menschliche Magier aus Dalaran besetzen das nahe gelegene Mühlenbern, das Allister als Orientierungspunkt nutzt, damit Späher die verborgene Höhle finden.",al={"verbindung zu dalaran","verbindung zu mühlenbern"}}},fp="13,172,19.290.0,15.323.0,22.113.0,41.142.0,48.169.0,41.114.0,35.154.0,44.165.0"}
P.entries["quest:517"] = {n="Elixier der Pein",s="In Tarrens Mühle stellt Apotheker Lydon sein Elixier der Pein auf eine tödliche Probe. Er schickt Champions der Horde nach Dun Garok, um ein Fässchen Kniegräberstarkbier zu beschaffen.",h="In Tarrens Mühle stellt Apotheker Lydon sein Elixier der Pein auf eine tödliche Probe.",kw={"apotheker lydon","dun garok","zwerge","elixier der pein","hillsbrad","shindigger-stout","tarrens mühle","umpi"},ang={["class:Rogue"]="Als Schurke schlüpft Ihr ungesehen durch die überfüllten Speisesäle von Dun Garok und stehlt direkt vor den Nasen der Gebirgsjäger.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Präsenz der Allianz in Dun Garok zu untergraben. Tarrens Mühle behauptet einen gefährdeten Stützpunkt gegen unablässige Bedrohungen aus dem Süden.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass es die Handwerkskunst Eisenschmiedes beleidigt, traditionelles Zwergenbier zum Gefäß für chemischen Massenmord zu machen.",["race:Undead"]="Als Untoter seht Ihr, wie jede von Lydon perfektionierte Mischung die Verlassenen dem Einsatz des Todes gegen die lebenden Feinde näherbringt, die nach Lordaeron vordringen."},sec={{t="Ein bitteres Gebräu",b="Apotheker Lydon dient von Tarrens Mühle aus der Königlichen Apothekervereinigung und Fürstin Sylvanas. Er hat in ganz Hillsbrad tödliche Zutaten gesammelt und ein neues Gebräu vollendet. Frösche und streunende Hunde können seine Stärke nicht auf die Probe stellen. Lydon will sehen, was es lebenden Widersachern antut."},{t="Dun Garok infiltrieren",b="Lydon braucht ein unauffälliges Mittel, um sein Experiment zu transportieren. Südlich von Hillsbrad halten Zwerge aus Eisenschmiede die befestigte Anlage von Dun Garok. Er schickt Agenten der Horde in die unterirdischen Kasernen und Speisesäle. Dort müssen sie an zwergischen Gewehren und Äxten vorbeischlüpfen, um ein Fässchen Kniegräberstarkbier zu stehlen."},{t="Ein Rezept fürs Unheil",b="Apotheker Lydon plant, sein Gift in das Lieblingsgebräu der Zwerge zu mischen. Das gestohlene Fässchen kann das Elixier als festliche Erfrischung getarnt zu einem ahnungslosen Opfer bringen. Ein beliebtes Zwergenstarkbier wird zum Gefäß der Pein."}},faq={{q="Wer ist Apotheker Lydon?",a="Apotheker Lydon ist ein Alchemist der Verlassenen, der in Tarrens Mühle stationiert ist. Er vertritt die Königliche Apothekervereinigung und experimentiert für die Banshee Queen, Fürstin Sylvanas, mit tödlichen Seuchen und Elixieren.",al={"lydon","wer vergibt diese quest","apotheker lydon hintergrund"}},{q="Warum braucht Lydon ein Fässchen Kniegräberstarkbier?",a="Lydon will sein fertiges Elixier der Pein an lebenden Zielen testen. Indem er es in ein Fässchen beliebten Zwergenbiers mischt, kann er seine Opfer heimlich vergiften.",al={"warum zwergenbier","warum shindigger-stout","zweck des fässchens"}},{q="Wo liegt Dun Garok?",a="Dun Garok liegt im Südosten des Vorgebirges des Hügellands. Gebirgsjäger und Schützen aus Eisenschmiede bemannen die befestigte Stellung und wahren ihre Interessen im Norden.",al={"wo liegt dun garok","dun garok lage","wo ist das fässchen"}},{q="Wer ist Umpi?",a="Umpi ist Apotheker Lydons Assistent in Tarrens Mühle. Lydon sagt, dass Umpi sichtlich nervös wird, wenn im Labor Formaldehydgläser geöffnet werden.",al={"umpi","wer ist umpi","lydons assistent"}},{q="Was ist das eigentliche Ziel des Elixiers der Pein?",a="Die Königliche Apothekervereinigung schuf das Elixier der Pein als experimentelles Gift, um die Lebenden auszurotten. Es dient dem Feldzug der Verlassenen, Lordaeron gegen die Stützpunkte der Menschen und Zwerge zu sichern.",al={"was bewirkt das elixier der pein","zweck der seuche","ziel des gifts der verlassenen"}},{q="Was folgt, nachdem das Fässchen beschafft wurde?",a="Sobald Lydon das Fässchen hat, mischt er das giftige Elixier in das Shindigger-Stout. Er schickt Euch los, um das vergiftete Bier einer ahnungslosen Versuchsperson zu bringen.",al={"nächste quest","was folgt nach dun garok","elixier teil fünf"}}},fx={["9a9bdb3b"]={q="Gegen wen werdet Ihr bei Dun Garok ausgesandt?",a="Ihr werdet ausgesandt, um Dun Garok zu infiltrieren, einen schwer befestigten Außenposten der Zwerge im südöstlichen Vorgebirge des Hügellands. Die dort stationierten Bergsteiger und Schützen aus Eisenschmiede gehören der Allianz an, verteidigen die Interessen der Zwerge in der Region und stellen eine ständige Bedrohung für die Präsenz der Verlassenen in Tarrens Mühle dar.",al={"dun garok zwerge","wer ist bei dun garok","wer bewacht die zwerge"}}},fp="15,144,13.273.0,22.285.0,21.220.1,24.195.0,46.157.0,27.149.0,12.137.0,49.190.0,41.150.1"}
P.entries["quest:518"] = {n="Die Krone des Willens",s="In Tarrens Mühle will Melisara Mug'Thols Oger schwächen, bevor sie deren Stellung in den Ruinen von Alterac angreift. Sie schickt Euch los, um die Crushridge maulers zu jagen.",h="In Tarrens Mühle will Melisara Mug'Thols Oger schwächen, bevor sie deren Stellung in den Ruinen von Alterac...",kw={"crushridge maulers","melisara","mug'thol","die ruinen von alterac","sharlindra","tarrens mühle","die krone des willens"},sec={{t="Die Crushridge schwächen",b="Mug'Thol und die Crushridge-Ogre halten die Ruinen von Alterac. Melisara sieht kaum eine Möglichkeit, Mug'Thol zu bestrafen, solange ihn so viele Oger umgeben. Ihre Zahl muss sinken, bevor sie ihren nächsten Schritt machen kann. Ihr werdet ausgesandt, um die Crushridge maulers zu jagen."},{t="Noch keine Ruhe",b="Melisara sieht, wie Ogerblut den Schnee färbt, nachdem die maulers gefallen sind. Doch die Kämpfe gehen weiter, bis die Crushridge nicht nur zahlenmäßig geschwächt, sondern auch im Geiste gebrochen sind."}},faq={{q="Wer vergibt diesen Teil der Krone des Willens?",a="Melisara gibt Euch diese Aufgabe in Tarrens Mühle, und Ihr kehrt zu ihr zurück.",al={"wer vergibt die krone des willens","melisara questgeberin","krone des willens 2 questgeberin"}},{q="Wo befinden sich die Crushridge-Ogre?",a="Mug'Thol und seine Oger haben die Ruinen von Alterac überrannt, wo die Crushridge ihre Stellung halten.",al={"crushridge maulers standort","wo sind crushridge-ogre","ruinen von alterac oger"}},{q="Warum nimmt Melisara zuerst die maulers ins Visier?",a="Melisara sagt, Mug'Thol sei schwer zu bestrafen, solange seine Oger so zahlreich sind. Ihre Zahl muss sinken, bevor sie ihren Plan weiterverfolgen kann.",al={"warum crushridge maulers töten","warum die oger dezimieren"}}},fp="17,155,24.251.0,11.158.1,41.67.0,39.97.0,44.137.0"}
P.entries["quest:519"] = {n="Die Krone des Willens",s="In Tarrens Mühle verlangt Melisara drei Ogerköpfe, bevor sie Mug'Thols Kopf fordert.",h="In Tarrens Mühle verlangt Melisara drei Ogerköpfe, bevor sie Mug'Thols Kopf fordert.",kw={"alterac","krone des willens","glommus","hillsbrad","melisara","muckrake","mug'thol","targ","tarrens mühle"},sec={{t="Die Führung im Visier",b="Melisara nennt Targ, Muckrake und Glommus als Mug'Thols treue Leutnants. Sie fragt sich, was einen Oger zur Treue bewegen könnte. Tötet alle drei und bringt ihre Köpfe nach Tarrens Mühle. Dann bleibt nur noch Mug'Thols Kopf samt Krone zu holen."},{t="Was aus den Köpfen wird",b="Melisara bemerkt, wie übel die Oger riechen. Sobald Mug'Thols Kopf eintrifft, werden alle vier Köpfe auf Spieße über Alterac gesteckt, als Warnung an jeden, der sich gegen die Dunkle Fürstin stellt."}},faq={{q="Wer vergibt diesen Teil der Krone des Willens?",a="Melisara gibt Euch diesen Teil in Tarrens Mühle. Ihr bringt ihr die Köpfe dorthin.",al={"wer startet die krone des willens","melisara standort","wo die krone des willens abgeben"}},{q="Wer sind Targ, Muckrake und Glommus?",a="Targ, Muckrake und Glommus sind Mug'Thols treue Leutnants. Melisara will ihre Köpfe.",al={"mugthols leutnants","wer sind die ogerleutnants","targ muckrake glommus"}},{q="Was geschah vor diesem Teil?",a="Vor diesem Teil wurden die Reihen der Oger im zweiten Teil der Krone des Willens gelichtet.",al={"krone des willens questreihe","welche quest kommt davor","vorheriger teil der krone des willens"}}},fp="17,66,25.237.0,25.171.1,41.78.0,36.88.0,27.90.0"}
P.entries["quest:52"] = {n="Grenzschutz",s="An Elwynns östlicher Brücke bittet Euch Wache Thomas, die Wölfe und Bären zu dezimieren, die Reisende und Arbeiter nahe dem Holzfällerlager des Osttals bedrohen. Die Bestien sind dreister geworden und gefährden die Straßen und Holzfällertrupps.",h="An Elwynns östlicher Brücke bittet Euch Wache Thomas, die Wölfe und Bären zu dezimieren, die Reisende und...",kw={"holzfällerlager des osttals","wald von elwynn","grauwolf","wache thomas","grenzschutz","streuner","junger waldbär"},ang={["class:Hunter"]="Als Jäger könnt Ihr Eure Fährtenlesekunst und Treffsicherheit an den Wölfen und Bären erproben, die durch den östlichen Wald von Elwynn streifen.",["faction:Alliance"]="Die Sicherung der östlichen Straßen hilft, das Bauholz aus Eastvale in die Gebiete der Allianz zu bringen, wo es dem Wiederaufbau und der Verteidigung dient."},sec={{t="Schwindende Verteidigung",b="Goldhain und das Nordhaintal haben sichtbare Garnisonen aus Sturmwind. An der östlichen Grenze gibt es weit weniger Wachen. Wache Thomas bewacht den Flussübergang als einer der wenigen Wachposten zwischen den besiedelten Kernlanden und der Wildnis. Reisende helfen, die Versorgungswege offen zu halten."},{t="Die Bedrohung durch Raubtiere",b="Das Holzfällerlager des Osttals liefert Bauholz nach Sturmwind. Holzfäller, die am Waldrand Bäume fällen, treffen nahe den Straßen und Holzplätzen auf Streuner, Grauwölfe und junge Waldbären. Die Bestien zu dezimieren mindert die Gefahr für die Arbeiter vor Ort eine Zeit lang. Thomas vermutet, dass etwas tiefer im Wald sie auf die Siedlungen zutreibt."}},faq={{q="Wer vergibt den Auftrag Grenzschutz?",a="Wache Thomas erteilt den Auftrag. Er bewacht die östliche Brücke an der Hauptstraße durch den Wald von Elwynn, zwischen dem Waldinneren und der Region Eastvale.",al={"questgeber grenzschutz","wer startet grenzschutz","wache thomas quest"}},{q="Warum greifen Wölfe und Bären das Grenzgebiet an?",a="Wölfe und Bären drängen nahe an Straßen und Arbeitsstätten rund um das Holzfällerlager des Osttals heran. Thomas vermutet, dass etwas tiefer in der Wildnis sie aufscheucht und auf besiedeltes Gebiet zutreibt.",al={"warum sind bären aggressiv","warum greifen wölfe eastvale an","tierangriffe elwynn"}},{q="Wo liegt das Holzfällerlager des Osttals?",a="Das Holzfällerlager des Osttals liegt im östlichen Wald von Elwynn, gleich östlich der Brücke von Wache Thomas. Es versorgt Sturmwind und die Grenzsiedlungen mit dringend benötigtem Bauholz.",al={"eastvale lage","wo ist das holzfällerlager in elwynn","lager eastvale"}},{q="Warum bewacht Wache Thomas die Brücke allein?",a="Sturmwinds Armee und Stadtwache sind über das ganze Königreich verteilt und personell stark beansprucht. Außenposten an Flüssen und Wegkreuzungen haben oft nur ein oder zwei Wachen für die Landstraßen, weshalb sie bei größeren Bedrohungen durch Wildtiere auf Reisende angewiesen sind.",al={"warum ist wache thomas allein","wache thomas posten","sturmwinder wachen eastvale"}},{q="Welche Tiere müssen für diesen Auftrag dezimiert werden?",a="Ihr müsst acht Wölfe, entweder Streuner oder Grauwölfe, und fünf junge Waldbären töten, die durch den östlichen Wald von Elwynn streifen.",al={"grenzschutz ziele","wölfe und bären töten","welche gegner für grenzschutz"}},{q="Was geschieht, sobald die Wildtiere dezimiert sind?",a="Wenn Ihr Bericht erstattet, dankt Euch Wache Thomas, und die Holzkarawanen können sicherer reisen. Er bleibt auf der Hut, denn der dunkle Einfluss, der die Bestien aufwiegelt, könnte dem Wald weiteres Unheil bringen.",al={"grenzschutz folgequest","grenzschutz abgeben"}}},fx={ad29ae35={q="Warum will Wache Thomas, dass die wilden Bestien dezimiert werden?",a="Das Holzfällerlager des Osttals wird ständig von zunehmend aggressiven Wölfen und Bären angegriffen, die durch den östlichen Wald von Elwynn streifen. Wache Thomas ist an der östlichen Brücke stationiert, um Arbeiter und Reisende auf der Straße zu schützen, doch die Raubtiere sind dreist genug, um wichtige Holzfällarbeiten zu stören und jeden zu bedrohen, der sich über die Grenzen des Lagers hinauswagt.",al={"warum wölfe dezimieren wache thomas","protect the frontier warum","warum osttal schützen"}},ce43057a={q="Gegen welche Tiere werdet Ihr in Protect the Frontier ausgesandt?",a="Ihr seid ausgesandt, um die Streuner, Grauwaldwölfe und jungen Waldbären zu dezimieren, die in den Wäldern rund um das Holzfällerlager des Osttals umherstreifen. Die normalerweise scheuen Tiere im westlichen Wald von Elwynn sind hier an der Grenze ungewöhnlich bösartig und dreist geworden, was das alltägliche Reisen und die Holzarbeit gefährlich macht.",al={"welche wölfe und bären protect the frontier","protect the frontier bestien","welche tiere wache thomas"}}},fp="20,209,18.267.0,20.335.0,41.142.0,48.187.0,35.150.0,46.217.0,45.128.0,41.192.0"}
P.entries["quest:520"] = {n="Die Krone des Willens",s="Melisara in Tarrens Mühle schickt Euch hinter Mug'Thol her, dessen Leutnants tot sind. Bringt seinen Kopf und die Krone des Willens zurück, und der Widerstand der Crushridge wird ein Ende haben.",h="Melisara in Tarrens Mühle schickt Euch hinter Mug'Thol her, dessen Leutnants tot sind.",kw={"alterac","krone des willens","crushridge","vorgebirge des hügellands","melisara","mug'thol","tarrens mühle"},sec={{t="Der letzte Kopf",b="Nur Mug'Thol bleibt noch übrig. Melisara erwartet, dass er sich dagegen wehren wird, die Krone des Willens herzugeben. Da seine Leutnants gefallen sind, rechnet er wahrscheinlich mit Euch. Findet ihn, tötet ihn und bringt seinen Kopf und die Krone nach Tarrens Mühle zurück."},{t="Melisaras Antwort",b="Melisara ist mit Eurer Arbeit zufrieden. Mug'Thols Kopf wird den höchsten Gipfel der Ruinen von Alterac zieren. Dann wird die Todeswache zerschlagen, was von den Crushridge übrig ist."}},faq={{q="Wer schickt Euch los, um Mug'Thol zu töten?",a="Melisara in Tarrens Mühle schickt Euch los, um Mug'Thol zu töten. Ihr bringt ihr seinen Kopf zurück.",al={"krone des willens questgeber","wer gibt die krone des willens","melisara quest"}},{q="Was verlangt Melisara von Mug'Thol?",a="Melisara verlangt Mug'Thols Kopf und die Krone des Willens.",al={"mugthol questziele","was bekommt man von mugthol","mug'thol gegenstände"}},{q="Warum glaubt Melisara, dass Mug'Thol mit Ärger rechnet?",a="Da seine Leutnants tot sind, vermutet Melisara, dass Mug'Thol mit Euch rechnet. Sie glaubt, dass er sich dagegen wehren wird, die Krone herzugeben.",al={"warum ist mugthol bereit","mugthol erwartet kampf","mug'thol gewarnt"}},{q="Wo ist dieser Auftrag innerhalb von „Die Krone des Willens“ einzuordnen?",a="Dieser Auftrag kommt nach dem dritten Teil, in dem Mug'Thols Leutnants gejagt wurden. Ein fünfter Teil folgt.",al={"krone des willens questreihe","welche quest kommt vor krone des willens vier","krone des willens questverlauf"}}},fp="17,164,13.208.0,16.167.1,31.83.0,41.56.0,49.113.0,42.99.0"}
P.entries["quest:521"] = {n="Die Krone des Willens",s="Melisara schickt die Krone des Willens in die Unterstadt, wo Sharlindra dafür sorgen wird, dass sie Fürstin Sylvanas erreicht.",h="Melisara schickt die Krone des Willens in die Unterstadt, wo Sharlindra dafür sorgen wird, dass sie Fürstin...",kw={"krone des willens","hillsbrad","melisara","mugthol","sharlindra","sylvanas","unterstadt"},sec={{t="In die Unterstadt",b="Melisara schickt Euch mit der Krone zu Sharlindra in die Unterstadt. Sharlindra wird sie an Fürstin Sylvanas weitergeben. Melisara warnt Euch davor, die Krone für Eure eigenen Zwecke zu nutzen. Mug'Thols Schicksal ist Warnung genug."},{t="Sharlindras Reaktion",b="Sharlindra erkennt die Krone als das Relikt, mit dem sich der Oger dem Willen der Dunklen Fürstin entzog. Sie findet es merkwürdig, dass ein so schlichter Gegenstand solche Macht besaß und in so ungeschickte Hände fiel. Sharlindra wird sie aus der Unterstadt zu Fürstin Sylvanas bringen und ihr berichten, was Ihr getan habt."}},faq={{q="Wer nimmt die Krone des Willens in der Unterstadt entgegen?",a="Sharlindra nimmt die Krone in der Unterstadt entgegen. Melisara sagt, dass Sharlindra sie an Fürstin Sylvanas weitergeben wird.",al={"wer bekommt die krone des willens","wohin die krone bringen","bei sharlindra abgeben"}},{q="Warum warnt Melisara davor, die Krone zu benutzen?",a="Melisara warnt Euch davor, die Krone für Eure eigenen Zwecke zu nutzen. Sie verweist auf Mug'Thols Schicksal als Warnung genug.",al={"krone anlegen möglich","warum krone des willens nicht benutzen","mug'thols schicksal warnung"}},{q="Wer schickt Euch mit der Krone los?",a="Melisara schickt Euch im fünften und letzten Teil, nach dem vierten, mit der Krone los.",al={"krone des willens letzter teil","wer vergibt krone des willens fünf"}}},fp="17,102,16.204.0,21.267.1,48.106.0,47.107.0,29.80.0"}
P.entries["quest:522"] = {n="Auftragsmördervertrag",s="Im Vorgebirge des Hügellands trägt ein Shadowy Assassin einen Vertrag bei sich, der die Tötung von Magistrat Henry Maleb anordnet. Ihr sollt ihn zu Maleb in Süderstade bringen, wo rotes Wachs den Abdruck eines unverwechselbaren Siegelrings trägt.",h="Im Vorgebirge des Hügellands trägt ein Shadowy Assassin einen Vertrag bei sich, der die Tötung von Magistrat...",kw={"auftragsmördervertrag","vorgebirge des hügellands","magistrat henry maleb","shadowy assassin","siegelring","süderstade","syndikat"},sec={{t="Ein gezeichneter Magistrat",b="Ein Shadowy Assassin trägt im Vorgebirge des Hügellands einen Vertrag bei sich. Er ordnet die Tötung von Magistrat Henry Maleb an, und ein unverwechselbarer Siegelring hat seinen Abdruck im roten Wachs hinterlassen. Bringt das Schriftstück zu Maleb in Süderstade."},{t="Malebs Urteil",b="Magistrat Henry Maleb liest den Vertrag und sagt, dass er den jüngsten Angriff auf Süderstade erklärt. Er ist sich sicher, dass das Syndikat ihm nach dem Leben trachtet, wie schon dem vorherigen Magistrat."}},faq={{q="Was steht in dem Vertrag?",a="Der Vertrag ordnet die Tötung von Magistrat Henry Maleb an. Rotes Wachs versiegelt ihn und trägt den Abdruck eines unverwechselbaren Siegelrings.",al={"was steht im vertrag","auftragsmördervertrag details","wer ist das ziel"}},{q="Woher stammt dieser Vertrag?",a="Ein Shadowy Assassin trägt den Vertrag im Vorgebirge des Hügellands bei sich.",al={"wer hat den vertrag fallen gelassen","wo den vertrag finden","shadowy assassin beute"}},{q="Wem soll der Vertrag überbracht werden?",a="Bringt den Vertrag zu Magistrat Henry Maleb in Süderstade. Er ist der Magistrat, dessen Tötung darin angeordnet wird.",al={"wem den vertrag geben","wo auftragsmördervertrag abgeben","maleb aufenthaltsort"}}},fp="19,198,19.198.0,15.174.1,32.108.0,35.63.0,41.100.0"}
P.entries["quest:523"] = {n="Ableben des Barons",s="In Süderstade fordert Magistrat Henry Maleb Gerechtigkeit für den Vertrag, den Ihr geborgen habt. Baron Vardus, ein kaltherziger Adliger aus dem alten Alterac, hat ihn unterzeichnet, und Maleb bittet Euch, ihm dessen Kopf zu bringen.",h="In Süderstade fordert Magistrat Henry Maleb Gerechtigkeit für den Vertrag, den Ihr geborgen habt.",kw={"alteracgebirge","baron vardus","ableben des barons","magistrat henry maleb","süderstade","strahnbrad","syndikat"},sec={{t="Gerechtigkeit für einen Vertrag",b="Nach Assassin's Contract erzählt Euch Magistrat Henry Maleb, dass Baron Vardus den Vertrag unterzeichnet hat. Vardus ist ein Adliger aus dem alten Alterac, bekannt für sein kaltes Herz und seine brutale Art. Maleb überrascht es nicht, dass er dahintersteckt. Süderstade wird den Baron nicht Schläger gegen die Stadt schicken lassen, ohne ihn dafür zur Rechenschaft zu ziehen.\n\nMaleb vermutet Vardus in einem der Unterschlüpfe des Syndikats, in den Ruinen von Strahnbrad oder im Tal nördlich davon. Er bittet Euch, ihm den Kopf des Barons zu bringen."},{t="Malebs Erleichterung",b="Als Ihr den Kopf von Baron Vardus bringt, dankt Euch Magistrat Henry Maleb. Das Wissen, dass der Schurke seinen eigenen verloren hat, lässt Maleb etwas ruhiger schlafen."}},faq={{q="Wer ist Baron Vardus?",a="Baron Vardus ist ein Adliger aus dem alten Alterac, bekannt für sein kaltes Herz und seine brutale Art. Sein Name steht auf dem Vertrag, der Magistrat Maleb zum Tode verurteilte.",al={"baron vardus hintergrund","wer ist vardus","vardus alterac"}},{q="Warum will Magistrat Maleb Baron Vardus tot sehen?",a="Baron Vardus hat den Vertrag unterzeichnet, den Ihr geborgen habt. Magistrat Maleb wird ihn nicht Schläger gegen Süderstade schicken lassen, ohne ihn dafür zur Rechenschaft zu ziehen.",al={"warum baron vardus töten","maleb vardus","grund für ableben des barons"}},{q="Wo ist Baron Vardus zu finden?",a="Magistrat Maleb vermutet Baron Vardus in einem der Unterschlüpfe des Syndikats, vielleicht in den Ruinen von Strahnbrad oder im Tal nördlich davon.",al={"baron vardus aufenthaltsort","wo ist vardus","strahnbrad vardus"}},{q="Was kommt davor?",a="Es folgt auf Assassin's Contract, den von Euch geborgenen Vertrag, der den Namen von Baron Vardus trägt.",al={"ableben des barons vorquest","questreihe vor ableben des barons","assassin's contract voraussetzung"}}},fp="14,190,22.458.0,14.140.1,20.152.0,49.137.0,32.131.0,23.87.0"}
P.entries["quest:524"] = {n="Elixier der Pein",s="In Tarrens Mühle bereitet Apotheker Lydon ein tödliches Gift für einen grausamen Versuch vor. Er plant, es als gestohlenes Zwergenbier zu tarnen und an menschlichen Gefangenen einzusetzen.",h="In Tarrens Mühle bereitet Apotheker Lydon ein tödliches Gift für einen grausamen Versuch vor.",kw={"apotheker lydon","gefangene bauern","dun garok","elixier der pein","hochexekutorin darthalia","hillsbrad","besudeltes fässchen","tarrens mühle"},ang={["faction:Horde"]="Als Mitglied der Horde erlebt Ihr die härtere Seite der Unternehmungen der Verlassenen in Tarrens Mühle, wo sie die Grenzen dessen ausloten, was andere hinzunehmen bereit sind.",["race:Human"]="Als Mensch seht Ihr die kalte Skrupellosigkeit der Verlassenen im Abschlachten hilfloser Bauern aus Lordaeron, ihrer einstigen Verwandten.",["race:Undead"]="Als Verlassene wisst Ihr, dass die Gifte der Royal Apothecary Society überlebenswichtig sind. Sie wollen das Vorgebirge des Hügellands mit allen Mitteln gegen ein Wiedererstarken der Menschen sichern."},sec={{t="Ein tödlicher Jahrgang",b="Apotheker Lydon sammelt im gesamten Vorgebirge des Hügellands widerliche Zutaten und stiehlt Zwergenbier aus Dun Garok. Die Royal Apothecary Society hat ihn beauftragt, ein tödliches Gebräu namens Elixier der Pein herzustellen. Sobald es gemischt ist, wartet das Gift in einem Fässchen, das gewöhnliches Starkbier aus den Bergen zu enthalten scheint."},{t="Unglückliche Gäste",b="Deathguards in Tarrens Mühle nahmen kürzlich einheimische menschliche Bauern gefangen, weil sie vermuteten, ein Militärstratege aus Sturmwind verstecke sich unter ihnen. Dann kam die Nachricht, dass der Stratege in den Plaguelands gestorben war. Hochexekutorin Darthalia hielt die überlebenden Bauern daraufhin für die militärische Aufklärung für nutzlos und übergab sie Lydon für seine chemischen Versuche."},{t="Das Gebräu im Versuch",b="Lydons besudeltes Fässchen wird nach oben in den Gefangenenraum getragen und vor den durstigen Gefangenen auf einen staubigen Teppich gestellt. Ohne die Gefahr zu ahnen, eilen die Bauern herbei, um zu trinken. Das Gift wirkt binnen weniger Augenblicke, und sie brechen tot zusammen, was zeigt, wie tödlich das Gebräu ist."}},faq={{q="Warum wurden die menschlichen Bauern überhaupt gefangen genommen?",a="Deathguards nahmen die Bauern gefangen, weil sie vermuteten, ein Militärstratege aus dem Königreich Sturmwind verstecke sich unter ihnen. Nachdem der Stratege in den Plaguelands gestorben war, hielt Hochexekutorin Darthalia die Gefangenen für die Aufklärung nicht länger für nützlich.",al={"warum gefangene","warum bauern eingesperrt","gefangene tarrens mühle"}},{q="Wer ist Apotheker Lydon?",a="Apotheker Lydon gehört der Royal Apothecary Society der Verlassenen an und arbeitet in Tarrens Mühle. Er entwickelt und erprobt tödliche Seuchen und Gifte, die alles Lebende auslöschen sollen, oft an gefangenen Einheimischen.",al={"geschichte apotheker lydon","wer ist lydon","lydon tarrens mühle"}},{q="Woher stammte das Bier im Fässchen?",a="Das Bier stammte von den Zwergen aus Dun Garok, einer wehrhaften Bergfestung im südlichen Vorgebirge des Hügellands. Lydon versetzte das gestohlene Fässchen mit seinen Reagenzien, damit sein tödliches Gift wie gewöhnliches Zwergengebräu wirkte.",al={"herkunft des biers","bier aus dun garok","herkunft des fässchens"}},{q="Was geschieht, wenn Ihr das besudelte Fässchen abliefert?",a="Lydon bittet Euch, das besudelte Fässchen für sein Experiment auf den Teppich im Gefangenenraum zu stellen.",al={"was geschieht mit den bauern","bauern trinken aus fässchen","ergebnis des verseuchten gebräus"}},{q="Wer genehmigte den Einsatz der Gefangenen als Versuchspersonen?",a="Hochexekutorin Darthalia, Befehlshaberin der Streitkräfte der Verlassenen in Tarrens Mühle, übergab die überlebenden Gefangenen Apotheker Lydon, nachdem sie keinen militärischen Wert mehr hatten.",al={"wer ließ lydon an bauern experimentieren","darthalias rolle","darthalias gefangene"}},{q="Was versucht die Royal Apothecary Society hier zu erreichen?",a="Die Royal Apothecary Society will eine tödliche Seuche erschaffen, die sowohl die Geißel als auch die Lebenden vernichten kann. Feldversuche wie das Elixier der Pein erproben neue Wege, Chemikalien zu verabreichen, und messen ihre Wirkung auf menschliche Körper.",al={"apothekerziele hügelland","warum elixier der pein herstellen","seuchenversuche der verlassenen"}}},fx={["34bdf792"]={q="Warum will Apotheker Lydon die Gefangenen vergiften?",a="Apotheker Lydon benötigt lebende menschliche Subjekte, um die tödliche Wirksamkeit seines neu fertiggestellten Elixir of Agony zu überprüfen. Die Königliche Apothekervereinigung ist ständig bestrebt, tödliche Seuchen und Gifte zu verfeinern, um die Menschheit wie auch die Geißel auszurotten. Da Hochexekutorin Darthalia die gefangenen Bauern nicht länger für Verhöre benötigt, betrachtet Lydon sie als bequeme, entbehrliche Testsubjekte, um zu bestätigen, dass sein Gebräu wie beabsichtigt funktioniert, bevor er seinen Erfolg meldet.",al={"warum bauern vergiften","lydon motiv","warum elixir of agony testen","warum will lydon das erledigt haben"}}},fp="15,152,16.294.0,18.340.1,16.258.1,55.259.1,24.201.0,43.216.0,46.95.0,52.163.1,60.223.0"}
P.entries["quest:525"] = {n="Weitere Geheimnisse",s="In den Ausläufern des Alteracgebirges rätselt Ausgrabungsleiter Sturmlanze über einen entschlüsselten Brief. Er schickt Euch mit der Nachricht zum Magistrat von Süderstade.",h="In den Ausläufern des Alteracgebirges rätselt Ausgrabungsleiter Sturmlanze über einen entschlüsselten Brief.",kw={"alterac","entschlüsselter brief","weitere geheimnisse","magistrat henry maleb","ausgrabungsleiter sturmlanze","süderstade","syndikat"},sec={{t="Ein Brief ohne Sinn",b="Ausgrabungsleiter Sturmlanze hat den Brief entschlüsselt, den Ihr bei Dieben in den Ausläufern des Alteracgebirges gefunden habt. Doch seine Bedeutung bleibt ihm verborgen, und er fragt sich, warum Diebe ihn überhaupt besaßen. Süderstade liegt Alterac am nächsten. Sollte sich eine Bedrohung anbahnen, sollte der dortige Magistrat davon erfahren, also bringt Ihr die Nachricht zu Magistrat Henry Maleb."},{t="Was Maleb liest",b="Magistrat Henry Maleb studiert den Brief und urteilt, dass weder ein Dieb noch ein Adeliger aus Alterac ihn verfasst haben könnte. Seine Worte deuten auf eine dunklere Macht hinter dem Syndikat hin. Maleb schaudert bei dem Gedanken daran, was für eine Macht das sein könnte."}},faq={{q="Wer schickt Euch mit dem entschlüsselten Brief los?",a="Ausgrabungsleiter Sturmlanze hat den Brief entschlüsselt, kann sich aber keinen Reim darauf machen. Er schickt Euch zum Magistrat von Süderstade, weil die Stadt Alterac am nächsten liegt.",al={"wer vergibt weitere geheimnisse","weitere geheimnisse questgeber","wo beginnt weitere geheimnisse"}},{q="Wer muss den entschlüsselten Brief sehen?",a="Magistrat Henry Maleb in Süderstade muss den entschlüsselten Brief sehen. Sturmlanze sagt, Süderstade liege Alterac am nächsten, also sollte der dortige Magistrat von jeder drohenden Bedrohung erfahren.",al={"wer bekommt den entschlüsselten brief","weitere geheimnisse abgeben","wohin den brief bringen"}},{q="Woher stammt der ursprüngliche verschlüsselte Brief?",a="Ihr habt den ursprünglichen verschlüsselten Brief bei Dieben in den Ausläufern des Alteracgebirges gefunden, bevor Ihr ihn zu Ausgrabungsleiter Sturmlanze gebracht habt.",al={"herkunft des entschlüsselten briefs","wo wurde der brief gefunden","wer hatte den brief"}}},fp="17,153,24.312.0,16.221.1,40.152.0,38.175.0,50.120.0"}
P.entries["quest:5261"] = {n="Eagan Pelzschneider",s="Waldwölfe bedrohen das Nordhaintal, und Eagan Pelzschneider hat vor der Abtei Arbeit für Rekruten. Der örtliche Kürschner braucht Jäger, die die Rudel ausdünnen und Felle zurückbringen.",h="Waldwölfe bedrohen das Nordhaintal, und Eagan Pelzschneider hat vor der Abtei Arbeit für Rekruten.",kw={"deputy willem","eagan pelzschneider","abtei von nordhain","nordhaintal","waldwölfe","wolves across the border"},ang={["faction:Alliance"]="Jede kleine Aufgabe in Nordhain hilft, Sturmwinds Kernland zu sichern, während das Hauptheer des Königreichs andernorts weiterhin überlastet ist.",["race:Human"]="Als junger Mensch, der die Abtei von Nordhain verlässt, lernt Ihr zuerst, Eure Heimat zu verteidigen, indem Ihr örtlichen Handwerkern wie Eagan helft."},sec={{t="Ein Wort mit dem Kürschner",b="Deputy Willem schickt Rekruten der Abtei oft zu Eagan Pelzschneider auf dem nahen Gelände. Die Obstgärten und Felder des Nordhaintals grenzen an wilde Wälder, in denen Waldwölfe umherstreifen. Eagan bittet Neuankömmlinge, die aggressiven Rudel zu jagen und Felle für sein Handwerk zu sammeln."},{t="Gefahr am Rand",b="Waldwölfe bedrohen Arbeiter, Akolythen und Versorgungsgüter auf dem Weg nach Nordhain und von dort zurück. Junge Champions zu Eagan zu schicken, hilft, die nahen Pfade zu sichern, und hält Sturmwinds wenige verbliebene Wachen für andere Aufgaben frei. Diese Wachen sind bereits mit wachsenden Spannungen im gesamten Wald von Elwynn beschäftigt."}},faq={{q="Wer schickt Euch zu Eagan Pelzschneider?",a="Deputy Willem schickt vielversprechende Rekruten zu Eagan, nachdem er ihnen von den Sicherheitsproblemen des Tals berichtet hat. Er wartet vor dem Eingang der Abtei von Nordhain.",al={"wer vergibt diese quest","wer startet die quest eagan pelzschneider"}},{q="Wo befindet sich Eagan Pelzschneider?",a="Eagan Pelzschneider arbeitet nahe den Außenmauern der Abtei von Nordhain, an der linken Seite des Hauptgebäudes, zwischen seinen Trockengestellen und seiner Ausrüstung.",al={"wo ist eagan","eagan pelzschneider standort","eagan finden"}},{q="Wobei braucht Eagan Pelzschneider Hilfe?",a="Eagan braucht einen Jäger, der aggressive Waldwölfe in den umliegenden Wäldern tötet und ihre Felle zurückbringt. Das hilft, Nordhains Randgebiet zu sichern.",al={"was will eagan","warum wölfe jagen","eagans zweck"}},{q="Könnt Ihr diese Quest überspringen und direkt mit Eagan sprechen?",a="Ja. Eagan bietet jedem, der ihn anspricht, Jagdarbeit an. Wenn Ihr zuerst mit ihm sprecht, verpasst Ihr die Einführung durch Deputy Willem.",al={"eagan-quest überspringen","wolves across the border direkt"}},{q="Warum gibt es so viele Wölfe im Nordhaintal?",a="Das Nordhaintal grenzt an dichte, ungezähmte Wälder, in denen Waldwölfe frei umherstreifen. Die örtlichen Wachen sind durch andere Bedrohungen im ganzen Königreich überlastet, sodass die Raubtiere ungehindert ihr Unwesen treiben.",al={"warum wölfe in nordhain","wolfsproblem elwynn"}},{q="Welche Aufgabe folgt auf das Gespräch mit Eagan Pelzschneider?",a="Nach dem Gespräch mit Eagan werdet Ihr gebeten, jenseits des Abteigeländes Waldwölfe zu jagen und ihre zähen Felle zu sammeln.",al={"nächste quest nach eagan","was bietet eagan als nächstes an"}}},fx={b90d340a={q="Warum schickt Euch Deputy Willem zu Eagan Peltskinner?",a="Deputy Willem ist für die Aufrechterhaltung der Sicherheit rund um die Abtei von Nordhain verantwortlich. Da Wolfssichtungen im gesamten Tal zunehmen, ist ein Jäger, der um Hilfe bei der Dezimierung des Rudels bittet, eine willkommene Gelegenheit. Willem schickt willige Rekruten zu Eagan, damit sich die wenigen Wachen der Abtei auf größere Sorgen konzentrieren können, während sie dennoch die Raubtiere eindämmen, die in die Siedlung eindringen.",al={"warum schickt willem zu eagan","willem motiv eagan peltskinner","warum eagan besuchen"}}},fp="17,176,23.254.0,24.292.0,46.150.0,35.136.0,43.147.0,51.129.0,50.185.0,50.118.0"}
P.entries["quest:527"] = {n="Kampf um das Hügelland",s="In ganz Hillsbrad greifen die Verlassenen die Höfe an, die die Menschenstadt versorgen. Hochexekutorin Darthalia leitet den Angriff von Tarrens Mühle aus unter dem Befehl von Varimathras.",h="In ganz Hillsbrad greifen die Verlassenen die Höfe an, die die Menschenstadt versorgen.",kw={"kampf um das hügelland","darthalia","farmer getz","farmer ray","die felder von hillsbrad","new plague","tarrens mühle","varimathras"},ang={["faction:Alliance"]="Als Angehörige der Allianz erlebt Ihr beim Abschlachten der nördlichen Siedler die Gefahr für Lordaerons verbliebene menschliche Enklaven.",["faction:Horde"]="Als Angehörige der Horde erlebt Ihr im nördlichen Feldzug von Tarrens Mühle aus die Brutalität von Sylvanas' Krieg gegen die Allianz, während Thrall Ehre predigt.",["race:Undead"]="Als Verlassene kämpft Ihr darum, Lordaeron zurückzuerobern, indem Ihr die Lebenden auslöscht, die Eure Heimat als geraubtes Land beanspruchen."},sec={{t="Den Widerstand aushungern",b="Hochexekutorin Darthalia leitet den Feldzug der Verlassenen von Tarrens Mühle aus. Varimathras in Unterstadt hat ihr befohlen, den menschlichen Widerstand im Vorgebirge des Hügellands zu brechen. Deshalb nimmt Darthalia die nördlichen Felder ins Visier, bevor sie die befestigte Stadt angreift. Diese Höfe ernähren die Stadt. Ihre Bewirtschaftung zu stören, schneidet die Menschenmiliz von Vorräten ab und stiftet Unruhe auf den Gehöften."},{t="Ein Verzögerungsgefecht",b="Die Verlassenen bedrängen die menschlichen Verteidiger, während die Königliche Apothekervereinigung eine Seuche vorbereitet, die die Lebenden und die Geißel vernichten soll. Darthalia nutzt die Kämpfe, um die Menschen niederzuhalten, bis die Seuche bereit ist. Farmer Ray und Farmer Getz gehören zu den Landbesitzern, die bei diesen frühen Angriffen getötet werden."}},faq={{q="Warum greifen die Verlassenen einfache Bauern an?",a="Bauern und Landarbeiter auf den Feldern von Hillsbrad helfen dabei, die Stadt Hillsbrad zu versorgen. Landbesitzer wie Farmer Ray und Farmer Getz zu töten, stört die Bewirtschaftung der Höfe und kappt die Nahrungsversorgung der menschlichen Garnison, was ihre Verteidigung vor einem direkten Angriff schwächt.",al={"warum bauern töten","angriffsziele auf hillsbrads höfen","warum höfe angreifen"}},{q="Wer befiehlt diesen Angriff?",a="Hochexekutorin Darthalia, die Befehlshaberin der Verlassenen in Tarrens Mühle, befiehlt den Angriff. Sie untersteht Varimathras und Fürstin Sylvanas Windläufer.",al={"wer vergibt die quest","darthalias befehle","wer ist darthalia"}},{q="Welche Rolle spielt die Königliche Apothekervereinigung in diesem Feldzug?",a="Darthalia sagt, die Kämpfe halten die Lebenden zurück, während die Apotheker der Verlassenen eine Seuche vorbereiten, um ihre Feinde zu vernichten.",al={"warum the new plague","apotheker in hillsbrad","seuchenplan der verlassenen"}},{q="Wo befinden sich Farmer Ray und Farmer Getz?",a="Farmer Ray und Farmer Getz beaufsichtigen die nördlichen Felder von Hillsbrad. Farmer Ray ist in der Nähe des großen Bauernhauses oder im Garten direkt östlich davon. Farmer Getz ist bei der Scheune, beim Nebenhaus oder auf den umliegenden Feldern.",al={"farmer ray finden","farmer getz finden","ray und getz fundort"}},{q="Was geschieht nach Abschluss dieses Überfalls?",a="Nachdem Ihr siegreich zu Darthalia zurückgekehrt seid, verlagert sich der Angriff auf die südlichen Felder und Hillsbrad. Auch weitere Unternehmungen werden möglich, darunter das Sammeln grausiger Trophäen in Souvenirs of Death.",al={"kampf um das hügelland folgequest","what comes next","fortschritt der questreihe"}},{q="Warum bedroht Darthalia ihre Soldaten?",a="Darthalia verlangt strenge Disziplin und Rücksichtslosigkeit. Zögern oder Leichtfertigkeit im Umgang mit dem Krieg gegen die Allianz betrachtet sie als Verrat, der mit sofortiger Hinrichtung bestraft wird.",al={"darthalias dialog","darthalias enthauptungsdrohung"}}},fx={a66392fb={q="Gegen wen werdet Ihr auf Die Felder von Hillsbrad ausgesandt?",a="Ihr werdet gegen die menschlichen Bauern und Landarbeiter ausgesandt, die auf den nördlichen Parzellen von Die Felder von Hillsbrad arbeiten, wobei Ihr es insbesondere auf die Landbesitzer Farmer Ray und Farmer Getz abgesehen habt. Diese Bewohner bilden das Rückgrat der landwirtschaftlichen Infrastruktur der Region und bauen Feldfrüchte an und halten Vieh, das die nahe gelegene menschliche Siedlung Hillsbrad und die Streitkräfte der Allianz, die das Gebiet halten, versorgt.",al={"battle of hillsbrad ziele","wen greifen wir in hillsbrad an","wer sind bauer ray und getz"}}},fp="19,165,23.366.0,17.298.0,46.234.0,23.139.0,61.120.0,45.214.0,40.189.0,41.164.0"}
P.entries["quest:528"] = {n="Kampf um das Hügelland",s="In Hillsbrad rücken die Verlassenen nach Angriffen auf die nördlichen Bauernhöfe nach Süden vor. Agenten der Horde jagen nun die Bauern, die in die Obstgärten geflohen sind.",h="In Hillsbrad rücken die Verlassenen nach Angriffen auf die nördlichen Bauernhöfe nach Süden vor.",kw={"kampf um das hügelland","dark lady","darthalia","deathstalkers","verlassene","die felder von hillsbrad","bauern von hillsbrad","tarrens mühle"},ang={["faction:Alliance"]="Die Ermordung unbewaffneter Flüchtlinge in den südlichen Obstgärten zeigt den erbarmungslosen Krieg der Verlassenen gegen Lordaerons verbliebene lebende Untertanen.",["faction:Horde"]="Tarrens Mühle ist die Hochburg der Horde im Vorgebirge. Hillsbrads Widerstand zu brechen sichert die Verbindungs- und Nachschublinien der Horde gegen Vorstöße der Allianz.",["race:Undead"]="Für die Verlassenen ist die Tötung der lebenden Arbeiter zweckmäßig und endgültig. Sie entzieht der Allianz die Nahrungsgrundlage und stärkt die Herrschaft der Dark Lady über das südliche Lordaeron."},sec={{t="Schrecken auf den Feldern",b="Die Bauernhöfe der Menschen in Hillsbrad sind angegriffen worden, was die Arbeiter nach Süden auf die Felder treibt. Nach Angriffen auf die nördlichen Bauernhöfe fliehen viele in die Obstgärten und auf die Weiden der Felder von Hillsbrad. Sie hoffen, den vorrückenden Untoten zu entkommen. Hochexekutorin Darthalia sieht ihre Flucht als Gelegenheit, die verbliebenen Arbeitskräfte und die Moral der Ortschaft zu brechen."},{t="Der Vormarsch der Dark Lady",b="Von Tarrens Mühle aus befiehlt Hochexekutorin Darthalia den Streitkräften der Horde, die vertriebenen Arbeiter auf den Feldern zu jagen. Die Bauern sind schutzlos. Ihr Tod schnürt Hillsbrads Nahrungsversorgung ab und schwächt den Widerstandswillen der Zivilbevölkerung. Für Darthalia und die Verlassenen festigt jeder getötete Mensch ihre Kontrolle über die verbliebene Ortschaft und hilft, Lordaeron in den Händen der Verlassenen zu halten."}},faq={{q="Warum nehmen die Verlassenen einfache Bauern ins Visier?",a="Die Verlassenen greifen die Bauern an, um die Arbeitskräfte zu vernichten, die Hillsbrad ernähren. Indem Hochexekutorin Darthalia jene töten lässt, die sich in den südlichen Obstgärten verstecken, verschärft sie Panik und Hunger in der Stadt und erleichtert die Eroberung.",al={"warum bauern töten","warum bauern angreifen","darthalias plan für die bauern"}},{q="Wer befiehlt diesen Angriff?",a="Hochexekutorin Darthalia, die Befehlshaberin der Verlassenen in Tarrens Mühle, befiehlt den Angriff auf die örtlichen Menschensiedlungen im Namen von Fürstin Sylvanas Windläufer.",al={"wer vergibt kampf um das hügelland 2","questgeber kampf um das hügelland","darthalias befehle"}},{q="Woher sind diese Bauern geflohen?",a="Die Bauern flohen nach früheren Angriffen der Horde von den nördlichen Bauernhöfen. In Panik suchten sie zwischen den Bäumen und auf den Weiden im Süden der Felder von Hillsbrad Zuflucht.",al={"woher kommen die bauern","nördliche bauernhöfe hillsbrad"}},{q="Wo sind die fliehenden Bauern zu finden?",a="Die Bauern sind über die südlichen Obstgärten und Weiden der Felder von Hillsbrad verstreut, direkt südlich der Hauptstraße durch das Vorgebirge.",al={"bauern in hillsbrad fundort","wo sind die bauern von hillsbrad"}},{q="Was folgt auf die Tötung der Bauern?",a="Nachdem die Arbeiter auf den südlichen Feldern beseitigt sind, richtet Hochexekutorin Darthalia den Feldzug gegen Blacksmith Verringtan und die Schmiede, die Hillsbrads Verteidiger bewaffnet. Die Kämpfe rücken näher an den Stadtkern.",al={"was kommt nach den bauern","kampf um das hügelland nächster schritt"}},{q="Warum kämpft die Horde hier so erbarmungslos?",a="Hillsbrad ist eine Stadt der Menschen und eine der letzten Hochburgen der Allianz in Lordaeron. Die Verlassenen beanspruchen die Region als ihr Hoheitsgebiet und wollen die Allianzenklaven, die ihre Südgrenze bedrohen, vertreiben oder vernichten.",al={"warum greift die horde hillsbrad an","verlassene gegen hillsbrad krieg"}}},fx={cca64c76={q="Wer sind die Bauern von Hillsbrad?",a="Sie sind die einfachen Menschen von Hillsbrad, die vor dem ersten Angriff auf die nördlichen Farmen geflohen sind. Von den vorrückenden Verlassenen in Angst und Schrecken versetzt, zerstreuten sie sich nach Süden in die Obstplantagen von Die Felder von Hillsbrad, in der Hoffnung, sich vor dem Gemetzel zu verstecken, doch Darthalias Späher entdeckten ihr Versteck schnell.",al={"hillsbrad bauern","wer sind die bauern","bauern in obstgärten"}}},fp="19,143,27.338.0,23.354.0,47.216.0,24.150.0,35.153.0,40.141.0,38.219.1,45.224.0"}
P.entries["quest:529"] = {n="Kampf um das Hügelland",s="Bei Hillsbrad setzen die Verlassenen ihren Vormarsch gegen die Menschen fort, die ihnen Widerstand leisten. Hochexekutorin Darthalia befiehlt, die Schmiede auf den Feldern von Hillsbrad zu zerstören, um die Waffenversorgung der örtlichen Bevölkerung abzuschneiden.",h="Bei Hillsbrad setzen die Verlassenen ihren Vormarsch gegen die Menschen fort, die ihnen Widerstand leisten.",kw={"schmiedelehrling","kampf um das hügelland","darthalia","die felder von hillsbrad","eisenlieferung","tarrens mühle","verringtan"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass Verringtans Ermordung und der Diebstahl der Eisenvorräte der Siedlung Süderstades abgelegenen Höfen ihre einzige Möglichkeit zur Selbstverteidigung nehmen.",["profession:Blacksmithing"]="Als Schmied wisst Ihr, dass Verringtans Schmiede den örtlichen Widerstand nährte. Ein Amboss kann eine einfallende Armee ebenso bedrohen wie ein Regiment Fußsoldaten.",["race:Undead"]="Als Verlassener wisst Ihr, dass die Zerstörung der menschlichen Schmiede helfen kann, Lordaerons südliche Grenzen zu sichern und Metall für Eure mühsamen Kriegsanstrengungen anzuhäufen."},sec={{t="Den Amboss zerschlagen",b="Im Vorgebirge des Hügellands stoßen die Verlassenen auf heftigeren Widerstand, als Hochexekutorin Darthalia erwartet hat. Die Menschen auf dem Land weigern sich, auseinanderzustieben oder vor den Todespirschern und Soldaten aus Tarrens Mühle zu kapitulieren. Die Verlassenen erfahren, dass die Bauern mit mehr als Heugabeln und Sensen kämpfen. Auf den Feldern werden sie für den Krieg bewaffnet."},{t="Die Versorgungslinie kappen",b="Am südwestlichen Rand der Felder von Hillsbrad schmieden Schmied Verringtan und seine Lehrlinge aus Roherz Klingen und Rüstungen für die Miliz. Darthalia entsendet einen Agenten, um Verringtan zu töten, seine Lehrlinge niederzumetzeln und ihre Eisenvorräte zu beschlagnahmen. Sie will die Verteidigung der Siedlung schwächen und das Metall beim späteren Angriff auf Süderstade einsetzen."}},faq={{q="Warum nimmt Hochexekutorin Darthalia gerade den Schmied ins Visier?",a="Die menschlichen Stadtbewohner und Bauern leisten dem Vormarsch der Verlassenen bewaffneten Widerstand. Darthalia erfährt, dass Schmied Verringtan und seine Lehrlinge Waffen für die Miliz schmieden und damit die Bauern bewaffnen.",al={"warum verringtan töten","schmied als ziel","verringtan quest"}},{q="Wo liegt die Schmiede?",a="Die Schmiede liegt an der Südwestseite der Felder von Hillsbrad, wo Lehrlinge inmitten von Wachen und örtlichen Patrouillen arbeiten.",al={"verringtan standort","wo ist der schmied","hillsbrad schmiede"}},{q="Wofür wird die Eisenlieferung verwendet?",a="Darthalia nimmt das Eisen an sich, um die Kriegsanstrengungen der Verlassenen zu unterstützen. Sie plant, daraus Waffen und Ausrüstung für den Angriff auf Süderstade zu schmieden.",al={"was geschieht mit dem eisen","eisenlieferung hintergrund"}},{q="Wie fügt sich dieser Schlag in den größeren Feldzug zum Kampf um das Hügelland ein?",a="Der Schlag ist die dritte Phase von Darthalias Bestreben, die menschliche Präsenz im Vorgebirge zu zerschlagen. Nachdem sie Arbeiter und Bauern auf dem Land dezimiert hat, wendet sie sich deren Führung, Logistik und Produktion zu.",al={"kampf um das hügelland questreihe","darthalias feldzug"}},{q="Gehören die Menschen auf den Feldern von Hillsbrad zum Militär der Allianz?",a="Die Menschen auf den Feldern von Hillsbrad sind hauptsächlich örtliche Bauern, Arbeiter und Stadtbewohner, keine Soldaten der Allianz. Obwohl sie Süderstade und der Allianz verbunden sind, haben sie eine behelfsmäßige Miliz gebildet, um ihre Heimat gegen die Verlassenen zu verteidigen.",al={"gehören hillsbrads bauern zur allianz","hillsbrad miliz"}},{q="Wer befiehlt diesen Schlag?",a="Hochexekutorin Darthalia befiehlt den Schlag. Sie leitet die Operationen der Verlassenen von Tarrens Mühle aus.",al={"questgeber","wer ist darthalia"}}},fx={c3d79e95={q="Wer ist Schmied Verringtan?",a="Schmied Verringtan ist der örtliche Metallarbeiter, der an der Schmiede am südwestlichen Rand von Die Felder von Hillsbrad stationiert ist. Zusammen mit seinen Lehrlingen stellt er Waffen und Werkzeuge für die lokale menschliche Bevölkerung her und befeuert so deren erbitterten Widerstand gegen den Vormarsch der Verlassenen in das Vorgebirge.",al={"wer ist verringtan","schmied verringtan","hillsbrad schmied"}}},fp="19,210,18.328.0,24.349.0,68.192.0,28.115.0,38.130.0,64.201.0,65.229.0,23.93.0"}
P.entries["quest:530"] = {n="Rache eines Ehemanns",s="In der Unterstadt schickt Raleigh Andrean Euch auf die Jagd nach dem Mann, der seine Frau ermordet hat.",h="In der Unterstadt schickt Raleigh Andrean Euch auf die Jagd nach dem Mann, der seine Frau ermordet hat.",kw={"deliah","gravierter ring","der greymane-wall","raleigh andrean","ring of scorn","silberwald","unterstadt","valdred moray"},ang={["faction:Horde"]="Als Mitglied der Horde verfolgt Ihr menschliche Gesetzlose durch den Silberwald, um die Grenzen der Unterstadt zu sichern.",["race:Undead"]="Als Untoter könnt Ihr erkennen, wie der Untod Raleighs Liebe zu seiner verstorbenen Frau abgestumpft hat, während sein Hass und sein Hunger nach Rache geblieben sind."},sec={{t="Eine bittere Erinnerung",b="Ein gravierter Ring aus dem Silberwald weckt Raleigh Andreans Erinnerungen an sein sterbliches Leben. Er erinnert sich an seinen engen Freund Valdred Moray, der Raleighs Frau Deliah ermordet hat. Die Kälte der Geißel und der Untod haben seine Trauer und Liebe abgestumpft. Doch sein Durst nach Rache bleibt, und Ihr werdet losgeschickt, um Valdred zu finden."},{t="Gerechtigkeit am Wall",b="Valdred Moray floh durch den Silberwald nach Süden und suchte Zuflucht jenseits des Greymane-Walls. Die Tore nach Gilneas blieben Flüchtlingen und Ausgestoßenen verschlossen. Am Wall gefangen, fand Valdred auf Raleighs Befehl sein Ende. Seine abgetrennten Hände wurden in die Unterstadt zurückgebracht."},{t="Kalte Andenken",b="Raleigh nimmt die Hände seines einstigen Freundes ohne Wärme oder Erleichterung entgegen. Nachdem die Rechnung beglichen ist, gibt er Deliahs Ehering zurück und nennt ihn ein nutzloses Schmuckstück. Valdred Morays abgetrennte Hände bleiben in der Unterstadt, eine bleibende Erinnerung an den Verrat."}},faq={{q="Warum will Raleigh ausgerechnet Valdreds Hände?",a="Raleigh will Valdreds Hände, weil sie das Leben seiner Frau beendet haben. Er bewahrt sie in der Unterstadt als Trophäe und Erinnerung an den Verrat seines Freundes auf.",al={"warum hände","valdreds hände","raleigh will hände"}},{q="Wo versteckt sich Valdred Moray?",a="Valdred Moray lagert im äußersten Süden des Silberwalds am Greymane-Wall, nachdem es ihm nicht gelungen ist, nach Gilneas zu gelangen.",al={"wo ist valdred","valdreds aufenthaltsort","valdred morays standort"}},{q="Warum gibt Raleigh den Ehering zurück?",a="Raleighs Verbundenheit mit Deliah ist im Untod verkümmert. Ihr Ring bedeutet ihm nichts; es ging ihm nur um Rache.",al={"warum ring weggeben","ring of scorn geschichte","warum ring wegwerfen"}},{q="Kann Valdred Moray nach Gilneas gelangen?",a="Nein. König Genn Greymane schottete Gilneas nach dem Zweiten Krieg hinter einem Wall ab, und seine Tore bleiben geschlossen. Wie viele verzweifelte Flüchtlinge sitzt Valdred dort fest.",al={"greymane-wall geschlossen","warum ist valdred vor dem wall"}},{q="Welche Quests führen zu dieser Aufgabe?",a="Die Questreihe beginnt mit The Engraved Ring im Silberwald. Sie schickt Euch zu Raleigh in der Unterstadt, wo Ihr Rache eines Ehemanns erhaltet.",al={"rache eines ehemanns questreihe","vorausgesetzte quest","vorherige quest"}}},fx={f744ed49={q="Warum will Raleigh Andrean Rache?",a="Valdred Moray war einst Raleighs enger Freund, aber er ermordete Raleighs Frau Deliah. Während der kalte Griff des Untodes Raleigh die Fähigkeit geraubt hat, um seine verlorene Liebe zu trauern oder zu klagen, bleibt der brennende Drang nach Vergeltung. Ihr Tod zu rächen und den Verrat seines ehemaligen Freundes zu bestrafen, ist der einzige Wunsch, der ihm in seinem Untod geblieben ist.",al={"warum will raleigh valdred tot sehen","raleigh andrean motiv","warum valdred moray töten"}},["71a98bea"]={q="Wer ist Valdred Moray und warum befindet er sich am Greymane-Wall?",a="Valdred Moray ist Raleigh Andreans ehemaliger Freund, der Raleighs Frau Deliah ermordete. Nachdem er das Verbrechen begangen hatte, floh er nach Süden in den Silberwald und versteckte sich an den versiegelten Toren von Der Greymane-Wall, verzweifelt darauf bedacht, in das geschlossene Königreich Gilneas zu entkommen, bevor ihn seine Vergangenheit einholt.",al={"wer ist valdred moray","warum ist valdred moray im silberwald","valdred moray greymane wall"}}},fp="19,82,15.294.0,19.273.1,14.243.1,51.147.0,30.116.0,44.113.1,32.159.0,33.142.0"}
P.entries["quest:532"] = {n="Kampf um das Hügelland",s="In der Stadt Hillsbrad greifen die Verlassenen an, um die menschliche Herrschaft zu brechen. Hochexekutorin Darthalia leitet den Angriff von Tarrens Mühle aus.",h="In der Stadt Hillsbrad greifen die Verlassenen an, um die menschliche Herrschaft zu brechen.",kw={"kampf um das hügelland","darthalia","ratsmitglieder von hillsbrad","proklamation von hillsbrad","stadtverzeichnis von hügellandhof","magistrat burnside","tarrens mühle","rathaus"},ang={["faction:Alliance"]="Für die Allianz markieren Magistrat Burnsides Tod und die Verbrennung der Stadtcharta den Untergang von Hillsbrads letzter rechtmäßiger örtlicher Regierung.",["faction:Horde"]="Für die Horde schwächt der Angriff auf das Rathaus die Fähigkeit der Allianz, örtliche Milizen zu koordinieren. Er hilft außerdem, die Südgrenze von Tarrens Mühle gegen menschliche Gegenangriffe zu sichern.",["race:Undead"]="Als Untoter seht Ihr den Feldzug der Verlassenen gegen Hillsbrads menschliche Herrschaft als Expansion und Vergeltung zugleich. Die Lebenden stellen Lordaerons Grenzen infrage."},sec={{t="Enthauptung des Stadtrats",b="Hillsbrads menschliche Verteidiger halten trotz schwerer Verluste auf den Feldern und unter den Patrouillen an ihrer Autorität fest. Hochexekutorin Darthalia weiß, dass sich die Bauern und Milizen hinter den Anführern der Stadt scharen. Deshalb schickt sie Agenten der Verlassenen ins Rathaus, um Magistrat Burnside und fünf Ratsmitglieder zu töten. Ohne sie verliert die Stadt ihre Führung."},{t="Tilgung der städtischen Aufzeichnungen",b="Darthalia will neben Hillsbrads Führung auch das Gemeinwesen der Stadt zerschlagen. Sie befiehlt Agenten, die Proklamation von Hillsbrad zu verbrennen, ein politisches Dokument, das mit der Charta und dem Stolz der Siedlung verbunden ist. Außerdem nehmen sie überlebenden Loyalisten der Allianz das Stadtregister ab. Seine amtlichen Aufzeichnungen und Bürgerlisten verschaffen dem Geheimdienst von Unterstadt einen genauen Einblick in die örtliche Bevölkerung."}},faq={{q="Wer befiehlt diesen Angriff?",a="Hochexekutorin Darthalia, die Befehlshaberin der Verlassenen in Tarrens Mühle, leitet den Angriff. Er ist Teil ihres Feldzugs gegen die Siedlungen der Allianz im Vorgebirge.",al={"wer vergibt diese quest","questgeber kampf um das hügelland","darthalia hillsbrad"}},{q="Wer ist Magistrat Burnside?",a="Magistrat Burnside führt Hillsbrads menschliche Regierung. Er befindet sich mit seinen Ratsmitgliedern im Rathaus und verteidigt die verbliebene Autorität der Stadt mit arkaner Magie.",al={"magistrat burnside","wer ist burnside","anführer von hillsbrad"}},{q="Was ist die Proklamation von Hillsbrad?",a="Die Proklamation von Hillsbrad ist eine politische Charta, die im Rathaus aufbewahrt wird. Sie verkörpert das Recht und den Bürgerstolz der Stadt, weshalb ihre Zerstörung die Moral der örtlichen Bevölkerung trifft.",al={"was ist die proklamation","geschichte der proklamation von hillsbrad","proklamation zerstören"}},{q="Warum will Darthalia das Stadtregister?",a="Das Stadtregister enthält eine Volkszählung und Verwaltungsunterlagen über Hillsbrads Bevölkerung. Seine Beschlagnahmung beraubt die überlebenden Menschen ihrer Aufzeichnungen und verrät den Verlassenen, wer sich noch in der Nähe aufhält.",al={"warum das stadtregister stehlen","stadtverzeichnis von hügellandhof","wozu dient das stadtregister"}},{q="Wo findet dieser Kampf statt?",a="Die Ziele befinden sich in und um Hillsbrads großes Rathaus. Die menschliche Siedlung liegt im südlichen Vorgebirge zwischen Tarrens Mühle und Süderstade.",al={"wo ist magistrat burnside","standort des rathauses von hillsbrad","wo sind die ratsmitglieder"}},{q="Welche Rolle spielen die Ratsmitglieder?",a="Die Ratsmitglieder von Hillsbrad helfen Magistrat Burnside, die Stadt zu regieren. Sie sind Zauberwirker, die das Rathaus und das umliegende Gelände verteidigen.",al={"ratsmitglieder von hillsbrad","wer sind die ratsmitglieder"}}},fx={["1e1aeb4f"]={q="Warum will Hochexekutorin Darthalia, dass dies erledigt wird?",a="Die Stadt Hillsbrad ist nach wiederholten Angriffen der Verlassenen in Aufruhr, aber ihre menschlichen Verteidiger weigern sich aufzugeben, solange ihre lokale Führung Bestand hat. Hochexekutorin Darthalia beabsichtigt, ihren Geist vollständig zu brechen und sie für immer aus dem Vorgebirge zu tilgen. Durch die Ermordung von Magistrat Burnside und dem Rat, die Zerstörung ihrer verehrten Hillsbrad Proclamation und die Beschlagnahmung ihrer Aufzeichnungen zielt sie darauf ab, die verbleibende Struktur zu zerschlagen, die die Felder von Hillsbrad organisiert hält.",al={"warum hillsbrad führung angreifen","darthalia motiv battle of hillsbrad","warum will darthalia burnside tot"}},acee9bfa={q="Gegen wen werdet Ihr in Hillsbrad ausgesandt?",a="Ihr seid ausgesandt, um Magistrat Burnside und fünf seiner Ratsmitglieder im Rathaus von Hillsbrad zu ermorden. Trotz schwerer Verluste auf den Feldern und in den Obstgärten organisieren Burnside und sein Rat weiterhin die lokale Verteidigung und sammeln die menschliche Bevölkerung gegen Tarrens Mühle. Die Ausschaltung ihres Magistrats und politischen Rats beraubt die Stadt ihrer regierenden Autorität.",al={"wen töten wir in hillsbrad","battle of hillsbrad ziel","wer sind magistrat burnside und rat"}},["827d131a"]={q="Wofür ist das Stadtverzeichnis von Hügellandhof?",a="Das Stadtverzeichnis von Hügellandhof ist das offizielle Bürgerregister, das die lokale Bevölkerung und das Eigentum von Hillsbrad dokumentiert. Die Beschlagnahmung beraubt die überlebenden Menschen ihrer administrativen Volkszählung und verschafft Hochexekutorin Darthalia gleichzeitig umfassende Informationen über jeden Einwohner, Grundstückseigentümer und Steuerzahler in der Siedlung.",al={"was ist hillsbrad stadtverzeichnis","hillsbrad verzeichnis zweck","warum stadtverzeichnis stehlen"}}},fp="19,124,29.344.0,24.379.0,23.158.0,27.166.0,35.162.0,42.190.0,33.150.0,33.142.0"}
P.entries["quest:5321"] = {n="Der Schläfer ist erwacht",s="Kerlonian Schattenspiel kämpft auf dem Weg von Dunkelküste zu Maestras Posten in Eschental gegen den Schlaf. Frisch aus einem langen Schlaf erwacht, trägt er das Horn der Erweckung und braucht Hilfe, um an Furbolgs und Kultisten vorbeizukommen.",h="Kerlonian Schattenspiel kämpft auf dem Weg von Dunkelküste zu Maestras Posten in Eschental gegen den Schlaf.",kw={"eschental","dark strand","dunkelküste","druide der klaue","schattenspiel","horn der erweckung","kerlonian","liladris","maestras posten","das zwielichttal"},ang={["class:Druid"]="Als Druide wisst Ihr, dass die tiefe Verbindung mit dem Smaragdgrünen Traum einen hohen Tribut fordern kann. Nach langem Winterschlaf kann der erwachende Geist nur langsam wieder zu vollem Bewusstsein gelangen.",["faction:Alliance"]="Als Reisender der Allianz helft Ihr, die Verbindung zwischen Auberdine und den entlegenen Wachposten aufrechtzuerhalten, indem Ihr Reisende sicher zwischen Dunkelküste und dem nördlichen Eschental geleitet.",["race:NightElf"]="Als Nachtelf teilt Ihr den Umbruch, den Kerlonians Volk erlebt. Tausende Druiden folgten während des Dritten Krieges dem Ruf des Horns und gewöhnen sich nun an das Tageslicht."},sec={{t="Ein schlummernder Geist",b="Kerlonian Schattenspiel ist ein Druide der Klaue, der gerade erst aus seinem Schlaf in den Grabhügeln erwacht ist. Jahrtausendelang traten Druiden durch den Smaragdgrünen Traum mit wilden Geistern in Verbindung. Der Dritte Krieg rief sie zum Erwachen, doch nach Jahrhunderten des Winterschlafs fiel es Kerlonian schwer, bei Bewusstsein zu bleiben.\n\nEr brach von Dunkelküste nach Süden auf, um Liladris Moonriver in Eschental zu treffen, doch bald übermannte ihn die Erschöpfung. Plötzliche Nickerchen lassen ihn hilflos in der Wildnis zurück, weshalb er auf ein Horn der Erweckung aus Messing und vorbeikommende Verbündete angewiesen ist, um weiterzukommen."},{t="Gefahren am Weg",b="Der Weg von Dunkelküste nach Eschental ist für Kerlonian gefährlich. Im Zwielichttal lauern verderbte Furbolgs der Blackwood am Weg. Weiter südlich in Eschental liegen Mitglieder des Kults der Dark Strand im Hinterhalt. Der Schlaf kann Kerlonian überall übermannen, wo er gerade steht, also müsst Ihr Wache halten und ihn mit dem Horn wecken."},{t="Ankunft am Außenposten",b="Kerlonian Schattenspiel erreicht Maestras Posten, nachdem er die Hinterhalte überstanden hat, und schleicht sich dann davon, um ein Fleckchen Gras für sein unterbrochenes Nickerchen zu finden. Liladris Moonriver, seine Kontaktperson, begrüßt ihn liebevoll und genervt zugleich und zeigt sich über seine Benommenheit kaum überrascht. Die wache Welt verstört viele Druiden noch immer nach der zeitlosen Ruhe des Traums."}},faq={{q="Warum schläft Kerlonian immer wieder ein?",a="Kerlonian Schattenspiel schläft immer wieder ein, weil er erst kürzlich aus Jahrhunderten des Winterschlafs im Smaragdgrünen Traum erwacht ist. Die wache Welt lässt viele Druiden orientierungslos und träge zurück, und er kann nur schwer wach bleiben, ohne geweckt zu werden.",al={"warum schläft kerlonian","warum ist er so schläfrig","einschlafender druide"}},{q="Wie weckt Ihr Kerlonian bei seinen Nickerchen?",a="Ihr könnt Kerlonian mit dem Horn der Erweckung wecken, das Ihr zu Beginn der Reise in einer Truhe neben ihm findet. Wenn er unterwegs einschläft, blast das Horn, um ihn zu wecken und seine Weiterreise zu ermöglichen.",al={"wie kerlonian wecken","kerlonian horn","horn der erweckung benutzen"}},{q="Wer wartet bei Maestras Posten auf Kerlonian?",a="Liladris Moonriver wartet bei Maestras Posten im nördlichen Eschental auf Kerlonian. Sie kennt seine ständige Schläfrigkeit und ist erleichtert, ihn wohlbehalten ankommen zu sehen.",al={"wer ist liladris","wen trifft kerlonian"}},{q="Welche Feinde greifen unterwegs an?",a="Furbolgs der Blackwood greifen nahe dem Zwielichttal an. Weiter südlich in Eschental schlagen Ausgräber, Adepten und Kultisten der Dark Strand aus den Schatten zu.",al={"hinterhalte während der eskorte","was greift kerlonian an","zwielichttal hinterhalt"}},{q="Woher stammt der Titel „Der Schläfer ist erwacht“?",a="„Der Schläfer ist erwacht“ ist ein Gruß, den Druiden der Klaue sprechen, wenn sie während des Dritten Krieges zum Dienst gerufen werden. Die Worte verweisen auf Kerlonians Wesen als erwachter Gestaltwandler.",al={"der schläfer ist erwacht zitat","druiden sprachzeile"}},{q="Was geschieht mit dem Horn, wenn Ihr zu lange braucht?",a="Das Horn der Erweckung verschwindet nach begrenzter Zeit aus Eurem Besitz. Wenn die Reise zu lange dauert oder nach einem Fehlschlag neu begonnen werden muss, holt Ersatz aus der Truhe an Kerlonians Ruheplatz.",al={"horn abgelaufen","horn der erweckung verschwunden"}}},fx={be04fcfa={q="Warum benötigt Kerlonian Schattenspiel eine Eskorte zu Maestras Posten?",a="Kerlonian reist nach Süden, um sich mit Liladris Moonriver bei Maestras Posten wieder zu vereinen, aber sein langer Schlummer im Smaragdgrünen Traum hat ihn chronisch erschöpft und desorientiert zurückgelassen. Da er nicht lange wach bleiben kann und mit der tückischen Straße nach Eschental nicht vertraut ist, kann er die Reise nicht sicher allein antreten, ohne jemanden, der ihn führt und ihn weckt, wann immer er einnickt.",al={"warum kerlonian eskortieren","kerlonian schattenspiel zweck","warum zu maestras posten"}},["9356c39d"]={q="Was ist das Horn der Erweckung?",a="Das Horn der Erweckung ist Kerlonians persönliches verzaubertes Instrument, das in einer Truhe an seinem Lagerplatz aufbewahrt wird. Da das Erwachen aus dem Smaragdgrünen Traum ihn mit überwältigender Müdigkeit kämpfen lässt, durchbricht der scharfe Ruf des Horns seine anhaltende, magisch schwere Benommenheit, um ihn wachzurütteln, wann immer er in einen Schlaf am Straßenrand fällt.",al={"horn der erweckung lore","was macht horn der erweckung","kerlonian horn"}},b8969ed3={q="Warum bittet Kerlonian Euch um Hilfe anstatt die Nachtelfen-Wächterinnen?",a="Kerlonian hat weit abseits jedes befestigten Außenpostens der Nachtelfen angehalten, isoliert in der Wildnis der südlichen Dunkelküste. Da die Patrouillen der Wächterinnen durch die Verteidigung gegen regionale Bedrohungen stark beansprucht sind, sind keine Wachen in der Nähe stationiert, um sich um einen schlummernden Druiden zu kümmern. Als reisender Abenteurer, der auf der Durchreise ist, seid Ihr seine einzige unmittelbare Hoffnung auf einen Führer und Beschützer auf dem Weg nach Eschental.",al={"warum braucht kerlonian mich","warum abenteurer kerlonian fragen","warum keine wächterinnen kerlonian"}}},fp="24,210,17.500.0,20.308.0,22.324.1,39.238.0,42.190.0,47.159.0,34.150.0,58.187.0,46.206.0"}
P.entries["quest:533"] = {n="Unterwanderung",s="In Tarrens Mühle sucht Krusk Kunde von Gol'dir, dem Orcgefangenen, den das Syndikat immer wieder verlegt. Er schickt Euch in dessen großes Lager direkt nördlich der Stadt, um alle Informationen zu beschaffen, die Ihr zurückbringen könnt.",h="In Tarrens Mühle sucht Krusk Kunde von Gol'dir, dem Orcgefangenen, den das Syndikat immer wieder verlegt.",kw={"alterac","gol'dir","hillsbrad","unterwanderung","krusk","schreiben","syndikat","tarrens mühle"},sec={{t="Kunde von Gol'dir",b="Krusk hat Kunde und Gerüchte über Gol'dir gehört, einen Orc, den das Syndikat gefangen hält. Seine menschlichen Häscher verlegen ihn immer wieder, doch die Suche hat sich auf ihr großes Lager direkt nördlich von Tarrens Mühle eingegrenzt. Krusk schickt Euch dorthin, um herauszufinden, was Ihr könnt, und es ihm zu berichten. Er fürchtet, dass sich Gol'dirs Aussichten mit jedem Tag verdüstern."},{t="Nachrichten für Krusk",b="Die Informationen, die Ihr zurückbringt, verraten Krusk, wo Gol'dir festgehalten wird. Das Lager liegt nicht weit von Tarrens Mühle entfernt. Krusk hofft, dass seine Verteidiger weniger vorbereitet sind als die Häscher, die Gol'dir und die anderen beim ersten Mal gefangen nahmen."}},faq={{q="Wen sucht Krusk?",a="Krusk sucht Gol'dir, einen Orc, den das Syndikat gefangen hält. Die Menschen des Syndikats verlegen ihn immer wieder.",al={"wen sucht krusk","wer ist goldir","wer muss gerettet werden"}},{q="Wohin schickt Krusk Euch, um die Informationen zu finden?",a="Krusk schickt Euch zum großen Lager des Syndikats direkt nördlich von Tarrens Mühle, um alle auffindbaren Informationen über Gol'dirs Aufenthaltsort zurückzubringen.",al={"wohin für unterwanderung","standort des syndikatslagers","wo ist das schreiben des syndikats"}},{q="Welche Informationen werden benötigt, um Gol'dir zu finden?",a="Alles, was Gol'dirs Aufenthaltsort verrät, kann helfen, ihn zu finden. Ihr bringt Krusk ein Schreiben des Syndikats zurück.",al={"was muss gefunden werden","welchen gegenstand sucht krusk","was ist das schreiben"}},{q="Wer hält Gol'dir gefangen?",a="Das Syndikat hält Gol'dir gefangen, und die Menschen des Syndikats verlegen ihn immer wieder.",al={"wer hat goldir gefangen genommen","wer hält den orc gefangen"}}},fp="12,179,15.305.0,14.214.1,25.102.0,50.148.0,45.102.0,23.71.0"}
P.entries["quest:535"] = {n="Valik",s="In einem Lager des Syndikats liegt Valik im Sterben, einen Feind vor sich. Valik erwartet, dass Ihr ihn tötet, bietet aber Antworten für einen Krug Süderstade-Starkbier.",h="In einem Lager des Syndikats liegt Valik im Sterben, einen Feind vor sich.",kw={"alteracgebirge","handlanger valik","southshore-starkbier","syndikat","valik"},sec={{t="Ein Handel im Sterben",b="Handlanger Valik liegt verwundet im Lager des Syndikats, und Ihr steht als Feind vor ihm. Er erwartet, dass Ihr ihn ohnehin tötet. Doch Valik bietet Antworten auf Eure Fragen, wenn Ihr einen Krug Süderstade-Starkbier ins Lager bringt. Er fragt sich sogar laut, ob Euresgleichen überhaupt trinkt."},{t="Valiks letzter Trunk",b="Valik nennt das Starkbier das Süßeste, was er je gekostet hat, obwohl der Tod wartet. Er überreicht Euch etwas, das den Toten nichts nützt. Dann fordert Valik Euch auf, es hinter Euch zu bringen."}},faq={{q="Wer ist Valik?",a="Handlanger Valik liegt verletzt und im Sterben im Lager des Syndikats.",al={"handlanger valik","wer ist valik","valik alterac"}},{q="Was will Valik?",a="Valik will, dass Ihr einen Krug Süderstade-Starkbier ins Lager des Syndikats bringt.",al={"was braucht valik","valik getränk","valik starkbier"}},{q="Was verspricht Valik im Austausch für das Starkbier?",a="Valik verspricht, Euch mitzuteilen, was Ihr wissen wollt, obwohl er erwartet, dass Ihr ihn danach tötet.",al={"valik belohnung hintergrund","was erzählt valik","valik handel"}}},fp="5,146,15.287.0,18.170.1,13.60.0,21.73.0,48.85.0"}
P.entries["quest:536"] = {n="Die Küste entlang",s="An Hillsbrads Küste überlässt Leutnant Farren Orinelle die Verteidigung Süderstades vorbeiziehenden Abenteurern. Aus Sturmwind entsandt, trinkt er lieber Bier, als zu patrouillieren, während sich Murlocs der Torn Fin am Weststrand sammeln.",h="An Hillsbrads Küste überlässt Leutnant Farren Orinelle die Verteidigung Süderstades vorbeiziehenden...",kw={"die küste entlang","farren orinelle","hillsbrad","murloc","redpath","süderstade","torn fin","weststrand"},ang={["faction:Alliance"]="Als Soldat der Allianz wisst Ihr, dass Süderstade eine wichtige Küstenfestung im Norden ist. Nachlässigkeit in der Garnison kann die Stadt gefährden.",["race:Human"]="Als Mensch könnt Ihr an Orinelles Nachlässigkeit die Kluft zwischen dem behüteten Herzen Sturmwinds und dem harten Leben in den nördlichen Siedlungen erkennen."},sec={{t="Ein ungeliebter Posten",b="Leutnant Farren Orinelle verließ die Stadtgarde von Sturmwind für einen Posten in Süderstade. Die Hafenstadt erscheint ihm trostlos, und der fischige Geruch des Hafens ist für ihn unerträglich. So verbringt er seine Tage trinkend im Gasthaus, statt an den Frontlinien zu patrouillieren. Marshal Redpath hat ihm befohlen, Süderstade vor Gefahren aus der Umgebung zu schützen, doch Orinelle heuert vorbeiziehende Söldner für diese Arbeit an."},{t="Die Bedrohung der Torn Fin",b="Der Weststrand verläuft entlang der Küste westlich von Süderstade. Orinelle verspottet die Murlocs als übergroße Fische, doch der Stamm der Torn Fin bedroht Reisen entlang der Küste und die örtliche Schifffahrt. Seine Gezeitenjäger und Orakel sammeln sich in Lagern entlang der Brandung. Dort überfallen sie jeden, der sich zu weit von den Stadtmauern entfernt, weshalb man sich ihnen stellen muss, um die Küste zu räumen."}},faq={{q="Warum kümmert sich Farren Orinelle nicht selbst um die Murlocs?",a="Farren betrachtet Süderstade als ungewollte Verbannung aus seinem früheren Leben in der Stadtgarde von Sturmwind. Verbittert über seine Versetzung und angewidert von der Küstenstadt, trinkt er lieber Bier im Gasthaus, als Murlocs zu bekämpfen, und bezahlt daher vorbeiziehende Abenteurer dafür.",al={"warum trinkt farren","farren orinelles persönlichkeit","warum abenteurer anheuern"}},{q="Wen meint Orinelle mit dem „alten Redpath“?",a="Er meint Marshal Redpath, den Marschall von Süderstade. Redpath ist für Ordnung und Verteidigung in der umkämpften Siedlung verantwortlich und erteilt militärische Befehle, denen Leutnant Orinelle auszuweichen versucht.",al={"wer ist redpath","magistrat redpath","orinelles befehlshaber"}},{q="Wo befinden sich die Murlocs der Torn Fin?",a="Die Murlocs der Torn Fin leben am Weststrand, den Küstenstränden westlich von Süderstade im Vorgebirge des Hügellands.",al={"wo sind die torn fin","murlocs fundort hillsbrad","weststrand lage"}},{q="Welche Arten von Murlocs müssen getötet werden?",a="Der Befehl verlangt, Gezeitenjäger der Torn Fin zu töten, die Frontkämpfer des Stammes, sowie Orakel der Torn Fin, die ihren Artgenossen mit Elementar- und Wassermagie helfen.",al={"murloc-ziele","welche murlocs töten","gezeitenjäger orakel"}},{q="Was geschieht, nachdem der Strand für Orinelle geräumt wurde?",a="Nach dem Einsatz erkennt Orinelle, dass er Beweise braucht, um Marshal Redpaths prüfendem Blick standzuhalten. Deshalb sucht er nach handfesten Beweisen für die getöteten Murlocs.",al={"nächste quest nach die küste entlang","die küste entlang questreihe","farrens beweis als nächstes"}},{q="Ist die Bedrohung durch die Murlocs wirklich ernst oder nur ein Vorwand?",a="Farren verspottet sie als harmlose, übergroße Fische, doch die Torn Fin sind zahlreich und aggressiv. Sie leben nahe den Anlegestellen von Süderstade und bedrohen Handelsrouten und Fischer.",al={"sind murlocs in hillsbrad gefährlich","süderstade murloc-gefahr"}}},fx={dc8aa8a8={q="Warum will Leutnant Farren Orinelle, dass die Murlocs getötet werden?",a="Leutnant Orinelle verachtet Süderstade und fühlt sich nach seiner Versetzung von der Stadtwache von Sturmwind verbannt. Sein Vorgesetzter, Marshal Redpath, befahl ihm, die Küste gegen die örtlichen Murlocs zu sichern. Farren hält den Auftrag für unter seiner Würde und verspottet die überdimensionalen Fische als triviale Aufgabe. Indem er Euch ihre Reihen dezimieren lässt, hofft er, die Illusion zu erwecken, dass er Befehle aktiv befolgt und Süderstade sicher hält, während er sein Bier trinkt und sich nach einer Versetzung zurück in die Hauptstadt sehnt.",al={"farren motiv","warum murlocs töten farren","warum will farren murlocs tot"}},["11ea9e8a"]={q="Was sind die Torn Fin-Murlocs entlang der Küste?",a="Die Torn Fin sind ein aggressiver Stamm von Murlocs, die den Weststrand und die südlichen Ufer des Vorgebirge des Hügellands befallen. In Fischersiedlungen entlang des Wassers angesiedelt, überfallen ihre Gezeitenjäger und mystischen Orakel die Küste und stellen ein ständiges Ärgernis für die Stadt Süderstade dar. Obwohl Leutnant Orinelle sie als bloße Fische verspottet, machen sie aufgrund ihrer schieren Anzahl entlang der Brandung eine ständige Plage für den örtlichen Hafen und Reisende, die sich entlang der Küste wagen.",al={"wer sind torn fin","torn fin murlocs","hillsbrad murlocs"}}},fp="14,218,19.373.0,19.348.0,58.255.0,42.184.0,39.118.0,44.157.0,51.136.1,56.170.0"}
P.entries["quest:5361"] = {n="Stammbaum",s="Klippenbehüter Langhorn schickt Euch mit Nachrichten über ungewöhnliche Zentaurenaktivitäten zum Geistwandlerposten. Sein Bruder ist dort in Desolace.",h="Klippenbehüter Langhorn schickt Euch mit Nachrichten über ungewöhnliche Zentaurenaktivitäten zum...",kw={"zentaur","das verbrannte tal","klippenbehüter langhorn","desolace","stammbaum","geistwandlerposten","nataka longhorn","steinkrallengebirge","tausend nadeln"},sec={{t="Ein Bericht für den Bruder",b="Klippenbehüter Langhorn bittet Euch, seinem Bruder Nataka am Geistwandlerposten in Desolace einen Bericht zu bringen. Seit seinem letzten Brief ist ein Jahr vergangen. Nun verhalten sich die Zentauren ungewöhnlich, und Nataka muss erfahren, was geschieht."},{t="Der Weg dorthin",b="Reist von Tausend Nadeln zum Steinkrallengebirge, nördlich des Wegekreuzes. Geht nach Westen ins Verbrannte Tal, dann nach Süden nach Desolace. Folgt der Straße nach Süden zum Geistwandlerposten."},{t="Willkommen am Posten",b="Nataka Longhorn heißt Euch am Geistwandlerposten willkommen. Er kann nicht sagen, woher Ihr Klippenbehüter kennt, aber sein Bruder scheint Euch zu vertrauen. Am Posten wird vieles gebraucht, daher schlägt Nataka vor, mit den anderen dort zu sprechen. Einer von ihnen könnte Eure Hilfe brauchen."}},faq={{q="Wen versucht Klippenbehüter Langhorn zu erreichen?",a="Klippenbehüter Langhorn versucht, seinen Bruder Nataka Longhorn am Geistwandlerposten in Desolace zu erreichen.",al={"wer ist nataka","langhorns bruder","wer erhält den bericht"}},{q="Warum schickt Klippenbehüter Langhorn gerade jetzt einen Bericht?",a="Klippenbehüter hat seit einem Jahr nicht geschrieben, und die Zentauren haben sich ungewöhnlich verhalten. Nataka muss davon erfahren.",al={"warum einen bericht schicken","bericht über zentaurenaktivitäten","grund für die nachricht"}},{q="Wo befindet sich Nataka Longhorn?",a="Nataka Longhorn ist am Geistwandlerposten in Desolace, den man über eine nach Süden führende Straße erreicht.",al={"natakas aufenthaltsort","wo ist der geistwandlerposten","wo den bericht abgeben"}},{q="Welcher Weg führt von Tausend Nadeln zum Geistwandlerposten?",a="Reist von Tausend Nadeln zum Steinkrallengebirge, nördlich des Wegekreuzes. Geht nach Westen ins Verbrannte Tal, dann nach Süden nach Desolace und folgt der Straße zum Geistwandlerposten.",al={"wie gelangt man nach desolace","weg zum geistwandlerposten","reiseweg"}}},fp="11,125,22.230.0,13.179.0,21.240.1,47.106.0,50.116.0,33.85.0,59.176.0"}
P.entries["quest:537"] = {n="Der Dunkle Rat",s="In Süderstade prüft Magistrat Henry Maleb einen Brief, der Nagaz und die Arguswacht nennt. Er fürchtet, sie könnten im Bündnis mit dem Syndikat das Land bedrohen, und schickt Euch, Nagaz und die Argusschattenmagier im Oberland zu jagen.",h="In Süderstade prüft Magistrat Henry Maleb einen Brief, der Nagaz und die Arguswacht nennt.",kw={"argusschattenmagier","arguswacht","der dunkle rat","henry maleb","nagaz","süderstade","strahnbrad","syndikat","das oberland"},sec={{t="Gesandte im Oberland",b="Nach „Weitere Mysterien“ erzählt Maleb Euch, dass der Brief von Nagaz stammt, der zur Arguswacht gehört. Er weiß nicht, was die Arguswacht ist, fürchtet aber, ein Bündnis mit dem Syndikat würde sie zu einer Bedrohung machen. Deshalb will er, dass Nagaz und die im Brief genannten Argusschattenmagier gefunden und getötet werden. Bringt ihm Nagaz’ Kopf.\n\nDurchsucht das Oberland nördlich von Strahnbrad, wo das Syndikat am stärksten ist. Maleb hofft, dass die Gesandten der Arguswacht dort sind."},{t="Malebs Schlussfolgerungen",b="Magistrat Henry Maleb beunruhigt der Gedanke, dass eine Gruppe wie die Arguswacht das Syndikat lenken könnte. Nagaz, sagt er, war nur der Diener eines anderen. Der Einfluss der Arguswacht könnte tief über den gesamten Kontinent oder sogar die ganze Welt reichen."}},faq={{q="Wer schickt Euch auf die Jagd nach Nagaz?",a="Magistrat Henry Maleb in Süderstade schickt Euch auf die Jagd nach Nagaz. Er hat den Brief gelesen, den Ihr ihm gebracht habt.",al={"wer vergibt der dunkle rat","der dunkle rat questgeber","wo der dunkle rat annehmen"}},{q="Wo befinden sich Nagaz und die Argusschattenmagier?",a="Maleb fordert Euch auf, das Oberland nördlich von Strahnbrad zu durchsuchen, wo das Syndikat am stärksten ist.",al={"wo ist nagaz","argusschattenmagier fundort","wo ist das oberland"}},{q="Was ist die Arguswacht?",a="Maleb weiß nicht, was die Arguswacht ist. Er weiß nur, dass Nagaz ihr angehört und dass sie im Bündnis mit dem Syndikat eine Bedrohung sein muss.",al={"wer ist die arguswacht","was ist die arguswacht","arguswacht hintergrundgeschichte"}},{q="Was geschieht davor?",a="Dies folgt auf „Weitere Mysterien“, als Ihr Maleb den entschlüsselten Brief gebracht habt.",al={"voraussetzung für den dunklen rat","vorherige quest","welche quest kommt davor"}}},fp="12,223,21.441.0,20.223.1,26.95.0,51.93.0,23.142.0,25.77.0"}
P.entries["quest:5381"] = {n="Hand von Iruxos",s="In Schattenflucht schickt Euch Taiga Klugmähne zur Festung Donneraxt, um einen Dämonenkasten zu holen. Die Burning Blade nutzt die darin verwahrte Hand von Iruxos, um bei Mannorocs Koven Portale für Dämonen zu öffnen.",h="In Schattenflucht schickt Euch Taiga Klugmähne zur Festung Donneraxt, um einen Dämonenkasten zu holen.",kw={"burning blade","dämonenkasten","dämonenspitzhacke","hand von iruxos","mannorocs koven","roter kristall","schattenflucht","taiga klugmähne","festung donneraxt"},sec={{t="Der Kasten in der Festung",b="Taiga Klugmähne will den Durchgang der Dämonen in unsere Welt unterbinden. Sie gibt Euch eine Dämonenspitzhacke für den roten Kristall in der Festung Donneraxt. Benutzt sie, um zum Dämonenkasten zu gelangen, und bringt dann den Kasten und die Spitzhacke zu Taiga in Schattenflucht zurück."}},faq={{q="Wer bittet um den Dämonenkasten?",a="Taiga Klugmähne bittet Euch in Schattenflucht um den Dämonenkasten.",al={"questgeber","wer startet hand von iruxos","wo gibt es die quest"}},{q="Was ist die Hand von Iruxos?",a="Die Hand von Iruxos ist ein mächtiger Gegenstand, der im Dämonenkasten verwahrt wird. Bei Mannorocs Koven nutzt die Burning Blade sie, um Portale für Dämonen zu öffnen.",al={"was ist die hand von iruxos","hand von iruxos artefakt","was bewirkt die hand"}},{q="Wo ist der Dämonenkasten?",a="Der Dämonenkasten liegt in der Festung Donneraxt, hinter einem roten Kristall.",al={"wo ist der dämonenkasten","dämonenkasten fundort","dämonenkasten finden"}},{q="Wie gelangt Ihr zum Dämonenkasten?",a="Taiga gibt Euch eine Dämonenspitzhacke, die Ihr am roten Kristall in der Festung Donneraxt benutzen sollt.",al={"wie bekommt man den dämonenkasten","dämonenspitzhacke benutzen","roter kristall donneraxt"}}},fp="14,186,23.236.0,27.64.0,27.138.0,23.65.0,32.83.0"}
P.entries["quest:5386"] = {n="Der Fang des Tages",s="Am Geistwandlerposten sehnt sich Nataka Longhorn nach gekochtem Fisch. Sie preist die Trolle von Schattenflucht als die besten Fischfänger, doch die Aktivitäten der Zentauren halten sie von der Reise ab. Sie bittet Euch, ihr zwei Bloodbelly fish zu bringen.",h="Am Geistwandlerposten sehnt sich Nataka Longhorn nach gekochtem Fisch.",kw={"bloodbelly fish","der fang des tages","zentauren","desolace","geistwandlerposten","jinar'zillen","nataka longhorn","schattenflucht"},sec={{t="Ein Geschmack der Küste",b="Am Geistwandlerposten hat Nataka Longhorn schon lange keinen gekochten Fisch mehr gegessen. Sie vertraut darauf, dass die Trolle von Schattenflucht die besten Fische fangen, doch die Aktivitäten der Zentauren lassen ihr wenig Zeit zum Reisen. Daher bittet sie Euch, mit Jinar'Zillen, dem örtlichen Fischer des Dorfes, zu sprechen und zwei Bloodbelly fish mitzubringen. Sie sind Natakas Lieblingsfische. Die Straße südlich des Postens biegt nach Westen zum Trolldorf ab."}},faq={{q="Wer sucht nach Bloodbelly fish?",a="Nataka Longhorn am Geistwandlerposten in Desolace sucht nach Bloodbelly fish. Sie sind seine Lieblingsfische.",al={"wer vergibt der fang des tages","nataka longhorn quest"}},{q="Warum kann Nataka Longhorn die Fische nicht selbst besorgen?",a="Die Aktivitäten der Zentauren lassen Nataka wenig Zeit für die Reise zu den Trollen.",al={"warum kann nataka nicht fort","warum braucht nataka hilfe"}},{q="Wo sind die Bloodbelly fish zu finden?",a="Nataka schickt Euch nach Schattenflucht, um mit dem örtlichen Fischer Jinar'Zillen zu sprechen.",al={"wo bloodbelly fish bekommen","jinar'zillen fundort"}},{q="Wie gelangt Ihr vom Geistwandlerposten nach Schattenflucht?",a="Die Straße vom Geistwandlerposten nach Süden biegt nach Westen ab und führt zum Trolldorf.",al={"weg nach schattenflucht","wie zum trolldorf gelangen"}},{q="Wie viele Bloodbelly fish möchte Nataka haben?",a="Nataka möchte zwei Bloodbelly fish haben.",al={"wie viele fische","bloodbelly fish anzahl"}}},fp="16,242,20.408.0,35.103.0,47.77.0,39.87.0,59.80.0,42.33.0"}
P.entries["quest:539"] = {n="Kampf um das Hügelland",s="Am Azurschacht greifen Streitkräfte der Horde an, um Eisenlieferungen an die Waffenkammern der Allianz zu unterbinden. Hochexekutorin Darthalia hat befohlen, Vorarbeiter Bonds und seine Mannschaft zu töten.",h="Am Azurschacht greifen Streitkräfte der Horde an, um Eisenlieferungen an die Waffenkammern der Allianz zu...",kw={"azurelode","bonds","darthalia","hillsbrad","eisen","bergarbeiter","süderstade","tarrens mühle","unterstadt"},ang={["faction:Horde"]="Als Mitglied der Horde verringert Ihr durch die Störung von Hillsbrads wichtigster Metallversorgung den Druck auf die Front bei Tarrens Mühle und erschwert menschlichen Truppen den Ersatz ihrer Ausrüstung.",["profession:Mining"]="Als Bergarbeiter könnt Ihr erkennen, warum die reichen Eisenadern des Azurschachts jene in Konflikte verwickeln, die wertvolles Erz suchen.",["race:Undead"]="Als Untoter sichert Ihr durch die Einnahme des Azurschachts Eisen für die Deathguard und stellt die menschliche Industrie in den Dienst der Bewaffnung von Sylvanas’ Armeen in ganz Lordaeron."},sec={{t="Die Eisenzufuhr unterbrechen",b="Hochexekutorin Darthalia erkannte den Azurschacht als entscheidend für die Stärke der Menschen, nachdem die Horde bei früheren Überfällen das Stadtverzeichnis von Hügellandhof erbeutet hatte. Die Mine liegt unmittelbar südlich der Felder von Hillsbrad. Dort fördern Arbeiter weiterhin hochwertiges Eisenerz für die Waffenschmiede und Waffenkammern der Allianz. Bleibt die Mine in Betrieb, kann Süderstade aufrüsten und seine Garnisonen verstärken, was die früheren Siege von Tarrens Mühle zunichtemachen würde."},{t="Eine unmissverständliche Botschaft",b="Darthalia befiehlt den Streitkräften der Horde, Vorarbeiter Bonds, den menschlichen Aufseher, und einen großen Teil seiner Arbeiter zu töten. Der Angriff dringt bis in die dunklen Schächte der Mine vor, um die Produktion zum Erliegen zu bringen. Süderstade erhält eine klare Warnung: Die Verlassenen können seine Nachschublinien und abgelegenen Arbeitslager angreifen."},{t="Beute für die Dark Lady",b="Die Streitkräfte von Sylvanas Windläufer wollen die reichen Erzadern der Mine auch für ihre eigenen Gießereien nutzen. Tarrens Mühle braucht im Krieg in ganz Lordaeron einen stetigen Metallnachschub für Waffen und Plattenrüstungen. Das Erz kann einen einstigen Besitz der Menschen in eine Waffenquelle für die Verlassenen verwandeln."}},faq={{q="Warum ist der Azurschacht für die Verlassenen so wichtig?",a="Der Azurschacht liefert hochwertiges Eisenerz an die Waffenkammern der Allianz. Seine Einnahme entzieht Garnisonen wie Süderstade das Schmiedematerial und bringt das Erz in die Hände von Unterstadt, um die Streitkräfte der Verlassenen auszurüsten.",al={"warum azurelode angreifen","zweck des azurschachts","warum die mine angreifen"}},{q="Wer ist Vorarbeiter Bonds?",a="Vorarbeiter Bonds ist der menschliche Aufseher der Ausgrabung von Azurelode. Er leitet die Bergarbeiter und kann standhafte zwergische Verteidiger zu Hilfe rufen, wenn er tief in den unteren Kammern in die Enge getrieben wird.",al={"vorarbeiter bonds","wer ist bonds","wer leitet die mine"}},{q="Wo liegt der Azurschacht?",a="Der Azurschacht liegt in den Hügeln südlich der Felder von Hillsbrad, westlich von Süderstade entlang der Küstenklippen.",al={"wo ist der azurschacht","lage von azurelode","wie die mine finden"}},{q="Wie erfuhr Darthalia vom Betrieb der Mine?",a="Beim Durchsehen des Stadtverzeichnisses von Hügellandhof erfuhr Darthalia, dass die Mine in Betrieb und für die Nachschublinien von entscheidender Bedeutung war. Agenten der Horde hatten das Verzeichnis bei früheren Angriffen auf menschliche Siedlungen erbeutet.",al={"woher wusste darthalia davon","stadtverzeichnis mine","informationen über hillsbrad"}},{q="Was geschieht, nachdem Vorarbeiter Bonds getötet wurde?",a="Nachdem die Mine lahmgelegt und ihre Ressourcen für die Verlassenen beansprucht wurden, weitet Hochexekutorin Darthalia die Offensive gegen Hillsbrads verbliebene Infrastruktur aus und rückt näher an Süderstade heran.",al={"wie geht der kampf um das hügelland weiter","nach bonds’ tod","folgen der quest"}},{q="Verteidigt die Allianz die Mine?",a="Ja. Bewaffnete Wachen der Allianz bewachen den Eingang, und menschliche Bergarbeiter arbeiten in den Schächten. Vorarbeiter Bonds kann tief in den Stollen auch zähe zwergische Verstärkung zu Hilfe rufen.",al={"minenwachen","allianzpräsenz in azurelode","zwerge in der mine"}}},fp="19,153,24.387.0,18.280.0,24.257.1,51.207.0,21.171.0,36.106.0,55.186.0,42.195.1,34.161.0"}
P.entries["quest:54"] = {n="Meldung in Goldhain",s="Marschall McBride schickt Euch mit Depeschen für Marschall Dughan nach Süden nach Goldhain. Jenseits des geschützten Tals von Nordhain schenken Sturmwinds Adlige dem Wald von Elwynn immer weniger Beachtung.",h="Marschall McBride schickt Euch mit Depeschen für Marschall Dughan nach Süden nach Goldhain.",kw={"acting deputy","wald von elwynn","goldhain","marschall dughan","marschall mcbride","nordhain","meldung in goldhain","stormwind marshals"},ang={["faction:Alliance"]="Da Sturmwinds Armee andernorts eingesetzt wird, ruht Elwynns Verteidigung zunehmend auf frisch ernannten Stellvertretern und Freiwilligen wie Euch.",["race:Human"]="Als Mensch erhaltet Ihr mit Eurer Versetzung von Nordhain nach Goldhain erstmals echte Anerkennung durch Sturmwinds Militär."},sec={{t="Von Nordhain in den weiten Wald",b="Ihr habt Euch gegen die Gefahren in Nordhain bewährt, und McBride entlässt Euch aus der Wache des Tals. Seine Versetzungspapiere führen Euch durch die Grenztore und die Straße hinab nach Goldhain. Von dort aus erstrecken sich Eure Pflichten über den weiteren Wald."},{t="Die Bürde der Marschälle",b="Marschall Dughan wartet in Goldhain, um McBrides Depeschen entgegenzunehmen und Euch zum Acting Deputy der Sturmwind Marshals zu ernennen. Seine Begrüßung birgt eine düstere Warnung: Verglichen mit den Gefahren, die Elwynn durchstreifen, ist Nordhain ein friedlicher Garten. Sturmwinds königliches Heer ist in die politischen Machenschaften ferner Adliger verstrickt, statt die Heimat zu bewachen."}},faq={{q="Wer ist Marschall Dughan?",a="Marschall Dughan befehligt die Sturmwind Marshals in Goldhain. Er beaufsichtigt die Verteidigung und die Patrouillen im Wald von Elwynn.",al={"wer ist marschall dughan","wo ist dughan","dughans aufgabe"}},{q="Warum werden Rekruten nach Goldhain geschickt?",a="Wenn Rekruten die Schwierigkeiten im Nordhaintal bewältigt haben, schickt Marschall McBride jene, die sich bewähren, nach Süden nach Goldhain. Die dortigen Gefahren erstrecken sich über den gesamten Wald von Elwynn.",al={"warum nach goldhain gehen","nordhain verlassen","nächster schritt nach nordhain"}},{q="Was bedeutet der Acting Deputy Status?",a="Acting Deputy ist ein Rang, der im Felddienst mit Marschall McBrides Papieren verliehen wird. Er nimmt vielversprechende Rekruten in die Sturmwind Marshals auf, damit sie helfen, das Gesetz zu wahren.",al={"acting deputy","was ist der acting deputy status","bedeutung des stellvertreterstatus"}},{q="Wo ist Sturmwinds Armee?",a="Marschall Dughan sagt, dass der Großteil von Sturmwinds stehendem Heer fort ist. Die Hofadligen halten es mit ihren Aufgaben beschäftigt, statt es in den heimischen Ortschaften und auf den Bauernhöfen patrouillieren zu lassen.",al={"wo ist sturmwinds armee","sturmwinds armee fehlt","warum ist elwynn ungeschützt"}},{q="Wer ist Marschall McBride?",a="Marschall McBride befehligt die Garnison in der Abtei von Nordhain. Er bildet neue Verteidiger aus und schickt jene, die sich bewähren, an die Front in Goldhain.",al={"wer ist mcbride","mcbrides aufgabe"}},{q="Wie findet Ihr von Nordhain nach Goldhain?",a="Folgt der Hauptstraße nach Süden aus dem Nordhaintal hinaus, durch die Grenztore und ins Herz des Walds von Elwynn. Goldhain liegt an der Straße.",al={"straße nach goldhain","wie nach goldhain gelangen","richtung nach goldhain"}}},fp="19,179,37.241.0,26.323.0,22.110.0,35.180.0,36.147.0,28.161.0,23.151.0,42.137.0"}
P.entries["quest:540"] = {n="Wissen bewahren",s="In Süderstade schickt Euch Meister der Lehren Dibbs in die Ruinen von Alterac, um Bücher vor den dort angesiedelten Ogern zu retten. Ein abgenutzter Lederband ist besonders wichtig: Er enthält The Arm of Gri'lek, ein Werk über uraltes Trollwissen.",h="In Süderstade schickt Euch Meister der Lehren Dibbs in die Ruinen von Alterac, um Bücher vor den dort...",kw={"arm of gri'lek","vorgebirge des hügellands","meister der lehren dibbs","oger","wissen bewahren","die ruinen von alterac","süderstade","trollwissen"},sec={{t="Bücher in Ogerhänden",b="Meister der Lehren Dibbs fürchtet um die Bücher, die in den Ruinen von Alterac zurückgeblieben sind, wo nun Oger hausen. Ihr sucht nach den Folianten, die sie geplündert haben, und bergt, was Ihr könnt. Dibbs würde ebenfalls zur Suche in die Berge steigen, fürchtet aber, seine alten Knochen würden die Reise nicht überstehen."},{t="Der Arm von Gri'lek",b="Unter den Folianten möchte Meister der Lehren Dibbs vor allem ein abgenutztes Lederbuch mit The Arm of Gri'lek finden. Dibbs ist entschlossen, das darin enthaltene uralte Trollwissen zu ergründen. Die Ruinen von Alterac waren der letzte bekannte Aufbewahrungsort eines unversehrten Exemplars."}},faq={{q="Wer bietet diese Quest an und wo?",a="Meister der Lehren Dibbs bietet sie in Süderstade an.",al={"wer vergibt wissen bewahren","wo ist meister der lehren dibbs","wissen bewahren questgeber"}},{q="Nach welchem bestimmten Buch sucht Meister der Lehren Dibbs?",a="Dibbs sucht den abgenutzten Lederband mit The Arm of Gri'lek, einem Werk über uraltes Trollwissen.",al={"welches buch will dibbs","welcher foliant wird benötigt","arm of gri'lek buch"}},{q="Wo befinden sich die Bücher?",a="Die Bücher befinden sich in den Ruinen von Alterac, wo Oger sich niedergelassen und Folianten geplündert haben. Die Ruinen waren der letzte bekannte Aufbewahrungsort eines unversehrten Exemplars von The Arm of Gri'lek.",al={"wo die folianten finden","wo sind die ruinen","wo ist the arm of gri'lek"}},{q="Warum möchte Dibbs Bücher aus Alterac haben?",a="Dibbs fürchtet, was die Oger mit den kostbaren Büchern in den Ruinen anstellen könnten, und möchte retten, was sich bergen lässt. Am meisten möchte Dibbs The Arm of Gri'lek haben, um das darin enthaltene uralte Trollwissen zu ergründen.",al={"warum wissen bewahren","warum bücher aus alterac","was will dibbs mit büchern"}}},fp="20,217,19.256.0,18.210.0,41.41.0,53.96.0,28.157.0,39.185.0"}
P.entries["quest:541"] = {n="Kampf um das Hügelland",s="In Hillsbrad richtet sich der Feldzug der Verlassenen nun gegen Dun Garok. Hochexekutorin Darthalia entsendet Champions der Horde, um die Zwergengarnison zu zerschlagen, die den einheimischen Menschen hilft, und ihren Kommandanten Captain Ironhill zu töten.",h="In Hillsbrad richtet sich der Feldzug der Verlassenen nun gegen Dun Garok.",kw={"kampf um das hügelland","captain ironhill","dun garok","hochexekutorin darthalia","gebirgsjäger","schütze","tarrens mühle","thoradinswall"},ang={["faction:Horde"]="Ein Schlag gegen Dun Garok schneidet die militärischen Verstärkungen aus Eisenschmiede ab, die den bedrängten Menschen von Süderstade helfen sollen.",["race:Dwarf"]="Dun Garok zeigt Eisenschmiedes Treue zu seinen menschlichen Verbündeten. Die Zwerge halten der Belagerung durch die Verlassenen stand, um die nördliche Grenze zu halten.",["race:Undead"]="Für die Verlassenen sichert die Vernichtung der Zwergengarnison den Südosten Lordaerons. Sie erschwert einer Vorhut der Allianz den Marsch nach Süden durch Thoradinswall."},sec={{t="Die Allianz auf dem Prüfstand",b="Hochexekutorin Darthalia hat den menschlichen Bauern und der Stadtmiliz im gesamten Vorgebirge bereits zugesetzt. Nun richtet sie den Zorn von Tarrens Mühle gegen die Truppen aus Eisenschmiede. Zwergensoldaten haben für Süderstade zu den Waffen gegriffen und stärken so die menschliche Präsenz in Lordaeron. Darthalia betrachtet dieses Bündnis als Hindernis. Sie will der Allianz zeigen, dass Hilfe für die überlebenden Menschen Verwüstung nach sich zieht."},{t="Der Fall von Dun Garok",b="Dun Garok schmiegt sich im südöstlichen Hillsbrad an Thoradinswall. Disziplinierte Gebirgsjäger halten die befestigte Festung, unterstützt von geübten Schützen und kampferprobten Priestern. Die Streitkräfte der Horde müssen diese Verteidiger durchbrechen und Captain Ironhill töten. Sein Tod zerschlägt Eisenschmiedes vorgeschobene Kommandostruktur in der Region und lässt die verbliebenen menschlichen Enklaven isoliert zurück."}},faq={{q="Warum kämpfen Zwerge in Hillsbrad?",a="Eisenschmiede hat seine Soldaten nach Norden nach Dun Garok entsandt, weil die Zwerge die Allianz unterstützen. Sie wollen den überlebenden Menschen in Süderstade und Hillsbrad gegen die Ausbreitung der Verlassenen beistehen.",al={"warum gibt es zwerge in hillsbrad","zwerge dun garok","warum helfen zwerge den menschen"}},{q="Wo liegt Dun Garok?",a="Dun Garok liegt im Südosten des Vorgebirges des Hügellands und ist in die Fundamente von Thoradinswall gebaut.",al={"dun garok lage","wo ist dun garok","dun garok finden"}},{q="Wer ist Captain Ironhill?",a="Captain Ironhill befehligt die Zwergengarnison von Dun Garok. Er hält ihre Gebirgsjäger organisiert und für Kämpfe in der Region bereit.",al={"captain ironhill","wer ist ironhill","dun garok anführer"}},{q="Wer gibt diesen Befehl?",a="Hochexekutorin Darthalia, die in Tarrens Mühle stationierte Befehlshaberin der Verlassenen, befiehlt den Angriff auf die Zwergengarnison.",al={"wer gibt die quest","questgeberin darthalia","darthalia hillsbrad"}},{q="Was geschieht, wenn die Streitkräfte der Horde hier scheitern?",a="Darthalia warnt, dass Versagen nicht geduldet wird. Wer Dun Garok nicht bezwingen kann, wird nach Tirisfal zurückgeschickt, um Gräber auszuheben.",al={"was passiert bei versagen","darthalias drohung","folgen"}},{q="Warum ist Dun Garok so schwer zu stürmen?",a="Dun Garok wird von ausgebildeten Zwergensoldaten, Schützentrupps und heiligen Priestern gehalten. Sie kämpfen in engen Formationen in den befestigten unterirdischen Anlagen und im erhöht gelegenen Bunker.",al={"dun garok elite","warum ist dun garok schwer","dun garok verteidigung"}}},fx={b055c9ea={q="Warum will Hochexekutorin Darthalia Dun Garok angreifen lassen?",a="Die Verlassenen führen einen umfassenden Feldzug, um die Kontrolle der Menschen über das Vorgebirge des Hügellands zu brechen, doch die Zwerge von Eisenschmiede haben eingegriffen, um ihre Verbündeten der Allianz zu stärken. Hochexekutorin Darthalia beabsichtigt, den Widerstand der Allianz zu brechen, indem sie ihnen die Kosten für die Verteidigung von Süderstade vor Augen führt. Durch die Zerstörung ihrer Kaserne in Dun Garok und die Tötung ihres Kommandanten will sie den menschlichen Nachschub abschneiden und die Region vollständig unter die Herrschaft der Dunklen Fürstin bringen.",al={"warum dun garok angreifen","darthalias motiv","warum die zwerge töten"}}},fp="19,199,20.386.0,21.356.0,38.177.0,27.98.0,24.125.0,21.116.0,39.136.0,41.163.0"}
P.entries["quest:5421"] = {n="Fisch im Eimer",s="In Schattenflucht überlässt Jinar'Zillen das Sammeln der Schalentiere anderen. Die Fallen liegen unter den Docks, und er bietet für je fünf Schalentiere einen Bloodbelly-Fisch.",h="In Schattenflucht überlässt Jinar'Zillen das Sammeln der Schalentiere anderen.",kw={"bloodbelly-fisch","desolace","fisch im eimer","jinar'zillen","schattenflucht","schalentiere"},sec={{t="Von anderen erledigt",b="Jinar'Zillen hat viele Schalentierfallen unter den Docks von Schattenflucht. Er möchte lieber, dass jemand anderes sie leert, und bietet für je fünf herbeigebrachte Schalentiere einen feinen Bloodbelly-Fisch."}},faq={{q="Wer bietet diesen Tausch an?",a="Jinar'Zillen bietet den Tausch in Schattenflucht in Desolace an.",al={"wer vergibt fisch im eimer","jinar'zillen","questgeber"}},{q="Wo sind die Schalentierfallen?",a="Die Schalentierfallen liegen unter den Docks von Schattenflucht.",al={"standort der fallen","wo findet man schalentiere","schalentierfallen"}},{q="Warum möchte Jinar'Zillen, dass jemand anderes die Schalentiere sammelt?",a="Jinar'Zillen tut am liebsten so wenig wie möglich, also verspricht er jedem eine Gegenleistung, der die Fallen leert.",al={"warum braucht er schalentiere","jinar'zillens beweggrund"}},{q="Was gibt Jinar'Zillen als Gegenleistung für die Schalentiere?",a="Jinar'Zillen gibt für je fünf Schalentiere einen feinen Bloodbelly-Fisch.",al={"fisch im eimer belohnung","was bekommt man"}}},fp="16,166,25.196.0,22.65.0,30.62.0,64.109.0,56.69.0"}
P.entries["quest:543"] = {n="Die Tiara von Perenolde",s="Graf Remington Kronenbrunn schickt Söldner wegen eines verlorenen Erbstücks in die Ruinen von Alterac. Die Tiara von Perenolde schmückte einst Alteracs Königsfamilie und befindet sich nun bei einem Oger-Magier.",h="Graf Remington Kronenbrunn schickt Söldner wegen eines verlorenen Erbstücks in die Ruinen von Alterac.",kw={"alterac","crushridge","grel'borg","geizhals","perenolde","kronenbrunn","sturmwind","tiara"},ang={["faction:Alliance"]="Wenn Ihr nach Norden ins gesetzlose Alteracgebirge reist, könnt Ihr gefährliche Crushridgeoger vertreiben und unbezahlbare historische Artefakte für Sturmwinds Adel bergen.",["race:Dwarf"]="Eisenschmiedes Juweliermeister fertigten die Tiara. Ihre feine Arbeit überdauerte selbst den Fall eines Menschenkönigreichs.",["race:Human"]="Für die Menschen der Allianz erinnert die Tiara an Alteracs Verrat während des Zweiten Krieges, als dessen menschliche Königsfamilie die Horde gegen ihresgleichen unterstützte."},sec={{t="Ein Relikt des gefallenen Königreichs",b="Alteracs Königsfamilie trug eine mit Smaragden besetzte Tiara, gefertigt von zwergischen Juweliermeistern in Eisenschmiede. Während des Zweiten Krieges verriet König Aiden Perenolde die Große Allianz und schloss sich der Orcischen Horde an. Alterac wurde erobert und zerfiel. Als Alterac City fiel, verschwanden viele königliche Schätze im verschneiten Schutt des Alteracgebirges."},{t="Der Geizhals in den Ruinen",b="Grel'borg der Geizhals, ein Oger-Magier unter den Crushridgeogern, besitzt die Tiara in den Ruinen. Er durchsucht das zerbrochene Mauerwerk nach Schmuckstücken und herrenlosen Reichtümern. Graf Remington Kronenbrunn, ein Sammler historischer Kuriositäten in Sturmwind, erfährt, dass die Tiara erhalten geblieben ist. Er heuert Söldner an, die ins Ogergebiet eindringen, Grel'borg besiegen und das Juwel in seine Galerie zurückbringen sollen."}},faq={{q="Wer war die Familie Perenolde?",a="Die Perenoldes waren die Königsfamilie von Alterac, dem Menschenreich im Norden. Während des Zweiten Krieges arbeitete König Aiden Perenolde mit der einfallenden Orcischen Horde zusammen, um sein Königreich zu verschonen. Die Allianz von Lordaeron deckte seinen Verrat auf, besetzte Alterac, schaffte dessen Thron ab und überließ das Königreich der Gesetzlosigkeit und dem Verfall.",al={"haus perenolde","wer waren die perenoldes","perenolde hintergrundgeschichte"}},{q="Wer fertigte die Tiara von Perenolde?",a="Juweliermeister in Eisenschmiede fertigten die Tiara und besetzten sie mit Smaragden. Sie war ein Zeichen von Adel und Reichtum für Alteracs Herrscherfamilie.",al={"ursprung der tiara","wer fertigte die tiara von perenolde"}},{q="Wer besitzt die Tiara jetzt?",a="Grel'borg der Geizhals besitzt die Tiara. Der Oger-Magier durchstöbert die verschneiten Ruinen von Alterac nach Schätzen, die in der zerstörten Menschenstadt zurückblieben.",al={"grelborg","wer besitzt die tiara von perenolde","fundort der tiara"}},{q="Warum will Graf Remington Kronenbrunn die Tiara haben?",a="Graf Remington Kronenbrunn will die Tiara für seine Privatsammlung haben. Der wohlhabende Adlige und Altertumssammler lebt in Sturmwind und heuert Söldner an, um verlorene Schätze aus gefährlichen Orten in ganz Azeroth zu bergen.",al={"remington kronenbrunn beweggrund","warum die tiara beschaffen"}},{q="Wo liegen die Ruinen von Alterac?",a="Die Ruinen von Alterac liegen im nördlichen Alteracgebirge, nördlich des Vorgebirges des Hügellands und der Region Durnholde. Crushridgeoger und Gesetzlose des Syndikats machen die verlassene Stadt nun unsicher.",al={"lage der ruinen von alterac","wo liegt alterac"}},{q="Was geschieht mit der Tiara, nachdem Ihr sie geborgen habt?",a="Nachdem Graf Kronenbrunn das schlammige, angelaufene Erbstück erhalten hat, reinigen und polieren es professionelle Restauratoren. Dann stellt er es als Prunkstück seiner Sammlung aus.",al={"tiara abgeben","schicksal der tiara"}}},fx={["19149d4d"]={q="Was ist die Tiara von Perenolde?",a="Die Tiara von Perenolde ist ein unschätzbares königliches Erbstück, das von den meisterhaften zwergischen Juwelieren in Eisenschmiede gefertigt wurde. Mit exquisiten Smaragden besetzt, zierte sie einst die Häupter des regierenden Adels von Alterac. Als das verräterische Königreich zusammenbrach und in Trümmern versank, verschwand die Tiara in der Asche der Geschichte, begehrt von Sammlern aufgrund ihrer extravaganten Schönheit und ihrer historischen Abstammung.",al={"was ist die tiara von perenolde","hintergrund der tiara von perenolde","perenoldes tiara"}},e2bd82b9={q="Warum engagiert Graf Kronenbrunn einen Abenteurer, anstatt seine eigenen Leute zu schicken?",a="Graf Remington Kronenbrunn ist ein penibler Adliger aus Sturmwind, der sich Sorgen um die makellosen Aufschläge seiner maßgeschneiderten Hose macht – er ist kaum ein Mann, der in die eisige Wildnis nach Norden ziehen möchte. Zudem liegt Alterac weit außerhalb der Gerichtsbarkeit und Reichweite der Stadtwache von Sturmwind und ist von feindseligen Ogern und Gesetzlosen überrannt. Die Sicherung eines solchen Erbstücks in entlegenen Ruinen erfordert einen abgehärteten Abenteurer, der bereit ist, gefährliche, schmutzige Arbeit für Gold zu erledigen.",al={"warum ich für die tiara","warum nicht die königliche wache","warum braucht mich kronenbrunn"}}},fp="19,179,27.335.0,22.369.0,29.326.0,29.135.0,24.139.0,50.213.0,39.188.0,47.157.1"}
P.entries["quest:544"] = {n="Gefängnis-Einbruch",s="Magus Wordeen Voidglare steht bei seinen Forschungen in Tarrens Mühle vor einer Krise. Vier Verlassene flohen vor Monaten mit Artefakten aus einem gesicherten Gewölbe aus Unterstadt, und Sylvanas verlangt deren Rückgabe.",h="Magus Wordeen Voidglare steht bei seinen Forschungen in Tarrens Mühle vor einer Krise.",kw={"alina","blutstein","dalaran","dermot","kegan darkmar","lordamere-internierungslager","ricter","tarrens mühle","wordeen voidglare"},sec={{t="Diebe der Dunklen Fürstin",b="Magus Wordeen Voidglare kam nach Tarrens Mühle, um zu forschen. Nun fordert eine Krise seine Aufmerksamkeit. Vier Verlassene wandten sich von ihren Brüdern ab und bestahlen die Dunkle Fürstin. Sie brachen in ein gesichertes Gewölbe ein und nahmen vier Artefakte mit, die die Apotheker für bestimmte Studien brauchen. Sylvanas verlangt deren Rückgabe."},{t="Das Internierungslager",b="Die Diebe flohen aus Unterstadt nach Dalaran. Die dortigen Zauberer stellten sie im Lordamere-Internierungslager unter Quarantäne. Ihr werdet ausgesandt, die Verräter aufzuspüren, die Artefakte zurückzuholen und Euch bei Voidglare in Tarrens Mühle zu melden. Es sind vier: ein Blutsteinkeil, ein Marmor, ein Splitter und ein Oval. Dermot hat den Keil, Ricter die Murmel, Alina den Splitter und Kegan Darkmar das Oval."}},faq={{q="Wer ist Magus Wordeen Voidglare?",a="Magus Wordeen Voidglare kam nach Tarrens Mühle, um zu forschen. Nun steht er vor einer Krise wegen vier Artefakten, die der Dunklen Fürstin gestohlen wurden.",al={"magus voidglare","wordeen voidglare","questgeber"}},{q="Was haben die Diebe der Verlassenen gestohlen?",a="Die Verlassenen stahlen vier Artefakte aus einem gesicherten Gewölbe. Die Apotheker brauchen sie für bestimmte Studien: einen Blutsteinkeil, einen Marmor, einen Splitter und ein Oval.",al={"was wurde gestohlen","blutsteine","gestohlene artefakte"}},{q="Wo werden die Diebe festgehalten?",a="Dalarans Zauberer halten die Diebe im Lordamere-Internierungslager unter Quarantäne.",al={"standort des internierungslagers","wo sind die verräter","wo ist kegan"}},{q="Wer sind die vier Verräter?",a="Die vier Verräter sind Dermot, der den Blutsteinkeil hat; Ricter, der den Marmor hat; Alina, die den Splitter hat; und Kegan Darkmar, der das Oval hat.",al={"namen der diebe","vier verlassene","wer stahl die blutsteine"}}},fp="15,203,24.293.0,19.359.0,31.125.0,36.146.0,33.82.0,26.158.0"}
P.entries["quest:545"] = {n="Patrouillen von Dalaran",s="In Tarrens Mühle richtet Magus Wordeen Voidglare seinen Blick auf Dalarans Außenbezirke. Jenseits der gewaltigen Kuppel könnten zerstörte Straßen Schätze von magischem Wert bergen, doch Zauberer und ihre Elementarsklaven patrouillieren dort. Voidglare will diese Patrouillen ausdünnen lassen.",h="In Tarrens Mühle richtet Magus Wordeen Voidglare seinen Blick auf Dalarans Außenbezirke.",kw={"dalaran","dalaran summoners","elemental slaves","vorgebirge des hügellands","magische kuppel","tarrens mühle","wordeen voidglare"},sec={{t="Schätze in den Ruinen",b="Nach Prison Break In wendet sich Voidglare den Zauberern von Dalaran zu. Sie haben eine gewaltige magische Kuppel über dem Herzen ihrer Stadt errichtet. Manche sagen, sie schütze sie vor der Gewalt dieses Zeitalters. Andere sagen, sie hätten Abgeschiedenheit gesucht, um zu studieren und Pläne zu schmieden. Ihr Beweggrund ist Voidglare gleichgültig.\n\nJenseits der Kuppel könnten die zerstörten Außenbezirke Schätze von echtem magischem Wert bergen. Doch Zauberer und ihre Elementarsklaven patrouillieren durch diese Straßen. Ihr werdet ausgesandt, um sechs Dalaran Summoners und zwölf Elemental Slaves zu jagen und dann zu Voidglare in Tarrens Mühle zurückzukehren."}},faq={{q="Warum will Magus Voidglare die Patrouillen ausdünnen lassen?",a="Voidglare glaubt, dass die zerstörten Außenbezirke jenseits von Dalarans Kuppel Schätze von echtem magischem Wert bergen könnten. Zauberer und ihre Elementarsklaven patrouillieren dort.",al={"warum dalarans patrouillen töten","magus voidglares ziel","beweggrund für patrouillen von dalaran"}},{q="Was ist die magische Kuppel um Dalaran?",a="Die Zauberer von Dalaran haben eine gewaltige magische Kuppel über dem Herzen ihrer Stadt errichtet. Manche sagen, sie schütze sie vor der Gewalt dieses Zeitalters. Andere sagen, sie hätten Abgeschiedenheit gesucht, um zu studieren und Pläne zu schmieden.",al={"was ist dalarans kuppel","warum ist dalaran in einer blase","dalarans schutzschild"}},{q="Wer patrouilliert durch Dalarans Außenbezirke?",a="Die Zauberer von Dalaran und ihre Elementarsklaven patrouillieren durch die Außenbezirke. Voidglare will, dass Ihr sechs Dalaran Summoners und zwölf Elemental Slaves jagt.",al={"wer bewacht dalaran","feinde in dalarans ruinen","wer patrouilliert durch dalaran"}},{q="Welche Quest ging dieser voraus?",a="Prison Break In ging dieser Quest voraus, und Voidglare gab sie Euch in Tarrens Mühle.",al={"vorherige quest","was kommt vor patrouillen von dalaran"}}},fp="15,250,22.543.0,50.157.0,40.184.0,38.150.0,28.78.0"}
P.entries["quest:546"] = {n="Andenken des Todes",s="In Tarrens Mühle sieht Todeswache Samsa andere gegen Hillsbrads Menschensiedlungen ziehen und will sich ihnen anschließen. Er bittet um dreißig im Kampf erbeutete Menschenschädel für seine Sammlung.",h="In Tarrens Mühle sieht Todeswache Samsa andere gegen Hillsbrads Menschensiedlungen ziehen und will sich ihnen...",kw={"battle of hillsbrad","darthalia","todeswache samsa","verlassene","hillsbrad","menschlicher schädel aus dem hügelland","andenken des todes","tarrens mühle"},ang={["faction:Alliance"]="Als Recke der Allianz erlebt Ihr die brutale Bedrohung der überlebenden Stadtbewohner Hillsbrads durch die Verlassenen, die systematisch abgetrennte Menschenköpfe sammeln.",["faction:Horde"]="Als Recke der Horde schließt Ihr Euch dem Vorstoß gegen die Stützpunkte der Allianz in Lordaeron an und sichert die nördlichen Nachschubwege für Tarrens Mühle.",["race:Undead"]="Als untoter Recke erlebt Ihr die beiläufige Grausamkeit und die tiefe Feindseligkeit vieler Verlassener gegenüber lebenden Menschen, die sie als Monster betrachten."},sec={{t="Der Neid einer Wache",b="Hochexekutorin Darthalia leitet den Feldzug der Verlassenen gegen Hillsbrads Menschensiedlungen. Todeswache Samsa hält in Tarrens Mühle Wache, während andere zum Überfallen, Brandschatzen und Plündern ausgesandt werden. Er beneidet sie um die Gelegenheit, die Lebenden abzuschlachten, die einer an ihren Posten gebundenen Wache verwehrt bleibt."},{t="Eine grausige Trophäe",b="Samsa hasst die Menschen von Hillsbrad und sammelt die Schädel jener, die im Feldzug getötet wurden. Er bittet um dreißig als Trophäen eines Krieges, in dem er selbst nur allzu gern kämpfen würde. Hinter seiner Bitte steckt weder ein arkanes Ritual noch ein militärischer Plan."}},faq={{q="Wer vergibt diese Quest und wo?",a="Todeswache Samsa vergibt sie an seinem Wachposten in Tarrens Mühle, dem wichtigsten Stützpunkt der Verlassenen im nördlichen Vorgebirge des Hügellands.",al={"questgeber","wer vergibt andenken des todes","samsas standort"}},{q="Was will Todeswache Samsa?",a="Samsa bittet um dreißig Hillsbrad Human Skulls von menschlichen Kämpfern und Stadtbewohnern auf den Feldern von Hillsbrad und in der Stadt Hillsbrad.",al={"questziel","welche gegenstände benötigt","benötigte schädel"}},{q="Warum will Samsa Menschenschädel?",a="Samsa sammelt makabre Trophäen. An den Garnisonsdienst in Tarrens Mühle gebunden, während andere Krieg führen, sammelt er Schädel, um aus der Ferne am Abschlachten der Lebenden teilzuhaben.",al={"warum schädel sammeln","samsas beweggründe","wofür sind die schädel"}},{q="Wann wird diese Quest verfügbar?",a="Samsa spricht Euch an, nachdem Ihr Euch bei Hochexekutorin Darthalia verpflichtet und den ersten Angriff im Feldzug Battle of Hillsbrad abgeschlossen habt.",al={"questvoraussetzungen","wie freischalten","voraussetzungen für andenken"}},{q="Werden die Schädel für Alchemie oder Magie der Verlassenen verwendet?",a="Nein. Samsas Bitte ist persönlich, anders als die Aufträge der Royal Apothecary Society, bei denen biologische Reagenzien für die New Plague gesucht werden. Er findet die abgetrennten Schädel schön und hütet sie als Kriegsandenken.",al={"sind schädel für apotheker","magische schädel","verwendung für nekromantie"}},{q="Welche Menschen liefern die Schädel?",a="Die Schädel stammen von menschlichen Farmern, Bauern, Milizionären und Verteidigern auf den Feldern von Hillsbrad oder in der Stadt Hillsbrad, wo Ihr für Tarrens Mühle kämpft.",al={"wo schädel farmen","welche gegner lassen schädel fallen","menschen von hillsbrad"}}},fx={["0c405e10"]={q="Warum braucht Todeswache Samsa einen Abenteurer, anstatt selbst nach Schädeln zu jagen?",a="Todeswache Samsa ist an seinen Posten in Tarrens Mühle gebunden. Während die Verlassenen einen aktiven Feldzug gegen Hillsbrad führen, sitzt Samsa fest und muss Wache halten, anstatt am Angriff teilzunehmen. Da Hochexekutorin Darthalia Euch bereits für den Kampf an der Front rekrutiert hat, bittet Samsa Euch, Mitleid mit einem alten Soldaten zu haben und in seinem Namen makabre Trophäen zu sammeln.",al={"warum ich für todeswache samsa","warum kann samsa keine schädel sammeln","warum jagt samsa nicht selbst"}},["3446168a"]={q="Wer sind die Menschen in Hillsbrad, gegen die Ihr kämpft?",a="Die Ziele sind die menschlichen Bürger, Arbeiter und Verteidiger der Felder von Hillsbrad und der Stadt Hillsbrad. Als eine der verbliebenen souveränen menschlichen Bastionen in Lordaeron widersetzt sich Hillsbrad direkt dem Außenposten der Verlassenen in Tarrens Mühle. Die Verlassenen betrachten ihre fortwährende Existenz und Allianz-Zugehörigkeit als eine inakzeptable Bedrohung für ihre territoriale Vorherrschaft.",al={"wer sind die menschen in hillsbrad","hillsbrad ziel","warum sind hillsbrad menschen hier"}}},fp="18,183,14.270.0,17.217.0,49.125.0,32.137.0,33.165.0,38.136.0,50.202.0,32.147.0"}
P.entries["quest:547"] = {n="Humberts Schwert",s="Nahe Dun Garok fehlt Humberts Schwert in dem Lager, in dem sein Besitzer es zurückgelassen hat. Todeswache Humbert war Brennholz sammeln gegangen, während er auf Befehl von Hochexekutorin Darthalia die Zwergenfestung beobachtete. Kundschafter aus Eisenschmiede nahmen seine Waffe mit, und nun fürchtet er, dass Darthalia von seinem Versagen erfährt.",h="Nahe Dun Garok fehlt Humberts Schwert in dem Lager, in dem sein Besitzer es zurückgelassen hat.",kw={"darthalia","todeswache","dun garok","brennholz","hillsbrad","humbert","schwert","tarrens mühle"},ang={["faction:Horde"]="Als Mitglied der Horde greift Ihr Dun Garok an, um Eisenschmiedes militärische Kontrolle über das Vorgebirge des Hügellands zu schwächen und Tarrens Mühle vor Einfällen aus dem Süden zu schützen.",["race:Dwarf"]="Als Gebirgsjäger von Dun Garok habt Ihr für die Verlassenen vor Eurer Haustür nichts übrig. Jede Gelegenheit zählt, den Wachposten von Tarrens Mühle zuzusetzen und ihre Lager restlos auszuplündern.",["race:Undead"]="Als Soldat der Verlassenen in Hillsbrad kennt Ihr die brutale Disziplin, die Hochexekutorin Darthalia durchsetzt. In Tarrens Mühle können Versagen oder Nachlässigkeit die Hinrichtung nach sich ziehen, ohne jede Gnade."},sec={{t="Die Nachlässigkeit eines Spähers",b="Todeswache Humbert beobachtet Dun Garok für Hochexekutorin Darthalia. Sein versteckter Posten liegt nahe der Zwergenfestung. Eines Morgens verlässt er das Lager, um Brennholz zum Wasserkochen zu sammeln. Kundschafter aus Eisenschmiede finden den Posten unbewacht vor und plündern ihn. Als Humbert zurückkehrt, ist sein Schwert verschwunden und in den schwer verteidigten Bunker verschleppt worden."},{t="Angst vor den Dachbalken",b="Humbert weiß, dass es ihn unter dem Kommando der Verlassenen das Leben kosten könnte, seine Waffe an den Feind zu verlieren, den er beobachten sollte. Falls Hochexekutorin Darthalia erfährt, was geschehen ist, fürchtet er, dass sie ihn an den Dachbalken in Tarrens Mühle aufhängt. Er kann Dun Garok nicht allein stürmen. Also wendet er sich an vorbeiziehende Abenteurer der Horde, damit sie seine Klinge zurückholen, bevor seine Kommandantin bemerkt, dass etwas nicht stimmt."}},faq={{q="Wer ist Todeswache Humbert?",a="Todeswache Humbert ist ein Soldat der Verlassenen, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Hochexekutorin Darthalia hat ihm aufgetragen, Dun Garok zu beobachten, den befestigten Außenposten der Zwerge im südöstlichen Vorgebirge.",al={"todeswache humbert","wer ist humbert","humbert"}},{q="Wie hat Humbert sein Schwert verloren?",a="Humbert verließ eines Morgens seinen Posten nahe Dun Garok, um Brennholz zum Wasserkochen zu sammeln. Während seiner Abwesenheit fanden zwergische Kundschafter sein Lager, nahmen seine Habseligkeiten an sich und schleppten sein Schwert fort.",al={"wie hat humbert seine waffe verloren","wer hat humberts schwert gestohlen","gestohlenes schwert"}},{q="Warum will Humbert sein Schwert so verzweifelt heimlich zurückbekommen?",a="Humbert fürchtet, dass Hochexekutorin Darthalia ihn hinrichten lässt, weil er seine Ausrüstung an die Zwerge verloren hat, die er beobachten sollte. Er erwartet, dass sie ihn an den Dachbalken in Tarrens Mühle aufhängt.",al={"warum ist humbert besorgt","darthalias strafe","warum darthalia fürchten"}},{q="Wo befindet sich das Schwert?",a="Die zwergischen Kundschafter haben Humberts Schwert nach Dun Garok gebracht. Es befindet sich bei den Gebirgsjägern, Scharfschützen und Offizieren aus Eisenschmiede im Bunker.",al={"fundort des schwertes","wo ist humberts schwert","dun garok schwert"}},{q="Haben die Zwerge Humbert noch etwas anderes gestohlen?",a="Ja. Humbert stellte fest, dass seine Ausrüstung im Lager fehlte, darunter auch sein Schwert. Das Schwert ist das Einzige, das Ihr für ihn aus Dun Garok zurückholen sollt.",al={"humberts übrige ausrüstung","humberts rüstungsteile","humberts hose"}},{q="Was ist Dun Garok?",a="Dun Garok ist eine Festung der Zwerge aus Eisenschmiede im Südosten des Vorgebirges des Hügellands. Ihre Zwerge helfen dabei, die Menschen von Hillsbrad und den nahe gelegenen Azurschacht zu schützen. Ihre Garnison der Allianz steht in direktem Konflikt mit den Verlassenen von Tarrens Mühle.",al={"dun garok festung","dun garok hintergrundgeschichte","zwerge in hillsbrad"}}},fx={["65d1b07f"]={q="Warum ist Humberts Schwert so wichtig für ihn?",a="Für Todeswache Humbert ist die Waffe sowohl sein persönlicher Stolz als auch das Abzeichen seiner Pflicht. Ohne sie steht er während seines Wachdienstes für Tarrens Mühle unbewaffnet da und ist der Wut von Hochexekutorin Darthalia schutzlos ausgeliefert. Sie besitzt keine magischen Kräfte oder großen Verzauberungen; es ist einfach seine geliebte Klinge, und sie zurückzubekommen stellt seine Würde wieder her und verbirgt einen demütigenden Patzer vor seiner Kommandantin.",al={"was ist humberts schwert","warum braucht humbert sein schwert","humberts schwert zweck"}},c70ad326={q="Wer sind die Zwerge, die Humberts Schwert haben?",a="Die Diebe gehören zu den zwergischen Streitkräften, die in Dun Garok stationiert sind, einer Festung der Allianz im südöstlichen Vorgebirge des Hügellands. Diese Bergsteiger und Schützen aus Eisenschmiede schicken regelmäßig Späher durch das Hügelland, um die Expansion der Verlassenen zu bekämpfen. Eine Patrouille stieß auf Humberts unbewachtes Lager, während er Feuerholz sammelte, plünderte seine Ausrüstung und trug sie hinter ihre befestigten Mauern.",al={"wer hat humberts schwert gestohlen","zwerge in dun garok","wer hat das schwert"}},["6c936ae5"]={q="Warum braucht Humbert Euch, um sein Schwert zurückzuholen, anstatt es selbst zu tun?",a="Humbert kann keine schwer befestigte zwergische Bastion alleine stürmen, noch kann er seine Kameraden der Todeswache um Hilfe bitten, ohne zuzugeben, dass er seinen Posten verlassen hat, um Wasser zu kochen, und seine Ausrüstung stehlen ließ. Wenn Hochexekutorin Darthalia erfährt, dass er seine Waffe an zwergische Diebe verloren hat, würde sie ein brutales Exempel an ihm statuieren. Ein unabhängiger Abenteurer kann sich hineinschleichen und die Klinge diskret zurückholen.",al={"warum kann humbert sein schwert nicht holen","warum fragt man mich wegen humberts schwert","warum braucht humbert hilfe"}}},fp="15,280,20.316.0,19.362.0,26.207.0,31.184.0,58.176.0,27.136.0,49.134.0,18.235.0"}
P.entries["quest:5481"] = {n="Gordos Aufgabe",s="Entlang der Straße nach Brill sammelt Gordo Pflanzen für die Königliche Apothekervereinigung. Für seine ungeschickten Hände ist die Arbeit zu filigran, also bittet er Reisende, Düsterkraut für Hilfsapotheker Holland zu sammeln.",h="Entlang der Straße nach Brill sammelt Gordo Pflanzen für die Königliche Apothekervereinigung.",kw={"abscheulichkeit","apotheker","brill","doom weed","düsterkraut","gordo","holland","tirisfal"},ang={["profession:Herbalism"]="Als ausgebildeter Kräuterkundiger könnt Ihr Düsterkrautbestände im verseuchten Gras leicht finden.",["race:Undead"]="Als frisch erweckter Verlassener, der Todesend verlässt, erlebt Ihr die unbeholfene Arbeit der Abscheulichkeiten und das aufbrausende Temperament der Königlichen Apothekervereinigung."},sec={{t="Ein ungeschickter Arbeiter",b="Zwischen Todesend und Brill stapft Gordo im Auftrag der Königlichen Apothekervereinigung durch die Landschaft. Abscheulichkeiten können mit roher Kraft kämpfen und schwere Lasten tragen, doch ihre riesigen, zusammengenähten Hände tun sich mit feinen Arbeiten schwer. Zum Sammeln von Zutaten auf die Wiesen geschickt, zerquetscht Gordo mehr Stängel, als er pflückt. Also wendet er sich an Vorbeigehende und schüchtert sie ein oder besticht sie, damit sie die behutsame Arbeit für ihn erledigen."},{t="Der verärgerte Apotheker",b="Hilfsapotheker Holland wartet auf dem Friedhof hinter Brills Rathaus auf die Lieferung. Gordo hat seine Befehle missverstanden. Holland braucht unbeständiges Doom Weed für alchemistische Forschungen, doch Gordo hat Reisende losgeschickt, um harmloses Düsterkraut zu sammeln. Der Fehler bringt Holland völlig zur Verzweiflung. Er sieht darin den Beweis, dass Gordo nutzlos ist, und schickt Euch los, um den Fehler zu berichtigen."}},faq={{q="Wer ist Gordo?",a="Gordo ist eine Abscheulichkeit im Dienst der Königlichen Apothekervereinigung. Er patrouilliert auf den Wiesen westlich von Brill und verrichtet Arbeiten, die ihm sein Meister, Hilfsapotheker Holland, aufträgt.",al={"wer ist gordo","gordo tirisfal","gordo npc","was ist gordo"}},{q="Warum braucht Gordo Hilfe beim Kräutersammeln?",a="Gordos gewaltigen, zusammengenähten Händen fehlt das Fingerspitzengefühl, um zarte Pflanzen zu pflücken, ohne sie zu zerstören. Also wirbt er umherreisende Verlassene an, um die Pflanzen zu sammeln.",al={"warum braucht gordo kräuter","warum kann gordo keine kräuter pflücken","gordos hände"}},{q="Wer ist Meister Holland?",a="Hilfsapotheker Holland ist ein Alchemist der Königlichen Apothekervereinigung, der auf dem Friedhof von Brill stationiert ist. Er beaufsichtigt Gordo und erforscht die örtliche Pflanzenwelt und den verseuchten Boden, um die Kriegsanstrengungen der Verlassenen zu unterstützen.",al={"meister holland","wer ist holland","apotheker holland"}},{q="Warum ist Holland verärgert, als das Düsterkraut geliefert wird?",a="Holland ist verärgert, weil er unbeständiges Doom Weed für alchemistische Forschungen braucht, Gordo Euch aber losgeschickt hat, um harmloses Düsterkraut zu sammeln.",al={"warum ist holland wütend","düsterkraut verwechslung","falsches kraut"}},{q="Wo ist Düsterkraut zu finden?",a="Düsterkraut wächst dicht am Boden auf den Feldern zwischen Todesend und Brill, besonders auf den offenen Wiesen östlich von Sollidens Bauernhof.",al={"wo düsterkraut finden","düsterkraut fundorte","düsterkraut finden"}},{q="Was geschieht nach dem Abschluss von Gordos Aufgabe?",a="Danach bietet Holland Euch auf dem Friedhof von Brill einen weiteren Auftrag an: Doom Weed.",al={"what comes next","gordos aufgabe folgeauftrag","nächste quest nach gordo"}}},fx={["2383074c"]={q="Warum möchte Gordo, dass Düsterkraut gesammelt wird?",a="Gordo sagt, Meister Holland möchte Unkraut und bittet um Hilfe beim Sammeln von Düsterkraut. Seine großen Hände machen das Pflücken schwierig, also schickt er Reisende, um die Pflanzen zu Holland auf dem Friedhof von Brill zu bringen.",al={"warum will gordo unkraut","gordos motiv","warum düsterkraut sammeln"}},a763e1e7={q="Wofür wird Düsterkraut verwendet?",a="Was Meister Holland betrifft, so ist Düsterkraut völlig nutzlos. Es ist einfach ein gewöhnliches, harmloses Unkraut, das überall in Tirisfal wächst. Holland hat kein Interesse daran, Gänseblümchen zu pflücken, und benötigt stattdessen Doom Weed für seine Gebräue.",al={"wofür ist düsterkraut","zweck von düsterkraut","nutzen von düsterkraut"}}},fp="12,193,16.402.0,23.367.1,13.172.0,41.152.0,22.205.0,54.127.1,30.139.0,43.82.1"}
P.entries["quest:5482"] = {n="Verdammniskraut",s="In Brill sucht Juniorapotheker Holland Verdammniskraut für seine Forschung. Die Pflanze wächst bei den nördlichen Massengräbern von Tirisfal, wo Gnolle der Rot Hide umherstreifen.",h="In Brill sucht Juniorapotheker Holland Verdammniskraut für seine Forschung.",kw={"brill","verdammniskraut","gordo","juniorapotheker holland","massengrab","gnolle der rot hide","königliche apothekervereinigung","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde erkennt Ihr an Brills beunruhigender Alchemie, wie sich die Verlassenen von ihren schamanistischen und nomadischen Verbündeten in Kalimdor unterscheiden.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass die Lichtungen gewöhnliche Pflanzen und verdorbene Gewächse wie Verdammniskraut bergen, die von der Seuche der Geißel geformt wurden.",["race:Undead"]="Als Untoter könnt Ihr niederen Mitgliedern der Königlichen Apothekervereinigung dienen und dabei Euren Nutzen für Sylvanas' Reich beweisen."},sec={{t="Ambitionen eines Apothekers",b="Juniorapotheker Holland studiert in Brill Alchemie für die Königliche Apothekervereinigung. Er braucht Verdammniskraut für seine Experimente, doch Gordo kann die Pflanzen nicht auseinanderhalten. Deshalb bittet Holland fähige Helfer, zu sammeln, was er benötigt."},{t="Ernte am Massengrab",b="Verdammniskraut wächst rund um die Massengrabstätte unmittelbar nördlich des Friedhofs von Brill. Tod und Seuche haben dort den Boden verdorben. Gnolle der Rot Hide streifen über die Grabhügel, suchen zwischen den Überresten nach Nahrung und bewachen die überwucherten Gräben."}},faq={{q="Warum braucht Juniorapotheker Holland Verdammniskraut?",a="Juniorapotheker Holland braucht Verdammniskraut für seine alchemistische Arbeit bei der Königlichen Apothekervereinigung. Er sagt, die Arbeit diene Fürstin Sylvanas Windläufer, doch sein Eifer lässt auch auf Ehrgeiz innerhalb der Vereinigung schließen.",al={"holland verdammniskraut","warum verdammniskraut","verdammniskraut zweck"}},{q="Warum sammelt Gordo die Kräuter nicht selbst?",a="Gordo ist eine Monstrosität, die zum Kräutersammeln in die Umgebung von Brill geschickt wurde, doch er kann bestimmte Pflanzen nicht erkennen. Nachdem er die falschen Kräuter zurückgebracht hat, wendet sich Holland an fähige Abenteurer.",al={"warum nicht gordo","gordo aufgabe gescheitert","wer ist gordo"}},{q="Wo wächst Verdammniskraut?",a="Verdammniskraut wächst rund um die Massengrabstätte unmittelbar nördlich des Friedhofs außerhalb von Brill. Es breitet sich in Erde aus, die durch Grabgräben und die noch immer wirkende Seuche verdorben ist.",al={"verdammniskraut fundort","wo ist verdammniskraut","massengrab kräuter"}},{q="Welche Gefahren lauern bei den Verdammniskrautbeständen?",a="Gnolle der Rot Hide streifen über das Gelände rund um die Massengrabstätte. Diese wilden, von Krankheiten gezeichneten Aasfresser greifen jeden an, der sich zum Kräutersammeln nähert.",al={"verdammniskraut monster","massengrab feinde","gnolle bei brill"}},{q="Welches Interesse hat die Königliche Apothekervereinigung an der Pflanzenwelt von Tirisfal?",a="Die Königliche Apothekervereinigung erforscht überall in Tirisfal Pflanzen, Gifte und durch die Seuche veränderte Pilze. Sie sammelt Reagenzien wie Verdammniskraut, um Giftstoffe zu verfeinern, alchemistische Heilmittel zu finden und Waffen für die Verlassenen gegen ihre Feinde zu entwickeln.",al={"apotheker interesse","königliche apothekervereinigung tirisfal","verlassene kräutersammeln"}},{q="Wer ist die von Holland erwähnte „Fürstin“?",a="Mit „der Fürstin“ ist Fürstin Sylvanas Windläufer gemeint, die Banshee Queen und Herrscherin der Verlassenen. Apotheker in Unterstadt und Brill berufen sich auf ihren Namen und sagen, ihre alchemistische Arbeit folge ihrem Befehl.",al={"wer ist die fürstin","holland fürstin sylvanas","die fürstin unterstadt"}}},fp="9,150,20.225.0,22.229.0,50.212.0,43.176.0,26.157.0,45.149.0,66.238.0,39.194.0"}
P.entries["quest:549"] = {n="GESUCHT: Syndikatspersonal",s="In Tarrens Mühle fordert Fürstin Sylvanas Windläufers Kopfgeld den Tod jedes Syndikatsmitglieds. Die Verlassenen wollen die Briganten aus Burg Durnholde vertreiben, bevor sie die Operationen der Horde im Vorgebirge bedrohen.",h="In Tarrens Mühle fordert Fürstin Sylvanas Windläufers Kopfgeld den Tod jedes Syndikatsmitglieds.",kw={"burg durnholde","hochexekutorin darthalia","vorgebirge des hügellands","syndikat","schurke des syndikats","wächter des syndikats","tarrens mühle","gesucht"},ang={["class:Rogue"]="Das Syndikat hat in ganz Durnholde geschickte Beutelschneider und Meister des Hinterhalts. Euch stehen Rivalen gegenüber, die ebenfalls die Kunst der Verstohlenheit beherrschen.",["faction:Horde"]="Burg Durnholde weckt bei der Horde düstere Erinnerungen. Einst wurden Orcs in dieser Internierungsfestung gefangen gehalten, weshalb die Vertreibung ihrer Briganten symbolisches Gewicht hat.",["race:Undead"]="Als Verlassene habt Ihr einen handfesten Grund, die lebenden Überreste von Alteracs Adel zu beseitigen, wenn Ihr die Hügel Lordaerons unangefochten halten wollt."},sec={{t="Ein dauerhafter Hinrichtungsbefehl",b="Das plötzliche Auftauchen des Syndikats südöstlich von Tarrens Mühle hat die Aufmerksamkeit der Verlassenen erregt. Fürstin Sylvanas Windläufer und ihre Befehlshaber betrachten das Syndikat als Plage, nicht als vertriebene Adlige, mit denen man verhandeln könnte. Ihr Kopfgeld befiehlt deren sofortige Tötung. Alle eingelieferten Gefangenen werden ohne Gerichtsverhandlung hingerichtet."},{t="Die Ruinen von Durnholde",b="Burg Durnholde war einst eine berüchtigte Internierungsfestung. Jetzt liegt sie in Trümmern und ist der Gesetzlosigkeit überlassen. Schurken und Wächter des Syndikats haben ihre verfallenden Wehrmauern und Türme zu einer Operationsbasis gemacht. Hochexekutorin Darthalia muss die bewaffneten Banditen vertreiben lassen, um die Straße zu sichern und den südöstlichen Zugang zu Tarrens Mühle zu schützen."}},faq={{q="Wer hat das Kopfgeld auf das Syndikatspersonal ausgesetzt?",a="Fürstin Sylvanas Windläufer hat das Kopfgeld unter ihrer unmittelbaren Autorität ausgesetzt, und der Steckbrief hängt an der Anschlagtafel von Tarrens Mühle. Hochexekutorin Darthalia, die militärische Befehlshaberin der Siedlung, nimmt die Hinrichtungsnachweise entgegen.",al={"wer hat gesucht syndikatspersonal ausgehängt","wer will das syndikat tot sehen","steckbrief"}},{q="Wo befinden sich diese Syndikatsmitglieder?",a="Syndikatsmitglieder sammeln sich zwischen den zertrümmerten Steinen von Burg Durnholde, südöstlich von Tarrens Mühle auf der anderen Seite des Flusses. Weitere halten sich beim zerstörten Wachturm unmittelbar südlich der Festung auf.",al={"wo sind die schurken des syndikats","syndikat in durnholde fundort","wo sind die wächter zu finden"}},{q="Warum wollen die Verlassenen sie tot sehen, statt sie gefangen zu nehmen?",a="Die Verlassenen betrachten das Syndikat als heimtückisches Ungeziefer und als bewaffnete Bedrohung auf ihrem Gebiet. Das Dekret befiehlt, gefangene Mitglieder ohne Gerichtsverhandlung hinzurichten, also hat es keinen Sinn, sie lebend gefangen zu nehmen.",al={"warum syndikatsmitglieder töten","warum keine gefangenen","darthalia syndikat"}},{q="Was macht das Syndikat in Burg Durnholde?",a="Das Syndikat besteht überwiegend aus in Ungnade gefallenen Alteraci-Adligen und Söldnern. In ganz Lordaeron nutzen seine Mitglieder verlassene Burgen, Ruinen und Türme als Stützpunkte, um Siedlungen zu überfallen, Reisende auszurauben und ihre zerschlagene Macht wiederaufzubauen.",al={"warum ist das syndikat in durnholde","syndikat ziele hillsbrad","besatzer von burg durnholde"}},{q="Was geschieht, nachdem diese Syndikatskräfte dezimiert wurden?",a="Sobald die örtlichen Schurken und Wächter dezimiert sind, setzt Hochexekutorin Darthalia mit höchster Dringlichkeit ein Kopfgeld auf ihren Anführer Baron Vardus aus.",al={"welche quest kommt als nächstes","nach gesucht syndikatspersonal","nächstes kopfgeld"}}},fx={["6d6e03d8"]={q="Warum verlässt sich Hochexekutorin Darthalia für dieses Kopfgeld auf Abenteurer?",a="Hochexekutorin Darthalia beaufsichtigt Tarrens Mühle unter direktem Mandat von Lady Sylvanas, doch ihre Garnison ist überlastet mit der Verteidigung des Gebiets der Verlassenen gegen Süderstade und die regionalen Bedrohungen in Hillsbrad. Wie sie Besuchern unverblümt mitteilt, hat sie weit dringendere Angelegenheiten des Kommandos zu regeln, als sich persönlich um jedes Lager von Dieben zu kümmern. Das Aussetzen öffentlicher Kopfgelder lockt willige Söldner und Champions der Horde an, um Durnholde von Ungeziefer zu befreien, ohne die Verteidigung an der Front der Stadt zu schwächen.",al={"warum abenteurer schicken","warum darthalias kopfgeld","warum nicht wachen aus tarrens mühle"}}},fp="27,205,26.302.0,22.315.0,46.205.0,42.177.0,55.193.0,46.226.0,54.132.1"}
P.entries["quest:55"] = {n="Morbent Teufel",s="Über dem Friedhof von Rabenflucht schützen Morbent Teufels Schutzzauber ihn vor gewöhnlichem Stahl. Sven Yorgen schickt Euch mit Morbents Bann aus, um sie zu brechen und dem Schrecken des Totenbeschwörers im westlichen Dämmerwald ein Ende zu setzen.",h="Über dem Friedhof von Rabenflucht schützen Morbent Teufels Schutzzauber ihn vor gewöhnlichem Stahl.",kw={"dämmerwald","morbent teufel","morbents bann","totenbeschwörer","rabenflucht","friedhof von rabenflucht","sven yorgen"},ang={["class:Paladin"]="Als Paladin folgt Ihr der Berufung eines Ritters des Heiligen Lichts, wenn Ihr einen verderbten Totenbeschwörer niederstreckt und Rabenflucht von seinen unnatürlichen Schutzzaubern reinigt.",["class:Priest"]="Als Priester könnt Ihr der Entweihung des Friedhofs von Rabenflucht mit spiritueller Reinigung begegnen und Fels magische Schutzzauber als heilige Pflicht bannen.",["faction:Alliance"]="Morbent Teufel zu erschlagen, beseitigt eine der größten Bedrohungen für die Bewohner des Dämmerwalds, sichert die Straße und würdigt das Leid westlicher Siedlungen wie Rabenflucht."},sec={{t="Die Warte über den Toten",b="Morbent Teufel haust in einem verlassenen Haus auf einem felsigen Bergrücken unmittelbar östlich von Svens Lager. Das Haus überblickt die weiten Flächen des Friedhofs von Rabenflucht. Von dort schickt der Totenbeschwörer Untote durch den umliegenden Wald und schändet die Gräber des Dämmerwalds. Dunkle Magie und treue untote Knechte schützen ihn vor gewöhnlichem Stahl."},{t="Svens Rache",b="Dunkle Mächte schlachteten Sven Yorgens Familie ab und zwangen ihn, sich zu verstecken, woraufhin er vor Trauer den Verstand verlor. Sven weiß, dass die Schwarzen Reiter von Karazhan für das Massaker auf seinem Hof verantwortlich waren. Morbent Teufels abscheuliche Zauberei hält den Albtraum der Region am Leben. Den Totenbeschwörer niederzustrecken, bietet Sven den einzigen greifbaren Funken Gerechtigkeit, der ihm in diesem verheerten Land noch bleibt."},{t="Morbents Bann",b="Morbent Teufels Schutzzauber machen einen direkten Angriff zum Selbstmord und wehren herkömmliche Angriffe ab. Sven vertraut Euch Morbents Bann an, ein verzaubertes Artefakt, das diese magische Abschirmung auflösen soll. Ruft das Relikt an, und die Barriere bricht zusammen. Dann ist Fel einem tödlichen Streich schutzlos ausgeliefert."}},faq={{q="Wer ist Morbent Teufel?",a="Morbent Teufel befehligt die Untoten, die die Gegend um Rabenflucht heimsuchen. Er lauert in einem Haus auf einem Hügel über dem Friedhof von Rabenflucht und schützt sich mit dunkler Zauberei, während er die Lebenden des Dämmerwalds quält.",al={"morbent teufel geschichte","wer ist morbent teufel","morbent teufel hintergrund"}},{q="Warum braucht man Morbents Bann, um ihn zu töten?",a="Morbent Teufels mächtige Schutzzauber wehren gewöhnliche Angriffe ab und machen ihn nahezu unverwundbar. Morbents Bann ist ein verzaubertes Relikt, das diese Schutzzauber bannen und ihn verwundbar machen soll.",al={"morbents bann","warum morbents bann benutzen","wie morbent teufel besiegen"}},{q="Welche Verbindung besteht zwischen Sven Yorgen und Morbent Teufel?",a="Die Schwarzen Reiter waren dafür verantwortlich, Sven Yorgens Familie auf ihrem Hof abzuschlachten. Morbent Teufel hat dieses Massaker nicht verübt, doch sein nekromantischer Würgegriff um das Land verkörpert das Böse, das den westlichen Dämmerwald heimsucht. Fels Vernichtung gibt Sven ein Ziel für seine Rache.",al={"warum will sven morbent tot sehen","sven yorgen morbent teufel","svens rache"}},{q="Wo ist Morbent Teufel zu finden?",a="Morbent Teufel lebt im Obergeschoss eines verfallenen, zerstörten Hauses auf einem Hügel unmittelbar östlich von Sven Yorgens Lager. Das Haus überblickt die Westseite des Friedhofs von Rabenflucht.",al={"morbent teufel aufenthaltsort","wo ist morbent teufel","morbents haus"}},{q="Hat Morbent Teufel Svens Familie getötet?",a="Nein. Die geheimnisvollen Schwarzen Reiter, die nach der Sichel von Elune suchten, schlachteten Svens Familie ab. Morbent Teufels Nekromantie suchte die umliegende Gegend heim und entweihte die Gräber des Dämmerwalds, weshalb seine Vernichtung unerlässlich ist, um den Frieden wiederherzustellen.",al={"hat morbent svens familie getötet","wer hat svens familie abgeschlachtet"}},{q="Was geschieht nach Morbent Teufels Tod?",a="Morbents Bann zu Sven zurückzubringen, spendet dem trauernden Einsiedler ein wenig Trost. Die schwer zu fassenden Schwarzen Reiter sind weiterhin auf freiem Fuß, doch Fels Tod bricht den nekromantischen Würgegriff um Rabenflucht und festigt Euren Ruf im gesamten Dämmerwald.",al={"nach morbent teufel","questabschluss","findet sven frieden"}}},fx={bd8ba8cc={q="Warum muss Sven Yorgen Euch gegen Morbent Fel schicken, anstatt es selbst zu tun?",a="Sven ist ein isolierter, traumatisierter Einsiedler, der durch Kummer und Paranoia fast in den Wahnsinn getrieben wurde. Er versteckt sich in einem provisorischen Lager am westlichen Rand vom Dämmerwald und besitzt nicht die Kraft, die Schutzzauber und die kriegerische Stärke, um Raven Hill alleine zu stürmen. Morbent Fel beherrscht dunkle Magie und ruht, umgeben von untoten Wächtern, auf dem Friedhofshügel. Sven brauchte einen erfahrenen Champion, um Morbents Bann direkt in die Höhle des Nekromanten zu tragen und die Rache zu vollziehen, die er alleine nicht erreichen kann.",al={"warum braucht sven mich","warum tötet sven morbent fel nicht selbst","warum ich für sven yorgen"}}},fp="11,195,24.316.0,16.351.1,14.270.0,19.202.0,44.183.0,48.270.0,31.172.0,35.228.1,40.232.1"}
P.entries["quest:550"] = {n="Kampf um das Hügelland",s="In Hillsbrad haben die Verlassenen die Verteidigung der Ortschaft gebrochen. Hochexekutorin Darthalia entsendet Euch, um ihre Belobigung zu Varimathras in der Unterstadt zu bringen.",h="In Hillsbrad haben die Verlassenen die Verteidigung der Ortschaft gebrochen.",kw={"kampf um das hügelland","darthalia","vorgebirge des hügellands","königsviertel","versiegelte belobigung","tarrens mühle","unterstadt","varimathras"},ang={["faction:Horde"]="Als Mitglied der Horde drängt Ihr die Streitkräfte der Allianz in Lordaeron zurück. Ihr sichert der Horde wichtiges Gebiet in den Östlichen Königreichen.",["race:Undead"]="Als Untoter bringt Ihr die Nachricht von Eurem Sieg über die Lebenden von Hillsbrad ins Königsviertel. Dort erntet Ihr Lob und festigt Euren Platz im aufstrebenden Reich der Dunklen Fürstin."},sec={{t="Ein entscheidender Feldzug",b="Heftige Kämpfe im Vorgebirge des Hügellands haben das Ringen um das südliche Lordaeron entschieden. Von Tarrens Mühle aus griffen Streiter der Horde die Bauern, Milizen, Schmiede und zivilen Anführer der Ortschaft an. Die Streitkräfte der Allianz sind zerschlagen, und das Gebiet ist für die Verlassenen gesichert. Nun verfasst Hochexekutorin Darthalia eine offizielle Belobigung, damit die Taten des Streiters die höchsten Ränge der Führung erreichen."},{t="Audienz beim Schreckenslord",b="Darthalias versiegelte Belobigung führt Euch zu Varimathras ins Königsviertel der Unterstadt. Der Schreckenslord überwacht an der Seite von Fürstin Sylvanas Windläufer die militärischen Operationen in ganz Lordaeron. Die Geißel aus den nördlichen Pestländern bleibt die größte Bedrohung für die Dunkle Fürstin. Doch überlebende menschliche Enklaven gefährden weiterhin die südlichen Grenzen der Verlassenen."}},faq={{q="Worum geht es bei dieser Quest?",a="Hochexekutorin Darthalia entsendet Euch, um ihre versiegelte Belobigung zu Varimathras in der Unterstadt zu bringen. Der Feldzug der Verlassenen gegen Hillsbrad hat die Verteidigung der Ortschaft gebrochen.",al={"kampf um das hügelland finale","hillsbrad letzte quest","quest 550"}},{q="Wo gebe ich Darthalias versiegelte Belobigung ab?",a="Bringt Darthalias versiegelte Belobigung zu Varimathras im Königsviertel der Unterstadt. Er steht neben Fürstin Sylvanas Windläufer.",al={"wo ist varimathras","belobigung abgeben","darthalias brief abgeben"}},{q="Warum interessiert sich Varimathras für Hillsbrad?",a="Varimathras überwacht die militärischen Operationen in ganz Lordaeron. Die Geißel im Norden ist die größte Bedrohung für die Unterstadt, doch menschliche Siedlungen im Süden bedrängen die Linien der Verlassenen. Die Niederlage Hillsbrads schützt die südliche Grenze.",al={"warum varimathras","varimathras rolle in hillsbrad"}},{q="Wer ist Hochexekutorin Darthalia?",a="Hochexekutorin Darthalia ist die ranghöchste Befehlshaberin der Verlassenen in Tarrens Mühle im Vorgebirge des Hügellands. Sie leitet die Offensive gegen die nahe gelegene menschliche Siedlung.",al={"darthalia","wer hat die quest vergeben"}},{q="Führt diese Quest zu weiteren Aufträgen in Hillsbrad?",a="Die Übergabe der Belobigung an Varimathras schließt die Questreihe Kampf um das Hügelland ab. Darthalia lobt Euch dafür, dass Ihr die Verteidigung der Ortschaft gebrochen habt.",al={"nächste quest nach kampf um das hügelland","was kommt nach quest 550"}},{q="Warum haben die Verlassenen Hillsbrad überhaupt angegriffen?",a="Hillsbrad ist einer der letzten organisierten menschlichen Stützpunkte in Lordaeron. Seine Allianzmiliz und seine Nähe bedrohen Tarrens Mühle und die südlichen Zugänge zur Unterstadt.",al={"warum hillsbrad angreifen","hillsbrad geschichte"}}},fx={["8522c300"]={q="Warum möchte Hochexekutorin Darthalia, dass diese Belobigung überbracht wird?",a="Ihr habt während des brutalen Feldzugs im Vorgebirge des Hügellands tapfer und ausdauernd gekämpft. Hochexekutorin Darthalia möchte, dass Eure Heldentaten auf dem Schlachtfeld offiziell vom Oberkommando der Verlassenen in der Unterstadt anerkannt werden. Indem sie Euch mit ihrer versiegelten Belobigung direkt zu Varimathras schickt, stellt sie sicher, dass die Führung einen fähigen Champion anerkennt, dessen entscheidende Schläge den Widerstand der Menschen an der südlichen Front gebrochen haben.",al={"warum belobigung senden","darthalias motiv","warum zu varimathras schicken"}}},fp="19,156,19.392.0,27.343.0,19.177.0,51.133.0,42.228.0,31.162.0,54.144.0,61.174.0"}
P.entries["quest:5501"] = {n="Knochensammler",s="Bei Kormeks Hütte in Desolace wartet Bibbly F'utzbuckle auf zehn weitere Kodoknochen. Eine Karawane wird jeden Augenblick erwartet, und der Goblin glaubt, dass die Knochen die Welt verändern werden.",h="Bei Kormeks Hütte in Desolace wartet Bibbly F'utzbuckle auf zehn weitere Kodoknochen.",kw={"bibbly f'utzbuckle","knochensammler","desolace","goblin'preneur","kodoknochen","der kodofriedhof","kormeks hütte","schattenflucht"},sec={{t="Reichtum in alten Knochen",b="Bibbly F'utzbuckle sieht in den Kodoknochen rund um die Hütte ein Vermögen. Kunden machen daraus Möbel, Musikinstrumente und sogar Sprengpulver. Also schickt Bibbly Euch nach Süden zum Kodofriedhof, um zehn Knochen zu holen, und verspricht Euch etwas als Gegenleistung."},{t="Eine Karawane unterwegs",b="Eine Karawane kommt bei Kormeks Hütte vorbei, um Bibblys Kodoknochen abzuholen. Sie verkauft sie in Schattenflucht und wird jeden Augenblick erwartet. Bibbly fehlen noch zehn Knochen zum Höhepunkt seiner Karriere."},{t="Bibblys große Träume",b="Wenn die Knochen eintreffen, malt sich Bibbly aus, wie die Kumpel daheim Bibblys Gesicht groß auf dem Goblin'preneur sehen. Dann werden sie wissen, dass Bibbly zum reichsten Goblin der Welt geworden ist. Ein Sportlehrer sagte einmal, aus Bibbly würde nie etwas werden."}},faq={{q="Wer ist Bibbly F'utzbuckle?",a="Bibbly F'utzbuckle ist ein Goblin bei Kormeks Hütte in Desolace, der in Kodoknochen ein Vermögen sieht und zehn weitere sucht.",al={"wer vergibt knochensammler","bibbly futzbuckle","kormeks hütte goblin"}},{q="Warum braucht Bibbly Kodoknochen?",a="Bibblys Kunden stellen aus Kodoknochen Möbel, Musikinstrumente und sogar Sprengpulver her.",al={"wofür werden kodoknochen verwendet","warum kodoknochen"}},{q="Wohin kommen die Kodoknochen, nachdem Bibbly sie erhalten hat?",a="Eine Karawane holt Bibblys Kodoknochen ab und verkauft sie in Schattenflucht.",al={"wohin kommen die knochen","ziel der karawane"}},{q="Wo sind die Kodoknochen zu finden?",a="Der Kodofriedhof liegt südlich von Kormeks Hütte in Desolace. Bibbly schickt Euch dorthin, um Knochen zu sammeln.",al={"kodoknochen fundort","wo kodoknochen finden"}},{q="Wo liegt Kormeks Hütte?",a="Kormeks Hütte liegt in Desolace, nördlich des Kodofriedhofs.",al={"kormeks hütte standort","wo ist bibbly"}}},fp="14,165,20.244.0,20.170.0,19.251.1,26.111.0,32.97.0,50.76.0,34.98.0,22.57.0"}
P.entries["quest:5502"] = {n="Tageseltern der Horde",s="In Orgrimmar kehrt Grunth zum Ende der Kinderwoche zu Waisenmatrone Schlachterbe zurück. Nachdem das junge Waisenkind mit Euch die Welt gesehen hat, hofft es, selbst ein Held zu werden.",h="In Orgrimmar kehrt Grunth zum Ende der Kinderwoche zu Waisenmatrone Schlachterbe zurück.",kw={"schlachterbe","kinderwoche","grunth","orgrimmar","waisenkind","pfeife des orcischen waisenkindes","tal der ehre"},ang={["faction:Horde"]="Für die Horde bedeutet Stärke mehr als Geschick im Kampf. Sie bedeutet, die Schutzbedürftigen zu beschützen und zu stärken, die eines Tages das Banner des Kriegshäuptlings tragen werden.",["race:Orc"]="Als Orc wisst Ihr, dass Mut und Ehre zählen. Mitgefühl für ein Waisenkind wie Grunth zu zeigen, spiegelt den Edelmut wider, den Thrall der neuen Horde vermitteln möchte."},sec={{t="Abschied eines Waisenkindes",b="Nach Euren gemeinsamen Reisen dankt Grunth Euch dafür, dass Ihr ihm mehr gezeigt habt, als er je zu sehen erträumt hätte. Er erinnert sich an den Rat seiner Eltern, über Widrigkeiten hinauszuwachsen, und hofft, ein Held wie Ihr zu werden. Nun bittet er darum, nach Hause zurückzukehren und der Matrone von Eurer gemeinsamen Zeit zu erzählen."},{t="Heim ins Tal der Ehre",b="Ihr bringt Grunth zu Waisenmatrone Schlachterbe im Waisenhaus im Tal der Ehre zurück. In der neuen Horde ist die Fürsorge für die Jungen eine heilige Pflicht, denn der Krieg hat unzählige Kinder ohne Eltern zurückgelassen. Schlachterbe lobt Euer Mitgefühl als den wahren Maßstab für einen Helden der Horde. Grunth schenkt Euch ein geliebtes Haustier, damit Ihr Euch an das Band erinnert, das auf Euren Reisen entstanden ist."}},faq={{q="Was ist das Ziel dieser Quest?",a="Die Kinderwoche endet, wenn Ihr Grunth und die Pfeife des orcischen Waisenkindes zu Waisenmatrone Schlachterbe im Tal der Ehre zurückbringt.",al={"tageseltern der horde zusammenfassung","kinderwoche ende horde"}},{q="Wer ist Grunth?",a="Grunth ist ein junger Orc, der im Waisenhaus von Orgrimmar im Tal der Ehre lebt. Während der Kinderwoche führt ihn ein Champion der Horde durch Kalimdor, um legendäre Gestalten und großartige Sehenswürdigkeiten zu sehen.",al={"wer ist das orcische waisenkind","grunth hintergrundgeschichte"}},{q="Was bringe ich der Matrone zurück?",a="Bringt die Pfeife des orcischen Waisenkindes zu Waisenmatrone Schlachterbe, wenn Grunth bereit ist, nach Hause zurückzukehren.",al={"waisenpfeife zurückbringen","grunth pfeife zurückbringen"}},{q="Wer kümmert sich um die Waisenkinder in Orgrimmar?",a="Waisenmatrone Schlachterbe leitet das Waisenhaus von Orgrimmar im Tal der Ehre. Sie widmet ihr Leben dem Schutz und der Erziehung der Kriegswaisen der Horde.",al={"waisenmatrone horde","wer leitet das waisenhaus"}},{q="Warum möchte Grunth nach Hause zurückkehren?",a="Grunth möchte der Matrone von seinen Abenteuern und dem freundlichen Beschützer erzählen, der ihn mitgenommen hat. Seine Ausflüge während der Kinderwoche sind vorbei.",al={"grunth heimkehr","kinderwoche abschied"}},{q="Warum ist die Kinderwoche für die Horde wichtig?",a="Unablässige Kriege gegen Dämonen, Menschen und Zentauren haben unzählige Kinder der Horde ohne Familie zurückgelassen. Die Kinderwoche gibt Kriegern Zeit fernab der Schlacht, um die künftigen Generationen Durotars und darüber hinaus zu ehren.",al={"kinderwoche hintergrundgeschichte","warum kümmert sich die horde um waisenkinder"}}},fx={["02759f47"]={q="Warum die Pfeife des orcischen Waisenkindes zurückgeben?",a="Die Rückgabe der Pfeife an Waisenmatrone Schlachterbe schließt Eure Verantwortung für Grunth während der Kinderwoche ab. Er ist bereit, nach Hause in das Waisenhaus im Tal der Ehre zurückzukehren und der Matrone von seinen Abenteuern zu erzählen.",al={"waisenpfeife zurückgeben","pfeife der horde"}}},fp="21,163,20.266.0,27.357.0,34.125.0,14.196.0,35.96.0,38.153.0,36.132.0,46.214.0"}
P.entries["quest:551"] = {n="Das Verhexte Pergament",s="Am oberen Rand des Verhexten Pergaments ist nur der Name Nagaz lesbar. Ein Zauber verbirgt den Rest, also bringt Ihr es zu Meister der Lehren Dibbs in Süderstade.",h="Am oberen Rand des Verhexten Pergaments ist nur der Name Nagaz lesbar.",kw={"alterac","dibbs","verhext","nagaz","pergament","süderstade"},sec={{t="Ein zauberverhülltes Pergament",b="Ein Zauber verhindert, dass die Schrift auf dem Pergament gelesen werden kann. Nur Nagaz lässt sich am oberen Rand erkennen. Ihr bringt es zu Meister der Lehren Dibbs in Süderstade."},{t="Was Dibbs davon hält",b="Dibbs fragt, ob das Pergament weitere verschlüsselte Notizen enthält. Er wünscht, er könnte jedes sonderbare Schriftstück entziffern, das aus Alterac herüberweht. Doch er gibt zu, dass ihm das Wissen fehlt."}},faq={{q="Was steht auf dem Pergament?",a="Ein Zauber verbirgt die Schrift, bis auf ein Wort am oberen Rand: Nagaz.",al={"was steht auf dem verhexten pergament","pergamenttext","worte auf dem verhexten pergament"}},{q="Wer sollte das Pergament sehen?",a="Zeigt das Pergament Meister der Lehren Dibbs in Süderstade. Er nimmt Bruchstücke alten Wissens entgegen, die in den Bergen gesammelt wurden.",al={"meister der lehren dibbs","wer ist dibbs","meister der lehren in süderstade"}}},fp="25,144,24.140.0,22.176.1,33.65.0,29.109.0"}
P.entries["quest:552"] = {n="Helculars Rache",s="In Tarrens Mühle dreht sich Helculars Rache um Thaivands Racheschwur. Meister Helcular, ein großer Zauberer, der kurz davor stand, ein Lich zu werden, wurde von einem Lynchmob aus Menschen getötet, nachdem dieser sein rituelles Versteck in den Hügeln gefunden hatte. Bevor die Rache über Süderstade hereinbricht, braucht Thaivand Helculars Rute, die seiner Ansicht nach einer der Yetis besitzt.",h="In Tarrens Mühle dreht sich Helculars Rache um Thaivands Racheschwur.",kw={"alterac","helcular","hillsbrad","lich","rute","süderstade","tarrens mühle","thaivand","yeti"},ang={["faction:Horde"]="Als Abenteurer der Horde hört Ihr in Tarrens Mühle von Thaivand."},sec={{t="Ein Meister wird unterbrochen",b="Meister Helcular stand kurz davor, ein Lich zu werden, als ein Lynchmob aus Menschen sein rituelles Versteck in den Hügeln fand und ihn tötete. Sie begruben seinen Leichnam auf dem Friedhof von Süderstade. Thaivand, sein Lehrling, hält diese Behandlung eines großen Zauberers für inakzeptabel. Er schwört, dass Süderstade die Rache zu spüren bekommen wird."},{t="Die verschwundene Rute",b="Thaivand sagt, dass zuerst Helculars Rute gefunden werden muss. Yetis haben das rituelle Versteck übernommen, und Thaivand ist sicher, dass einer von ihnen die Rute hat. So viele Yetis streifen durch die Region, dass die Suche schwierig sein wird. Ihr könnt sie bei der Eisfellhöhle und bei Darrow Hill finden."}},faq={{q="Wer war Meister Helcular?",a="Meister Helcular war ein großer Zauberer, der kurz davor stand, ein Lich zu werden. Ein Lynchmob aus Menschen fand sein rituelles Versteck in den Hügeln, tötete ihn und begrub seinen Leichnam auf dem Friedhof von Süderstade.",al={"wer ist helcular","helcular geschichte","helcular hintergrundgeschichte"}},{q="Warum will Novize Thaivand Helculars Rute?",a="Thaivand, Helculars Lehrling, plant Rache an Süderstade. Er sagt, dass zuerst die Rute gefunden werden muss.",al={"warum wird die rute benötigt","helculars rute zweck","thaivands ziel"}},{q="Wo ist die Rute geblieben?",a="Yetis haben Helculars rituelles Versteck übernommen, und Thaivand ist sicher, dass einer von ihnen die Rute hat. Ihr könnt Yetis bei der Eisfellhöhle und bei Darrow Hill finden.",al={"wo ist die rute","wie kamen yetis an die rute","rute fundort"}},{q="Wo befindet sich Novize Thaivand?",a="Novize Thaivand ist in Tarrens Mühle im Vorgebirge des Hügellands.",al={"thaivand aufenthaltsort","wo helculars rache abgeben","novize thaivand"}}},fp="18,318,20.292.0,15.249.0,24.175.0,45.102.0,21.142.0,33.62.0"}
P.entries["quest:553"] = {n="Helculars Rache",s="In Hillsbrad beginnt Helculars Rache mit einer Rute und drei Flammen. Novize Thaivand gibt Euch die Rute von Helcular. Helcular errichtete drei zeremonielle Scheiterhaufen für seinen mächtigsten Zauber, und jede Flamme muss die Rute aufladen, bevor sie in Helculars Grab in Süderstade gerammt wird.",h="In Hillsbrad beginnt Helculars Rache mit einer Rute und drei Flammen.",kw={"alterac","azel","darrow hill","eisfellhöhle","helcular","hillsbrad","süderstade","thaivand","uzel","veraz"},sec={{t="Die drei Flammen",b="Helcular errichtete drei zeremonielle Scheiterhaufen für seinen mächtigsten Zauber, und jede Flamme muss die Rute aufladen. Die Flammen von Azel und Veraz brennen in der Yetihöhle bei Darrow Hill, innerhalb der Vorgebirgshöhlen. Die Flamme von Uzel befindet sich in einer kleinen Höhle oberhalb der Vorgebirgshöhlen, weiter nördlich in den Bergen nahe der Eisfellhöhle."},{t="Das Grab in Süderstade",b="Nachdem alle drei Flammen die Rute aufgeladen haben, soll sie in Helculars Grab in Süderstade gerammt werden, einer schwer bewachten Stadt der Menschen. Der Friedhof liegt in der nordöstlichen Ecke der Stadt am Fluss. Helculars Grab liegt in der südöstlichen Ecke des Friedhofs."},{t="Nach dem Ritual",b="Wenn die aufgeladene Rute in Helculars Grab gerammt wird, erbebt der Boden heftig. Helcular kehrt zurück und streift über den Friedhof von Süderstade, wobei er Menschen in der Nähe angreift."}},faq={{q="Wo befinden sich die drei zeremoniellen Flammen?",a="Die Flamme von Azel und die Flamme von Veraz befinden sich in der Yetihöhle bei Darrow Hill, innerhalb der Vorgebirgshöhlen im Vorgebirge des Hügellands. Die Flamme von Uzel befindet sich in einer kleinen Höhle oberhalb dieser Höhlen, weiter nördlich in den Bergen nahe der Eisfellhöhle im Alteracgebirge.",al={"standorte der flammen","wo ist die flamme von azel","wo ist die flamme von uzel","scheiterhaufen finden"}},{q="Wo liegt Helculars Grab?",a="Helculars Grab liegt in Süderstade, einer schwer bewachten Stadt der Menschen. Der Friedhof liegt in der nordöstlichen Ecke der Stadt am Fluss, und das Grab befindet sich in seiner südöstlichen Ecke.",al={"helculars grab finden","wo ist das grab","friedhof von süderstade"}},{q="Wer stellt die Rute von Helcular bereit?",a="Die Rute stammt von Novize Thaivand, Helculars Lehrling.",al={"wer gibt die rute","questgeber","novize thaivand"}},{q="Was geschah vor dieser Quest?",a="Zuvor musste für Novize Thaivand Helculars Rute gefunden werden. Thaivand ist Helculars Lehrling. Eine Menschenmenge lynchte Helcular, und er wurde auf dem Friedhof von Süderstade begraben.",al={"vorherige quest","helcular questreihe teil eins"}}},fp="18,278,16.311.0,23.248.0,16.161.1,46.248.0,26.173.0,33.58.0,28.170.0"}
P.entries["quest:554"] = {n="Stormpikes Entschlüsselung",s="In Eisenschmiede schickt Euch Meister der Lehren Dibbs mit einem verhexten Pergament zu Ausgrabungsleiter Sturmlanze.",h="In Eisenschmiede schickt Euch Meister der Lehren Dibbs mit einem verhexten Pergament zu Ausgrabungsleiter...",kw={"entschlüsselung","dibbs","verhextes pergament","eisenschmiede","hauptquartier der ausgrabungsleiter","sturmlanze"},sec={{t="Ein Meister der Entschlüsselung",b="Nach „Verhextes Pergament“ schickt Dibbs Euch mit dem Pergament nach Eisenschmiede. Ausgrabungsleiter Sturmlanze geht im Hauptquartier der Ausgrabungsleiter seinen Studien nach. Sagt ihm, dass Dibbs Euch geschickt hat; Dibbs hat Sturmlanze in letzter Zeit reichlich Kundschaft beschert."},{t="Eine Frage der Zeit",b="Ausgrabungsleiter Sturmlanze entdeckt einen feinen, kunstvoll gewobenen Zauber auf dem Pergament. Er sagt, dass er ihn entwirren kann, doch die Arbeit wird Zeit brauchen, und seine Zeit ist kostbar. Er bietet Euch an, das Pergament zu kaufen.\n\nSobald Ihr zustimmt, sagt Sturmlanze, er glaube, dass kein anderer Gelehrter es übersetzen könne. Sollte sich sein Inhalt als interessant erweisen, verspricht er, nach Euch schicken zu lassen."}},faq={{q="Wer schickt Euch zu Ausgrabungsleiter Sturmlanze?",a="Meister der Lehren Dibbs schickt Euch zu Ausgrabungsleiter Sturmlanze, den er einen Meister der Entschlüsselung und Dechiffrierung nennt.",al={"wer vergibt die quest","questgeber","meister der lehren dibbs quest"}},{q="Wo ist Ausgrabungsleiter Sturmlanze zu finden?",a="Ausgrabungsleiter Sturmlanze geht im Hauptquartier der Ausgrabungsleiter in Eisenschmiede seinen Studien nach.",al={"sturmlanze standort","wo ist sturmlanze","hauptquartier der ausgrabungsleiter"}},{q="Warum ist das Pergament schwer zu lesen?",a="Ein Zauber verschleiert die Schrift, sodass nur der Name Nagaz am oberen Rand lesbar bleibt.",al={"warum verhextes pergament","pergament zauber","warum entschlüsseln"}},{q="Was kommt vor diesem Schritt?",a="„Verhextes Pergament“ kommt vor diesem Schritt und bringt das verzauberte Pergament zu Dibbs.",al={"vorherige quest","beginn der questreihe","voraussetzung"}}},fp="23,95,22.232.0,16.343.1,38.105.0,40.77.0,39.78.0,28.93.0"}
P.entries["quest:5541"] = {n="Munition für Schlingerschuss",s="Büchsenmacher Hegnar Schlingerschuss gehen Schrot und Pulver für die Scharfschützen aus, die außerhalb von Ambossar üben. Eine verschollene Kiste mit Munition wurde in der verschneiten Wildnis nahe dem altgedienten Bau zurückgelassen, als ein Kurier von hungrigen Wendigos in die Flucht geschlagen wurde.",h="Büchsenmacher Hegnar Schlingerschuss gehen Schrot und Pulver für die Scharfschützen aus, die außerhalb von...",kw={"munition","ambossar","coldridge","der altgediente bau","hegnar","loslor rudge","rumbleshot","wendigo"},ang={["class:Hunter"]="Jeder Schütze im Coldridgetal kennt Hegnars Laden gut; seine Regale mit frischem Pulver und Schrot gefüllt zu halten stellt sicher, dass Ihr der Wildnis niemals mit einem leeren Gewehr entgegentretet.",["profession:Engineering"]="Zwergische Schusswaffen und Mörser verlangen nach feinst gemahlenem Pulver und ebenmäßigem Schrot, was Schlingerschusss Inventar für örtliche Tüftler und Schützen unverzichtbar macht.",["race:Dwarf"]="Zwergische Handwerkskunst stützt sich auf eine unerschütterliche Lieferkette zwischen den Schmieden von Ambossar und Büchsenmachern an vorderster Front wie Schlingerschuss."},sec={{t="Die Flucht eines Kuriers",b="Loslor Rudge in Stahlrosts Depot hält stetige Nachschubwege zu Händlern in ganz Dun Morogh aufrecht, doch die Tierwelt des Tals stört oft die Abläufe. Seine jüngste Lieferung schwerer Munition erreichte nie die Werkstatt von Hegnar Schlingerschuss an der Straße. Als er in der Nähe des Höhlensystems namens Der altgediente Bau lagerte, kreuzte der verängstigte Kurier den Weg einheimischer Wendigos und floh um sein Leben, wobei er die schwere Holzkiste im Schnee zurückließ."},{t="Pulver und Schrot",b="Hegnar Schlingerschuss betreibt ein Waffengeschäft direkt an der Hauptstraße, die von Ambossar wegführt. Auf der Lichtung vor seiner Schmiede herrscht ständiger Betrieb durch Scharfschützen aus Eisenschmiede, Gebirgsjäger und Zwergenmörser-Trupps, die ihre Visiere einstellen und mit scharfer Munition üben wollen. Ohne stetige Kisten mit Pulver und Blei von Lieferanten wie Loslor kommt das Schießtraining der Scharfschützen schnell völlig zum Erliegen."}},faq={{q="Wo ging die Munitionskiste verloren?",a="Loslor Rudges verängstigter Kurier ließ die Lieferung fallen, als er direkt vor dem Graufelsbau lagerte, einer von Wendigos heimgesuchten Höhle in den verschneiten Hügeln südwestlich von Kharanos.",al={"ort der munition","wo ist rumbleshots munition","kistenstandort"}},{q="Wer ist Hegnar Schlingerschuss?",a="Hegnar Schlingerschuss ist ein zwergischer Büchsenmacher, der einen Waffenladen an der Straße nahe Ambossar betreibt. Er versorgt die Gebirgsjäger, Jäger und Belagerungsteams, die in der Nähe Manöver abhalten, mit Pulver, Kugeln und Schusswaffen.",al={"wer ist hegnar","rumbleshot","hegnar schlingerschuss"}},{q="Warum wurde der Kurier vertrieben?",a="Der Kurier beging den Fehler, in der Nähe des Graufelsbaus zu lagern, der Höhle der wilden, territorialen Wendigos, welche die Hügel südwestlich von Kharanos durchstreifen.",al={"warum der kurier floh","wendigoangriff","kuriergeschichte"}},{q="Warum hat Hegnar Schlingerschuss keine Munition mehr?",a="Zwergische Scharfschützen und Mörserteams verbrauchen bei Zielübungen in der Nähe von Hegnars Werkstatt ständig Pulver und Blei, wodurch seine Vorräte heiß begehrt sind.",al={"warum wenig munition","rumbleshot keine munition"}},{q="Wer ist Loslor Rudge?",a="Loslor Rudge ist ein zwergischer Ingenieurbedarfshändler in Stahlrosts Depot, dessen Betrieb Munition an Hegnar Schlingerschuss liefert.",al={"loslor rudge","wer ist loslor"}},{q="Verdirbt wiedergefundene Munition im Schnee?",a="Zwergische Munition wird traditionell in schweren, wetterfesten Holzkisten verpackt, um Schwarzpulver selbst bei den eisigen Schneestürmen von Dun Morogh trocken und zündbereit zu halten.",al={"munition durch schnee ruiniert","nasses pulver"}}},fx={["76205b16"]={q="Warum muss Loslor Rudge diese Munition ausliefern lassen?",a="Loslor Rudge arbeitet von Stahlrosts Depot aus und beliefert Händler im gesamten Dun Morogh. Hegnar Schlingerschuss wartet auf eine überfällige Lieferung, um lokale Schützen und Mörserteams mit Übungsmunition zu versorgen. Ein Kurier geriet in Panik und ließ die Kiste zurück, als Wendigos ihr Lager angriffen, was Loslors geschäftliche Verpflichtung unerfüllt ließ und einen geschätzten Kunden leer ausgehen ließ, bis Ihr sie sicherstellt.",al={"warum kümmert das loslor","loslor rudges motiv","warum die munition schicken"}},c1dcb566={q="Wofür wird Schlingerschuss' Munition verwendet?",a="Die Kiste enthält frische Munition, die für Hegnar Schlingerschuss' Laden an der Straße nach Ambossar bestimmt ist. Zwergische Schützen und Mörserteams trainieren häufig in der Nähe und verbrauchen schnell Vorräte, wobei sie sich auf Hegnar verlassen, um ihre Pulverhörner und Munitionstaschen gefüllt zu halten.",al={"was ist schlingerschuss-munition","verwendung der kiste von schlingerschuss","warum wird munition gebraucht"}}},fp="19,152,18.278.0,15.368.0,30.156.0,25.189.0,31.120.0,43.147.0,20.111.0,44.166.0"}
P.entries["quest:5545"] = {n="Ein Bündel Probleme",s="Im Holzfällerlager des Osttals kämpft Vorsteherin Raelen darum, die Lieferfrist für Bauholz für Sturmwind einzuhalten. Wölfe und Bären haben ihre Holzfäller aus den nördlichen Wäldern vertrieben, sodass die Bündel mit geschlagenem Holz zurückblieben.",h="Im Holzfällerlager des Osttals kämpft Vorsteherin Raelen darum, die Lieferfrist für Bauholz für Sturmwind...",kw={"bären","kleinholzbündel","stellvertreter rainer","osttal","wald von elwynn","holzfällerlager","vorsteherin raelen","bauholz","wölfe"},ang={["class:Hunter"]="Als Jäger könnt Ihr in Gehölzen voller Raubtiere Spuren verfolgen und Euch den einheimischen Bestien stellen, während Ihr die Vorräte bergt.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr helfen, den Wiederaufbau Sturmwinds und die Außenposten der Region mit Bauholz aus dem Osttal zu versorgen."},sec={{t="Eine drohende Lieferfrist",b="Bauholz aus dem Osttal dient im ganzen Königreich dem Wiederaufbau von Städten und der Verstärkung von Brücken, doch diese wichtige Lieferung ist in Verzug geraten. Die Lieferfrist rückt näher, und Vorsteherin Raelen bleibt wenig Zeit."},{t="Raubtiere im Gehölz",b="Nördlich des Lagers vertrieben Wölfe und Bären die Holzfäller von den Holzbündeln, die sie geschlagen und verschnürt hatten. Raelen kann nicht warten, bis Wachen die Wälder sichern, und bittet Euch deshalb, das Bauholz zurückzubringen, bevor der Auftrag verloren geht."}},faq={{q="Wer ist Vorsteherin Raelen?",a="Vorsteherin Raelen leitet das Holzfällerlager des Osttals im östlichen Wald von Elwynn. Sie beaufsichtigt die Holzfäller und die Bauholzlieferungen für Sturmwind und die umliegenden Siedlungen.",al={"vorsteherin raelen","raelen","vorsteherin osttal"}},{q="Warum liegt das Holz verlassen im Wald?",a="Die Arbeiter hatten die Stämme bereits geschlagen und gebündelt, als Bären und Wölfe sie von der Lichtung vertrieben. Sie flohen ohne das Holz ins Lager.",al={"warum holz zurückgelassen","verlassenes bauholz","holz im wald"}},{q="Warum erwähnt Raelen Stellvertreter Rainer?",a="Raelen sagt, sie habe Stellvertreter Rainer wegen der Raubtiere kontaktiert. Er ist in der Weststromgarnison stationiert, weit entfernt auf der anderen Seite des Waldes von Elwynn. Die Nachricht könnte über die Wachen weitergeleitet worden sein, oder die örtlichen Ordnungskräfte sind womöglich überlastet.",al={"stellvertreter rainer raelen","warum stellvertreter rainer","verbindung zu rainer"}},{q="Wo wird das Bauholz gebraucht?",a="Das Holzfällerlager des Osttals liefert Bauholz ins ganze Königreich, um Städte wiederaufzubauen und Palisaden und Brücken zu verstärken. Eine versäumte Lieferfrist kann Elwynns Wirtschaft schaden und Bauarbeiten verzögern.",al={"wer braucht das holz","bauholzlieferung","verwendungszweck bauholz"}},{q="Warum können die Holzfäller das Holz nicht selbst holen?",a="Die Holzfäller sind Arbeiter, die Bäume fällen, keine im Kampf gegen Raubtiere ausgebildeten Kämpfer. Wölfe und Bären haben sie vertrieben, und sie werden nicht unbewaffnet ins Dickicht zurückkehren.",al={"warum holzfäller angst haben","warum nicht die holzfäller","holzfäller wölfe"}},{q="Wo sind die Holzbündel zu finden?",a="Die Bündel liegen im Wald direkt nördlich des Holzfällerlagers des Osttals, wo die Arbeiter tätig waren, bevor einheimische Bestien sie vertrieben.",al={"fundort holz","wo liegen die bündel","bündel finden"}}},fx={d8093908={q="Warum braucht Vorsteherin Raelen dieses Holz so schnell?",a="Vorsteherin Raelen steht unter einer strengen Lieferfrist für eine Holzbestellung. Wenn sie das versprochene Holz nicht rechtzeitig liefert, leiden die Holzfällerbetriebe von Eastvale und ihr Ruf. Das Holz ist bereits geschlagen, aber die Arbeiter des Lagers mussten fliehen, als wilde Raubtiere auftauchten, wodurch die gesamte Lieferung gefährdet ist.",al={"warum braucht raelen holz","raelens frist","warum die holzbestellung beschleunigen"}}},fp="19,201,18.206.0,23.213.0,25.167.0,39.131.0,38.215.0,27.180.0,50.167.0,39.134.0"}
P.entries["quest:555"] = {n="Milde Schildkrötensuppe",s="Küchenchef Jessen will Milde Schildkrötensuppe wieder auf die Speisekarte der Taverne in Süderstade setzen. Unruhen haben seinen Nachschub an Snapjaw-Schildkrötenfleisch abgeschnitten, also bittet er Köche, sich in die nördlichen Gewässer nahe Dalaran und dem Lordameresee zu wagen.",h="Küchenchef Jessen will Milde Schildkrötensuppe wieder auf die Speisekarte der Taverne in Süderstade setzen.",kw={"küchenchef jessen","cooking","dalaran","hillsbrad","der lordameresee","snapjaw","milde schildkrötensuppe","süderstade","schildkrötenfleisch"},ang={["faction:Alliance"]="Süderstades Annehmlichkeiten wiederherzustellen hilft, die Stimmung vor Ort zu heben, während die Stadt den Gesetzlosen des Syndikats und der Ausbreitung der Verlassenen allein gegenübersteht.",["profession:Cooking"]="Küchenchef Jessen teilt sein Handwerk nur mit anderen Köchen. Er lehrt Euch, Eure eigene Milde Schildkrötensuppe zuzubereiten.",["race:Human"]="Als Mensch aus den südlichen Königreichen findet Ihr in Jessens Küche vielleicht einen seltenen Geschmack von Heimat und Gastfreundschaft, hier im umkämpften Norden."},sec={{t="Eine nördliche Delikatesse",b="Süderstade ist eine der letzten intakten Küstenstädte Lordaerons, die von der Allianz gehalten werden. Trotz zunehmender Konflikte geht das zivile Leben dort weiter. Küchenchef Jessen sagt, seine Kochkunst könne es mit jeder Taverne nördlich von Sturmwind aufnehmen. Angeblich kommen Gäste aus Dunkelhain im Dämmerwald, um seine Suppe zu kosten. Die reichhaltige Suppe verlangt nach frischem Fleisch von Snapjaw-Schildkröten, die in den Flüssen und Seen der nördlichen Berge heimisch sind."},{t="Gefahr am Lordameresee",b="In ruhigeren Jahren beschaffte Jessen sein Schildkrötenfleisch selbst. Er reiste an Dalaran vorbei zum Ostufer des Lordameresees. Nun machen wachsende Spannungen, feindselige Wildtiere, das Syndikat und Vorstöße der Verlassenen das Umland für gewöhnliche Stadtbewohner tödlich. Damit die Suppe auf seiner Speisekarte bleibt, verlässt sich Jessen auf bewaffnete Reisende, die Fleisch von Snapjaws an den Flussufern und nördlichen Seeufern beschaffen."}},faq={{q="Wer bietet die Quest für Milde Schildkrötensuppe an?",a="Küchenchef Jessen, ein Koch in Süderstade, richtet die Bitte an durchreisende Köche. Süderstade ist eine Küstenstadt der Allianz im Vorgebirge des Hügellands.",al={"wer vergibt milde schildkrötensuppe","wo beginnt milde schildkrötensuppe","küchenchef jessen quest"}},{q="Warum braucht Küchenchef Jessen fremde Hilfe beim Beschaffen von Schildkrötenfleisch?",a="Jessen jagte einst Snapjaw-Schildkröten nahe Dalaran und dem Lordameresee. Unruhen und gefährliche Bestien machen die Gegend inzwischen zu gefährlich, als dass er selbst Fleisch beschaffen könnte.",al={"warum bekommt jessen kein fleisch","warum braucht jessen schildkröten"}},{q="Wo sind Snapjaw-Schildkröten in der Gegend zu finden?",a="Snapjaw-Schildkröten leben am Süßwasserfluss zwischen dem Vorgebirge des Hügellands und dem Alteracgebirge sowie an den Ufern des Lordameresees nördlich von Dalaran.",al={"schildkrötenfleisch fundort","wo sind snapjaws","wo schildkrötenfleisch farmen"}},{q="Müsst Ihr Cooking beherrschen, um diese Quest anzunehmen?",a="Ja. Küchenchef Jessen teilt seine Bitte und sein Wissen über das Kochen nur mit Reisenden, die in Cooking ausgebildet sind. Ein bestimmter Fertigkeitsrang ist nicht erforderlich.",al={"ist cooking erforderlich","beruf cooking erforderlich","kann jeder milde schildkrötensuppe annehmen"}},{q="Warum ist Süderstades Küche berühmt?",a="Küchenchef Jessen behauptet, Süderstade habe die feinste Küche nördlich von Sturmwind. Seine Schildkrötensuppe lockt angeblich sogar Gäste aus dem fernen Dunkelhain an.",al={"süderstade essen","warum ist jessen berühmt","anreise aus dunkelhain für suppe"}},{q="Welche Unruhen beklagt Küchenchef Jessen?",a="Hillsbrad und Alterac stehen im offenen Konflikt mit den Verlassenen aus dem Norden, Gesetzlosen des Syndikats in den Ruinen und wilden Raubtieren, die durch Lordaerons Fall verdrängt wurden. Für Zivilisten sind Reisen gefährlich geworden.",al={"hillsbrad unruhen","warum ist es jetzt gefährlich","welche unruhen"}}},fx={d8a3c1e1={q="Warum möchte Küchenchef Jessen, dass dies erledigt wird?",a="Küchenchef Jessen ist sehr stolz auf den kulinarischen Ruf von Süderstade und rühmt sich damit, dass die Stadt einige der besten Gerichte nördlich von Sturmwind anbietet. Sein berühmtes Geheimrezept für Soothing Turtle Bisque lockt Reisende sogar aus dem fernen Dunkelhain an, doch die jüngste Gewalt in der Region hat seine Zutatenversorgung unterbrochen. Indem Ihr das nötige Schildkrötenfleisch sammelt, ermöglicht Ihr es ihm, sein Markenzeichen-Gericht wieder zu servieren und der belagerten Stadt Trost zu spenden.",al={"warum schildkrötenbisque zubereiten","küchenchef jessens motiv","warum will jessen schildkrötenfleisch"}},bb599998={q="Wofür ist das Schildkrötenfleisch?",a="Das Fleisch ist die wesentliche Zutat für Küchenchef Jessens Geheimrezept für Soothing Turtle Bisque. Sammler beschaffen es normalerweise von Schnappkiefer-Schildkröten in den nördlichen Gewässern, wie dem Lordameresee, was es dem Koch ermöglicht, seine beliebte regionale Spezialität wieder zu köcheln.",al={"wofür wird schildkrötenfleisch verwendet","warum schildkrötenfleisch","zweck von schildkrötenfleisch"}}},fp="22,197,19.384.0,18.390.0,48.134.0,61.160.0,46.154.0,47.137.0,35.145.0,39.203.0"}
P.entries["quest:556"] = {n="Steinmarken",s="In Tarrens Mühle schickt Euch Bewahrer Bel'varil los, um Steinmarken von Dalarans Agenten in Alterac zu beschaffen. Die Verlassenen wollen erfahren, wie Dalarans Magier Elementare binden und befehligen. Magus Voidglare untersucht diese arkanen Methoden für sie.",h="In Tarrens Mühle schickt Euch Bewahrer Bel'varil los, um Steinmarken von Dalarans Agenten in Alterac zu...",kw={"alteracgebirge","bindung","dalaran","elementare","vorgebirge des hügellands","bewahrer bel'varil","magus voidglare","steinmarken","tarrens mühle","abgenutzte steinmarke"},ang={["class:Mage"]="Als Magier wisst Ihr, dass Dalarans Beschwörer dafür bekannt sind, Elementare ihrem Willen zu unterwerfen. Diese Marken offenbaren, wie menschliche Magier Geister aus anderen Ebenen an materielle Foki binden.",["class:Shaman"]="Als Schamane ehrt Ihr Elementare durch gegenseitige Pakte. Dalarans Zauberer nutzen arkane Marken, um sie zu beherrschen und zu versklaven, entgegen dem Weg spiritueller Harmonie.",["race:Undead"]="Als einer der Verlassenen in Tarrens Mühle wisst Ihr, dass die Entschlüsselung von Dalarans arkanen Geheimnissen für Lordaerons Verteidigung gegen menschliche Zauberer dicht vor seinen Mauern zählt."},sec={{t="Arkane Unterwerfung",b="Dalarans Magier befehligen seit Langem elementare Wesen mithilfe spezieller Leitungen und verzauberter Foki. Sie binden Kreaturen aus anderen Dimensionen und zwingen sie in die Knechtschaft.\n\nObwohl sich die Stadt noch im Wiederaufbau befindet, patrouillieren ihre Agenten und verbliebenen Streitkräfte im umliegenden Gebiet. Sie setzen Elementare als Arbeitskräfte und defensive Stoßtruppen ein. Magus Voidglare, ein arkaner Forscher in Tarrens Mühle, arbeitet für die Verlassenen und will die Zauberei ergründen, die diese Wesen zum Gehorsam zwingt."},{t="Inerte Proben sammeln",b="Bewahrer Bel'varil weist Euch an, abgenutzte, verblasste Marken zu sammeln, bevor Ihr nach mächtigen und unberechenbaren magischen Instrumenten sucht. Dalarans Personal trägt sie in den Randgebieten und im nahe gelegenen Internierungslager bei sich.\n\nVoidglare kann die verbliebenen Verzauberungen untersuchen, ohne eine unkontrollierte planare Rückwirkung zu riskieren. Diese verwitterten Marken vermitteln ihm die theoretischen Grundlagen, die er braucht, bevor er stärkere Bindemittel erprobt."}},faq={{q="Wozu dienen die Steinmarken?",a="Dalarans Zauberer fertigen und tragen Steinmarken als magische Foki, um Elementare zu befehligen und zu unterwerfen. Sie zwingen Kreaturen aus anderen Dimensionen, als Wachen, Wachposten und Arbeitskräfte zu dienen.",al={"zweck der steinmarken","warum haben dalarans zauberer steinmarken","was bewirken die marken"}},{q="Warum will Magus Voidglare ausdrücklich abgenutzte Marken?",a="Abgenutzte Steinmarken bewahren die grundlegende Matrix von Dalarans Bindungszaubern, obwohl ihre aktive arkane Macht verblasst ist. Dadurch kann Magus Voidglare sie sicherer untersuchen, ohne Vergeltung durch Elementare oder magische Rückkopplungen zu riskieren.",al={"warum abgenutzte steinmarken","warum keine aktiven marken"}},{q="Wer ist Bewahrer Bel'varil?",a="Bewahrer Bel'varil ist ein Verlassener, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Er unterstützt Magus Voidglare, indem er magische Artefakte und Reagenzien aus nahe gelegenen Gebieten beschafft.",al={"belvaril","wer vergibt den auftrag steinmarken"}},{q="Wo haben Dalarans Streitkräfte diese Marken?",a="Dalarans Zauberer und ihr Personal tragen die Marken entlang der Grenze zwischen dem westlichen Hillsbrad und dem Alteracgebirge bei sich. Sie sind nahe Dalaran selbst und bei den nahe gelegenen Ruinen des alten Internierungslagers für Orcs zu finden.",al={"wo steinmarken finden","standort von dalarans streitkräften"}},{q="Was geschieht, nachdem diese Marken abgeliefert wurden?",a="Nachdem Bel'varil die inerten Proben untersucht hat, geht Magus Voidglare von der Theorie zur physischen Gefangensetzung über. Er erteilt den Auftrag, schwerere Bracers of Binding direkt von den Elementaren zu beschaffen.",al={"was kommt nach steinmarken","folgeauftrag von steinmarken"}},{q="Warum untersucht die Horde Dalarans Magie?",a="Die Verlassenen betrachten Dalarans überlebende Magier als territoriale und magische Bedrohung in Lordaeron. Indem sie deren Methoden erlernen, können die Zauberwirker der Verlassenen Einsätzen der Kirin Tor entgegenwirken, ihre Grenzen schützen und vielleicht elementare Kräfte für sich nutzen.",al={"warum will die horde dalarans magie","interesse der verlassenen an dalaran"}}},fx={["618b6456"]={q="Warum möchte Bewahrer Bel'varil, dass diese Steintoken gesammelt werden?",a="Bewahrer Bel'varil handelt im Auftrag von Magus Leerenblick, einem Magier der Verlassenen in Tarrens Mühle, der versucht, die arkanen Praktiken von Dalaran zu entschlüsseln. Die Magier von Kirin Tor sind bekannt für ihre Meisterschaft über extradimensionale Elementare, die sie durch verzauberte Steine beherrschen. Leerenblick beabsichtigt, die Token zu studieren, um ihre bindenden Geheimnisse zu entschlüsseln und das Verständnis der Verlassenen über die Kontrolle der Elemente zu erweitern.",al={"warum will bewahrer bel'varil steintoken","bel'varils motiv für steintoken","warum abgenutzte steintoken sammeln"}},["4e88982b"]={q="Wer sind die Streitkräfte von Dalaran, die das Internierungslager bewachen?",a="Ihr werdet gegen die Magier von Kirin Tor und die Wachen ausgesandt, die die zerstörten Internierungslager und das Land westlich von Hillsbrad entlang der Grenze zu Alterac besetzen. Nach dem Dritten Krieg und der Zerstörung von Dalaran halten diese menschlichen Überbleibsel eine hartnäckige Enklave aufrecht und nutzen elementare Diener und Schutzzauber, um ihren Besitz gegen die Verlassenen und andere regionale Bedrohungen zu sichern.",al={"wer sind die kräfte von dalaran in hillsbrad","warum sind dalaran-magier im internierungslager","dalaran-ziel steintoken"}}},fp="12,229,18.477.0,24.393.1,35.192.0,55.231.0,24.177.0,50.212.0,46.198.1,42.256.0"}
P.entries["quest:5561"] = {n="Kodozusammentrieb",s="In Scrabblescrews Lager werden fünf gezähmte Kodos für eine bald eintreffende Karawane gebraucht. Ihr tragt Smeed Scrabblescrews Kodokombobulator hinaus unter die uralten, gealterten und sterbenden Kodos von Desolace und führt dann jedes gezähmte Tier zurück zum Lager.",h="In Scrabblescrews Lager werden fünf gezähmte Kodos für eine bald eintreffende Karawane gebraucht.",kw={"bibbly","cork","desolace","kodo","kodokombobulator","rigger","scrabblescrews lager","smeed scrabblescrew"},sec={{t="Eine Karawane unterwegs",b="Eine Karawane wird in Kürze in Scrabblescrews Lager erwartet, und Smeed Scrabblescrew sagt, sie sei auf ihn angewiesen. Bibbly glaubt, kein anderer Goblin in Desolace wisse, wie man Profit macht. Smeed sieht das anders. Er ist eine Partnerschaft mit Cork und Rigger eingegangen, und die Karawane ist bereit, diesem Land zu trotzen."},{t="Der Kodokombobulator",b="Smeed hat den Kodokombobulator gebaut, um gealterte und sterbende Kodos wiederzubeleben und unter Kontrolle zu bringen. Richtet ihn auf einen uralten, gealterten oder sterbenden Kodo, und das Gerät macht das Tier mit einem Stromstoß zu einem gezähmten Kodo, der Euch folgt. Bringt fünf Kodos und das Gerät zurück zu Scrabblescrews Lager."}},faq={{q="Wer ist Smeed Scrabblescrew?",a="Smeed Scrabblescrew befindet sich in Scrabblescrews Lager in Desolace. Er hat den Kodokombobulator erfunden und ist eine Partnerschaft mit Cork und Rigger eingegangen. Bibbly glaubt, kein anderer Goblin in Desolace wisse, wie man Geld verdient, doch Smeed sieht das anders.",al={"wer ist smeed","smeed scrabblescrew hintergrund","scrabblescrew"}},{q="Warum braucht Smeed gezähmte Kodos?",a="Smeed wartet auf fünf frisch gezähmte Kodos. Die Karawane, die auf ihn angewiesen ist, wird in Kürze in Scrabblescrews Lager erwartet.",al={"warum kodos zähmen","kodozusammentrieb zweck","warum will smeed kodos"}},{q="Was ist der Kodokombobulator?",a="Smeed hat den Kodokombobulator gebaut, um gealterte oder sterbende Kodos wiederzubeleben und unter Kontrolle zu bringen. Er macht ein anvisiertes Tier mit einem Stromstoß zu einem gezähmten Kodo, der Euch folgt.",al={"was macht der kombobulator","kodokombobulator hintergrund"}},{q="Bei welchen Kodos könnt Ihr den Kombobulator einsetzen?",a="Ihr könnt den Kodokombobulator bei uralten, gealterten und sterbenden Kodos einsetzen. Sobald ein Kodo gezähmt ist, folgt er Euch zurück zu Scrabblescrews Lager.",al={"welche kodos zähmen","kodozusammentrieb kodos"}},{q="Wer ist Bibbly?",a="Bibbly ist ein Goblin in Desolace, der glaubt, kein anderer Goblin dort wisse, wie man Geld verdient. Smeed Scrabblescrew sieht das anders.",al={"bibbly rivale","wer ist bibbly"}}},fp="12,214,20.281.0,21.265.0,27.217.0,32.116.0,30.155.0,44.131.0,14.119.0"}
P.entries["quest:557"] = {n="Armschienen der Bindung",s="In Tarrens Mühle achtet Bewahrer Bel'varil darauf, was der Magus als Nächstes brauchen könnte. Während der Magus die von Euch gesammelten Stone Tokens studiert, schickt Bel'varil Euch zu den Ruinen von Dalaran, um vier Armschienen der Erdbindung zu beschaffen.",h="In Tarrens Mühle achtet Bewahrer Bel'varil darauf, was der Magus als Nächstes brauchen könnte.",kw={"alterac","bel'varil","bindung","armschienen","dalaran","erdbindung","elementare","magus","tarrens mühle"},sec={{t="Armschienen der Erdbindung",b="Der Magus studiert die von Euch gesammelten Stone Tokens, und Bewahrer Bel'varil rechnet mit einem weiteren Bedarf. Armschienen der Bindung werden an den Handgelenken eines Elementars getragen und binden das Wesen an den Dienst eines Magiers. Die Elementare tragen sie in den Ruinen von Dalaran. Bel'varil bittet Euch, vier Armschienen der Erdbindung nach Tarrens Mühle zurückzubringen."}},faq={{q="Wer vergibt diese Quest?",a="Bewahrer Bel'varil gibt sie Euch in Tarrens Mühle, nachdem Ihr die Stone Tokens gesammelt habt.",al={"questgeber","wer vergibt armschienen der bindung","bewahrer bel'varil quest"}},{q="Wozu dienen die Armschienen?",a="Armschienen der Bindung werden an den Handgelenken eines Elementars getragen, um ihn an den Dienst eines Magiers zu binden.",al={"was bewirken armschienen der bindung","zweck der armschienen","warum armschienen beschaffen"}},{q="Wo sind die Elementare zu finden?",a="Ihr findet die Elementare in den Ruinen von Dalaran im Alteracgebirge.",al={"fundort der elementare","wo armschienen finden","wo sind elementarsklaven"}},{q="Warum will Bewahrer Bel'varil sie haben?",a="Bel'varil erwartet, dass der Magus irgendwann Exemplare der Armschienen haben möchte, des Gegenstücks zu den Stone Tokens, die der Magus studiert.",al={"warum will belvaril armschienen","wer will die armschienen"}},{q="Was kam vor dieser Quest?",a="Zuvor habt Ihr in Stone Tokens die Stone Tokens gesammelt. Der Magus studiert sie jetzt.",al={"vorherige quest","voraussetzung","folgequest von stone tokens"}}},fp="18,205,24.329.0,21.84.0,30.84.0,31.74.0,36.132.0,28.91.0"}
P.entries["quest:5581"] = {n="Portale der Legion",s="Bei Mannorocs Koven drohen sechs Dämonenportale, den Zustrom von Dämonen in diese Welt zu verstärken. Von Schattenflucht aus bittet Euch Taiga Klugmähne, sie zu schließen.",h="Bei Mannorocs Koven drohen sechs Dämonenportale, den Zustrom von Dämonen in diese Welt zu verstärken.",kw={"dämonenportale","desolace","hand of iruxos","legion","mannorocs koven","schattenflucht","taiga klugmähne"},sec={{t="Die Tore schließen",b="In Schattenflucht gibt Euch Taiga Klugmähne die Hand of Iruxos. Sie sagt, Ihr müsst sie zu Mannorocs Koven tragen und die Portale dort bannen. Die Dämonenbedrohung wächst, und jedes Portal, das Ihr schließt, begrenzt die Zahl der Dämonen, die in diese Welt übertreten. Sie möchte, dass alle sechs gebannt werden. Hütet Euch vor ihren Wächtern."}},faq={{q="Wo sind die Dämonenportale?",a="Die Dämonenportale befinden sich bei Mannorocs Koven in Desolace.",al={"standort der portale","wo ist mannorocs koven","wo sind die portale der legion"}},{q="Was wird benötigt, um die Portale zu bannen?",a="Ihr braucht die Hand of Iruxos, um die Portale zu bannen. Taiga Klugmähne sagt, Ihr müsst sie bei Euch haben.",al={"wie portale bannen","welcher gegenstand schließt portale","hand of iruxos verwenden"}},{q="Wer bittet Euch, die Portale zu bannen?",a="Von Schattenflucht aus bittet Euch Taiga Klugmähne, die Portale zu bannen.",al={"questgeber","wer vergibt portale der legion","standort von taiga klugmähne"}},{q="Wie viele Portale müssen gebannt werden?",a="Ihr müsst sechs Portale bei Mannorocs Koven bannen.",al={"wie viele portale","anzahl der portale"}},{q="Was geschah zuvor?",a="Zuvor schickte Euch Taiga Klugmähne in „Hand of Iruxos“ zur Festung Donneraxt, um den Dämonenkasten zu holen.",al={"vorherige quest","vorquest","voraussetzung"}}},fp="21,153,17.300.0,28.52.0,37.91.0,35.70.0,34.46.0,22.97.0"}
P.entries["quest:559"] = {n="Farrens Beweis",s="An Süderstades Küste schickt Farren Orinelle Rekruten der Allianz aus, um die Arbeit seiner Patrouille zu belegen. Marshal Redpath will Beweise dafür, dass die Murlocs vom Weststrand verschwunden sind.",h="An Süderstades Küste schickt Farren Orinelle Rekruten der Allianz aus, um die Arbeit seiner Patrouille zu...",kw={"farren","köpfe","hillsbrad","murloc","orinelle","redpath","süderstade","strand"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Süderstades Küste gegen einheimische Raubtiere zu sichern. Dadurch kann sich der Außenposten auf Bedrohungen durch das Syndikat und die Horde konzentrieren.",["profession:Cooking"]="Als Koch in Süderstade könnt Ihr Farrens Abneigung gegen Meeresfrüchte womöglich nicht nachvollziehen. Bei Kämpfen am Strand können auch zusätzliche rohe Fische abfallen."},sec={{t="Eine widerwillige Bitte",b="Nach den ersten Küstenstreifzügen in Down the Coast muss sich Leutnant Farren Orinelle den Fragen von Marshal Redpath und Süderstades Stadtführung stellen. Farren sagt, die örtlichen Murlocs seien verschwunden, doch seine Vorgesetzten wollen Beweise. Also schickt er umherziehende Abenteurer der Allianz zurück an die Küste, um Beweise für die Tötungen zu beschaffen, und überlässt ihnen die grausige Arbeit."},{t="Grausige Beweise",b="Westlich von Süderstade leben Küstenmurlocs im seichten Wasser am Weststrand. Farren bittet Euch um zehn abgetrennte Murlocköpfe, um die Offiziere der Garnison zufriedenzustellen. Er verabscheut die Kreaturen, deren abstoßender Anblick und Geruch ihm den Appetit auf Süderstades wichtigstes Exportgut und Grundnahrungsmittel verdorben haben."}},faq={{q="Wer ist Leutnant Farren Orinelle?",a="Leutnant Farren Orinelle ist ein Offizier der Allianz, der in Süderstade stationiert ist. Er will seinen Vorgesetzten Erfolge melden und überlässt deshalb die blutige, schmutzige Arbeit zur Sicherung der Küste den Abenteurern.",al={"farren orinelle","wer vergibt farrens beweis","leutnant farren"}},{q="Warum braucht Farren abgetrennte Murlocköpfe?",a="Farren braucht abgetrennte Murlocköpfe, weil Marshal Redpath und Süderstades Amtsträger greifbare Beweise verlangen, bevor sie Berichte akzeptieren, dass der Weststrand gesäubert wurde.",al={"warum murlocköpfe","grund für farrens beweis","warum köpfe sammeln"}},{q="Wo befinden sich diese Murlocs?",a="Die Murlocs leben am Weststrand, westlich von Süderstade, in Richtung der Grenze zum Silberwald.",al={"fundort kopf eines murlocs","wo ist der weststrand","murlocfundorte hillsbrad"}},{q="Was geschieht nach der Abgabe von Farrens Beweis?",a="Nachdem Farren die Beweise angenommen hat, bittet er Euch, Marshal Redpath den Tod der Murlocs zu melden. Redpath wendet sich dann den Bedrohungen am Oststrand zu und übermittelt später Sturmwinds Versetzungsbefehl für Farren.",al={"nächste quest nach farrens beweis","farrens questreihe","folgequest zu farrens beweis"}},{q="Warum ekelt sich Farren vor den Murlocs?",a="Farren findet gehende, zweibeinige Fische abstoßend. Der Umgang mit ihren kalten, schleimigen Überresten hat ihm den Appetit auf Fisch verdorben und das Leben in Süderstades Fischergemeinde verleidet.",al={"farren fisch","warum mag farren keinen fisch"}},{q="Wer ist Marshal Redpath?",a="Marshal Redpath befehligt Süderstades Stadtverteidigung. Er zieht rangniedere Offiziere wie Farren Orinelle für die Sicherheit der Region zur Verantwortung.",al={"hauptmann redpath","wer ist redpath"}}},fx={fff9ab4a={q="Warum lässt Leutnant Farren Euch die Köpfe sammeln, anstatt es selbst zu tun?",a="Leutnant Farren empfindet tiefe Abscheu vor Murlocs. Während er sich schnell die Lorbeeren für die Säuberung der Küste aufsetzt, dreht ihm allein der Gedanke, kalte, schleimige Köpfe abzuhacken, so sehr den Magen um, dass er seit Wochen keinen Fisch mehr anrühren konnte. Er heuert lieber einen Abenteurer an, der diese grausige Schlächterei ertragen muss, als sich die eigenen Hände schmutzig zu machen.",al={"warum braucht farren mich","warum holt farren die köpfe nicht selbst","farrens beweis warum ich"}}},fp="14,179,18.335.0,15.298.0,34.195.0,42.173.0,32.102.0,45.211.1,39.169.0,23.135.0"}
P.entries["quest:56"] = {n="Die Nachtwache",s="In Dunkelhain hält die Nachtwache den Toten stand, die sich in der Nähe erheben. Sturmwind hat seine Garnison abgezogen, sodass die örtliche Miliz am Friedhof \"Stille Gärten\" auf Reisende angewiesen ist.",h="In Dunkelhain hält die Nachtwache den Toten stand, die sich in der Nähe erheben.",kw={"althea schwarzhaupt","dunkelhain","dämmerwald","nachtwache","skelettmagier","skelettkrieger","sturmwind","stille gärten"},ang={["class:Paladin"]="Als Paladin steht Ihr in den Stillen Gärten einem Frevel am Licht gegenüber. Entweihte Gräber verlangen nach geweihtem Stahl und gerechtem Urteil.",["class:Priest"]="Als Priester könnt Ihr gequälten, rastlosen Skeletten in einem von finsteren Flüchen heimgesuchten Land als Akt geistlicher Barmherzigkeit die letzte Ruhe schenken.",["faction:Alliance"]="Für treue Anhänger der Allianz zeigt diese Pflicht Sturmwinds Vernachlässigung. Die Bewohner des Grenzlands müssen ohne königliche Hilfe um ihr eigenes Überleben kämpfen."},sec={{t="Von der Krone verlassen",b="Sturmwind schützte einst den Dämmerwald, doch die Mittel der Krone schwanden, als politische Zwietracht die Hauptstadt ergriff. Dann zog die Krone ihre regulären Soldaten ab und ließ Dunkelhain mit kaum Schutz gegen die vordringenden Schatten des Waldes zurück. Die Bewohner gründeten eine örtliche Miliz namens Nachtwache unter der Führung von Kommandantin Althea Schwarzhaupt. Sie steht zwischen dem verfluchten Wald und den verbliebenen Bewohnern der Stadt."},{t="Die Stillen Gärten säubern",b="Südlich von Dunkelhain war der Friedhof \"Stille Gärten\" einst eine friedliche Ruhestätte. Nun streifen rastlose Skelette und wiedererweckte Zauberwirker zwischen seinen Gräbern umher. Die Nachtwache ist entlang der Grenzen des Dämmerwalds dünn aufgestellt, weshalb Kommandantin Schwarzhaupt eintreffende Reisende aussendet, Skelettkrieger und Skelettmagier niederzustrecken, bevor die Toten die Straßen erreichen."}},faq={{q="Warum braucht die Nachtwache Hilfe von außen?",a="Sturmwind hat seine reguläre Garnison aus dem Dämmerwald zurückgerufen und Dunkelhain seiner eigenen Verteidigung überlassen. Die Nachtwache ist eine örtliche Miliz mit zu wenigen Leuten und Vorräten, um die Untoten im gesamten Gebiet allein zu bekämpfen.",al={"warum hilfe nötig","warum dunkelhain schwach","warum keine wachen"}},{q="Wer ist Kommandantin Althea Schwarzhaupt?",a="Althea Schwarzhaupt ist eine Verwandte von Dunkelhains Bürgermeister, Lord Ello Schwarzhaupt, und befehligt die Nachtwache. Sie organisiert die Verteidigung der Stadt und versammelt jene, die sich den finsteren Bedrohungen des Dämmerwalds entgegenstellen können.",al={"wer ist althea","kommandantin schwarzhaupt","althea schwarzhaupt hintergrund"}},{q="Wo liegt der Friedhof \"Stille Gärten\"?",a="Der Friedhof \"Stille Gärten\" liegt unmittelbar südlich von Dunkelhain. Dort werden weiterhin Tote bestattet, doch dunkle Magie im Dämmerwald hat die Toten erweckt, die nun Reisende am Stadtrand bedrängen.",al={"stille gärten lage","wo ist der friedhof","wo skelette finden"}},{q="Welche Kreaturen erheben sich in den Stillen Gärten?",a="Skelettkrieger und Skelettmagier überrennen den Friedhof. Diese belebten Überreste bewahren ihre Kampffertigkeit und arkane Macht, was sie zu einer tödlichen Bedrohung für gewöhnliche Stadtbewohner macht.",al={"welche untoten gibt es","skelette im dämmerwald"}},{q="Schickt Sturmwind Verstärkung?",a="Nein. Sturmwind hat seine regulären Wachen abgezogen und den abgelegenen Dämmerwald seiner eigenen Verteidigung überlassen.",al={"sturmwind hilfe für dämmerwald","wird sturmwind truppen schicken"}},{q="Beendet dieser Auftrag die Bedrohung auf dem Friedhof?",a="Nein. Die Skelette aus den Stillen Gärten zu vertreiben, ist nur der erste Schritt. Die Nachtwache steht tiefer in den Wäldern wachsenden Bedrohungen gegenüber, und weitere Expeditionen sind nötig, um die zunehmende Verderbnis des Dämmerwalds einzudämmen.",al={"ist dies die einzige quest","nachtwache questreihe"}}},fx={bf57f222={q="Warum möchte Kommandantin Althea Schwarzhaupt, dass dies erledigt wird?",a="Kommandantin Althea Schwarzhaupt hat geschworen, die Bewohner von Dunkelhain zu beschützen, doch da Sturmwind seine königliche Garnison abzieht, lastet die Bürde vollständig auf ihrer eigenen Nachtwache. Der Friedhof \"Stille Gärten\" liegt gefährlich nahe, direkt südlich der Stadt. Wenn die wandelnden Toten, die aus ihren Gräbern steigen, nicht niedergestreckt werden, bevor ihre Reihen anschwellen, läuft Dunkelhain Gefahr, vollständig von den Schrecken des Waldes überrannt zu werden.",al={"warum will althea dass dies getan wird","althea schwarzhaupt beweggrund","warum die skelette in dunkelhain bekämpfen"}}},fp="15,200,22.412.0,29.343.0,43.211.0,34.208.0,39.186.0,50.171.0,40.89.0,52.209.0"}
P.entries["quest:560"] = {n="Farrens Beweis",s="In Süderstade schickt Euch Leutnant Farren Orinelle mit seinem Bericht zu Marshal Redpath. Die Murlocköpfe sind der Beweis Eurer Arbeit, doch Farren will sie nicht selbst tragen.",h="In Süderstade schickt Euch Leutnant Farren Orinelle mit seinem Bericht zu Marshal Redpath.",kw={"allianz","laufbursche","farren orinelle","farrens beweis","vorgebirge des hügellands","marshal redpath","murlocköpfe","süderstade"},ang={["faction:Alliance"]="Jede kleine Aufgabe in Süderstade hilft, den wichtigsten Stützpunkt der Allianz in Lordaeron gegen Bedrohungen aus dem Norden und vom Meer zu befestigen.",["race:Human"]="Als menschlicher Reisender erlebt Ihr im Umgang mit Farren und Redpath die überlastete Bürokratie und die zermürbende Grenzwacht von Hillsbrads Garnison."},sec={{t="Ein zartbesaiteter Offizier",b="Leutnant Farren Orinelle patrouilliert an der südlichen Küste des Vorgebirges des Hügellands und sichert sie. Doch die harte Arbeit im Grenzkrieg dreht ihm den Magen um. Nachdem Ihr die Murlocs an den Stränden dezimiert habt, bringt er es nicht über sich, die abgetrennten Köpfe anzufassen, die Ihr als Beweis zurückbringt. Also schickt er Euch quer durch Süderstade, um sie der Stadtkommandantur zu übergeben."},{t="Bericht an Redpath",b="Marshal Redpath wacht über Süderstades Verteidigung und militärische Einsatzbereitschaft, während die Bedrohungen durch Tarrens Mühle und wilde Bestien zunehmen. Er erhält den Sack mit Murlocköpfen von Euch statt direkt von Farren. Redpath weiß, dass Ihr zu Farrens Laufburschen geworden seid, nimmt Eure Hilfe aber an. Süderstade braucht jede helfende Hand, um seine Grenzen zu sichern."}},faq={{q="Warum überbringt Leutnant Farren die Murlocköpfe nicht selbst?",a="Leutnant Farren möchte keinen Sack mit abgetrennten Murlocköpfen anfassen. Nachdem er Euch in den Kampf geschickt hat, überlässt er Euch auch die Übergabe.",al={"warum geht farren nicht selbst","farrens beweis warum überbringen","warum laufbursche"}},{q="Wer ist Marshal Redpath?",a="Marshal Redpath ist der ranghöchste militärische Befehlshaber der Allianz in Süderstade. Er leitet die örtliche Verteidigung, koordiniert die Stadtwachen und kümmert sich um Bedrohungen für die Menschensiedlung im Vorgebirge des Hügellands.",al={"wer ist redpath","marshal redpath hintergrund","süderstade marshal"}},{q="Wohin führt diese Lieferung als Nächstes in der Questreihe?",a="Auf die Lieferung folgen weitere Aufgaben von Marshal Redpath und Leutnant Farren. Danach folgen offizielle Depeschen über Truppenverlegungen und Schriftstücke, die nach Sturmwind geschickt werden.",al={"what comes next","farrens beweis nächste quest","redpath nächste quest"}},{q="Warum haben Murlocs für Süderstades Garnison Vorrang?",a="Murlocstämme versammeln sich in großer Zahl an Hillsbrads Stränden. Sie bedrohen die Versorgungswege an der Küste, bedrängen die örtlichen Fischer und gefährden den südlichen Zugang zu Süderstade, während die Stadt den Verlassenen im Norden gegenübersteht.",al={"warum murlocs töten","murlocproblem süderstade","hillsbrad murlocs"}},{q="Was hält Marshal Redpath von Leutnant Farrens Verhalten?",a="Marshal Redpath kennt Farrens Gewohnheiten und bemerkt trocken, dass Ihr zu Farrens Laufburschen geworden seid. Er begrüßt Eure Hilfe, denn Süderstade steht unter großem Druck und braucht fähige Helfer.",al={"redpaths meinung über farren","mag redpath farren"}},{q="Wo befindet sich Marshal Redpath in Süderstade?",a="Marshal Redpath befindet sich nahe Süderstades Ortsmitte und Ratsgebäude, wo er die tägliche Verteidigung der Siedlung leitet.",al={"redpath finden","wo ist marshal redpath","redpath aufenthaltsort"}}},fx={["8013187e"]={q="Warum möchte Leutnant Farren, dass die Murlocköpfe an Marshal Redpath geliefert werden?",a="Leutnant Farren benötigt konkrete Beweise dafür, dass die Murlocbedrohung entlang der Küste von Süderstade aktiv bekämpft wird. Die Präsentation der abgetrennten Köpfe vor Marshal Redpath beweist, dass Farrens Patrouillenbefehle ausgeführt werden und die Küsten von Süderstade verteidigt werden, auch wenn der Leutnant es lieber vermeiden würde, selbst einen übelriechenden Sack durch die Stadt zu schleppen.",al={"farrens beweggrund","warum murlocköpfe abliefern","farrens beweis zweck"}}},fp="14,172,19.342.0,17.339.0,63.138.0,23.191.0,54.164.0,53.208.0,63.182.0,47.121.0"}
P.entries["quest:561"] = {n="Farrens Beweis",s="In Süderstade befiehlt Marshal Redpath Leutnant Farren Orinelle, sich den Naga am Oststrand zuzuwenden. Er will, dass Orinelle sie zurückdrängt und persönlich Bericht erstattet.",h="In Süderstade befiehlt Marshal Redpath Leutnant Farren Orinelle, sich den Naga am Oststrand zuzuwenden.",kw={"oststrand","farren orinelle","farrens beweis","hillsbrad","marshal redpath","naga","beförderung","süderstade"},ang={["class:Warrior"]="Als Krieger der Allianz kennt Ihr vielleicht den Zwiespalt, Euch im Kampf zu beweisen und Euch zugleich mit den Ambitionen der Offiziere auseinanderzusetzen.",["faction:Alliance"]="Der Austausch offenbart Rivalitäten um Rang und Anerkennung innerhalb der Garnison von Süderstade, während der nördliche Außenposten Bedrohungen ausgesetzt ist."},sec={{t="Neue Befehle",b="Marshal Redpath schickt Leutnant Farren Orinelle eine Nachricht quer durch Süderstade. Berichte künden von Einfällen der Naga am Oststrand, und Redpath will, dass Orinelle sich auf diese Bedrohung konzentriert. Der Leutnant muss andere Belange zurückstellen, die Naga zurückdrängen und dem Marshal persönlich über seine Fortschritte berichten."},{t="Rivalität an der Küste",b="Leutnant Farren Orinelle vermutet, dass Marshal Redpath die Anerkennung für die Befriedung des Oststrands einstreichen will. Er glaubt, Redpath nutze Aufklärungsberichte, die sie beide erhalten haben, um die Arbeit der Garnison als seine eigene auszugeben. Orinelle will nicht zulassen, dass sein Kommandant durch die Arbeit seiner Soldaten befördert wird, und ersinnt einen anderen Weg, die Gunst der Krone zu gewinnen."}},faq={{q="Welchen Zweck hat diese Zustellung?",a="Marshal Redpaths Befehle weisen Leutnant Farren Orinelle an, den Naga an Hillsbrads Oststrand entgegenzutreten und dem Marshal persönlich über seine Fortschritte zu berichten.",al={"was will redpath","warum eine nachricht an farren schicken","farrens beweis drei ziel"}},{q="Warum reagiert Farren Orinelle verbittert auf Redpaths Befehle?",a="Orinelle glaubt, dass Redpath aufgrund derselben militärischen Aufklärungsberichte handelt, die sie beide erhalten haben. Er fürchtet, der Marshal wolle die Anerkennung für die Sicherung der Küste einstreichen und durch Orinelles harte Arbeit befördert werden.",al={"farren redpath rivalität","warum ist orinelle wütend","orinelle beförderung"}},{q="Wo liegt der Oststrand?",a="Der Oststrand erstreckt sich entlang der Südküste des Vorgebirges des Hügellands, südöstlich von Süderstade. Naga haben auf seinem Sand Lager errichtet.",al={"oststrand lage","wo sind die naga","hillsbrads küste"}},{q="Was folgt nach der Zustellung dieser Nachricht?",a="Nach der Zustellung ersinnt Orinelle einen eigenen Plan, statt sich einfach Redpaths Befehlsgewalt zu fügen. Sein Plan schickt Kuriere in 'Sturmwind Ho!' die Küste hinab zum Oberkommando.",al={"nächste quest","was geschieht als nächstes","stormwind ho folgequest"}},{q="Welche Befehlshaber sind an diesem Austausch beteiligt?",a="Marshal Redpath befehligt die Garnison von Süderstade, und Leutnant Farren Orinelle dient unter ihm als Feldleutnant, der die Küstenverteidigung überwacht.",al={"wer sind farren und redpath","süderstades offiziere","farren orinelle und redpath"}},{q="Erfordert dieser Auftrag Kämpfe?",a="Nein. Bei der Zustellung geht es um einen Austausch zwischen Offizieren in Süderstade, auch wenn er das militärische Vorgehen gegen Naga entlang der Küste betrifft.",al={"gibt es kämpfe","gegen naga kämpfen","farrens beweis kampf"}}},fx={["4fc43d37"]={q="Warum schickt Marshal Redpath Euch zu Leutnant Farren?",a="Marshal Redpath überwacht die Verteidigung von Süderstade und möchte, dass Leutnant Farren Orinelle aufhört, Zeit mit Murlocs zu verschwenden, und seine Aufmerksamkeit stattdessen auf die Naga richtet, die den Oststrand bedrohen. Er braucht von Farren echte taktische Ergebnisse und dass dieser sich direkt vor ihm verantwortet, anstatt belanglose persönliche Initiativen zu verfolgen.",al={"warum sendet redpath diese nachricht","redpaths beweggrund bezüglich farren","warum fokus auf naga"}}},fp="14,176,18.298.0,20.328.1,37.155.0,60.206.0,36.141.0,46.179.1,46.145.0,40.129.0"}
P.entries["quest:562"] = {n="Sturmwind Ho!",s="Das Oberkommando der Allianz fürchtet die Naga, und Sturmwind Ho! eröffnet Farren Orinelle einen Weg nach Süden. Er hofft, sich ihren Sieg zuzuschreiben und eine Rückkehr nach Sturmwind zu erwirken.",h="Das Oberkommando der Allianz fürchtet die Naga, und Sturmwind Ho!",kw={"daggerspine","farren orinelle","vorgebirge des hügellands","naga","reassignment","samuelson","süderstade","sturmwind ho"},ang={["faction:Alliance"]="Das Kommando der Allianz in Hillsbrad ist überlastet. Gewöhnliche Stadtwachen sind mit monströsen Bedrohungen wie den Naga der Daggerspine überfordert.",["race:Human"]="Als Mensch im Dienst in Lordaeron seht Ihr Süderstade als düstere Erinnerung an den verlorenen Ruhm des Nordens, fern von Sturmwinds wiederaufgebauter Pracht und Sicherheit."},sec={{t="Ein Weg aus Süderstade",b="Leutnant Farren Orinelle findet seinen Posten in Süderstade erbärmlich. Die Stadt liegt am Rande Lordaerons, eingekreist von Streitkräften der Verlassenen, Syndikatsbanditen und Meeresbestien. Farren diente einst als Stadtwache in Sturmwind, wo Betrunkene und kleinere Schlägereien seinen Alltag bestimmten. Nun sehnt er sich danach, nach Süden zurückzukehren.\n\nSein früherer Mentor berichtet ihm, dass sich das Oberkommando der Allianz zunehmend wegen der an den Küsten vordringenden Naga sorgt. Farren sieht eine Gelegenheit, den Norden hinter sich zu lassen."},{t="Gestohlener Ruhm an der Küste",b="Farren gibt zu, dass ihm Mut und Können fehlen, um Sirenen und Küstenjägern der Daggerspine im offenen Kampf gegenüberzutreten. Also schickt er Euch los, die Strände südöstlich von Süderstade abzusuchen und die Reihen der Naga auszudünnen.\n\nEr braucht Eure Taten für eine eindrucksvolle Meldung an Major Samuelson in Sturmwind. Mit diesen Verdiensten hofft Farren, sich eine Versetzung zu sichern."}},faq={{q="Warum will Farren Orinelle die Naga töten?",a="Farren will Süderstade entkommen, die Naga sind ihm dabei gleichgültig. Sein Mentor sagt, das Oberkommando der Allianz fürchte ihre wachsende Bedrohung, weshalb ein Erfolg gegen sie Farren eine Beförderung oder Versetzung nach Sturmwind einbringen könnte.",al={"warum naga","farrens beweggrund","warum naga in süderstade töten"}},{q="Kann Leutnant Farren Orinelle selbst gegen die Naga kämpfen?",a="Nein. Farren diente als Stadtwache, schlichtete betrunkene Wirtshausschlägereien und verhaftete randalierende Bettler. Die wilden Naga der Daggerspine machen ihm Angst, deshalb verlässt er sich darauf, dass Reisende gegen sie kämpfen.",al={"warum kämpft farren nicht","ist farren schwach","farren kampf"}},{q="Wo sind die Naga der Daggerspine zu finden?",a="Küstenjäger und Sirenen der Daggerspine unterhalten Lager entlang der Küste südöstlich von Süderstade. Sie durchstreifen die Ufer des großen Meeres im Vorgebirge des Hügellands.",al={"wo sind naga","daggerspine standort","süderstade naga strand"}},{q="Wer ist Major Samuelson?",a="Major Samuelson war Farren Orinelles Mentor bei der Sturmwind City Guard. Während Farren einen Bericht über die Naga vorbereitet, hofft er, dass Samuelson seinen Einfluss nutzt, um ihm eine Versetzung nach Süden zu sichern.",al={"major samuelson","samuelson sturmwind","wer bekommt den brief"}},{q="Was geschieht nach Abschluss dieser Aufgabe?",a="Nachdem die Bedrohung durch die Naga eingedämmt ist, beansprucht Farren den Ruhm für Eure Arbeit und schickt Euch nach Süden zur Burg Sturmwind. Dort übergebt Ihr Major Samuelson persönlich seinen Bericht und seine Bitte um Versetzung.",al={"what comes next","nächste quest nach sturmwind ho","versetzungsquest"}},{q="Warum hasst Farren Süderstade so sehr?",a="Farren sieht Süderstade als gefährlichen Grenzposten, fern der Sicherheit Sturmwinds. Mit untoten Nachbarn und Küstenmonstern ringsum nennt er es verbittert einen „vom Licht verlassenen Hafen“.",al={"warum hasst farren süderstade","vom licht verlassener hafen"}}},fx={d5622c58={q="Wer sind die Daggerspine-Naga, die Süderstade bedrohen?",a="Die Daggerspine sind schlangenartige monströse Humanoide, die entlang der östlichen Küste des Vorgebirges des Hügellands vordringen. Das Oberkommando der Allianz ist zunehmend alarmiert über ihre organisierte Präsenz an den Küsten. Wilde Küstenjäger patrouillieren zusammen mit Sirenen, die Ozeanmagie beherrschen, an den Stränden, belästigen die regionalen Fischereibetriebe und drohen, die zerbrechliche Verteidigung von Süderstade zu überwältigen, falls man sie gewähren lässt.",al={"daggerspine-naga","wer sind die naga in süderstade","daggerspine-küstenjäger"}}},fp="13,164,26.449.0,25.328.0,47.223.0,54.186.0,39.149.0,23.189.0,40.193.1,40.191.0"}
P.entries["quest:5621"] = {n="Gewänder des Mondes",s="In Dolanaar schickt Laurna Morgenglanz einen jungen Priester zu einer verwundeten Wächterin südlich des Ortes. Diese Pflicht prüft die Hingabe eines Eingeweihten und bringt ihm die formelle Anerkennung in der Sisterhood of Elune ein.",h="In Dolanaar schickt Laurna Morgenglanz einen jungen Priester zu einer verwundeten Wächterin südlich des Ortes.",kw={"dolanaar","gewänder des mondes","in favor of elune","laurna morgenglanz","wächterin shaya","sisterhood of elune","teldrassil"},ang={["class:Priest"]="Als Priester heilt Ihr verwundete Verbündete durch Gebete und schützt sie mit göttlichen Schutzzaubern vor Gefahren.",["race:NightElf"]="Als Kaldorei gehört Ihr einem Volk an, dessen Sisterhood of Elune und Wächterinnen seit Jahrtausenden gemeinsam die Wälder und ihr Volk vor der vordringenden Dunkelheit schützen."},sec={{t="Eine heilige Berufung",b="Die Sisterhood of Elune leitet die Kaldorei in ihrem Glauben und hilft, Teldrassils Grenzen zu schützen. Wächterin Shaya wurde auf einer Patrouille in der Wildnis südlich von Dolanaar verwundet, und Priesterausbilderin Laurna Morgenglanz kann ihren Posten nicht verlassen, um zu helfen. Deshalb bittet sie einen frisch ausgebildeten Eingeweihten, Shayas Wunden zu versorgen und sie mit schützender Magie zu stärken."},{t="Gewänder der Sisterhood",b="Nachdem Ihr die Lebenskraft von Wächterin Shaya wiederhergestellt habt, kehrt Ihr nach Dolanaar zurück und erhaltet von Laurna Morgenglanz Eure formellen Amtsgewänder. Die Gewänder kennzeichnen den Übergang eines Akolythen vom Unterricht zum praktischen Dienst, der Leben retten kann. Für die Kaldorei bedeutet die Hilfe für die Wächterinnen, Elune zu dienen und zur Sicherheit Teldrassils beizutragen."}},faq={{q="Wer bietet die Quest Gewänder des Mondes an?",a="Laurna Morgenglanz, die Priesterausbilderin im nördlichen Gebäude von Dolanaar, überträgt Euch diese Pflicht.",al={"wer vergibt gewänder des mondes","wo beginnt gewänder des mondes","gewänder des mondes questgeber"}},{q="Wer braucht bei dieser Aufgabe Hilfe?",a="Wächterin Shaya braucht Hilfe. Sie wurde auf einer Patrouille in der Wildnis verwundet und wartet unmittelbar südlich von Dolanaar.",al={"wen heilen","verwundete wächterin fundort","wo ist wächterin shaya"}},{q="Welche Magie ist nötig, um Wächterin Shaya zu helfen?",a="Ihr versorgt die Wunden von Wächterin Shaya mit Heilmagie und stärkt sie mit Schutzzaubern, bevor Ihr nach Dolanaar zurückkehrt.",al={"welche zauber auf shaya wirken","wie gewänder des mondes abschließen","shaya questziel"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Nur Nachtelfenpriester dürfen diesen frühen Schritt ihrer geistlichen Ausbildung gehen.",al={"gewänder des mondes nur für priester","gewänder des mondes klassenanforderung","können druiden gewänder des mondes machen"}},{q="Was symbolisiert die Robe als Belohnung?",a="Die Robe von Laurna Morgenglanz steht für Euren Dienst an Elune und Euren anerkannten Platz in der örtlichen Priesterschaft.",al={"gewänder des mondes bedeutung der robe","hintergrund der belohnungsrobe","bedeutung von gewänder des mondes"}},{q="Wie hängen diese Quest und In Favor of Elune zusammen?",a="In Favor of Elune ist eine einführende Aufforderung, die Ausbilderin in Dolanaar aufzusuchen. Sie ist für diese Pflicht nicht erforderlich, doch Ihr könnt sie nach Abschluss von Gewänder des Mondes nicht mehr abschließen.",al={"in favor of elune voraussetzung","in favor of elune verpasst","reihenfolge der priesterquests in dolanaar"}}},fx={e07db161={q="Warum möchte Laurna Morgenglanz, dass die Schildwache Shaya geheilt wird?",a="Schildwache Shaya wurde verwundet, als sie die Grenzen südlich von Dolanaar patrouillierte, um die Siedlung zu sichern. Als Priesterausbilderin, die sich Elune verschrieben hat, betrachtet Laurna Morgenglanz es als ihre heilige Pflicht, sich um die Beschützer von Teldrassil zu kümmern. Die Wunden von Shaya zu versorgen und ihren Geist zu stärken stellt sicher, dass die Schildwachen den wachsenden Gefahren standhalten können, die die Zweige des Weltenbaums bedrohen.",al={"laurna morgenglanz beweggrund","warum schildwache shaya heilen","garmente der mondin beweggrund"}},["6b18db0b"]={q="Warum schickt Laurna Euch, anstatt Shaya selbst zu helfen?",a="Laurna Morgenglanz kann ihren Posten in Dolanaar nicht verlassen, wo sie mit der Unterweisung und Führung der unerfahrenen Akolythen der Priesterschaft betraut ist. Da sie durch ihre Pflichten an das Heiligtum des Dorfes gebunden ist, vertraut sie darauf, dass Ihr Euch ins Feld begebt, Eure Ausbildung in die Praxis umsetzt und Eure Pflicht gegenüber Elune erfüllt, indem Ihr der verwundeten Schildwache helft.",al={"warum schickt man mich","warum heilt laurna shaya nicht selbst","warum kann laurna nicht gehen"}}},fp="20,189,16.333.0,27.298.0,42.90.0,32.101.0,46.122.0,30.80.0,36.115.0,66.177.0"}
P.entries["quest:5622"] = {n="Elune geneigt",s="In Laubschattental brechen junge Nachtelfenpriester auf, um in Dolanaar Anleitung und Ausbildung zu erhalten. Priesterin Shanda schickt sie den Waldpfad entlang zu Laurna Morgenglanz.",h="In Laubschattental brechen junge Nachtelfenpriester auf, um in Dolanaar Anleitung und Ausbildung zu erhalten.",kw={"dolanaar","garments of the moon","elune geneigt","laurna morgenglanz","priester","laubschattental","shanda","teldrassil"},ang={["class:Priest"]="Als Priester lasst Ihr die einfachen Studien des Noviziats hinter Euch, um umfassender zu dienen, und beginnt den Weg zu Euren ersten geweihten Priestergewändern.",["race:NightElf"]="Als Nachtelf durchlauft Ihr einen traditionellen Meilenstein für Gläubige. Die Sisterhood of Elune ist das spirituelle Herz und die historische Führung der Gesellschaft der Kaldorei."},sec={{t="Abschied von der Lichtung",b="Priesterin Shanda bildet Novizen aus, die Elune im abgeschiedenen Schutz von Aldrassil dienen. Unter ihrer Aufsicht beginnen sie mit einfachen Gebeten und Schutzzaubern. Doch das ruhige Leben in Laubschattental kann sie nicht auf die Unruhen jenseits der Lichtung vorbereiten. Sobald ein Novize beständigen Glauben und Disziplin beweist, schickt Shanda ihn den Waldpfad hinunter nach Dolanaar, um seine Ausbildung fortzusetzen."},{t="Ein Schritt ins Priesteramt",b="In Dolanaar macht ein junger Nachtelf einen wichtigen Schritt im Dienst an Elune. Priesterin Laurna Morgenglanz bereitet ihre Schüler auf die Prüfungen vor, denen Teldrassil gegenübersteht. Dort kann ein Akolyth fortgeschrittene, vom Mond erfüllte Zauberkunst erlernen und förmliche Gewänder erhalten. Diese Roben kennzeichnen seinen Platz in der Sisterhood of Elune."}},faq={{q="Wer schickt mich auf diese Reise?",a="Priesterin Shanda schickt Euch von Aldrassil in Laubschattental los, sobald Eure erste Ausbildung abgeschlossen ist.",al={"questgeber","wer startet elune geneigt","wo gibt es diese quest"}},{q="Wohin muss ich gehen, um Laurna Morgenglanz zu finden?",a="Laurna Morgenglanz befindet sich im nördlichen Gebäude von Dolanaar. Dolanaar ist die erste größere Siedlung südlich der Tore von Laubschattental in Teldrassil.",al={"laurna morgenglanz standort","wo ist dolanaar","wo ist morgenglanz"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Sie ist für junge Nachtelfenpriester bestimmt, die ihre ersten Schritte in der Sisterhood und im Dienst an Elune machen.",al={"nur für priester","wer kann elune geneigt machen","druidenquest?"}},{q="Was geschieht, nachdem ich mit Laurna Morgenglanz gesprochen habe?",a="Laurna Morgenglanz begrüßt Euch und bietet Euch die Prüfung Garments of the Moon an. Sie prüft Eure Fähigkeit, verwundete Verteidiger zu schützen und zu heilen, bevor sie Euch Eure ersten offiziellen Priesterroben gibt.",al={"what comes next","folgequest","garments of the moon quest"}},{q="Ist diese Quest erforderlich, um die Priesterausbildung fortzusetzen?",a="Diese Einführung ist optional. Wenn Ihr direkt nach Dolanaar reist, bietet Laurna Morgenglanz Euch dennoch Ausbildung und die darauffolgenden Schritte an.",al={"ist elune geneigt pflicht","elune geneigt überspringen","optionale hinführungsquest"}},{q="Warum ist es für die Sisterhood so wichtig, sich Gewänder zu verdienen?",a="Gewänder sind heilige Symbole in der Kultur der Nachtelfen. Sie kennzeichnen den Rang, die Hingabe und die Bereitschaft eines Priesters, den Segen der Moon Goddess im Dienst an seinem Volk zu kanalisieren.",al={"warum roben wichtig sind","bedeutung der gewänder","rang einer elunepriesterin"}}},fx={["012a62ea"]={q="Warum schickt Shanda Euch nach Dolanaar?",a="Shanda hat Euch die grundlegenden Riten gelehrt, die für einen Novizen im Laubschattental angemessen sind, aber Eure Ausbildung im Dienste Elunes muss über dieses abgelegene Tal hinausgehen. Sie verweist Euch an Laurna Morgenglanz in Dolanaar, damit Ihr Euer spirituelles Verständnis vertiefen und die zeremoniellen Gewänder erlangen könnt, die Eurem wachsenden Rang innerhalb der Priesterschaft entsprechen.",al={"warum nach dolanaar schicken","shandas beweggrund","warum laurna morgenglanz aufsuchen"}}},fp="17,159,17.358.0,26.314.0,29.93.0,50.139.0,30.107.0,50.190.0,52.135.0,55.172.0"}
P.entries["quest:5623"] = {n="Dem Licht geneigt",s="In der Abtei von Nordhain schickt Euch Priesterin Anetta nach Süden, um Eure Ausbildung in Goldhain fortzusetzen. Priesterin Josetta erwartet Euch im Gasthaus \"Zur Höhle des Löwen\", um Eure nächsten Schritte im Heiligen Licht zu begleiten.",h="In der Abtei von Nordhain schickt Euch Priesterin Anetta nach Süden, um Eure Ausbildung in Goldhain...",kw={"anetta","kirche","wald von elwynn","goldhain","heiliges licht","josetta","nordhain","priesterquest"},ang={["class:Priest"]="Als Priester verlasst Ihr Eure behüteten Studien in Nordhain, um den Menschen und Garnisonen des Waldes von Elwynn zu dienen.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr Euch an die Kirche des Heiligen Lichts wenden, um Heiler zu finden, die sich um die Verteidiger der Allianz kümmern.",["race:Human"]="Als Mensch aus Sturmwind könnt Ihr in Goldhain die Führung der Priesterschaft suchen, während Ihr dazu beitragt, das moralische und geistliche Leben Eures Königreichs zu bewahren."},sec={{t="Über Nordhain hinaus",b="Eure Ausbildung führt Euch über die abgeschiedenen Hallen der Abtei von Nordhain hinaus und mitten ins Leben der Menschen von Elwynn. Ihr verlasst das abgeschiedene Studium für den aktiven geistlichen Dienst, bei dem das Heilige Licht alltäglichen Nöten jenseits der Abteimauern begegnen muss."},{t="Unterweisung in Goldhain",b="Im Gasthaus \"Zur Höhle des Löwen\" kümmert sich Priesterin Josetta um Goldhains geistliche Bedürfnisse und leitet angehende Akolythen an. Sie baut auf Euren Lektionen auf und lehrt Euch, Trost zu spenden, die Gläubigen zu schützen und die Verletzten zu heilen. Unter ihrer Anleitung lernt Ihr die Pflichten der Kirchendiener im ganzen Königreich kennen, darunter die Versorgung einer verwundeten Wache und der Empfang zeremonieller geistlicher Gewänder."}},faq={{q="Wer vergibt diese Quest und bei wem muss ich mich melden?",a="Priesterin Anetta gibt Euch in der Abtei von Nordhain Anweisungen und schickt Euch die Straße hinab zu Priesterin Josetta in Goldhain.",al={"wer vergibt dem licht geneigt","quest abgeben","wo dem licht geneigt abgeben"}},{q="Warum wird ein Priester so früh aus Nordhain fortgeschickt?",a="Nordhain lehrt Euch die Grundlagen des Heiligen Lichts, während Ihr in Goldhain einer echten Gemeinde dienen könnt. Unter Josettas Anleitung könnt Ihr den Einwohnern und den Wachen des Ortes helfen.",al={"warum nach goldhain gehen","warum die abtei von nordhain verlassen"}},{q="Wo ist Priesterin Josetta in Goldhain zu finden?",a="Priesterin Josetta befindet sich im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, wo sie Priester ausbildet.",al={"wo ist priesterin josetta","josetta finden","josetta standort"}},{q="Was geschieht nach dem Treffen mit Priesterin Josetta?",a="Nach Eurem Treffen mit Priesterin Josetta prüft sie Eure Ausbildung, indem sie Euch bittet, eine verwundete Wache zu versorgen und zeremonielle geistliche Gewänder entgegenzunehmen.",al={"nächste quest nach dem licht geneigt","was folgt auf dem licht geneigt"}},{q="Ist diese Quest auf Priester beschränkt?",a="Ja. Diese Lehren richten sich an Priesternovizen, die lernen, der Kirche des Heiligen Lichts zu dienen.",al={"kann jede klasse dem licht geneigt machen","ist das nur für priester"}},{q="Welche Rolle spielt die Kirche des Heiligen Lichts in Elwynn?",a="Die Kirche des Heiligen Lichts bietet den Einwohnern und Verteidigern, die in Elwynn Banditen und gefährlichen Wildtieren gegenüberstehen, Trost, geistliche Führung und Heilung.",al={"rolle der kirche des heiligen lichts","priester in elwynn"}}},fp="21,185,26.227.0,21.380.0,45.131.0,51.175.0,50.88.0,45.142.0,36.93.0,59.154.0"}
P.entries["quest:5624"] = {n="Gewänder des Lichts",s="Priesterin Josetta schickt Euch östlich von Goldhain zum Kristallsee, wo Guard Roberts verwundet liegt. Seine Genesung ist für den Ort wichtig, und die Kirche des Heiligen Lichts wird Euren Dienst anerkennen.",h="Priesterin Josetta schickt Euch östlich von Goldhain zum Kristallsee, wo Guard Roberts verwundet liegt.",kw={"kristallsee","wald von elwynn","gewänder des lichts","goldhain","guard roberts","lesser heal","power word fortitude","priesterrobe","priesterin josetta"},ang={["class:Priest"]="Als Priester setzt Ihr das in Nordhain Gelernte im Dienst vor Ort ein. Verbündete zu heilen und zu stärken hilft, die Kämpfer an vorderster Front am Leben zu halten.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie örtliche Kirchenschüler Stadtwächtern helfen, standzuhalten, während Sturmwinds Armee überlastet ist und in den Weilern fehlt.",["race:Human"]="Als Mensch gehört Ihr einer Kultur an, die die Kirche des Heiligen Lichts ehrt. Gewänder von der Priesterin einer Gemeinde zu erhalten, ist ein wichtiger gesellschaftlicher und geistlicher Meilenstein."},sec={{t="Test of Faith in der Praxis",b="Josetta fordert Euch auf, göttliche Macht einzusetzen, bevor die Kirche einen Priesternovizen anerkennt. Guard Roberts braucht Heilung und gibt Euch damit Gelegenheit, einem Bedürftigen zu dienen. Ihn zu versorgen ist Euer erster Schritt zur formellen Anerkennung in der Kirche des Heiligen Lichts."},{t="Das Königreich stärken",b="Schließt Roberts' Wunden mit heilenden Gebeten und stärkt ihn dann mit einem Segen der Seelenstärke. Er braucht Heilung und Widerstandskraft, um seinen Dienst wieder aufzunehmen. Eure Fürsorge hilft einem Stadtwächter, Gefahren standzuhalten, und unterstützt die Gemeinde. Josetta erwartet von einem Priester, Verteidiger zu stärken und ihre Wunden zu heilen."},{t="Gewänder des Ordens",b="Kehrt nach Roberts' Versorgung ins Gasthaus „Zur Höhle des Löwen“ zurück, um Eure ersten offiziellen Roben zu erhalten. Sie stehen für die Anerkennung und Gemeinschaft der Priesterschaft von Sturmwind, auch wenn sie für die weitere Ausbildung nicht erforderlich sind. Die Kirche erkennt Euch als Diener des Heiligen Lichts an."}},faq={{q="Wo finde ich Guard Roberts?",a="Guard Roberts befindet sich unmittelbar östlich von Goldhain, nahe dem Kristallsee. Er ruht am Straßenrand beim Wasser, während er sich von Wunden erholt, die er im Wachdienst erlitten hat.",al={"guard roberts standort","wo ist guard roberts","guard roberts finden"}},{q="Welche Zauber werden benötigt, um diese Quest abzuschließen?",a="Verwendet Lesser Heal auf Rang zwei, um Guard Roberts' Gesundheit wiederherzustellen, und wirkt dann Power Word: Fortitude, um ihn zu stärken. Kehrt anschließend zu Priesterin Josetta zurück.",al={"benötigte zauber","welche zauber auf roberts wirken","wie guard roberts heilen"}},{q="Wer ist Priesterin Josetta?",a="Priesterin Josetta bildet im Gasthaus „Zur Höhle des Löwen“ in Goldhain Priester für die Kirche des Heiligen Lichts aus. Sie unterweist junge Akolythen aus der Abtei von Nordhain im praktischen Dienst und in göttlicher Magie.",al={"josetta hintergrundgeschichte","priesterin josetta goldhain","wer vergibt gewänder des lichts"}},{q="Warum vergibt die Kirche Roben für diese Aufgabe?",a="Die Roben zeigen, dass die Kirche des Heiligen Lichts den Akolythen anerkennt und seinen geistlichen Dienst unterstützt. Die Versorgung von Guard Roberts beweist das Können und die Disziplin, die zum Tragen der Kirchengewänder erforderlich sind.",al={"warum gewänder des lichts","priesterrobe belohnung hintergrundgeschichte","bedeutung der kirchenroben"}},{q="Können andere Klassen diese Quest abschließen?",a="Nein. Nur Priester der Allianz können diese Prüfung während ihrer ersten Ausbildung abschließen, nachdem sie grundlegende Heil- und Schutzgebete erlernt haben.",al={"gewänder des lichts nur für priester","können paladine gewänder des lichts abschließen","priester klassenquest"}},{q="Was geschieht nach Abschluss von Gewänder des Lichts?",a="Nach Eurer ersten Priesterausbildung in Goldhain gibt es keine unmittelbare Folgequest. Priesterin Josetta und andere Lehrer im ganzen Königreich bieten weitere Ausbildung und Prüfungen an, während Ihr Erfahrung sammelt.",al={"nächste quest nach gewänder des lichts","gewänder des lichts folgequest"}}},fx={["45956511"]={q="Warum möchte Priesterin Josetta, dass dies erledigt wird?",a="Priesterin Josetta stellt üblicherweise eine kleine Herausforderung, um Priesternovizen zu prüfen, bevor die Kirche des Heiligen Lichts sie offiziell mit ihren Gewändern anerkennt. Als sie hörte, dass ein Stadtwächter in der Nähe des Sees östlich von Goldhain verwundet liegt, sieht sie eine Gelegenheit, Eure heilende und schützende Magie im Feld zu testen und gleichzeitig dabei zu helfen, die Sicherheit der Stadt zu gewährleisten.",al={"warum schickt josetta euch","priesterin josettas beweggrund","warum wächter roberts heilen"}},["010a8804"]={q="Wer ist Wächter Roberts?",a="Wächter Roberts ist ein Wächter aus Sturmwind, der bei Goldhain stationiert ist und in der Nähe des Sees östlich der Stadt verwundet wurde. Angesichts der Bedrohungen, die auf den Wald von Elwynn drücken, zählt jeder fähige Verteidiger, weshalb seine Genesung für den Schutz der Gemeinde von entscheidender Bedeutung ist.",al={"wächter roberts","wer ist der verwundete wächter","der verwundete wächter roberts"}}},fp="21,192,25.251.0,20.297.0,22.262.0,31.155.0,48.149.0,25.192.0,49.200.0,38.137.0,52.197.0"}
P.entries["quest:5625"] = {n="Gewänder des Lichts",s="Auf Maxan Anvols Drängen helft Ihr südlich von Kharanos einem verwundeten Gebirgsjäger, bevor Ihr die Gewänder des Lichts erhaltet.",h="Auf Maxan Anvols Drängen helft Ihr südlich von Kharanos einem verwundeten Gebirgsjäger, bevor Ihr die...",kw={"dun morogh","seelenstärke","gewänder des lichts","heiliges licht","eisenschmiede","kharanos","lesser heal","maxan anvol","gebirgsjäger dolf","priester"},ang={["class:Priest"]="Als Priester steigt Ihr vom Novizen zum anerkannten Geistlichen des Heiligen Lichts auf, dem man anvertraut, Gefährten an vorderster Front am Leben zu halten.",["faction:Alliance"]="Als Mitglied der Allianz sucht Ihr beim Heiligen Licht Trost und Heilung auf dem Schlachtfeld, während Soldaten gegen Troggs, Bestien und Schlimmeres standhalten.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Gebirgsjäger von Eisenschmiede die gefährlichen Pässe von Dun Morogh bewachen. Die Versorgung verwundeter Späher wie Dolf stärkt die Verbindung zwischen zwergischem Glauben und militärischer Verteidigung."},sec={{t="Eine dringende Prüfung",b="Maxan Anvol, der Priesterlehrer, bittet vor der Zeremonie um praktische Hilfe. Akolythen müssen gewöhnlich formelle Prüfungen bestehen, um sich der Kirchengewänder würdig zu erweisen. Doch Gebirgsjäger Dolf ist verwundet und braucht jetzt Hilfe."},{t="Beistand für die Gebirgsjäger",b="Südlich von Kharanos findet Ihr Gebirgsjäger Dolf, der im Dienst verwundet wurde. Heilende Gebete versorgen seine Verletzungen. Machtwort: Seelenstärke kräftigt ihn und hilft, einen Verteidiger von Eisenschmiede am Leben zu halten."},{t="Roben der Kirche",b="Sobald Dolf Hilfe erhalten hat, überreicht Maxan Anvol Euch die zeremoniellen Gewänder. Die Roben wärmen Euch in der Kälte von Dun Morogh und kennzeichnen Euch als Diener des Lichts. Ihr seid bereit, verwundeten Wanderern und örtlichen Wachen beizustehen."}},faq={{q="Was ist das Ziel dieser Quest?",a="Maxan Anvol prüft, ob ein angehender Priester mit seinen ersten Zaubern jemandem in Not helfen kann. Ihr findet den verletzten Gebirgsjäger Dolf südlich von Kharanos, heilt seine Wunden und stärkt ihn mit Machtwort: Seelenstärke.",al={"was ist zu tun","gewänder des lichts ziel"}},{q="Wer ist Maxan Anvol?",a="Maxan Anvol ist der zwergische Priesterlehrer in Kharanos. Er unterweist junge Priester aus dem Coldridgetal und zieht die unmittelbare Lebensrettung durch das Licht einer streng geregelten Liturgie vor.",al={"wer ist maxan anvol","kharanos priesterlehrer"}},{q="Wer ist Gebirgsjäger Dolf?",a="Dolf ist ein Gebirgsjäger aus Eisenschmiede, der nahe Kharanos stationiert ist und auf Patrouille verletzt wurde. Er wartet südlich der Siedlung, wohin Initianten geschickt werden, um seine Wunden zu heilen und ihm Seelenstärke zu verleihen.",al={"dolf aufenthaltsort","wer ist dolf"}},{q="Warum erhält ein Priester für diese Aufgabe besondere Gewänder?",a="Gewänder und Roben zeigen die Hingabe und den Rang eines Gläubigen innerhalb des Heiligen Lichts. Soldaten und andere Mitglieder der Gemeinschaft erkennen an der Robe einen Priester, der lebensbedrohliche Verletzungen versorgen und geistlichen Beistand leisten kann.",al={"warum tragen priester roben","priestergewänder hintergrund"}},{q="Warum verehren Zwerge das Heilige Licht?",a="Die Zwerge von Eisenschmiede übernahmen das Heilige Licht durch jahrhundertelangen engen Kulturaustausch und Bündnisse mit den Menschen von Lordaeron und Sturmwind. Zwergische Priester verbinden traditionelle Zähigkeit des Hochlands mit Ehrfurcht vor Mitgefühl, Beharrlichkeit und Schutz.",al={"zwerge licht hintergrund","glauben zwerge an das licht"}},{q="Was geschieht nach Abschluss dieser Prüfung?",a="Nach der Prüfung ermutigt Maxan Anvol den frisch eingekleideten Akolythen, hinauszuziehen, Kampf- und Unterstützungszauber zu üben und gemeinsam mit anderen Reisenden seine Grenzen auszuloten. Innerhalb der Kirche warten schwerere Prüfungen, während der Priester an Erfahrung und Macht gewinnt.",al={"was kommt nach gewänder des lichts","nächste priesterprüfung"}}},fx={["21e41a20"]={q="Warum möchte Maxan Anvol, dass Ihr Dolf heilt?",a="Priester Eures Standes müssen normalerweise formale Prüfungen ablegen, um zu beweisen, dass sie würdig sind, kirchliche Gewänder zu tragen. Maxan Anvol hat jedoch dringendere Angelegenheiten im Sinn und erhielt Nachricht, dass Bergsteiger Dolf südlich von Kharanos verletzt liegt. Anstatt eine müßige Prüfung durchzuführen, nutzt Maxan diesen echten Notfall, um zu sehen, ob Ihr Euren Glauben in die Praxis umsetzen könnt, indem Ihr einen Verbündeten auf dem Feld heilt und stärkt.",al={"warum schickt maxan euch","maxan anvols beweggrund","warum bergsteiger dolf helfen"}},["574078e1"]={q="Warum schickt Maxan Anvol Euch, anstatt sich selbst um Dolf zu kümmern?",a="Maxan ist durch umfassendere Pflichten bei der Betreuung der Gemeinde und kirchliche Angelegenheiten in Kharanos gebunden, und Ihr steht gerade vor ihm und benötigt Eure Prüfung. Euch in den Schnee hinauszuschicken löst zwei Probleme auf einmal: Es bietet sofortige Hilfe für den verwundeten Bergsteiger und beweist gleichzeitig, ob Eure Ausbildung im Licht Euch auf die rauen Realitäten von Dun Morogh vorbereitet hat.",al={"warum kann maxan dolf nicht heilen","warum braucht maxan mich","warum einen novizen schicken"}}},fp="21,127,15.204.0,23.194.0,19.222.0,34.208.0,19.191.0,24.179.0,58.219.0,38.253.0,41.248.0"}
P.entries["quest:5626"] = {n="Dem Licht geneigt",s="„Dem Licht geneigt“ markiert den Übergangsritus eines jungen Priesters von den abgelegenen Übungsplätzen des Coldridgetals in die weiteren Gefilde von Dun Morogh. Auf Anweisung von Branstock Khalder werden die Novizen durch den Bergtunnel nach Kharanos geschickt, um ihre Studien beim Priesterlehrer Maxan Anvol fortzusetzen. Dies signalisiert, dass ein Akolyth bereit ist, echte Verantwortung zu übernehmen und sich die traditionellen Gewänder seiner Berufung zu verdienen.",h="„Dem Licht geneigt“ markiert den Übergangsritus eines jungen Priesters von den abgelegenen Übungsplätzen des...",kw={"branstock khalder","das coldridgetal","dun morogh","dem licht geneigt","kharanos","licht","maxan anvol","priester","gewänder"},ang={["class:Priest"]="Diese Aufgabe ist ein Meilenstein für angehende Priester; sie markiert ihren formellen Abschluss der Grundausbildung, den Eintritt in den aktiven Dienst und den Erhalt ihrer ersten Gewänder.",["race:Dwarf"]="Das Priestertum der Zwerge verbindet spirituelle Hingabe mit praktischer Widerstandskraft und schickt die Akolythen direkt von den Feuern Coldridges in die rauen, eisigen Winde von Dun Morogh."},sec={{t="Den Amboss verlassen",b="In der abgeschiedenen Wiege des Coldridgetals beginnen Zwergpriester ihre Studien unter den wachsamen Augen von Ausbildern wie Branstock Khalder. Sobald ein Novize ausreichend Hingabe und Verständnis für Heiligmagie beweist, findet seine einführende Unterweisung ein Ende. Anstatt sie behütet in Ambossar zu belassen, schickt Khalder vielversprechende Schüler über die Berge nach Kharanos, wo die Anforderungen von geistlichem Dienst und Verteidigung mit den alltäglichen Nöten des Volkes von Dun Morogh verschmelzen."},{t="Ein Schritt nach Kharanos",b="Um Kharanos zu erreichen, muss man durch den Tunnel der Eisklamm in die windgepeitschten Schneefelder des zentralen Dun Morogh wandern. In der Siedlung wartet Maxan Anvol, ein erfahrener Priester, der damit betraut ist, Schüler über einfache Gebete hinauszuführen. Anvol ist fest davon überzeugt, dass die Hingabe an das Heilige Licht gleichermaßen moralischen Charakter, körperliche Zähigkeit und einen unbezwingbaren Willen erfordert. Für Akolythen, die unter seiner Anleitung ihre Entschlossenheit beweisen, hält Anvol ihre ersten formellen Amtsgewänder bereit."}},faq={{q="Wer schickt Euch auf diese Reise?",a="Branstock Khalder, der in Ambossar im Coldridgetal stationierte Priesterlehrer der Zwerge, schickt Euch nach Kharanos, sobald Ihr genügend Begabung im Umgang mit dem Heiligen Licht bewiesen habt, um fortgeschrittene Studien aufzunehmen.",al={"wer vergibt die quest","questgeber","branstock khalder"}},{q="Wer ist Maxan Anvol?",a="Maxan Anvol ist der im Bergdorf Kharanos stationierte Priesterlehrer. Er leitet angehende Priester an und lehrt sie, ihre Hingabe mit körperlicher Ausdauer und geistiger Stärke zu stählen.",al={"maxan anvol lore","wer ist maxan anvol","kharanos priesterlehrer"}},{q="Was geschieht nach dem Eintreffen bei Maxan Anvol?",a="Maxan Anvol fordert Euch auf, Eure Würdigkeit durch die Quest „Gewänder des Lichts“ zu beweisen. Er beauftragt Euch, verletzten Einheimischen zu helfen, bevor Ihr Eure ersten offiziellen Priesterroben erhaltet.",al={"nächste quest","was folgt auf dem licht geneigt","gewänder des lichts"}},{q="Warum müssen Priester das Coldridgetal so früh verlassen?",a="Das Coldridgetal bietet lediglich die Grundlagen von Kampf und Zauberkunst. Größere Siedlungen wie Kharanos sind unmittelbaren logistischen und verteidigungspolitischen Bedrohungen ausgesetzt und bieten angehenden Priestern praktische Erfahrung im Dienst an ihrem Volk.",al={"warum coldridge verlassen","ambossar verlassen","warum nach kharanos reisen"}},{q="Erhalten menschliche Priester dieselbe Quest?",a="Menschliche Priester im Wald von Elwynn absolvieren einen gleichwertigen Übergangsritus unter genau demselben Namen. Sie werden von Priesterin Anetta in Nordhain angewiesen, Priesterin Josetta in Goldhain aufzusuchen.",al={"mensch dem licht geneigt","nordhain version"}},{q="Wie unterscheidet sich hier die zwergische Sichtweise auf das Licht?",a="Zwerge legen neben der Frömmigkeit großen Wert auf körperliche Stärke, Willenskraft und praktische Ausdauer. Wie Maxan Anvol bemerkt, verlangt der Dienst am Licht in den eisigen Berggipfeln ebenso viel körperliche Stärke wie Glauben.",al={"zwerge lichtglaube","zwerge und das licht"}}},fx={["7dcff5c0"]={q="Warum schickt Branstock Khalder Euch nach Kharanos?",a="Branstock erkennt, dass Ihr die grundlegenden Lehren im Coldridgetal hinter Euch gelassen habt. Um Eure spirituelle Reise fortzusetzen und die Gewänder zu verdienen, die einem ordinierten Diener des Heiligen Lichts angemessen sind, schickt er Euch zu Maxan Anvol, einem hochrangigen Priester in Kharanos, der Eure Würdigkeit prüfen und Eure nächsten Schritte leiten kann.",al={"warum nach kharanos schicken","branstock khalders beweggrund","warum maxan anvol besuchen"}}},fp="21,241,17.208.0,22.332.0,30.155.0,19.180.0,40.151.0,49.161.0,41.152.0,51.194.0"}
P.entries["quest:5627"] = {n="Sterne von Elune",s="Im Tempel des Mondes in Darnassus folgen Nachtelfenakolythen dem Ruf der Sisterhood of Elune. Ihre Hingabe hat ihnen heilige Unterweisung in ihrem Glauben verdient.",h="Im Tempel des Mondes in Darnassus folgen Nachtelfenakolythen dem Ruf der Sisterhood of Elune.",kw={"darnassus","priesterin alathea","returning home","sisterhood of elune","sterne von elune","starshards","tempel des mondes"},ang={["class:Priest"]="Als Priester folgt Ihr dem Pfad der Kaldoreipriester und empfangt astrale Zauber, die Euch die Mondgöttin gewährt.",["faction:Alliance"]="Als Mitglied der Allianz steht Ihr unter menschlichen und zwergischen Priestern des Heiligen Lichts. Die Hingabe der Nachtelfen an Elune bringt uralte himmlische Magie in die Allianz.",["race:NightElf"]="Als Kaldorei ist Euer Dienst an Elune mit dem gesellschaftlichen und kulturellen Leben verbunden. Dem Ruf der Schwesternschaft zu folgen, markiert Euer Erwachsenwerden im Dienste Teldrassils."},sec={{t="Ein Ritus der Hingabe",b="Nachtelfenpriester schöpfen ihre heilige Macht aus Elune, ihrer Göttin. Menschen und Zwerge wenden sich dem Licht zu. Wenn ein Akolyth dem Reich mit unerschütterlicher Hingabe dient, wird die Schwesternschaft in Darnassus auf ihn aufmerksam. Der Akolyth wird in den Tempel des Mondes gerufen und einer tieferen Zwiesprache für würdig befunden.\n\nDort erlernt der Priester heilige Zauber, die über Jahrtausende der Anbetung hinweg weitergegeben wurden."},{t="Gaben der Mondgöttin",b="Priesterin Alathea ruft den Initianden, die heiligen Mysterien des Nachtelfenglaubens zu erlernen, darunter Starshards. Diese Zauber kanalisieren den strahlenden Zorn und die Gnade der Weißen Dame. Die Unterweisung führt einen Akolythen über die Grundausbildung hinaus, bereit, sich in Elunes Namen über Teldrassils schützendes Blätterdach hinauszuwagen."}},faq={{q="Welchen Zweck hat diese Quest?",a="Die Sisterhood of Elune erkennt die Hingabe eines Initianden an. Priesterin Alathea lehrt den jungen Priester Nachtelfenzauber wie Starshards.",al={"sterne von elune quest","was gibt es als belohnung","warum diese quest machen"}},{q="Wer bietet Sterne von Elune an?",a="Priesterin Alathea, eine Anführerin der Sisterhood of Elune, vollendet den Ritus im Tempel des Mondes in Darnassus.",al={"wer vergibt sterne von elune","questgeber sterne von elune","wo ist alathea"}},{q="Warum ist diese Quest auf Nachtelfen beschränkt?",a="Die Riten gehören der Sisterhood of Elune, der uralten Priesterschaft des Nachtelfenglaubens. Kaldoreipriester schöpfen ihre besondere Magie aus der Zwiesprache mit Elune, während andere Priesterschaften der Allianz das Heilige Licht studieren.",al={"können menschen das machen","ist das nur für nachtelfen","wer kann sterne von elune machen"}},{q="Wohin führt diese Quest innerhalb der Priestergeschichte?",a="Nach „Returning Home“ kehrt ein angehender Priester, der überall auf Teldrassil geholfen hat, zur weiteren Unterweisung im Tempel des Mondes in die Hauptstadt zurück.",al={"was kommt vor sterne von elune","sterne von elune voraussetzung","returning home quest"}},{q="Welche Art von Magie gewährt Elune ihren Priestern?",a="Elune ergebene Priester verweben Mondlicht, Sternenlicht und Schatten. Durch Riten wie Starshards rufen Kaldoreianbeter himmlisches Feuer auf ihre Feinde herab und vereinen göttliches Gericht mit astralem Zorn.",al={"elune zauber","nachtelfenpriester magie","starshards hintergrund"}},{q="Wo in Darnassus findet dies statt?",a="Der Ritus findet im Tempel des Mondes statt, einem marmornen Heiligtum über dem südlichen Viertel von Darnassus. Er ist das religiöse Herz der Kaldoreination.",al={"sterne von elune ort","wo ist priesterin alathea","tempel des mondes ort"}}},fx={b42d6b57={q="Warum lässt Priesterin Alathea nach Euch rufen?",a="Priesterin Alathea wacht über das Wachstum der aufstrebenden Nachtelfpriester in Darnassus. Sobald Ihr Eure Hingabe bewiesen und von Eurem ersten Dienst zurückgekehrt seid, ruft sie Euch zu sich, um zu bestätigen, dass Ihr wirklich bereit für tiefere Mysterien seid. Ihr Ziel ist es, Sternensplitter zu verleihen, ein göttliches Geschenk himmlischen Zorns, das von der Mondgöttin nur den gläubigen Kaldorei-Priestern gewährt wird, die sich ihres Blickes als würdig erwiesen haben.",al={"warum will priesterin alathea dies","alathea beweggrund","warum sterne von elune"}}},fp="14,166,18.384.0,25.305.0,34.138.0,26.114.0,44.212.0,55.149.0,52.196.0,40.156.0"}
P.entries["quest:5628"] = {n="Heimkehr",s="In Goldhain hört ein junger Nachtelfenpriester einen dringenden Ruf aus Darnassus. Priesterin Josetta überbringt die Botschaft: Kehrt in den Tempel des Mondes zurück und setzt Eure Ausbildung bei Priesterin Alathea fort.",h="In Goldhain hört ein junger Nachtelfenpriester einen dringenden Ruf aus Darnassus.",kw={"darnassus","elune","goldhain","priesterin alathea","priesterin josetta","heimkehr","stars of elune","tempel des mondes"},ang={["class:Priest"]="Jeder Priesterorden ist tief in der Tradition verwurzelt. Als Akolyth der Kaldorei macht Ihr in den Mondriten nur mit Zustimmung der ranghohen Priesterinnen im Tempel des Mondes Fortschritte.",["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr die wachsende Zusammenarbeit zwischen der Kirche des Heiligen Lichts in Elwynn und der Sisterhood of Elune in Darnassus. Ihre Gastfreundschaft stärkt die Bande zwischen den Völkern der Allianz.",["race:NightElf"]="Als Nachtelf mögt Ihr weit über das Meer in die Länder der jüngeren Völker reisen, doch Teldrassil und Elunes Segen ziehen Euch zu Euren heiligen Stätten zurück."},sec={{t="Eine Botschaft in Goldhain",b="Nachtelfen sind im Wald von Elwynn selten, und ein junger Akolyth in den menschlichen Siedlungen erregt Aufmerksamkeit. Wenn Ihr Goldhain erreicht, begrüßt Euch Priesterin Josetta mit Neuigkeiten. Eine Schwester von Elune ist über Kontinente gereist, um Euch zu suchen, und überbringt einen dringenden Befehl aus dem Tempel des Mondes. Eure Berufung führt Euch nun zurück nach Kalimdor, wo Ihr Eure Ausbildung vertiefen könnt."},{t="Der Ruf des Tempels",b="Darnassus blickt in Fragen des Glaubens und der Führung der Nachtelfen zum Tempel des Mondes. Priesterin Alathea und Hohepriesterin Tyrande Wisperwind beaufsichtigen die Ausbildung der Schwesternschaft und wachen über ihre Schüler, selbst wenn Neugier sie übers Meer führt. Wenn Ihr zurückkehrt, empfangen Euch die Priesterinnen mit mütterlicher Fürsorge. Dann beginnen sie, Euch tiefer in die himmlischen Mysterien der Mondgöttin einzuweihen."}},faq={{q="Warum wird ein Nachtelfenpriester aus den Menschenlanden zurückgerufen?",a="Junge Nachtelfenpriester, die in die Östlichen Königreiche reisen, bleiben ihrem heiligen Orden in Teldrassil verbunden. Priesterin Alathea verfolgt ihre Fortschritte und ruft sie in den Tempel des Mondes zurück, sobald sie bereit sind, höhere Riten Elunes zu erlernen.",al={"warum die rückberufung","warum heimkehr","priesterquest goldhain"}},{q="Wer ist Priesterin Josetta?",a="Priesterin Josetta ist die menschliche Priesterlehrerin im Gasthaus \"Zur Höhle des Löwen\" in Goldhain. Sie dient dem Heiligen Licht und achtet die Akolythen der Kaldorei, die zu Besuch kommen, und hilft Gesandten aus Darnassus, ihre umherstreifenden Verwandten zu erreichen.",al={"wer vergibt heimkehr","priesterlehrer goldhain","priesterin josetta"}},{q="Wer ist Priesterin Alathea?",a="Priesterin Alathea ist eine hochrangige Schwester von Elune, die im Tempel des Mondes in Darnassus Akolythen ausbildet. Gemeinsam mit Hohepriesterin Tyrande Wisperwind wacht sie über die Entwicklung und geistige Hingabe junger Nachtelfenpriester.",al={"wer ist alathea","priesterlehrer im tempel","priesterin alathea"}},{q="Was geschieht nach der Rückkehr nach Darnassus?",a="Wenn Ihr Euch bei Priesterin Alathea im Tempel des Mondes meldet, heißt sie Euch daheim willkommen und gibt Euch Eure nächste Aufgabe, Stars of Elune. Dort erforscht Ihr die heilige Macht, die Euch die Göttin gewährt.",al={"what comes next","nächste quest nach heimkehr","folgequest"}},{q="Wie unterscheidet sich dies vom üblichen Ausbildungsweg?",a="Dieser alternative Weg führt Nachtelfenpriester, die sich für eine Ausbildung in Menschenlanden wie dem Wald von Elwynn entscheiden, zu den Lehrern ihres Volkes in Darnassus zurück. Dort können sie die besonderen Priesterfähigkeiten ihres Volkes erlernen.",al={"machen das alle priester","ist diese quest pflicht","priesterquest elwynn"}},{q="Wie fand die Botin einen Akolythen so weit entfernt im Wald von Elwynn?",a="Eine Schwester von Elune reist von Darnassus in die Östlichen Königreiche und hinterlässt eine Botschaft bei Lehrern der Allianz wie Priesterin Josetta in Goldhain. Josetta hält nach dem reisenden Novizen Ausschau und weist ihm den Weg nach Hause.",al={"woher wussten sie vom aufenthaltsort","wer folgte der spur nach goldhain"}}},fx={["50552740"]={q="Warum möchte Priesterin Josetta, dass Ihr nach Darnassus zurückkehrt?",a="Priesterin Josetta leitet Eure Ausbildung nicht selbst; sie übermittelt eine dringende Vorladung Eures eigenen Volkes. Eine Priesterin aus Darnassus kam eigens nach Goldhain, um nach Euch zu suchen, und bat darum, dass Ihr Euch bei Priesterin Alathea im Tempel des Mondes meldet. Josetta erkennt, wie weit Ihr in jungen Jahren von Zuhause gereist seid, aber als eine Mitdienerin des Göttlichen weiß sie, dass fortgeschrittene spirituelle Unterweisung durch Eure Mentoren Vorrang vor dem Umherwandern in fremden Landen hat.",al={"warum schickt josetta euch zurück","priesterin josettas beweggrund","warum nach darnassus zurückkehren"}}},fp="14,195,19.360.0,22.395.0,58.247.0,25.209.0,25.225.0,42.191.0,51.207.0,67.207.0"}
P.entries["quest:5629"] = {n="Heimkehr",s="In Heimkehr werden junge Nachtelfenpriester nach Darnassus gerufen. Nach ihrem Dienst in Teldrassils Wildnis werden sie zum Tempel des Mondes gerufen, um Priesterin Alathea und Hohepriesterin Tyrande Wisperwind zu treffen.",h="In Heimkehr werden junge Nachtelfenpriester nach Darnassus gerufen.",kw={"darnassus","dolanaar","elune","laurna morgenglanz","priesterin alathea","heimkehr","sisterhood of elune","teldrassil","tempel des mondes","tyrande"},ang={["class:Priest"]="Als Priester folgt Ihr einem Ruf, der Euren Übergang vom Akolythen des Waldes zum Diener der Sisterhood of Elune markiert. Er ruft Euch nach Darnassus.",["race:NightElf"]="Als Kaldorei folgt Ihr dem Ruf des Tempels des Mondes und erneuert unter den wachsamen Augen von Hohepriesterin Tyrande Wisperwind Eure Verbundenheit mit den Traditionen Eures Volkes."},sec={{t="Ein Ruf aus Darnassus",b="Rund um Dolanaar versorgen Priester die Verwundeten und läutern Verderbnis. Ihr Dienst erregt die Aufmerksamkeit der Sisterhood of Elune. Ausbilderin Laurna Morgenglanz überbringt vielversprechenden Initianden die Nachricht, dass Priesterin Alathea sie zu treffen wünscht. Hilfe für die örtlichen Siedlungen ist wichtig, doch jeder Gläubige muss auch seine Zwiesprache mit der Mondmutter vertiefen und dem höheren Ruf des Glaubens folgen."},{t="Im Tempel des Mondes",b="Von Teldrassils Ästen führt der Weg zum Tempel des Mondes in Darnassus. Elunes sanfter Glanz erfüllt das Heiligtum über der Stadt. Es ist das wichtigste Gotteshaus und die spirituelle Hauptstadt der Kaldorei. Eine Einladung in seine Hallen bedeutet, dass die Führung der Priesterschaft einen Initianden anerkennt und nicht länger nur als jungen Schüler betrachtet."},{t="Tyrandes und Alatheas Gunst",b="Priesterin Alathea begrüßt die heimkehrenden Initianden herzlich. Sie sagt, dass sie und Hohepriesterin Tyrande Wisperwind stolz sind, wenn Initianden sich in die ungewisse Welt wagen und unversehrt zurückkehren. Diese Heimkehr eröffnet weiterführende heilige Prüfungen unter Alatheas unmittelbarer Anleitung."}},faq={{q="Wer bietet die Quest Heimkehr an?",a="Laurna Morgenglanz, die Priesterlehrerin in Dolanaar, ruft junge Nachtelfenpriester zu sich, sobald sie genügend Ausbildung und Erfahrung gesammelt haben.",al={"wer vergibt heimkehr","heimkehr questgeber","laurna morgenglanz quest"}},{q="Wo befindet sich Priesterin Alathea?",a="Priesterin Alathea befindet sich im Tempel des Mondes in Darnassus, nahe dem Zentrum der Nachtelfenhauptstadt auf Teldrassil.",al={"wo ist alathea","priesterin alathea standort","tempel des mondes priesterin"}},{q="Warum möchte Priesterin Alathea mich sehen?",a="Die Ältesten der Sisterhood of Elune haben Euren Dienst in Teldrassils Wildnis bemerkt. Alathea glaubt, dass Ihr für weiterführende Unterweisung und größere geistliche Pflichten bereit seid.",al={"warum nach darnassus gerufen","warum zum tempel des mondes gehen"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Nur Nachtelfenpriester erhalten diesen Ruf als Teil ihrer frühen Ausbildung und ihrer Einführung in die höheren Pflichten der Sisterhood.",al={"ist heimkehr für alle klassen","können druiden heimkehr machen","quest nur für priester"}},{q="Welche Quest folgt auf Heimkehr?",a="Nachdem Ihr Euch bei Priesterin Alathea gemeldet habt, gibt sie Euch als nächste Aufgabe Stars of Elune.",al={"was kommt nach heimkehr","heimkehr folgequest","nächste quest"}},{q="Welche Bedeutung hat der Tempel des Mondes für Nachtelfen?",a="Der Tempel des Mondes ist Elunes wichtigstes Gotteshaus. Hohepriesterin Tyrande Wisperwind führt von dort aus die Sisterhood und das Volk der Kaldorei.",al={"tempel des mondes hintergrundgeschichte","darnassus tempel des mondes"}}},fx={["1b068d1d"]={q="Warum schickt Laurna Morgenglanz Euch zurück nach Darnassus?",a="Laurna Morgenglanz schickt Euch nicht wegen einer dringenden Krise fort, sondern handelt als Mentorin, die Euer Wachstum leitet. Priesterin Alathea hat Nachricht geschickt und speziell Eure Anwesenheit im Tempel des Mondes angefordert. Die Ältesten der Priesterschaft haben Eure Hingabe und Euren Dienst für das Volk der Nachtelfen in ganz Teldrassil bemerkt und sie glauben, dass Ihr stark genug geworden seid, um größere spirituelle Pflichten im Dienste Elunes zu übernehmen.",al={"warum schickt laurna mich zurück","laurna morgenglanz rückkehr nach hause beweggrund","warum nach darnassus zurückkehren"}},d7077bd4={q="Warum ruft Priesterin Alathea speziell nach Euch?",a="Ihr werdet aufgrund Eurer eigenen bewiesenen Hingabe und Ausbildung gerufen. Priesterin Alathea und Hohepriesterin Tyrande nehmen persönlich Anteil an der Entwicklung junger Akolythen, die hinausziehen, um ihrem Volk zu helfen. Nachdem Ihr Eure Fähigkeiten und spirituelle Reife im Feld bewiesen habt, betrachtet die Führung im Tempel des Mondes Euch als bereit, fortgeschrittenere heilige Verantwortlichkeiten zu übernehmen, die gewöhnliche Akolythen oder Tempelwachen nicht erfüllen können.",al={"warum will alathea mich","warum ich rückkehr nach hause","warum meinen priester rufen"}}},fp="14,215,24.374.0,29.335.0,32.266.0,36.132.0,35.116.0,42.176.0,30.133.0,34.86.0,61.152.0"}
P.entries["quest:563"] = {n="Versetzungen",s="In Süderstade sucht Leutnant Farren Orinelle nach einem Weg zurück nach Sturmwind. Er schickt einen Abenteurer mit einem übertriebenen Bericht über seine Taten gegen die Naga an der Küste nach Burg Sturmwind, bestimmt für seinen ehemaligen Mentor, Major Samuelson.",h="In Süderstade sucht Leutnant Farren Orinelle nach einem Weg zurück nach Sturmwind.",kw={"daggerspine","farren orinelle","major samuelson","reassignment","redpath","süderstade","burg sturmwind"},ang={["faction:Alliance"]="Die Übergabe zeigt das alltägliche politische Ränkespiel im Militär der Allianz. Grenzgarnisonen wie Süderstade können weit von den Ambitionen jener Offiziere entfernt sein, die auf eine Rückkehr nach Sturmwind hoffen.",["race:Human"]="Die Übergabe zeigt die Kluft zwischen menschlichen Flüchtlingen und Verteidigern, die in Lordaeron die Stellung halten, und den politischen Winkelzügen in den hohen Hallen von Burg Sturmwind."},sec={{t="Ein Ausweg aus Süderstade",b="Leutnant Farren Orinelle ist über seine Stationierung im Vorgebirge des Hügellands verbittert. Süderstade liegt weit von der Hauptstadt entfernt, und Marshal Redpath wacht streng über die Stadt. So verbringt Farren seine Tage damit, eine Versetzung nach Süden zu planen. Er beansprucht das Verdienst, die nahegelegenen Daggerspine-Naga vertrieben zu haben, und hofft, als unentbehrlicher, kampferprobter Offizier zu erscheinen, der eine Beförderung verdient."},{t="Beziehungen zur Burg",b="Farren will eine Versetzung, ohne Marshal Redpaths Verdacht zu erregen, also umgeht er die örtliche Befehlskette. Er wendet sich an Major Samuelson, einen hochrangigen Offizier in Burg Sturmwind, der einst sein Mentor war. Ein direkt an Samuelson geschickter Bericht legt Farrens angebliche Taten einem Offizier vor, der über Garnisonszuweisungen entscheiden darf."},{t="Die Mühlen der Bürokratie",b="Major Samuelson erhält das Dossier in Burg Sturmwind und äußert verhaltene Zustimmung zur Initiative seines ehemaligen Schülers gegen die Bedrohung durch die Naga. Doch militärische Entscheidungen brauchen Zeit. Er verspricht lediglich, den Bericht bei der routinemäßigen Personalprüfung im nächsten Monat abzuwägen, wodurch Farrens Zukunft in Süderstade ungewiss bleibt."}},faq={{q="Warum will Farren Orinelle eine Versetzung?",a="Leutnant Farren Orinelle will Süderstade verlassen, einen abgelegenen Außenposten im Norden, den er für langweilig, gefährlich und seiner unwürdig hält. Er sehnt sich nach dem vergleichsweisen Luxus und der Sicherheit Sturmwinds und hofft, dass seine Berichte über die Naga eine Versetzung rechtfertigen.",al={"warum süderstade verlassen","farrens beweggrund","warum will farren fort"}},{q="Wer ist Major Samuelson?",a="Major Samuelson ist ein hochrangiger Offizier in Burg Sturmwind, der die Postenzuweisungen der Stadtwache beaufsichtigt. Er war Leutnant Farren Orinelles Mentor während dessen früher Laufbahn in der Hauptstadt.",al={"wer ist samuelson","samuelsons geschichte"}},{q="Warum kann Farren den Bericht nicht selbst überbringen?",a="Farren steht in Süderstade im aktiven Dienst und darf seinen Posten nicht ohne Erlaubnis verlassen. Außerdem versucht er, Marshal Redpath zu umgehen, seinen unmittelbaren Vorgesetzten, der einen Versetzungsantrag zu Farrens eigenem Vorteil vermutlich behindern würde.",al={"warum muss ich es überbringen","warum nicht selbst überbringen"}},{q="Hat Farren die Naga tatsächlich selbst besiegt?",a="Nein. Farren schickte Abenteurer aus, um Daggerspine-Naga am Oststrand zu töten, und nutzte dann ihren Erfolg im Bericht zur Unterstützung seines Versetzungsgesuchs.",al={"hat farren naga getötet","wahrheit über farrens bericht"}},{q="Wird Farren tatsächlich zurück nach Sturmwind versetzt?",a="Nicht sofort. Major Samuelson verspricht lediglich, den Bericht bei der Personalprüfung im nächsten Monat zu berücksichtigen. Farren bleibt auf absehbare Zeit in Süderstade stationiert, denn die militärische Bürokratie des Königreichs mahlt langsam.",al={"wird farren versetzt","klappt die versetzung"}},{q="Wo befindet sich Major Samuelson?",a="Major Samuelson befindet sich in Burg Sturmwind, der Festung im Herzen Sturmwinds, in der das Oberkommando und der Regentschaftsrat ihren Sitz haben.",al={"samuelsons standort","wo ist major samuelson"}}},fp="12,226,26.366.0,16.333.0,19.304.1,45.241.0,23.174.0,44.229.0,44.154.0,55.221.1,33.137.0"}
P.entries["quest:5630"] = {n="Heimkehr",s="In Dun Morogh ruft eine Vorladung Nachtelfenpriester nach Darnassus zurück. Maxan Anvol schickt sie zu Priesterin Alathea im Tempel des Mondes.",h="In Dun Morogh ruft eine Vorladung Nachtelfenpriester nach Darnassus zurück.",kw={"darnassus","dun morogh","kharanos","maxan anvol","priesterin alathea","heimkehr","stars of elune","teldrassil","tempel des mondes"},ang={["class:Priest"]="Als Priester kehrt Ihr aus fernen Ländern zu den Oberhäuptern der Sisterhood of Elune zurück und bleibt der Moon Goddess unerschütterlich ergeben.",["race:NightElf"]="Als Kaldorei in Dun Moroghs eisigen Winden erhaltet Ihr einen willkommenen Ruf zurück zu Teldrassils vertrauten Heiligtümern und den Wäldern Eurer Ahnen."},sec={{t="Ein Ruf übers Meer",b="In Kharanos sieht Maxan Anvol einen Nachtelfen der bitteren Kälte Dun Moroghs trotzen, fern von Teldrassils friedlichen Wäldern. Der zwergische Priesterlehrer bringt dringende Neuigkeiten. Eine Priesterin Elunes kam auf der Suche nach Euch durch den Ort und trug Befehle aus Darnassus bei sich. Sie rufen Euch unverzüglich zurück."},{t="Der Tempel des Mondes",b="Euer Weg führt Euch übers Meer zum Tempel des Mondes in Darnassus, unter Teldrassils heiligen Ästen. Priesterin Alathea heißt Euch wieder in der Sisterhood of Elune willkommen, erleichtert über Eure sichere Rückkehr aus fremden Ländern. Sie bereitet Eure nächsten Riten der Hingabe vor, beginnend mit Stars of Elune."}},faq={{q="Wer schickt mich auf diese Quest?",a="Maxan Anvol, der zwergische Priesterlehrer in Kharanos, überbringt die Nachricht. Er sagt, eine andere Nachtelfenpriesterin sei auf der Suche nach Euch durch Dun Morogh gereist.",al={"questgeber","wer startet heimkehr","maxan anvol"}},{q="Wohin muss ich gehen, um sie abzuschließen?",a="Kehrt nach Darnassus auf Teldrassil im Norden Kalimdors zurück. Priesterin Alathea erwartet Euch im Tempel des Mondes.",al={"abgabeort","wo ist priesterin alathea","wohin muss ich gehen"}},{q="Warum ruft mich der Tempel des Mondes zurück?",a="Priesterin Alathea und Hohepriesterin Tyrande Wisperwind wachen über die Entwicklung junger Novizen. Alathea möchte wissen, dass Ihr wohlauf seid, von Euren Reisen unter Elune's Grace hören und Eure nächste geistliche Ausbildung mit Stars of Elune beginnen.",al={"warum heimkehr","grund für priestervorladung"}},{q="Was geschieht nach dem Gespräch mit Priesterin Alathea?",a="Wenn Ihr Eure Rückkehr meldet, bietet Priesterin Alathea Euch Stars of Elune an. Damit werden Eure ersten Riten als Kaldorei-Priester fortgesetzt.",al={"nächste quest","what comes next"}},{q="Warum sollte ein Nachtelf auf Stufe zehn in Dun Morogh sein?",a="Nachtelfische Abenteurer können von der Dunkelküste zum Hafen von Menethil in den Östlichen Königreichen segeln. Von dort aus können sie die Lande der Allianz erkunden oder mit zwergischen und gnomischen Gefährten reisen.",al={"warum dun morogh","nachtelf in eisenschmiede"}},{q="Ist diese Quest auch für andere Völker verfügbar?",a="Nein. Sie richtet sich an Nachtelfenpriester, die in den Landen der Zwerge ausgebildet werden, und führt sie in ihre kulturelle und geistliche Heimat Darnassus zurück.",al={"können zwerge heimkehr machen","wer kann diese quest annehmen"}}},fx={["39744d7e"]={q="Warum möchte Maxan Anvol, dass ich nach Darnassus zurückkehre?",a="Maxan Anvol hat kein persönliches Interesse an den Angelegenheiten des Tempels des Mondes. Er leitet lediglich eine dringende Vorladung weiter. Eine Nachtelfpriesterin kam kürzlich durch Dun Morogh und suchte speziell nach Euch, mit der Bitte, dass Ihr Euch wegen wichtiger Angelegenheiten bei Priesterin Alathea in Darnassus meldet. Als freundlicher Priesterausbilder, der Eure Widerstandsfähigkeit im bitteren Zwergenschnee bewundert, erweist Maxan einer reisenden Schwester lediglich einen Gefallen, indem er sicherstellt, dass die Nachricht Eure Ohren erreicht.",al={"warum schickt maxan mich","maxan anvols beweggrund","warum nach darnassus zurückkehren"}}},fp="14,138,24.263.0,22.301.0,27.149.0,37.112.0,46.240.0,51.121.0,51.174.0,39.134.0"}
P.entries["quest:5631"] = {n="Heimkehr",s="Ein Ruf führt einen Nachtelfenpriester aus den Ländern der Menschen zurück nach Teldrassil. Bruder Joshua überbringt den Ruf von Priesterin Alathea zum Tempel des Mondes in Darnassus, wo der junge Priester weiterführende Unterweisung in Elunes Mysterien erhalten wird.",h="Ein Ruf führt einen Nachtelfenpriester aus den Ländern der Menschen zurück nach Teldrassil.",kw={"bruder joshua","darnassus","priester","priesterin alathea","heimkehr","stars of elune","teldrassil","tempel des mondes","tyrande"},ang={["class:Priest"]="Als Priester kehrt Ihr aus der Gemeinschaft mit der Kirche des Heiligen Lichts zur Sisterhood of Elune zurück, wo Ihr die Riten der Kaldorei meistern könnt.",["faction:Alliance"]="Bruder Joshua in den Östlichen Königreichen und die Priesterinnen in Darnassus arbeiten zusammen und spiegeln damit die spirituellen Bande wider, die die Allianz vereinen.",["race:NightElf"]="Als Nachtelfenpriester, der jenseits des Meeres unter Menschen oder Zwergen gewandelt ist, vollzieht Ihr eine heilige Rückkehr zu den Heiligtümern Teldrassils."},sec={{t="Ein Ruf übers Meer",b="Nachtelfenpriester reisen manchmal in die Länder der Menschen, etwa nach Sturmwind, um Gemeinschaft mit der Kirche des Heiligen Lichts zu pflegen. Ihre stärksten Bande verbinden sie weiterhin mit der Sisterhood of Elune. Bruder Joshua berichtet Euch, dass eine Abgesandte der Nachtelfen nach Euch sucht. Eure ersten Wanderjahre sind vorüber, und Euer Heimattempel ruft Euch zur vertieften Ausbildung im inneren Zirkel von Hohepriesterin Tyrande Wisperwind zurück."},{t="Der Tempel des Mondes",b="Jenseits des Meeres heißt Euch der Tempel des Mondes in Darnassus wieder zu Hause willkommen. Priesterin Alathea begrüßt Euch herzlich und feiert Eure sichere Reise durch eine unruhige Welt. Eure Rückkehr bereitet Alathea und Tyrande Freude. Anspruchsvollere spirituelle Prüfungen erwarten Euch."}},faq={{q="Warum gibt Bruder Joshua einem Nachtelfenpriester Anweisungen?",a="Bruder Joshua dient der Kirche des Heiligen Lichts in den Ländern der Menschen, wo junge Priester der Allianz oft gemeinsam ausgebildet werden. Eine Schwester Elunes kam mit einer Botschaft in seine Hallen, die Euch nach Darnassus zurückruft, und Joshua überbringt diesen Ruf.",al={"warum bruder joshua","bruder joshua nachtelf","wer schickt nach hause"}},{q="Wer ist Priesterin Alathea?",a="Priesterin Alathea ist ein hochrangiges Mitglied der Sisterhood of Elune im Tempel des Mondes in Darnassus. Sie arbeitet mit Hohepriesterin Tyrande Wisperwind zusammen und begleitet die Ausbildung und den Aufstieg vielversprechender Nachtelfenpriester.",al={"priesterin alathea","alathea darnassus","wer ist alathea"}},{q="Was geschieht nach der Ankunft im Tempel des Mondes?",a="Im Tempel des Mondes heißt Priesterin Alathea Euch wieder zu Hause willkommen und leitet Euren nächsten Übergangsritus ein. Stars of Elune vertieft Eure Verbindung zur Moon Goddess.",al={"quest nach heimkehr","was kommt als nächstes","stars of elune quest"}},{q="Kann jedes Volk der Allianz diese Quest erledigen?",a="Dieser Ruf richtet sich an Nachtelfenpriester, die während ihrer frühen Ausbildung weit von Kalimdor fortgereist sind. Er ruft Euch nach Hause, um mit der Sisterhood of Elune die priesterlichen Traditionen Eures Volkes zu studieren.",al={"nur für nachtelfen","können menschen heimkehr erledigen","wer kann heimkehr annehmen"}},{q="Wo befindet sich der Tempel des Mondes?",a="Der Tempel des Mondes liegt im südlichen Bezirk von Darnassus, hoch oben auf den Ästen Teldrassils. Er ist das spirituelle Herz der Nachtelfenkultur und der Machtsitz von Hohepriesterin Tyrande Wisperwind.",al={"tempel des mondes standort","wo ist der tempel","wo ist alathea"}},{q="Warum erwähnt Alathea Tyrande Wisperwind?",a="Tyrande Wisperwind ist die Hohepriesterin Elunes und die spirituelle Anführerin der Nachtelfen. Hochrangige Priesterinnen wie Alathea handeln in ihrem Auftrag und begleiten und leiten Novizen, die ihren Glauben nach Tyrandes Maßstäben in der Fremde vertreten.",al={"warum wird tyrande erwähnt","tyrande wisperwind priesterin","alathea und tyrande"}}},fx={["76c2bc63"]={q="Warum ruft Priesterin Alathea speziell nach mir?",a="Priesterin Alathea und die Priesterschaft Elunes haben Euch mit ausgebildet, bevor Ihr Euch aufgemacht habt, Azeroth zu durchqueren. Ein Nachtelfengesandter wurde speziell entsandt, um Euch unter Euren menschlichen Verbündeten in Sturmwind aufzuspüren und die dringende Vorladung zu übermitteln. Jetzt, da Ihr an Macht und Erfahrung gewachsen seid, haben Alathea und Tyrande Wisperwind spezifische Aufgaben und heilige Pflichten in Kalimdor, die eine bewährte Schwester des Mondes erfordern, anstatt eines frischen Novizen.",al={"warum will alathea mich","warum ich rückkehr nach hause","warum ruft priesterin alathea mich"}}},fp="14,240,21.399.0,22.251.0,64.230.0,25.225.0,51.161.0,36.197.0,40.199.0,45.240.0"}
P.entries["quest:5632"] = {n="Heimkehr",s="Priesterin Alathea ruft vielversprechende Nachtelfenpriester zurück nach Darnassus. Im Tempel des Mondes wird die Sisterhood of Elune sie anerkennen und ihre nächsten Schritte lenken.",h="Priesterin Alathea ruft vielversprechende Nachtelfenpriester zurück nach Darnassus.",kw={"darnassus","nara meideros","priesterquest","priesterin alathea","heimkehr","sisterhood of elune","stars of elune","tempel des mondes","tyrande wisperwind"},ang={["class:Priest"]="Als Priester markiert diese Vorladung einen wichtigen Schritt in Eurem Priesteramt. Euer früher Dienst führt Euch vor die Sisterhood of Elune, wo Ihr weitere Unterweisung und Führung erhaltet.",["faction:Alliance"]="Die Sisterhood of Elune ist das spirituelle Herz der Nachtelfen in der Allianz. Ihre Heiler und göttlichen Krieger bereiten sich darauf vor, Bedrohungen in ganz Kalimdor entgegenzutreten.",["race:NightElf"]="Als Kaldorei ist Eure wohlbehaltene Rückkehr zum Tempel des Mondes eine Heimkehr. Sie bekräftigt Elunes Priesterschaft als beständige Quelle kultureller und spiritueller Führung."},sec={{t="Ein Bote der Schwestern",b="Ein Bote der Schwestern findet Euch, während Ihr Nara Meideros im Park von Sturmwind besucht. Ihr habt Eurem Volk in der Ferne gedient, und nun rufen Euch die Anführerinnen des Ordens zurück nach Darnassus. Sie haben Euer spirituelles Wachstum verfolgt und laden Euch zu einer Beurteilung und einem Ritus der Anerkennung vor. Diese Reise markiert Euren Übergang vom neuen Initianden zum aktiven Diener der Mutter Mond."},{t="Audienz im Tempel des Mondes",b="Die Vorladung führt Euch zu Priesterin Alathea im Tempel des Mondes, dem höchsten Heiligtum von Darnassus. Hohepriesterin Tyrande Wisperwind wacht über die Schwestern, die ihre Mitglieder behüten, wo immer sie dienen. Eure wohlbehaltene Rückkehr ehrt Eure Gemeinschaft und Elune. Sie zeigt auch, wie die Gnade der Göttin Euch durch Eure frühen Prüfungen in der Wildnis geleitet und bewahrt hat."}},faq={{q="Warum ruft mich die Priesterin zurück nach Darnassus?",a="Die Sisterhood of Elune hat Euer spirituelles Wachstum verfolgt, und Priesterin Alathea ruft Euch in den Tempel des Mondes, weil Ihr im Orden rasch vorangekommen seid. Dort könnt Ihr eine vertiefende Ausbildung und einen heiligen Segen erhalten.",al={"warum heimkehr","grund für die vorladung","warum alathea besuchen"}},{q="Wer ist Priesterin Alathea?",a="Priesterin Alathea ist eine Mentorin der Sisterhood of Elune und im Tempel des Mondes stationiert. Sie dient unter Hohepriesterin Tyrande Wisperwind, bildet vielversprechende Nachtelfenpriester aus und führt sie durch heilige Riten.",al={"wer ist alathea","alatheas geschichte","identität von priesterin alathea"}},{q="Wohin führt diese Vorladung als Nächstes?",a="Priesterin Alathea schickt Euch als Nächstes zu Stars of Elune, einer uralten Prüfung, bei der Ihr lernt, die himmlische Macht der Göttin zur Verteidigung Eures Volkes zu kanalisieren.",al={"welche quest folgt auf heimkehr","nächster schritt in heimkehr","hinführung zu stars of elune"}},{q="Wer übermittelt die Nachricht durch Nara Meideros?",a="Ein von der Sisterhood of Elune entsandter Bote überbrachte Nara Meideros die Nachricht. Der Orden hält Kontakt zu Priesterinnen, die in der Ferne dienen, darunter Nara im Park von Sturmwind, um die Fortschritte seiner Initianden zu verfolgen.",al={"wer hat nara geschickt","bote der schwestern"}},{q="Erhalten auch andere Völker oder Klassen diese Vorladung?",a="Nein. Die Vorladung richtet sich an die Priesterschaft der Nachtelfen und die Sisterhood of Elune. Andere Völker und Glaubensgemeinschaften suchen Führung bei ihren eigenen spirituellen Mentoren und heiligen Orden.",al={"auch für andere völker als nachtelfen","nur für priester"}},{q="Warum erwähnt Alathea Tyrande Wisperwind?",a="Tyrande Wisperwind führt als Hohepriesterin Elunes die Sisterhood of Elune und die Regierung der Nachtelfen an. Alathea dient unter ihr im Tempel des Mondes und trägt Tyrandes Willen und spirituelle Führung an jeden Initianden heran.",al={"verbindung zu tyrande","beziehung zwischen tyrande und alathea"}}},fx={f171321e={q="Warum schickt Nara Meideros Euch zurück nach Darnassus?",a="Nara Meideros erfüllt lediglich ihre Pflicht gegenüber der Schwesternschaft von Elune. Ein Bote ist eigens eingetroffen, um im Namen der Führung des Ordens im Tempel des Mondes nach Euch zu suchen. Da sie Eure schnellen Fortschritte in den spirituellen und kriegerischen Wegen der Priesterschaft sieht, leitet Nara die Vorladung weiter, damit Ihr direkt von Priesterin Alathea Anleitung erhalten und Eure Hingabe an Elune vertiefen könnt.",al={"warum will nara meideros dass dies getan wird","nara meideros beweggrund","warum schickt man mich zurück nach darnassus"}}},fp="14,169,31.372.0,34.369.0,52.228.0,25.223.0,34.152.0,44.209.0,47.165.0,45.223.0"}
P.entries["quest:5633"] = {n="Heimkehr",s="Nachtelfenpriester in Eisenschmiede werden zum Tempel des Mondes in Darnassus zurückgerufen. Eine Abgesandte der Schwesternschaft sucht Akolythen in der Fremde und schickt sie für weitere Ausbildung und heilige Pflichten zu Priesterin Alathea.",h="Nachtelfenpriester in Eisenschmiede werden zum Tempel des Mondes in Darnassus zurückgerufen.",kw={"braenna kieselbruch","darnassus","priesterquest","priesterin alathea","heimkehr","stars of elune","tempel des mondes"},ang={["class:Priest"]="Als Priester kehrt Ihr von Euren ersten Abenteuern unter Verbündeten der Allianz zur geistigen Heimat der Nachtelfenpriesterschaft im Tempel des Mondes zurück.",["faction:Alliance"]="Als Abenteurer der Allianz erlebt Ihr, wie zwergische Geistliche in Eisenschmiede und die Sisterhood of Elune in Darnassus zusammenarbeiten, um Reisenden zu helfen.",["race:NightElf"]="Als Nachtelf unternehmt Ihr eine seltene Reise von Kalimdor in die Östlichen Königreiche, während Elunes Führung und Tyrandes Priesterschaft über das große Meer hinweg reichen."},sec={{t="Ruf aus der Bergstadt",b="In Eisenschmiede bleiben Nachtelfenpriester der Sisterhood of Elune verbunden, obwohl Teldrassil weit entfernt liegt. Braenna Kieselbruch, eine zwergische Priesterlehrerin im Mystic Ward, überbringt eine Botschaft von einer Nachtelfenpriesterin, die zu Besuch war. Die Abgesandte suchte junge Jünger auf Reisen in der Fremde und sagte, ihre Mentoren bräuchten sie unverzüglich zurück in der Hauptstadt."},{t="Der Tempel des Mondes",b="Im Tempel des Mondes in Darnassus melden sich heimkehrende Akolythen bei Priesterin Alathea. Unter dem Blick von Hohepriesterin Tyrande Wisperwind heißt Alathea ihren Schüler willkommen und ist erleichtert, dass er die Meere sicher überquert hat. Mit der Rückkehr beginnen weitere Hingabe und heilige Pflichten, darunter die Stars of Elune."}},faq={{q="Wer vergibt diese Quest?",a="Braenna Kieselbruch, die zwergische Priesterlehrerin im Mystic Ward von Eisenschmiede, übergibt Euch den Ruf zur Rückkehr.",al={"wer vergibt heimkehr","questgeber heimkehr","braenna kieselbruch standort"}},{q="Bei wem soll ich mich in Darnassus melden?",a="Meldet Euch bei Priesterin Alathea im Tempel des Mondes in Darnassus.",al={"wo heimkehr abgeben","priesterin alathea standort","heimkehr abgeben"}},{q="Warum ruft die Schwesternschaft Priester zurück?",a="Die Sisterhood of Elune ruft ihre Akolythen aus der Fremde zurück, um sie weiter auszubilden und heilige Riten wie die Stars of Elune abzuhalten.",al={"warum heimkehr","warum nach darnassus zurückkehren"}},{q="Ist diese Quest für andere Klassen verfügbar?",a="Nein. Der Ruf richtet sich an Nachtelfenpriester, die schon früh auf ihren Reisen nach Dun Morogh und Eisenschmiede gelangt sind.",al={"können krieger heimkehr machen","quest nur für priester"}},{q="Was geschieht nach der Abgabe dieser Quest?",a="Priesterin Alathea heißt ihren Schüler wieder in Darnassus willkommen und bietet die Stars of Elune an, die mehr über die Wege der Göttin lehren.",al={"heimkehr nächste quest","folgequest von heimkehr"}},{q="Woher weiß Braenna, dass sie nach Euch suchen soll?",a="Eine Priesterin aus dem Tempel des Mondes kam durch Eisenschmiede und suchte Akolythen. Sie hinterließ bei örtlichen Lehrern wie Braenna Anweisungen, umherziehende Nachtelfen nach Hause zu schicken.",al={"warum kennt braenna mich","eisenschmiede priesterin botschaft"}}},fx={cd40b4be={q="Warum möchte Braenna Kieselbruch, dass dies erledigt wird?",a="Braenna hat kein persönliches Interesse an den Angelegenheiten des Tempels; sie überbringt lediglich aus Höflichkeit und Respekt eine dringende Nachricht. Eine Nachtelfenpriesterin kam eigens nach Eisenschmiede, um Euch zu suchen, und bat darum, dass Ihr unverzüglich nach Darnassus zurückkehrt. Da die Angelegenheit dringend klang, versprach Braenna, die Vorladung weiterzuleiten, sobald Ihr in den großen Hallen der Zwerge eintreffet.",al={"warum will braenna dies erledigt haben","braenna kieselbruch motiv","warum zurück nach darnassus"}}},fp="14,214,31.339.0,22.304.0,22.94.0,32.71.0,43.122.0,41.110.0,41.129.0,38.174.0"}
P.entries["quest:5634"] = {n="Verzweifeltes Gebet",s="In Sturmwinds Kathedrale des Lichts lehrt Hohepriesterin Laurena menschliche Akolythen ein Gebet für den Fall, dass ihr Leben in Gefahr ist. Es ruft das Heilige Licht an, die Wunden eines Priesters zu heilen, wenn alles andere versagt.",h="In Sturmwinds Kathedrale des Lichts lehrt Hohepriesterin Laurena menschliche Akolythen ein Gebet für den...",kw={"kathedrale des lichts","kathedralenplatz","verzweifeltes gebet","hohepriesterin laurena","heiliges licht","laurena","priester","sturmwind"},ang={["class:Priest"]="Als Priester werdet Ihr vom Akolythen in der Ausbildung zum tätigen Diener des Heiligen Lichts, bereit, tödliche Prüfungen im Felde zu überstehen.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass Segen wie Verzweifeltes Gebet Heiler an der Front am Leben halten, damit sie Soldaten in gefährlichen Grenzgebieten versorgen können.",["race:Human"]="Als Mensch erhaltet Ihr diese Unterweisung vom Klerus der Kathedrale des Lichts. Sie bekräftigt Sturmwinds Stellung als wichtigster Sitz des menschlichen Glaubens."},sec={{t="Ein Flehen im Dunkeln",b="Priester der Kathedrale des Lichts nutzen ihren Glauben, um Gefährten zu schützen, Wunden zu heilen und das Böse zu bekämpfen. Selbst die Frommen können allein, in die Enge getrieben oder dem Tode nahe sein. In diesem Moment kann ein Akolyth das Heilige Licht um Hilfe anrufen, wenn sein eigenes Leben auf dem Spiel steht."},{t="Der Segen der Kathedrale",b="Hohepriesterin Laurena führt den Klerus auf Sturmwinds Kathedralenplatz und entscheidet, wann ein Akolyth für tiefere Lehren bereit ist. Menschliche Novizen, die im ganzen Königreich Hingabe an das Licht zeigen, erhalten diese Unterweisung als Schutz und als Auftrag, dem Reich weiter zu dienen."}},faq={{q="Welchen Zweck erfüllt Verzweifeltes Gebet?",a="Verzweifeltes Gebet ruft das Heilige Licht an, die lebensgefährlichen Verletzungen eines verwundeten Priesters sofort und ohne langen Gesang zu heilen.",al={"was bewirkt verzweifeltes gebet","warum verzweifeltes gebet","zweck von verzweifeltes gebet"}},{q="Wer erteilt diese Unterweisung in Sturmwind?",a="Hohepriesterin Laurena erteilt diese Unterweisung in der Kathedrale des Lichts auf Sturmwinds Kathedralenplatz. Sie lehrt Akolythen, die in der weiten Welt Hingabe und Erfahrung bewiesen haben.",al={"wer lehrt verzweifeltes gebet","wo verzweifeltes gebet erlernen","hohepriesterin laurena quest"}},{q="Warum erhalten Priester gerade diese Unterweisung?",a="Priester des Heiligen Lichts riskieren ihr Leben, um anderen zu helfen. Dieses Gebet kann das Leben eines Heilers bewahren, wenn er allein oder schwer verletzt ist.",al={"warum erhalten priester verzweifeltes gebet","geschichte hinter verzweifeltes gebet"}},{q="Kann jeder Abenteurer hier Verzweifeltes Gebet erlernen?",a="Nein. Nur Priester, die dem Heiligen Licht ergeben sind und von der Church of the Light geführt werden, erhalten diese Unterweisung.",al={"kann jeder verzweifeltes gebet erlernen","ist diese quest nur für priester"}},{q="Wo findet dieser Ritus statt?",a="Der Ritus findet in der Kathedrale des Lichts im nördlichen Stadtviertel von Sturmwind statt.",al={"verzweifeltes gebet ort","wo ist laurena"}},{q="Ist Verzweifeltes Gebet menschlichen Priestern vorbehalten?",a="Sowohl menschliche als auch zwergische Geistliche in den Ländern der Allianz können Verzweifeltes Gebet erlernen. Ihre Traditionen der Verehrung des Heiligen Lichts sind in Sturmwind und Eisenschmiede eng miteinander verbunden.",al={"erhalten andere völker verzweifeltes gebet","zwerg verzweifeltes gebet"}}},fp="16,199,18.260.0,24.274.0,40.116.0,36.180.0,46.133.0,47.101.0,32.91.0,44.168.0"}
P.entries["quest:5635"] = {n="Verzweifeltes Gebet",s="In Sturmwind vertiefen vielversprechende Priester aus dem Wald von Elwynn ihre Ausbildung in der Kirche des Heiligen Lichts. Nachdem sie ihre Hingabe und Disziplin bewiesen haben, stellen sie sich Hohepriesterin Laurena in der Kathedrale des Lichts vor.",h="In Sturmwind vertiefen vielversprechende Priester aus dem Wald von Elwynn ihre Ausbildung in der Kirche des...",kw={"kathedrale des lichts","verzweifeltes gebet","goldhain","hohepriesterin laurena","heiliges licht","priester","priesterin josetta","sturmwind"},ang={["class:Priest"]="Als Priester wechselt Ihr vom Novizendienst in Goldhain zur Ausbildung unter den führenden Geistlichen der Kathedrale des Lichts.",["faction:Alliance"]="Als Mitglied der Allianz gehört Ihr einer Gemeinschaft an, die unter anderem durch die Kirche des Heiligen Lichts verbunden ist, eine ihrer stärksten kulturellen und moralischen Stützen angesichts drohender Gefahren.",["race:Human"]="Als Mensch, der dem Heiligen Licht folgt, bekräftigt Ihr mit dem Betreten der Kathedrale des Lichts Eure Pflicht gegenüber dem geistlichen Herzen des Königreichs."},sec={{t="Ein Ruf in die Hauptstadt",b="Priesterin Josetta leitet Priesternovizen in Goldhain an, während örtliche Mentoren den abgelegenen Siedlungen des Waldes von Elwynn dienen. Wenn sich ein Jünger in Geist und Tat als fähig erweist, erreicht die Kunde die höhere Priesterschaft in Sturmwind. Eine Vorladung zur Kathedrale des Lichts bedeutet den Übergang zu tieferen Pflichten im Glauben und einer förmlichen Ausbildung im geistlichen Herzen des Königreichs Sturmwind."},{t="Unterweisung durch die Hohepriesterin",b="In der Kathedrale treten Akolythen vor Hohepriesterin Laurena, eine der führenden Persönlichkeiten der Kirche in Sturmwind. Sie wacht über die geistlichen Grundlagen und die praktische Ausbildung der neu erhobenen Priester. Ihre Unterweisung bereitet sie auf die harten Prüfungen der Allianz vor und lehrt die Wunder des Lichts, darunter Verzweifeltes Gebet, ein unter menschlichen Gläubigen bekanntes Flehen um Rettung."}},faq={{q="Welchen Zweck hat die Quest Verzweifeltes Gebet?",a="Verzweifeltes Gebet schickt vielversprechende Priester aus Goldhain zur Kathedrale des Lichts in Sturmwind, wo sie ihre Ausbildung unter Hohepriesterin Laurena fortsetzen.",al={"verzweifeltes gebet quest","was ist die quest verzweifeltes gebet","warum verzweifeltes gebet machen"}},{q="Wer vergibt die Quest Verzweifeltes Gebet?",a="Priesterin Josetta, die Priesterlehrerin im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, überreicht Euch die Vorladung, nachdem Ihr Eure Hingabe bewiesen habt.",al={"wer startet verzweifeltes gebet","verzweifeltes gebet questgeber"}},{q="Wer ist Hohepriesterin Laurena?",a="Hohepriesterin Laurena ist eine der führenden Persönlichkeiten der Kirche des Heiligen Lichts und bildet Akolythen in der Kathedrale des Lichts in Sturmwind aus.",al={"wer ist laurena","hohepriesterin laurena hintergrundgeschichte"}},{q="Wo befindet sich die Kathedrale des Lichts?",a="Die Kathedrale des Lichts steht am Kathedralenplatz im nördlichen Viertel von Sturmwind. Sie ist das geistliche Zentrum des Königreichs für Priester und Paladine.",al={"wo ist die kathedrale des lichts","kathedrale standort sturmwind"}},{q="Warum heißt die Quest Verzweifeltes Gebet?",a="Menschliche Priester erlernen Verzweifeltes Gebet in Sturmwind als Flehen an das Licht um sofortige Rettung, die ihr eigenes Überleben sichert.",al={"warum heißt es verzweifeltes gebet","verzweifeltes gebet namensbedeutung"}},{q="Erhalten auch andere Völker oder Klassen diese Quest?",a="Diese Unterweisung richtet sich an Priester, die aus dem Wald von Elwynn kommen, um in Sturmwind eine höhere Ausbildung zu beginnen.",al={"können zwerge die quest verzweifeltes gebet machen","ist verzweifeltes gebet nur für priester"}}},fx={["24d97f9e"]={q="Warum möchte Priesterin Josetta, dass Ihr die Kathedrale des Lichts besucht?",a="Priesterin Josetta handelt auf Anweisung der Kirchenhierarchie. Ihr habt Eure Hingabe und Eure Fähigkeiten im Feld unter Beweis gestellt und damit die Aufmerksamkeit der kirchlichen Vorgesetzten in Sturmwind auf Euch gezogen. Josettas Rolle ist es, vielversprechende junge Akolythen an eine höhere Betreuung zu verweisen, und sie schickt Euch in die Kathedrale des Lichts, damit Ihr fortgeschritteneren Unterricht in den Wegen des Lichts erhalten könnt.",al={"warum schickt mich josetta","priesterin josetta motiv","warum sturmwind priester besuchen"}}},fp="16,230,24.364.0,32.373.0,50.140.0,37.128.0,30.132.0,40.148.0,40.116.0,41.99.0"}
P.entries["quest:5636"] = {n="Verzweifeltes Gebet",s="In Dolanaar ruft eine Nachricht aus der Heimat menschliche Priester zur weiteren Ausbildung nach Sturmwind zurück. Ein Mitpriester hat Kontinente überquert, um sie zur Kathedrale des Lichts zu rufen.",h="In Dolanaar ruft eine Nachricht aus der Heimat menschliche Priester zur weiteren Ausbildung nach Sturmwind...",kw={"kathedrale des lichts","verzweifeltes gebet","dolanaar","hohepriesterin laurena","laurna morgenglanz","priesterquest","sturmwind","teldrassil"},ang={["class:Priest"]="Als Priester kehrt Ihr auf Stufe zehn zur Kathedrale des Lichts zurück, um die mit Eurem Volk verbundenen Glaubenssegen zu erlernen.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie sich Nachtelfenpriesterinnen mit der Kirchenführung in Sturmwind abstimmen.",["race:NightElf"]="Als Nachtelf verehrt Ihr Elune. Priesterin Laurna Morgenglanz respektiert dennoch auswärtige Anhänger des Heiligen Lichts unter Teldrassils Ästen."},sec={{t="Eine Nachricht aus der Heimat",b="In Dolanaar überbringt Euch Priesterin Laurna Morgenglanz eine Nachricht aus der Heimat. Ein Mitpriester hat Kontinente überquert, um Euch zu finden, und so drängt Laurna Euch, unverzüglich zurückzukehren. Sie gibt Euch Elunes Segen und gute Wünsche für Euren Glauben mit auf den Weg, wenn Ihr Teldrassil verlasst."},{t="Der Ruf nach Sturmwind",b="Euer Weg führt über das große Meer zur Kathedrale des Lichts in Sturmwind. Hohepriesterin Laurena begleitet die Gläubigen der Allianz bei ihrem geistlichen Wachstum. Sie ruft vielversprechende Akolythen zu sich, damit sie ihre Hingabe vertiefen und Verzweifeltes Gebet erlernen, ein Notgebet, das in dunkelster Stunde ein Leben retten kann."}},faq={{q="Wer vergibt die Quest Verzweifeltes Gebet in Teldrassil?",a="Laurna Morgenglanz, die Nachtelfen-Priesterlehrerin in Dolanaar, übermittelt eine Nachricht aus der Heimat. Ein Priester auf Besuch hat eine dringende Nachricht für Euch hinterlassen.",al={"wer vergibt verzweifeltes gebet","verzweifeltes gebet questgeber teldrassil","laurna morgenglanz quest"}},{q="Wohin führt diese Quest?",a="Ihr reist zur Kathedrale des Lichts in Sturmwind, um mit Hohepriesterin Laurena zu sprechen.",al={"wohin gehen","verzweifeltes gebet abgeben","wo ist laurena"}},{q="Warum schickt ein Nachtelf einen Priester nach Sturmwind?",a="Laurna Morgenglanz respektiert den Glauben auswärtiger Priester, die Teldrassil besuchen. Sie übermittelt Nachrichten von religiösen Oberhäuptern aus deren Heimatländern, obwohl Nachtelfenpriester Elune verehren.",al={"warum schickt ein nachtelf mich nach sturmwind","nachtelf heiliges licht"}},{q="Welche Belohnung gibt es für den Abschluss dieser Quest?",a="Ihr erhaltet geistliche Anleitung und könnt bei Hohepriesterin Laurena Verzweifeltes Gebet erlernen, ein augenblicklich wirkendes Heilgebet.",al={"verzweifeltes gebet belohnung","welchen zauber erhalte ich"}},{q="Können Nachtelfenpriester diese bestimmte Quest annehmen?",a="Nein. Nachtelfenpriester beten Elune an und erlernen Starshards. Dieser Ruf richtet sich an menschliche Priester, die auf niedrigen Stufen Kalimdor erkunden.",al={"können nachtelfen verzweifeltes gebet machen","nachtelfenpriester verzweifeltes gebet"}},{q="Wie reist Ihr von Teldrassil zurück nach Sturmwind?",a="Reist durch Darnassus nach Rut'theran und nehmt dann ein Boot nach Auberdine an der Dunkelküste. Geht dort an Bord des Schiffes, das Euch über das Meer zum Hafen von Sturmwind bringt.",al={"wie von dolanaar nach sturmwind kommen","teldrassil nach sturmwind route"}}},fx={["32b36d47"]={q="Warum schickt Euch Laurna Morgenglanz nach Sturmwind?",a="Laurna Morgenglanz verfolgt keine persönlichen Interessen oder geheimen Absichten; sie übermittelt lediglich eine dringende Vorladung. Ein Abgesandter des Heiligen Lichts besuchte Dolanaar auf der Suche nach Euch und wies sie an, dass Hohepriesterin Laurena Eure Anwesenheit in der Kathedrale des Lichts wünscht. Da Laurna erkennt, dass Eure Talente die Aufmerksamkeit Eurer Anführer erregt haben und Euer Volk Euch braucht, drängt sie Euch dazu, nicht länger auf Teldrassil zu verweilen, wenn größere Pflichten Euch nach Hause rufen.",al={"warum nach sturmwind schicken","laurna morgenglanz motiv","warum desperate prayer quest"}},["5980c3c7"]={q="Warum braucht Laurena Euch statt örtlicher Priester in Sturmwind?",a="Ihr seid in Eurer Gemeinschaft mit dem Heiligen Licht weit genug vorangeschritten, um eine individuelle Anleitung durch die höchsten Ältesten der Kirche zu rechtfertigen. Hohepriesterin Laurena sucht nach vielversprechenden Akolythen, die im Feld wahre Hingabe zeigen, und ruft Euch nach Sturmwind zurück, um fortgeschrittenen Unterricht in heiligen Riten wie dem Desperate Prayer zu erhalten. Euer persönliches Wachstum als Gefäß des Lichts ist es, das ihre Aufmerksamkeit erregt.",al={"warum will mich laurena","warum ich desperate prayer","warum vorladung nach sturmwind"}}},fp="16,168,19.257.0,24.306.0,52.138.0,27.92.0,51.186.0,45.122.0,47.127.0,52.154.0"}
P.entries["quest:5637"] = {n="Verzweifeltes Gebet",s="In Sturmwind ruft Hohepriesterin Laurena vielversprechende Zwergenakolythen in die Kathedrale des Lichts. Dort vertiefen sie ihren Dienst am Licht und übernehmen umfassendere Pflichten innerhalb der Allianz.",h="In Sturmwind ruft Hohepriesterin Laurena vielversprechende Zwergenakolythen in die Kathedrale des Lichts.",kw={"kathedrale des lichts","verzweifeltes gebet","dun morogh","kharanos","laurena","maxan anvol","priester","sturmwind"},ang={["class:Priest"]="Als Priester geht Ihr von grundlegenden Pflichten in Eurer Gemeinde zu fortgeschrittenen heiligen Techniken über, die von den Oberhäuptern der Kirche gelehrt werden.",["faction:Alliance"]="Als Mitglied der Allianz teilt Ihr das Licht mit Gläubigen aus Eisenschmiede und Sturmwind, vereint über die Grenzen der Völker hinweg.",["race:Dwarf"]="Als Zwerg stärkt Eure Reise zur Kathedrale von Sturmwind das geistige Band zwischen Eisenschmiede und dem Menschenreich Sturmwind."},sec={{t="Ein Ruf in die Kathedrale",b="Zwergenpriester, die in Dun Morogh ausgebildet wurden, können über die Lehren örtlicher Mentoren wie Maxan Anvol in Kharanos hinauswachsen. Zeigt ein Akolyth vielversprechende Anlagen, schickt Hohepriesterin Laurena eine förmliche Vorladung aus der Kathedrale des Lichts. Ihre Aufmerksamkeit bedeutet, dass der junge Priester für vertiefte Studien und größere Pflichten im Glauben bereit ist."},{t="Bande zwischen Königreichen",b="Eisenschmiede pflegt seine heiligen Traditionen im Mystic Ward, während Sturmwinds Kirche des Heiligen Lichts Menschen und Zwerge gleichermaßen willkommen heißt. Die Reise nach Süden mit der Tiefenbahn führt Zwergenakolythen in die größere Gemeinschaft der Kirche. Die Reise stärkt das geistige Band zwischen den verbündeten Königreichen."}},faq={{q="Warum ruft Hohepriesterin Laurena Zwergenpriester nach Sturmwind?",a="Hohepriesterin Laurena ruft vielversprechende Akolythen zur Fortsetzung ihrer religiösen Unterweisung in die Kathedrale des Lichts. Örtliche Lehrer wie Maxan Anvol schicken sie dorthin, sobald sie die grundlegenden Glaubenssätze beherrschen, damit sie fortgeschrittene Techniken wie Verzweifeltes Gebet erlernen können.",al={"warum ruft laurena mich","warum als priester nach sturmwind","wer ist hohepriesterin laurena"}},{q="Was ist Verzweifeltes Gebet in der Geschichte der Welt?",a="Verzweifeltes Gebet ist ein dringender Hilferuf an das Heilige Licht, den menschliche und zwergische Geistliche praktizieren. Ist ein Priester dem Tode nahe, schließt ein plötzlicher Glaubensruf Wunden und stellt Lebenskraft wieder her.",al={"verzweifeltes gebet hintergrund","was ist verzweifeltes gebet","wie funktioniert verzweifeltes gebet"}},{q="Wo findet diese Quest statt?",a="Ihr beginnt in Kharanos in Dun Morogh, wo Maxan Anvol Euch unterweist. Von dort reist Ihr nach Sturmwind und zur Kathedrale des Lichts am Kathedralenplatz, wo Hohepriesterin Laurena den Vorsitz führt.",al={"questschauplatz","wohin gehen","wo ist laurena"}},{q="Warum sollte ein Zwergenpriester bei einer menschlichen Hohepriesterin lernen?",a="Zwerge und Menschen teilen den Glauben an das Heilige Licht, ein Band, das während des Zweiten Krieges gestärkt wurde. Zwergenpriester dienen oft im Mystic Ward von Eisenschmiede, während Sturmwinds Kathedrale des Lichts Gläubige aus der gesamten Allianz willkommen heißt.",al={"warum menschlicher lehrer für zwerg","zwerg kirche des lichts","eisenschmiede und sturmwind licht"}},{q="Wie sollte ein junger Reisender von Dun Morogh nach Sturmwind gelangen?",a="Reist durch die Tüftlerstadt in Eisenschmiede und nehmt die Tiefenbahn unter den Bergen hindurch zum Zwergendistrikt von Sturmwind.",al={"wie nach sturmwind gelangen","reise nach sturmwind als zwerg","die tiefenbahn"}},{q="Wer ist Maxan Anvol?",a="Maxan Anvol ist ein zwergischer Priesterlehrer in Kharanos, Dun Morogh. Er vermittelt jungen Geistlichen die Grundlagen, bis sie bereit sind, bei hochrangigen Kirchenführern in Sturmwind zu lernen.",al={"maxan anvol hintergrund","wer gab die quest","kharanos priesterlehrer"}}},fx={["9ecbae4a"]={q="Warum schickt Maxan Anvol Euch nach Sturmwind?",a="Maxan Anvol dient als Euer örtlicher Lehrmeister in Kharanos, aber er weiß, wann ein junger Akolyt den bescheidenen Lektionen eines verschneiten Außenpostens entwachsen ist. Ihm ist zu Ohren gekommen, dass Hohepriesterin Laurena höchstpersönlich Euch in die Kathedrale des Lichts gerufen hat. Maxan möchte sicherstellen, dass Ihr Euer Potenzial nicht vergeudet – ob die Vorladung nun ernste Neuigkeiten oder eine große Gelegenheit mit sich bringt, die Vertiefung Eurer Meisterschaft des Lichts erfordert es, von den führenden Köpfen der Kirche in der Hauptstadt der Menschen zu lernen.",al={"warum schickt mich maxan","maxan anvol motiv","warum zur sturmwind priester quest"}},["12c7ba04"]={q="Warum schickt Maxan Anvol Euch, anstatt selbst zu gehen?",a="Die Vorladung ist kein Besorgungsauftrag und keine offizielle diplomatische Depesche; Hohepriesterin Laurena hat Euch ausdrücklich beim Namen gerufen. Maxan glaubt, dass Eure bewiesene Hingabe und Eure Entwicklung die Aufmerksamkeit der Kathedrale auf sich gezogen haben. Außerdem muss Maxan in Kharanos bleiben, um sich um die örtliche zwergische Gemeinde zu kümmern und Anfänger anzuleiten, die ihre ersten Schritte im Glauben machen.",al={"warum ich desperate prayer","warum geht maxan nicht nach sturmwind"}}},fp="16,186,26.310.0,21.294.0,67.260.0,37.181.0,33.195.0,60.234.0,60.119.0,19.177.0"}
P.entries["quest:5638"] = {n="Verzweifeltes Gebet",s="In Sturmwind führt ein Ruf einen jungen Priester vom Park zur Kathedrale des Lichts. Nara Meideros schickt Euch zur weiteren Unterweisung zu Hohepriesterin Laurena.",h="In Sturmwind führt ein Ruf einen jungen Priester vom Park zur Kathedrale des Lichts.",kw={"kathedrale des lichts","verzweifeltes gebet","hohepriesterin laurena","heiliges licht","nara meideros","priesterquest","sturmwind","der park"},ang={["class:Priest"]="Für Euch als Priester markiert dieser Ruf den Eintritt in höhere geistliche Disziplinen und eröffnet den Weg, Verzweifeltes Gebet zu erlernen, eine lebensrettende Anrufung.",["faction:Alliance"]="Als Mitglied der Allianz erkennt Ihr in der Zusammenarbeit zwischen Nara Meideros und dem Kathedralenklerus die stille Verbundenheit zwischen Darnassus und Sturmwinds heiligen Orden.",["race:Human"]="Als Mensch findet Ihr in der Kathedrale des Lichts das wichtigste Heiligtum des menschlichen Glaubens in den südlichen Östlichen Königreichen. Laurenas Unterweisung markiert einen wichtigen geistlichen Schritt."},sec={{t="Ein Wort im Park",b="Im Park von Sturmwind hält Nara Meideros Elune die Treue. Die geistlichen Anführer der Stadt pflegen Verbindungen über ihre Glaubenstraditionen hinweg. Als die Kathedrale einen vielversprechenden Schüler sucht, schickt Nara Euch mit stiller Ermutigung über die Kanäle. Die Botschaft bringt gute Kunde, keinen Grund zur Sorge."},{t="Der Ruf der Kathedrale",b="In der Kathedrale des Lichts am Kathedralenplatz meldet Ihr Euch bei Hohepriesterin Laurena. Als eine der ranghöchsten geistlichen Anführerinnen Sturmwinds führt sie junge Akolythen über ihre ersten Gebete hinaus. Laurena lehrt die heilige Anrufung namens Verzweifeltes Gebet, ein persönliches Flehen um göttlichen Beistand. Dem Tode nahe kann ein Diener des Lichts damit schwere Wunden augenblicklich heilen."}},faq={{q="Wer schickt mich auf diese Quest?",a="Priesterin Nara Meideros, eine Nachtelfenklerikerin im Park von Sturmwind, lässt Euch ausrichten, dass die Führung der Kathedrale nach Euch sucht.",al={"questgeber","wer vergibt verzweifeltes gebet","nara meideros"}},{q="Bei wem muss ich mich in Sturmwind melden?",a="Meldet Euch bei Hohepriesterin Laurena in der Kathedrale des Lichts am Kathedralenplatz von Sturmwind.",al={"wohin gehen","quest abgeben","wer ist laurena"}},{q="Welche Bedeutung hat Verzweifeltes Gebet?",a="Verzweifeltes Gebet ruft göttliche Gnade an, um den Zaubernden in höchster Gefahr augenblicklich zu heilen. Menschen und Zwerge, die dem Heiligen Licht als Kleriker dienen, erlernen es.",al={"was bewirkt verzweifeltes gebet","hintergrund der priesterfähigkeit","zauber verzweifeltes gebet"}},{q="Warum schickt eine Nachtelfe Priester zur Kathedrale der Menschen?",a="Nachtelfenpriesterinnen verehren Elune, während Menschen und Zwerge dem Heiligen Licht folgen. Sturmwinds geistliche Orden pflegen engen Kontakt und gegenseitigen Respekt und geben einander Bescheid, wenn Kleriker der Allianz Unterweisung benötigen.",al={"warum nara meideros","vom park zur kathedrale","nachtelf elune sturmwind"}},{q="Zu welchem Zeitpunkt der Ausbildung erfolgt dieser Ruf?",a="Der Ruf erfolgt etwa im zehnten Kreis der Erfahrung, wenn ein junger Priester im Felddienst genügend Können für anspruchsvollere göttliche Riten bewiesen hat.",al={"welche stufe","wann gibt es verzweifeltes gebet"}},{q="Wo befindet sich die Kathedrale des Lichts?",a="Die Kathedrale des Lichts beherrscht den Kathedralenplatz im Norden Sturmwinds, zwischen dem Zwergendistrikt und dem Park.",al={"standort der kathedrale","wo ist der kathedralenplatz"}}},fx={["8a572a98"]={q="Warum möchte Nara Meideros, dass ich die Kathedrale des Lichts besuche?",a="Nara Meideros hat kein persönliches Interesse oder Groll; sie tut lediglich einem Priesterkollegen Eures Ordens einen Gefallen. Ein Priester besuchte den Park auf der Suche nach Euch und bat Nara, die Nachricht zu überbringen, sobald sich unsere Wege kreuzen würden. Da ihr das fröhliche und optimistische Auftreten des Boten auffiel, gibt sie die Vorladung mit dem beruhigenden Gedanken weiter, dass gute Nachrichten und wichtige Fortschritte unter der Anleitung von Hohepriesterin Laurena auf Euch warten.",al={"warum schickt mich nara","nara meideros motiv","warum kathedrale des lichts besuchen"}},e569a4a2={q="Warum ruft mich Hohepriesterin Laurena persönlich?",a="Als angehender Priester des Heiligen Lichts, der sich auf seinen ersten Abenteuern bewährt hat, erkennt Eure Mentorin, dass Eure spirituelle Einstimmung gereift ist. Laurena benötigt Eure persönliche Anwesenheit, da die tieferen Geheimnisse und Verantwortungen des Priestertums nicht delegiert oder durch Vermittler gelehrt werden können. Sie hat grundlegende, direkte Lektionen in Eurem Glauben vorbereitet, die Eure heiligen Gaben erweitern und Euch die Meisterschaft verleihen werden, die erforderlich ist, um Eure Verbündeten zu schützen.",al={"warum ich desperate prayer","warum will mich laurena","warum vorladung kathedrale"}}},fp="16,162,18.281.0,25.364.0,27.118.0,40.97.0,45.150.0,60.204.0,50.138.0,40.120.0"}
P.entries["quest:5639"] = {n="Verzweifeltes Gebet",s="Hohepriester Rohan schickt Euch von Eisenschmiede nach Sturmwind, um Heilung und Überleben zu erlernen. Dort lehrt Hohepriesterin Laurena zwergische Akolythen die tieferen Mysterien der Kirche.",h="Hohepriester Rohan schickt Euch von Eisenschmiede nach Sturmwind, um Heilung und Überleben zu erlernen.",kw={"kathedrale des lichts","verzweifeltes gebet","eisenschmiede","laurena","mystic ward","priester","rohan","sturmwind"},ang={["class:Priest"]="Als Priester verlasst Ihr die örtliche Ausbildung in Eisenschmiede und tretet in die übergeordnete Hierarchie der Kirche des Heiligen Lichts ein.",["faction:Alliance"]="Als Mitglied der Allianz erkennt Ihr die geistliche Verbundenheit zwischen Eisenschmiede und Sturmwind daran, wie ihre Priesterschaften gemeinsam ausbilden und zusammenarbeiten.",["race:Dwarf"]="Als junger Zwerg aus Khaz Modan gewährt Euch die Reise nach Sturmwind einen frühen Einblick in menschliche Kultur, prächtige Architektur und gemeinsame geistliche Hingabe."},sec={{t="Ein Ruf nach Sturmwind",b="In Eisenschmiedes Mystic Ward leitet Rohan zwergische Initianden an, die sich dem Heiligen Licht verschrieben haben. Angesichts Eurer Disziplin und Eures Glaubens schickt er Euch nach Südwesten nach Sturmwind. Menschliche und zwergische Kleriker pflegen enge geistliche Bande, und die prächtigen Hallen der Stadt bieten weiterführenden Unterricht."},{t="Die Kathedrale des Lichts",b="Ihr erreicht Sturmwind mit der Tiefenbahn und steigt zum Kathedralenplatz hinauf. In der Kathedrale des Lichts prüft Euch Hohepriesterin Laurena im Namen der Kirche. Sie lehrt die verzweifelten Gebete, mit denen ein Priester im Kampf um göttlichen Beistand fleht, wenn die Kraft schwindet und der Tod naht."}},faq={{q="Wer schickt mich auf diese Quest?",a="Hohepriester Rohan schickt Euch. Er führt die zwergische Geistlichkeit in der Hall of Mysteries in Eisenschmiedes Mystic Ward.",al={"wer vergibt die quest","questgeber","rohans standort"}},{q="Wohin muss ich gehen, um diese Quest abzuschließen?",a="Begebt Euch zur Kathedrale des Lichts im Herzen des Kathedralenplatzes in Sturmwind. Hohepriesterin Laurena wartet im Hauptheiligtum.",al={"wo ist laurena","wo abgeben","abgabe in sturmwind"}},{q="Wie komme ich am besten von Eisenschmiede nach Sturmwind?",a="Nehmt die von den Gnomen erbaute Tiefenbahn vom Osten Eisenschmiedes zum Zwergendistrikt von Sturmwind.",al={"wie nach sturmwind gelangen","reise nach sturmwind","standort der tiefenbahn"}},{q="Warum muss ein zwergischer Priester zur Ausbildung in eine Menschenstadt reisen?",a="Die Kirche des Heiligen Lichts wurzelt in der Tradition der Menschen, und die Kathedrale des Lichts ist ihre wichtigste Lehrstätte. Die zwergische und die menschliche Priesterschaft arbeiten zusammen und teilen Lehren und Traditionen in der gesamten Allianz.",al={"warum sturmwind","zwerg mensch kirche","warum laurena"}},{q="Welche Fähigkeit schaltet diese Ausbildung frei?",a="Mit dieser Ausbildung beginnt Euer Studium des Verzweifelten Gebets. Es ist ein sofortiges Flehen um Selbsterhaltung, das die Gesundheit eines Priesters in höchster Gefahr rasch wiederherstellt.",al={"questbelohnung","welchen zauber erhält man","fähigkeit verzweifeltes gebet"}},{q="Gibt es bei dieser Quest Kämpfe?",a="Es sind keine Kämpfe erforderlich. Ihr reist als Gesandter sicher von Eisenschmiede nach Sturmwind und stellt Euch Hohepriesterin Laurena vor.",al={"gibt es kämpfe","questkämpfe","reisequest"}}},fx={c0c688ec={q="Warum schickt Euch Hohepriester Rohan nach Sturmwind?",a="Hohepriesterin Laurena in Sturmwind hat angefragt, dass Ihr kommt, da sie Euch für bereit hält, Euren Wert für die nächste Stufe Eurer heiligen Ausbildung zu beweisen. Rohan ehrt diesen Ruf der Kathedrale des Lichts und vertraut darauf, dass Eure Ausbildung unter Laurena Eure Hingabe stärken und Eure Befehlsgewalt über die Segnungen des Lichts vertiefen wird.",al={"warum schickt mich rohan","warum zum sturmwind priester","rohan motiv desperate prayer"}}},fp="16,177,22.261.0,22.280.0,27.110.0,39.134.0,56.99.0,52.215.0,39.152.0,31.131.0"}
P.entries["quest:564"] = {n="Teure Bedrohung",s="In Süderstade fürchtet Darren Malvew die Berglöwen, die aus Alterac herabkommen. Untote, die Syndikatsbande und andere Schurken haben die Stadt Pferde gekostet, doch die Löwen bereiten ihm die größte Sorge.",h="In Süderstade fürchtet Darren Malvew die Berglöwen, die aus Alterac herabkommen.",kw={"alteracgebirge","teure bedrohung","darren malvew","vorgebirge des hügellands","pferde","bulliger berglöwe","berglöwe","süderstade"},sec={{t="Verlorene Pferde",b="Darren Malvew lebt in Süderstade und hasst es, mitanzusehen, wie die Stadt ihre prächtigen Pferde verliert. Untote, die Syndikatsbande und andere Schurken in der Gegend haben bereits etliche geraubt. Doch am meisten fürchtet Darren die Berglöwen von Alterac. Sie kommen immer wieder aus den Hügeln herab."},{t="Löwen der Hügel",b="Darren möchte, dass acht Berglöwen und zehn bullige Berglöwen erledigt werden. Die Berglöwen streifen durch die tiefer gelegenen Hügel des Alteracgebirges."}},faq={{q="Wer ist Darren Malvew?",a="Darren Malvew lebt in Süderstade im Vorgebirge des Hügellands und hat es satt, dass die Stadt ihre Pferde verliert.",al={"darren malvew","wer vergibt teure bedrohung","darren malvew süderstade pferde"}},{q="Woher kommen die Berglöwen?",a="Die Berglöwen kommen aus den Hügeln von Alterac herab. Berglöwen streifen durch die tiefer gelegenen Hügel des Alteracgebirges.",al={"berglöwen fundort","wo sind berglöwen","wo löwen finden"}},{q="Welche Bedrohungen für die Pferde erwähnt Darren?",a="Untote, die Syndikatsbande und andere Schurken in der Gegend haben Süderstade Pferde gekostet. Darren sagt, die Berglöwen von Alterac seien die größte Bedrohung.",al={"süderstade bedrohungen","was greift süderstades pferde an","darren malvew feinde"}},{q="Welche Tiere müssen genau getötet werden?",a="Acht Berglöwen und zehn bullige Berglöwen, wie Darren es verlangt.",al={"welche löwen töten","bulliger berglöwe teure bedrohung","teure bedrohung ziele"}}},fp="13,186,11.272.0,18.142.0,21.100.0,41.117.0,47.158.0,39.68.0"}
P.entries["quest:5640"] = {n="Verzweifeltes Gebet",s="In Darnassus suchen junge menschliche und zwergische Priester Rat bei einem anderen Glauben. Priesterin Alathea lehrt die Wege Elunes und schickt Anhänger des Heiligen Lichts nach Sturmwind, wo Hohepriesterin Laurena heimkehrende Akolythen in der Kathedrale des Lichts willkommen heißt.",h="In Darnassus suchen junge menschliche und zwergische Priester Rat bei einem anderen Glauben.",kw={"alathea","kathedrale des lichts","darnassus","verzweifeltes gebet","elune","heiliges licht","laurena","sturmwind"},ang={["class:Priest"]="Als Priester seht Ihr, wie sich die heilige Magie der Allianz zwischen der Verehrung Elunes und der Hingabe an das Heilige Licht aufteilt.",["race:Dwarf"]="Als zwergischer Priester seid Ihr eng mit Sturmwinds Kathedrale verbunden und erlernt hohe Riten an der Seite Eurer menschlichen Glaubensbrüder.",["race:Human"]="Als menschlicher Priester fern der Heimat werdet Ihr daran erinnert, dass Eure geistige Heimat und Eure Ausbildung in Sturmwinds Kathedrale des Lichts auf Euch warten.",["race:NightElf"]="Als Nachtelf begegnet Ihr fremden Glaubensrichtungen mit Höflichkeit, während Ihr allein Mother Moon ergeben bleibt."},sec={{t="Zwei Pfade des Glaubens",b="Die Priester der Allianz folgen unterschiedlichen heiligen Pfaden. In Darnassus dient die Priesterschaft Elune und kanalisiert das Strahlen und den Zorn der Mondgöttin. Priesterin Alathea ehrt Elune und respektiert das Heilige Licht. Doch sie kann Angehörigen eines anderen Volkes nicht die tieferen Gebete lehren, die an eine andere Glaubenshingabe gebunden sind. Menschliche und zwergische Akolythen, die diese Gebete erlernen wollen, müssen sich anderswo umsehen."},{t="Rückkehr zur Kathedrale",b="Initianden des Heiligen Lichts kehren heim, um seine Riten zu erlernen, darunter das Gebet um göttlichen Beistand in einem Augenblick der Gefahr. In Sturmwinds Kathedrale des Lichts unterweist Hohepriesterin Laurena heimkehrende Priester unter ihren Marmorbögen."}},faq={{q="Warum schickt mich ein Priester aus Darnassus nach Sturmwind?",a="Priesterin Alathea lehrt die Wege Elunes. Sie respektiert das Heilige Licht, kann Menschen und Zwerge jedoch nicht seine Gebete lehren. Sie suchen Rat bei Hohepriesterin Laurena in Sturmwind.",al={"warum nach sturmwind gehen","warum alathea mich fortschickt","priesterquest darnassus nach sturmwind"}},{q="Wer ist Priesterin Alathea?",a="Priesterin Alathea ist eine nachtelfische Priesterin im Tempel des Mondes in Darnassus. Sie unterweist angehende Anhänger Elunes und bietet zu Besuch weilenden Priestern anderer Glaubensrichtungen respektvollen Rat.",al={"alathea hintergrundgeschichte","wer ist alathea"}},{q="Wer ist Hohepriesterin Laurena?",a="Hohepriesterin Laurena ist eine menschliche geistliche Anführerin in Sturmwinds Kathedrale des Lichts. Sie unterweist Diener des Heiligen Lichts in fortgeschrittenen Gebeten und ihren Pflichten.",al={"wer ist laurena","hohepriesterin laurena sturmwind"}},{q="Was ist Verzweifeltes Gebet in der Hintergrundgeschichte?",a="Verzweifeltes Gebet ruft göttlichen Beistand herbei, wenn ein Priester dem Tode nahe ist oder in Lebensgefahr schwebt. Es ist eine Anrufung des Heiligen Lichts, die sofortige Heilung bringen kann.",al={"was ist verzweifeltes gebet","verzweifeltes gebet fähigkeit hintergrundgeschichte"}},{q="Können Nachtelfen das Heilige Licht lehren?",a="Nein. Nachtelfen verehren fast ausschließlich Elune und kanalisieren ihre Mondkraft. Sie respektieren das Heilige Licht, predigen es jedoch nicht und lehren auch nicht seine Gebete. Diese gehören den menschlichen und zwergischen Priestern.",al={"kennen nachtelfen das licht","elune gegen heiliges licht"}},{q="Wo kann ich Hohepriesterin Laurena finden?",a="Hohepriesterin Laurena hält sich auf dem Kathedralenplatz in Sturmwind auf, im Inneren der Kathedrale des Lichts. Dort ist sie unter Geistlichen und Paladinen der Silver Hand.",al={"laurena aufenthaltsort","wo ist laurena"}}},fx={["6bd09142"]={q="Warum möchte Priesterin Alathea, dass ich Hohepriesterin Laurena aufsuche?",a="Priesterin Alathea erkennt, dass beide Eurer Orden zwar durch den Glauben gebunden sind, Nachtelfenpriesterinnen ihre Macht jedoch direkt von Elune beziehen, während Ihr den Pfad des Heiligen Lichts beschreitet. Sie weiß, dass ihre eigenen Lehren im The Temple of the Moon Euch nur bis zu einem gewissen Punkt bringen können. Aus Respekt vor Euren unterschiedlichen Traditionen verweist sie Euch an Eure eigenen geistlichen Führer in Sturmwind, damit Ihr die heiligen Künste Eures Glaubens richtig meistern könnt.",al={"warum schickt mich alathea weg","alathea motiv","warum zu laurena"}}},fp="16,259,18.356.0,23.227.0,49.186.0,25.185.0,30.174.0,37.161.0,37.191.0,40.159.0"}
P.entries["quest:5643"] = {n="Schattenwache",s="In Unterstadt schickt Aelthalyste einen Dunkelspeerpriester über das große Meer nach Orgrimmar. Sie hat gesehen, dass der junge Troll für die heiligen Riten des Stammes bereit ist, und Ur'kyo wartet im Tal der Geister.",h="In Unterstadt schickt Aelthalyste einen Dunkelspeerpriester über das große Meer nach Orgrimmar.",kw={"aelthalyste","orgrimmar","übergangsritus","shadowguard","trollpriester","unterstadt","ur'kyo","tal der geister"},ang={["class:Priest"]="Als Priester erreicht Ihr einen Meilenstein, der die ersten Lehren der heiligen Magie und der Schattenmagie mit den Traditionen Eures Volkes verbindet.",["race:Troll"]="Als Dunkelspeertroll verbindet Eure Priesterausbildung die Zwiesprache mit den Loa mit der Verteidigung Eures Stammes. Ur'kyo bewahrt dieses Erbe im Tal der Geister.",["race:Undead"]="Als Untoter könnt Ihr sehen, wie Aelthalyste die eigenständigen Traditionen ihrer lebenden Verbündeten achtet. Besuchende Trolle erhalten Unterweisung von ihren eigenen Ältesten statt in der Glaubenslehre der Verlassenen."},sec={{t="Ein Ruf über Kontinente",b="In Unterstadt beobachtet Aelthalyste die Trollpriester, die zum Lernen kommen. Wenn ein Initiand stark genug für die Prüfungen des Stammes ist, schickt sie ihn über das große Meer zu seinen eigenen Ältesten. Sie zwingt ihnen die Lehren der Verlassenen nicht auf. Ihr Glaube folgt den Traditionen ihres Volkes."},{t="Das Tal der Geister",b="Im Tal der Geister in Orgrimmar kümmert sich Ur'kyo um die spirituellen Bedürfnisse und uralten Riten des Dunkelspeer-Stammes. Er heißt den zurückkehrenden Initianden willkommen und bereitet ihn auf einen Übergangsritus vor. Der Ritus vertieft die Bindung des Priesters an die Loa und nutzt Zauber, um Schaden abzuwehren."}},faq={{q="Wer beginnt diese Quest?",a="Aelthalyste, eine Priesterlehrerin im Kriegsviertel von Unterstadt, lässt den Ruf ergehen. Sie weiß, wann ein Trollpriester für die spirituellen Prüfungen des Stammes bereit ist.",al={"questgeber","wo beginnt die quest","wer vergibt shadowguard"}},{q="Warum schickt mich eine Lehrerin aus Unterstadt nach Orgrimmar?",a="Die Priester der Verlassenen haben sich dem Schatten zugewandt, während Dunkelspeertrolle spirituelle Kraft aus den Loa und den Traditionen ihres Stammes schöpfen. Aelthalyste achtet diesen Unterschied und schickt junge Trollpriester nach Hause, damit sie die Künste ihres Volkes von ihrem eigenen Ältesten lernen.",al={"warum nach orgrimmar","von unterstadt nach orgrimmar","warum ur'kyo"}},{q="Wer ist Ur'kyo?",a="Ur'kyo ist ein Priesterlehrer der Dunkelspeertrolle im Tal der Geister in Orgrimmar. Er lehrt die spirituellen Bräuche und Übergangsriten der Trolle.",al={"ur'kyos geschichte","wer ist urkyo","priesterlehrer ur'kyo"}},{q="Welche Bedeutung hat die Fähigkeit Shadowguard?",a="Shadowguard ist ein Schutzzauber, der allein Trollpriestern vorbehalten ist. Schattenhafte Geister und der Segen der Loa umkreisen den Zaubernden und treffen jeden Feind, der angreift.",al={"was ist shadowguard","geschichte des zaubers shadowguard","warum ist das wichtig"}},{q="Erhalten andere Völker diese Quest?",a="Der Ruf gilt Priestern der Dunkelspeertrolle, die Unterstadt etwa in ihrer zwanzigsten Jahreszeit der Erfahrung besuchen. Die Priester der Verlassenen haben dort ihre eigenen Riten und ihre eigene Ausbildung.",al={"können untote diese quest machen","nur für trolle","volksspezifische priesterquest"}},{q="Wo in Orgrimmar befindet sich Ur'kyo?",a="Ur'kyo befindet sich im Tal der Geister, dem südlichen Viertel Orgrimmars, das den Dunkelspeertrollen und ihren mystischen Praktiken vorbehalten ist.",al={"wo ist ur'kyo","urkyos standort","ur'kyo finden"}}},fx={b54fa89c={q="Warum möchte Aelthalyste, dass Ihr nach Orgrimmar zurückkehrt?",a="Aelthalyste erkennt, dass die Spiritualität der Trolle Traditionen erfordert, die sich von der dunklen Disziplin der Verlassenen unterscheiden. Sie spürt, dass Ihr einen kritischen Punkt in Eurem spirituellen Wachstum erreicht habt, an dem Ihr die alten Initiationsriten Eures eigenen Stammes durchlaufen müsst. Anstatt Euch in der Unterstadt festzuhalten, weist sie Euch an, zu den spirituellen Führern Eures Volkes zurückzukehren, damit Ihr wichtige defensive Gaben freischalten könnt, die für Euer Überleben unerlässlich sind.",al={"warum zu ur'kyo schicken","aelthalystes beweggrund","zweck der shadowguard"}},bb765c88={q="Warum schickt Aelthalyste Euch und nicht jemand anderen?",a="Dieser Initiationsritus ist zutiefst persönlich für Eure Entwicklung als Trollpriester. Kein Bote oder Champion kann an Eurer Stelle spirituelle Prüfungen ablegen. Aelthalyste spürt, dass die Zeit speziell für Eure Entwicklung gekommen ist, was bedeutet, dass nur Ihr vor Ur'kyo stehen könnt, um die heiligen Lehren Eures Glaubens zu empfangen.",al={"warum ich shadowguard","warum wählt aelthalyste mich aus"}}},fp="11,205,27.295.0,21.270.0,22.157.0,51.246.0,14.135.0,52.143.0,34.168.0,37.132.0"}
P.entries["quest:5644"] = {n="Verschlingende Seuche",s="Jenseits des Meeres von Lordaeron erwartet die Verschlingende Seuche Priester der Verlassenen, die bereit sind, ihre dunkle Kunst zu erlernen. Miles Welsch in Donnerfels schickt den Adepten zu Aelthalyste in den Ruinen von Lordaeron, um diese charakteristische Form von Shadow Magic zu erlernen.",h="Jenseits des Meeres von Lordaeron erwartet die Verschlingende Seuche Priester der Verlassenen, die bereit...",kw={"aelthalyste","verschlingende seuche","verlassene","miles welsch","schattenpriester","donnerfels","unterstadt","kriegsviertel"},ang={["class:Priest"]="Als Priester der Verlassenen erreicht Ihr einen wichtigen Meilenstein Eurer Ausbildung. Ihr lasst die grundlegenden Lehren hinter Euch und erlernt die furchterregenden Schattentraditionen, die nur die Untoten kennen.",["faction:Horde"]="Als Mitglied der Horde verbinden Euch spirituelle und praktische Bande mit fernen Außenposten in Mulgore, die bis zur Unterstadt zurückreichen.",["race:Undead"]="Als Verlassener verschreibt Ihr Euch schweren Leiden und Shadow Magic wie der Verschlingenden Seuche, anders als dem Licht, das Ihr zu Lebzeiten wirktet."},sec={{t="Ein Ruf in die Heimat",b="In Donnerfels bildet Miles Welsch unter den Tauren Priester der Verlassenen aus. Er wacht über ihre göttlichen und schattenhaften Studien und weiß, wann ein Akolyth für höhere Mysterien bereit ist. Statt diese Geheimnisse selbst in Kalimdor zu lehren, schickt Miles die Würdigen zurück zu den Ruinen von Lordaeron."},{t="Die Geheimnisse von Aelthalyste",b="Aelthalyste wartet unter den Stadtruinen im Kriegsviertel der Unterstadt. Sie ist eine der bedeutendsten Mentorinnen der Priesterschaft der Verlassenen und leitet Akolythen an, die Schatten weben. Die Verschlingende Seuche zehrt ihr Opfer aus und birgt eine verderbliche Macht. Aelthalyste lehrt sie nur jene, die diese Macht führen können, ohne ihr zu erliegen."}},faq={{q="Wer schickt Euch auf diese Quest?",a="Miles Welsch schickt Euch von den Teichen der Visionen unterhalb der Anhöhe der Geister in Donnerfels los, sobald Eure Fähigkeiten weit genug entwickelt sind. Er ist ein Priesterlehrer der Verlassenen, der unter den Tauren stationiert ist.",al={"wer startet die quest verschlingende seuche","questgeber verschlingende seuche","miles welsch rolle"}},{q="Wo befindet sich Aelthalyste?",a="Aelthalyste befindet sich im Kriegsviertel der Unterstadt, zwischen den Übungsringen und dunklen Energieleitungen, wo sich die Priester der Verlassenen versammeln.",al={"aelthalyste standort","wo ist aelthalyste","verschlingende seuche abgeben"}},{q="Warum kann Miles Welsch den Zauber nicht selbst lehren?",a="Jeder Priester lernt die Verschlingende Seuche auf Stufe zwanzig bei einem Priesterlehrer. Miles achtet die Rangordnung der Priesterschaft der Verlassenen, indem er würdige Adepten heim in die Unterstadt schickt, wo Aelthalyste sie prüfen kann.",al={"warum zur unterstadt reisen","warum aelthalyste aufsuchen","unterstadt priesterlehrer"}},{q="Was ist die Verschlingende Seuche aus Sicht der Geschichte?",a="Die Verschlingende Seuche ist ein verheerender Fluch, den Priester der Verlassenen wirken. Ihre ansteckende Magie verzehrt die Lebenskraft eines Opfers und stärkt den Zaubernden.",al={"was ist verschlingende seuche","geschichte der verschlingenden seuche","verlassene krankheitszauber"}},{q="Ist diese Quest auch für andere Völker verfügbar?",a="Nein. Dieser Ruf gilt Priestern der Verlassenen, obwohl Priester aller Völker die Verschlingende Seuche auf Stufe zwanzig bei einem Priesterlehrer lernen.",al={"können trolle die quest verschlingende seuche machen","können orcs verschlingende seuche machen","ist diese quest nur für untote"}},{q="Warum ist überhaupt ein Lehrer der Verlassenen in Donnerfels?",a="Nachdem die Verlassenen der Horde beigetreten waren, tauschten deren Hauptstädte Diplomaten und Mentoren aus. Miles Welsch vertritt die spirituellen Traditionen der Unterstadt und leitet Verlassene an, die durch Kalimdor reisen.",al={"warum sind untote in donnerfels","verlassene in donnerfels geschichte","miles welsch donnerfels"}}},fx={["988f0d1b"]={q="Warum muss Miles Welsch Euch schicken, anstatt die Nachricht selbst zu überbringen?",a="Miles Welsch dient als Gesandter und Mentor für Besucher der Verlassenen auf den hohen Plateaus von Donnerfels; sein Posten erfordert, dass er auf dem Plateau bleibt, um sein Volk zu unterweisen und zu vertreten. Noch wichtiger ist, dass die Reise Eurem persönlichen Aufstieg dient. Die Hohepriesterin in der Unterstadt erfordert es, dass Ihr persönlich erscheint, damit sie Euer spirituelles Wachstum aus erster Hand beurteilen kann, bevor sie ihre tödlichen Lehren teilt.",al={"warum ich","warum mich schicken","warum braucht mich miles"}},ec2983f6={q="Warum schickt Miles Welsch Euch nach Unterstadt?",a="Miles Welsch erkennt, dass Euer Verständnis der Priesterschaft über das hinausgewachsen ist, was eine einfache Unterweisung in der Fremde bieten kann. Als Vertreter, der unter den Tauren stationiert ist, besteht seine Pflicht darin zu erkennen, wann ein vielversprechender Priester der Verlassenen für tiefere Mysterien bereit ist. Anstatt Euch zurückzuhalten, schickt er Euch nach Hause zu Aelthalyste, damit Ihr in die dunkleren Lehren der Priesterschaft der Verlassenen eingeweiht werden könnt.",al={"warum will miles welsch das getan haben","miles welsch motiv","warum nach unterstadt gehen"}}},fp="16,219,14.281.0,26.319.0,28.186.0,29.120.0,46.201.0,49.143.0,39.128.0,62.190.0"}
P.entries["quest:5645"] = {n="Furchtlos",s="In Eisenschmiede prüft Hohepriester Rohan vielversprechende zwergische Schüler. Im Mystic Ward unterweist er sie, während ihre geistige Stärke wächst.",h="In Eisenschmiede prüft Hohepriester Rohan vielversprechende zwergische Schüler.",kw={"alathea","fear ward","hall of mysteries","eisenschmiede","laurena","mystic ward","priester","rohan"},ang={["class:Priest"]="Für Euch als Priester markiert dieser Ruf Eure Reife innerhalb der Priesterschaft. Ihr könnt heilige Techniken erlernen, die von den standhaften Geistlichen Eisenschmiedes verfeinert wurden.",["faction:Alliance"]="Als Priester der Allianz lernt Ihr gemeinsam mit Geistlichen aus anderen Hauptstädten. Die Priesterschaften der Allianz schicken Akolythen über Grenzen hinweg, um von Meistern in Eisenschmiede zu lernen.",["race:Dwarf"]="Als Zwerg ehrt Ihr mit Eurer Rückkehr zu Rohan den Glauben, die körperliche Standhaftigkeit und die Zähigkeit im Kampf Eures Volkes im Dienste des Heiligen Lichts."},sec={{t="Ein Ruf nach Eisenschmiede",b="Örtliche Mentoren schicken Priester, die der Allianz in der Ferne dienen, zu hochrangigen Geistlichen ihres Ordens. Für zwergische Schüler führt dieser Ruf Euch zu Hohepriester Rohan im Mystic Ward von Eisenschmiede. Dort weichen grundlegende geistliche Übungen tieferen Anwendungen heiliger Magie, die in Prüfungen erprobt werden."},{t="Die Prüfungen der Standhaftigkeit",b="Die zwergische Tradition lehrt, dass das Licht in körperlichen Auseinandersetzungen als Schild dient. Wenn Ihr Euch bei Hohepriester Rohan meldet, zeigt Ihr, dass Ihr Prüfungen in der weiten Welt bestanden habt. Nun müsst Ihr Euren Mut beweisen und die Furcht an vorderster Front bezwingen."}},faq={{q="Welchen Zweck hat diese Quest?",a="Örtliche Priesterlehrer schicken erfahrene Novizen zu Hohepriester Rohan nach Eisenschmiede, damit sie weiterführende Unterweisung und die geistlichen Gaben erhalten, die die Priesterschaft der Stadt lehrt.",al={"warum zu rohan gehen","was bewirkt furchtlos","priesterquest stufe zwanzig eisenschmiede"}},{q="Wer ist Hohepriester Rohan?",a="Hohepriester Rohan führt die zwergische Priesterschaft in Eisenschmiede an. In der Hall of Mysteries im Mystic Ward lehrt er seine Schüler unerschütterliche Hingabe und Widerstandskraft im Kampf.",al={"wer ist rohan","hohepriester rohan hintergrundgeschichte"}},{q="Wo ist Hohepriester Rohan zu finden?",a="Hohepriester Rohan ist in der Hall of Mysteries zu finden, im Mystic Ward in den westlichen Vierteln von Eisenschmiede.",al={"wo ist rohan","rohan standort","hohepriester rohan finden"}},{q="Warum heißt diese Quest „Furchtlos“?",a="Der Name verweist auf Fear Ward, den Schutz des Heiligen Lichts vor Panik und übernatürlichem Schrecken. Jeder Priester, gleich welchen Volkes, erlernt diesen Zauber auf Stufe zwanzig bei einem Priesterlehrer.",al={"bedeutung von furchtlos","fear ward quest"}},{q="Wer schickt den Priester nach Eisenschmiede?",a="Örtliche Lehrer schicken Novizen nach Eisenschmiede. Hohepriesterin Laurena in Sturmwind und Priesterin Alathea in Darnassus weisen Schüler an, ihr Erbe zu ehren oder bei Rohan zu lernen.",al={"wer startet furchtlos","questgeber für furchtlos"}},{q="Gehören Kämpfe zu dieser Quest?",a="Nein. Ihr reist nach Eisenschmiede und sprecht mit Hohepriester Rohan.",al={"kämpfen erforderlich","gibt es kämpfe in furchtlos"}}},fx={["54793667"]={q="Warum werdet Ihr zu Hohepriester Rohan gerufen?",a="Priesterausbilder in anderen Städten erkennen, dass Euer Glaube und Eure Kampfstärke erheblich gewachsen sind. Hohepriester Rohan in Eisenschmiede überwacht die Ausbildung der Priester der Allianz in der Region, insbesondere die einzigartigen Disziplinen und Riten der Zwerge. Er hat Euch gerufen, weil Ihr bewiesen habt, dass Ihr bereit seid, Eure nächste Prüfung zu bestehen und fortgeschrittenere heilige Lehren zu erlernen.",al={"warum rohan sehen","a lack of fear motiv","warum nach eisenschmiede schicken"}}},fp="14,137,22.278.0,23.237.0,34.161.0,25.169.0,37.108.0,36.168.0,34.175.0,31.61.0"}
P.entries["quest:5646"] = {n="Verschlingende Seuche",s="In Orgrimmar schickt Ur'kyo Priester der Verlassenen heim, um Verschlingende Seuche zu erlernen. Sie kamen nach Kalimdor, um von den Dunkelspeeren zu lernen, doch Aelthalyste wartet in Unterstadt, um sie die Schattenkünste ihres Volkes zu lehren.",h="In Orgrimmar schickt Ur'kyo Priester der Verlassenen heim, um Verschlingende Seuche zu erlernen.",kw={"aelthalyste","verschlingende seuche","priester der verlassenen","orgrimmar","schattenpriester","unterstadt","ur'kyo","kriegsviertel"},ang={["class:Priest"]="Als Priester schöpft Ihr aus den Lehren der Verlassenen über Schatten und Verfall. Ihr lenkt körperliche Qual in dunkle Riten wie Touch of Weakness und Dark Sacrifice.",["faction:Horde"]="Als Mitglied der Horde teilt Ihr die Ausbildungsaufgaben zwischen Ur'kyo in Durotar und Aelthalyste in Tirisfal. Ihre Arbeit zeugt von Zusammenarbeit und gegenseitigem Respekt zwischen den weit voneinander entfernten Hauptstädten.",["race:Undead"]="Als Verlassener erinnert Euch die Rückkehr ins Kriegsviertel von Unterstadt daran, dass Eure Treue und Eure spirituellen Wurzeln unter den Ruinen von Lordaeron liegen. Das gilt, wohin Euch Eure Pflichten für die Horde auch führen."},sec={{t="Ein Austausch des Glaubens",b="Ur'kyo leitet jene an, die sich in Orgrimmar zu spiritueller Macht hingezogen fühlen. Dunkelspeertrolle und Verlassene verbindet in Glaubensfragen ein ungewöhnliches Band, während Orcs und Tauren wenig Neigung zur priesterlichen Verehrung zeigen. Ur'kyo weiß, dass Initianden der Verlassenen die Schattenkünste meistern müssen, die mit ihrem eigenen Zustand verbunden sind. Aus Respekt zwischen ihren Völkern schickt er umherziehende Verlassene zurück nach Lordaeron, um ihre Ausbildung abzuschließen."},{t="Das Kriegsviertel von Unterstadt",b="Unter den Ruinen von Lordaeron kümmert sich Priesterin Aelthalyste im Kriegsviertel von Unterstadt um ihre Herde. Priester der Verlassenen folgen einem einsamen, beschwerlichen Pfad, geprägt von ihrer Hinwendung zum Schatten. Sie ertragen die schmerzhafte Berührung des Heiligen Lichts und lernen, das verheerende Leiden der Shadow Magic zu entfesseln.\n\nWenn ein Initiand genügend Können erlangt, ruft Aelthalyste ihn zu sich. Dort lehrt sie ihn das Leiden, das ihresgleichen Verschlingende Seuche nennt."}},faq={{q="Wer schickt mich auf diese Quest?",a="Ur'kyo, der Priesterlehrer der Trolle unter den Geistern in Orgrimmar, bietet sie Priestern der Verlassenen an, die ihren zwanzigsten Machtkreis erreicht haben.",al={"questgeber","wer startet verschlingende seuche","ur'kyo standort"}},{q="Wohin muss ich gehen?",a="Überquert das große Meer nach Unterstadt in Tirisfal. Sucht Priesterin Aelthalyste auf, die im Kriegsviertel die Priesterausbildung der Verlassenen leitet.",al={"wo wird die quest abgegeben","aelthalyste standort","priesterlehrer unterstadt"}},{q="Warum schickt Ur'kyo Verlassene zurück nach Lordaeron?",a="Ur'kyo hält sich an eine Übereinkunft mit Priesterin Aelthalyste. Schattenpriester der Trolle verstehen Loa und Geister, während Verlassene dunkle Künste wirken, die mit ihrer untoten Natur verbunden sind. Sie brauchen Unterweisung durch ihre eigenen Anführer.",al={"warum zurück nach unterstadt","warum schickt der trollpriester einen fort"}},{q="Welche Bedeutung hat die Verschlingende Seuche?",a="Verschlingende Seuche ist ein mächtiges Leiden des Schattens, das jeder Priester im zwanzigsten Machtkreis erlernt. Sie befällt Ziele mit einer verheerenden Krankheit und überträgt deren Lebenskraft auf den Zaubernden.",al={"hintergrundgeschichte der verschlingenden seuche","priester der verlassenen seuche"}},{q="Können andere Völker der Horde diese Quest annehmen?",a="Nein. Sie wird nur Priestern der Verlassenen angeboten, da sie die Verbundenheit mit den einzigartigen Schattendisziplinen ihrer Heimat verkörpert.",al={"können trolle diese quest machen","ist diese quest nur für untote"}},{q="Wie fügt sich das in die Beziehungen zwischen den Priestern der Horde ein?",a="Die Horde teilt die Ausbildungsaufgaben zwischen Hexendoktoren und Hexenpriestern der Dunkelspeere auf Kalimdor und Schattenpriestern der Verlassenen in den Östlichen Königreichen auf. Jedes Volk verweist Reisende an Meister, die zu ihrer Kultur passen.",al={"trolle und untote priester","hintergrundgeschichte der hordepriester"}}},fp="16,203,21.392.0,28.422.0,27.146.0,22.138.0,48.213.0,49.206.0,40.119.0,46.212.0"}
P.entries["quest:5648"] = {n="Gewänder der Spiritualität",s="In Klingenhügel stellen neue Priester ihre Heilkunst im Feld auf die Probe. Sie suchen Grunt Kor'ja, die im Kampf gegen Überlebende aus Kul Tiras verwundet wurde, und versorgen ihre Verletzungen. Wer Erfolg hat, erhält zeremonielle Gewänder und Anerkennung unter den spirituellen Praktizierenden der Horde.",h="In Klingenhügel stellen neue Priester ihre Heilkunst im Feld auf die Probe.",kw={"durotar","fortitude","gewänder der spiritualität","grunt kor'ja","lesser heal","prachtmeer","klingenhügel","tai'jin"},ang={["class:Priest"]="Als Priester stellt Ihr Euch in Durotar einer frühen Prüfung der Heilkunst im Feld und verdient Euch Eure ersten Gewänder.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, Grunt Kor'ja am Leben zu halten, während Klingenhügel Angreifern aus Kul Tiras in der Nähe gegenübersteht.",["race:Troll"]="Als Troll lernt Ihr von Tai'jin, die Spiritualität der Dunkelspeer einzusetzen, um Verbündete im Kampf zu schützen."},sec={{t="Die Prüfung eines Heilers",b="Südlich von Klingenhügel kämpft die Horde noch immer gegen die Überreste der Streitkräfte von Großadmiral Daelin Prachtmeer. Tai'jin, die Priesterlehrerin der Trolle, prüft neue Priester bei der Versorgung von Verwundeten im Kampf. Sie schickt sie zu Grunt Kor'ja, einer Kriegerin, die bei der Abwehr menschlicher Infiltratoren schwer verwundet wurde. Ihr versorgt ihre Verletzungen und stärkt sie, bevor sie ihren Wunden erliegt."},{t="Gewänder der Gläubigen",b="Kor'ja zu heilen beweist, dass ein junger Priester bereit ist, der spirituellen Tradition der Horde zu dienen. Tai'jin verleiht die Gewänder der Spiritualität für die Rettung einer Verteidigerin an der Front. Für Orks und Dunkelspeertrolle gleichermaßen zeigen die Roben, dass ihr Träger mehr als ein Lehrling der Zauberformeln ist. Ihm kann man anvertrauen, die Krieger der Horde im Kampf am Leben zu halten."}},faq={{q="Wer ist Grunt Kor'ja und warum braucht sie Heilung?",a="Grunt Kor'ja ist eine Kriegerin der Horde, die unmittelbar südlich von Klingenhügel stationiert ist. Sie wurde im Kampf gegen Soldaten verwundet, die Admiral Prachtmeers Expedition aus Kul Tiras überlebten und noch immer die Küste Durotars heimsuchen.",al={"grunt korja","wer ist korja","verwundete grunt im süden"}},{q="Wo kann ich Tai'jin finden?",a="Tai'jin befindet sich in Klingenhügel in Durotar. Sie unterweist junge Priester der Horde, die das Tal der Prüfungen verlassen.",al={"taijin standort","wer vergibt gewänder der spiritualität","priesterlehrer klingenhügel"}},{q="Welche Kräfte sind nötig, um Kor'ja zu heilen?",a="Wirkt Lesser Heal, um Kor'jas Verletzungen zu versorgen, und stärkt dann ihre Ausdauer mit Power Word: Fortitude, bevor Ihr zu Tai'jin zurückkehrt.",al={"welche zauber verwenden","wie gewänder der spiritualität abschließen","korja zauber"}},{q="Warum kämpfen Soldaten aus Kul Tiras noch immer in Durotar?",a="Nachdem Großadmiral Prachtmeers Invasion zurückgeschlagen worden war, verstreuten sich die Überreste seiner Flotte entlang der Ostküste Durotars. Sie unternehmen noch immer verzweifelte Überfälle und halten Orte wie Burg Tiragarde besetzt.",al={"prachtmeers truppen durotar","warum menschen in klingenhügel","überreste aus kul tiras"}},{q="Welche Bedeutung haben die verliehenen Gewänder?",a="Die Roben, die Tai'jin verleiht, kennzeichnen den Eintritt eines Initianden in den aktiven Dienst als Heiler der Horde. Wer diese praktische Prüfung besteht, erwirbt das Recht, die Gewänder seiner Berufung zu tragen.",al={"gewänder belohnung hintergrund","warum eine robe verleihen","priestergewänder klingenhügel"}},{q="Welche Quest geht Gewänder der Spiritualität voraus?",a="Die Prüfung folgt auf In Favor of Spirituality. Ken'jai schickt einen jungen Priester aus dem Tal der Prüfungen zu Tai'jin in Klingenhügel.",al={"vorausgesetzte quest","vor gewänder der spiritualität","wie gewänder beginnen"}}},fx={ef970fef={q="Warum möchte Tai'jin, dass Kor'ja geheilt wird?",a="Tai'jin sieht diese Prüfung sowohl als praktische Verteidigung als auch als geistliche Pflicht. Grunz Kor'ja erlitt schwere Wunden bei der Verteidigung der Siedlung vor den verbliebenen Überresten von Daelin Prachtmeers Kul Tiras-Truppen, und ohne Heilung kann sie nicht überleben, um Klingenhügel zu bewachen. Für Euch dient die Aufgabe als Eure erste echte Prüfung: Indem Ihr ihren Körper heilt und ihr die Segnungen der Ahnen zuteilwerden lasst, beweist Ihr Eure Meisterschaft in den priesterlichen Künsten und zeigt, dass Ihr bereit seid, auf dem spirituellen Pfad voranzuschreiten.",al={"warum hilft taijin korja","taijin motiv","warum korja heilen"}},["2bdbaeb4"]={q="Warum schickt Tai'jin Euch, anstatt sich selbst um Kor'ja zu kümmern?",a="Tai'jin bleibt in Klingenhügel, um angehende Priester anzuleiten, und Kor'jas Notlage bietet die perfekte Prüfung, um Euer Wachstum zu beurteilen. Der wahre Wert eines Priesters erweist sich außerhalb komfortabler Heiligtümer, im Staub, wo Blut vergossen wird und die Verteidiger an der Front wanken. Indem Tai'jin Euch damit beauftragt, Kor'ja zu heilen und ihren Geist zu stärken, verlangt sie von Euch den Beweis, dass Euer Glaube und Eure Ausbildung den harten Realitäten standhalten können, denen sich die Horde gegenübersieht.",al={"warum schickt man mich","warum heilt taijin korja nicht","warum muss ich korja heilen"}}},fp="24,264,16.339.0,25.332.0,50.193.0,25.96.0,40.128.0,53.192.0,49.186.0,45.124.0"}
P.entries["quest:5649"] = {n="Der Spiritualität geneigt",s="Im Tal der Prüfungen beginnen junge Priester der Dunkelspeere ihr Leben jenseits des Ausbildungsgeländes. Auf Ken'jais Anweisung reisen sie zu Tai'jin in Klingenhügel und stellen sich den größeren Herausforderungen Durotars. Ihr Weg verbindet die überlieferten Bräuche der Trolle mit dem Dienst in der Horde.",h="Im Tal der Prüfungen beginnen junge Priester der Dunkelspeere ihr Leben jenseits des Ausbildungsgeländes.",kw={"dunkelspeer","durotar","der spiritualität geneigt","ken'jai","priester","klingenhügel","tai'jin","das tal der prüfungen"},ang={["class:Priest"]="Als Priester verlasst Ihr die Schlucht der Novizen und erhaltet bei Tai'jin in Klingenhügel eine formelle Ausbildung und Gewänder.",["faction:Horde"]="Als Mitglied der Horde erlebt Ihr, wie verschiedene Kulturen in Durotar zusammenarbeiten und die wilden Traditionen der Echoinseln mit dem militärischen Außenposten Klingenhügel verbinden.",["race:Troll"]="Als Troll bringt Ihr Eure Treue zur Horde mit der Bewahrung der uralten Spiritualität Eures Stammes in Einklang."},sec={{t="Abschied vom Red Canyon",b="Akolythen der Dunkelspeere verlassen das Tal der Prüfungen, nachdem sie bei Ken'jai ihre grundlegenden Riten erlernt haben. Der Weg von diesem abgeschiedenen Gelände führt nach Klingenhügel, einer Siedlung an einer Wegkreuzung in Durotar. Dort lässt ein junger Priester die Überlebensübungen hinter sich und beginnt, die spirituellen und kulturellen Pflichten des Stammes zu übernehmen."},{t="Alter Glaube und neue Bündnisse",b="Ken'jai spricht offen über den Platz der Dunkelspeere in Thralls Horde. Die Trolle schätzen die Treue der Orcs und ihre Lehren über Ehre, doch manche überlieferten Traditionen finden bei ihren Verbündeten wenig Anklang. Deshalb lehren die spirituellen Anführer der Dunkelspeere ihre Schüler, ihr Erbe im Stillen zu bewahren, während sie der Horde dienen.\n\nIn Klingenhügel heißt Tai'jin die Akolythen willkommen. Er führt sie zu Selbstständigkeit und Stärke innerhalb der Gemeinschaft."}},faq={{q="Wer vergibt die Quest „Der Spiritualität geneigt“?",a="Ken'jai, der Priesterlehrer der Trolle im Den, schickt Euch aus dem Tal der Prüfungen fort.",al={"wer startet der spiritualität geneigt","questgeber der spiritualität geneigt","kenjai priesterquest"}},{q="Wo finde ich Tai'jin?",a="Tai'jin befindet sich in der Kaserne von Klingenhügel, östlich des Ortskerns an Durotars Hauptstraße.",al={"tai'jin standort","wo ist tai jin","tai'jin finden"}},{q="Welche Klassen können diese Quest annehmen?",a="Nur Trollpriester, die ihre Reise in Durotar beginnen, können diesen Weg einschlagen.",al={"ist diese quest nur für priester","wer kann der spiritualität geneigt annehmen","priesterklassenquest klingenhügel"}},{q="Warum betont Ken'jai, dass manche Traditionen geheim bleiben müssen?",a="Ken'jai sagt, die Orcs seien treue Verbündete, die Ehre schätzen, aber nicht jedes uralte Ritual oder jeden Brauch der Trolle willkommen heißen. Er lehrt junge Priester, das Erbe ihrer Ahnen im Stillen zu ehren und die Eintracht innerhalb der Horde zu bewahren.",al={"warum geheime trolltraditionen","spannungen orcs trolle religion","warum im geheimen praktizieren"}},{q="Was lehrt Tai'jin den jungen Priester bei seiner Ankunft?",a="Tai'jin lehrt, dass die Dunkelspeere stärker wurden, indem sie sich an das Leben in der Horde anpassten. Der Stamm bereitet sich im Voraus vor und zieht bereits gestärkt in den Kampf, statt darauf zu warten, Kraft unmittelbar aus gefallenen Feinden zu schöpfen.",al={"taijin rede","was sagt tai jin","anpassung der dunkelspeere"}},{q="Welche Quest folgt unmittelbar auf „Der Spiritualität geneigt“?",a="Nachdem Ihr Euch bei Tai'jin gemeldet habt, bietet sie Euch „Garments of Spirituality“ an. Ihr zieht los, um einem verwundeten Soldaten der Horde im Feld zu helfen.",al={"was kommt nach der spiritualität geneigt","der spiritualität geneigt folgequest","nächste priesterquest nach taijin"}}},fp="24,265,22.308.0,28.423.0,45.84.0,25.92.0,35.73.0,58.221.0,54.213.0,56.118.0"}
P.entries["quest:565"] = {n="Bartolos Yetifellumhang",s="In Süderstade sammelt Bartolo Ginsetti Materialien für Bartolos Yetifellumhang. Der exzentrische Handwerker behauptet, sein Überwurf sei in der gesamten Allianz berühmt, und verlangt Schneiderbedarf, einen Umhang von einem Lederverarbeiter und rohes Yetifell.",h="In Süderstade sammelt Bartolo Ginsetti Materialien für Bartolos Yetifellumhang.",kw={"bartolo ginsetti","bolt of wool","feiner faden","umhang des hügelwächters","vorgebirge des hügellands","süderstade","yetifell","yetifell-umhang"},ang={["faction:Alliance"]="Bartolo prahlt, dass sein Yetifell-Umhang in der gesamten Allianz berühmt sei. Er bietet seine Schneiderkunst in Süderstade an, einer Hochburg der Allianz.",["profession:Tailoring"]="Für das Gewand werden ein Bolt of Wool und Feiner Faden sowie exotische Tierfelle benötigt."},sec={{t="Der Großschneider von Süderstade",b="Reisende können im Küstenort Süderstade bei Bartolo Ginsetti einen Yetifell-Umhang in Auftrag geben. Der Handwerker prahlt, dass es auf dem ganzen Planeten kein feineres Gewand gebe. Seine Arbeit vereint Materialien aus der heimischen Wildnis mit dem Können verbündeter Handwerker."},{t="Bestandteile des Handwerks",b="Bartolo braucht mehr als ein Fell und eine Nadel, um seinen Umhang zu fertigen. Bringt ihm einen Bolt of Wool, Feinen Faden, einen Umhang des Hügelwächters und zehn Büschel Yetifell von Bestien, die das Vorgebirge durchstreifen. Mit diesen Waren verarbeitet er die Rohmaterialien zu seinem Überwurf für kaltes Wetter."}},faq={{q="Wer ist Bartolo Ginsetti?",a="Bartolo Ginsetti ist ein exzentrischer, prahlerischer Handwerker in Süderstade im Vorgebirge des Hügellands. Er behauptet, einen unübertroffenen, weltberühmten Yetifell-Umhang gefertigt zu haben.",al={"wer ist bartolo","bartolo ginsetti","wer vergibt diese quest"}},{q="Welche Materialien benötigt Bartolo für den Umhang?",a="Bartolo braucht einen Bolt of Wool, einen von einem Lederverarbeiter gefertigten Umhang des Hügelwächters, Feinen Faden und zehn Büschel Yetifell.",al={"umhangzutaten","welche gegenstände für bartolo","yetifell-umhang materialien"}},{q="Wo fertigt Bartolo seine Umhänge?",a="Bartolo fertigt seine Umhänge in Süderstade, einer Küstenstadt der Menschen und dem wichtigsten Stützpunkt der Allianz im Vorgebirge des Hügellands. Er heißt Reisende willkommen, die die Region durchqueren.",al={"warum süderstade","wo ist süderstade","wo geschieht das"}},{q="Wo erhalten Abenteurer Yetifell in Hillsbrad?",a="Wilde Yetis in den Vorgebirgen und Bergen von Hillsbrad und Alterac tragen Büschel Yetifell. Ihr Fell ist dicht und wärmeisolierend.",al={"woher bekommt man fell","welche yetis","wo wird yetifell erbeutet"}},{q="Wie erhält man den Umhang des Hügelwächters?",a="Ein geschickter Lederverarbeiter schneidet den Umhang des Hügelwächters zu und näht ihn, den Bartolo als Grundlage für sein Gewand verwendet. Er ergänzt ihn um Wolle, Feinen Faden und Fell.",al={"wer fertigt den umhang des hügelwächters","umhang des hügelwächters herstellen","lederverarbeitungsumhang"}},{q="Warum behauptet Bartolo, sein Umhang sei weltberühmt?",a="Bartolo sagt, auf dem ganzen Planeten gebe es keinen feineren Umhang. Er prahlt, dass dieser in der gesamten Allianz berühmt sei und unübertroffene Wärme, Luxus und Ansehen biete.",al={"warum ist der umhang berühmt","bester umhang der welt","ist bartolos umhang gut"}}},fp="24,232,30.253.0,23.263.0,24.161.0,54.113.0,35.164.0,50.130.0,36.146.0,49.163.0"}
P.entries["quest:5650"] = {n="Gewänder der Dunkelheit",s="In Brill prüft Dunkler Kleriker Beryll angehende Priester der Verlassenen, bevor sie tiefer in die Schatten vordringen. Die Prüfung verlangt, einen verletzten Todeswächter zu heilen und zu stärken, denn ihre Berufung erfordert mehr, als Feinde zu peinigen.",h="In Brill prüft Dunkler Kleriker Beryll angehende Priester der Verlassenen, bevor sie tiefer in die Schatten...",kw={"brill","dunkler kleriker beryll","todeswächter kel","fortitude","gewänder der dunkelheit","lesser heal","priester","schatten","tirisfal"},ang={["class:Priest"]="Als Priester der Verlassenen verbindet Ihr den düsteren Nutzen der Schatten mit der Pflicht, Verbündete zu stärken und zu heilen.",["race:Undead"]="Als Verlassene nutzt Ihr Heilmagie, um Frontsoldaten wie Todeswächter Kel im Kampf gegen Gnolle und Überreste der Geißel zu unterstützen."},sec={{t="Zwischen Dunkelheit und Licht",b="Priester der Verlassenen sind für Schatten und Dunkelheit bekannt, doch Dunkler Kleriker Beryll lehrt, dass die Beherrschung der Dunkelheit auch Licht und Heilkunst erfordert. Wer nur nach Verderben strebt, dem wird geraten, stattdessen Arkanmagie zu studieren. Ein Priester muss Kameraden stärken und bewahren, ebenso wie Feinde peinigen."},{t="Eine Pflicht am Friedhof",b="Nördlich von Brills Friedhof hält Todeswächter Kel die Stellung gegen umherstreifende Gnollrudel, obwohl er verwundet ist. Beryll schickt Euch, um Kels Wunden mit Heilzaubern zu versorgen und seine Ausdauer mit Schutzzaubern zu stärken. Damit zeigt Ihr, dass Ihr Tirisfals Verteidiger unterstützen könnt. Beryll gewährt Euch sein Gewand und nimmt Euch in die höheren Mysterien der Priesterschaft auf."}},faq={{q="Warum nutzen Priester der Verlassenen Heilmagie, wenn ihre Macht aus der Dunkelheit stammt?",a="Dunkler Kleriker Beryll lehrt, dass Priester der Verlassenen außergewöhnliche Kraft aus den Schatten schöpfen, doch Heilung bleibt unerlässlich. Bevor ein Akolyth die Dunkelheit meistert, muss er unterstützende und heilende Magie erlernen, damit die Verteidiger der Verlassenen im Kampf bestehen.",al={"warum heilen untote","hintergrund zur heilung durch verlassene priester","schatten gegen licht bei untoten"}},{q="Wer ist Todeswächter Kel?",a="Todeswächter Kel ist ein Wachposten der Verlassenen, der nördlich von Brills Friedhof stationiert ist. Er verteidigt die örtlichen Siedlungen gegen angriffslustige Gnollrudel, die durch die Wälder streifen, und braucht Hilfe, wenn er im Dienst verwundet wird.",al={"todeswächter kel hintergrund","wer ist todeswächter kel","verwundeter todeswächter"}},{q="Wer vergibt diese Quest?",a="Dunkler Kleriker Beryll, der Priesterlehrer in Brill, bietet sie an, nachdem Ihr In Favor of Darkness abgeschlossen habt.",al={"wer startet gewänder der dunkelheit","gewänder der dunkelheit questgeber"}},{q="Welche Gewänder erhält man nach bestandener Prüfung?",a="Beryll verleiht eine maßgeschneiderte Robe als Zeichen des Ranges und der erbrachten Leistung. Sie kennzeichnet die Beherrschung der grundlegenden Priesterpflichten und die Anerkennung durch andere Priester.",al={"welche robe erhält man","gewänder belohnung priester"}},{q="Welche Bedrohungen bekämpfte Todeswächter Kel?",a="Kel wurde im Kampf gegen örtliche Gnolle verwundet, die Tirisfals Wildnis nördlich von Brills Friedhof unsicher machen.",al={"was hat kel angegriffen","kel gnolle"}},{q="Welche dunkleren Mächte deutet Dunkler Kleriker Beryll an?",a="Beryll deutet Schattentechniken an, die nur die Priesterschaft der Verlassenen kennt, darunter besondere Formen der Schattenmagie und geistiger Peinigung, die Priester anderer Völker nicht praktizieren.",al={"einzigartige zauber der verlassenen priester","andeutung dunklerer mächte"}}},fx={["933f71c0"]={q="Warum möchte Dunkler Kleriker Beryll, dass dies erledigt wird?",a="Dunkler Kleriker Beryll möchte Eure Disziplin und Bereitschaft innerhalb des Priestertums der Verlassenen testen. Während Priester der Verlassenen tiefgreifende Stärke aus der Dunkelheit und dem Schatten beziehen, glaubt Beryll, dass ein Priester die Dunkelheit nicht wahrhaft meistern kann, ohne zuerst das Licht und seine wiederherstellenden Künste zu verstehen. Indem er Euch anweist, den verletzten Todeswache Kel zu heilen und zu stärken, testet er Euer praktisches Verständnis grundlegender Heilung, bevor er Euch tiefer in die dunkleren Lehren des Priestertums aufnimmt.",al={"beryll motiv","warum schickt mich beryll","warum kel heilen beryll"}},a6afe368={q="Warum schickt Dunkler Kleriker Beryll Euch, anstatt sich selbst um Todeswache Kel zu kümmern?",a="Diese Aufgabe dient speziell als Initiationsritus für Euch als Initiat. Beryll besitzt diese Fähigkeiten bereits, aber die Bewertung Eures Wachstums erfordert, dass Ihr Euch ins Feld begebt und Eure Ausbildung direkt anwendet. Das Heilen und Stärken eines aktiven Verteidigers wie Todeswache Kel beweist Beryll und Euren Gefährten, dass Ihr fähig seid, die Verlassenen im Kampf zu unterstützen.",al={"warum schickt man mich kel zu heilen","warum nicht beryll selbst","warum braucht mich beryll"}}},fp="20,224,27.289.0,23.378.0,77.246.0,22.200.0,21.98.0,52.154.0,41.110.0,50.183.0"}
P.entries["quest:5651"] = {n="Der Dunkelheit geneigt",s="Dunkler Kleriker Duesten schickt Euch für Der Dunkelheit geneigt von Todesend nach Brill. Dort setzt Ihr Eure Ausbildung bei Dunklem Kleriker Beryll fort und studiert das Heilige Licht und den Schatten.",h="Dunkler Kleriker Duesten schickt Euch für Der Dunkelheit geneigt von Todesend nach Brill.",kw={"beryll","brill","todesend","duesten","licht","priester","schatten","tirisfal"},ang={["class:Priest"]="Als Priester lernt Ihr den Weg der Verlassenen: Heiliges Licht und Schatten mit kaltem Bedacht einzusetzen, ohne religiöse Ehrfurcht.",["race:Undead"]="Als Untoter reist Ihr von Todesend nach Brill und wagt Euch erstmals in das größere Reich der Verlassenen. Die Reise zeigt den Initianden, wie ihr Volk inmitten der Ruinen Lordaerons den Wiederaufbau betreibt."},sec={{t="Ein Pfad durch Fäulnis",b="Dunkler Kleriker Duesten lehrt, dass Verderbnis die Verlassenen schmiedete und sie dann wie Aas beiseitewarf. Um zu überleben, müssen sie Licht und Schatten ohne Sentimentalität verstehen. Ihr verlasst den Friedhof von Todesend und betretet die weite Welt jenseits seiner Mauern."},{t="Unterweisung in Brill",b="Ihr folgt der Straße von Todesend nach Nordosten, überquert eine überdachte Holzbrücke und erreicht das verfallene Brill. Dunkler Kleriker Beryll wartet in den oberen Gemächern des örtlichen Gasthauses, um Eure Entschlossenheit zu prüfen. Er schätzt Ehrgeiz und kalte Zweckmäßigkeit mehr als blinde Hingabe. Ein Priester der Verlassenen muss göttliche Macht als Waffe und Werkzeug einsetzen, niemals als moralische Krücke."}},faq={{q="Welchen Zweck hat diese Quest?",a="Dunkler Kleriker Duesten schickt Euch von Todesend nach Brill, um Eure Ausbildung zum Priester der Verlassenen fortzusetzen. Dunkler Kleriker Beryll stellt Euch vor Eure nächste priesterliche Herausforderung.",al={"was bewirkt diese quest","warum der dunkelheit geneigt","der dunkelheit geneigt zweck"}},{q="Warum nutzen Priester der Verlassenen das Licht, wenn sie sich der Dunkelheit verschreiben?",a="Kleriker der Verlassenen studieren Licht und Schatten, weil sie glauben, dass deren Gleichgewicht die Welt bestimmt. Das Heilige Licht bereitet untotem Fleisch unerträgliche Schmerzen, während der Ursprung der Verlassenen in Fäulnis und Dunkelheit liegt. Sie studieren beide Kräfte aus Notwendigkeit und praktischem Bedarf.",al={"warum nutzen untote priester licht","hintergrund der priester der verlassenen","licht und schatten untote"}},{q="Wo finde ich Dunklen Kleriker Beryll?",a="Dunkler Kleriker Beryll befindet sich in Brill, nordöstlich von Todesend. Er wohnt im zweiten Stock der Taverne Zur Galgenschlinge auf der Ostseite der Siedlung.",al={"wo ist dunkler kleriker beryll","beryll aufenthaltsort","beryll finden"}},{q="Welche Quest folgt darauf?",a="Das Gespräch mit Dunklem Kleriker Beryll schließt Eure Ausbildung hier ab und schaltet Garments of Darkness frei. Anschließend prüft er, ob Ihr mit Euren neuen Disziplinen Verbündete heilen und am Leben erhalten könnt.",al={"what comes next","nächste quest nach der dunkelheit geneigt","der dunkelheit geneigt folgequest"}},{q="Wer ist Dunkler Kleriker Duesten?",a="Dunkler Kleriker Duesten ist der Priesterlehrer in Todesend. Er hilft frisch erwachten Priestern der Verlassenen, ihre schmerzhafte Existenz zu verstehen und ihre geistigen Kräfte einzusetzen.",al={"wer vergibt diese quest","duesten hintergrund","dunkler kleriker duesten"}},{q="Warum spricht Beryll von Ehrgeiz statt Glauben?",a="Priester der Verlassenen halten traditionelle Frömmigkeit für unzureichend, seit die Mächte, die sie zu Lebzeiten verehrten, sie verlassen haben. Dunkler Kleriker Beryll erwartet von seinen Schülern, dass sie sich zum Überleben auf Ehrgeiz, Dringlichkeit und praktische Stärke verlassen.",al={"beryll dialog bedeutung","warum ehrgeiz statt glauben","glaube der verlassenen"}}},fx={["066c2d01"]={q="Warum schickt Dunkler Kleriker Duesten Euch nach Brill?",a="Duesten hat Euch die grundlegende Wahrheit des Priestertums der Verlassenen gelehrt: dass Ihr zwar sowohl das Licht als auch die Dunkelheit mit Diskretion handhaben könnt, Eure Existenz jedoch in Fäulnis und Dunkelheit geschmiedet wurde. Nun, da Ihr diese Grundlagen in Todesend erfasst habt, schickt er Euch weiter zu Dunkler Kleriker Beryll in Brill, um Eure Ausbildung im Dienst der Verlassenen voranzutreiben.",al={"warum schickt mich duesten weg","duesten motiv in favor of darkness","warum zu dunkler kleriker beryll"}}},fp="20,169,20.250.0,20.339.0,34.160.0,63.270.0,34.146.0,31.173.0,27.164.0,43.224.0"}
P.entries["quest:5654"] = {n="Verhexung der Schwäche",s="Von Klingenhügel bis Orgrimmar markiert Verhexung der Schwäche den nächsten Schritt eines jungen Dunkelspeerpriesters. Tai'jin schickt einen Initianten nach Norden zu Ur'kyo, der neue Schüler in den spirituellen Kreis des Stammes aufnimmt und die dunkleren Künste der Loa lehrt.",h="Von Klingenhügel bis Orgrimmar markiert Verhexung der Schwäche den nächsten Schritt eines jungen...",kw={"dunkelspeer","durotar","verhexung der schwäche","loa","orgrimmar","sen'jin","tai'jin","ur'kyo","tal der geister"},ang={["class:Priest"]="Als Priester schöpft Ihr Kraft aus der Zwiesprache mit urtümlichen Geistern und verwebt Stammesverhexungen mit Schattenzaubern und heilenden Zaubern. Diese Traditionen unterscheiden sich vom Dogma des Heiligen Lichts oder des Forgotten Shadow.",["faction:Horde"]="Als Mitglied der Horde seht Ihr auf Eurer Reise von Klingenhügel zum Tal der Geister, wie die Trollkultur innerhalb der befestigten Mauern von Thralls wachsender Hauptstadt Wurzeln schlägt.",["race:Troll"]="Als Troll lasst Ihr die ersten Lektionen in Klingenhügel hinter Euch und reist Eurer Anerkennung als Dunkelspeerpriester entgegen, während Ihr über Generationen weitergegebene Flüche erlernt."},sec={{t="Ein Ruf in den Kreis",b="Tai'jin wacht über junge Dunkelspeerpriester, während sie in der Kaserne von Klingenhügel lernen. Sobald ein Akolyth spirituelle Zwiesprache und Shadow Magic beherrscht, enden diese ersten Lektionen. Tai'jin schickt den vielversprechenden Priester nach Norden durch Durotars Schluchten aus roter Erde nach Orgrimmar, der Hauptstadt der Horde. Dort lehren ältere Praktizierende die umfassenderen magischen Traditionen des Stammes."},{t="Die alten Wege im Tal der Geister",b="Im Tal der Geister in Orgrimmar unterhalten die Dunkelspeer eine Zuflucht abseits der Schmieden und Kriegerplätze der Orcs. Ur'kyo, ein älterer Priester, heißt dort neue Initianten willkommen. Seinem Kreis beizutreten bedeutet, die Loa zu ehren und die überlieferten Wege der Dschungeltrolle zu erlernen. Es bedeutet auch, mächtige Flüche und Verhexungen zu meistern, die einem Feind im Kampf die Kraft rauben."}},faq={{q="Welchen Zweck hat diese Quest?",a="Der Ritus markiert den Aufstieg eines Initianten innerhalb der Dunkelspeerpriesterschaft. Tai'jin schickt heranwachsende Trollpriester von Durotars Küste zu Ur'kyo in Orgrimmar, wo sie dem inneren Kreis der spirituellen Praktizierenden des Stammes beitreten.",al={"warum diese quest machen","verhexung der schwäche zweck","was bewirkt die quest verhexung der schwäche"}},{q="Wer ist Tai'jin?",a="Tai'jin ist eine trollische Priesterlehrerin in der Kaserne von Klingenhügel in Durotar. Sie führt junge Zauberwirker der Dunkelspeer durch ihre ersten Prüfungen, bevor sie sie in die Hauptstadt weiterschickt.",al={"wer ist der questgeber","tai'jin hintergrundgeschichte","taijin"}},{q="Wer ist Ur'kyo?",a="Ur'kyo ist ein älterer trollischer Priesterlehrer im Tal der Geister in Orgrimmar. Er leitet die fortgeschrittene spirituelle Ausbildung und lehrt Dunkelspeerpriester die Verhexungen des Stammes und tiefgründige Riten der Ahnen.",al={"wer ist ur'kyo","urkyo priesterlehrer","ur-kyo"}},{q="Wo liegt das Tal der Geister?",a="Das Tal der Geister ist ein abgelegenes, sumpfiges Viertel im Westen Orgrimmars. Es ist die wichtigste Heimstatt der Dunkelspeertrolle innerhalb der orkischen Festungsstadt, mit ihren Lehrern, Unterkünften und Totems.",al={"tal der geister lage","wo ist ur'kyo","wo ist ur'kyo zu finden"}},{q="Auf welche Art von Magie konzentriert sich diese Ausbildung?",a="Dunkelspeerpriester schöpfen ihre Kraft aus den Loa und den uralten Traditionen der Dschungeltrolle. Sie verbinden heilende Geistermagie mit schwächenden Flüchen wie Verhexung der Schwäche, statt sich allein auf das von Menschen oder Zwergen bevorzugte Heilige Licht zu verlassen.",al={"trollpriester magie","was sind die alten wege","verhexung hintergrundgeschichte"}},{q="Können auch Nichttrolle diese Quest annehmen?",a="Nein. Der Ritus gehört zur Tradition der Dunkelspeer und ihren einzigartigen Zaubern. Untote Priester wenden sich ihren eigenen Mentoren und Schattenphilosophien in Tirisfal und Unterstadt zu.",al={"können untote das machen","ist das nur für trolle"}}},fx={f04dcf0d={q="Warum möchte Tai'jin, dass dies erledigt wird?",a="Tai'jin erkennt, dass Eure Grundausbildung abgeschlossen ist und Ihr bereit seid, tiefer in die Traditionen des Stammes der Dunkelspeere einzutauchen. Sie schickt Euch zu Ur'kyo, damit Ihr förmlich in den Kreis aufgenommen werdet und die alten spirituellen Riten erlernt, die einen wahren Trollpriester definieren.",al={"taijin motiv","warum schickt man mich zu ur'kyo","warum hex of weakness lernen"}},["3c464e0c"]={q="Warum schickt Tai'jin Euch, anstatt Euch selbst zu unterrichten?",a="Tai'jin bietet angehenden Priestern in Klingenhügel erste Anleitung, aber fortgeschrittene spirituelle Unterweisung und die Stammesinitiation werden von älteren Meistern wie Ur'kyo beaufsichtigt. Um in Eurem Handwerk wirklich voranzukommen und die tieferen Wege Eures Volkes zu meistern, müsst Ihr zum Tal der Geister reisen, wo die Ältesten zusammenkommen.",al={"warum kann taijin mich nicht lehren","warum schickt man mich nach orgrimmar","warum muss ich zu ur'kyo"}}},fp="15,233,23.372.0,37.358.0,34.228.0,15.185.0,14.184.0,31.190.0,47.228.0,36.160.0"}
P.entries["quest:5658"] = {n="Touch of Weakness",s="Eine Priesterin heißt Euch erneut willkommen und bietet Euch eine Lektion in Schwäche an. Ihre Worte machen deutlich, dass sie erwartet, dass Ihr lernbereit zurückkehrt.",h="Eine Priesterin heißt Euch erneut willkommen und bietet Euch eine Lektion in Schwäche an.",kw={"lektion","priesterin","rückkehr","touch of weakness","schwäche"},ang={["class:Priest"]="Als Priester werdet Ihr als junge Priesterin angesprochen und bekommt eine Lektion angeboten."},sec={{t="Eine angebotene Lektion",b="Eine Priesterin begrüßt Euch bei Eurer Rückkehr und sagt, dass sie sich freut, Euch zu sehen. Sie bietet Euch eine Lektion an, von der sie erwartet, dass Ihr sie Euch merkt. Die Lektion selbst steht Euch noch bevor, und sie fragt, ob Ihr bereit seid."}},faq={{q="Wer fordert mich zum Lernen auf?",a="Eine Priesterin heißt Euch erneut willkommen und bietet Euch an, Euch eine Lektion zu erteilen.",al={"wer vergibt das","lektion der priesterin","questgeber touch of weakness"}},{q="Was will mir die Priesterin beibringen?",a="Sie bietet Euch eine Lektion an, die Ihr Euch ihren Worten nach gut merken solltet.",al={"welche lektion","lektion in schwäche","was ist touch weakness"}},{q="Was geschieht, wenn ich zurückkehre?",a="Die Priesterin freut sich über Eure Rückkehr und fragt, ob Ihr für eine Lektion bereit seid.",al={"zur priesterin zurückkehren","was geschieht hier","touch of weakness"}}},fp="17,130,16.197.0,26.63.0,41.59.0,27.84.0"}
P.entries["quest:566"] = {n="GESUCHT: Baron Vardus",s="In Tarrens Mühle fordert Hochexekutorin Darthalia den Tod von Baron Vardus. Er ist ein Mensch und ein hochrangiges Mitglied des Syndikats, dem Verbrechen gegen die Verlassenen vorgeworfen werden. Bringt Darthalia einen Beweis für seinen Tod.",h="In Tarrens Mühle fordert Hochexekutorin Darthalia den Tod von Baron Vardus.",kw={"alteracgebirge","baron vardus","darthalia","hochexekutorin darthalia","vorgebirge des hügellands","strahnbrad","syndikat","tarrens mühle","das oberland","vardus"},sec={{t="Kopfgeld auf den Baron",b="Hochexekutorin Darthalia hat ein Kopfgeld auf Baron Vardus ausgesetzt. Er ist ein Mensch, dem Verbrechen gegen die Verlassenen vorgeworfen werden, und eines der hochrangigen Mitglieder des Syndikats. Zuletzt soll er sich im Oberland des Alteracgebirges aufgehalten haben, nördlich von Tarrens Mühle. Darthalia fordert seinen Tod, und eine Belohnung erwartet jeden, der ihr einen Beweis bringt."},{t="Sein möglicher Aufenthaltsort",b="Baron Vardus könnte sich in jedem der Lager des Syndikats im Oberland aufhalten. Möglicherweise versteckt er sich auch im Keller des Gasthauses in Strahnbrad."},{t="Darthalias Urteil",b="Nach dem Tod von Baron Vardus erklärt Hochexekutorin Darthalia, dass das Syndikat nun weniger Anführer hat. Sie erwartet, dass ihr Zorn und Widerstand von kurzer Dauer sein werden."}},faq={{q="Wer ist Baron Vardus?",a="Baron Vardus ist ein Mensch und ein hochrangiges Mitglied des Syndikats. Er wird wegen Verbrechen gegen die Verlassenen gesucht.",al={"baron vardus","wer ist vardus","wer ist der baron"}},{q="Wo ist Baron Vardus zu finden?",a="Baron Vardus wurde zuletzt im Oberland des Alteracgebirges gesehen, nördlich von Tarrens Mühle. Er könnte sich dort in einem der Lager des Syndikats aufhalten oder im Keller des Gasthauses in Strahnbrad verstecken.",al={"baron vardus aufenthaltsort","wo ist vardus","baron vardus finden"}},{q="Wer setzt das Kopfgeld auf Baron Vardus aus?",a="Hochexekutorin Darthalia setzt das Kopfgeld auf Baron Vardus aus. Bringt ihr einen Beweis für seinen Tod nach Tarrens Mühle.",al={"wer hat das kopfgeld ausgesetzt","wer will vardus tot sehen","darthalia kopfgeld"}}},fp="20,205,20.318.0,17.131.0,19.154.1,20.113.0,32.185.0,38.103.0"}
P.entries["quest:567"] = {n="Gefährlich!",s="In Tarrens Mühle bestimmt Hochexekutorin Darthalia vier Menschen aus Hillsbrad zur Hinrichtung. Ihr zufolge haben sie Verlassene getötet und Versorgungslieferungen angegriffen.",h="In Tarrens Mühle bestimmt Hochexekutorin Darthalia vier Menschen aus Hillsbrad zur Hinrichtung.",kw={"apotheker eli","citizen wilkes","clerk horrace whitesteed","dangerous","todeswache toma","todespirscher fry","farmer kalaba","hochexekutorin darthalia","hillsbrad","miner hackett","tarrens mühle","unterstadt"},ang={["class:Rogue"]="Als Schurke spürt Ihr verborgene Anführer in feindlichem Gebiet auf und folgt damit der verdeckten Arbeit von Todespirscher Fry, dessen Tod dieser Auftrag rächt.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, das Vorgebirge des Hügellands zu sichern, indem Ihr die erbittertsten Kämpfer der menschlichen Miliz brecht und die Truppenbewegungen der Horde durch die Region sicherer macht.",["race:Undead"]="Als Untoter ist es für Euch als treuer Diener der Dark Lady ein düsterer Quell des Stolzes, gefallene Todeswachen, Apotheker und Todespirscher zu rächen."},sec={{t="Eine Frage der Vergeltung",b="Im gesamten Vorgebirge des Hügellands sind die Kämpfe brutal und persönlich. Hochexekutorin Darthalia und die Garnison der Verlassenen in Tarrens Mühle sehen gewöhnliche Bürger von Hillsbrad als tödliche Feinde. Ein Steckbrief nennt vier Menschen, deren Widerstand Verlassene das Leben und wertvolle Lieferungen aus Unterstadt gekostet hat."},{t="Ziele von Tarrens Mühle",b="Das Kopfgeld gilt Clerk Horrace Whitesteed, der Todeswache Toma getötet hat; Citizen Wilkes, der Apotheker Eli ermordet hat; Miner Hackett, der Todespirscher Fry getötet hat; und Farmer Kalaba, der Versorgungskonvois aus Unterstadt sabotiert hat. Jeder von ihnen operiert von einem anderen Widerstandsnest in Hillsbrad aus und bleibt inmitten des größeren Konflikts schwer zu fassen."}},faq={{q="Wer hat das Kopfgeld für Dangerous! ausgesetzt?",a="Hochexekutorin Darthalia, Befehlshaberin der Streitkräfte der Verlassenen in Tarrens Mühle, hat das Kopfgeld auf vier prominente Menschen aus Hillsbrad ausgesetzt.",al={"wer hat dangerous ausgehängt","wer vergibt die quest dangerous","darthalias kopfgeld"}},{q="Warum werden gerade diese Menschen gesucht?",a="Jeder von ihnen hat die Verlassenen angegriffen. Clerk Horrace Whitesteed hat Todeswache Toma getötet, Citizen Wilkes hat Apotheker Eli ermordet, Miner Hackett hat Todespirscher Fry getötet und Farmer Kalaba hat lebenswichtige Versorgungslieferungen aus Unterstadt überfallen.",al={"warum sind sie gefährlich","was haben sie getan","verbrechen der ziele in hillsbrad"}},{q="Wo befinden sich die Ziele?",a="Alle vier halten sich verstreut im Vorgebirge des Hügellands auf, in den Siedlungen, auf den Höfen und in den Minen der Menschen.",al={"wo sind die ziele","questorte dangerous","hacketts aufenthaltsort"}},{q="Welchen strategischen Zweck hat dieser Auftrag?",a="Der Auftrag ist eine Antwort auf die Tötungen und soll den örtlichen Widerstand der Menschen lähmen. Er schützt die Patrouillen und Versorgungslinien der Verlassenen zwischen Tarrens Mühle und Unterstadt.",al={"warum sie töten","ziel des kopfgelds in hillsbrad","strategie von tarrens mühle"}},{q="Gibt es eine Verbindung zu Battle of Hillsbrad?",a="Ja. Die Ziele leben auf den Höfen, in den Minen und in den Ortskernen, die die Streitkräfte der Verlassenen während der umfassenderen Offensive Battle of Hillsbrad angreifen.",al={"verbindung zu battle of hillsbrad","darthalias schlacht","offensive in hillsbrad"}},{q="Wer löst das Kopfgeld ein, sobald sie getötet sind?",a="Bringt Beweise für ihren Tod direkt zu Hochexekutorin Darthalia in Tarrens Mühle.",al={"wer schließt dangerous ab","dangerous abgeben","bei darthalia abgeben"}}},fx={ed73acb1={q="Warum möchte Hochexekutorin Darthalia, dass diese vier Menschen eliminiert werden?",a="Hochexekutorin Darthalia hat das Kopfgeld ausgesetzt, weil diese vier Individuen direkte, verheerende Schläge gegen die wichtigsten Operationen von Tarrens Mühle geführt haben. Schreiber Whitesteed, Bürger Wilkes und Bergmann Hackett haben jeweils wichtige Personen der Verlassenen ermordet – eine Todeswache, einen Apotheker und einen Todespirscher-Späher. Bauer Kalaba fing entscheidende Versorgungskarawanen aus der Unterstadt ab. Ihre Beseitigung rächt gefallene Kameraden, sichert die Versorgungswege und entfernt gefährliche Guerilla-Bedrohungen von der Hillsbrad-Front.",al={"warum sie töten","darthalia motiv","warum werden sie tot gesucht"}},["4592bc02"]={q="Wer sind die Ziele, die auf dem Dangerous! Kopfgeld markiert sind?",a="Eure Ziele sind vier einflussreiche Bewohner von Hillsbrad, die gegen die Verlassenen zu den Waffen gegriffen haben: Schreiber Horrace Whitesteed, Bürger Wilkes, Bergmann Hackett und Bauer Kalaba. Obwohl sie wie gewöhnliche Stadtbewohner, Bergleute und Arbeiter erscheinen, hat sich jeder von ihnen als außerordentlich tödlich und einfallsreich erwiesen, da sie aus dem Verborgenen heraus über die Vorgebirge und Felder hinweg einen irregulären Krieg gegen Tarrens Mühle führen.",al={"wer sind die ziele","dangerous kopfgeld ziele","wen töten"}},["7da50b6a"]={q="Warum verlässt sich Hochexekutorin Darthalia auf Abenteurer anstatt auf ihre eigenen Todeswachen?",a="Die militärischen Streitkräfte von Tarrens Mühle sind bereits bis an ihre Grenzen beansprucht, da sie Verteidigungslinien halten und Scharmützel in ganz Hillsbrad austragen. Zudem marschieren die Ziele nicht offen umher; sie haben sich in zivilen Farmen, Minen und auf Nebenwegen versteckt. Darthalia verlässt sich auf umherstreifende Kopfgeldjäger und fähige Abenteurer, die sich unabhängig bewegen, ausweichende Ziele aufspüren und diese hinter feindlichen Linien ausräuchern können, ohne dabei ganze Garnisonstruppen abzuziehen.",al={"warum keine wachen benutzen","warum ich gefährlich","warum abenteurer schicken"}}},fp="10,136,23.301.0,22.331.0,33.132.0,37.223.0,30.97.0,47.162.0,45.131.0,44.79.0"}
P.entries["quest:5672"] = {n="Elunes Anmut",s="In Darnassus folgen junge Nachtelfenpriester dem Ruf der Sisterhood of Elune. Ihre ersten Reisen bereiten sie auf tiefere Unterweisung durch Priesterin Alathea vor.",h="In Darnassus folgen junge Nachtelfenpriester dem Ruf der Sisterhood of Elune.",kw={"alathea","darnassus","elune","elunes anmut","priesterquest","priesterin alathea","sisterhood of elune","tempel des mondes"},ang={["class:Priest"]="Als Priester folgt Ihr dem Glauben der Kaldorei, der sich von den auf dem Licht beruhenden Lehren der Menschen und Zwerge unterscheidet. Eure Kunst gründet auf Elunes Schutz.",["race:NightElf"]="Als Nachtelf erbt Ihr Elunes Anmut durch Traditionen, die die Sisterhood of Elune über die Zeitalter hinweg bewahrt hat."},sec={{t="Eine heilige Berufung",b="Im Tempel des Mondes führt die Schwesternschaft junge Akolythen von ihren ersten Gebeten bis zur Beherrschung der Mondmagie. Nachtelfen vertrauen auf die Mondmutter Elune. Menschen und Zwerge folgen hingegen dem Heiligen Licht. Erreicht ein Novize einen Meilenstein seiner Hingabe, werden erfahrene Mentoren aufmerksam und erachten den Schüler als bereit, größere göttliche Macht zu tragen."},{t="Segen der Mondgöttin",b="Priesterin Alathea überbringt dem Akolythen den Ruf der Schwesternschaft. Sie würdigt seine Hingabe und heißt ihn in Traditionen willkommen, die über Jahrtausende bewahrt wurden. Mit der Annahme des Ritus besiegelt der Novize ein Band mit Elune. Fortan sind Schutzzauber und Mondanrufungen des Glaubens der Kaldorei in Reichweite."}},faq={{q="Welchen Zweck hat diese Quest?",a="Der Ritus markiert einen spirituellen Meilenstein für Nachtelfenpriester. Er ruft einen Akolythen nach Darnassus zurück, wo Priesterin Alathea seine Entwicklung anerkennt und ihm die höheren Lehren der Sisterhood of Elune erschließt.",al={"warum elunes anmut","was bewirkt elunes anmut","zweck der quest"}},{q="Wer ist Priesterin Alathea?",a="Priesterin Alathea ist eine angesehene Lehrerin der Sisterhood of Elune in Darnassus. Sie begleitet Priester der Kaldorei, während sie ihre Verbundenheit mit der Mondgöttin vertiefen.",al={"alatheas rolle","wer vergibt die quest","wer ist alathea"}},{q="Warum ist diese Gabe den Nachtelfen vorbehalten?",a="Nachtelfenpriester verehren Elune unmittelbar, während Menschen- und Zwergenpriester ihre Kraft aus dem Heiligen Licht schöpfen. Die Anrufungen der Schwesternschaft, darunter Elunes Anmut, spiegeln den Schutz des Mondes und Abwehrzauber wider, die die Kaldorei seit Jahrtausenden pflegen.",al={"warum nur nachtelfen","hintergrund der volksfähigkeit","unterschied bei elunes priestern"}},{q="Wo findet diese Zeremonie statt?",a="Dem Ruf wird in Darnassus im Tempel des Mondes gefolgt, wo sich die Priesterschaft der Stadt versammelt und lehrt.",al={"wo ist alathea","questort","tempel in darnassus"}},{q="Erhalten andere Priester der Allianz einen ähnlichen Ruf?",a="Jede Kultur folgt in der Priesterschaft ihrem eigenen Weg. Menschen und Zwerge studieren das Heilige Licht unter ihren Mentoren in Sturmwind und Eisenschmiede und erlernen Disziplinen, die sich von der Mondmagie der Nachtelfen unterscheiden.",al={"erhalten menschen das auch","entsprechung für zwergenpriester","andere völker"}},{q="Welchen Zustand der Hingabe meint Alathea?",a="Alathea spricht von der spirituellen Stärke und Reife, die durch Prüfungen in der weiten Welt errungen werden. Überleben, Disziplin und unerschütterliche Hingabe an Elunes Tugenden zeigen, dass ein Akolyth stärkere Mondsegen sicher kanalisieren kann.",al={"einen zustand erreicht","alatheas dialog","welche hingabe"}}},fx={["853b2ba0"]={q="Warum möchte Priesterin Alathea diese Gabe gewähren?",a="Priesterin Alathea überwacht den spirituellen Fortschritt der Priesterschaft von Darnassus. Als Dienerin von The Temple of the Moon ist es ihre heilige Pflicht und alte Tradition, zu erkennen, wenn ein Akolyth außergewöhnliche Hingabe gegenüber Elune und dem Volk der Kaldorei bewiesen hat. Indem sie Elune's Grace verleiht, stellt sie sicher, dass würdige Nachtelfenpriester mit den tieferen Segnungen der Mondgöttin betraut werden, um ihr Volk besser zu schützen.",al={"warum lehrt alathea elune's grace","alathea motiv","warum jetzt elune's grace"}}},fp="13,154,16.344.0,29.301.0,34.200.0,25.163.0,41.259.0,36.112.0,52.217.0,47.223.0"}
P.entries["quest:5674"] = {n="Elunes Anmut",s="Nachtelfenpriester verlassen Dolanaar, um in Darnassus Elunes Anmut zu empfangen. Der Ritus bezeugt ihre Bereitschaft für eine göttliche Begabung, die den Kaldorei vorbehalten ist.",h="Nachtelfenpriester verlassen Dolanaar, um in Darnassus Elunes Anmut zu empfangen.",kw={"darnassus","dolanaar","elunes anmut","laurna morgenglanz","priesterin alathea","sisterhood of elune","teldrassil","tempel des mondes"},ang={["class:Priest"]="Als Nachtelfenpriester erlernt Ihr die himmlische Magie der Sisterhood of Elune, die sich von den allgemeinen heiligen Praktiken unterscheidet.",["race:NightElf"]="Als Nachtelf spiegelt Eure Pilgerreise zum Tempel des Mondes Elunes zentrale Stellung in der Gesellschaft der Kaldorei wider. Sie führt Akolythen aus der Ferne ins Herz von Darnassus."},sec={{t="Ein heiliger Meilenstein",b="Ein Priester der Sisterhood of Elune braucht mehr als Geschick in Gebeten der Heilung und Züchtigung. Mit wachsender Erfahrung erreicht ein Akolyth den Punkt, an dem ihm Segnungen verliehen werden können, die den Kaldorei vorbehalten sind. Örtliche Mentoren wie Laurna Morgenglanz in Dolanaar können diese tieferen Künste nicht lehren, weshalb sie vielversprechende Schüler ins spirituelle Herz ihres Ordens entsenden."},{t="Audienz im Tempel",b="Initianden durchqueren Teldrassil auf ihrem Weg zum Tempel des Mondes in Darnassus. Dort prüft Priesterin Alathea unter den Blicken der Hohenpriesterschaft, ob jeder Bittsteller bereit ist, den schützenden Mantel der Göttin zu tragen. Sie lehrt dort Elunes Anmut, eine göttliche Begabung, die den Kaldorei vorbehalten ist."}},faq={{q="Was ist der Zweck dieser Quest?",a="Nachtelfenpriester kehren für einen Übergangsritus nach Darnassus zurück, sobald sie genügend praktische Erfahrung gesammelt haben. Im Tempel des Mondes prüft Priesterin Alathea sie und lehrt sie die schützende Kunst von Elunes Anmut.",al={"was bewirkt diese quest","elunes anmut quest zweck","warum alathea aufsuchen"}},{q="Wer ist Priesterin Alathea?",a="Priesterin Alathea ist eine hochrangige Priesterlehrerin im Tempel des Mondes in Darnassus. Sie beaufsichtigt die förmliche Ausbildung und den Aufstieg der Nachtelfenakolythen und prüft, ob sie die geistige Sammlung für fortgeschrittene, volksspezifische Gebete besitzen.",al={"priesterin alathea hintergrund","wer ist alathea","alathea darnassus"}},{q="Warum können örtliche Mentoren diese Fähigkeit nicht lehren?",a="Mentoren in Außenposten wie Laurna Morgenglanz vermitteln Novizen die grundlegenden Lehren, doch die Sisterhood behält den Kaldorei eigene heilige Segnungen einer förmlichen Verleihung vor. Akolythen reisen zum zentralen Sitz der Andacht ihres Ordens in Darnassus, um geprüft zu werden, bevor sie diese tieferen Gaben erlernen.",al={"warum nicht in dolanaar lernen","warum nach darnassus gehen"}},{q="Was verkörpert Elunes Anmut im Glauben der Kaldorei eigentlich?",a="Elunes Anmut verkörpert den unmittelbaren Schutz der Mondgöttin. Durch Gebete gewoben, mindert sie die Wucht eintreffender Angriffe und spiegelt Elunes schützende Gegenwart über ihren Gläubigen wider, wenn Gefahr naht.",al={"was ist elunes anmut","elunes anmut hintergrund"}},{q="Können Priester anderer Völker diesen Segen empfangen?",a="Nein. Elunes Anmut gehört zum überlieferten Glauben und zur Verehrung der Kaldorei. Nur Nachtelfenpriester, die unmittelbar mit der Mondgöttin Zwiesprache halten, lernen, sie anzurufen.",al={"können menschen elunes anmut erlernen","ist elunes anmut nur für nachtelfen"}},{q="Wo beginnt und endet diese Reise?",a="Laurna Morgenglanz schickt den Akolythen von Dolanaar auf Teldrassil zum Tempel des Mondes in Darnassus.",al={"quest anfang und ende","wohin gehen"}}},fx={dd9d0779={q="Warum schickt Laurna Morgenglanz Euch nach Darnassus?",a="Laurna Morgenglanz sieht dies als einen bedeutsamen Meilenstein in Eurer spirituellen Berufung. Ihr seid erfahren genug geworden, um heilige Segnungen zu empfangen, die nur der Geistlichkeit der Kaldorei bekannt sind, doch Tradition und Ritual verlangen, dass solch lebenswichtiges Wissen nicht in einem bescheidenen Waldaußenposten wie Dolanaar vermittelt werden kann. Ihre Pflicht ist es, Euch zurück zur hohen Priesterschaft von The Temple of the Moon zu führen, um sicherzustellen, dass Eure Bereitschaft ordnungsgemäß geprüft und genehmigt wurde, bevor Ihr mit den tieferen Mysterien der Mondgöttin betraut werdet.",al={"warum möchte laurna morgenglanz, dass dies erledigt wird","laurna morgenglanz motiv","warum zu priesterin alathea schicken"}}},fp="13,150,18.355.0,22.288.0,34.214.0,25.237.0,43.299.0,61.212.0,49.170.0,38.105.0"}
P.entries["quest:5676"] = {n="Arkane Rückkopplung",s="In Sturmwind lehrt Hohepriesterin Laurena Priester, die auf gefährliche Wege aufbrechen, Arkane Rückkopplung. In der Kathedrale des Lichts wird Glaube zur Verteidigung gegen feindliche Zauberwirker.",h="In Sturmwind lehrt Hohepriesterin Laurena Priester, die auf gefährliche Wege aufbrechen, Arkane Rückkopplung.",kw={"antimagie","arkane rückkopplung","kathedrale des lichts","hohepriesterin laurena","heiliges licht","menschlicher priester","laurena","priester","sturmwind"},ang={["class:Priest"]="Als Priester erhaltet Ihr eine Möglichkeit, Manawirker zu behindern, wenn göttliche Diplomatie versagt.",["faction:Alliance"]="Als Priester der Allianz helft Ihr, der Bedrohung durch abtrünnige Zirkel und dunkle Magieanwender in den Östlichen Königreichen zu begegnen.",["race:Human"]="Als menschlicher Priester in Sturmwind folgt Ihr der Ausbildung der Kathedrale des Lichts und verbindet Hingabe mit Disziplin gegen Magie."},sec={{t="Ein Schild gegen das Arkane",b="In der Kathedrale des Lichts warnt Hohepriesterin Laurena die Akolythen, dass arkane Magie gefährlich bleibt. Das Heilige Licht bringt Heilung, Wärme und göttliche Ordnung. Rohe Magie kann unberechenbar werden und zu Verderbnis oder Katastrophen führen. Hexenmeister, abtrünnige Zauberer und magische Bestien bedrohen die Gläubigen, weshalb Priester lernen, ihren Glauben zu einem aktiven Schutz gegen Zauber zu formen."},{t="Den Strom nach innen lenken",b="Arkane Rückkopplung wendet die Macht eines feindlichen Zauberwirkers gegen ihn selbst. Der Schutz wehrt Zauber nicht nur ab; er verbrennt das Mana des Zauberwirkers und bereitet ihm Qualen. Laurena lehrt den Ritus menschlichen Priestern, die sich auf Reisen jenseits von Sturmwind vorbereiten. So können die Gesandten der Kathedrale der Zauberei mit einer eigenen Verteidigung begegnen."}},faq={{q="Welchen Zweck hat die Quest Arkane Rückkopplung?",a="Der Ritus lehrt einen menschlichen Priester eine schützende Disziplin unter der Kirche des Lichts. Hohepriesterin Laurena zeigt, wie man feindlichen Zauberwirkern widersteht und gegen sie zurückschlägt.",al={"arkane rückkopplung quest","was ist arkane rückkopplung","warum diese quest machen"}},{q="Wer bietet diese Quest an und wo ist sie zu finden?",a="Hohepriesterin Laurena bietet die Ausbildung in der Kathedrale des Lichts am Kathedralenplatz in Sturmwind an.",al={"wer vergibt arkane rückkopplung","arkane rückkopplung questgeber","wo ist laurena"}},{q="Warum betrachtet die Kirche des Heiligen Lichts arkane Magie als Feind?",a="Die Kirche lehrt Hingabe, moralische Klarheit und Vertrauen auf göttliche Gnade. Ihre Priester betrachten unkontrollierte arkane Magie als Gefahr, weil ihre unberechenbaren, süchtig machenden Kräfte dämonische Einfälle angezogen und Verwüstung über Azeroth gebracht haben.",al={"warum hassen priester arkane magie","kirche gegen arkane magie","ist arkane magie schlecht"}},{q="Wie funktioniert der Schutz durch Arkane Rückkopplung grundsätzlich?",a="Der Zauber umgibt den Priester mit einer vergeltenden Aura. Trifft ein feindlicher Zauber auf sie, entzieht die Rückkopplung dem Angreifer Mana und verursacht einen körperlichen Schock.",al={"wie funktioniert arkane rückkopplung","arkane rückkopplung hintergrundgeschichte"}},{q="Kann jeder Priester dies von Laurena lernen?",a="In Sturmwind lehrt Laurena diese Disziplin menschlichen Priestern als Teil der Traditionen der Kathedrale des Lichts.",al={"können zwerge arkane rückkopplung lernen","wer kann arkane rückkopplung erhalten","volksspezifischer priesterzauber"}},{q="Welche Stufe wird von einem Akolythen erwartet, der diese Ausbildung beginnt?",a="Priester erlernen diese Technik etwa mit ihrem zwanzigsten Erfahrungskreis, wenn sie einfache Kirchendienste hinter sich lassen und in gefährliche Grenzlande aufbrechen.",al={"welche stufe für arkane rückkopplung","arkane rückkopplung stufenvoraussetzung"}}},fx={["1a3af0d5"]={q="Warum bietet Hohepriesterin Laurena an, Euch Arcane Feedback beizubringen?",a="Hohepriesterin Laurena betrachtet arkanmagische Magie als eine der größten Bedrohungen für die Gläubigen. Anstatt Priester schutzlos gegen feindliche Zauberwirker dastehen zu lassen, hielt es die Priesterschaft für notwendig, Gegenmaßnahmen zu meistern. Laurena vermittelt diesen Zauber, um sicherzustellen, dass Ihr über die spirituellen und mystischen Abwehrmaßnahmen verfügt, die nötig sind, um Euch selbst und Eure Gefährten vor jenen zu schützen, die zerstörerische arkane Macht gegen Euch einsetzen.",al={"warum lehrt laurena arcane feedback","hohepriesterin laurena motiv","warum arcane feedback lernen"}}},fp="15,179,27.369.0,23.321.0,49.175.0,49.108.0,68.229.0,52.155.0,39.110.0,63.137.0"}
P.entries["quest:5677"] = {n="Arkane Rückkopplung",s="In Eisenschmiede werden menschliche Akolythen, die tiefere Unterweisung suchen, nach Sturmwind zurückgeschickt. Dort bewahrt die Kathedrale des Lichts die Traditionen ihres Volkes.",h="In Eisenschmiede werden menschliche Akolythen, die tiefere Unterweisung suchen, nach Sturmwind...",kw={"arkane rückkopplung","kathedrale des lichts","hohepriester rohan","hohepriesterin laurena","eisenschmiede","mystic ward","priesterquest","sturmwind"},ang={["class:Priest"]="Als Priester lernt Ihr, dass jedes Volk dem Heiligen Licht durch seine eigenen Traditionen folgt.",["race:Dwarf"]="Als Zwerg ehrt Ihr Euer Bündnis mit den Menschen und bewahrt zugleich die besonderen Riten Khaz Modans unter Eurem eigenen Volk.",["race:Human"]="Als menschlicher Priester werdet Ihr aus zwergischen Heiligtümern nach Sturmwind geschickt. In der Kathedrale des Lichts erlernt Ihr die heiligen Bräuche, die Eurem Volk gelehrt werden."},sec={{t="Eine sanfte Weiterleitung",b="Hohepriester Rohan empfängt einen menschlichen Priester, der im Mystic Ward von Eisenschmiede tiefere geistliche Unterweisung sucht. Zwergenpriester und menschliche Priester dienen beide dem Heiligen Licht, doch jedes Volk bewahrt seine eigenen Riten, Glaubensübungen und Schutzgebete. Rohan behält die Lehren von Eisenschmiede seiner eigenen Priesterschaft vor. Deshalb schickt er menschliche Priester zurück nach Elwynn, damit sie die Traditionen der Menschen erlernen."},{t="Rückkehr zur Kathedrale",b="Nach seiner Ankunft in Sturmwind findet der Akolyth Hohepriesterin Laurena in der Kathedrale des Lichts. Laurena ist erleichtert, dass Rohans Rat den Reisenden zu ihr geführt hat, und heißt ihn willkommen, während seine Kräfte zu wachsen beginnen. In der Kathedrale können menschliche Priester die geistlichen Praktiken Sturmwinds weiter erlernen. Dort bereiten sie sich darauf vor, das Heilige Licht gegen die Bedrohungen rings um das Königreich einzusetzen."}},faq={{q="Warum weigert sich Hohepriester Rohan, menschliche Priester zu unterrichten?",a="Hohepriester Rohan achtet menschliche Glaubensdiener, doch die zwergische Priesterschaft bewahrt Riten und Segnungen, die innerhalb ihres eigenen Volkes weitergegeben wurden. Er schickt menschliche Priester nach Sturmwind, wo ihre Lehrmeister diese Lehren bewahren.",al={"warum nach sturmwind geschickt","warum rohan nicht ausbildet","zwergenpriester bildet mich nicht aus"}},{q="Wer ist Hohepriesterin Laurena?",a="Hohepriesterin Laurena führt die Priester in der Kathedrale des Lichts in Sturmwind und bildet sie aus. Sie begleitet vielversprechende menschliche Priester durch ihre weiterführenden Studien und Riten.",al={"hohepriesterin laurena","wer ist laurena","priesterlehrer kathedrale"}},{q="Wo ist Hohepriester Rohan zu finden?",a="Hohepriester Rohan ist in der Hall of Mysteries im Mystic Ward von Eisenschmiede zu finden.",al={"rohans standort","wo ist hohepriester rohan","rohan finden"}},{q="Was ist der Zweck dieser Quest?",a="Menschliche Priester auf mittlerer Ausbildungsstufe werden aus den Zwergenlanden zur Kathedrale des Lichts geschickt, der wichtigsten Ausbildungsstätte ihres Volkes. Dort können sie geistlichen Lehren folgen, die auf ihr Volk zugeschnitten sind.",al={"arkane rückkopplung questzweck","warum diese quest machen","was bewirkt diese quest"}}},fp="15,148,20.372.0,23.392.0,57.212.0,30.170.0,37.86.0,34.185.0"}
P.entries["quest:5678"] = {n="Arkane Rückkopplung",s="Menschliche Priester werden von Darnassus nach Sturmwind gerufen. Im Tempel des Mondes kommt Priesterin Alathea dem Ruf der Allianz widerwillig nach. Hohepriesterin Laurena wartet in der Kathedrale des Lichts, um den Akolythen auf vertiefende Unterweisungen vorzubereiten.",h="Menschliche Priester werden von Darnassus nach Sturmwind gerufen.",kw={"arkane rückkopplung","kathedrale des lichts","darnassus","hohepriesterin laurena","das heilige licht","priesterquest","priesterin alathea","sturmwind"},ang={["class:Priest"]="Als Priester überschreitet Ihr mit Eurer Rückkehr eine Schwelle auf Eurem spirituellen Weg. Ihr erkennt die tiefe Kluft zwischen Elunes Schwesternschaft und den Lehren des Heiligen Lichts.",["race:Human"]="Als Mensch kehrt Ihr nach Sturmwind zurück, der Heimat der Kirche des Heiligen Lichts. Ihr lasst die abgeschottete und skeptische Priesterschaft der Kaldorei hinter Euch.",["race:NightElf"]="Als Nachtelf erkennt Ihr in Priesterin Alatheas Vorsicht die Furcht der Kaldorei, dass arkane Eingriffe jüngerer sterblicher Völker eine weitere Katastrophe heraufbeschwören könnten."},sec={{t="Ein widerwilliger Ruf",b="Priesterin Alathea betreut gastierende Priester im Tempel des Mondes in Darnassus. Sie achtet das formelle Bündnis zwischen den Kaldorei und Sturmwind, misstraut jedoch den menschlichen Wegen der Magie und des Glaubens. Seit zehn Jahrtausenden prägt die Trauer über den Krieg der Ahnen die Furcht der Nachtelfen vor arkaner Macht. Selbst göttliche Riten der Menschen beunruhigen die Geistlichen, wenn strahlender Glaube mit arkanem Wirken verschwimmt."},{t="Rückkehr zur Kathedrale",b="Alathea achtet das Band zwischen den Völkern der Allianz und schickt Euch los, um einem Rückruf aus der Kathedrale des Lichts zu folgen. Hohepriesterin Laurena hat Boten über die Meere gesandt, um menschliche Priester für eine weiterführende Ausbildung zusammenzurufen. In Sturmwind lasst Ihr Elunes mondbeschienene Haine hinter Euch und betretet erhabene steinerne Heiligtümer im goldenen Glanz des Heiligen Lichts."}},faq={{q="Warum will Priesterin Alathea, dass ich Darnassus verlasse?",a="Priesterin Alathea schickt Euch auf Wunsch Eurer Vorgesetzten in Sturmwind nach Hause, doch auch die menschliche Theologie beunruhigt sie. Sie misstraut arkaner Magie selbst dann, wenn sie göttliche Praktiken berührt, und schickt menschliche Akolythen gern in ihre eigenen Kathedralen zurück.",al={"warum alathea mich fortschickt","warum nach sturmwind zurückkehren","alathea arkane rückkopplung"}},{q="Warum misstrauen Nachtelfen der Priestermagie der Menschen?",a="Nachtelfen misstrauen der Priestermagie der Menschen, weil ihre Kultur die Trauer über die Sundering trägt, verursacht durch rücksichtslose arkane Zauberei vor zehntausend Jahren. Im Mittelpunkt der Verehrung der Kaldorei steht Elune. Ihre Priesterinnen misstrauen Traditionen, die an arkane Macht grenzen oder sie nutzen, selbst unter Verbündeten, die dem Heiligen Licht folgen.",al={"warum nachtelfen arkane magie hassen","nachtelfen misstrauen arkaner magie","elune gegen das heilige licht"}},{q="Wer ist Hohepriesterin Laurena?",a="Hohepriesterin Laurena führt die Gläubigen in Sturmwinds Kathedrale des Lichts. Sie unterweist angehende menschliche Priester im Heiligen Licht, während ihre Macht wächst.",al={"wer ist laurena","hohepriesterin laurena sturmwind"}},{q="Wozu führt diese Quest?",a="Wenn Ihr Euch bei Hohepriesterin Laurena meldet, beginnt Eure weiterführende Ausbildung als menschlicher Priester in Sturmwind. Dort erlernt Ihr die Disziplin und die Segnungen der menschlichen Anhänger des Heiligen Lichts.",al={"was folgt auf arkane rückkopplung","arkane rückkopplung belohnung hintergrund"}}},fp="15,247,19.384.0,23.334.0,54.244.0,49.310.0,30.150.0,31.180.0"}
P.entries["quest:5679"] = {n="Verschlingende Seuche",s="In der Unterstadt kennzeichnet Verschlingende Seuche den Schattenpfad der Priester der Verlassenen. Priesterin Aelthalyste lehrt den Ritus jene, die ihre Hingabe an Shadow Magic bewiesen haben.",h="In der Unterstadt kennzeichnet Verschlingende Seuche den Schattenpfad der Priester der Verlassenen.",kw={"aelthalyste","verschlingende seuche","verlassene","lordaeron","priester","schatten","unterstadt","kriegsviertel"},ang={["class:Priest"]="Als Priester der Verlassenen erlernt Ihr einen Eurer gefürchtetsten Zauber. Euer Überleben ist an das Leiden gebunden, das Ihr Euren Feinden zufügt.",["faction:Horde"]="Als Mitglied der Horde erweitert Ihr ihr Arsenal um erbarmungslose, krankheitsartige Flüche. Andere Verbündete verlassen sich auf die Geister der Ahnen oder das Gleichgewicht der Elemente.",["race:Undead"]="Als Untoter erbt Ihr einen Pfad seuchenartiger Schattenkünste. Er spiegelt die Abkehr der Verlassenen von der traditionellen Glaubenspraxis Lordaerons nach dem Dritten Krieg wider."},sec={{t="Ein Fluch des Schattens",b="Im Kriegsviertel der Unterstadt lehrt Priesterin Aelthalyste die Priester der Verlassenen die finsteren Künste des Schattens. Priester anderer Völker schöpfen aus dem Heiligen Licht oder den Geistern der Ahnen, während die Verlassenen ihre eigenen spirituellen Lehren entwickelt haben. Verschlingende Seuche verleiht diesem Pfad eine furchterregende Gestalt. Sie peinigt Feinde und entzieht ihnen Lebenskraft, um den verfallenden Körper des Zaubernden mit dieser gestohlenen Kraft zu erhalten."},{t="Eine Prüfung der Meisterschaft",b="Priesterin Aelthalyste gibt die Macht der Seuche mit Bedacht weiter. Diese mächtige Waffe soll das Blatt gegen die Geißel und den Scharlachroten Kreuzzug wenden. Sie ermahnt ihre Schüler, zu üben, bis sie die Seuche sicher beherrschen. Größere Prüfungen erwarten jene, die nach Meisterschaft in den dunklen Künsten streben."}},faq={{q="Welchen Zweck hat diese Quest?",a="Dieser Ritus lehrt erfahrene Priester der Verlassenen, Verschlingende Seuche zu wirken. Das Schattenleiden zehrt sein Opfer aus und heilt den Zaubernden.",al={"warum verschlingende seuche machen","was bewirkt die quest verschlingende seuche","verschlingende seuche zweck"}},{q="Wer ist Priesterin Aelthalyste?",a="Priesterin Aelthalyste ist eine Priesterlehrerin der Verlassenen im Kriegsviertel der Unterstadt. Sie führt angehende Schattenwirker und sorgt dafür, dass sie ihre zerstörerischen Segnungen wirksam für die Verlassenen einsetzen.",al={"wer ist aelthalyste","aelthalyste hintergrundgeschichte","aelthalyste unterstadt"}},{q="Können Priester anderer Völker Verschlingende Seuche von Aelthalyste lernen?",a="Verschlingende Seuche kann nicht nur von ihr gelehrt werden. Jeder Priester erlernt sie unabhängig von seinem Volk auf Stufe zwanzig bei einem Priesterlehrer. Die eigenen Volkslehren der Verlassenen sind Touch of Weakness und Dark Sacrifice.",al={"können trolle verschlingende seuche lernen","ist verschlingende seuche nur für untote","andere völker verschlingende seuche"}},{q="Wo gebe ich diese Quest ab?",a="Priesterin Aelthalyste gehört zu den Priesterlehrern und Praktizierenden der Verlassenen im Kriegsviertel der Unterstadt.",al={"aelthalyste standort","wo ist die quest verschlingende seuche","unterstadt priesterlehrer standort"}},{q="Warum spezialisieren sich Priester der Verlassenen auf Seuchen und Shadow Magic?",a="Priester der Verlassenen erleiden starke körperliche Schmerzen, wenn sie das Heilige Licht kanalisieren, weil sie untot sind. Viele wenden sich dem Schatten zu und nutzen Leiden, Flüche und gestohlene Lebenskraft, um zu überleben und Krieg zu führen.",al={"warum schattenpriester der verlassenen","hintergrundgeschichte untoter priester","priestermagie der verlassenen"}},{q="Welche Prüfungen meint Aelthalyste?",a="Aelthalyste warnt, dass die Prüfungen in ganz Lordaeron schwerer werden, je mächtiger ein Priester wird. Dunkle Magie zieht gefährliche Aufmerksamkeit und tödliche Feinde auf sich, deshalb muss ein Akolyth jeden Fluch in seinem Repertoire beherrschen.",al={"spätere prüfungen bedeutung","künftige prüfungen aelthalyste","welche prüfungen"}}},fx={["7f0f5b4f"]={q="Warum möchte Priesterin Aelthalyste, dass Ihr Devouring Plague erlernt?",a="Priesterin Aelthalyste sieht in Devouring Plague eine lebenswichtige, mächtige Waffe für das Überleben der Verlassenen. Sie unterweist Priester der Verlassenen in dieser dunklen Kunst, damit Ihr angemessen ausgerüstet seid, um die Unterstadt zu verteidigen und in den unerbittlichen Prüfungen und Konflikten zu bestehen, die die Verlassenen in ganz Lordaeron erwarten.",al={"aelthalyste motiv","warum devouring plague lehren","warum will aelthalyste, dass dies getan wird"}}},fp="16,175,21.380.0,17.277.0,34.157.0,29.202.0,67.201.0,30.114.0,62.200.0,39.196.0"}
P.entries["quest:568"] = {n="Die Verteidigung von Grom'gol",s="In Grom'gol bewacht Kommandant Aggro'gosh den Stützpunkt der Horde im Schlingendorntal. Er dezimiert die Lashtail Raptors vor dem Basislager, um den sicheren Nachschub nach Steinard zu gewährleisten.",h="In Grom'gol bewacht Kommandant Aggro'gosh den Stützpunkt der Horde im Schlingendorntal.",kw={"aggrogosh","gromgol","horde","lashtail","raptoren","steinard","schlingendorntal"},ang={["faction:Horde"]="Als Mitglied der Horde haltet Ihr im Basislager Grom'gol einen Stützpunkt im Dschungel und sichert die Nachschublinie nach Steinard."},sec={{t="Den Stützpunkt sichern",b="Kommandant Aggro'gosh bewacht die Horde im Basislager Grom'gol. Das Lager ist für eine sichere Nachschublinie nach Steinard unerlässlich, doch die einheimischen Bewohner stehen dem im Weg."},{t="Die Dschungelräuber dezimieren",b="Lashtail Raptors vor Grom'gol bedrohen die Nachschublinie. Aggro'gosh ruft treue Kämpfer dazu auf, ihre Zahl zu verringern und sich dann für neue Befehle zurückzumelden."}},faq={{q="Wer befiehlt die Verteidigung des Lagers?",a="Kommandant Aggro'gosh, der die Festung des Kriegshäuptlings im Basislager Grom'gol befehligt, ordnet an, die Lashtail Raptors zu dezimieren.",al={"wer vergibt die quest","kommandant aggrogosh","questgeber"}},{q="Warum ist das Basislager Grom'gol für die Horde wichtig?",a="Das Basislager Grom'gol ist für eine sichere Nachschublinie zum Lager der Horde in Steinard in den Sümpfen des Elends unerlässlich.",al={"gromgols zweck","warum gromgol","nachschublinie"}},{q="Welche Bedrohungen gefährden die Abläufe im Lager?",a="Einheimische Bewohner behindern die Nachschublinie der Horde nach Steinard. Aggro'gosh will die Lashtail Raptors vor dem Lager dezimieren lassen.",al={"welche feinde","warum raptoren","welche bestien"}},{q="Was geschieht nach dem Dezimieren der Raptoren?",a="Nachdem Ihr die Raptoren dezimiert habt, meldet Ihr Euch bei Kommandant Aggro'gosh, um neue Befehle zu erhalten.",al={"was kommt als nächstes","questfortsetzung","folgequest"}}},fp="23,191,21.152.0,29.150.0,35.132.0,49.109.0,49.128.0,39.82.0"}
P.entries["quest:569"] = {n="Die Verteidigung von Grom'gol",s="In Grom'gol schickt sich Kommandant Aggro'gosh an, die Nachschubstraße nach Steinard zu sichern. Nach der Raptorenjagd vor dem Lager greifen Mosh'Ogg-Oger aus den Ruinen von Mizjah weiterhin die Karawanen an.",h="In Grom'gol schickt sich Kommandant Aggro'gosh an, die Nachschubstraße nach Steinard zu sichern.",kw={"aggro'gosh","grom'gol","ruinen von mizjah","mosh'ogg","ogerrüpel","steinard","schlingendorntal","hexendoktoren"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass die Karawanen zwischen Grom'gol und Steinard die Präsenz der Horde in den südlichen Östlichen Königreichen aufrechterhalten."},sec={{t="Die Sicherung der Karawanen",b="Kommandant Aggro'gosh muss den Nachschub von Grom'gol durch das Schlingendorntal nach Steinard sichern, einem für die Horde lebenswichtigen Außenposten. Er ist nicht gekommen, um jedes Volk des Tals zu bekämpfen. Doch die Mosh'Ogg-Oger haben die Ruinen von Mizjah südöstlich des Lagers besetzt, und Warnungen konnten ihre wiederholten Angriffe auf Karawanen der Horde nicht stoppen. Deshalb befiehlt Aggro'gosh einen Angriff auf die Oger und Hexendoktoren, die die Ruinen besetzt halten."}},faq={{q="Wo haben die Oger ihr Lager?",a="Die Oger besetzen die Ruinen von Mizjah, südöstlich des Basislagers Grom'gol im nördlichen Schlingendorntal.",al={"ogerstandort","wo sind die ruinen von mizjah","ogerlager"}},{q="Warum geht Grom'gol gegen diese Oger vor?",a="Grom'gol schickt Nachschub nach Steinard. Die Oger in den Ruinen von Mizjah überfallen weiterhin die Karawanen, obwohl sie förmlich aufgefordert wurden, damit aufzuhören.",al={"warum die oger töten","grund für die verteidigung von gromgol","warum moshogg bekämpfen"}},{q="Wer befiehlt diesen Angriff?",a="Kommandant Aggro'gosh, der militärische Anführer des Basislagers Grom'gol, leitet den Angriff auf die Oger.",al={"questgeber","wer gibt die quest","wer ist aggrogosh"}},{q="Was geht diesem Auftrag voraus?",a="Vor diesem Auftrag befahl Aggro'gosh eine Jagd, um die Raptoren vor Grom'gol auszudünnen.",al={"voraussetzung","vorherige quest","beginn der questreihe"}}},fp="23,172,21.404.0,26.94.0,38.122.0,23.97.0,31.84.0"}
P.entries["quest:57"] = {n="Die Nachtwache",s="Im ganzen Dämmerwald erheben sich rastlose Tote aus ihren Gräbern, und die Nachtwache ringt darum, sie zurückzuhalten. Kommandantin Althea Schwarzhaupt schickt Reisende in die heimgesuchten Hügelgräber, um Dunkelhain zu verteidigen. Ihr Kampf könnte die Stadt davor bewahren, der Dunkelheit anheimzufallen.",h="Im ganzen Dämmerwald erheben sich rastlose Tote aus ihren Gräbern, und die Nachtwache ringt darum, sie...",kw={"althea schwarzhaupt","dunkelhain","dämmerwald","nachtwache","rabenflucht","skelettschänder","skeletthorror","stille gärten"},ang={["class:Paladin"]="Für die Silver Hand und die Ritter des Lichts ist es eine heilige Pflicht, sich den entweihten Toten in den Stillen Gärten zu stellen. Sie wollen verderbte Ruhestätten reinigen.",["class:Priest"]="In Rabenflucht betreten Priester verseuchten Boden und stellen sich der unverhohlenen Schändung von Bestattungsbräuchen. Ihr Glaube kann gequälten Seelen friedliche Ruhe schenken.",["faction:Alliance"]="Dunkelhain markiert die gefährdete Südostgrenze der Allianz im Süden der Östlichen Königreiche. Wer der Nachtwache hilft, erhält die Stadt als nutzbaren Stützpunkt und bewahrt sie vor dem Untergang.",["race:Human"]="Viele Skelette, die sich aus der Erde des Dämmerwalds erheben, sind Vorfahren lebender Bürger von Sturmwind und Dunkelhain. Für menschliche Verteidiger ist der Kampf zutiefst persönlich."},sec={{t="Die Toten ruhen nicht",b="Auf den Friedhöfen des Dämmerwalds regt sich etwas im Zwielicht des Waldes. Kommandantin Althea Schwarzhaupt führt Dunkelhains Freiwilligenmiliz, die Nachtwache, gegen die auferstehenden Toten. Sturmwind schickt keine Hilfe, und ihre Truppen sind überlastet. Skelette und andere Schrecken bedrohen die östlichen Siedlungen, weshalb die Miliz wehrhafte Reisende aufruft, die Totenlande zu betreten."},{t="Heimgesuchte Erde",b="Zwei Orte stehen im Blick der Miliz: der Friedhof \"Stille Gärten\" unmittelbar südlich der Stadt und der Friedhof von Rabenflucht weit im Westen. Skelette erheben sich aus vergessenen Grüften und flachen Gräbern neben den Straßen, geweckt von dunkler Magie in den Schatten des Waldes. Sie niederzustrecken verschafft Dunkelhains bedrängten Bürgern eine Atempause. Doch der Kampf gegen dieses tief verwurzelte Übel endet nie."}},faq={{q="Warum verlässt sich die Nachtwache auf Reisende statt auf Wachen aus Sturmwind?",a="Sturmwind hat den Dämmerwald sich selbst überlassen, weshalb Kommandantin Althea Schwarzhaupt und ihre Miliz die Region verteidigen. Unruhen in der Hauptstadt und die Abwesenheit des Königs verhindern, dass Wachen sie verstärken, weshalb sich die Nachtwache an durchreisende Abenteurer wendet.",al={"warum keine hilfe aus sturmwind","wo ist sturmwinds armee","warum dunkelhain allein"}},{q="Woher kommen die Skelette?",a="Skelette erheben sich aus dem Friedhof \"Stille Gärten\" und dem Friedhof von Rabenflucht. Dunkle Magie in den Wäldern hat alte Grabstätten gestört und die Überreste als gewalttätige, willenlose Wächter auferweckt.",al={"herkunft der skelette im dämmerwald","warum gibt es skelette","ursprung der untoten im dämmerwald"}},{q="Wer führt die Nachtwache an?",a="Kommandantin Althea Schwarzhaupt führt die Nachtwache an. Sie ist mit Dunkelhains Bürgermeister, Lord Ello Schwarzhaupt, verwandt und leitet die Verteidigung der Stadt gegen die Untoten und Ungeheuer des Dämmerwalds.",al={"anführerin der nachtwache","wer ist althea schwarzhaupt","kommandantin schwarzhaupt"}},{q="Was ist der Unterschied zwischen den Stillen Gärten und Rabenflucht?",a="Der Friedhof \"Stille Gärten\" liegt unmittelbar südlich von Dunkelhain und bedroht die nahe Stadt. Der Friedhof von Rabenflucht liegt weit im Westen, jenseits des Waldes, und ist eine riesige Begräbnisstätte im Herzen der Untotenplage des Dämmerwalds.",al={"stille gärten oder rabenflucht","welcher friedhof ist besser","friedhofsstandorte im dämmerwald"}},{q="Was geschieht, nachdem diese Skelette dezimiert wurden?",a="Altheas Feldzug geht weiter, nachdem die Skelette und Unholde niedergestreckt wurden. Die Nachtwache hält im ganzen Wald nach neuen Bedrohungen Ausschau, von Ghulen und Skeletten bis hin zu gefährlicheren Untoten und den Nekromanten, die sie tiefer im Dämmerwald lenken.",al={"wie geht es mit der nachtwache weiter","questreihe der nachtwache","nach nachtwache zwei"}},{q="Warum ist Dunkelhain ständig in Gefahr?",a="Der Dämmerwald war einst eine friedliche Provinz des Königreichs Sturmwind, doch magisches Zwielicht und finstere Flüche verschlangen ihn. Wilde Worgen, gefräßige Spinnen und rastlose Untote überrennen die Wälder. Dunkelhain bleibt die letzte Bastion lebender Menschen in diesem Gebiet.",al={"warum ist der dämmerwald gefährlich","gefahr für dunkelhain","was hat den dämmerwald verflucht"}}},fx={dfb05d16={q="Warum möchte Kommandantin Althea Schwarzhaupt, dass dies erledigt wird?",a="Kommandantin Althea Schwarzhaupt ist für den Schutz der bedrängten Stadt Dunkelhain und der umliegenden Wälder verantwortlich. Da Berichte über eine aggressive Welle von Untoten aus den örtlichen Begräbnisstätten einströmen, steht Dunkelhain vor einer existenziellen Bedrohung. Die Schrecken und Unholde zurückzudrängen, die Raven Hill und Der Friedhof \"Stille Gärten\" durchstreifen, ist entscheidend, um die Stadt davor zu bewahren, völlig überrannt zu werden.",al={"warum skelette für althea töten","althea schwarzhaupt motiv","warum die untoten im dämmerwald ausräuchern"}},["8863b63d"]={q="Was sind Skelettunholde und Skelettschrecken?",a="Es handelt sich um animierte menschliche Überreste, die mit dunkler nekrotischer Magie erfüllt sind und aus der geschändeten Erde der Friedhöfe im Dämmerwald auferstehen. Diese untoten Unholde und Schrecken sind widerstandsfähiger und bösartiger als einfache schlurfende Knochen und durchstreifen den Raven Hill Graveyard und Der Friedhof \"Stille Gärten\", wo sie jedes Lebewesen angreifen, das ihren Weg kreuzt.",al={"skelettunholde schrecken","wen jagen wir für die nachtwache","skelette dämmerwald ziel"}}},fp="15,248,20.353.0,12.386.0,73.239.0,36.175.0,26.193.0,63.224.0,43.240.0,36.254.0"}
P.entries["quest:570"] = {n="Mok'Thardins Verzauberung",s="Im Basislager Grom'gol sammelt Scharfseher Mok'thardin die Kraft des Dschungels für die Horde. Seine früheren Riten waren erfolgreich, und er sucht scharfe Klauen und einen makellosen Katzenzahn für eine Verzauberung.",h="Im Basislager Grom'gol sammelt Scharfseher Mok'thardin die Kraft des Dschungels für die Horde.",kw={"verzauberung","scharfseher","grom'gol","mizjah","mok'thardin","schattenmaul","schlingendorntal","tigerin"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Scharfseher Mok'thardin die Magie des Dschungels für Euer Volk nutzen will."},sec={{t="Die Kraft des Dschungels",b="Im Basislager Grom'gol erforscht Scharfseher Mok'thardin die ungezähmte Kraft der Wildnis. Er will sie der Horde dienstbar machen. Seine ersten Riten waren erfolgreich, und er bietet an, ein verzaubertes Relikt zu erschaffen. Wer dazu bereit ist, muss ins dichte Unterholz vordringen und die tödlichen Raubtiere in der Nähe jagen."},{t="Die Schleicher von Mizjah",b="Mok'thardins Ritus verlangt acht Klauen von Schattenmaulpanthern und einen makellosen Zahn von einer Tigerin. Die wilden Katzen durchstreifen das Schlingendorntal. Viele streifen südöstlich der Ruinen von Mizjah umher, gleich jenseits des Flusses."}},faq={{q="Wer verlangt diese Tierteile?",a="Scharfseher Mok'thardin, ein Orcschamane im Basislager Grom'gol im Schlingendorntal, bittet um die Zutaten für seine Riten.",al={"wer vergibt mok'thardins verzauberung","questgeber mok'thardin","wer ist mok'thardin"}},{q="Wo sind die Panther und Tigerinnen zu finden?",a="Die Panther und Tigerinnen durchstreifen den dichten Dschungel. Mok'thardin weist Jäger nach Südosten zu einem Gebiet jenseits der Ruinen von Mizjah, gleich auf der anderen Seite des Flusses.",al={"schattenmaulklauen fundort","makelloser tigerinnenzahn fundort","wo wildtiere jagen"}},{q="Warum braucht Scharfseher Mok'thardin diese Gegenstände?",a="Mok'thardin will die natürliche Magie des Dschungels nutzen, mächtige Verzauberungen wirken und einen besonderen Gegenstand für die Champions der Horde herstellen.",al={"warum klauen und zähne sammeln","mok'thardin ritual zweck","warum schattenmaulklauen"}},{q="Wie geht Mok'thardins Ritualarbeit weiter?",a="Sobald Mok'thardin die Klauen und den Zahn hat, setzt er seine rituelle Handwerksarbeit in der nächsten Stufe der Verzauberungsreihe fort.",al={"was folgt auf mok'thardins verzauberung 2","nächste quest nach schattenmaulklauen","mok'thardin fortsetzung"}}},fp="25,191,21.269.0,22.213.0,36.120.0,46.130.0,47.130.0,45.118.0"}
P.entries["quest:571"] = {n="Mok'Thardins Verzauberung",s="Im Basislager Grom'gol braucht Scharfseher Mok'thardin ein starkes Band für die bisher gesammelten Trophäen aus dem Schlingendorntal. Gealterte Sehnen von älteren Primaten im südlichen Schlingendorntal werden die Federn, Krallen und den Reißzahn sicher zusammenhalten.",h="Im Basislager Grom'gol braucht Scharfseher Mok'thardin ein starkes Band für die bisher gesammelten Trophäen...",kw={"gealterte gorillasehne","beutebucht","gorilla","grom'gol","mistvale","mok'thardin","sehne","schlingendorntal"},ang={["faction:Horde"]="Als Abenteurer der Horde könnt Ihr im Basislager Grom'gol Scharfseher Mok'thardins Hilfe suchen. Er wirkt mächtige Dschungelmagie, um Eure Stellung im Schlingendorntal zu stärken."},sec={{t="Ein magisches Band",b="Die Federn, Krallen und der makellose Reißzahn bringen Scharfseher Mok'thardin zur nächsten Stufe seines Rituals. Er braucht ein zähes magisches Band, um sie miteinander zu verbinden. Nur die gealterte Sehne eines Elder Mistvale Gorillas kann der Magie standhalten, die er zu weben gedenkt."},{t="Jagd auf die Mistvale Elders",b="Elder Mistvale Gorillas suchen in den Dschungeln östlich von Beutebucht nach Nahrung. Mok'thardin braucht eine einwandfreie Sehne, daher müsst Ihr womöglich mehrere jagen, bevor Ihr eine findet, die sich für seine Verzauberung eignet."}},faq={{q="Wofür wird die gealterte Gorillasehne benötigt?",a="Scharfseher Mok'thardin braucht eine gealterte Sehne als magisches Band, um die gesammelten Federn, Krallen und den makellosen Reißzahn für seine Verzauberung sicher zusammenzuhalten.",al={"warum sehne","wofür braucht mokthardin die sehne","zweck der gorillasehne"}},{q="Wo sind die Elder Mistvale Gorillas zu finden?",a="Elder Mistvale Gorillas suchen in den südlichen Dschungeln des Schlingendorntals östlich von Beutebucht nach Nahrung.",al={"wo elder mistvale gorilla finden","mistvale gorilla fundort","wo sind gorillas"}},{q="Wer bittet um diese Jagd?",a="Scharfseher Mok'thardin, ein spiritueller Führer der Orcs im Basislager Grom'gol im Schlingendorntal, bittet um die Sehne.",al={"wer gibt die quest","questgeber"}},{q="Wo fügt sich dies in Mok'thardins Verzauberungsarbeit ein?",a="Die Jagd folgt auf das Sammeln der Krallen und des makellosen Reißzahns. Scharfseher Mok'thardins Verzauberungsarbeit geht danach weiter.",al={"was kommt davor","reihenfolge der questreihe","voraussetzung"}}},fp="25,222,16.240.0,27.174.0,42.152.0,46.96.0,23.108.0,56.123.0"}
P.entries["quest:5713"] = {n="Ein Schuss, ein Treffer",s="Auf dem Weg nach Auberdine gerät Schildwache Aynasha in einen Hinterhalt und kann ihre Botschaft nicht weitertragen. Von Marosh the Devious und seinen Furbolgfährtenlesern vergiftet, muss sie ein Gegengift anmischen, bevor sie weiterreisen kann.",h="Auf dem Weg nach Auberdine gerät Schildwache Aynasha in einen Hinterhalt und kann ihre Botschaft nicht...",kw={"hinterhalt","gegengift","aynasha","dunkelküste","furbolg","maestras posten","marosh","onaeya","schildwache"},ang={["class:Hunter"]="Als Jäger erkennt Ihr Aynashas Entschlossenheit an den Schüssen, die sie weiter ins Dickicht abgibt, während das Gift sie schwächt.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Waldpfade von aggressiven Furbolgs freizuhalten und sichert die Reisewege zwischen dem Eschental und den Festungen der Allianz im Norden.",["race:NightElf"]="Als Nachtelf schützt Ihr eine Schildwache Eures Volkes und die wichtigen Botschaften, die zwischen Außenposten im Eschental und an der nördlichen Dunkelküste überbracht werden."},sec={{t="Hinterhalt auf dem Waldweg",b="Schildwache Aynasha trägt wichtige Botschaften nach Auberdine, als feindselige Furbolgs sie auf einem Pfad im nördlichen Kalimdor abfangen. Marosh the Devious führt sie an. Ihr Gift lässt die Späherin taumeln und hindert sie daran, ihren Weg zu Fuß fortzusetzen."},{t="Die Stellung halten",b="Aynasha weiß, wie man natürliche Heilmittel herstellt, doch das Gegengift braucht Zeit zum Anmischen und Wirken. Maroshs Fährtenleser rücken näher, also braucht sie Reisende, die sie bei ihrer Arbeit beschützen. Obwohl ihre Kräfte schwinden, hält sie ihren Bogen ruhig und schießt ins Dickicht, um die Angreifer zurückzuhalten."},{t="Bericht an Maestras Posten",b="Nachdem Marosh getötet und der Angriff beendet ist, gibt das Gegengift Aynasha genug Kraft zurück, um nach Auberdine weiterzureisen. Sie bittet ihre Beschützer, Schildwache Onaeya bei Maestras Posten im südlich gelegenen Eschental von den aggressiven Furbolgs zu berichten, die regionale Versorgungswege bedrohen."}},faq={{q="Wer ist Schildwache Aynasha?",a="Schildwache Aynasha ist eine Nachtelfenspäherin, die wichtige Botschaften zwischen der Dunkelküste und dem Eschental überbringt. Geschickt mit dem Bogen und im Überleben in den Wäldern, wird sie im Dienst bei einem Hinterhalt vergiftet.",al={"schildwache aynasha","aynasha","wer ist aynasha"}},{q="Wer hat Schildwache Aynasha angegriffen?",a="Ein Rudel feindseliger Furbolgs unter der Führung von Marosh the Devious greift Schildwache Aynasha an. Sie vergiften sie im Kampf, sodass sie sich nicht mehr frei bewegen kann.",al={"wer hat sie angegriffen","marosh the devious","marosh","wer hat sie vergiftet"}},{q="Wohin war Schildwache Aynasha unterwegs?",a="Aynasha ist mit einer wichtigen Depesche nach Auberdine unterwegs, als Marosh und seine Fährtenleser ihr auf der Straße eine Falle stellen.",al={"wohin war aynasha unterwegs","aynashas reiseziel"}},{q="Warum müsst Ihr Schildwache Onaeya Bericht erstatten?",a="Aynasha muss Auberdine mit ihrer Botschaft erreichen, also bittet sie Euch, nach Süden zu Maestras Posten im Eschental zu gehen und Schildwache Onaeya vor der Feindseligkeit der Furbolgs zu warnen.",al={"schildwache onaeya","warum maestras posten","onaeya"}},{q="Warum sind die Furbolgs in der Gegend feindselig?",a="Viele Furbolgstämme in der gesamten Dunkelküste und im Eschental sind seit dem Dritten Krieg dämonischer Verderbnis und dem Wahnsinn verfallen. Sie greifen reisende Schildwachen und Wanderer auf den Wegen unterschiedslos an.",al={"warum greifen furbolgs an","feindseligkeit der furbolgs","verderbter furbolg"}},{q="Kämpft Aynasha während des Hinterhalts?",a="Ja. Durch das Gift kann Aynasha kaum noch stehen, doch sie schießt mit ihrem Bogen, um ihrem Verteidiger Deckung zu geben, während sie das Gegengift vorbereitet.",al={"hilft aynasha","aynashas bogen","kämpft sie"}}},fx={["39e047c2"]={q="Warum benötigt Schildwache Aynasha Euren Schutz?",a="Aynasha trägt eine dringende Nachricht nach Auberdine bei sich, aber ein Hinterhalt örtlicher Furbolgs führte dazu, dass sie von einem lähmenden Gift getroffen wurde. Sie ist kaum in der Lage zu stehen, geschweige denn ihre Reise allein fortzusetzen. Sie braucht Euch, um Wache zu stehen und die Angreifer lange genug in Schach zu halten, damit sie ein Gegenmittel brauen und verabreichen kann, damit sie sich erholt und ihre Mission erfüllen kann.",al={"warum aynasha helfen","aynasha motiv","warum braucht aynasha hilfe"}},["85f1ffa2"]={q="Wer greift Schildwache Aynasha an?",a="Der Hinterhalt wird von Marosh dem Hinterlistigen und seinem Rudel von Furbolg-Spähern angeführt. Die korrumpierten Furbolgs, die diese Grenzen durchstreifen, jagen verwundbare Reisende entlang der Straße, und sie griffen Aynasha an, um eine isolierte Nachtelfenbotin zur Strecke zu bringen.",al={"wer führt den hinterhalt an","wer ist marosh","aynasha angreifer"}},["69f547c2"]={q="Warum kann Aynasha die Furbolgs nicht selbst abwehren?",a="Obwohl Aynasha eine erfahrene Schildwache-Bogenschützin ist und Euch mit ihrem Bogen unterstützen wird, lässt sie das Gift, das durch ihre Adern fließt, schwer geschwächt und kaum in der Lage zu stehen. Sie kann keinen Nahkampf bewältigen, während sie sich gleichzeitig darauf konzentriert, ihr Gegenmittel vorzubereiten, was ihr Leben vollständig in Eure Hände legt.",al={"warum ich aynasha","warum braucht aynasha mich","warum kann aynasha nicht kämpfen"}}},fp="19,196,25.236.0,16.289.0,24.277.1,24.184.0,30.143.0,37.111.0,39.161.0,41.187.0,37.125.0"}
P.entries["quest:572"] = {n="Mok'Thardins Verzauberung",s="Im Basislager Grom'gol sammelt Scharfseher Mok'thardin Materialien für ein schamanistisches Ritual. Nachdem die Trophäen von Raubkatzen gesammelt sind, sucht er nun Federn von den Raptoren des Schlingendorntals.",h="Im Basislager Grom'gol sammelt Scharfseher Mok'thardin Materialien für ein schamanistisches Ritual.",kw={"verzauberung","federn","grom'gol","jungle stalker","mok'thardin","raptor","schlingendorntal"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass Mok'thardin mit seinem Ritual kleine Gegenstände aus dem Dschungel verbindet, um einen verzauberten Gegenstand herzustellen.",["faction:Horde"]="Scharfseher Mok'thardin will mit der fertigen Verzauberung der Horde und dem Kriegshäuptling helfen."},sec={{t="Federn des Pirschers",b="Scharfseher Mok'thardin braucht noch mehr, bevor sein schamanistisches Ritual beginnen kann. Er sammelt Materialien für ein Werkzeug, das dem Kriegshäuptling helfen soll. Nun bittet er Euch, Federn zu bringen, die Jungle Stalkers tragen. Die Raptoren leben im dichten Dschungel südlich des Basislagers Grom'gol, nahe der großen Arena."}},faq={{q="Wer bittet um die Federn?",a="Scharfseher Mok'thardin, ein Orkschamane im Basislager Grom'gol im Schlingendorntal, sucht Federn für eine rituelle Verzauberung.",al={"questgeber","mok'thardin","wer braucht federn"}},{q="Wo sind die Jungle Stalkers zu finden?",a="Jungle Stalkers leben im Dschungel direkt südlich des Basislagers Grom'gol, nahe der Arena der Gurubashi.",al={"jungle stalker fundort","wo sind raptoren","jungle stalker federn wo"}},{q="Warum braucht Scharfseher Mok'thardin Federn von Jungle Stalkers?",a="Mok'thardin verbindet durch ein schamanistisches Ritual Kuriositäten aus dem Dschungel und Bestientrophäen zu einem verzauberten Werkzeug, das der Horde und dem Kriegshäuptling helfen soll.",al={"zweck der federn","warum stalker-federn","mok'thardins ritual"}},{q="Was ging dieser Bitte voraus?",a="Vor dieser Bitte habt Ihr Mok'thardin geholfen, die Raubkatzen des Tals zu jagen und die ersten Bestandteile für seine geplante Verzauberung zu sammeln.",al={"vorherige quest","vorheriger schritt"}}},fp="25,176,23.283.0,31.121.0,38.98.0,59.150.0,30.134.0"}
P.entries["quest:5722"] = {n="Die Suche nach dem verloren gegangenen Ranzen",s="Rahauro schickt Euch von der Anhöhe der Ältesten in Donnerfels in den Flammenschlund, wo Magatha Grimmtotem Nachricht von ihrem vermissten Gesandten Maur erwartet.",h="Rahauro schickt Euch von der Anhöhe der Ältesten in Donnerfels in den Flammenschlund, wo Magatha Grimmtotem...",kw={"die anhöhe der ältesten","magatha grimmtotem","maur grimmtotem","der flammenschlund","rahauro","die suche nach dem verloren gegangenen ranzen","donnerfels","troggs"},ang={["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Thrall sich auf finstere Kultisten unter der Hauptstadt konzentriert, während die Grimmtotem in derselben Höhle im Stillen ihre eigenen Ziele verfolgen.",["race:Tauren"]="Als Tauren könnte Euch Magathas Neugier auf die Kreaturen unter einer verbündeten Stadt beobachtenswert erscheinen. Die Ziele des Grimmtotemklans unterscheiden sich oft deutlich von Cairne Bluthufs offener Führung."},sec={{t="Eine Mission der Grimmtotem unter Orgrimmar",b="Magatha Grimmtotem erfährt auf der Anhöhe der Ältesten in Donnerfels, dass ihr Gesandter Maur Grimmtotem die Höhle unter Orgrimmar betreten hat. Er wollte die Troggs studieren und versuchen, mit ihnen zu verhandeln, kehrte aber nie zurück. Gerüchten zufolge fand er kurz vor seinem Tod etwas Ungewöhnliches. Während Kriegshäuptling Thrall und seine Berater sich um den Schattenrat im Flammenschlund kümmern, verfolgt der Grimmtotemklan seine eigenen Interessen."},{t="Der gefallene Gesandte",b="Rahauro, Magatha Grimmtotems Gehilfe, schickt in ihrem Auftrag Krieger in den Flammenschlund. Tief in seinen lavaerfüllten Tunneln liegt Maurs geschundener Leichnam nahe den Lagern der Troggs. Die Troggs erschlugen ihn mit primitiven Keulen und bloßen Fäusten, ließen seine Habseligkeiten jedoch unberührt. Sein Ranzen und die Geheimnisse, nach denen er suchte, warten noch darauf, von Magathas Handlangern geborgen zu werden."}},faq={{q="Wer schickt Abenteurer auf diese Quest?",a="Rahauro, Magatha Grimmtotems Gehilfe auf der Anhöhe der Ältesten in Donnerfels, schickt Euch in den Flammenschlund.",al={"questgeber","wer startet die suche nach dem verloren gegangenen ranzen","wo quest annehmen"}},{q="Wer ist Maur Grimmtotem?",a="Maur Grimmtotem war Magathas Gesandter. Er betrat den Flammenschlund, um die Troggs zu studieren und zu versuchen, sich mit ihnen zu verständigen, doch sie erschlugen ihn tief in der Höhle.",al={"maur grimmtotem","wer war maur","was geschah mit maur"}},{q="Warum interessierte sich Magatha Grimmtotem für den Flammenschlund?",a="Magatha interessierte sich für die Troggs unter Orgrimmar und schickte Maur, um zu versuchen, sich mit ihnen zu verständigen. Nachdem er etwas Ungewöhnliches unter ihnen entdeckt hatte, wollte sie, dass seine Entdeckung zu ihr gebracht wurde.",al={"magatha troggs","warum interessiert sich magatha für den flammenschlund","warum maur schicken"}},{q="Wo befindet sich Maur Grimmtotems Leichnam?",a="Maurs Leichnam liegt tief im Flammenschlund unter Orgrimmar, nahe den Gebieten der Troggs entlang der unterirdischen Pfade.",al={"maur finden","maur grimmtotem fundort","wo ist maurs leichnam"}},{q="Haben die Troggs Maur nach seinem Tod ausgeplündert?",a="Nein. Die Troggs ließen Maurs Kleidung und seinen Ranzen neben seinen geschundenen Überresten liegen.",al={"trogg beute","wurde maur ausgeraubt"}},{q="Was geschieht, nachdem Maurs Leichnam gefunden wurde?",a="Der Fund von Maurs Leichnam führt zum nächsten Schritt, Returning the Lost Satchel. Ihr bringt seinen Ranzen mit seinen Erkenntnissen zu Magatha Grimmtotem in Donnerfels.",al={"folgequest","nächste quest nach verlorenem ranzen","was mit dem ranzen tun"}}},fx={["1d6b392d"]={q="Warum möchte Rahauro, dass Maurs Tasche geborgen wird?",a="Rahauro handelt direkt im Auftrag von Magatha Grimmtotem. Magatha erfuhr, dass ihr Diener Maur etwas Ungewöhnliches tief im Inneren von Der Flammenschlund entdeckte, bevor er bei dem Versuch, mit den Troggs zu kommunizieren, sein Ende fand. Was auch immer Maur entdeckte, erreichte nie Donnerfels, und Magatha weigert sich, potenziell wertvolle Geheimnisse oder Relikte in die dunklen Kavernen unter Orgrimmar entgleiten zu lassen.",al={"warum möchte rahauro, dass dies erledigt wird","rahauro motiv","warum maurs tasche finden"}},["0cb3748c"]={q="Warum schickt Rahauro einen Abenteurer anstatt Grimmtotem-Krieger?",a="Sich in den Flammenschlund zu wagen, erfordert das Eindringen in den feurigen Unterleib von Orgrimmar, einem Gebiet, das fernab der Grenzen von Donnerfels von wilden Troggs und dunklen Kultisten wimmelt. Offizielle Grimmtotem-Krieger oder Stammeswachen in die Tiefen der Hauptstadt zu schicken, würde unerwünschte Aufmerksamkeit der orcischen Behörden auf sich ziehen. Einen fähigen Abenteurer anzuheuern, erlaubt es Magatha, Maurs Funde diskret zu bergen, ohne Verdacht bei der Führung der Horde zu erregen.",al={"warum mich schicken","warum keine wachen aus donnerfels","warum ein abenteurer"}}},fp="30,138,37.404.0,19.350.1,36.104.0,22.169.0,55.192.0,41.116.0,43.78.0,40.151.1"}
P.entries["quest:5723"] = {n="Die Kraft des Feindes wird auf die Probe gestellt",s="In Donnerfels reagiert Rahauro auf das Gemetzel an Magatha Grimmtotems Gesandten unter Orgrimmar. Er schickt Krieger in den Flammenschlund, um die Reihen der Troggs zu lichten.",h="In Donnerfels reagiert Rahauro auf das Gemetzel an Magatha Grimmtotems Gesandten unter Orgrimmar.",kw={"die anhöhe der ältesten","magatha grimmtotem","orgrimmar","der flammenschlund","rahauro","die kraft des feindes wird auf die probe gestellt","donnerfels","troggs"},ang={["class:Shaman"]="Als Schamane begegnet Ihr in den Lavatunneln spirituellen Vertretern der Troggs, die urtümliche Elemente beherrschen, einem groben Spiegelbild Eurer ehrwürdigen Traditionen.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Donnerfels Krieger und Mittel einsetzt, um Orgrimmars Fundamente zu schützen.",["race:Orc"]="Als Orc helft Ihr, das Herz Eurer Hauptstadt vor Troggs zu schützen, die sich unter der Stadt hindurchgraben.",["race:Tauren"]="Als Taure übt Ihr im Namen der Anhöhe der Ältesten Vergeltung für die im Flammenschlund getöteten Diplomaten."},sec={{t="Diplomatie trifft auf Wildheit",b="Magatha Grimmtotem schickte taurische Gesandte in die feurigen Tiefen unter Orgrimmar, um mit den Troggs Frieden zu schließen. Die Kreaturen schlachteten die Abgesandten bei ihrer Ankunft ab. Magatha sah in dem Massaker eine Beleidigung der Tauren und eine wachsende Gefahr für die Horde. Also beschloss sie, mit Gewalt zu antworten."},{t="Die Bedrohung unter Orgrimmar",b="Von Donnerfels aus führt Rahauro Magathas Befehle aus. Er schickt Krieger in den Flammenschlund, um Krieger und Schamanen der Troggs aufzuspüren und zu töten. Die Horde stößt tief in ihre unterirdische Heimat vor und dezimiert sie, bevor sie durch die Tunnel nach Orgrimmar strömen können."}},faq={{q="Warum wird eine Quest für einen Dungeon in Orgrimmar in Donnerfels vergeben?",a="Die Führung der Tauren in Donnerfels erteilte den Auftrag. Magatha Grimmtotem schickte Diplomaten in den Flammenschlund, um die Troggs zu treffen. Nachdem die Troggs sie abgeschlachtet hatten, versammelte ihr Gehilfe Rahauro auf der Anhöhe der Ältesten Krieger, um sie zu rächen.",al={"warum donnerfels","questbeginn donnerfels","rahauro standort"}},{q="Wer ist Rahauro?",a="Rahauro ist ein Taure, der von der Anhöhe der Ältesten in Donnerfels aus Expeditionen in den Flammenschlund leitet. Er handelt im Auftrag von Magatha Grimmtotem und entsendet Krieger, um Troggs zu töten und bei früheren gescheiterten diplomatischen Missionen verlorene Relikte zurückzuholen.",al={"wer ist rahauro","rahauro npc","rahauro anhöhe der ältesten"}},{q="Warum versuchte Magatha Grimmtotem, mit den Troggs Frieden zu schließen?",a="Magatha Grimmtotem entsandte die Gesandten als Zeichen ihres guten Willens und hoffte, mit den unterirdischen Wesen Frieden zu schließen, statt Blut zu vergießen. Die Troggs schlachteten ihre Abgesandten bei deren Ankunft ab und zeigten keinerlei Verhandlungsbereitschaft.",al={"warum frieden mit troggs","magatha trogg-diplomatie","warum mit troggs verhandeln"}},{q="Welche Feinde müssen für diesen Auftrag getötet werden?",a="Ihr betretet den Flammenschlund unter Orgrimmar, um die Troggs und Schamanen des Flammenschlunds zu töten. Ihr Tod schwächt die vordersten Reihen der Troggs und deren magische Unterstützung.",al={"welche gegner töten","questziele","ragefire troggs"}},{q="Lässt sich diese Quest zusammen mit anderen Dungeonaufträgen erledigen?",a="Ja. Rahauro bietet auch Searching for the Lost Satchel an, wobei Ihr in derselben Schlucht die sterblichen Überreste der gescheiterten diplomatischen Gesandtschaft finden sollt. Ihr könnt beide Aufträge gemeinsam angehen.",al={"andere flammenschlund-quests","quest verlorener rucksack","flammenschlund-quests"}},{q="Woher kommen die Troggs?",a="Die Troggs kamen aus tiefen vulkanischen Spalten unter Durotar hervor. Selbst nach den Kämpfen weiß die Horde kaum, woher diese Höhlenbewohner kamen oder warum sie sich gerade jetzt nach Orgrimmar hinaufgraben.",al={"trogg-ursprung flammenschlund","woher kommen troggs","warum sind troggs unter orgrimmar"}}},fx={["4ba56403"]={q="Warum möchte Rahauro, dass Ihr gegen die Troggs im Flammenschlund kämpft?",a="Rahauro handelt auf Befehl von Magatha Grimmtotem. Magatha versuchte ursprünglich, friedlichen Kontakt mit den Troggs herzustellen, die unter Orgrimmar auftauchten, aber die Kreaturen schlachteten ihre Gesandten ab. Da sie eine solche Beleidigung nicht tolerieren wollte und die unterirdischen Bestien als direkte Gefahr für die gesamte Horde ansah, ließ sie durch Rahauro ausrichten, deren Zahl zu dezimieren, bevor sie die orcische Hauptstadt überrennen.",al={"warum troggs töten","rahauro motiv","warum will magatha, dass troggs sterben"}},["5de83fed"]={q="Gegen wen werdet Ihr in den Flammenschlund geschickt, um zu kämpfen?",a="Ihr werdet ausgesandt, um Ragefire-Troggs und ihren Schamanen tief im Inneren der vulkanischen Kluft unter Orgrimmar zu jagen. Diese aggressiven, primitiven Wilden tauchten aus unterirdischen Tunneln auf und wiesen die friedlichen Annäherungsversuche der Tauren gewaltsam zurück, ermordeten Magathas Abgesandte und errichteten direkt unter der Stadt einen wilden Stützpunkt.",al={"feinde im flammenschlund","wer sind die troggs","gegen wen kämpfen wir"}}},fp="27,165,24.289.0,28.274.0,68.234.0,15.226.0,52.220.0,44.162.0,58.177.0,33.204.0"}
P.entries["quest:5724"] = {n="Wiederbeschaffung des verloren gegangenen Ranzens",s="Im Flammenschlund unter Orgrimmar findet Ihr Maur Grimmtotems Ranzen und bringt ihn zu Rahauro auf der Anhöhe der Ältesten in Donnerfels.",h="Im Flammenschlund unter Orgrimmar findet Ihr Maur Grimmtotems Ranzen und bringt ihn zu Rahauro auf der Anhöhe...",kw={"die anhöhe der ältesten","grimmtotemranzen","magatha","maur grimmtotem","der flammenschlund","rahauro","wiederbeschaffung des verloren gegangenen ranzens","donnerfels"},ang={["faction:Horde"]="Troggs und Kultisten bedrohen die Tunnel unter Orgrimmar. Auch Agenten des Grimmtotemklans sind unter Thralls Festung zugegen, was unbeantwortete politische Fragen aufwirft.",["race:Tauren"]="Der Grimmtotemklan hat ein angespanntes Verhältnis zu Cairne Bluthufs Volk. Jede geheime Operation von Magathas Anhängern in Orgrimmar gibt Anlass zu Misstrauen."},sec={{t="Ein grausiger Fund",b="Troggs erschlugen Maur Grimmtotem in den feurigen Tiefen des Flammenschlunds unter Orgrimmar. Selbst im Tod hielten seine Arme seinen persönlichen Ranzen fest umschlungen. Ihn aus seinem Griff zu lösen, gibt Euch den einzigen Hinweis darauf, warum ein Mitglied des Grimmtotemklans die vulkanischen Höhlen unter Thralls Hauptstadt betrat."},{t="Magathas Interesse",b="Rahauro nimmt den Ranzen auf der Anhöhe der Ältesten entgegen und versucht herauszufinden, warum ein Angehöriger von Magatha Grimmtotems Klan unnötig starb. Magatha Grimmtotem selbst beaufsichtigte das Unterfangen, und Rahauro überreicht eine von der Elder Crone genehmigte Belohnung. Nur die Führung des Grimmtotemklans weiß, was Maur bei sich trug oder warum Magatha ihn in Orgrimmars troggverseuchte Klüfte schickte."}},faq={{q="Wo befindet sich Maur Grimmtotem?",a="Maur Grimmtotems Leichnam liegt tief im Flammenschlund unter Orgrimmar, umgeben von feindseligen Troggs.",al={"maur grimmtotem leichnam","maur grimmtotem finden","wo ist maur"}},{q="Bei wem gebe ich den Ranzen ab?",a="Bringt den Grimmtotemranzen zu Rahauro auf der Anhöhe der Ältesten in Donnerfels.",al={"verlorenen ranzen abgeben","wo ist rahauro","ranzen abgeben"}},{q="Warum war Maur Grimmtotem im Flammenschlund?",a="Rahauro sagt, er wisse nicht, warum Magathas Klanangehöriger unnötig sterben musste. Magatha Grimmtotem ordnete die Bergung persönlich an, was darauf hindeutet, dass Maur möglicherweise im Auftrag des Klans handelte.",al={"warum war maur im flammenschlund","maurs mission","was hat maur gemacht"}},{q="Was befindet sich im Grimmtotemranzen?",a="Der Inhalt des Ranzens wird dem Überbringer nie offenbart. Maur bewachte ihn bis zu seinem Tod erbittert, und er wird ungeöffnet in Magathas Namen an Rahauro übergeben.",al={"was war in der tasche","inhalt des ranzens"}},{q="Was hat Maur Grimmtotem getötet?",a="Wilde Troggs überfielen und töteten Maur in den Tunneln des Flammenschlunds.",al={"wie ist maur gestorben","wer hat maur getötet"}},{q="Wer steckt hinter diesem Auftrag?",a="Rahauro ist der Ansprechpartner auf der Anhöhe der Ältesten. Elder Crone Magatha Grimmtotem erteilt die Anweisung und genehmigt die Belohnung.",al={"wer hat rahauro geschickt","verbindung zu magatha"}}},fx={["5b8e763c"]={q="Warum möchte Maur Grimmtotem, dass seine Tasche zurückgegeben wird?",a="Maur Grimmtotem gab Euch diesen Auftrag nicht zu Lebzeiten – er starb, während er seine Tasche in den Tiefen von Der Flammenschlund umklammerte. Selbst als die Troggs ihn überwältigten, war sein letzter Akt, die Stammesgeheimnisse oder Wertsachen zu bewachen, die sich darin befanden. Die Rückgabe der Tasche ehrt dieses Opfer und erfüllt die Untersuchung, die Rahauro und Magatha Grimmtotem in die Wege geleitet haben, um herauszufinden, was mit ihrem Stammesmitglied geschah.",al={"maur grimmtotem motiv","warum tasche zurückgeben","warum möchte maur, dass die tasche zurückgegeben wird"}},["2bcdc4f2"]={q="Warum wurdet Ihr geschickt, um die Tasche zu bergen, anstatt der Wachen von Donnerfels?",a="Der Flammenschlund liegt tief unter den Straßen von Orgrimmar, weit entfernt von der Zuständigkeit der Stadtwachen von Donnerfels. Das Betreten der unterirdischen Tunnel erfordert das Vorbeischleichen an grausamen Troggs und Kultisten der Burning Blade. Anstatt einen diplomatischen oder militärischen Zwischenfall zu provozieren, indem man Streitkräfte aus Kalimdor durch die Tiefen einer verbündeten Hauptstadt marschieren lässt, verließ sich Rahauro auf fähige Abenteurer, um ihren gefallenen Stammesgenossen unauffällig aufzuspüren.",al={"warum ich, die verlorene tasche zurückzuholen","warum abenteurer für flammenschlund-tasche schicken","warum bergen wachen die tasche nicht"}}},fp="26,126,16.285.0,18.334.1,32.100.0,32.70.0,41.188.0,37.154.0,27.72.0,24.114.0"}
P.entries["quest:5725"] = {n="Die Macht zu Zerstören...",s="Von Unterstadt aus schickt Varimathras Abenteurer der Horde unter Orgrimmar. Fürstin Sylvanas Windläufer sucht zwei dunkle Folianten des Kults der Searing Blade, deren Macht ihren Krieg gegen die Geißel und den Lichkönig unterstützen soll.",h="Von Unterstadt aus schickt Varimathras Abenteurer der Horde unter Orgrimmar.",kw={"zauberformeln aus dem nether","lichkönig","der flammenschlund","searing blade","schattenzauber","sylvanas","unterstadt","varimathras"},ang={["class:Warlock"]="Als Hexenmeister entreißt Ihr leichtsinnigen Kultisten Schattenzauber und Zauberformeln aus dem Nether und nehmt ihnen damit gefährliches Geheimwissen der Legion aus den Händen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, Orgrimmars Fundamente zu sichern, indem Ihr die Searing Blade beseitigt. Die magische Beute gelangt in die Gewölbe von Unterstadt.",["race:Undead"]="Als Mitglied der Verlassenen überquert Ihr das große Meer, um Orgrimmars Untergrund zu plündern. Das dient Eurem Bündnis mit der Horde und dem Bestreben der Dunklen Fürstin, die Geißel zu vernichten."},sec={{t="Ein geliehenes Arsenal",b="Thralls Orcs jagen den Kult der Searing Blade unter ihrer Hauptstadt. Die Verlassenen begehren die okkulten Bestände des Kults. Auf Befehl von Sylvanas Windläufer schickt Varimathras Agenten in den Flammenschlund, um zwei dämonische Zauberbücher zu erbeuten: Schattenzauber und Zauberformeln aus dem Nether. Die Dunkle Fürstin glaubt, dass der disziplinierte Wille der Verlassenen diese Gaben besser nutzen kann als die niederen Kultisten."},{t="Der Krieg um Befreiung",b="Sobald die Folianten gesichert sind, erklärt Varimathras ihren Zweck. Ihre dunkle Magie soll Sylvanas' Feldzug gegen die Geißel stärken. Die Verlassenen hoffen, jeden Funken verbotener Macht zu erlangen, den Griff des Lichkönigs über Lordaeron zu brechen und die verbliebenen Untoten aus seiner geistigen Knechtschaft zu befreien."}},faq={{q="Warum will Varimathras Bücher aus den Tiefen unter Orgrimmar?",a="Kultisten der Searing Blade im Flammenschlund besitzen mächtige dämonische Folianten. Fürstin Sylvanas glaubt, dass die Kultisten ihr Wissen verschwenden, und will es gegen den Lichkönig wenden.",al={"warum varimathras flammenschlund","unterstadt flammenschlund quest grund","warum bücher stehlen"}},{q="Welche Bücher sollt Ihr beschaffen?",a="Ihr sollt zwei Zauberbücher von Kultisten und Hexenmeistern der Searing Blade beschaffen: Schattenzauber und Zauberformeln aus dem Nether.",al={"welche bücher","die macht zu zerstören bücher","flammenschlund bücher beute"}},{q="Wo hält sich Varimathras in Unterstadt auf?",a="Varimathras hält sich an der Seite von Fürstin Sylvanas Windläufer im Königsviertel von Unterstadt auf.",al={"varimathras aufenthaltsort","wo ist varimathras","abgabeort"}},{q="Wie hängt das mit den übergeordneten Zielen der Verlassenen zusammen?",a="Sylvanas sammelt jedes Mittel, das sie für ihren Krieg gegen die Geißel finden kann. Verbotenes dämonisches Geheimwissen könnte den Verlassenen helfen, die Herrschaft des Lichkönigs über die Untoten zu brechen.",al={"verlassene beweggründe","warum braucht sylvanas zauber","unterstadt lichkönig plan"}},{q="Weiß Thrall, dass die Verlassenen diese Bücher an sich nehmen?",a="Orgrimmars Anführer konzentrieren sich darauf, die Verräter und Dämonen unter ihren Straßen auszumerzen. Varimathras stellt den Auftrag zur Beschaffung der Bücher als diskrete Angelegenheit für die Dunkle Fürstin dar, nicht als offiziellen gemeinsamen Erlass der Horde.",al={"weiß thrall davon","orgrimmar unterstadt geheime bücher","shadow council bücher reaktion der orcs"}},{q="Wer sind die Searing Blade?",a="Die Searing Blade sind eine geheimniskrämerische Sekte des Shadow Council im Flammenschlund unter Orgrimmar. Ihre Mitglieder wirken direkt unter der Nase des Kriegshäuptlings dunkle dämonische Magie.",al={"was sind searing blade","searing blade flammenschlund","flammenschlund kultisten"}}},fx={fcfaa53d={q="Was sind die Schattenzauber und die Zauberformeln aus dem Nether?",a="Diese beiden Bände sind dunkle Zauberbücher, die die Brennende Legion ihren sterblichen Anhängern geschenkt hat. Sie enthalten mächtiges dämonisches Wissen und Shadow Magic, die die Kultisten der Brennenden Klinge nutzen, um die Pläne ihrer Meister voranzutreiben. Lady Sylvanas glaubt, dass solche Macht bei niederen Handlangern verschwendet ist, und beabsichtigt, die Zauberbücher an sich zu nehmen, um den Kampf der Verlassenen gegen den Lichkönig zu stärken.",al={"schattenzauber buch","zauberformeln aus dem nether","wofür sind die bücher"}},d6e166d9={q="Warum schickt Varimathras Euch statt der Königlichen Wache?",a="Varimathras hat hundert andere Aufgaben, die seine Aufmerksamkeit erfordern, und die Brennende Klinge versteckt sich in Höhlen tief unter Orgrimmar. Lady Sylvanas möchte, dass die beiden Zauberbücher des Kults für ihre eigenen Zwecke \"ausgeliehen\" werden, daher schickt Varimathras einen ehrgeizigen Abenteurer, um sie zu holen, und verspricht denjenigen, die der Dunklen Fürstin gut dienen, weitere Aufgaben.",al={"warum schickt man mich","warum nicht die königliche wache","warum geht varimathras nicht selbst"}}},fp="23,224,18.376.0,22.307.0,58.171.0,35.131.0,47.90.0,53.165.0,53.209.0,26.165.0"}
P.entries["quest:5726"] = {n="Verborgene Feinde",s="Thrall beginnt eine verdeckte Suche nach der Burning Blade in Durotar. Er bittet einen vielversprechenden jungen Abenteurer, eine Insigne des Leutnants aus der Knochenhöhle zu bergen, um Kultisten direkt unter den Augen der Horde aufzuspüren.",h="Thrall beginnt eine verdeckte Suche nach der Burning Blade in Durotar.",kw={"burning blade","durotar","verborgene feinde","insigne des leutnants","orgrimmar","die knochenhöhle","thrall"},ang={["class:Warlock"]="Als Hexenmeister der Horde müsst Ihr Euch unter Thralls strenger Aufsicht über die Teufelsmagie vorsichtig bewegen. Er ruft Euch dazu auf, Kultisten aufzuspüren, deren zügelloser Dienst an Dämonen Orgrimmars Überleben bedroht.",["faction:Horde"]="Als Mitglied der Horde vertraut Euch Kriegshäuptling Thrall an, das Herz der neuen Horde vor dämonischer Unterwanderung zu schützen.",["race:Orc"]="Als Orc kennt Ihr den Kampf, den Blutrausch und die Schande des Dämonenfluchs zu überwinden. Die Jagd auf die Burning Blade ist ein persönlicher Kampf, damit dämonische Verderbnis Euer Volk nicht erneut vergiftet."},sec={{t="Die Fäulnis in Durotar",b="In Durotar ringt die neue Horde um eine sichere Heimat, und Kriegshäuptling Thrall sieht sich Verrat aus den eigenen Reihen gegenüber. Die Burning Blade hat direkt vor Orgrimmars Toren Fuß gefasst. Ihre Kultisten nutzen die verbliebene dämonische Verderbnis aus und hungern nach dunkler Macht. Thrall braucht jemanden, der unbemerkt beobachten und lauschen kann."},{t="Die Knochenhöhle unterwandern",b="Die Knochenhöhle liegt östlich von Orgrimmar. Ihre zerklüfteten Höhlen beherbergen Hexenmeister, Leerwandler und fanatische Kultisten. Thrall schickt Euch los, um einem der Anführer der Burning Blade eine Insigne des Leutnants abzunehmen. Das Abzeichen soll Zugang zu den verborgenen Reihen des Kults gewähren, damit Thrall erfahren kann, wer dessen Bewegungen lenkt."}},faq={{q="Wer vergibt die Quest Verborgene Feinde?",a="Kriegshäuptling Thrall gibt sie Euch in Orgrimmars Valley of Wisdom, nachdem Ihr Euch bei Orgnil Narbenseele gemeldet habt.",al={"verborgene feinde questgeber","wer vergibt verborgene feinde","wo beginnt verborgene feinde"}},{q="Was ist das Ziel von Verborgene Feinde?",a="Thrall schickt Euch östlich von Orgrimmar in die Knochenhöhle, um Kultisten der Burning Blade zu töten und ihm eine Insigne des Leutnants zu bringen.",al={"verborgene feinde questziel","was wird für verborgene feinde benötigt"}},{q="Warum schickt Thrall nicht einfach seine Elitewachen, um die Knochenhöhle zu säubern?",a="Thrall fürchtet, ein offener Angriff würde die wahren Verschwörer entkommen lassen und die Verderbnis noch tiefer verbergen. Jemand, den der Kult nicht kennt, kann sich unbemerkt einen Zugang zu seinen Reihen verschaffen, ohne die hochrangigen Verräter dahinter zu warnen.",al={"warum thrall abenteurer braucht","warum nicht die armee schicken"}},{q="Was ist die Knochenhöhle?",a="Die Knochenhöhle ist ein abgelegenes Höhlensystem an Durotars Ostküste, nordöstlich von Orgrimmar. Die Burning Blade nutzt sie als verborgenen Stützpunkt und als Ort für Beschwörungen.",al={"wo liegt die knochenhöhle","was ist die knochenhöhle"}},{q="Wozu dient die Insigne des Leutnants?",a="Die Insigne des Leutnants belegt den Rang eines Kultisten. Thrall will damit einen Agenten tarnen und in die Burning Blade einschleusen, damit er herausfinden kann, wer ihre Unternehmungen lenkt.",al={"wozu dient die insigne","insigne des leutnants verwendung"}},{q="Welche anderen Quests lassen sich gleichzeitig abschließen?",a="Ihr könnt in der Knochenhöhle auch Halsbänder von Kultisten sammeln. Der Kultführer Gazz'uz trägt das Auge des brennenden Schatten bei sich, mit dem sich Burning Shadows beginnen lässt.",al={"knochenhöhle quests","quests in der knochenhöhle"}}},fx={aa12f8a2={q="Warum möchte Thrall die Burning Blade untersuchen?",a="Thrall betrachtet den Kult der Burning Blade als die größte interne Bedrohung für die junge Horde. Ein verräterischer, dämonenanbetender Zirkel, der direkt vor der Haustür von Orgrimmar wuchert, untergräbt alles, wofür die Orcs in Durotar geblutet haben, um es aufzubauen. Anstatt übereilt zuzuschlagen, ohne das volle Ausmaß ihrer Reichweite zu kennen, zielt der Kriegshäuptling darauf ab, aufzudecken, wie tief die Korruption sitzt, und sie an der Wurzel auszureißen, bevor sie ihre neue Heimat verzehrt.",al={"warum möchte thrall dies","thrall motiv hidden enemies","warum burning blade untersuchen"}},d2691c1c={q="Wer sind die Kultisten der Burning Blade in Die Knochenhöhle?",a="Ihr jagt die Agenten und Hexenmeister der Burning Blade, die sich in Die Knochenhöhle verstecken, östlich von Orgrimmar. Einst ein stolzer Orc-Clan, ist der Überrest zu einem Schattenkult verkommen, der sich dämonischer Korruption und schattenhafter Manipulation verschrieben hat. Verschanzt in geheimen Höhlen in der Nähe der Hauptstadt weben sie ein Netz aus Verrat, Gier und dunkler Magie, das direkt darauf abzielt, Thralls neue Horde von innen heraus zu unterwandern.",al={"wer sind burning blade in die knochenhöhle","feinde in die knochenhöhle","ziel von hidden enemies"}}},fp="14,218,22.308.0,23.293.0,35.101.0,35.118.0,66.236.0,19.158.0,43.187.0,54.143.0"}
P.entries["quest:5727"] = {n="Verborgene Feinde",s="In Orgrimmar schickt Thrall Euch los, um herauszufinden, was die Burning Blade weiß. Kultaktivitäten in der Knochenhöhle haben Euch mit der Insigne eines Leutnants zu Neeru Feuerklinge geführt, um seine Loyalität zu prüfen.",h="In Orgrimmar schickt Thrall Euch los, um herauszufinden, was die Burning Blade weiß.",kw={"burning blade","die kluft der schatten","insigne","neeru fireblade","orgrimmar","der flammenschlund","schattenrat","thrall"},ang={["class:Warlock"]="Als Hexenmeister erlebt Ihr womöglich, wie Neeru einen Platz für Hexenmeister in der Horde beansprucht. Sein Verrat droht allen, die unter Thralls Herrschaft die Teufelskünste ausüben, schwere Verurteilung einzubringen.",["faction:Horde"]="Für die Horde bedrohen dämonische Kulte unter Orgrimmars Fundamenten das Überleben der jungen Nation.",["race:Orc"]="Als Ork wisst Ihr, dass die Rückkehr des Schattenrats unter Eure Hauptstadt an Draenors dunkle Vergangenheit erinnert. Wer Blutdurst und dämonischer Verderbnis zu entkommen sucht, trägt diese Bürde."},sec={{t="Die List des Kriegshäuptlings",b="Thrall setzt auf List statt auf einen Angriff auf die Kluft der Schatten. Er weiß, dass Neeru Feuerklinge vorgibt, der Horde zu dienen, während er heimlich den Kultisten hilft. Ein direkter Angriff könnte Neerus Meister warnen und die Spur zur Verschwörung abreißen lassen. Deshalb gibt Thrall Euch eine Insigne, die dem Kult in Durotar abgenommen wurde, und bittet Euch, als Initiand herauszufinden, was Neeru weiß."},{t="Der verborgene Meister der Kluft",b="Neeru Feuerklinge wartet in der Kluft der Schatten vor dem Eingang zum Flammenschlund. Er hält Euch für einen frisch beförderten Leutnant und spottet über Thralls Unwissenheit. Neeru sagt, die Burning Blade und ihre Ableger, darunter die Searing Blade, unterstünden dem Schattenrat, der der Brennenden Legion dient. Er prahlt damit, Thrall dazu gebracht zu haben, loyale Soldaten gegen die Kultisten im Schlund zu schicken und mit den Streitkräften des Kriegshäuptlings die Schwachen auszusortieren."}},faq={{q="Warum lässt Thrall Neeru am Leben, wenn er weiß, dass er ein Verräter ist?",a="Thrall lässt Neeru am Leben, um ihn beobachten zu können. Würde Neeru getötet, könnte der Schattenrat ihn durch jemanden ersetzen, der schwerer zu enttarnen ist. Unter genauer Beobachtung könnte Neeru ungewollt die Bewegungen des Kults in Orgrimmar verraten.",al={"warum thrall neeru vertraut","warum neeru am leben lassen","neeru verräter"}},{q="Wer ist Neeru Feuerklinge?",a="Neeru Feuerklinge ist ein orkischer Hexenmeister, der in der Kluft der Schatten lebt. Er behauptet, Thrall dabei zu helfen, Hexenmeister zu pflichtbewussten Dienern der Horde zu machen, führt aber heimlich für den Schattenrat die Burning Blade unter der Stadt.",al={"neerus vorgeschichte","wer ist neeru"}},{q="In welcher Beziehung stehen die Burning Blade und der Schattenrat zueinander?",a="Die Burning Blade ist ein Arm des Schattenrats und keine unabhängige Sekte. Der Rat kontrolliert auch Kulte wie die Searing Blade im Flammenschlund und spaltet und täuscht ehrgeizige Anhänger unter der Herrschaft der Brennenden Legion.",al={"verbindung burning blade schattenrat","gehört die burning blade zum schattenrat"}},{q="Wer führt die Kultisten im Flammenschlund an?",a="Bazzalan, ein Satyr, und Jergosh der Herbeirufer, ein orkischer Hexenmeister, führen die Searing Blade im Flammenschlund an. Neeru schickt Thralls Abenteurer gegen sie aus, um die Reihen der Hordetreuen zu lichten und seine Untergebenen zu prüfen.",al={"anführer im flammenschlund","anführer der searing blade"}},{q="Wie habe ich die Insigne des Leutnants erhalten?",a="Ihr habt die Insigne des Leutnants während Thralls erster Untersuchung der Kultaktivitäten in Durotar geborgen. Sie stammte von Kultisten der Burning Blade in der Knochenhöhle.",al={"woher stammt die insigne des leutnants","herkunft der insigne"}}},fx={["7a6d2fe3"]={q="Warum schickt Thrall mich zu Neeru, anstatt ihn selbst zu konfrontieren?",a="Thrall kann Neeru Feuerklinge nicht offen befragen oder gegen ihn vorgehen, ohne den Hexenmeister darauf aufmerksam zu machen, dass sein Verrat aufgedeckt wurde. Neeru glaubt, dass er immer noch das volle Vertrauen des Kriegshäuptlings genießt und dass er unentdeckt innerhalb von Die Kluft agiert. Indem er einen unbekannten Agenten schickt, der das Abzeichen eines gefallenen Kult-Leutnants trägt, etabliert Thrall einen unwissenden Informanten im Inneren. Ihr könnt Neerus Netzwerk infiltrieren, wichtige Informationen bezüglich der Reichweite des Schattenrats sammeln und wichtige Informationen an den Kriegshäuptling zurückgeben, ohne Thralls strategischen Vorteil zu gefährden.",al={"warum mich zu neeru schicken","warum braucht thrall mich","warum nicht neeru direkt konfrontieren"}}},fp="14,185,21.358.0,25.454.1,61.223.1,23.222.1,74.233.1,45.198.0,43.155.0"}
P.entries["quest:5728"] = {n="Verborgene Feinde",s="Thrall schickt Euch gegen die Searing Blade unter Orgrimmar. Ihr habt Neeru Fireblades Vertrauen gewonnen, indem Ihr vorgetäuscht habt, die Ziele des Kults zu teilen. Nun schickt Thrall Euch in den Flammenschlund, um gegen dessen Anführer vorzugehen.",h="Thrall schickt Euch gegen die Searing Blade unter Orgrimmar.",kw={"bazzalan","die kluft der schatten","verborgene feinde","jergosh der herbeirufer","neeru fireblade","der flammenschlund","searing blade","shadow council","thrall"},ang={["class:Warlock"]="Als Hexenmeister wisst Ihr, dass Thrall dunkle Künste zur Verteidigung der Horde duldet. Jergosh und die Searing Blade haben sich dämonischen Meistern verschrieben und die Horde verraten.",["faction:Horde"]="Als Mitglied der Horde stellt Ihr Euch dämonischer Verderbnis im Herzen Durotars. Sie bedroht alles, was die neue Horde sich erkämpft hat. Die Säuberung des Flammenschlunds hilft, ihre hart errungene Freiheit zu bewahren.",["race:Orc"]="Als Orc, der Erlösung vom Blutrausch sucht, stellt Ihr Euch den Überresten des Shadow Council unter Orgrimmar. Ihre Vernichtung ist eine Frage des kulturellen Überlebens und der Ehre."},sec={{t="Ein Krebsgeschwür unter den Straßen",b="Orgrimmar wurde als Zuflucht für ein freies Volk der Orcs erbaut. Doch unter seinen Märkten führt die Kluft der Schatten in die Tunnel des Flammenschlunds. Dort sammeln Überreste des Shadow Council als Searing Blade neue Kräfte. Sie praktizieren dunkle Künste und schmieden Pläne, um die junge Horde aus dem Inneren ihrer eigenen Hauptstadt heraus an sich zu reißen."},{t="Als Doppelagent",b="Ein direkter Angriff ohne vorherige Erkenntnisse würde das Netzwerk des Shadow Council unversehrt lassen. Thrall wendet sich an Euch, um von Neeru Feuerklinge zu erfahren, einem scheinbar kooperationsbereiten Hexenmeister in der Kluft der Schatten. Neeru glaubt, Ihr teilt die Ziele des Kults. Daher verrät er die Namen seiner Anführer im Untergrund: Bazzalan, ein verdorbener Satyr, und Jergosh der Herbeirufer, ein Hexenmeister."},{t="Die Searing Blade enthaupten",b="Thrall schickt Euch in den Flammenschlund, um Bazzalan und Jergosh zu töten. Ihr Tod stürzt die Kultisten ins Chaos, doch Neeru darf nicht erfahren, wer sie getötet hat. Thrall plant, den Hexenmeister weiter beobachten zu lassen. Ohne seine Anführer gerät der Kult ins Wanken, und die junge Stadt der Horde gewinnt eine kostbare Atempause."}},faq={{q="Wer befiehlt den Anschlag in Verborgene Feinde?",a="Kriegshäuptling Thrall befiehlt den Angriff vom Valley of Wisdom in Orgrimmar aus. Er vertraut Euch heikle Aufgaben an, um den Untergrund der Stadt zu sichern.",al={"wer vergibt verborgene feinde","verborgene feinde questgeber","thrall flammenschlund quest"}},{q="Warum lässt Thrall Neeru Feuerklinge nicht einfach hinrichten?",a="Thrall lässt Neeru am Leben und unter Beobachtung. Den Verräter zu kennen, erlaubt den Spähern des Kriegshäuptlings, den Nachrichtenaustausch des Shadow Council zu verfolgen und Verschwörungen vorauszusehen, während der Kult keinen Spielraum erhält, heimlich einen Ersatz einzusetzen.",al={"warum neeru nicht töten","warum neeru am leben lassen","neeru fireblade verräter"}},{q="Wo befinden sich Bazzalan und Jergosh der Herbeirufer?",a="Bazzalan und Jergosh der Herbeirufer befinden sich tief im Flammenschlund, erreichbar durch die Kluft der Schatten in Orgrimmar. Jergosh befehligt die Kultisten von einem vulkanischen Felsvorsprung aus, während Bazzalan in einer nahe gelegenen, höher gelegenen Höhle lauert.",al={"wo ist bazzalan","wo ist jergosh","flammenschlund bosse"}},{q="Wer sind die Searing Blade?",a="Die Searing Blade sind eine örtliche Sekte, die mit der Burning Blade und dem Shadow Council verbündet ist. Ihre Mitglieder verehren dämonische Mächte und praktizieren unter Orgrimmar Teufelsmagie. Sie wollen Thrall stürzen und die Horde erneut versklaven.",al={"was sind die searing blade","searing blade kult","burning blade orgrimmar"}},{q="Warum arbeitet ein Satyr wie Bazzalan unter einer Stadt der Orcs?",a="Satyrn sind uralte Diener der Brennenden Legion. Unter der Stadt der Orcs wirkt Bazzalan als dämonischer Drahtzieher und Anstifter. Er leitet die sterblichen Kultisten der Searing Blade dabei an, unter Thralls Füßen den Willen der Legion auszuführen.",al={"warum ist ein satyr in orgrimmar","bazzalan hintergrundgeschichte","satyr im flammenschlund"}},{q="Wie fügt sich diese Quest in den gesamten Durchlauf durch den Flammenschlund ein?",a="Verborgene Feinde bringt Thralls Bemühungen, die Searing Blade zu unterwandern, zu ihrem Höhepunkt. Die Quest verbindet sich mit anderen Aufträgen im Flammenschlund zu einem koordinierten Angriff gegen die wichtigsten humanoiden Gegner dort.",al={"ist verborgene feinde im flammenschlund","rfc questreihe","verborgene feinde questreihe"}}},fx={["53ca461d"]={q="Warum möchte Thrall, dass dies erledigt wird?",a="Der Schattenrat versucht, Orgrimmar zu ergreifen und die Horde aus Thralls Griff zu reißen. Nachdem er von Neeru Feuerklinge erfahren hat, dass die Searing Blade direkt unter den Straßen der Stadt operiert, erkennt Thrall ihre Anführer als eine unmittelbare Gefahr. Die Ausschaltung von Bazzalan und Jergosh versetzt den unterirdischen Operationen des Kults einen unmittelbaren Schlag und stürzt ihre Planung ins Chaos, bevor sie Orgrimmar von unten angreifen können.",al={"warum möchte thrall bazzalan tot sehen","thrall motiv hidden enemies","warum searing blade-anführer töten"}},["0041999b"]={q="Wen werdet Ihr ausgesandt zu töten?",a="Ihr werdet ausgesandt, um Bazzalan und Jergosh der Herbeirufer zu eliminieren, die Anführer des Kults der Searing Blade, die tief im Inneren von Der Flammenschlund nisten. Bazzalan ist ein Satyr, der dunkle Kräfte aus den Schatten befehligt, während Jergosh ein mächtiger Hexenmeister ist, der Kultrituale leitet. Beide unterstehen Neeru Feuerklinge und dienen als operatives Rückgrat des Kults in den Kavernen unter Orgrimmar.",al={"wer sind die ziele","wer für hidden enemies töten","bazzalan und jergosh"}},["1b8ff306"]={q="Warum schickt Thrall Euch anstelle der Stadtwachen?",a="Eine Armee von Wachen aus Orgrimmar in den Schlund zu schicken, würde das Wissen des Kriegshäuptlings um die Verschwörung offenlegen und Eure Tarnung sofort auffliegen lassen. Da Ihr erfolgreich die Burning Blade infiltriert und Euch das Vertrauen von Neeru Feuerklinge verdient habt, könnt Ihr Euch unbemerkt in den Flammenschlund schleichen. Thrall muss die Anführer ausschalten, ohne dass Neeru entdeckt, dass sein vermeintlicher Rekrut der Attentäter war, um Eure Identität für zukünftige Informationen zu wahren.",al={"warum schickt man mich","warum keine wachen aus orgrimmar","warum nicht die kor'kron schicken"}}},fp="14,206,28.306.0,24.356.1,30.298.2,37.140.0,48.207.1,51.217.0,26.220.0,57.224.0,60.191.0"}
P.entries["quest:5729"] = {n="Verborgene Feinde",s="In Orgrimmar reicht Thralls wachsamer Blick bis in die Kluft der Schatten. Nachdem Bazzalan und Jergosh der Herbeirufer unter der Stadt sterben, schickt Thrall Euch los, um Neeru Fireblades Vertrauen zu gewinnen.",h="In Orgrimmar reicht Thralls wachsamer Blick bis in die Kluft der Schatten.",kw={"bazzalan","burning blade","die kluft der schatten","verborgene feinde","jergosh","neeru fireblade","orgrimmar","der flammenschlund","schattenrat","thrall"},ang={["class:Rogue"]="Als Schurke kennt Ihr den Ablauf einer Infiltration: Zuerst schaltet Ihr das Netzwerk einer Kontaktperson aus, dann tretet Ihr als ihr Vertrauter an dessen Stelle.",["class:Warlock"]="Als Hexenmeister findet Ihr Neeru Feuerklinge unter den Hexenmeisterlehrern in der Kluft der Schatten. Sein Platz dort zeigt, wie nahe Thralls neue Horde dunklerer Magie kommt, ohne der Verderbnis zu erliegen.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Thrall neben Diplomatie und Staatskunst auch Gegenspionage einsetzt, um Orgrimmar von innen zu sichern.",["race:Orc"]="Als Ork wisst Ihr, dass die Ausmerzung der Burning Blade aus Orgrimmars Untergrund Eure Ehre schützt, während Euer Volk das dämonische Erbe der alten Horde abschüttelt."},sec={{t="Thralls Schachzug",b="Thrall erkennt eine Gelegenheit, nachdem Bazzalan und Jergosh der Herbeirufer im Flammenschlund getötet wurden. Er beschließt, Neeru Feuerklinge auf seinem Posten zu belassen. Neeru hat die Leutnants verloren, die den örtlichen Kult anführten. Also schickt Thrall Euch zurück in die Kluft der Schatten, wo Ihr Euch als Verbündeter anbietet, der diese Lücke füllen kann."},{t="Die Täuschung des Hexenmeisters",b="Neeru Feuerklinge tobt in der Kluft der Schatten über die Niederlage seiner Mitverschwörer. Er weiß nicht, dass Ihr sie auf Thralls Befehl hingerichtet habt. Stattdessen verflucht er die Gutmenschen, die den Flammenschlund ins Verderben gestürzt haben. Überrumpelt beginnt Neeru, Euch gegenüber seine Wachsamkeit sinken zu lassen. Thrall kann den Einfluss des Schattenrats nun aus dem Inneren Orgrimmars beobachten."}},faq={{q="Warum lässt Thrall Neeru Feuerklinge nicht einfach sofort hinrichten?",a="Thrall belässt Neeru auf seinem Posten, um ihn zu beobachten, während Neeru glaubt, seine Tarnung sei weiterhin intakt. Mit Euch als eingeschleustem Vertrauten kann Thrall die Nachrichten der Burning Blade überwachen und ihre Verbindungen zum Schattenrat verfolgen.",al={"warum neeru verschonen","warum lässt thrall neeru leben","neeru am leben"}},{q="Wer waren Bazzalan und Jergosh?",a="Bazzalan war ein Satyr, und Jergosh der Herbeirufer war ein orkischer Hexenmeister. Sie führten den Kult der Searing Blade tief im Flammenschlund unter Orgrimmar an, bevor Thrall ihren Tod befahl.",al={"bazzalan","jergosh","wer starb im flammenschlund"}},{q="Weiß Neeru, dass Ihr seine Leutnants getötet habt?",a="Nein. Neeru glaubt, dass Thralls Agenten seine Leutnants überrascht und getötet haben. Er weiß nicht, dass Ihr die Hinrichtungen ausgeführt habt und ihm nun Beileid und Hilfe anbietet.",al={"weiß neeru bescheid","neeru weiß wer sie getötet hat"}},{q="Wo befindet sich Neeru Feuerklinge?",a="Neeru Feuerklinge befindet sich in der Kluft der Schatten, einer Höhle unter dem Herzen Orgrimmars, wo sich Hexenmeister, Schurken und Schattenwirker abseits der übrigen Stadt versammeln.",al={"neerus standort","neeru finden","wo ist neeru fireblade"}},{q="Was ist die Burning Blade?",a="Die Burning Blade war zunächst ein wilder Klan aus Draenor und wurde dann zu einem dämonischen Kult, den der Schattenrat lenkte. In Kalimdor versuchen ihre Überreste, Thralls neue Horde zu untergraben und sie erneut in dämonische Knechtschaft zu führen.",al={"burning blade","kult der burning blade"}},{q="Was geschieht nach dem Gespräch mit Neeru?",a="Nachdem Ihr Neerus Vertrauen gewonnen und seine Bestürzung über die Verluste im Flammenschlund gehört habt, kehrt Ihr zu Thrall in Grommash Hold zurück, um Euren Erfolg zu melden und die Infiltrationsquestreihe abzuschließen.",al={"was kommt als nächstes","questfortsetzung"}}},fx={["29529508"]={q="Warum schickt Thrall Euch zu Neeru Feuerklinge, anstatt ihn selbst zur Rede zu stellen?",a="Thrall kann Neeru nicht offen zur Rede stellen oder festnehmen, ohne den Rest des Schattenrats und den in ganz Durotar verwurzelten Kult der Burning Blade zu warnen. Neeru glaubt, Thralls Vertrauen zu genießen, und Thrall beabsichtigt, ihn gegen ihre Feinde zu benutzen. Indem er Euch mit den Insignien der Burning Blade losschickt, die Ihr gefunden habt, prüft Thrall, ob Neeru Euch für einen der Seinen hält; Neeru heißt Euch als Mitglied und sogar als aufstrebenden Leutnant willkommen und spricht offen. Eine offizielle Wache würde sofortigen Verdacht erregen, doch Ihr könnt heimlich ihre Geheimnisse von innen heraus in Erfahrung bringen.",al={"warum mich zu neeru schicken","warum thrall neeru nicht konfrontiert","warum einen agenten fuer neeru nutzen"}}},fp="14,172,15.291.0,23.359.1,60.207.0,30.178.0,46.164.0,33.165.0,26.210.0,37.188.1"}
P.entries["quest:573"] = {n="Mok'Thardins Verzauberung",s="Im Basislager Grom'gol sucht Scharfseher Mok'thardin das letzte heilige Wasser für ein zeremonielles Halsband. Er schickt Euch zu einer Heiligen Quelle auf den südlichen Klippen nahe dem westlichen Meer, wo Naga-Forscher eingetroffen sind.",h="Im Basislager Grom'gol sucht Scharfseher Mok'thardin das letzte heilige Wasser für ein zeremonielles Halsband.",kw={"zeremonielles halsband","grom'gol","heilige quelle","wasser der heiligen quelle","mok'thardin","naga-forscher","schlingendorntal"},ang={["faction:Horde"]="Als Champion der Horde könnt Ihr Scharfseher Mok'thardin helfen, ein zeremonielles Halsband fertigzustellen, um den Kriegshäuptling zu ehren und die Horde zu schützen."},sec={{t="Eine umkämpfte Quelle",b="Scharfseher Mok'thardin benötigt Wasser aus einer Heiligen Quelle hoch über den südlichen Klippen des Schlingendorntals, nahe der Westküste. Ihr habt bei den früheren Phasen der Verzauberung geholfen. Gelehrte des Mystischen und Göttlichen streiten darüber, wem die Quelle geweiht wurde. Jedes Volk in ganz Azeroth behauptet, ihre heiligen Wasser seien für das eigene Volk bestimmt gewesen."},{t="Der Einfall der Naga",b="Naga-Forscher haben die Quelle erreicht, und Mok'thardin braucht Euch, um sie zu vertreiben. Bringt ihm einen Schluck des Wassers und tötet zehn der schlangengleichen Eindringlinge. Er benötigt beides, um das zeremonielle Halsband im Namen des Kriegshäuptlings fertigzustellen."}},faq={{q="Wo befindet sich die Heilige Quelle?",a="Die Heilige Quelle liegt hoch auf den Klippen nahe der Westküste im südlichen Schlingendorntal.",al={"heilige quelle standort","wo ist das wasser der heiligen quelle","heilige quelle klippen"}},{q="Warum gilt die Heilige Quelle als wichtig?",a="Gelehrte des Mystischen und Göttlichen streiten über die Bedeutung der Quelle. Jedes Volk in ganz Azeroth behauptet, ihre göttlichen Wasser seien dem eigenen Volk geweiht worden.",al={"warum ist die quelle heilig","heilige quelle bedeutung"}},{q="Wer macht die Heilige Quelle streitig?",a="Eine Expedition von Naga-Forschern hat die Klippen rund um die Heilige Quelle erreicht und bedroht das Gebiet.",al={"wer greift die quelle an","heilige quelle feinde"}},{q="Wofür wird das Wasser verwendet?",a="Scharfseher Mok'thardin benötigt das Wasser als letztes Reagenz, um ein zeremonielles Halsband zur Verteidigung der Horde vorzubereiten und zu verzaubern.",al={"warum wasser der heiligen quelle nötig","wasser der heiligen quelle verwendung"}}},fp="25,206,18.341.0,18.227.0,33.95.0,44.153.0,34.99.0,33.125.0"}
P.entries["quest:5730"] = {n="Verborgene Feinde",s="In Orgrimmar erwartet Thrall Euren Bericht über die Burning Blade. Neeru Feuerklinge vertraut Euch, und der Kriegshäuptling muss wissen, wie weit der Einfluss des Kults in Kalimdor reicht.",h="In Orgrimmar erwartet Thrall Euren Bericht über die Burning Blade.",kw={"eschental","brachland","burning blade","die kluft der schatten","verborgene feinde","neeru fireblade","der flammenschlund","searing blade","schattenrat","thrall"},ang={["class:Rogue"]="Als Schurke erlebt Ihr die frühen Spionagemethoden der Horde im Einsatz. Gründliche Tarnung, Spionageabwehr und Geduld treten an die Stelle einer sofortigen Konfrontation.",["class:Warlock"]="Als Hexenmeister erkennt Ihr die Gefahr auf Neeru Fireblades Weg. Der Umgang mit Teufelsmagie kann von erlaubter Anwendung in den Dienst am Schattenrat abgleiten.",["faction:Horde"]="Als Mitglied der Horde deckt Ihr Verrat innerhalb der Grenzen Orgrimmars auf. Die junge Horde muss sich im Inneren vor uralter dämonischer Verderbnis schützen, während sie äußere Feinde bekämpft."},sec={{t="Ein Kult enthüllt",b="Auf Wunsch von Kriegshäuptling Thrall brachtet Ihr eine Insigne des Leutnants aus der Knochenhöhle zu Neeru Feuerklinge. Der Hexenmeister lebt offen in der Kluft der Schatten. Später schlugt Ihr gegen die Anführer der Searing Blade tief im Flammenschlund zu.\n\nIhr gabt Euch als williger Rekrut aus und trugt die Abzeichen gefallener Kultisten. Damit gewannt Ihr Fireblades Vertrauen, und er verriet mehr über das Netzwerk hinter seinen Operationen."},{t="Geflüster des Schattenrats",b="Neeru Feuerklinge glaubt, dass Ihr ein loyaler Leutnant seid. Er räumt ein, dass der Verlust im Flammenschlund die Searing Blade zurückgeworfen hat, doch die größeren Pläne des Schattenrats bleiben unberührt. Seine Meister haben aktive Agenten im Brachland und tiefer in den Wäldern des Eschentals.\n\nEuer Bericht trifft Thrall unvorbereitet. Die dämonische Verschwörung reicht weit über die Tunnel unter Orgrimmar hinaus."},{t="Die Wachsamkeit des Kriegshäuptlings",b="Thrall entscheidet sich für Vorsicht, statt Neeru sofort hinzurichten. Solange der Hexenmeister nicht weiß, dass seine Tarnung aufgeflogen ist, kann die Horde seine Nachrichten überwachen und den Kult durch Durotar, das Brachland und das Eschental verfolgen.\n\nDer Kriegshäuptling bereitet Späher und Spione darauf vor, diese Zweige zu untersuchen. Er will die dämonische Verderbnis ohne rücksichtslose Eile ausmerzen."}},faq={{q="Was ist das Ziel dieser Quest?",a="Reist von der Kluft der Schatten zum Valley of Wisdom in Orgrimmar und erstattet Kriegshäuptling Thrall Bericht. Erzählt ihm, was Neeru Feuerklinge über die Pläne des Schattenrats verraten hat.",al={"verborgene feinde ziel","was tun verborgene feinde 5","thrall abgeben"}},{q="Warum vertraut mir Neeru Feuerklinge?",a="Ihr habt in der Knochenhöhle eine Insigne des Leutnants von der Burning Blade erbeutet und sie Neeru als ehrgeiziger Kultnovize überreicht. Er hält Euch für einen loyalen Helfer.",al={"warum neeru mir vertraut","neeru täuschen","fireblade infiltration"}},{q="Warum lässt Thrall Neeru Feuerklinge nicht sofort verhaften oder hinrichten?",a="Thrall kann mehr erfahren, wenn Neeru glaubt, seine Tarnung sei weiterhin intakt. Die Späher des Kriegshäuptlings können seine Nachrichten überwachen und über seine Kontakte größere Zellen des Schattenrats in ganz Kalimdor aufspüren.",al={"warum lebt neeru","warum neeru nicht töten","warum thrall neeru verschont"}},{q="Welche neuen Informationen erhält Thrall durch diesen Bericht?",a="Thrall erfährt, dass der Schattenrat hinter dem Kult unter Orgrimmar steht. Seine Agenten planen Operationen im Brachland und in den Wäldern des Eschentals.",al={"was hat thrall erfahren","schattenrat eschental","neerus geheimnis"}},{q="Ist die Burning Blade dasselbe wie die Searing Blade?",a="Die Searing Blade ist eine örtliche Sekte, die im Flammenschlund unter Orgrimmar operiert. Sie untersteht dem größeren Kult der Burning Blade, der vom dämonischen Schattenrat gelenkt wird.",al={"burning blade gegen searing blade","flammenschlund kulte","unterschiede der kulte"}},{q="Wird diese Questreihe irgendwo fortgesetzt?",a="Thrall sagt Euch, Ihr sollt Euch ausruhen, und verspricht, Euch später wieder zu rufen. Eine direkte Fortsetzung dieser verdeckten Mission folgt nicht unmittelbar.",al={"verborgene feinde fortsetzung","nächste quest nach verborgene feinde","wohin schickt thrall als nächstes"}}},fx={e43a9a3d={q="Warum teilt Neeru Feuerklinge seine Pläne mit Euch?",a="Neeru Feuerklinge glaubt, Ihr seid ein loyaler Leutnant, der sich sein Vertrauen verdient hat, indem Ihr Bedrohungen beseitigt und den Interessen des Kults gedient habt. Da die Operationen der Searing Blade im Flammenschlund in Unordnung geraten sind, ist Neeru bestrebt, die Folgen zu minimieren und seinen Fokus auf die umfassenderen Ambitionen des Schattenrates im Brachland und Eschental zu verlagern.",al={"neeru fireblades pläne","warum redet neeru","neeru intrige im eschental"}}},fp="14,170,15.389.1,30.375.2,24.346.1,31.173.0,34.166.1,64.183.1,56.151.1,57.164.0,40.127.0"}
P.entries["quest:574"] = {n="Spezialtruppe",s="Im Kurzen Compound nimmt Sergeant Yohwa die Elitetruppen des Colonels ins Visier. Ihr betretet die Stockpile-Höhle, um Euch den Commandos und Headshrinkern zu stellen, und erstattet dann Lieutenant Doren Bericht.",h="Im Kurzen Compound nimmt Sergeant Yohwa die Elitetruppen des Colonels ins Visier.",kw={"kurzen commando","kurzen compound","kurzen headshrinker","lieutenant doren","rebellenlager","sergeant yohwa","spezialtruppe","stockpile"},sec={{t="Angriff auf Stockpile",b="Sergeant Yohwa nimmt nun die Elitespezialisten im Kurzen Compound ins Visier. Die Second Rebellion hat Kurzens reguläre Soldaten geschwächt, und Yohwa kennt viele seiner Leute persönlich. Sie nennt sie fähig, loyal und grausam.\n\nWenn sie nicht gerade in der Wildnis Rebellensoldaten niedermetzeln, versammeln sich die Commandos und Headshrinker in der Stockpile-Höhle im hinteren Teil des Geländes. Um Kurzen weiter zu schwächen, betretet Ihr die Höhle und tötet zehn Kurzen Commandos und sechs Kurzen Headshrinkers."},{t="Bericht an den Befehlshaber",b="Nach dem Kampf schickt Sergeant Yohwa Euch zu ihrem kommandierenden Offizier, Lieutenant Doren, im Rebellenlager. Er wird Euren Bericht aus erster Hand hören wollen."}},faq={{q="Wer befiehlt den Angriff auf Kurzens Elitetruppen?",a="Sergeant Yohwa im Rebellenlager im nördlichen Schlingendorntal befiehlt den Angriff, nachdem Ihr geholfen habt, Kurzens reguläre Infanterie zu dezimieren.",al={"wer vergibt spezialtruppe","spezialtruppe questgeber","wo beginnt spezialtruppe"}},{q="Wo befinden sich Kurzens Commandos und Headshrinker?",a="Kurzens Commandos und Headshrinker versammeln sich in Stockpile, einer Höhle im hinteren Teil des Kurzen Compound. Sie durchstreifen auch die Wildnis, um Rebellen zu jagen.",al={"wo sind headshrinker","wo ist stockpile","kurzen commando fundort"}},{q="Wem erstattet Ihr Bericht, nachdem Ihr die Höhle gesäubert habt?",a="Ihr erstattet Lieutenant Doren, dem kommandierenden Offizier im Rebellenlager, Euren Bericht aus erster Hand.",al={"bei wem abgeben","wo ist doren","bei wem spezialtruppe abschließen"}},{q="Was geht diesem Angriff im Feldzug der Rebellen voraus?",a="Die Second Rebellion geht diesem Angriff voraus. Ihr habt Colonel Kurzens reguläre Truppen auf dem gesamten Gelände geschwächt.",al={"spezialtruppe voraussetzung","welche quest kommt vor spezialtruppe"}}},fp="14,188,22.473.0,20.150.0,47.128.0,55.156.0,46.93.0,53.113.0"}
P.entries["quest:5741"] = {n="Szepter des Lichts",s="In der Festung Donneraxt besitzt die Burning Blade das Szepter des Lichts, das angeblich von den Naga stammt. Azore Aldamort fürchtet, dass es ganze Städte in den großen Meeren versenken kann, und bittet Euch deshalb, es nach Ethel Rethor zu bringen.",h="In der Festung Donneraxt besitzt die Burning Blade das Szepter des Lichts, das angeblich von den Naga stammt.",kw={"azore aldamort","burning blade","desolace","ethel rethor","naga","szepter des lichts","seher","festung donneraxt"},sec={{t="Ein Zepter der Naga",b="Es hat sich herumgesprochen, dass die Burning Blade in der Festung Donneraxt das Szepter des Lichts der Naga besitzt. Der Legende nach kann das Zepter ganze Städte in den großen Meeren versenken. Azore Aldamort wird der Burning Blade eine solche Macht nicht überlassen."},{t="Der Turm des Sehers",b="Ein Seher der Burning Blade verwahrt das Zepter in einem Wachturm oben auf der Festung und studiert es dort. Azore bittet Euch, dem Seher das Zepter abzunehmen und es zum Turm bei Ethel Rethor zurückzubringen."}},faq={{q="Welche Macht besitzt das Szepter des Lichts?",a="Der Legende nach kann das Szepter des Lichts ganze Städte in den großen Meeren versenken. Man erzählt sich, dass die Burning Blade es von den Naga erhalten hat.",al={"was bewirkt das szepter des lichts","geschichte des szepters des lichts","wie mächtig ist das szepter des lichts"}},{q="Wer besitzt derzeit das Szepter des Lichts?",a="Ein Seher der Burning Blade verwahrt das Szepter des Lichts in einem Wachturm der Festung Donneraxt und studiert es dort.",al={"wer hat das szepter des lichts","wo ist das szepter des lichts","wer lässt das szepter des lichts fallen"}},{q="Wer bittet um das Szepter des Lichts?",a="Azore Aldamort, der sich am Turm bei Ethel Rethor aufhält, bittet um das Szepter des Lichts.",al={"wer gibt das szepter des lichts","wo das szepter des lichts holen"}},{q="Wie hat die Burning Blade das Zepter erhalten?",a="Man erzählt sich, dass die Burning Blade das Zepter von den Naga erhalten hat.",al={"wie hat die burning blade das zepter erhalten","verbindung zwischen burning blade und naga"}}},fp="16,215,21.230.0,16.191.0,45.136.0,41.109.0,34.83.0,42.66.0"}
P.entries["quest:575"] = {n="Angebot und Nachfrage",s="In Beutebucht bereitet Drizzlik einen Auftrag für Director Riddlevox vor, den Cheferfinder der Tinkers' Union. Der Lederverarbeiter behauptet, der beste in den südlichen Meeren und darüber hinaus zu sein.",h="In Beutebucht bereitet Drizzlik einen Auftrag für Director Riddlevox vor, den Cheferfinder der Tinkers' Union.",kw={"beutebucht","krokilisk","drizzlik","excelsior","lederverarbeitung","riddlevox","schlingendorntal","tinkers' union"},sec={{t="Ein Auftrag der Tinkers' Union",b="Drizzlik bezeichnet seine Lederarbeiten als exquisit und überall berühmt. Director Riddlevox hat zwölf Stiefel der Excelsior-Linie bestellt, die zu Drizzliks Bestsellern zählen und die Riddlevox bevorzugt. Um mit ihrer Formung zu beginnen, braucht Drizzlik Bälge von Krokilisken am nördlichen Fluss im Schlingendorntal. Seine Ausrüstung steht bereit, und einen so wichtigen Kunden unzufrieden zu lassen, wäre keine gute Idee."},{t="Sobald die Bälge eintreffen",b="Drizzlik findet die Bälge gut genug für die Stiefel. Ihre Feinheit spielt kaum eine Rolle, weil sie die innere Schicht bilden, aber sie müssen dennoch bequem sein. Sind die Bälge zu steif, kann Tigerblut sie weich machen. Das ist einer der Kniffe des Handwerks."}},faq={{q="Wer ist Drizzlik?",a="Drizzlik ist ein Lederverarbeiter in Beutebucht, der behauptet, der beste in den südlichen Meeren und darüber hinaus zu sein.",al={"drizzlik beutebucht","lederverarbeiter beutebucht"}},{q="Wer hat die Excelsior-Stiefel bestellt?",a="Director Riddlevox, Cheferfinder der Tinkers' Union, hat zwölf Stiefel der Excelsior-Linie bestellt.",al={"wer hat die stiefel bestellt","director riddlevox","auftrag der tinkers' union"}},{q="Wo findet man die Krokilisken für diesen Auftrag?",a="Die Krokilisken für Drizzliks Auftrag leben am nördlichen Fluss im Schlingendorntal.",al={"krokilisken fundort","wo sind flusskrokilisken","wo findet man die bälge"}},{q="Wie viele Bälge möchte Drizzlik?",a="Drizzlik möchte zwei große Flusskrokiliskenbälge.",al={"wie viele krokiliskenbälge","große flusskrokiliskenbälge"}}},fp="17,179,32.375.0,21.250.1,16.99.0,32.94.0,51.82.0,34.47.0"}
P.entries["quest:576"] = {n="Ein Auge offen halten",s="In Beutebucht braucht Dizzy One-Eye das verzauberte Auge, das ihm das Sehen ermöglicht. Blutsegelbukaniere überfielen ihn letzte Nacht und nahmen es ihm ab.",h="In Beutebucht braucht Dizzy One-Eye das verzauberte Auge, das ihm das Sehen ermöglicht.",kw={"blutsegel","beutebucht","bukaniere","dizzy","glasauge","menethil","one-eye","schlingendorntal"},sec={{t="Das verzauberte Auge",b="Dizzy One-Eye verlor im Kampf beide Augen. Später legte sein Schiff in Menethil an, wo ihm ein durchreisender Zauberer ein verzaubertes Glasauge anfertigte. Es gab ihm sein Augenlicht zurück, und Dizzy hielt einst im Krähennest Ausschau. Ohne das Auge fühlt er sich nutzlos."},{t="Von den Bukanieren geraubt",b="Blutsegelbukaniere überfielen Dizzy letzte Nacht, als er gerade hinausging, und nahmen ihm sein Auge ab. Ihre Anwesenheit in Beutebucht beunruhigt ihn. Er fürchtet, dass der Kapitän ihn kielholen lässt, sobald das Schicksal des Auges ans Licht kommt. Ein Ausguck, der nicht sehen kann, taugt seiner Meinung nach vielleicht nur noch dazu, die Bilge zu schrubben. Deshalb bittet er Euch, das Auge von den Blutsegelbukanieren zurückzuholen."}},faq={{q="Wer ist Dizzy One-Eye?",a="Dizzy One-Eye ist ein alter Seebär in Beutebucht, der als Ausguck gearbeitet hat. Er verlor im Kampf beide Augen und sieht durch ein verzaubertes Glasauge.",al={"dizzy one eye","wer vergibt ein auge offen halten","wer ist dizzy"}},{q="Woher hat Dizzy das magische Auge?",a="Dizzys Schiff legte in Menethil an, wo ihm ein durchreisender Zauberer ein verzaubertes Glasauge anfertigte. Es gab ihm sein Augenlicht zurück.",al={"wie bekam dizzy sein auge","dizzy verzaubertes auge herkunft","glasauge zauberer"}},{q="Wer hat Dizzys Auge geraubt?",a="Blutsegelbukaniere. Sie überfielen Dizzy letzte Nacht, als er gerade hinausging, und nahmen ihm sein Auge ab.",al={"wer hat das auge gestohlen","wer hat dizzys auge geraubt","wer hat dizzys auge"}},{q="Was befürchtet Dizzy ohne das Auge?",a="Dizzy fürchtet, dass der Kapitän ihn kielholen lässt, sobald das Schicksal des Auges ans Licht kommt. Er meint, dass ein Ausguck, der nicht sehen kann, vielleicht nur noch dazu taugt, die Bilge zu schrubben.",al={"was passiert wenn dizzy sein auge verliert","dizzy kapitän strafe"}}},fp="15,131,17.236.0,23.335.0,21.138.0,36.115.0,21.89.0,49.146.0"}
P.entries["quest:5761"] = {n="Vernichtung der Bestie",s="Neeru Feuerklinge schickt Abenteurer der Horde aus Orgrimmar in den Flammenschlund, um Taragaman den Hungerleider zu jagen. Er sagt, Kriegshäuptling Thrall habe die Jagd befohlen, und fordert das Herz der Teufelswache als Beweis dafür, dass der Dämonenkult gefallen ist.",h="Neeru Feuerklinge schickt Abenteurer der Horde aus Orgrimmar in den Flammenschlund, um Taragaman den...",kw={"die kluft der schatten","teufelswache","neeru fireblade","orgrimmar","der flammenschlund","searing blade","vernichtung der bestie","taragaman"},ang={["class:Warlock"]="Als Hexenmeister, der in der Kluft der Schatten an Neerus Seite wirkt, erlebt Ihr die politischen Spannungen, die das Wirken von Teufelsmagie unter Thralls wachsamem Blick mit sich bringt.",["faction:Horde"]="Als Mitglied der Horde steht Ihr einer unmittelbaren Bedrohung für Orgrimmars Sicherheit durch die dämonische Präsenz unter der Hauptstadt gegenüber.",["race:Orc"]="Als Orc, der dem Erbe des Dämonenblutfluchs entkommen will, empfindet Ihr die Teufelswache und den Dämonenkult unter Thralls Thron womöglich als unerträgliche Schande."},sec={{t="Eine Bedrohung unter der Stadt",b="Der Flammenschlund verläuft unter Orgrimmars roten Lehmstraßen. Seine feurige Spalte beherbergt Troggs, Bestien und verdeckte Agenten der Searing Blade. In der Kluft der Schatten darüber behauptet Neeru Feuerklinge, Thrall zu dienen und die dämonische Fäulnis zu tilgen. Er deutet auf Taragaman den Hungerleider, eine gewaltige Teufelswache im Herzen der Höhle, und nennt ihn den Drahtzieher hinter dem Kult unter der Stadt."},{t="Die Täuschung des Hexenmeisters",b="Neeru Feuerklinge lobt jene, die mit Taragamans Herz zurückkehren, und verspricht, dass Thrall besänftigt sein wird. Doch Taragaman ist nur ein entbehrlicher Schläger, nicht der wahre Anführer des Kults. Neeru schickt Helden der Horde auf die Jagd nach dem Dämon, um Thrall einen sichtbaren Sieg zu verschaffen und seinen Argwohn zu zerstreuen. Die Jagd schützt die wahre Führung und die tiefer reichenden Operationen der Searing Blade unter Orgrimmar vor genauerer Prüfung."}},faq={{q="Wer ist Taragaman der Hungerleider?",a="Taragaman der Hungerleider ist eine mächtige Teufelswache auf einer Felsplattform im Herzen des Flammenschlunds. Neeru Feuerklinge bezeichnet ihn als Anführer der Kultisten der Searing Blade unter Orgrimmar.",al={"wer ist taragaman","was ist taragaman","taragamans geschichte"}},{q="Wer vergibt die Quest Vernichtung der Bestie?",a="Neeru Feuerklinge erteilt den Auftrag in seinem Zelt in der Kluft der Schatten, Orgrimmars höhlenartigem Hexenmeisterviertel.",al={"questgeber vernichtung der bestie","wer vergibt diese quest","neeru fireblade quest"}},{q="Warum will Neeru Taragamans Herz?",a="Neeru sagt, Taragamans Herz werde Kriegshäuptling Thrall beweisen, dass die dämonische Bedrohung unter Orgrimmar vernichtet wurde.",al={"warum das herz holen","taragamans herz zweck","warum will neeru das herz"}},{q="Ist Taragaman tatsächlich der Anführer der Searing Blade?",a="Neeru Feuerklinge bezeichnet Taragaman als Anführer der Searing Blade. Taragaman ist eine furchterregende Teufelswache unter den Kultisten im Herzen des Flammenschlunds.",al={"ist taragaman der wahre anführer","wer führt die searing blade","taragaman anführer"}},{q="Wo befindet sich Taragaman?",a="Taragaman der Hungerleider steht auf einer von Lava umgebenen Felsplattform im mittleren Bereich des Flammenschlunds, inmitten von Kultisten der Searing Blade.",al={"taragaman aufenthaltsort","wo ist die bestie","wo ist taragaman zu finden"}},{q="Wie hängt diese Quest mit Hidden Enemies zusammen?",a="Thrall untersucht die Unterwanderung Orgrimmars durch den Shadow Council und behält Neeru Feuerklinge genau im Auge. Neeru bietet die Jagd an, um Thrall sichtbare Erfolge gegen die Searing Blade zu zeigen.",al={"verbindung zu hidden enemies","hidden enemies questreihe","thrall und neeru"}}},fx={dcb60e0c={q="Warum will Neeru Feuerklinge, dass Taragaman getötet wird?",a="Neeru behauptet, er diene Kriegshäuptling Thrall, indem er die dämonische Verderbnis ausrottet, die unter Orgrimmar schwärt. Indem er Euch auf Taragaman der Hungerleider hinweist und behauptet, das Brutmensch sei der Anführer der Searing Blade, liefert Neeru Thrall einen prominenten Sündenbock. Den Dämon zu erschlagen bietet dem Kriegshäuptling einen sichtbaren Sieg, während der Verdacht weit von Neerus eigenen dunklen Intrigen abgelenkt wird.",al={"warum will neeru das erledigt haben","motiv von neeru fireblade","grund für das erschlagen der bestie"}}},fp="17,221,25.380.0,23.393.1,30.186.0,38.115.0,38.122.1,54.147.1,27.131.0,46.185.1"}
P.entries["quest:5762"] = {n="Hemet Nesingwary Jr.",s="Eine unterwegs aufgehaltene Kiste aus Kalimdor erreicht die Dschungel des Schlingendorntals auf dem Seeweg. An der Illusionenrennbahn schickt Kravel Kohlebart besondere Vorräte an Hemet Nesingwary, den berühmten Großwildjäger.",h="Eine unterwegs aufgehaltene Kiste aus Kalimdor erreicht die Dschungel des Schlingendorntals auf dem Seeweg.",kw={"munition","hemet nesingwary","kravel kohlebart","kravels kiste","illusionenrennbahn","die schimmernde ebene","schlingendorntal"},ang={["class:Hunter"]="Als Jäger bringt Ihr Spezialmunition zu Hemet Nesingwary, der Azeroths berühmteste Großwildsafari anführt.",["race:Dwarf"]="Als Zwerg seht Ihr zwei schlitzohrige zwergische Bekannte, die es auf der Suche nach Münzen und Jagdbeute von Eisenschmiede in die Ferne verschlagen hat."},sec={{t="Eine transkontinentale Lieferung",b="An der Illusionenrennbahn in der Schimmernden Ebene erhält Kravel Kohlebart eine längst überfällige Kiste für einen seiner wohlhabenden Gönner. Hemet Nesingwary hatte Tausend Nadeln bereits verlassen, doch er bezahlte dafür, die Kiste an sein Jagdlager im Schlingendorntal weiterzuschicken. Kravel bleibt zurück, statt die beschwerliche Reise selbst anzutreten. Also heuert er vorbeiziehende Abenteurer an, um die Kiste über das Meer zu bringen."},{t="Munition für die Jagd",b="Nördlich des Basislagers Grom'gol nimmt Hemet Nesingwarys Expedition die schwere Kiste entgegen. Sie enthält spezielle großkalibrige Munition, um die gefährlichen Raubtiere des Dschungels zur Strecke zu bringen. Hemet erkennt die weiße Salzkruste auf der Ausrüstung des Boten. Seine alten Geschäftsbeziehungen zu Kravel haben die Feuerkraft eingebracht, die seine Safari brauchte."}},faq={{q="Wo beginnt und endet diese Lieferung?",a="Die Lieferung beginnt bei Kravel Kohlebart an der Illusionenrennbahn in der Schimmernden Ebene, im Süden von Tausend Nadeln. Sie endet in Hemet Nesingwarys Expeditionslager im nördlichen Schlingendorntal, unmittelbar nördlich von Grom'gol.",al={"questanfang und questende","wo ist hemet","wohin gehen"}},{q="Was befindet sich in Kravels Kiste?",a="Kravels Kiste enthält Munition mit besonderem Kaliber für Großwildgewehre. Hemet bestellte die Geschosse, um die dicken Häute der wildesten Bestien des Schlingendorntals zu durchdringen.",al={"was ist in der kiste","kisteninhalt","kravels paket"}},{q="Warum hat Kravel die Kiste nicht selbst geliefert?",a="Kravel ist damit beschäftigt, seine Investitionen und Machenschaften an der Illusionenrennbahn zu beaufsichtigen. Mit dem Geld, das Hemet im Voraus bezahlt hat, heuert er vorbeiziehende Abenteurer an, statt seinen Posten zu verlassen und das Meer zu überqueren.",al={"warum heuert kravel jemanden an","warum braucht kravel hilfe"}},{q="Woher weiß Hemet, woher der Bote kam?",a="Hemet erkennt die Salzkruste auf der Kleidung des Boten als Merkmal der Schimmernden Ebene und nicht als gewöhnlichen Wüstenstaub.",al={"wüstensalz","hemet dialog salz"}},{q="In welcher Beziehung stehen Kravel und Hemet zueinander?",a="Hemet ist ein langjähriger und einträglicher Kunde von Kravel. Kravel schätzt Hemets prallen Geldbeutel, während Hemet Kravel liebevoll einen „knorrigen alten“ Schurken nennt, der ständig Unfug im Schilde führt.",al={"kravel und hemet vorgeschichte","kennen sie einander"}},{q="Wer ist Hemet Nesingwary?",a="Hemet Nesingwary ist ein gefeierter zwergischer Scharfschütze, Autor und Großwildjäger. Er führt eine Safari durch die gefährlichen Tiefen des Schlingendorntals.",al={"wer ist hemet","nesingwary hintergrundgeschichte"}}},fx={["4f3179a4"]={q="Warum will Kravel Kohlebart, dass diese Kiste an Hemet geliefert wird?",a="Kravel pflegt eine lukrative Geschäftsverbindung. Hemet Nesingwary ist ein bemerkenswert wohlhabender Zwerg, und Kravel weiß, dass es sich auszahlt, solch reiche Kundschaft zufriedenzustellen. Hemet hat im Voraus dafür bezahlt, dass die Kiste an seine Jagdgründe weitergeleitet wird, sobald sie eintrifft. Das Einhalten der Abmachung schützt also Kravels Ruf und garantiert zukünftige Münzen.",al={"warum kravels kiste ausliefern","kravel kohlebarts motiv","warum kiste an hemet schicken"}}},fp="16,205,27.391.0,23.316.0,39.220.0,30.153.0,44.191.0,48.118.0,51.175.0,24.148.0"}
P.entries["quest:5763"] = {n="Jagd im Schlingendorntal",s="Ihr bringt Roon Wildmanes Zeichen zu Hemet Nesingwary im Schlingendorntal, nördlich des Basislagers Grom'gol. Der Tauren und der Zwerg jagten einst gemeinsam in Desolace.",h="Ihr bringt Roon Wildmanes Zeichen zu Hemet Nesingwary im Schlingendorntal, nördlich des Basislagers Grom'gol.",kw={"desolace","grom'gol","hemet nesingwary","kodohorn","roon wildmane","schlingendorntal"},sec={{t="Ein Zeichen unter Jägern",b="Roon Wildmane erinnert sich an die Jagd an Hemets Seite, eines Zwergs, der nach Desolace kam, um große Bestien zu jagen. Hemet führte eine Büchse mit unheimlichem Geschick. Viele Tage lang jagten die beiden gemeinsam und legten die alte Feindschaft zwischen ihren Völkern beiseite.\n\nAls Hemet ins Schlingendorntal aufbrach, gelobte Roon, ihn zu einer weiteren Jagd wieder willkommen zu heißen. Nun schickt Roon Euch mit seinem Kodohorn los, einem Zeichen, das Hemet erkennen wird. Sucht Hemet im Schlingendorntal, nördlich des Basislagers Grom'gol."},{t="Hemets Antwort",b="Hemet erkennt Roon Wildmanes Kodohorn sofort. Er erinnert sich an die gute Jagd, die sie gemeinsam unter den Bestien von Desolace erlebten, und dankt Euch, obwohl er vorerst bis zum Hals im Dschungel steckt. Hemet glaubt, seine nächste Expedition könnte ihn zurück nach Desolace führen, wo die Zentauren leben."}},faq={{q="Wer ist Hemet?",a="Hemet ist ein Zwerg, der nach Desolace kam, um große Bestien zu jagen. Sein Geschick mit der Büchse war unheimlich, und er und Roon Wildmane jagten viele Tage gemeinsam, bevor Hemet ins Schlingendorntal aufbrach.",al={"hemet nesingwary","wer ist hemet"}},{q="Warum liegt Roon Wildmane etwas an einem Zwerg?",a="Roon Wildmane und Hemet jagten viele Tage gemeinsam und legten dabei die Feindschaft zwischen ihren Völkern beiseite. Roon gelobte, Hemet wieder willkommen zu heißen, damit sie erneut gemeinsam jagen könnten.",al={"warum dem zwerg helfen","roon wildmane zwergenfreund"}},{q="Wo befindet sich Hemet?",a="Hemet ist im Schlingendorntal, nördlich des Basislagers Grom'gol.",al={"wo ist hemet","hemets aufenthaltsort","jagdlager im schlingendorntal"}},{q="Wozu dient das Kodohorn?",a="Roon Wildmane schickt Hemet das Kodohorn, der es als Roons Horn erkennen wird.",al={"zweck des kodohorns","warum das kodohorn überbringen"}}},fp="24,152,23.441.0,14.269.1,13.180.0,42.161.0,23.55.0,37.76.0"}
P.entries["quest:577"] = {n="Etwas Zusammenbau benötigt",s="In Beutebucht sagt Drizzlik, dass die Excelsior-Stiefel vorankommen, doch die von Euch gebrachten Häute reichen nicht für das Innere. Für diese verborgenen Schichten will er billigere, dickere Häute von Krokilisken nahe dem Nazferitisee verwenden.",h="In Beutebucht sagt Drizzlik, dass die Excelsior-Stiefel vorankommen, doch die von Euch gebrachten Häute...",kw={"stiefel","beutebucht","krokilisk","drizzlik","der nazferitisee","snapjaw","schlingendorntal"},sec={{t="Die Stiefel füllen",b="Drizzlik sagt, dass die Excelsior-Stiefel gut vorankommen. Die Häute aus Supply and Demand reichen nicht für das Innere. Da niemand diese Schichten sehen wird, will er dickere, billigere Häute von den Krokilisken nahe dem Nazferitisee verwenden."},{t="Das Verkaufsargument",b="Drizzlik verspricht feine Handwerkskunst und Stiefel aus reiner, erstklassiger Salzwasserkrokiliskenhaut. Er vergleicht die Stiefel mit Würsten: Sie sehen großartig aus, schmecken hervorragend und sollen nur die feinsten Zutaten enthalten. Dem Hersteller zu vertrauen, ohne allzu genau nachzusehen, was darin steckt, könnte sicherer und angenehmer sein."}},faq={{q="Wer verlangt diese Häute?",a="Drizzlik in Beutebucht arbeitet an den Excelsior-Stiefeln. Nach den in Supply and Demand gelieferten Häuten braucht er weitere.",al={"questgeber","wer vergibt etwas zusammenbau benötigt","drizzlik standort"}},{q="Welche Häute braucht Drizzlik?",a="Drizzlik braucht fünf Häute von snapjaw-Krokilisken.",al={"welche häute werden benötigt","krokiliskenhaut art","welche krokilisken"}},{q="Wo sind die benötigten Krokilisken zu finden?",a="Drizzlik schickt Euch zu den Krokilisken rund um den Nazferitisee.",al={"nazferitisee lage","wo sind snapjaws","wo krokilisken finden"}},{q="Warum will Drizzlik billigere Häute?",a="Das Innere der Stiefel bleibt allen Blicken verborgen. Deshalb ist Drizzlik bereit, sie mit dickeren, billigeren Häuten zu füllen.",al={"warum billigere häute","warum snapjaw-häute","stiefelpolsterung"}}},fp="22,221,17.237.0,15.304.1,30.120.0,30.44.0,40.59.0,37.117.0"}
P.entries["quest:578"] = {n="Der Stein der Gezeiten",s="Baron Revilgaz erreichen seltsame Berichte von einer Insel vor dem Schlingendorntal. Er vermutet, dass ein uraltes Trollrelikt wieder aufgetaucht ist, und schickt Euch zur Erkundung der Küste, mit einem Passierschein für Nachforschungen in Sturmwinds Archiven.",h="Baron Revilgaz erreichen seltsame Berichte von einer Insel vor dem Schlingendorntal.",kw={"baron revilgaz","beutebucht","donyal tovald","gazban","gurubashi","stein der gezeiten","stormwind library","schlingendorntal"},sec={{t="Der Ehrgeiz eines Magnaten",b="Seltsame Erscheinungen und Wasserelementare suchen eine Insel vor dem Schlingendorntal heim. Baron Revilgaz herrscht über Beutebucht und vermutet, dass Gazban, ein Goblinmagier, den sagenumwobenen Stein der Gezeiten gefunden hat. Er schickt Euch los, um die Insel zu finden und herauszufinden, ob die Gerüchte wahr sind. Als Hilfe bei Eurer Suche gibt er Euch einen Bibliotheksschein für Sturmwinds Gelehrte."},{t="Ein uralter Schutzzauber",b="Die seltsame Präsenz auf der Insel bestätigt Baron Revilgaz' Hoffnung: Das legendäre Artefakt gibt es wirklich. Es an sich zu bringen, wird schwierig sein. Auf dem Stein der Gezeiten liegt ein mächtiger magischer Fluch, und Revilgaz kann ihn nicht allein brechen. Ein erfahrener Zauberer muss helfen, bevor jemand das Relikt bergen kann."}},faq={{q="Wer bittet Euch, die heimgesuchte Insel zu finden?",a="Baron Revilgaz, Herrscher von Beutebucht, schickt Euch auf die Suche nach der Insel, nachdem er Berichte über seltsame Vorgänge vor der Küste gehört hat.",al={"wer vergibt die quest","questgeber stein der gezeiten","wer erteilt den auftrag"}},{q="Wo liegt die heimgesuchte Insel?",a="Die Insel liegt im Meer vor der Küste des Schlingendorntals, und Ihr müsst sie selbst finden.",al={"wo ist die insel","lage der insel","heimgesuchte insel finden"}},{q="Was ist der Stein der Gezeiten?",a="Der Stein der Gezeiten ist ein legendäres Trollartefakt, das Revilgaz seiner Sammlung hinzufügen möchte. Er las erstmals in einem alten Buch von seiner Legende.",al={"was ist der stein","geschichte des steins der gezeiten","was ist der stein der gezeiten"}},{q="Warum will Baron Revilgaz das Artefakt haben?",a="Baron Revilgaz möchte das mächtige Trollrelikt für seine Sammlung uralter Artefakte und Relikte haben.",al={"warum will revilgaz ihn haben","revilgaz beweggründe"}},{q="Wofür wird der Bibliotheksschein verwendet?",a="Ihr könnt den Schein zu Donyal Tovald in der Sturmwind Library bringen und eine Abschrift des Buches erhalten, in dem der Baron erstmals von der Legende las.",al={"was ist der bibliotheksschein","sturmwind bibliotheksschein","wohin mit dem bibliotheksschein"}},{q="Was war der vorherige Schritt in dieser Questreihe?",a="The Haunted Isle ging dieser Untersuchung voraus und brachte Baron Revilgaz erstmals Kunde von den seltsamen Sichtungen.",al={"welche quest kommt davor","vorausgesetzte quest"}}},fp="22,209,20.334.0,15.287.1,42.119.0,36.90.0,31.137.0,42.97.0,35.137.0,41.114.0"}
P.entries["quest:579"] = {n="Bibliothek von Sturmwind",s="In Burg Sturmwind schreibt Donyal Tovald die Chroniken des Königreichs für jene ab, die Bibliotheksscheine vorlegen. Der junge König Anduin Wrynn finanziert diese Arbeit und macht Berichte über Azeroth für Bürger und Gelehrte zugänglich.",h="In Burg Sturmwind schreibt Donyal Tovald die Chroniken des Königreichs für jene ab, die Bibliotheksscheine...",kw={"anduin wrynn","bücher","donyal tovald","bibliotheksschein","geschichtswälzer","burg sturmwind","bibliothek von sturmwind","abschrift"},ang={["class:Mage"]="Als Magier könnt Ihr Euch neben Euren arkanen Studien im Mage Quarter an die Royal Library wenden, um die Chroniken des Königreichs zu studieren.",["faction:Alliance"]="Als Bürger der Allianz könnt Ihr Aufzeichnungen über die Triumphe und Tragödien der Allianz von Lordaeron und die Bande zwischen Menschen, Zwergen, Gnomen und Hochelfen finden.",["race:Human"]="Als Mensch wisst Ihr, wie wertvoll es ist, Geschichte zu bewahren. Das alte Sturmwind verlor unzählige Archive, als es im Ersten Krieg geplündert wurde. Heute schützen und kopieren Gelehrte die Chroniken, die den Wiederaufbau des Königreichs überdauert haben."},sec={{t="Ein königlicher Wissensauftrag",b="Der junge König Anduin stellt königliche Mittel für die Bildung bereit. Damit werden Abschriften alter Manuskripte und historischer Tagebücher bezahlt. In Burg Sturmwind bewahrt die Royal Library diese Berichte und fertigt Abschriften für jene im königlichen Dienst an."},{t="Der Tausch gegen Bibliotheksscheine",b="Empfindliches Pergament von Hand abzuschreiben erfordert Zeit, Tinte und königliche Genehmigung. Donyal Tovald nimmt offizielle Bibliotheksscheine an, die in den Gebieten der Allianz an Abenteurer und Gelehrte ausgegeben werden. Im Gegenzug stellt er Abschriften historischer Werke bereit, von alten Chroniken der Östlichen Königreiche bis zu Berichten aus fernen Ländern. Diese Bücher erzählen von Konflikten jenseits der Hauptstadt."}},faq={{q="Welchen Zweck hat die Quest „Bibliothek von Sturmwind“?",a="Ihr könnt bei Bibliothekar Donyal Tovald einen Bibliotheksschein gegen ein lesbares Buch eintauschen. Die Bücher erzählen von Menschen, Orten und Ereignissen der Allianz in ganz Azeroth.",al={"was bewirkt diese quest","bibliothek von sturmwind quest zweck","warum diese quest machen"}},{q="Wer ist Donyal Tovald?",a="Donyal Tovald leitet die Royal Library in Burg Sturmwind. Er verwaltet die schriftlichen Chroniken des Königreichs und verteilt auf Befehl von König Anduin Abschriften.",al={"wer ist donyal tovald","bibliothekar sturmwind","wer gibt die bücher aus"}},{q="Wo erhaltet Ihr einen Bibliotheksschein?",a="Gelehrte, Magistrate und Beamte in den Gebieten der Allianz geben Bibliotheksscheine an jene aus, die mehr über die weite Welt erfahren möchten.",al={"wo gibt es bibliotheksscheine","wie bibliotheksschein erhalten","bibliotheksschein herkunft"}},{q="Warum finanziert der junge König Anduin die Bibliothek?",a="König Anduin Wrynn finanziert Abschriften historischer Werke, weil ihm Wissen und Bildung viel bedeuten. Noch als Kind stellte er unter der Anleitung von Regent Bolvar Fordragon königliche Mittel bereit, um die Chroniken des Königreichs öffentlich zugänglich zu machen.",al={"warum sind anduin bücher wichtig","anduin bibliotheksfinanzierung","könig anduin bücher"}},{q="Wo in Sturmwind befindet sich die Bibliothek?",a="Die Royal Library liegt in Burg Sturmwind, der großen Festung im Osten der Stadt. Donyal Tovald ist zwischen ihren Regalen und Lesetischen zu finden.",al={"wo ist die bibliothek von sturmwind","royal library standort","wo befindet sich donyal tovald"}},{q="Kann ich die Bücher lesen, die ich erhalte?",a="Ja. Jedes Buch aus der Bibliothek lässt sich lesen und bietet Hintergründe zu Legenden und historischen Ereignissen in ganz Azeroth.",al={"sind die bücher lesbar","lassen sich die bücher öffnen","bewirken bücher etwas"}}},fx={c9ea8ca7={q="Wofür wird der Bibliotheksschein verwendet?",a="Ein Bibliotheksschein dient als offizielle königliche Genehmigung, um einen kopierten Band aus der Royal Library von Sturmwind einzulösen. Dank der Finanzierung durch den jungen König Anduin Wrynn reproduziert die Bibliothek historische Schriften und Berichte für die Bürger, aber Donyal Tovald benötigt einen gültigen Gutschein, bevor er sich von einem dieser sorgfältig transkribierten Bände trennen kann.",al={"was ist ein bibliotheksschein","zweck des bibliotheksscheins","warum der bibliotheksschein"}}},fp="17,193,29.228.0,18.349.0,51.152.0,21.153.0,36.139.0,45.226.0,42.162.0,31.109.0"}
P.entries["quest:58"] = {n="Die Nachtwache",s="Im Osten von Rabenflucht ruft die Nachtwache um Hilfe, während Dunkelhain den Untoten gegenübersteht. Kommandantin Althea Schwarzhaupt ruft Reisende auf, die Krypten zu betreten und die Seuchenverbreiter zu vernichten, während ihre Wachen die Stadt verteidigen. Dies ist das letzte Kapitel im direkten Kampf der Stadtwache gegen den Ansturm der Untoten.",h="Im Osten von Rabenflucht ruft die Nachtwache um Hilfe, während Dunkelhain den Untoten gegenübersteht.",kw={"althea schwarzhaupt","dunkelhain","dämmerwald","ghule","mausoleum","nachtwache","seuchenverbreiter","rabenflucht","untoter"},ang={["class:Paladin"]="Als Paladin steht Ihr in den seuchenverseuchten Gewölben von Rabenflucht einer frevelhaften Verhöhnung heiliger Bestattungsriten gegenüber. Die Krypten zu reinigen, ist eine unerlässliche Pflicht gegenüber dem Heiligen Licht.",["class:Priest"]="Als Priester steht Ihr der abscheulichen Seuche gegenüber, die Ghule im östlichen Mausoleum verbreiten. Diese Bedrohung verlangt nach einer Reinigung von Geist und Körper.",["faction:Alliance"]="Da die Krone von Sturmwind die Hilferufe des Dämmerwalds ignoriert, müssen Recken der Allianz vortreten, um treue Bürger vor den Untoten zu retten."},sec={{t="Eine verzweifelte Grenzregion",b="Dunkelhain steht beinahe allein da, ohne Soldaten aus Sturmwind, auf die es sich verlassen könnte. Seine Bürgermiliz, die Nachtwache, muss die Stadt halten. Kommandantin Althea Schwarzhaupt hat nur wenige Wachen übrig und setzt sie ein, um die Wegkreuzungen, den Stadtrand und die Nachschublinien zu schützen. Während sich die rastlosen Toten im Dämmerwald vermehren, ruft sie umherziehende Recken auf, den Kampf in die Tiefen von Rabenflucht zu tragen."},{t="Die Säuberung des Mausoleums",b="Das östliche Mausoleum auf dem Friedhof von Rabenflucht birgt eine der größten Ansammlungen von Untoten in der Region. Anders als in den offenen Grabhügeln wimmelt es in seinen steinernen Krypten von Seuchenverbreitern. Diese Ghule tragen Gebrechen in sich, die die Lebenden erkranken lassen können. Zwanzig von ihnen zu vernichten, verschafft der Nachtwache eine Atempause und hilft, Dunkelhain vor einem vereinten Ansturm der Untoten aus dem Westen zu bewahren."}},faq={{q="Warum schickt die Nachtwache Abenteurer statt ihrer eigenen Leute?",a="Die Nachtwache hat zu wenige Wachen, um den gesamten Dämmerwald zu sichern. Sturmwind entsendet keine offiziellen Truppen, sodass Kommandantin Althea Schwarzhaupt kaum den Stadtrand von Dunkelhain halten und die Straßen überwachen kann. Es bleiben keine Milizionäre übrig, um befestigte Krypten wie die von Rabenflucht zu betreten.",al={"warum dunkelhain helfen","warum die nachtwache hilfe braucht","nachtwache zu wenige wachen"}},{q="Wo befindet sich das östliche Mausoleum?",a="Das östliche Mausoleum liegt im östlichen Teil des Friedhofs von Rabenflucht, im Nordwesten des Dämmerwalds. Sein Eingang führt in steinerne Krypten, in denen sich Seuchenverbreiter sammeln.",al={"wo sind seuchenverbreiter","standort des östlichen mausoleums","wo ist das mausoleum"}},{q="Was macht die Seuchenverbreiter gefährlich?",a="Seuchenverbreiter sind gefräßige Ghule, die hoch ansteckende Fäulnis in sich tragen. Ihre Verderbnis könnte sich über den Friedhof hinaus ausbreiten und die überlebenden Bewohner von Dunkelhain befallen.",al={"warum seuchenverbreiter töten","was sind seuchenverbreiter"}},{q="Wer ist Kommandantin Althea Schwarzhaupt?",a="Althea Schwarzhaupt befehligt die Nachtwache und ist mit Dunkelhains Bürgermeister, Lord Ello Schwarzhaupt, verwandt. Sie leitet die Verteidigung des Dämmerwalds von Dunkelhain aus.",al={"wer ist althea","kommandantin schwarzhaupt","wer führt die nachtwache"}},{q="Endet mit dem Abschluss dieser Questreihe die Bedrohung durch die Untoten im Dämmerwald?",a="Nein. Die Reihen im Mausoleum zu lichten, mindert den unmittelbaren Druck auf Dunkelhain, doch Rabenflucht bleibt von Untoten verseucht. Dunklere Mächte im gesamten Dämmerwald rühren die Toten weiterhin auf.",al={"ist rabenflucht gerettet","ist dunkelhain jetzt sicher"}},{q="Wie fügt sich das in die Questreihe der Nachtwache ein?",a="Dies ist das dritte und letzte Kapitel in Kommandantin Schwarzhaupts direktem militärischem Feldzug für die Nachtwache. Der Kampf verlagert sich von den offenen Straßen an den Rand des Friedhofs und dann tief ins Mausoleum.",al={"welche questreihe ist das","ist dies die letzte quest der nachtwache"}}},fx={f0d896f3={q="Warum will Kommandantin Althea Schwarzhaupt, dass dies erledigt wird?",a="Kommandantin Althea Schwarzhaupt trägt die schwere Last, Dunkelhain mit stark dezimierten Milizrängen zu verteidigen. Der weitläufige Friedhof von Rabenflucht ist zu einem schwärenden Herd der untoten Verderbnis geworden, und sie befürchtet, dass die abscheulichen Kreaturen, die sich in seinen Krypten sammeln, unweigerlich nach Osten vordringen und die Stadt vollständig überwältigen werden, wenn sie nicht aufgehalten werden. Die Zerstörung der Seuchenverbreiter ist eine verzweifelte Maßnahme, um diese drohende Flut einzudämmen und die Lebenden zu schützen.",al={"warum seuchenverbreiter töten","ebonlockes motiv im dämmerwald","warum wieder nach raven hill schicken"}},["0678b7f2"]={q="Was sind die Seuchenverbreiter im Mausoleum?",a="Seuchenverbreiter sind verfaulte, wiederbelebte Leichen, die die entweihten Gräber auf dem Friedhof von Rabenflucht heimsuchen. Durchdrungen von übler Fäulnis und Verwesung, lauern sie tief im östlichen Mausoleum, entweihen die Gräber der Toten des Dämmerwalds und drohen, ihren ansteckenden Schmutz über die Wälder zu tragen. Ihre bleibende Anwesenheit verwandelt die uralten Begräbnisstätten in einen dauerhaften Quell des Untodes.",al={"wer sind die seuchenverbreiter","seuchenverbreiter im dämmerwald","untote im östlichen mausoleum"}}},fp="15,300,20.398.0,21.365.0,68.237.0,39.164.0,42.158.0,34.157.0,61.163.0,49.205.0"}
P.entries["quest:580"] = {n="Whiskey Slim's verlorener Grog",s="In Beutebucht braucht Whiskey Slim zwölf Flaschen Pupellyverbos-Portwein zurück, bevor sein Schiff ausläuft. Seine Mannschaft nahm die Kiste einem Kaperschiff ab, und er fürchtet eine Auspeitschung, falls sein befehlshabender Offizier ihr Fehlen bemerkt.",h="In Beutebucht braucht Whiskey Slim zwölf Flaschen Pupellyverbos-Portwein zurück, bevor sein Schiff ausläuft.",kw={"beutebucht","grog","hinterland","overlook cliffs","kaperschiff","pupellyverbos-portwein","sturmwind","whiskey slim"},sec={{t="Ein Sturm vor dem Hinterland",b="Vor den Overlook Cliffs geriet Whiskey Slims Schiff nahe der Küste des Hinterlands in ein schweres Unwetter. Die Mannschaft hatte einem Kaperschiff auf dem Weg nach Sturmwind eine Kiste Pupellyverbos-Portwein abgenommen. Als die Wellen das Schiff zu verschlingen drohten, brach Slim die Kiste des Kapitäns auf, um sich Mut anzutrinken. Dann riss eine plötzliche Sturzwelle die Flaschen über Bord."},{t="Die Verzweiflung eines Seemanns",b="Zurück in Beutebucht bereitet sich Whiskey Slims Schiff darauf vor, den Anker zu lichten. Er fürchtet die neunschwänzige Katze, sobald sein befehlshabender Offizier entdeckt, dass der beschlagnahmte Portwein fehlt. Slim braucht jemanden, der zwölf Flaschen zurückbringt, bevor sein Diebstahl ans Licht kommt."}},faq={{q="Wer ist Whiskey Slim?",a="Whiskey Slim ist ein Seemann in Beutebucht, der den gestohlenen Alkohol seines Kapitäns während einer Sturmbö auf See verlor und nun eine Strafe fürchtet.",al={"whiskey slim","wer gibt verlorenen grog","wer ist slim"}},{q="Woher kam der Grog?",a="Slims Mannschaft nahm einem Kaperschiff auf dem Weg nach Sturmwind eine Kiste Pupellyverbos-Portwein ab.",al={"herkunft von pupellyverbos-portwein","woher hatte slim den grog","kaperschiff schnaps"}},{q="Wo hat Whiskey Slim die Flaschen verloren?",a="Slim verlor die Flaschen während eines heftigen Sturms vor den Overlook Cliffs nahe der Küste des Hinterlands über Bord, als eine gewaltige Welle das Schiff traf.",al={"wo ging der grog verloren","overlook cliffs sturm","hinterland grog fundort"}},{q="Warum braucht Whiskey Slim die Flaschen so schnell zurück?",a="Slims Schiff bereitet sich auf die Abfahrt vor. Er fürchtet eine Auspeitschung mit der neunschwänzigen Katze, sobald sein Kapitän entdeckt, dass der Portwein fehlt.",al={"warum slim helfen","was passiert mit slim","die katze zu spüren bekommen"}}},fp="24,209,29.335.0,22.251.0,20.121.0,29.93.0,40.143.0,55.130.0"}
P.entries["quest:5801"] = {n="Feuerfeder geschmiedet",s="Am Feuersäulengrat erwartet Euch die nötige Hitze, um den Schaft eines Skelettschlüssels zu schmieden. Der brodelnde Vulkan liegt im Westen des Kraters von Un'Goro, wo sein Lavasee den Schaft verschmelzen kann. Dann bringt Ihr ihn zu Alchimist Arbington an der Zugwindspitze in den Westlichen Pestländern.",h="Am Feuersäulengrat erwartet Euch die nötige Hitze, um den Schaft eines Skelettschlüssels zu schmieden.",kw={"alchimist arbington","zugwindspitze","feuersäulengrat","krinkle goodsteel","gussform für den skelettschlüssel","thorium","krater von un'goro","unvollendeter skelettschlüssel"},sec={{t="Feuer für den Schlüsselschaft",b="Krinkle Goodsteel sagt, der Schlüsselschaft brauche zwei Thoriumbarren und gewaltige Hitze. Ihr findet das Thorium, und Euer Gold kauft eine Gussform. Taucht sie in den Lavasee auf dem Gipfel des Feuersäulengrats. Dort verschmilzt die Hitze Thorium und Knochen miteinander."},{t="Zurück zu Arbington",b="Krinkle Goodsteel hat seinen Teil getan. Um den Schlüssel fertigzustellen, kehrt Ihr zu Alchimist Arbington an der Zugwindspitze in den Westlichen Pestländern zurück. Der in Lava geschmiedete Schaft bleibt unvollendet. Diese Arbeit bereitet Euch auf einen Angriff vor."},{t="Was Euch bevorsteht",b="Alchimist Arbington nennt den Schlüssel kostspielig, doch noch unvollendet. In Andorhal wartet Araj der Beschwörer als der Feind, gegen den sich all diese Mühen richten. Der Lich zählt zu den Mächtigsten der Geißel."}},faq={{q="Wo wird der Schlüsselschaft geschmiedet?",a="Der Schlüsselschaft wird im Lavasee auf dem Gipfel des Feuersäulengrats geschmiedet, einem brodelnden Vulkan im Westen des Kraters von Un'Goro.",al={"wo schlüssel schmieden","feuerfeder geschmiedet ort","lavasee ort"}},{q="Was wird benötigt, um den Schlüsselschaft zu schmieden?",a="Ihr braucht die Gussform für den Skelettschlüssel und zwei Thoriumbarren. Das Thorium findet Ihr selbst.",al={"was wird benötigt","schlüsselmaterialien","thoriumbedarf"}},{q="Wer erhält den unvollendeten Schlüssel?",a="Alchimist Arbington erhält den unvollendeten Schlüssel an der Zugwindspitze in den Westlichen Pestländern.",al={"bei wem abgeben","arbington ort","wohin mit dem unvollendeten schlüssel"}}},fp="17,253,21.223.0,17.218.0,15.177.1,29.106.0,37.86.0,32.94.0"}
P.entries["quest:5802"] = {n="Feuerfeder geschmiedet",s="Am Feuersäulengrat kann gewaltige Hitze den Schaft eines Skelettschlüssels schmieden. Krinkle Goodsteel schickt Euch nach Westen zum Vulkan im Krater von Un'Goro, dessen Gipfel ein Lavasee krönt. Anschließend bringt Ihr den Schaft zu Apotheker Dithers am Bollwerk in den Westlichen Pestländern.",h="Am Feuersäulengrat kann gewaltige Hitze den Schaft eines Skelettschlüssels schmieden.",kw={"andorhal","apotheker dithers","das bollwerk","feuersäulengrat","krinkle goodsteel","gussform für skelettschlüssel","thoriumbarren","krater von un'goro","unvollendeter skelettschlüssel"},sec={{t="Feuer für den Schlüsselschaft",b="Zwei Thoriumbarren und gewaltige Hitze werden benötigt, um den Schlüsselschaft zu schmieden. Ihr beschafft das Thorium, und Krinkle Goodsteel hilft, die Hitze bereitzustellen. Euer Gold hat eine Gussform gekauft, bereit für den Lavasee auf dem Feuersäulengrat. Dort verschmilzt die Lava Thorium und Knochen miteinander."},{t="Zurück zu Dithers",b="Krinkle Goodsteel hat den eigenen Teil getan. Nun kehrt Ihr zu Apotheker Dithers am Bollwerk in den Westlichen Pestländern zurück, um den Schlüssel fertigzustellen. Der in Lava geschmiedete Schaft bleibt unvollendet, und diese Arbeit bereitet einen Angriff vor."},{t="Was Euch erwartet",b="Apotheker Dithers nennt den Schlüssel kostspielig, obwohl er noch unvollendet ist. All diese Arbeit richtet sich gegen einen Feind in Andorhal: Araj der Beschwörer, einen Lich, der zu den mächtigsten der Geißel zählt."}},faq={{q="Wo wird der Schlüsselschaft geschmiedet?",a="Ihr schmiedet den Schlüsselschaft im Lavasee auf dem Feuersäulengrat, einem brodelnden Vulkan im Krater von Un'Goro, westlich von Krinkle Goodsteel.",al={"wo schlüssel schmieden","lavasee fundort","feuersäulengrat lava"}},{q="Was wird zum Schmieden des Schlüsselschafts benötigt?",a="Ihr benötigt eine Gussform für einen Skelettschlüssel und zwei Thoriumbarren. Das Thorium beschafft Ihr selbst.",al={"was wird benötigt","schlüsselmaterialien","benötigtes thorium"}},{q="Wer erhält den unvollendeten Schlüssel?",a="Apotheker Dithers erhält den unvollendeten Schlüssel am Bollwerk in den Westlichen Pestländern.",al={"bei wem abgeben","wohin kommt der schlüssel","schlüssel abgeben"}}},fp="17,263,21.258.0,15.219.0,15.188.1,29.128.0,37.84.0,32.89.0"}
P.entries["quest:581"] = {n="Die Suche nach Yenniku",s="Im Basislager Grom'gol sucht Nimboya nach Yenniku, dem jüngsten Sohn seines Häuptlings. Er vermutet, dass der Stamm der Bloodscalp den Jungen gefangen hält, und bittet Euch, Eure Stärke zu beweisen, indem Ihr ihre Krieger jagt und deren Hauer zurückbringt.",h="Im Basislager Grom'gol sucht Nimboya nach Yenniku, dem jüngsten Sohn seines Häuptlings.",kw={"bloodscalp","dunkelspeer","grom'gol","die suche nach yenniku","nimboya","schlingendorntal","hauer","yenniku","zul'gurub"},ang={["faction:Horde"]="Als Verbündeter der Horde im Basislager Grom'gol könnt Ihr Nimboya helfen, die Angehörigen des Häuptlings der Dunkelspeere zu schützen. Er kam aus Orgrimmar, um nach dem Jungen zu suchen.",["race:Troll"]="Als Dunkelspeer-Troll könnt Ihr Nimboyas Ruf folgen, indem Ihr der Familie Eures Häuptlings helft und die Bloodscalp jagt, die möglicherweise Yenniku gefangen halten."},sec={{t="Der verschollene Häuptlingssohn",b="Im Basislager Grom'gol fürchtet Nimboya ein düsteres Schicksal für Yenniku, den jüngsten Sohn des Häuptlings der Dunkelspeere. Ein alter Stammesbrauch führte den Jungen zu den Gurubashi-Trollen von Zul'Gurub. Als der Darkspear tribe mit dem Orc-Kriegshäuptling Thrall seine Heimat verließ, blieb Yenniku zurück und ging verloren. Nimboya ist aus Orgrimmar ins Schlingendorntal zurückgekehrt, um den Sohn des Häuptlings zu finden und in Sicherheit zu bringen."},{t="Jagd auf die Bloodscalp",b="Nimboya vermutet, dass der Stamm der Bloodscalp Yenniku gefangen hält. Um zu beweisen, dass Ihr stark genug seid, sie zu jagen, schickt er Euch nach Norden, um neun Hauer von Bloodscalp-Trollen zu sammeln. Bringt die Trophäen als Beweis Eurer Stärke im Kampf zum Basislager Grom'gol zurück. Dann kann die Suche nach dem Jungen des Häuptlings mit Headhunting weitergehen."}},faq={{q="Wer ist Yenniku?",a="Yenniku ist der jüngste Sohn des Häuptlings der Dunkelspeere. Ein Stammesbrauch führte ihn zu den Gurubashi-Trollen in Zul'Gurub, und als sein Volk die Region verließ, wurde er von ihm getrennt.",al={"yennikus geschichte","wer ist yenniku","sohn des häuptlings"}},{q="Warum blieb Yenniku im Schlingendorntal zurück?",a="Ein Stammesbrauch führte Yenniku zu den Gurubashi-Trollen von Zul'Gurub. Als der Stamm der Dunkelspeere mit Thrall fortzog, ging ihm der Junge verloren.",al={"warum blieb yenniku zurück","wie ging yenniku verloren","warum zul'gurub"}},{q="Wer ist Nimboya?",a="Nimboya ist ein Dunkelspeer-Troll im Basislager Grom'gol. Er kehrte aus Orgrimmar ins Schlingendorntal zurück, um nach dem verschollenen Sohn seines Häuptlings zu suchen.",al={"wer vergibt die suche nach yenniku","nimboya","kundschafter von grom'gol"}},{q="Warum müsst Ihr Hauer der Bloodscalp sammeln?",a="Nimboya vermutet, dass der Stamm der Bloodscalp Yenniku gefangen hält. Er bittet Euch, neun Hauer der Bloodscalp als Beweis dafür zurückzubringen, dass Ihr stark genug seid, diese feindseligen Trolle zu jagen.",al={"zweck der bloodscalp-hauer","warum hauer","die suche nach yenniku hauer"}},{q="Wo befinden sich die Bloodscalp-Trolle?",a="Nimboya schickt Jäger vom Basislager Grom'gol nach Norden in das Gebiet der Bloodscalp.",al={"wo sind bloodscalp zu finden","bloodscalp standort","wo sind bloodscalp-trolle"}}},fp="16,227,22.403.0,23.315.0,15.188.0,45.133.0,15.140.0,44.166.0,40.78.0"}
P.entries["quest:582"] = {n="Kopfjägerei",s="Im Basislager Grom'gol sucht Nimboya nach Nachrichten über Yenniku, den Sohn des Dunkelspeer-Häuptlings. Er schickt Euch los, um Bloodscalp-Kopfjäger zu jagen und ihre Schrumpfköpfe zurückzubringen, in der Hoffnung zu erfahren, ob Yenniku tot ist.",h="Im Basislager Grom'gol sucht Nimboya nach Nachrichten über Yenniku, den Sohn des Dunkelspeer-Häuptlings.",kw={"bloodscalp","gan'zulah","basislager grom'gol","kopfjägerei","nimboya","schrumpfkopf","yenniku","zul'kunda","zuuldaia"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr Euren Dunkelspeer-Verbündeten im Basislager Grom'gol herauszufinden, ob der vermisste Sohn ihres Häuptlings noch lebt.",["race:Troll"]="Als Troll teilt Ihr die Sorge der Dunkelspeer um den Sohn des Häuptlings. Die Dunkelspeer müssen sich dem Bloodscalp-Stamm stellen, um zu erfahren, was mit ihm geschehen ist."},sec={{t="Die Trophäen durchsuchen",b="Nimboya fürchtet, dass der Bloodscalp-Stamm Yenniku, den Sohn des Dunkelspeer-Häuptlings, getötet haben könnte. Die Suche begann mit Hunt for Yenniku, und nun schickt er Euch zu den Bloodscalp Headhunters bei den Ruinen von Zuuldaia und Zul'Kunda an der Nordküste des Schlingendorntals.\n\nBringt zwanzig Schrumpfköpfe zurück. Nimboya wird sie auf Anzeichen dafür untersuchen, dass Yenniku ein gewaltsames Ende fand. Falls der Jüngling tot ist, verflucht Nimboya Gan'zulah, den Häuptling der Bloodscalp."}},faq={{q="Wer sucht nach Yenniku?",a="Nimboya im Basislager Grom'gol sucht nach Yenniku, dem Sohn des Häuptlings des Dunkelspeer-Stammes.",al={"wer vergibt kopfjägerei","nimboyas absicht","warum yenniku finden"}},{q="Warum will Nimboya Schrumpfköpfe?",a="Nimboya wird die von Bloodscalp-Kopfjägern erbeuteten Schrumpfköpfe untersuchen, um herauszufinden, ob Yennikus Kopf unter ihren Trophäen ist.",al={"warum schrumpfköpfe sammeln","zweck der schrumpfköpfe","was macht nimboya mit den köpfen"}},{q="Wo sind die Bloodscalp Headhunters zu finden?",a="Die Bloodscalp Headhunters sammeln sich an der Nordküste des Schlingendorntals, besonders in der Nähe der Ruinen von Zuuldaia und Zul'Kunda.",al={"fundort der kopfjäger","wo sind zuuldaia und zulkunda","wo schrumpfköpfe finden"}},{q="Wer führt den hier erwähnten Bloodscalp-Stamm an?",a="Häuptling Gan'zulah führt den Bloodscalp-Stamm an. Falls Yenniku tot ist, wünscht Nimboya Gan'zulahs Geist einen sechshundertjährigen Fluch.",al={"häuptling der bloodscalp","wer ist ganzulah","ganzulah häuptling"}}},fp="11,206,22.438.0,27.95.0,37.126.0,46.127.0,46.128.0"}
P.entries["quest:5821"] = {n="Leibwache zu mieten",s="In Desolace halten Cork Gizelton und Rigger ihre Kodokarawane an, sobald die Kriegstrommeln der Zentauren ertönen. Cork bittet Euch, sie am Dorf der Kolkar vorbeizubegleiten, und die Bezahlung wartet ein Stück die Straße hinunter.",h="In Desolace halten Cork Gizelton und Rigger ihre Kodokarawane an, sobald die Kriegstrommeln der Zentauren...",kw={"leibwache","zentaur","cork gizelton","desolace","gizelton-karawane","kolkar","rigger","smeed scrabblescrew"},sec={{t="Kriegstrommeln",b="Cork Gizelton und Rigger führen ihre Kodokarawane an den Kolkar-Zentauren vorbei. Dann ertönen die Kriegstrommeln, und die Karawane hält an. Tote Händler bringen keinen Gewinn, also bittet Cork Euch, die Karawane ein kurzes Stück am Dorf der Kolkar vorbeizubegleiten und sie zu beschützen. Die Karawane wartet nördlich von Kolkar und südöstlich der Festung Donneraxt."},{t="Smeed Scrabblescrew",b="Smeed Scrabblescrew wartet mit der Bezahlung in Scrabblescrews Lager, ein Stück die Straße hinunter. Smeed treibt ein wenig Handel mit der Gizelton-Karawane."}},faq={{q="Wer ist Cork Gizelton?",a="Cork Gizelton führt zusammen mit Rigger eine Kodokarawane durch Desolace. Sie halten an, sobald die Kriegstrommeln der Zentauren ertönen.",al={"cork gizelton","wer vergibt leibwache zu mieten","wer startet das"}},{q="Warum braucht die Karawane Schutz?",a="Die Karawane braucht Schutz, weil Cork und Rigger anhalten, sobald die Kriegstrommeln der Zentauren ertönen. Tote Händler bringen keinen Gewinn.",al={"warum eine leibwache nötig ist","warum die karawane angehalten hat","warum warten sie"}},{q="Wo beginnt diese Eskorte?",a="Die Eskorte beginnt nördlich von Kolkar und südöstlich der Festung Donneraxt.",al={"leibwache zu mieten ort","wo startet die karawane","startpunkt der eskorte"}},{q="Wo wartet die Bezahlung?",a="Die Bezahlung wartet bei Smeed Scrabblescrew in Scrabblescrews Lager, ein Stück die Straße hinunter. Smeed treibt ein wenig Handel mit Cork.",al={"wer gibt die belohnung","wo abgeben","wer ist smeed"}}},fp="18,183,9.325.0,19.147.0,21.112.0,37.125.0,29.84.0,29.131.0"}
P.entries["quest:583"] = {n="Willkommen im Dschungel",s="Im Schlingendorntal begrüßt Barnil Stonepot Neuankömmlinge im Jagdlager und erkennt einen erfahrenen Wanderer. Er bietet Euch an, Euch Hemet Nesingwary vorzustellen, dem Leiter der Expedition.",h="Im Schlingendorntal begrüßt Barnil Stonepot Neuankömmlinge im Jagdlager und erkennt einen erfahrenen Wanderer.",kw={"barnil","hemet","nesingwary","panther","raptor","stonepot","schlingendorntal","tiger"},ang={["class:Hunter"]="Als Jäger im Dschungel des Schlingendorntals könntet Ihr feststellen, dass Hemet Nesingwary Jagdtipps für Euch hat.",["faction:Alliance"]="Als Veteran der Allianz erfahrt Ihr von Barnil Stonepot, dass Hemet Nesingwary ein berühmter Kriegsheld ist, der andere Veteranen bevorzugt.",["race:Dwarf"]="Als Zwerg gehört Ihr demselben Volk an wie der berühmte Jäger des Lagers, Hemet Nesingwary. Barnil Stonepot weist auf ihn als Meister der Großwildjagd hin."},sec={{t="Eine Audienz beim Meister",b="Barnil Stonepot begrüßt Neuankömmlinge im Lager im Schlingendorntal. Er erkennt kampferprobte Kämpfer und weist auf Hemet Nesingwary hin, einen Kriegshelden der Allianz und unvergleichlichen Fährtenleser. Nesingwary umgibt sich mit Veteranen, die sich bewährt haben. Barnil glaubt, dass der alte Schütze seine Jagdweisheit vielleicht mit jemandem teilt, der Schlachten überstanden hat."},{t="Die Prüfungen der Expedition",b="Hemet Nesingwary heißt Euch willkommen und bemerkt, wie selten man in diesen wilden Landen jemanden Eurer Berufung trifft. Seine Expedition kam hierher, um eine legendäre, schwer zu fassende Dschungelbestie zu jagen. Er wird Euch an der Jagd beteiligen, sobald Ihr durch die Jagd auf geringere Beute sein Vertrauen verdient habt. Nesingwary leitet die Raptorenjagd. Seine Kameraden Ajeck und Sir Erlgadin lehren Jäger, Tigern und Panthern nachzustellen."}},faq={{q="Wer ist Hemet Nesingwary?",a="Hemet Nesingwary ist ein gefeierter Kriegsveteran der Allianz und ein berühmter Großwildjäger. Er leitet ein Expeditionslager im Dschungel des Schlingendorntals.",al={"hemet nesingwary","wer ist hemet","nesingwarys geschichte"}},{q="Wer schickt Euch zu Nesingwary?",a="Barnil Stonepot im Dschungellager erkennt die Kampferfahrung erfahrener Abenteurer und schickt sie zu Nesingwary, um ihn zu begrüßen.",al={"barnil stonepot","questgeber","wer startet willkommen im dschungel"}},{q="Was folgt auf das Gespräch mit Nesingwary?",a="Nach Eurem Gespräch mit Nesingwary stehen Euch mehrere Jagden offen: Raptor Mastery, Tiger Mastery, Panther Mastery und die Grünen Hügel des Schlingendorntals.",al={"wie an der jagd teilnehmen","nesingwarys prüfungen","jagdunterricht"}}},fp="21,181,27.334.0,28.373.1,24.144.0,39.134.0,42.140.0"}
P.entries["quest:584"] = {n="Köpfe des Bloodscalpklans",s="Nimboya sucht auch nach dem Sortieren der Trophäen weiter nach Nachricht von Yenniku. Der junge Troll ist verschwunden, also wenden sich die Dunkelspeer an die Köpfe des Bloodscalpklans, um Antworten zu erhalten.",h="Nimboya sucht auch nach dem Sortieren der Trophäen weiter nach Nachricht von Yenniku.",kw={"bloodscalp","kessel","dunkelspeer","gan'zulah","grom'gol","nezzliok","nimboya","yenniku","zul'kunda"},ang={["faction:Horde"]="Als Mitglied der Horde unterstützt Ihr im Basislager Grom'gol mit Eurer Kraft die Suche der Dunkelspeer nach Yenniku.",["race:Troll"]="Als Dunkelspeer stellt Ihr Euch den Anführern eines feindlichen Stammes, wenn Ihr den Häuptlingen der Bloodscalp entgegentretet."},sec={{t="Den Toten Antworten abverlangen",b="Nimboya sucht bei den Anführern der Bloodscalp nach Antworten. Die frühere Jagd ergab keine Spur von Yenniku unter den Gefallenen. Gan'zulah, der Häuptling der Bloodscalp, und Nezzliok the Dire, sein Hexendoktor, sind Feinde der Dunkelspeer. Keiner von ihnen würde freiwillig reden. Also plant Nimboya, ihre Köpfe zum Kessel im Basislager Grom'gol zu bringen und ihren toten Lippen die Wahrheit abzuzwingen."},{t="Nach Zul'Kunda",b="Gan'zulah und Nezzliok hausen tief in den Ruinen von Zul'Kunda im nordwestlichen Schlingendorntal. Nimboya will ihre Köpfe in das kochende Gebräu werfen und sie dazu zwingen, über Yenniku zu sprechen."}},faq={{q="Warum will Nimboya die Köpfe von Gan'zulah und Nezzliok?",a="Yenniku bleibt verschwunden, und Nimboya glaubt, dass Gan'zulah und Nezzliok die Wahrheit kennen. Sie sind Feinde der Dunkelspeer und würden niemals freiwillig reden, also will er ihnen mithilfe des Kessels Antworten abzwingen.",al={"warum bloodscalp-anführer töten","warum abgetrennte köpfe","nimboyas beweggründe"}},{q="Wo befinden sich Gan'zulah und Nezzliok?",a="Gan'zulah und Nezzliok hausen tief in Zul'Kunda, einer Ruine im nordwestlichen Schlingendorntal, nahe dem Strand.",al={"wo ist ganzulah","wo ist nezzliok","bloodscalp-häuptlinge finden","zulkunda lage"}},{q="Was geschieht, sobald die Köpfe abgeliefert sind?",a="Die abgetrennten Köpfe kommen in den brodelnden Kessel im Basislager Grom'gol. Dort will Nimboya die beiden Anführer zum Reden bringen.",al={"wohin kommen die köpfe","was mit den köpfen tun","brodelnder kessel abgabe"}},{q="Wie hängt das mit der Suche nach Yenniku zusammen?",a="Die Suche begann mit dem jungen Yenniku. Die frühere Jagd ergab keine Spur von ihm unter den gewöhnlichen Toten, also suchen die Dunkelspeer nun bei den Anführern der Bloodscalp nach Antworten auf die Frage, wo er ist.",al={"yenniku questreihe","zusammenhang mit der suche nach yenniku"}}},fp="21,158,31.363.0,14.186.0,58.212.0,41.114.0,42.122.0,48.181.0"}
P.entries["quest:585"] = {n="Mit Nezzliok sprechen",s="Im Basislager Grom'gol spricht Nezzlioks abgetrennter Kopf aus einem brodelnden Kessel. Der Hexendoktor der Bloodscalp weiß, wohin Yenniku gebracht wurde, verlangt aber einen finsteren Tribut, bevor er es Euch verrät.",h="Im Basislager Grom'gol spricht Nezzlioks abgetrennter Kopf aus einem brodelnden Kessel.",kw={"balia'mah","bloodscalp","kessel","grom'gol","nezzliok","schädelspalter","schlingendorntal","yenniku","ziata'jai","zul'mamwe"},ang={["faction:Horde"]="Als Mitglied der Horde verhandelt Ihr im Basislager Grom'gol mit einem gebundenen feindlichen Geist, um Yennikus Schicksal zu erfahren, des Sohnes des Dunkelspeer-Häuptlings.",["race:Troll"]="Als Dunkelspeer-Troll verhandelt Ihr mit dem abgetrennten Kopf eines feindlichen Hexendoktors der Bloodscalp, um zu erfahren, was aus dem entführten Sohn Eures Häuptlings wurde."},sec={{t="Der Preis eines Geistes",b="Nezzliok bleibt nach der Jagd auf Köpfe des Bloodscalp-Clans im brodelnden Kessel gebunden. Er weiß, wohin Yenniku gebracht wurde, doch er gibt nichts freiwillig preis. Bringt drei Trophäenschädel vom verfeindeten Stamm der Schädelspalter zu seiner Ruhestätte. Dann kann sein verstorbener Geist im Nether über Knechte gebieten."},{t="Schädel der Rivalen",b="Nezzliok verlangt einen Schädel aus dem Trophäenhaufen der Schädelspalter bei Balia'mah, einen aus Ziata'jai und einen aus Zul'Mamwe. Alle drei Gaben müssen neben seinem eigenen Kopf liegen, bevor der tote Hexendoktor seinen Geist als zufriedengestellt betrachtet."}},faq={{q="Wer ist Nezzliok?",a="Nezzliok war ein Hexendoktor des Bloodscalp-Stammes. Nachdem er im Kampf gefallen war, wurde sein abgetrennter Kopf in einen brodelnden Kessel im Basislager Grom'gol gelegt. Sein gebundener Geist spricht dort noch immer.",al={"nezzliok","hexendoktor nezzliok","nezzlioks geschichte"}},{q="Was verlangt Nezzliok?",a="Nezzliok verlangt drei Trophäenschädel aus den Lagern seiner verhassten Rivalen, der Schädelspalter. Holt einen aus Balia'mah, einen aus Ziata'jai und einen aus Zul'Mamwe.",al={"was will nezzliok","nezzlioks trophäen","mit nezzliok sprechen ziel"}},{q="Warum will Nezzliok Trophäen der Schädelspalter?",a="Nezzliok will die Trophäenschädel neben sich liegen haben, damit drei Diener im Tod an ihn gebunden sind, wenn sein Geist in den Nether übergeht.",al={"warum trophäenschädel","warum nezzliok schädel will"}},{q="Wo geschieht das?",a="Die Begegnung findet am brodelnden Kessel im Basislager Grom'gol statt, tief im Schlingendorntal.",al={"wo ist nezzliok","standort des brodelnden kessels"}}},fp="22,186,16.295.0,20.233.0,16.188.0,26.161.0,46.150.0,23.101.0"}
P.entries["quest:586"] = {n="Mit Gan'zulah sprechen",s="Im Basislager Grom'gol verflucht Gan'zulah jene, die über dem blubbernden Topf stehen. Der Häuptling der Bloodscalp verlangt den Tod seiner Schädelspalterrivalen und den Untergang ihres Herrschers, Ana'thek des Grausamen.",h="Im Basislager Grom'gol verflucht Gan'zulah jene, die über dem blubbernden Topf stehen.",kw={"ana'thek","berserker","bloodscalp","kessel","gan'zulah","grom'gol","kopfjäger","schädelspalter","schlingendorntal"},ang={["faction:Horde"]="Gan'zulahs Kopf ruht im Kessel im Basislager Grom'gol. Er schickt Champions der Horde gegen seine Feinde, die Schädelspalter.",["race:Troll"]="Als Dunkelspeertroll seht Ihr, wie die Häuptlinge der Bloodscalp und der Schädelspalter ihren unsterblichen Hass gegeneinander richten. Ihre Fehde zeigt die Brutalität des Dschungels."},sec={{t="Die Rache eines Häuptlings",b="Gan'zulahs abgetrennter Kopf verflucht jeden, der über dem blubbernden Topf steht. Obwohl er tot ist, hasst der Häuptling der Bloodscalp noch immer seine Entführer und angestammten Feinde. Er weist Euch nach Osten zur Feste der Schädelspalter und verlangt den Tod ihrer Jäger, Kopfjäger und Berserker. Ihr wilder Kriegstrupp könnte jene töten, die es wagen, sich ihm zu stellen."},{t="Die zerbrochene Rüstung",b="Gan'zulah erwartet, dass der Angriff in einer Katastrophe endet. Er glaubt, Häuptling Ana'thek der Grausame werde jeden Eindringling zerreißen, der ihn herausfordert. Dennoch verlangt er Ana'theks zerbrochene Rüstung als Beweis des Triumphs. Bringt diese Trophäe zum Kessel im Basislager Grom'gol zurück, um Gan'zulahs Bosheit zu stillen."},{t="Ein brüchiger Frieden",b="Gan'zulah verstummt, als Ana'theks zerbrochene Rüstung vor ihn gebracht wird. Die Niederlage seines Rivalen lindert endlich den rachsüchtigen Zorn des Häuptlings der Bloodscalp. Er erkennt die Stärke an, die nötig war, um Ana'thek zu besiegen, schwört aber, dass ihre Abrechnung nur aufgeschoben ist. Gan'zulah schwört, dass sie im Nether erneut aufeinanderprallen werden."}},faq={{q="Wohin sollt Ihr nach Gan'zulahs Willen gehen?",a="Gan'zulah schickt Euch nach Osten ins Gebiet der Schädelspalter, wo sich ihre Kämpfer unter Ana'thek dem Grausamen sammeln.",al={"wo sind die schädelspalter","wohin bei mit gan'zulah sprechen","standort der schädelspalter"}},{q="Wer ist Ana'thek der Grausame?",a="Ana'thek der Grausame führt die Schädelspaltertrolle an und ist ein verhasster Rivale von Gan'zulah und dem Stamm der Bloodscalp.",al={"wer ist anatek","wer ist der häuptling der schädelspalter","geschichte von anatek dem grausamen"}},{q="Warum kann Gan'zulah sprechen?",a="Gan'zulahs abgetrennter Kopf ruht im verzauberten Kessel im Basislager Grom'gol. Aus dem Jenseits spricht sein Geist Flüche und Forderungen aus.",al={"wie kann ganzulah sprechen","warum spricht der kopf","ganzulah kessel"}},{q="Welche Trophäe verlangt Gan'zulah?",a="Gan'zulah verlangt die zerbrochene Rüstung von Häuptling Ana'thek dem Grausamen und den Tod der Jäger, Kopfjäger und Berserker der Schädelspalter.",al={"welchen gegenstand braucht ganzulah","zerbrochene rüstung von anatek","gegenstand bei ganzulah abgeben"}},{q="Wie geht es weiter, nachdem Ihr Gan'zulah geholfen habt?",a="Nachdem Ihr Euch um die Stammeshäuptlinge gekümmert habt, setzt Ihr die Suche mit The Fate of Yenniku fort, um das Schicksal des jungen Dunkelspeertrolls zu erfahren.",al={"was folgt auf mit gan'zulah sprechen","nächste quest nach ganzulah","folgequest zu mit gan'zulah sprechen"}}},fp="23,199,23.337.0,16.292.0,15.303.1,36.108.0,26.109.0,30.136.0,34.131.0,40.143.0"}
P.entries["quest:5863"] = {n="Das Truppenlager der Dünenbrecher",s="In der Wüste südlich von Gadgetzan fürchtet Andi Lynn eine wachsende Ogerstreitmacht. Sie will das Lager zerstört sehen, bevor die Oger weiter an Stärke gewinnen.",h="In der Wüste südlich von Gadgetzan fürchtet Andi Lynn eine wachsende Ogerstreitmacht.",kw={"andi lynn","dunemaul","dunemaul brute","truppenlager der dünenbrecher","dunemaul enforcer","gadgetzan","gor'marok the ravager","oger","tanaris"},sec={{t="Oger in der Wüste",b="Eine große Schar nomadischer Oger hat Tanaris erreicht. Südlich von Gadgetzan haben sie einen weiten Wüstenstrich für sich beansprucht und ihr Lager errichtet. Kleinere Gruppen durchstreifen die Wüste, und einige sind in die alten Trollruinen eingedrungen. Andi Lynn fürchtet, was geschehen könnte, wenn die Oger stärker werden."},{t="Den Kopf abschlagen",b="Andi Lynn will, dass zehn Dunemaul Brutes und zehn Dunemaul Enforcers niedergestreckt werden. Gor'marok the Ravager führt die Schar an. Andi Lynn glaubt, dass die Oger auseinanderzufallen beginnen, sobald er sie nicht mehr befehligt."}},faq={{q="Wer fordert die Zerstörung des Truppenlagers der Dünenbrecher?",a="Andi Lynn in Gadgetzan fordert die Zerstörung des Truppenlagers der Dünenbrecher.",al={"andi lynn","wer vergibt die quest","questgeber"}},{q="Wo liegt das Truppenlager der Dünenbrecher?",a="Die Oger haben einen weiten Wüstenstrich südlich von Gadgetzan für sich beansprucht.",al={"truppenlager der dünenbrecher standort","wo sind die oger","dunemaul standort"}},{q="Wer führt die Dunemaul-Oger an?",a="Gor'marok the Ravager führt die Dunemaul-Oger an. Andi Lynn glaubt, dass ihr Niedergang beginnt, sobald er sie nicht mehr befehligt.",al={"ogeranführer","wer ist gormarok","gor'marok the ravager"}},{q="Warum sieht Andi Lynn die Oger als Gefahr an?",a="Andi Lynn fürchtet, dass die Oger an Stärke gewinnen. Eine große Schar hält ein Lager südlich von Gadgetzan, während kleinere Gruppen die Wüste durchstreifen und einige in die alten Trollruinen eingedrungen sind.",al={"warum die oger töten","ogergefahr tanaris"}}},fp="21,148,19.273.0,20.194.0,51.73.0,31.68.0,29.123.0,45.177.0"}
P.entries["quest:587"] = {n="Auf dem Schnupftabak",s="In Beutebucht wartet Deeg auf seinen geliebten Schnupftabak, doch der Kräuterkundige hat keinen zu verkaufen. Bloodsail Raiders sollen die Lieferung gekapert haben, und Deeg bittet Euch, ihm fünfzehn Portionen zu bringen.",h="In Beutebucht wartet Deeg auf seinen geliebten Schnupftabak, doch der Kräuterkundige hat keinen zu verkaufen.",kw={"bloodsail","beutebucht","deeg","grog","kräuterkundiger","schnupftabak"},sec={{t="Laster an Land",b="Deeg weiß, dass das Leben auf See karg sein mag, doch es ist das einzige Leben, das er hat. Wann immer er einen Hafen erreicht, sucht er nach Grog und feinem Schnupftabak.\n\nDem Kräuterkundigen in Beutebucht ist der Vorrat ausgegangen. Der Kräuterkundige sagt, Bloodsail Raiders hätten die Lieferung gekapert, also hofft Deeg, ein furchtloser Reisender könne sie zum Teilen bewegen. Er möchte fünfzehn Portionen Schnupftabak."},{t="Deegs Dank",b="Deeg ist hocherfreut, als der Schnupftabak kurz vor seinem Auslaufen eintrifft. Er dankt Euch herzlich, wie er einem alten Freund danken würde."}},faq={{q="Wer ist Deeg?",a="Deeg ist ein Pirat in Beutebucht, der nach Grog und feinem Schnupftabak sucht, wann immer er in den Hafen kommt.",al={"deeg beutebucht","wer vergibt auf dem schnupftabak"}},{q="Warum hat der Kräuterkundige keinen Schnupftabak mehr?",a="Der Kräuterkundige in Beutebucht sagt, Bloodsail Raiders hätten die Schnupftabaklieferung gekapert.",al={"warum kein schnupftabak","kräuterkundiger lieferung gekapert"}},{q="Wer hat den Schnupftabak?",a="Der Kräuterkundige sagt, Bloodsail Raiders hätten die Lieferung gekapert, und Deeg hofft, dass Ihr sie zum Teilen bewegen könnt.",al={"wer nahm den schnupftabak","bloodsail schnupftabak"}},{q="Wie viel Schnupftabak möchte Deeg?",a="Deeg möchte, dass ihm fünfzehn Portionen Schnupftabak nach Beutebucht gebracht werden.",al={"wie viel schnupftabak","auf dem schnupftabak anforderung"}}},fp="11,191,12.324.0,13.115.1,12.90.0,34.78.0,18.109.0,30.63.0"}
P.entries["quest:588"] = {n="Yennikus Schicksal",s="Im Basislager Grom'gol spricht Nezzlioks Kopf aus dem Kessel über Yenniku. Kin'weelay wartet daneben auf die Worte des Geistes.",h="Im Basislager Grom'gol spricht Nezzlioks Kopf aus dem Kessel über Yenniku.",kw={"kessel","grom'gol","kin'weelay","nezzliok","yenniku","zanzil"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, wie sehr dem Dunkelspeerstamm und seinen Verbündeten im Basislager Grom'gol daran liegt, den Sohn des Häuptlings zurückzuholen."},sec={{t="Worte aus dem Kessel",b="Ihr habt die Geister von Gan'zulah und Nezzliok besänftigt. Nun spricht Nezzlioks Kopf aus dem brodelnden Kessel. Kin'weelay wartet daneben, um das Geheimnis zu hören."},{t="Was der Kopf offenbarte",b="Nezzliok nennt den Hexendoktor Zanzil the Outcast als denjenigen, der Yenniku seinem Clan entrissen hat. Nur mächtige Magie kann den Jungen aus Zanzils Bann befreien. Kin'weelay hört die Worte, und ihm bleibt nur eine schwache Hoffnung."}},faq={{q="Wer verrät Yennikus Aufenthaltsort?",a="Nezzlioks Kopf spricht durch den brodelnden Kessel und erzählt, was Yenniku widerfahren ist.",al={"wer spricht aus dem kessel","wer enthüllt yennikus schicksal","stimme aus dem kessel"}},{q="Wer soll von Nezzlioks Worten erfahren?",a="Kin'weelay wartet neben dem brodelnden Kessel am nördlichen Rand des Basislagers Grom'gol. Nezzlioks Worte sind für Kin'weelay bestimmt.",al={"mit wem sprechen","yennikus schicksal abgeben","kin'weelays aufenthaltsort"}}},fp="19,126,21.156.0,22.209.1,34.88.0,43.132.0"}
P.entries["quest:5881"] = {n="Hinzurufen der Reserve",s="In Sonnenfels schickt Maggran Erdbinder Euch nach Süden, um einen erschöpften Wachposten am Großen Aufzug abzulösen. Er gibt Euch einen Brief für Grish Fernläufer, der fern der Heimat Wache gehalten hat.",h="In Sonnenfels schickt Maggran Erdbinder Euch nach Süden, um einen erschöpften Wachposten am Großen Aufzug...",kw={"hinzurufen der reserve","der große aufzug","grish fernläufer","maggran erdbinder","steinkrallengebirge","sonnenfels","brachland","tausend nadeln"},ang={["faction:Horde"]="Als Mitglied der Horde erlebt Ihr, wie Kommandanten die Wachposten im Grenzgebiet Kalimdors regelmäßig ablösen, um die Moral hochzuhalten und die Wachen zuverlässig zu besetzen.",["race:Tauren"]="Als Tauren helft Ihr, den Durchgang am Großen Aufzug zu den weitläufigen Gebieten von Donnerfels offenzuhalten."},sec={{t="Eine lang ersehnte Ablösung",b="Maggran Erdbinder kümmert sich in Sonnenfels im Steinkrallengebirge um das Wohlergehen und die Versorgung der Truppen. In ganz Kalimdor hat die Horde selbst nach dem Dritten Krieg Mühe, ihre Garnisonen ausreichend zu besetzen. Maggran weiß, dass endloser Wachdienst erfahrene Soldaten zermürbt. Deshalb schickt er einen Versetzungsbrief nach Süden zum Großen Aufzug, wo Grish Fernläufer fern der Heimat Wache gehalten hat."},{t="Wache am Aufzug",b="Der Große Aufzug verbindet das südliche Brachland mit den Schluchten von Tausend Nadeln. Mit Maggrans Brief in der Hand kann Grish seine einsame Wache über die Aufzugsmechanismen beenden und zu seiner Familie zurückkehren. Frische Reserven können seinen Platz einnehmen."}},faq={{q="Bei wem beginnt diese Quest?",a="Maggran Erdbinder gibt Euch den Brief in Sonnenfels im Steinkrallengebirge.",al={"questgeber","wo beginnt hinzurufen der reserve","maggran erdbinder standort"}},{q="Wo soll Maggrans Brief abgegeben werden?",a="Bringt Maggrans Reservebrief nach Süden durch das Brachland zum Großen Aufzug oberhalb von Tausend Nadeln.",al={"grish fernläufer standort","wo ist grish","wo ist der große aufzug"}},{q="Warum braucht Grish Fernläufer eine Ablösung?",a="Grish Fernläufer bewacht die Aufzugsmechanismen schon lange allein. Er bat um Ablösung, damit er nach Hause reisen und seine Familie besuchen könnte.",al={"grish hintergrundgeschichte","warum grish geht","wachdienst am großen aufzug"}},{q="Sind für diese Quest Kämpfe erforderlich?",a="Es sind keine Kämpfe erforderlich. Ihr bringt eine Nachricht nach Süden in Richtung Tausend Nadeln.",al={"kämpfe nötig","friedliche quest","kurierauftrag"}},{q="Bei welcher Fraktion gibt es für den Abschluss Ruf?",a="Die Übergabe des Briefes gewährt Euch Ruf bei Donnerfels, dessen Tauren die Route beaufsichtigen.",al={"rufbelohnung","welchen ruf gibt diese quest","donnerfels ruf"}},{q="Wohin führt diese Quest als Nächstes?",a="Die Lieferung führt Euch zum oberen Ende des Großen Aufzugs. Ihr könnt damit in die Schluchten von Tausend Nadeln hinabfahren und weitere Außenposten der Horde erkunden.",al={"nächste quest","wohin danach","hinführungsquest nach tausend nadeln"}}},fx={["39c5e94c"]={q="Warum will Maggran Erdbinder, dass dies erledigt wird?",a="Maggran ist stolz auf den Wohlstand der Horde und ihr Engagement, ihre Soldaten regelmäßig abzulösen und zu erfrischen. Grish Fernläufer hat vor einiger Zeit um Urlaub gebeten, um zu seiner Familie zurückzukehren, und Maggran hat endlich einen Reservekrieger bereit, um ihn auf seinem abgelegenen Posten auf dem großen Aufzug zu ersetzen.",al={"warum den brief schicken","zweck des reserve-briefs von maggran","warum ablösung zu grish schicken"}}},fp="23,180,21.382.0,17.227.0,22.89.0,36.98.0,38.141.0,44.73.0,52.95.0,32.144.0"}
P.entries["quest:589"] = {n="Die singenden Kristalle",s="Kin'weelay sucht einen Weg, Yenniku aus der Dunkelheit zu befreien, die ihn gefangen hält. Er wendet sich dem Gedankenauge zu und bittet Euch, Splitter zu sammeln, die ihm helfen könnten, dessen Macht zu beherrschen.",h="Kin'weelay sucht einen Weg, Yenniku aus der Dunkelheit zu befreien, die ihn gefangen hält.",kw={"kristalladermine","grom'gol","eisenkieferbasilisk","kin'weelay","gedankenauge","pulsierender blauer splitter","schlingendorntal","yenniku"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr dem Stamm der Dunkelspeer im Basislager Grom'gol bei seinen Bemühungen, den verschollenen Sohn seines Häuptlings zurückzuholen."},sec={{t="Echos des Gedankenauges",b="Kin'weelay durchforscht altes Dschungelwissen nach einem Weg, Yennikus Geist zu befreien. Die Geschichten erzählen vom Gedankenauge, einem tief im Schlingendorntal verborgenen Edelstein mit mächtiger Magie. Kin'weelay glaubt, dass es die Antwort bergen könnte. Während er die Dschungelgeister um Führung bittet, um es zu finden, braucht er seltene Katalysatoren, um seine Zauberei sicher zu beherrschen."},{t="Die Crystalvein Caverns",b="Kin'weelay schickt Euch nach Südosten zur Kristalladermine, wo Eisenkieferbasilisken unter der Erde hausen. Er bittet Euch, ihnen drei pulsierende blaue Splitter abzunehmen. Er plant, die Magie dieser singenden Steine während eines abschließenden Rituals zu kanalisieren. Sobald er das Gedankenauge geborgen hat, will er dessen Macht seinem Willen unterwerfen."}},faq={{q="Wer bietet diese Aufgabe an?",a="Kin'weelay, ein Trollmedizinmann im Basislager Grom'gol im Schlingendorntal, bietet diese Arbeit an.",al={"wer vergibt die singenden kristalle","questgeber","wo beginnen die singenden kristalle"}},{q="Warum werden die pulsierenden blauen Splitter benötigt?",a="Kin'weelay braucht die Magie der Splitter, um das Gedankenauge zu beherrschen. Er hofft, Yenniku mithilfe des mächtigen Juwels den dunklen Mächten zu entreißen, die ihn gefangen halten.",al={"warum werden blaue splitter benötigt","wozu dienen die splitter","pulsierender blauer splitter zweck"}},{q="Wo sind die Eisenkieferbasilisken zu finden?",a="Eisenkieferbasilisken leben in der Kristalladermine, südöstlich des Basislagers Grom'gol in den Bergen östlich der Arena der Gurubashi.",al={"eisenkieferbasilisk fundort","wo sind eisenkieferbasilisken","wo ist die kristalladermine"}},{q="Was ging dieser Aufgabe voraus?",a="The Fate of Yenniku ging dieser Aufgabe voraus und offenbarte die verzweifelte Lage des jungen Trolls.",al={"die singenden kristalle vorquest","vorherige quest"}},{q="Was tut Kin'weelay, während Ihr die Splitter sammelt?",a="Kin'weelay spricht mit den Dschungelgeistern, um herauszufinden, wo das Gedankenauge verborgen ist und was es beschützt.",al={"was macht kinweelay","kinweelay rolle"}}},fp="20,163,24.314.0,23.315.0,21.95.0,39.151.0,41.121.0,27.81.0,53.110.0"}
P.entries["quest:59"] = {n="Rüstung aus Tuch und aus Leder",s="In Goldhain schickt Rüstung aus Tuch und aus Leder einen bewährten Reisenden nach Osten, um Ausrüstung zu beschaffen. Marschall Dughan stellt einen Rüstungsgutschein für Sara Roderwald im Holzfällerlager des Osttals aus. Jenseits der Brücke von Wache Thomas suchen Rekruten nach Rüstung zur Verteidigung des Reiches.",h="In Goldhain schickt Rüstung aus Tuch und aus Leder einen bewährten Reisenden nach Osten, um Ausrüstung zu...",kw={"rüstungsgutschein","rüstung aus tuch und aus leder","eastvale","wald von elwynn","wache thomas","holzfällerlager","marschall dughan","sara roderwald","armee von sturmwind"},ang={["faction:Alliance"]="Als Verteidiger der Allianz seht Ihr, wie örtliche Aufträge Elwynns ländlichen Gemeinden helfen, die Allianz am Laufen zu halten, während die Hauptstadt politisch gelähmt ist.",["profession:Tailoring"]="Als Schneider erkennt Ihr an Sara Roderwalds Armeeauftrag, dass die Stoffverarbeitung im Königreich ein offiziell gefördertes militärisches Handwerk ist.",["race:Human"]="Als Mensch spiegeln Euer Dienst für Marschall Dughan und Eure Geschäfte mit Sara Roderwald die bürgerlichen Bindungen wider, die Elwynns kleine Gehöfte zusammenhalten."},sec={{t="Der Gutschein des Marschalls",b="Wache Thomas bewacht Elwynns östlichen Flussübergang, wo Murlocs und Gnolle die Grenze bedrohen. Ihr bringt seinen Bericht nach Goldhain, und Marschall Dughan würdigt Euren Dienst mit einem offiziellen Rüstungsgutschein der Armee von Sturmwind. Die Garnison von Goldhain hat nur geringe Vorräte, daher gibt Euch Dughan einen Gutschein statt Ausrüstung. Es ist ein militärischer Gutschein, der Euren Dienst für die Krone festhält."},{t="The Weaver von Eastvale",b="Östlich der Brücke von Wache Thomas liegt das Holzfällerlager des Osttals, Elwynns wichtigster Holzgewinnungsbetrieb. Sara Roderwald arbeitet dort im Auftrag der Armee von Sturmwind und fertigt Stoff- und Lederausrüstung. Die zentralen Waffenkammern des Königreichs sind überlastet, daher rüsten örtliche Handwerker wie Sara Truppen und Hilfsspäher an der Grenze aus."}},faq={{q="Was ist ein Rüstungsgutschein der Armee von Sturmwind?",a="Ein Rüstungsgutschein der Armee von Sturmwind ist ein offizieller militärischer Anforderungsschein, den Offiziere wie Marschall Dughan ausstellen. Bewährte Rekruten können bei zivilen Handwerkern im Auftrag der Armee maßgefertigte Rüstung erhalten, statt dass Offiziere sperrige Rüstungssätze an ihren Posten lagern.",al={"rüstungsgutschein","gutschein von sturmwind","was ist der gutschein"}},{q="Wer ist Sara Roderwald?",a="Sara Roderwald ist eine Schneiderin und Handwerkerin, die im Holzfällerlager des Osttals lebt. Im Auftrag der Armee von Sturmwind fertigt sie Stoff- und Lederausrüstung für Angehörige des Königreichs und zugelassene Hilfskämpfer.",al={"sara roderwald","schneiderin in eastvale","wer fertigt die rüstung"}},{q="Wo liegt das Holzfällerlager des Osttals?",a="Das Holzfällerlager des Osttals liegt ganz im Osten des Waldes von Elwynn. Folgt vom Posten von Wache Thomas an der Flussbrücke der Straße nach Osten ins bewaldete Tal, wo Holzfäller Holz für das Königreich schlagen.",al={"lage von eastvale","wo liegt eastvale","wie zu roderwald gelangen"}},{q="Warum schickt Marschall Dughan Abenteurer nach Eastvale?",a="Marschall Dughan verweist Rekruten an Sara Roderwald in Eastvale, weil er an seinem Posten in Goldhain keine fertige Ausrüstung ausgibt. Nach tapferen Taten schickt er Reisende nach Osten, damit sie angemessenen Schutz für die Verteidigung Elwynns erhalten.",al={"warum marschall dughan gutschein","dughans absicht","warum eastvale"}},{q="Warum verlässt sich die Armee bei der Versorgung auf örtliche Schneider?",a="König Varian Wrynn wird vermisst, und Sturmwinds Militär ist durch Einsätze gegen Aktivitäten der Defias und wilde Tiere überlastet. Örtliche Verteidigungsposten sind auf vertraglich verpflichtete Arbeitskräfte aus der Region angewiesen, um den Nachschub aufrechtzuerhalten.",al={"sturmwinds versorgungsprobleme","warum örtliche handwerker","armeelogistik"}},{q="Gegen wen verteidigt Wache Thomas die Grenze?",a="Wache Thomas schützt die östliche Grenze des Waldes von Elwynn und die Brücke vor Flussmurlocs, umherstreifenden Bestien und der gefährlichen Wildnis am Rotkammgebirge.",al={"feinde von wache thomas","bedrohungen an der brücke","bedrohungen im östlichen elwynn"}}},fx={ebb61187={q="Warum möchte Marschall Dughan dies erledigt haben?",a="Marschall Dughan möchte Euren Mut und Eure Scharfsinnigkeit belohnen, nachdem Ihr den Bericht von Wache Thomas von der Ostgrenze überbracht habt. Indem er Euch eine offizielle Anforderungsmarke für Sara Roderwald aushändigt, stellt er sicher, dass Ihr angemessen mit robuster Stoff- oder Lederrüstung ausgestattet werdet, um den Wald von Elwynn weiterhin gegen wachsende Bedrohungen zu verteidigen.",al={"marschall dughan motiv","warum zu sara roderwald schicken","warum ruestungsmarke vergeben"}}},fp="23,236,19.363.0,22.315.0,33.270.0,23.210.0,35.188.0,53.223.0,54.199.0,38.162.0"}
P.entries["quest:590"] = {n="Ein Schurkenhandel",s="Calvin Montague bietet frisch erwachten Verlassenen in Todesend Arbeit an. Er verspricht Reichtum für das Überbringen eines Briefes, doch Ihr wisst nicht, ob er sich an die Abmachung halten wird.",h="Calvin Montague bietet frisch erwachten Verlassenen in Todesend Arbeit an.",kw={"ein schurkenhandel","prügelei","calvin montague","todesend","verlassener schurke","betrug","tirisfal"},ang={["class:Rogue"]="Als junger Schurke lernt Ihr im Umgang mit Calvin Montague, niemandem zu vertrauen, auf Euren Geldbeutel zu achten und niemals einen anderen Halunken mit Eurem Anteil davonkommen zu lassen.",["race:Undead"]="Als Verlassener merkt Ihr nach dem Erwachen in Todesend schnell, dass der Tod die kleinlichsten menschlichen Laster nicht auslöscht. Verlassene Beutelschneider betrügen ihresgleichen ebenso bereitwillig wie lebende Banditen."},sec={{t="Todesend",b="Todesend ist ein verfallenes Dorf im Südwesten von Tirisfal."},{t="Den Preis zahlen",b="Als Ihr mit dem Brief zurückkehrt, tut Calvin Montague so, als hätte es keine Abmachung gegeben, und bestreitet, Euch etwas zu schulden. Als Ihr das versprochene Silber verlangt, zieht er stattdessen seine Waffen. Er erwartet, einen unerfahrenen Verlassenen leicht niederstrecken zu können. Nach seiner Niederlage gibt er Euch ein paar Münzen und gesteht, über die Bezahlung gelogen zu haben, weil er glaubte, damit durchzukommen."}},faq={{q="Warum greift Calvin Montague an, wenn er zur Zahlung aufgefordert wird?",a="Calvin Montague ist ein skrupelloser Schurke, der seine Münzen nie teilen wollte. Als Ihr ihn wegen des gebrochenen Versprechens zur Rede stellt, versucht er, Euch zum Schweigen zu bringen, statt zu zahlen, da er einen frisch auferstandenen Verlassenen für leichte Beute hält.",al={"warum kämpft calvin","calvin montague feindselig","warum greift der schurke an"}},{q="Wo findet diese Konfrontation statt?",a="Die Konfrontation findet in Todesend statt, dem verfallenen Dorf im Südwesten von Tirisfal, wo frisch auferstandene Verlassene zum ersten Mal erwachen.",al={"wo ist calvin montague","calvin montague standort","wo ist ein schurkenhandel"}},{q="Zahlt Calvin Montague tatsächlich, was er versprochen hat?",a="Nein. Nachdem Ihr ihn besiegt habt, ergibt sich Calvin Montague und überreicht Euch ein paar Münzen, weit weniger als ursprünglich angeboten. Er gesteht, von Anfang an über den vollen Betrag gelogen zu haben.",al={"calvin belohnung","zahlt calvin","hat er über die münzen gelogen"}},{q="Wie wird diese zweite Aufgabe freigeschaltet?",a="Nachdem Ihr Calvin Montagues ersten Auftrag zur Briefzustellung abgeschlossen habt, kehrt zurück und verlangt die versprochenen Münzen. Sobald Ihr ihn wegen seines Betrugs zur Rede stellt, beginnt der Kampf.",al={"wie teil zwei erhalten","kampf bei ein schurkenhandel freischalten","geheime schurkenquest"}},{q="Stirbt Calvin Montague, wenn er besiegt wird?",a="Nein. Calvin Montague gibt auf, bevor ihn ein tödlicher Schlag trifft, lobt Eure Kampfkünste und öffnet widerwillig seinen Münzbeutel, um seine eigene Haut zu retten.",al={"habe ich calvin getötet","ist calvin tot","calvin ergibt sich"}},{q="Welche Lektion bietet diese Begegnung neuen Verlassenen?",a="Neuen Verlassenen bietet die Begegnung eine praktische Lektion über die raue Wirklichkeit: Ehre ist unter Untoten selten, Worte sind billig, und Respekt verdient man sich nur durch Kampfkraft.",al={"was ist der sinn von ein schurkenhandel","hintergrundgeschichte zu ein schurkenhandel"}}},fx={["80d08ba4"]={q="Warum müsst Ihr gegen Calvin Montague kämpfen?",a="Calvin Montague ist ein durch und durch verkommener Schurke. Nachdem er Euch mit falschen Versprechungen von Reichtum dazu gelockt hat, Eure schmutzige Arbeit zu erledigen, stellt er sich dumm, als Ihr zurückkehrt, um Eure Münzen einzufordern. Anstatt sich von seinem Silber zu trennen, entscheidet er, dass es billiger und einfacher ist, Euch einfach anzugreifen, in der Hoffnung, dass Ihr ein leichtes Opfer seid. Um Euren rechtmäßigen Lohn zu erhalten, müsst Ihr ihm Respekt – und Eure Bezahlung – einprügeln.",al={"warum gegen calvin montague kämpfen","wer ist das ziel von calvin montague","warum calvin angreifen"}}},fp="14,165,10.63.0,16.351.1,55.218.1,41.136.0,51.169.1,33.147.0,39.147.1,54.181.1"}
P.entries["quest:591"] = {n="Das Gedankenauge",s="Im Basislager Grom'gol sucht Kin'weelay das Gedankenauge, um Yenniku zu retten. Mai'Zoth besitzt den Edelstein tief im Ogerhügel der Mosh'Ogg.",h="Im Basislager Grom'gol sucht Kin'weelay das Gedankenauge, um Yenniku zu retten.",kw={"dunkelspeer","grom'gol","kin'weelay","mai'zoth","gedankenauge","mosh'ogg","ogerhügel","yenniku"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr den Dunkelspeertrollen, vom Basislager Grom'gol aus gegen die Festung der Mosh'Ogg vorzugehen.",["race:Troll"]="Als Troll braucht Ihr das Gedankenauge, um bei der Befreiung von Yenniku zu helfen, dem Sohn des Häuptlings der Dunkelspeere."},sec={{t="Ein mächtiger Edelstein",b="Nach der Bergung der singenden Kristalle wendet sich Kin'weelay dem Gedankenauge zu. Er glaubt, dass nur der Edelstein helfen kann, Yenniku zu retten, den Sohn des Häuptlings der Dunkelspeere. Mai'Zoth besitzt ihn. Kin'weelay erinnert sich an den Ogermagier aus den früheren Tagen der Darkspear tribe im Dschungel."},{t="Die Tiefen von Mosh'Ogg",b="Mai'Zoth haust tief im Ogerhügel der Mosh'Ogg, östlich von Grom'gol. Seine Magie war schon gewaltig, bevor er das Gedankenauge an sich nahm, und der Stein hat ihn noch stärker gemacht. Die Ogerfestung ist voller Gefahren. Doch der Edelstein ist die einzige Hoffnung des jungen Trolls auf Freiheit."},{t="In den Nether",b="Laut Kin'weelay verbannt Mai'Zoths Niederlage den Ogermagier aus dem Reich von Fleisch und Knochen in den Nether. Seine körperliche Bedrohung ist vorüber, doch Kin'weelay fürchtet insgeheim, Mai'Zoth könnte in der Geisterwelt ein neues Herrschaftsgebiet errichten. Fürs Erste können diese Sorgen warten. Der Hexendoktor bereitet das Ritual vor, um Yenniku zu retten."}},faq={{q="Wer besitzt das Gedankenauge?",a="Mai'Zoth besitzt das Gedankenauge tief im Ogerhügel der Mosh'Ogg, östlich des Basislagers Grom'gol.",al={"wer hat das gedankenauge","wo ist das gedankenauge","wer lässt das gedankenauge fallen"}},{q="Warum braucht Kin'weelay das Gedankenauge?",a="Kin'weelay braucht das Gedankenauge für ein Ritual, das seiner Ansicht nach der einzige Weg ist, Yenniku zu retten, den verschollenen Sohn des Häuptlings der Dunkelspeere.",al={"warum brauchen wir das gedankenauge","zweck des gedankenauges","warum das gedankenauge beschaffen"}},{q="An welcher Stelle steht dies bei der Suche nach Yenniku?",a="Die Suche folgt auf „Die singenden Kristalle“. Die Beschaffung des Gedankenauges ebnet den Weg zu Saving Yenniku.",al={"welche quest kommt vor dem gedankenauge","vorherige quest gedankenauge","was kommt nach den singenden kristallen"}},{q="Wer ist Mai'Zoth?",a="Mai'Zoth ist ein Ogermagier, den Kin'weelay aus der Zeit kannte, als die Dunkelspeertrolle im Dschungel lebten. Seine gewaltige Magie wurde durch das Gedankenauge noch stärker.",al={"wer ist maizoth","über maizoth","maizoths geschichte"}}},fp="14,127,14.266.0,22.253.0,15.306.1,29.94.0,40.126.0,48.97.0,16.152.0"}
P.entries["quest:592"] = {n="Yennikus Rettung",s="Kin'weelay hat einen Weg gefunden, Yenniku von Zanzil the Outcast nach Hause zu bringen. Er formt das wiederbeschaffte Gedankenauge zu einem Seelenedelstein um, der Yenniku betäuben und seinen Geist festhalten kann, bis Ihr ihn zu Nimboya bringt.",h="Kin'weelay hat einen Weg gefunden, Yenniku von Zanzil the Outcast nach Hause zu bringen.",kw={"aboraz","kin'weelay","nimboya","yennikus rettung","seelenedelstein","schlingendorntal","yenniku","zanzil"},ang={["faction:Horde"]="Als Abenteurer der Horde aus dem Basislager Grom'gol führt Ihr Nimboyas Suche nach Yenniku bis zu Zanzil in den Ruinen von Aboraz fort.",["race:Troll"]="Als Troll helft Ihr, den jungen Dunkelspeer Yenniku zu seinem Volk zurückzubringen und ihn von der ruchlosen Magie von Zanzil the Outcast zu befreien."},sec={{t="Ein Gefäß für den Geist",b="Kin'weelay verwandelt das wiederbeschaffte Gedankenauge in einen magischen Seelenedelstein. Seine Verzauberung erlaubt es Euch, Yenniku zu betäuben und den Stein auf seinen Kopf zu legen, um seinen Geist einzufangen. Mit Yennikus Geist darin könnt Ihr den Edelstein sicher zu seinen Angehörigen im Basislager Grom'gol bringen."},{t="Der Unterschlupf des Ausgestoßenen",b="Zanzil the Outcast hält Yenniku in den Ruinen von Aboraz gefangen, am Kristallufer im Süden des Kaps des Schlingendorntals. Ihr betretet Zanzils Gebiet und nutzt den Edelstein, um den jungen Troll vom Einfluss des Hexendoktors zu befreien. Dann bringt Ihr den gefüllten Edelstein zu Nimboya zurück."}},faq={{q="Wer stellt den Seelenedelstein für diese Aufgabe bereit?",a="Kin'weelay fertigt den Seelenedelstein aus dem wiederbeschafften Gedankenauge und gibt ihn Euch, damit Ihr Yennikus Geist einfangen könnt.",al={"wer gibt den seelenedelstein","wo gibt es den seelenedelstein","wer startet yennikus rettung"}},{q="Wo befindet sich Yenniku?",a="Yenniku ist bei Zanzil the Outcast in den Ruinen von Aboraz, am Kristallufer am Kap des Schlingendorntals.",al={"wo ist yenniku","yenniku aufenthaltsort","ruinen von aboraz standort"}},{q="Wie funktioniert der Seelenedelstein?",a="Der Seelenedelstein betäubt Yenniku zunächst. Dann legt Ihr ihn auf seinen Kopf, um seinen Geist hineinzuziehen.",al={"wie seelenedelstein benutzen","was bewirkt der seelenedelstein","seelenedelstein schlingendorntal"}},{q="Wer erhält den Gefüllten Seelenedelstein, sobald Yenniku in Sicherheit ist?",a="Ihr überbringt den Gefüllten Seelenedelstein Nimboya im Basislager Grom'gol.",al={"wo gefüllten seelenedelstein abgeben","wer bekommt den edelstein","wo yenniku abliefern"}}},fp="14,198,23.250.0,18.266.0,40.108.0,25.112.0,27.90.0,57.65.0"}
P.entries["quest:5921"] = {n="Mondlichtung",s="In Darnassus lernen junge Nachtelfendruiden einen Zauber, der sie quer durch die Welt zur Mondlichtung trägt. Dort treffen sie Dendrite Sternenschauer in Nachthafen und beginnen ihren Weg zur Beherrschung der Bärengestalt.",h="In Darnassus lernen junge Nachtelfendruiden einen Zauber, der sie quer durch die Welt zur Mondlichtung trägt.",kw={"bär","cenarion","dendrite","mathrengyl","mondlichtung","nachthafen","remulos","sternenschauer","teleport"},ang={["class:Druid"]="Als Druide erschließt Euch diese Reise ein umfassenderes druidisches Erbe und schenkt Euch eine ewige Verbindung zum friedlichen Herzen des Zirkels des Cenarius.",["faction:Alliance"]="Als Mitglied der Allianz erinnert Euch das Betreten der Mondlichtung daran, dass Nachtelfendruiden einem älteren Ruf jenseits weltlicher Fraktionen folgen.",["race:NightElf"]="Als Nachtelf verbindet Euch der Weg von Teldrassils Ästen zur uralten Mondlichtung mit der angestammten Heimat, die aus der Zeit vor der Great Sundering bewahrt wurde."},sec={{t="Eine heilige Zuflucht",b="Die Mondlichtung bietet eine uralte Zuflucht, die den Lehren des Cenarius geweiht ist. Hüter Remulos wacht über ihre Haine, wo Druiden Frieden und Verbundenheit mit der Natur finden. Junge Druiden lernen einen Zauber, der sie quer durch die Welt zur Mondlichtung trägt. Dort finden sie Weisheit jenseits irdischer Entfernungen."},{t="Politik des Zirkels",b="Die Mondlichtung heißt alle willkommen, die der Wildnis folgen, doch der Zirkel des Cenarius kennt Spannungen. In Darnassus sind Erzdruide Fandral Hirschhaupt und Hüter Remulos uneins über die Bewahrung der Natur und die Erschaffung von Teldrassil. Ihre Meinungsverschiedenheiten verschließen jungen Akolythen nicht die Tore Nachthafens. Sie sind willkommen, ihre Studien fortzusetzen."},{t="Der Pfad des Bären",b="In Nachthafen unterweist Dendrite Sternenschauer junge Druiden in den Wegen der Klaue. Bevor ein Initiand die Bürde des Bären auf sich nimmt, lehren ihn die Prüfungen Ausdauer, Zorn und die Verteidigung der Wildnis. Sternenschauer heißt jeden Schüler in Ehrfurcht vor Vater Cenarius willkommen. Dann beginnen die Prüfungen des Großen Bärengeistes."}},faq={{q="Warum lernen Druiden, sich zur Mondlichtung zu teleportieren?",a="Druiden lernen den Zauber, um zur Mondlichtung zurückzukehren, wo in Nachthafen Ausbildung, Zwiesprache mit Geistern und Beratungen der höchsten Ränge stattfinden. Die augenblickliche Reise lässt jeden Druiden zurückkehren, um zu studieren und seine spirituellen Kräfte zu erneuern.",al={"warum zur mondlichtung teleportieren","teleport zur mondlichtung zweck","warum zur mondlichtung reisen"}},{q="Wer ist Dendrite Sternenschauer?",a="Dendrite Sternenschauer ist ein Druidenältester im Obergeschoss eines großen Versammlungshauses in Nachthafen. Er betreut ankommende Initianden und beginnt ihre Prüfungen in den Sichtweisen der Tiere, angefangen mit dem Bären.",al={"dendrite sternenschauer rolle","wer ist dendrite","dendrite sternenschauer"}},{q="Welche Spannungen bestehen zwischen Fandral Hirschhaupt und Hüter Remulos?",a="Erzdruide Fandral Hirschhaupt leitete die Pflanzung Teldrassils ohne den Segen der Dragon Aspects und verfolgte einen aggressiveren, nationalistischen Kurs für die Nachtelfen. Hüter Remulos und die Traditionalisten der Mondlichtung halten an den uralten, neutralen Wegen des Cenarius fest. Ihre Überzeugungen führen zu Reibungen im Zirkel des Cenarius.",al={"hirschhaupt remulos spannungen","fandral gegen remulos","spaltung des zirkels"}},{q="Können auch Druiden der Horde die Mondlichtung besuchen?",a="Ja. Die Mondlichtung ist eine neutrale Zuflucht unter Hüter Remulos und dem Zirkel des Cenarius. Nachtelfen- und Taurendruiden studieren dort gemeinsam die Wege der Wildnis und lassen im Frieden des Cenarius die Feindschaft ihrer Fraktionen ruhen.",al={"horde mondlichtung","dürfen tauren in die mondlichtung","ist die mondlichtung neutral"}},{q="Was geschieht, nachdem man Dendrite Sternenschauer erreicht hat?",a="Nachdem Ihr Dendrite Sternenschauer erreicht habt, führt er Euch zur rituellen Prüfung des Großen Bärengeistes. Die spirituelle Konfrontation prüft Eure Entschlossenheit und Euer Verständnis, bevor Ihr die Macht des Bären führen könnt.",al={"nach der mondlichtung-quest","nächster schritt bärengestalt","bärenquest danach"}},{q="Wo in Nachthafen befindet sich Dendrite?",a="Dendrite Sternenschauer befindet sich im Hauptversammlungshaus der Nachtelfen nahe dem Zentrum von Nachthafen. Er steht auf dessen Balkon im ersten Stock mit Blick über das Dorf.",al={"dendrite sternenschauer finden","dendrite sternenschauer standort","wo ist dendrite"}}},fx={["127ac65b"]={q="Warum schickt Mathrengyl Bärenfährte Euch zur Mondlichtung?",a="Mathrengyl Bärenfährte führt Eure Einweihung in die Wege der Klaue. Während die grundlegende Unterweisung unter den Ästen von Teldrassil beginnt, erfordert die wahre Meisterschaft über den Bärenaspekt die Gemeinschaft mit dem uralten Heiligtum des Zirkels des Cenarius. Mathrengyl schickt Euch nach Nachthafen, damit Ihr direkt von erfahrenen Druiden wie Dendrite Sternenschauer lernen könnt, wobei Ihr die politischen Spaltungen von Darnassus beiseitelasst, um Euren Geist im heiligen Kernland aller druidischen Tradition zu verwurzeln.",al={"warum zur mondlichtung schicken","mathrengyl bärenfährtes motiv","warum will mathrengyl das erledigt haben"}}},fp="9,196,15.292.0,22.310.0,20.299.0,45.237.0,26.190.0,64.314.0,41.204.0,47.203.0,40.143.0"}
P.entries["quest:5922"] = {n="Mondlichtung",s="Ein junger Taurendruide lernt, die uralten Bewahrer der Natur in der Mondlichtung zu erreichen. Unter Turak Runentotems Anleitung in Donnerfels lernt Ihr, die wache Welt zu durchqueren und direkt mit ihnen Zwiesprache zu halten.",h="Ein junger Taurendruide lernt, die uralten Bewahrer der Natur in der Mondlichtung zu erreichen.",kw={"bärengestalt","cenarius","dendrite sternenschauer","mondlichtung","nachthafen","remulos","teleport mondlichtung","turak runentotem"},ang={["class:Druid"]="Für Euch als Druide verbindet dieser Übergangsritus traditionelle Stammesvorstellungen mit den umfassenderen Lehren des Zirkels des Cenarius. Er öffnet den Weg zu uralten Gestaltwandlungsformen.",["faction:Horde"]="Als Druide der Horde könnt Ihr in der Mondlichtung Nachtelfendruiden friedlich begegnen, an einem der wenigen Orte Kalimdors, an denen dies möglich ist.",["race:Tauren"]="Als Taure erlebt Ihr Eure Ankunft in der Mondlichtung als tiefgreifendes Erwachen. Eure uralte Verbindung zur Earth Mother findet Einklang mit den Lehren des Cenarius."},sec={{t="Ein Heiligtum jenseits der Fraktionen",b="Abseits der Fraktionskämpfe Kalimdors bietet die Mondlichtung allen Zuflucht, die der Natur folgen. Keeper Remulos, Sohn des Cenarius, wacht über das uralte Tal. Nachtelfen- und Taurendruiden betreten Nachthafen als Gleichgestellte unter dem zeitlosen Schutz des Zirkels des Cenarius."},{t="Der Sprung über Kalimdor",b="Turak Runentotem lehrt Euch einen Transportzauber, der an die Mondlichtung gebunden ist. Er fördert Euer geistiges und kämpferisches Wachstum und trägt Euch durch Eure Verbindung zur Natur in einem Herzschlag Hunderte von Wegstunden weit. Das Tal bietet Euch einen Ort zum Lernen und während Eurer gesamten Reise eine beständige Zuflucht."},{t="Das Erwachen des Bären",b="In Nachthafen begegnet Ihr Dendrite Sternenschauer, einem älteren Nachtelfendruiden, der neue Schüler erwartet. Unter seiner Anleitung beginnt die erste wahre Prüfung Eurer Berufung: die Sichtweise des Bären zu verstehen. Um die Pfade der Klaue zu beschreiten, beweist Eure Stärke, Euren Mut und Euer Gleichgewicht vor dem Geist des Großen Bären."}},faq={{q="Warum dürfen Tauren ein Nachtelfenheiligtum wie die Mondlichtung besuchen?",a="Die Mondlichtung ist heiliger Boden unter der Obhut des Zirkels des Cenarius. Dort steht die Hingabe an die Natur und Cenarius über dem Konflikt zwischen Horde und Allianz, sodass Tauren- und Nachtelfendruiden friedlich zusammen lernen und leben können.",al={"warum tauren in der mondlichtung","horde in der mondlichtung erlaubt","ist die mondlichtung neutral"}},{q="Wer ist Dendrite Sternenschauer?",a="Dendrite Sternenschauer ist ein älterer Nachtelfendruide in Nachthafen. Er unterweist neu eingetroffene Initianden beider Völker und begleitet ihre ersten Prüfungen, während sie sich auf die uralten Tieraspekte einstimmen.",al={"dendrite sternenschauer","wer ist dendrite","nachtelfenquestgeber"}},{q="Wer ist Keeper Remulos?",a="Keeper Remulos ist ein mächtiger Keeper of the Grove und Sohn des Cenarius. Er ist der oberste Wächter der Mondlichtung, wacht über die heiligen Grabhügel, in denen schlafende Druiden ruhen, und schützt die Heiligkeit des Tals.",al={"keeper remulos","remulos mondlichtung","wer schützt die mondlichtung"}},{q="Was geschieht nach der Ankunft in der Mondlichtung?",a="Ein Gespräch mit Dendrite Sternenschauer eröffnet Eure Prüfung beim Geist des Großen Bären. Er schickt Euch zur Heimstatt des Geistes im Nordwesten der Mondlichtung, um Stärke in Körper und Herz zu erlernen, den ersten Schritt zur Bärengestalt.",al={"was als nächstes tun","bärenquestreihe","nach der mondlichtungsquest"}},{q="Wie funktioniert Teleport: Mondlichtung in der Hintergrundgeschichte?",a="Druiden verweben natürliche Leyenergien mit ihrer geistigen Verbindung zum Zirkel des Cenarius, um von jedem Standort augenblicklich ins Herz der Mondlichtung zu gelangen. Teleport: Mondlichtung verankert sie dort und lässt sie zur Unterweisung und zum Trost zurückkehren, wann immer sie gerufen werden.",al={"mondlichtung teleport hintergrundgeschichte","teleportzauber druide"}},{q="Wo befindet sich Turak Runentotem?",a="Turak Runentotem lebt oben auf der Anhöhe der Ältesten in Donnerfels. Er unterweist junge Tauren, die dem Ruf der Wildnis folgen, bevor er sie in die Mondlichtung weiterschickt.",al={"turak runentotem standort","wo ist turak"}}},fx={cadcf30c={q="Warum schickt Turak Runentotem Euch zur Mondlichtung?",a="Ihr beginnt Eure Unterweisung in den Wegen der Klaue, insbesondere lernt Ihr, mit dem Aspekt des Bären zu kommunizieren und ihn anzunehmen. Turak Runentotem kann Euch nicht allein von Donnerfels aus durch diese heilige Einweihung führen; Ihr müsst die heiligen Gründe der Mondlichtung beschreiten und unter Dendrite Sternenschauer studieren, um eine echte Bindung zu den wilden Geistern der Natur zu schmieden.",al={"warum schickt mich turak zur mondlichtung","turak runetotems motiv","warum zur mondlichtung gehen"}},["979ecc1c"]={q="Warum müsst Ihr die Pilgerreise zur Mondlichtung selbst antreten?",a="Der druidische Pfad erfordert individuelle spirituelle Gemeinschaft. Die Mondlichtung ist das Heiligtum, in dem Druiden des Zirkels des Cenarius direkt mit uralten Waldgeistern und den Lehren von Cenarius kommunizieren. Die Annahme des Bärengeistes ist eine intime, persönliche Prüfung von Charakter und Naturmagie, die kein Ältester oder Mentor in Eurem Namen durchlaufen kann.",al={"warum muss ich zur mondlichtung","warum kann turak mich hier nicht ausbilden","warum ich auf der mondlichtung"}}},fp="9,189,29.260.0,24.289.0,18.299.1,54.238.0,26.186.0,22.210.0,38.220.0,44.257.0,33.156.0"}
P.entries["quest:5923"] = {n="Dem Ruf folgen",s="In Darnassus ruft Mathrengyl Bärenfährte Druiden aus Teldrassil und darüber hinaus zum Beginn ihrer Ausbildung. Ein Lehrling steht nun vor dem Weg zur Meisterschaft über den Bärenaspekt.",h="In Darnassus ruft Mathrengyl Bärenfährte Druiden aus Teldrassil und darüber hinaus zum Beginn ihrer...",kw={"bärenform","die enklave des cenarius","darnassus","denatharion","druidenquest","fandral hirschhaupt","dem ruf folgen","kal","mathrengyl bärenfährte","theridran"},ang={["class:Druid"]="Als Druide schreitet Ihr von ersten Wurzel- und Zornzaubern zur Gestaltwandlung voran und lernt die Geister Kalimdors kennen.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr den Ruf von Theridran in Sturmwind erhalten. Er zeugt von der wachsenden Zusammenarbeit zwischen den Kaldorei von Teldrassil und ihren menschlichen Verbündeten.",["race:NightElf"]="Als Nachtelf betretet Ihr die Enklave des Cenarius in Darnassus, wo Fandral Hirschhaupts Kreis die Tradition der Kaldorei fortführt."},sec={{t="Ein Ruf aus der Enklave",b="Druidennovizen erhalten einen persönlichen Ruf, wenn ihre Ausbilder sie für bereit halten, sich Prüfungen zu stellen. Kal in Dolanaar, Denatharion in Darnassus und Theridran in Sturmwind überbringen Mathrengyl Bärenfährtes Einladung zur Ausbildung. Als direkter Assistent von Erzdruide Fandral Hirschhaupt ist Mathrengyl einer der angesehensten und sachkundigsten Mentoren der Nachtelfen. Seine Anleitung zeichnet einen Lehrling als bereit für echte Prüfungen aus."},{t="Der Pfad des Bären",b="Mathrengyl Bärenfährte empfängt Anwärter auf der oberen Ebene von Fandral Hirschhaupts Wohnsitz in der Enklave des Cenarius. Druiden müssen lernen, die lebenden Geschöpfe der Natur zu verkörpern, statt sie nur zu beobachten. Er erklärt jedem Anwärter, dass die erste große Aufgabe darin besteht, die Stärke, Ausdauer und den Geist des Bären anzunehmen. Der Pfad führt weit über Teldrassil hinaus zu heiligen Ahnenstätten."}},faq={{q="Wer schickt mich auf diese Quest?",a="Kal in Dolanaar, Denatharion in Darnassus und Theridran in Sturmwind können Euch den Ruf überbringen, wenn Ihr bereit seid.",al={"questgeber","wer startet die quest","wo gibt es diese quest"}},{q="Wer ist Mathrengyl Bärenfährte?",a="Mathrengyl Bärenfährte ist ein hochrangiger Nachtelfendruide und der direkte Assistent von Erzdruide Fandral Hirschhaupt. Er lebt in der Enklave des Cenarius in Darnassus und unterweist Initiaten, die Tiergestalten meistern wollen.",al={"mathrengyl","wer ist mathrengyl","bärenfährte"}},{q="Wo finde ich Mathrengyl Bärenfährte in Darnassus?",a="Mathrengyl Bärenfährte befindet sich in der Enklave des Cenarius im nordwestlichen Viertel von Darnassus. Sucht ihn im ersten Obergeschoss des großen lebenden Baumes, der Erzdruide Fandral Hirschhaupt als Heiligtum dient.",al={"mathrengyl standort","wo ist mathrengyl","enklave des cenarius standort"}},{q="Zu welcher Ausbildung führt diese Quest?",a="Wenn Ihr Euch bei Mathrengyl meldet, beginnt die Prüfung für Bear Form. Er schickt Euch quer durch Kalimdor zur Mondlichtung, wo Ihr die körperliche und seelische Stärke erlernt, um mit dem Great Bear Spirit Zwiesprache zu halten.",al={"what comes next","was gibt es als belohnung","nächste quest"}},{q="Warum kann ich diese Quest in Sturmwind erhalten?",a="Theridran unterhält im Park von Sturmwind ein Heiligtum der Nachtelfen, um Verbündeten der Allianz beizustehen. Während Ihr jenseits des Meeres im Wald von Elwynn Abenteuer erlebt, könnt Ihr von ihm den Ruf aus Teldrassil erhalten.",al={"sturmwind quest","theridran","quest in sturmwind erhältlich"}},{q="Warum wird die Bärenform als erster Tieraspekt gelehrt?",a="Druiden lehren den Bärenaspekt zuerst, weil er Widerstandskraft, körperliche Stärke und den Mut verkörpert, das Gleichgewicht der Natur vor Schaden zu bewahren. Diese Eigenschaften helfen Euch, gefährliche Prüfungen in der Wildnis zu bestehen.",al={"warum bärenform","druide bär hintergrundgeschichte"}}},fx={["7976a971"]={q="Warum werde ich zu Mathrengyl Bärenfährte geschickt?",a="Eure druidischen Ausbilder erkennen, dass Eure grundlegende Lehre abgeschlossen ist und Ihr bereit für fortgeschrittene Unterweisung seid. Mathrengyl Bärenfährte dient direkt unter Erzdruide Fandral Hirschhaupt und beaufsichtigt den kritischen Ritus der Gemeinschaft mit dem großen Bärengeist. Die Ausbilder schicken Euch zu ihm, damit Ihr mit dem Erlernen der Gestaltwandlung beginnen könnt, wodurch Ihr die Stärke von Körper und Geist freischaltet, die erforderlich ist, um das Gleichgewicht der Natur zu schützen.",al={"warum mathrengyl","warum dem ruf folgen","grund für das folgen des rufs","warum schickt mich denatharion"}},fad6f2dc={q="Warum will Mathrengyl Bärenfährte mich anstelle von jemand anderem?",a="Dies ist keine staatliche oder militärische Aufgabe, sondern ein persönlicher Initiationsritus, der einzigartig für Euren Pfad als aufstrebender Druide ist. Mathrengyl Bärenfährte sucht nach jungen Druiden, die das Potenzial besitzen, den Geist der Wildnis zu kanalisieren. Nur Ihr könnt mit den Schutzgeistern kommunizieren und die spirituellen Tests durchlaufen, die erforderlich sind, um Euren ersten Tieraspekt zu meistern.",al={"warum ich beim folgen des rufs","warum wählt man mich","warum braucht mich mathrengyl"}}},fp="16,167,26.409.0,20.385.0,27.114.0,29.204.0,52.194.0,38.190.0,38.183.0,52.199.0"}
P.entries["quest:5924"] = {n="Heeding the Call",s="Mathrengyl Bärenfährte erwartet Euch in Darnassus, wo er Euch ruft, die Wege des Bären zu erlernen. Dies ist Euer erster Schritt, um der Natur zu dienen und das Gleichgewicht zu bewahren.",h="Mathrengyl Bärenfährte erwartet Euch in Darnassus, wo er Euch ruft, die Wege des Bären zu erlernen.",kw={"gleichgewicht","die enklave des cenarius","cenarius","darnassus","heeding the call","mathrengyl bärenfährte","natur","wege des bären"},ang={["class:Druid"]="Als Druide ruft Mathrengyl Euch auf, die Wege des Bären zu erlernen und der Natur zu dienen, indem Ihr das Gleichgewicht bewahrt."},sec={{t="Ein Ruf in Darnassus",b="In der Enklave des Cenarius in Darnassus heißt Mathrengyl Bärenfährte Euch willkommen und ruft Euch auf, einen ersten Schritt in eine größere Welt zu wagen. Er lehrt, dass Cenarius' Kinder dazu berufen sind, der Natur zu dienen, wobei Tiere und Pflanzen zugleich Freunde und Schutzbefohlene sind. Ihr beginnt damit, die Wege des Bären und die Stärke von Körper und Herz kennenzulernen."}},faq={{q="Wer bittet mich, hierherzukommen?",a="Mathrengyl Bärenfährte erwartet Euch in der Enklave des Cenarius in Darnassus.",al={"wer sucht mich","wer ist mathrengyl","mathrengyl"}},{q="Wo finde ich Mathrengyl Bärenfährte?",a="Mathrengyl Bärenfährte befindet sich in der Enklave des Cenarius in Darnassus.",al={"wo ist mathrengyl","mathrengyl aufenthaltsort","die enklave des cenarius"}},{q="Was soll ich von Mathrengyl lernen?",a="Er ruft Euch auf, die Wege des Bären und die Stärke von Körper und Herz kennenzulernen.",al={"was lerne ich","wege des bären","dem ruf folgen"}},{q="Was ist die Berufung von Cenarius' Kindern?",a="Cenarius' Kinder sind dazu berufen, der Natur zu dienen und das Gleichgewicht zu bewahren, zum Wohl der Pflanzen und Tiere sowie zu ihrem eigenen.",al={"cenarius' ruf","der natur dienen","warum natur"}}},fp="16,166,19.319.0,30.70.0,38.62.0,38.74.0,39.124.0"}
P.entries["quest:5925"] = {n="Dem Ruf folgen",s="Mathrengyl Bärenfährte ruft einen jungen Nachtelfendruiden nach Darnassus, um dessen Ausbildung fortzusetzen. Als direkter Assistent von Erzdruide Fandral Hirschhaupt bereitet er den Initianden auf die Prüfungen des Bären vor.",h="Mathrengyl Bärenfährte ruft einen jungen Nachtelfendruiden nach Darnassus, um dessen Ausbildung fortzusetzen.",kw={"bärengestalt","die enklave des cenarius","darnassus","druidenausbildung","fandral hirschhaupt","heeding the call","mathrengyl bärenfährte","teldrassil"},ang={["class:Druid"]="Als Druide lasst Ihr die Grundausbildung der Novizen hinter Euch und beginnt, unter dem direkten Assistenten von Erzdruide Hirschhaupt die tieferen Formen der Natur zu erlernen.",["faction:Alliance"]="Als Mitglied der Allianz schließt Ihr Euch den Nachtelfendruiden an, die in Darnassus dem Ruf des Cenarius folgen. Ihre Arbeit stärkt die uralten magischen und natürlichen Grundlagen der Allianz auf Kalimdor.",["race:NightElf"]="Im Herzen von Darnassus zeigt die Enklave des Cenarius, wie tief der cenarische Druidismus mit der Gesellschaft der Kaldorei verwoben ist."},sec={{t="Ein Ruf nach Darnassus",b="Als Eure Grundausbildung in den Ästen Teldrassils zu Ende geht, erreicht Euch die Nachricht, dass Mathrengyl Bärenfährte mit Euch sprechen möchte. Er ist der direkte Assistent von Erzdruide Fandral Hirschhaupt und einer der weisesten Ältesten der Enklave des Cenarius. Sein Ruf führt Euch über die grundlegenden Wächterpflichten hinaus und hin zu den tieferen Künsten der Natur."},{t="Der Pfad des Bären",b="Ihr reist zur Enklave des Cenarius in Darnassus und steigt in den zweiten Stock des großen Baumes von Erzdruide Hirschhaupt hinauf. Bärenfährte heißt Euch willkommen und erinnert Euch daran, dass alle, die Cenarius' Ruf folgen, Pflanzen und Tiere als Gefährten und Schutzbefohlene ehren müssen. Um das Gleichgewicht der Natur zu bewahren, braucht Ihr mehr als stilles Nachdenken. Ihr müsst die Wege des wilden Bären erlernen und die Stärke von Körper und Herz meistern."}},faq={{q="Wer ist Mathrengyl Bärenfährte?",a="Mathrengyl Bärenfährte ist ein weiser Druide und der direkte Assistent von Erzdruide Fandral Hirschhaupt. Er leitet die weiterführende Ausbildung vielversprechender Druiden in Darnassus.",al={"wer möchte mit mir sprechen","wer ist mathrengyl","wer ist mathrengyl bärenfährte"}},{q="Wo befindet sich Mathrengyl Bärenfährte?",a="Mathrengyl Bärenfährte befindet sich im zweiten Stock von Fandral Hirschhaupts Baum in der Enklave des Cenarius in Darnassus. Hochrangige Mitglieder des Zirkels des Cenarius versammeln sich dort auf Teldrassil.",al={"wo finde ich bärenfährte","wo ist mathrengyl","enklave des cenarius standort"}},{q="Warum wurde ich zu Mathrengyl gerufen?",a="Eure Grundausbildung ist abgeschlossen, und Euer Weg als Druide kann sich nun erweitern. Mathrengyl wird Euch in die tieferen Lehren der Natur einführen.",al={"warum werde ich gerufen","wozu dient diese quest","warum dem ruf folgen"}},{q="Was werde ich von Mathrengyl Bärenfährte lernen?",a="Mathrengyl beginnt, Euch die Wege des Bären zu lehren. Ihr erlernt die Stärke von Körper und Herz, um das Gleichgewicht der Natur zu schützen.",al={"was wird mathrengyl mich lehren","was lerne ich als nächstes","welche gestalt erhalte ich"}},{q="Was bedeutet es, zu den „Kindern des Cenarius“ zu gehören?",a="Cenarius ist der schützende Halbgott der Natur und Lehrer der ersten Druiden. Seine Anhänger glauben, dass alle Druiden die Pflicht teilen, Azeroths wilde Pflanzen und Tiere zu schützen.",al={"wer ist cenarius","kinder des cenarius bedeutung"}},{q="Was ist Fandral Hirschhaupts Baum?",a="Fandral Hirschhaupts Baum ist ein prächtiger, hohler, lebender Baum in der Enklave des Cenarius in Darnassus. Erzdruide Fandral Hirschhaupt und sein engster Kreis lenken von dort aus die cenarischen Angelegenheiten in ganz Teldrassil.",al={"in welchem baum ist er","fandrals baum standort"}}},fp="16,195,22.324.0,20.393.0,29.161.0,39.176.0,44.136.0,45.123.0,51.164.0,32.189.0"}
P.entries["quest:5926"] = {n="Dem Ruf folgen",s="In den Siedlungen der Horde erfahren junge Druiden, dass Turak Runentotem sie persönlich unterweisen möchte. Dem Ruf folgen führt sie auf die Anhöhe der Ältesten in Donnerfels, wo die heiligen Prüfungen zur Bärengestalt beginnen.",h="In den Siedlungen der Horde erfahren junge Druiden, dass Turak Runentotem sie persönlich unterweisen möchte.",kw={"bärengestalt","dorf der bluthufe","zirkel des cenarius","druide","die anhöhe der ältesten","gennia runetotem","dem ruf folgen","donnerfels","turak runentotem"},ang={["class:Druid"]="Als Druide beginnt Ihr den Weg zur Beherrschung der Tiergestalten und die heilige Reise zum Geist und zur Standhaftigkeit des Bären.",["faction:Horde"]="Als Mitglied der Horde hört Ihr den Ruf durch Gastwirte in den Ländern der Orcs und Tauren und wahrt die Bindung Eures Volkes zur wilden Erde.",["race:Tauren"]="Als Tauren erneuert Ihr Eure angestammte Bindung zum Zirkel des Cenarius und den wilden Geistern Kalimdors durch Turaks Unterweisung auf der Anhöhe der Ältesten."},sec={{t="Eine Nachricht im Gasthaus",b="In Mulgore und Orgrimmar hört Ihr, dass Turak Runentotem auf Eure ersten Fortschritte aufmerksam geworden ist. Die Nachricht kann von Gastwirtin Gryshka in Orgrimmar, Gastwirtin Pala in Donnerfels oder Gennia Runetotem im Dorf der Bluthufe kommen. Der Zirkel des Cenarius ruft Praktizierende nicht leichtfertig zu sich. Eure Arbeit mit Kräutern und einfachen Zaubern hat Euch die Gelegenheit verschafft, Eure Bindung zu den wilden Geistern der Natur zu vertiefen."},{t="Der Zirkel auf der Anhöhe der Ältesten",b="Auf der Anhöhe der Ältesten führt Turak Runentotem junge Tauren an ihre angestammte Pflicht heran. Er unterstützt Erzdruide Hamuul Runetotem und heißt Euch im großen Zelt des Cenarius willkommen. Turak lehrt, dass Tiere und Pflanzen Verbündete sind und dass diese Bindungen ernste Pflichten mit sich bringen. Seine Unterweisung eröffnet einen Weg über die Grundlagen hinaus, hin zu Prüfungen von Körper und Herz und zur Zwiesprache mit dem Großen Bärengeist."}},faq={{q="Wer schickt mich zu Turak Runentotem?",a="Gennia Runetotem im Dorf der Bluthufe, Gastwirtin Pala in Donnerfels oder Gastwirtin Gryshka in Orgrimmar können den Ruf überbringen. Sie alle haben gehört, dass Turak Eure Ausbildung persönlich leiten möchte.",al={"wer vergibt dem ruf folgen","questgeber dem ruf folgen","wo beginnt dem ruf folgen"}},{q="Wo finde ich Turak Runentotem?",a="Turak Runentotem befindet sich im Zelt des Zirkels des Cenarius auf der Anhöhe der Ältesten in Donnerfels, nahe den anderen Druidenlehrern der Stadt.",al={"turak runentotem standort","wo ist turak","turak finden"}},{q="Warum ist dieser Ruf für junge Druiden so wichtig?",a="Mit diesem Ruf beginnen Eure förmlichen Prüfungen zur Gestaltwandlung. Turak schickt Euch auf heiligen Boden in der Mondlichtung, um den Weg des Bären zu erlernen und Eure erste Tiergestalt zu erlangen.",al={"warum wird turak gebraucht","wozu dient diese quest","druidenquest stufe zehn horde"}},{q="Welchen Rang hat Turak Runentotem im Zirkel des Cenarius?",a="Turak Runentotem ist ein angesehener Taurendruide und ein vertrauter Gehilfe von Erzdruide Hamuul Runetotem. Mit Geduld und Weisheit lehrt er junge Initianden das Gleichgewicht der Natur.",al={"wer ist turak runentotem","turaks geschichte"}},{q="Können andere Klassen diese Quest annehmen?",a="Nein. Nur Druiden, die ihre zehnte Jahreszeit der Erfahrung erreicht haben, erhalten diesen Ruf, einen Übergangsritus zur Gestaltwandlung.",al={"ist dem ruf folgen nur für druiden","können schamanen diese quest machen"}},{q="Was geschieht, nachdem ich mit Turak gesprochen habe?",a="Turak heißt Euch im Dienste des Cenarius willkommen und schickt Euch in die Mondlichtung. Dort sucht Ihr Dendrite Sternenschauer auf und beginnt die Zwiesprache mit dem Großen Bärengeist.",al={"was folgt auf dem ruf folgen","nächste quest nach turak"}}},fx={["309dc9df"]={q="Warum werde ich zu Turak Runentotem geschickt?",a="Die Nachricht hat die Siedlungen erreicht, dass Turak Runentotem, Assistent des Erzdruiden, vielversprechende junge Druiden sucht, die tieferer Unterweisung bedürfen. Die Questgeber fungieren lediglich als Boten, um sicherzustellen, dass Ihr seine Vorladung nicht verpasst. Turak hat angeboten, Euch persönlich zu unterweisen, was den Moment markiert, in dem Eure rudimentäre Ausbildung zu wahrer Gemeinschaft mit der Natur und den Wegen der Wildnis aufblüht.",al={"warum zu turak schicken","warum möchte gennia, dass ich mit turak spreche","warum turak runentotem aufsuchen"}}},fp="16,222,17.393.0,24.373.0,43.197.0,33.121.0,50.160.0,49.174.0,36.125.0,36.153.1"}
P.entries["quest:5928"] = {n="Heeding the Call",s="Turak Runentotem ruft Euch dazu auf, die Wege des Bären zu erlernen. Er lehrt, dass Druiden der Natur dienen und das Gleichgewicht bewahren.",h="Turak Runentotem ruft Euch dazu auf, die Wege des Bären zu erlernen.",kw={"bär","cenarius","druide","die anhöhe der ältesten","heeding the call","natur","donnerfels","turak runentotem"},ang={["class:Druid"]="Turaks Lehre für Euch als Druiden beginnt mit dem Dienst an der Natur und dem Erlernen der Wege des Bären."},sec={{t="Ein Ruf zum Lernen",b="Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels bittet Euch, mit ihm zu sprechen. Er sagt, die Zeit sei gekommen, Euren ersten Schritt in eine größere Welt zu wagen.\n\nEr lehrt, dass Cenarius' Kinder der Natur dienen und Tiere und Pflanzen als Freunde und Schutzbefohlene umsorgen. Eure erste Lektion gilt den Wegen des Bären und der Stärke von Körper und Herz."}},faq={{q="Wer bittet mich, hierherzukommen?",a="Turak Runentotem bittet Euch, auf der Anhöhe der Ältesten in Donnerfels mit ihm zu sprechen.",al={"wer hat mich geschickt","turak wer","wer ist turak"}},{q="Was soll ich von Turak lernen?",a="Turak sagt, Euer erster Schritt sei, die Wege des Bären und die Stärke von Körper und Herz kennenzulernen.",al={"was lerne ich","bärenlektion","bär lernen"}},{q="Was tun Druiden laut Turak?",a="Turak sagt, Cenarius' Kinder dienen der Natur und bewahren das Gleichgewicht zum Wohle der Tiere, der Pflanzen und ihrer selbst.",al={"druidenberufung","der natur dienen","warum natur"}},{q="Wo spreche ich mit Turak?",a="Turak Runentotem ist auf der Anhöhe der Ältesten in Donnerfels.",al={"wo ist turak","die anhöhe der ältesten","turaks standort"}}},fp="16,123,15.329.0,30.74.0,33.91.0,30.112.0,28.50.0"}
P.entries["quest:5929"] = {n="Großer Bärengeist",s="In der Mondlichtung werden Druiden nach Norden geschickt, um den Großen Bärengeist aufzusuchen. Die Zwiesprache mit diesem uralten Führer lehrt das Wesen und die Stärke des Bären, einen wesentlichen Teil der spirituellen und kämpferischen Ausbildung eines Druiden.",h="In der Mondlichtung werden Druiden nach Norden geschickt, um den Großen Bärengeist aufzusuchen.",kw={"bärengestalt","dendrite sternenschauer","druidenquest","großer bärengeist","mondlichtung","nachthafen"},ang={["class:Druid"]="Als Druide haltet Ihr Zwiesprache mit dem Großen Bärengeist, um natürliche Weisheit und die spirituelle Grundlage zu erlangen, die Ihr braucht, um die Widerstandskraft des Bären anzunehmen."},sec={{t="Der edle Mentor der Mondlichtung",b="Im Nordwesten der Mondlichtung wohnt der Große Bärengeist abseits der ruhigen Pfade von Nachthafen. Dieser uralte und edle Mentor lehrt jeden Initianden, der das Wesen des Bären verstehen will. Druiden suchen seit Langem seinen Segen und seine Weisheit als Teil ihres Weges auf dem Pfad der Wildnis."},{t="Ein Ritus ursprünglicher Konzentration",b="Dendrite Sternenschauer führt junge Druiden von Nachthafen in die Hügel, um dem Geist zu begegnen. Die Zwiesprache vermittelt ursprüngliche Weisheit und ein Bewusstsein für natürliche Stärke. Wenn die Druiden zurückkehren, prüft Dendrite ihre Konzentration. Die Begegnung verleiht ihnen rohe Stärke und bewusste Entschlossenheit, doch sie müssen lernen, diese Kraft in ihrem täglichen Wirken zu lenken."}},faq={{q="Wo ist der Große Bärengeist zu finden?",a="Der Große Bärengeist wohnt in der nordwestlichen Wildnis der Mondlichtung, fern von Nachthafen und seinen erschlossenen Pfaden.",al={"wo ist der bärengeist","bärengeist mondlichtung finden","standort des bärengeistes"}},{q="Wer schickt Druiden aus, um den Großen Bärengeist aufzusuchen?",a="Dendrite Sternenschauer, ein Druidenältester in Nachthafen, weist Initianden an, als Teil ihrer Ausbildung in den Kräften der Natur Zwiesprache mit dem Geist zu halten.",al={"wer schickt zum bärengeist","dendrite sternenschauers rolle","questgeber bärengeist"}},{q="Was ist der Große Bärengeist?",a="Der Große Bärengeist ist ein weiser und edler Führer, Lehrer und Mentor, der praktizierende Druiden das ursprüngliche Wesen des Bären lehrt.",al={"was ist der bärengeist","geschichte des bärengeistes","wer ist der große bärengeist"}},{q="Warum müssen Druiden Zwiesprache mit dem Großen Bärengeist halten?",a="Initianden halten Zwiesprache mit dem Geist, um das Wesen des Bären zu erlernen und seine rohe Stärke, Widerstandskraft und Weisheit aufzunehmen, bevor sie zurückkehren und diese Eigenschaften einsetzen.",al={"warum mit dem bärengeist sprechen","zweck der bärengeistquest","was lehrt der bärengeist"}},{q="Was geschieht, nachdem der Große Bärengeist zufriedengestellt wurde?",a="Nach der Zwiesprache mit dem Geist kehren Initianden zu Dendrite Sternenschauer in Nachthafen zurück. Dendrite erkennt ihr neues Verständnis und bereitet sie darauf vor, diese Kraft zu bündeln.",al={"was geschieht nach dem bärengeist","dendrite nach dem geist","nach dem besuch beim bärengeist"}},{q="Müssen alle Druiden die Weisheit des Geistes suchen?",a="Jeder Druide muss den Rat des Großen Bärengeistes suchen. Die Zwiesprache ist ein grundlegender Schritt, um sich auf Tiergestalten und die Kraft der Natur einzustimmen.",al={"besuchen alle druiden den bärengeist","ist der bärengeist pflicht","wer besucht den bärengeist"}}},fp="17,202,29.273.0,22.330.0,41.113.0,51.129.0,30.127.0,51.164.0,54.169.0,47.139.0"}
P.entries["quest:593"] = {n="Den Seelenedelstein füllen",s="Im Schlingendorntal erreicht Ihr Yenniku, während er noch in einer Trance gefangen ist. Ein vorbereiteter Seelenedelstein könnte ihn bewahren, indem er seinen Geist aufnimmt.",h="Im Schlingendorntal erreicht Ihr Yenniku, während er noch in einer Trance gefangen ist.",kw={"saving yenniku","seelenedelstein","schlingendorntal","troll","yenniku"},sec={{t="Trance im Dschungel",b="Yenniku, der junge Troll, den Ihr zu retten versucht habt, steht im Schlingendorntal regungslos vor Euch. Sein Geist ist weit fort. Der verzauberte Edelstein, der seine Essenz aufnehmen soll, ist der einzige Weg voran."},{t="Das Gefäß",b="Der Seelenedelstein wird an Yennikus Stirn gedrückt und zieht seinen Geist in den Stein. Sein Körper erbebt und bricht dann als leere, geistlose Hülle zusammen."}},faq={{q="In welchem Zustand ist Yenniku, als Ihr ihn erreicht?",a="Als Ihr Yenniku erreicht, ist er benommen und reagiert nicht, seine Gedanken sind fern der Welt um ihn gefangen.",al={"yennikus zustand","was fehlt yenniku","yenniku benommen"}},{q="Welcher Gegenstand wird bei Yenniku eingesetzt?",a="Ihr benutzt einen aus dem Schlingendorntal mitgebrachten Seelenedelstein bei Yenniku.",al={"welcher gegenstand wird benötigt","edelstein bei yenniku eingesetzt","yenniku gegenstand"}},{q="Was geschah vor diesem Augenblick?",a="Dieser Augenblick folgt auf die Ereignisse von Saving Yenniku im Dschungel des Schlingendorntals.",al={"vorherige quest","voraussetzung für „den seelenedelstein füllen“","was führt hierzu"}}},fp="20,136,22.195.0,10.138.1,48.104.0,29.62.0,29.86.0"}
P.entries["quest:5930"] = {n="Great Bear Spirit",s="In der Mondlichtung schickt Euch Dendrite Sternenschauer zum Great Bear Spirit, um das Wesen des Bären kennenzulernen. Er glaubt, dass Eure Kraft und Eure Entschlossenheit bereit sind, gebündelt zu werden.",h="In der Mondlichtung schickt Euch Dendrite Sternenschauer zum Great Bear Spirit, um das Wesen des Bären...",kw={"bär","dendrite sternenschauer","great bear spirit","mondlichtung","wesen des bären","nachthafen"},sec={{t="Eine Lehre vom Wesen des Bären",b="Dendrite Sternenschauer wartet in Nachthafen in der Mondlichtung und hat eine Lektion im Sinn. Er bittet Euch, den Great Bear Spirit im Nordwesten aufzusuchen und zu erfahren, was er über das Wesen des Bären vermitteln kann. Kehrt anschließend zu Dendrite zurück; er erkennt Kraft und Entschlossenheit in Euch und sagt, Ihr könnt durch das Wesen des Bären lernen, beides zu bündeln."}},faq={{q="Wer schickt mich zum Great Bear Spirit?",a="Dendrite Sternenschauer in Nachthafen bittet Euch, den Great Bear Spirit aufzusuchen.",al={"wer bittet mich","dendrites bitte"}},{q="Wo ist der Great Bear Spirit?",a="Der Great Bear Spirit befindet sich im Nordwesten der Mondlichtung.",al={"standort des bärengeistes","wo ist der geist"}},{q="Was soll ich lernen?",a="Dendrite bittet Euch, zu erfahren, was der Great Bear Spirit über das Wesen des Bären zu vermitteln hat.",al={"lehre vom wesen des bären","was lehrt der geist"}},{q="Wohin kehre ich anschließend zurück?",a="Kehrt nach dem Gespräch mit dem Great Bear Spirit zu Dendrite Sternenschauer in Nachthafen in der Mondlichtung zurück.",al={"wohin zurückkehren","zurück zu dendrite"}}},fp="17,165,23.333.0,38.72.0,31.51.0,25.96.0,28.97.0"}
P.entries["quest:5931"] = {n="Zurück nach Darnassus",s="Nach Eurer Begegnung mit dem Großen Bärengeist verlasst Ihr die Mondlichtung und kehrt nach Darnassus zurück. In der Enklave des Cenarius erwartet Euch Mathrengyl Bärenfährte, um Euch durch die praktischen Prüfungen des Gestaltwandels zu führen.",h="Nach Eurer Begegnung mit dem Großen Bärengeist verlasst Ihr die Mondlichtung und kehrt nach Darnassus zurück.",kw={"bärengeist","bärenfährte","die enklave des cenarius","darnassus","dendrite","mathrengyl","mondlichtung","gestaltwandel","sternenschauer"},ang={["class:Druid"]="Als jungen Druiden führt Euch diese Reise von der geistigen Zwiesprache zur körperlichen Ausübung des Gestaltwandels.",["race:NightElf"]="Als Nachtelf reist Ihr zwischen der Mondlichtung, einem uralten Heiligtum, und Teldrassil, dem neu gepflanzten World Tree. Eure Reise verbindet Jahrtausende des Erbes der Kaldorei mit Euren heutigen Pflichten."},sec={{t="Eine Reise zwischen Heiligtümern",b="Dendrite Sternenschauer schickt Euch nach Eurer Begegnung mit dem Großen Bärengeist in der Mondlichtung von Nachthafen zurück nach Darnassus. Dort verlasst Ihr das Heiligtum, in dem Ihr Zwiesprache mit dem Geist gehalten habt, und kehrt in die unruhige Welt jenseits seiner Grenzen zurück. In Darnassus wachen die örtlichen Mentoren über Teldrassil und begleiten den nächsten Abschnitt Eurer Ausbildung."},{t="Der Pfad der Klaue",b="Mathrengyl Bärenfährte erwartet Euch in der Enklave des Cenarius und beschützt die Natur, während ihr Gleichgewicht ins Wanken gerät. Der Segen des Großen Bärengeistes ist nur der erste Schritt. Mathrengyl bereitet Euch auf Prüfungen von Körper und Herz vor, damit Ihr der wilden Weisheit der Ahnen dieses Geistes körperliche Gestalt verleihen könnt."}},faq={{q="Warum muss ich nach Darnassus zurückkehren?",a="In der Mondlichtung haltet Ihr Zwiesprache mit dem Großen Bärengeist, während Euer Mentor Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus wartet. Er führt Euch durch praktische Prüfungen, die Euch helfen, Eure neue Macht zu meistern.",al={"warum nach darnassus zurückkehren","warum die mondlichtung verlassen","wohin schickt dendrite"}},{q="Wer ist Mathrengyl Bärenfährte?",a="Mathrengyl Bärenfährte ist ein erfahrener nachtelfischer Druidenlehrer in der Enklave des Cenarius in Darnassus. Er führt junge Initianden auf dem Way of the Claw und lehrt sie, die Bärengestalt zu meistern.",al={"wer ist mathrengyl","mathrengyl bärenfährte hintergrundgeschichte","bärenfährte"}},{q="Wie komme ich von der Mondlichtung zurück nach Darnassus?",a="Silva Fil'naveth, die Hippogryphenmeisterin im Südwesten von Nachthafen, kann Euch über das Meer nach Rut'theran fliegen. Von dort führt ein Portal hinauf nach Darnassus.",al={"wie nachthafen verlassen","rückflug von der mondlichtung","silva fil'naveth"}},{q="Was geschieht, nachdem ich mit Mathrengyl gesprochen habe?",a="Mathrengyl stellt Eure Entschlossenheit erstmals auf eine echte Probe: Stellt Euch Lunaclaw am Moonkin Stone östlich von Auberdine in der Dunkelküste. Die Prüfung zeigt, ob Euer Körper und Euer Herz bereit sind, die Bärengestalt anzunehmen.",al={"nächste quest nach zurück nach darnassus","what comes next"}},{q="Was ist der Path of the Claw?",a="Der Path of the Claw ist eine druidische Tradition, die durch Zwiesprache mit uralten ursprünglichen Geistern die Wildheit, Widerstandskraft und Stärke des Bären kanalisiert.",al={"path of the claw","druiden klaue hintergrundgeschichte"}},{q="Warum erwähnt Dendrite, dass das Gleichgewicht nahe Darnassus ins Wanken gerät?",a="Teldrassil ist jung und trägt den Segen der Dragon Aspects nicht, weshalb seine Äste für seltsame Verderbnis, den Wahnsinn der Furbolgs und vordringende Dunkelheit anfällig sind. Druiden in der Enklave des Cenarius bekämpfen diese Bedrohungen.",al={"gleichgewicht bei darnassus ins wanken geraten","teldrassil verderbt"}}},fx={["8983e9c4"]={q="Warum will Dendrite Sternenschauer, dass ich zu Mathrengyl zurückkehre?",a="Dendrite Sternenschauer hat Euch durch Eure anfängliche Gemeinschaft mit dem Großen Bärengeist auf der Mondlichtung geführt, aber die Mondlichtung ist ein Ort der Zuflucht und des Studiums, keine praktische Prüfung. Mathrengyl Bärenfährte hat Euch ursprünglich auf diese spirituelle Reise geschickt und ist damit beauftragt, Eure eigentliche Ausbildung zu beaufsichtigen. Dendrite schickt Euch zurück, damit Mathrengyl Eure neu gefundene Verbindung zum Bärengeist testen und Euch durch die anspruchsvollen Prüfungen führen kann, die erforderlich sind, um den Pfad der Klaue zu beschreiten.",al={"warum schickt mich dendrite zurück","dendrite sternenschauers motiv","warum zurück nach darnassus dendrite"}}},fp="17,180,29.323.0,20.282.0,37.202.0,29.182.0,46.163.0,41.195.0,29.150.0,59.208.0"}
P.entries["quest:5932"] = {n="Zurück nach Donnerfels",s="Auf der Anhöhe der Ältesten erwartet Turak Runentotem Eure Rückkehr aus Mondlichtung. Dendrite Sternenschauer schickt Euch nach Eurer Zwiesprache mit dem Großen Bärengeist nach Hause, damit Eure Ausbildung unter Eurem Volk weitergehen kann.",h="Auf der Anhöhe der Ältesten erwartet Turak Runentotem Eure Rückkehr aus Mondlichtung.",kw={"zurück nach donnerfels","bärengestalt","dendrite sternenschauer","die anhöhe der ältesten","großer bärengeist","mondlichtung","nachthafen","turak runentotem"},ang={["class:Druid"]="Als Druide verbindet Eure Reise Mondlichtung mit den Höhen von Donnerfels und kennzeichnet Euren Fortschritt auf dem Pfad der Klaue.",["faction:Horde"]="Als Mitglied der Horde helft Ihr dabei, ihre Reihen auf den Ebenen Kalimdors um gestaltwandelnde Verteidiger zu verstärken.",["race:Tauren"]="Als Tauren bringt Ihr die Weisheit der uralten Geister nach Hause, um Euren Stämmen in ganz Mulgore zu helfen und sie zu schützen."},sec={{t="Eine Gemeinschaft über Grenzen",b="In Mondlichtung kommen Nachtelfen und Tauren, die Naturmagie wirken, im Zirkel des Cenarius zusammen. Dort lassen sie die Spaltungen zwischen den sterblichen Fraktionen hinter sich. Nach Eurer Zwiesprache mit dem Großen Bärengeist schickt Dendrite Sternenschauer Euch zu Eurem Volk zurück. Nachtelfen betrachten Tauren oft als Neulinge in den formalen Lehren des Cenarius. Doch Starblaze erkennt die Weisheit und Ausgeglichenheit von Turak Runentotem an."},{t="Rückkehr auf die Höhen",b="Ihr steigt zur Anhöhe der Ältesten in Donnerfels hinauf und tretet vor Turak Runentotem, durch Euren Ritus verändert. Die Zwiesprache mit uralten Totemgeistern wie dem Großen Bärengeist ist tief in der Kultur der Tauren verwurzelt. Doch der Pfad der Klaue verlangt ernsthafte Hingabe. Euer geistiges Band ist geschmiedet, und Turak bereitet Euch darauf vor, Eure neue Stärke und Ausdauer in die Tat umzusetzen."}},faq={{q="Warum unterrichtete ein Nachtelf einen Tauren in Mondlichtung?",a="Der Zirkel des Cenarius ist neutral und widmet sich der Bewahrung der Natur. In Mondlichtung lassen nachtelfische und taurische Naturmagier die Spaltung zwischen Horde und Allianz hinter sich, sodass Dendrite Sternenschauer junge Taurendruiden anleiten kann.",al={"dendrite sternenschauer horde","warum nachtelf als mentor","zirkel des cenarius tauren"}},{q="Wer ist Turak Runentotem?",a="Turak Runentotem ist ein angesehener Taurendruide und einer der Gehilfen des Erzdruiden. Er ist auf der Anhöhe der Ältesten in Donnerfels stationiert, wo er junge Tauren im Weg der Natur und der Klaue unterweist und sie mit dem Zirkel des Cenarius verbindet.",al={"turak runentotem rolle","anhöhe der ältesten druidenanführer"}},{q="Was tat der junge Druide unmittelbar vor dieser Quest?",a="Vor Eurer Rückkehr nach Mulgore seid Ihr nach Mondlichtung gereist, um den uralten Großen Bärengeist aufzusuchen und mit ihm Zwiesprache zu halten. Ihr habt seinen Segen erhalten und das geistige Wesen der Bärengestalt kennengelernt.",al={"was kam vor zurück nach donnerfels","großer bärengeist quest"}},{q="Wie reisen junge Druiden von Mondlichtung zurück nach Donnerfels?",a="Bunthen Plainswind bietet im Südwesten von Nachthafen Flugdienste an und bringt Taurendruiden nach ihren Riten sicher zurück nach Donnerfels.",al={"wie aus mondlichtung zurückkehren","mondlichtung rückflug"}},{q="Was folgt als Nächstes in der Ausbildung des Druiden?",a="Nach Eurer Rückkehr schickt Turak Runentotem Euch zu einer körperlichen Prüfung am Moonkin Stone, wo das Brachland an Mulgore grenzt. Dort beweist Ihr, dass Ihr die Stärke des Geistes in Tiergestalt lenken könnt.",al={"nächste druidenquest","nach zurück nach donnerfels"}},{q="Warum nennt Dendrite Sternenschauer Tauren „jung in den Wegen des Cenarius“?",a="Die Legenden der Tauren erzählen von uralter Zwiesprache mit Cenarius zu Anbeginn der Welt. Nachtelfen entwickelten und bewahrten den formalen cenarischen Druidismus über zehntausend Jahre hinweg, während Tauren erst kürzlich das geregelte Studium im Zirkel des Cenarius wieder aufnahmen.",al={"sind tauren neue druiden","tauren druidengeschichte cenarius"}}},fx={["9396c536"]={q="Warum schickt Dendrite Sternenschauer Euch zurück nach Donnerfels?",a="Eure anfängliche Gemeinschaft mit dem Großen Bärengeist auf der Mondlichtung war nur der erste Schritt Eures Erwachens. Dendrite Sternenschauer erkennt, dass die Anwendung der Lektionen der Wildnis praktische Anleitung von Eurem eigenen Mentor erfordert. Er vertraut die nächste Phase Eurer Unterweisung Turak Runentotem an, einem Tauren-Druiden, der mit tiefem Gleichgewicht wandelt, damit Ihr Euch der dauerhaften Stärke des Bären als würdig erweisen könnt.",al={"warum zu turak schicken","dendrite sternenschauers motiv","warum zurück nach donnerfels"}}},fp="21,197,20.396.0,20.356.0,51.212.0,23.239.0,52.182.0,64.142.0,40.201.0,72.250.0"}
P.entries["quest:594"] = {n="Flaschenpost",s="An der Küste des Schlingendorntals trägt die Flaschenpost den Hilferuf einer Gefangenen. Die Verfasserin schreibt, dass eine große Bestie sie auf einer abgelegenen Insel in den südlichen Meeren festhält.",h="An der Küste des Schlingendorntals trägt die Flaschenpost den Hilferuf einer Gefangenen.",kw={"halb vergrabene flasche","flaschenpost","prinzessin poobah","skymane","die südlichen meere","schlingendorntal","die wilden ufer"},sec={{t="Ein Hilferuf aus den Wellen",b="Ein Hilferuf ruht in einem Glasbehälter, halb im Sand vergraben. Die Gefangene sitzt unter dem dichten Dschungeldach einer fremden Insel fest, gefangen gehalten von einem großen Skymane. Die wilden Ufer liegen im Nordwesten, jenseits der Bäume. Große Segelschiffe treiben im Südwesten."},{t="Die Verfasserin der Nachricht",b="Die nautischen Wegbeschreibungen weisen über das Wasser zu einer vorgelagerten Insel, wo Prinzessin Poobah wartet. Dort gestrandet, hofft sie verzweifelt auf einen Abenteurer, der sie erreicht und ihr eine Chance auf Freiheit gibt."}},faq={{q="Was steht auf dem Zettel in der Flasche?",a="Der Zettel enthält einen säuberlich verfassten Hilferuf. Die Verfasserin schreibt, dass ein großer Skymane sie auf einer Insel in den südlichen Meeren gefangen hält, und fleht den Finder um Hilfe an.",al={"inhalt der nachricht","zettel in der flasche","was steht in der flasche"}},{q="Wo liegt die Insel laut der Verfasserin?",a="Die Gefangene schreibt, dass die wilden Ufer an klaren Tagen im Nordwesten zu sehen sind, während große Segelschiffe im Südwesten erscheinen. Nachts verbergen die Dschungelbäume die Sterne.",al={"lage der insel","wie die gefangene finden","orientierungspunkte der insel"}},{q="Was hält die Verfasserin gefangen?",a="Auf dem Zettel steht, dass eine Kreatur namens großer Skymane die Verfasserin auf der Insel gefangen hält.",al={"wer hat die verfasserin gefangen","was hält die verfasserin gefangen","skymane als kerkermeister"}},{q="Führt dies zu weiteren Abenteuern?",a="Die Suche nach der Absenderin beginnt eine zweiteilige Questreihe. Der zweite Teil folgt, sobald Ihr die Gefangene gefunden habt.",al={"nächste quest","gibt es eine fortsetzung","was passiert danach"}}},fp="19,175,21.267.0,22.194.1,37.182.0,48.163.0,35.88.0,37.96.0"}
P.entries["quest:5943"] = {n="Gizeltons Karawane",s="Bei Mannorocs Koven bittet Rigger Gizelton Euch, seine Karawane zu bewachen. Er und Cork brachen auf, um ein Vermögen zu machen, doch der Handel erwies sich als gefährlicher als erwartet.",h="Bei Mannorocs Koven bittet Rigger Gizelton Euch, seine Karawane zu bewachen.",kw={"karawane","cork","koven","desolace","gizelton","kodo","mannoroc","rigger","scrabblescrew","smeed"},sec={{t="An Mannorocs Koven vorbei",b="Rigger Gizelton und Cork gründeten ihre Karawane in der Hoffnung, ein Vermögen zu machen. Sie wussten nicht, wie riskant es sein konnte, Gewinn zu erzielen. Mannorocs Koven liegt vor ihnen, wo die Dämonen die Karawane gewöhnlich in Ruhe lassen. Dieses Mal sind die Kodos aufgeschreckt. Rigger bietet Euch Bezahlung an, wenn Ihr die Karawane am Koven vorbei bewacht. Sobald sie sicher hindurch ist, bezahlt Euch Smeed in Scrabblescrews Lager."},{t="Smeeds Bedenken",b="In Scrabblescrews Lager wischt sich Smeed über die Stirn und sagt, das Verschwinden der Karawane würde ihn ruinieren. Er ist froh zu hören, dass sie nicht verloren ist. Dennoch bezweifelt er, dass sich so viel Geld für den Schutz einer Karawane lohnt, deren Besitzer nur ein Goldstück pro Woche verdienen. Trotzdem bezahlen Cork und Rigger ihn weiterhin für seine Kodos. Es ist ihm egal, wie sie ihre Geschäfte führen."}},faq={{q="Wer ist Rigger Gizelton?",a="Rigger Gizelton besitzt eine Karawane, die er gemeinsam mit Cork gründete, in der Hoffnung, ein Vermögen zu machen.",al={"wer ist rigger","gizelton hintergrund","rigger gizelton"}},{q="Warum braucht die Karawane auf dem Weg an Mannorocs Koven vorbei Schutz?",a="Rigger sagt, die Dämonen bei Mannorocs Koven lassen die Karawane gewöhnlich in Ruhe, doch dieses Mal hat etwas die Kodos aufgeschreckt.",al={"warum die karawane eskortieren","mannorocs koven gefahr","warum die karawane beschützen"}},{q="Wer bezahlt Euch für den Schutz der Karawane?",a="Smeed, der Geschäftspartner der Gizeltons in Scrabblescrews Lager, bezahlt Euch, sobald die Karawane sicher am Koven vorbei ist.",al={"wer bezahlt mich","wo gizeltons karawane abgeben","smeed belohnung"}},{q="Wer ist Cork?",a="Cork ist Rigger Gizeltons Partner bei der Karawane.",al={"cork gizelton","wer ist cork"}}},fp="16,160,19.366.0,18.332.1,23.86.0,57.120.0,40.117.0,12.49.0"}
P.entries["quest:595"] = {n="Die Blutsegelbukaniere",s="Gerüchte über rivalisierende Piraten an der ungezähmten Küste beunruhigen die frisch eingetroffenen Blackwater Raiders. Erster Maat Crazz schickt Euch los, eine Bucht auszukundschaften, während seine Besatzung in Beutebucht trinkt und Gesellschaft sucht.",h="Gerüchte über rivalisierende Piraten an der ungezähmten Küste beunruhigen die frisch eingetroffenen...",kw={"blackwater raiders","blutsegelbukaniere","beutebucht","korrespondenz","erster maat crazz","die ungezähmte küste","schlingendorntal"},sec={{t="Erkundung an der ungezähmten Küste",b="Die Blackwater Raiders haben gerade erst in Beutebucht angelegt, als sie von Rivalen im gesamten südlichen Schlingendorntal erfahren. Die Besatzung ist an Land mit Grog und Gesellschaft beschäftigt, also bittet Euch Erster Maat Crazz, an ihrer Stelle zu gehen. Zieht an der ungezähmten Küste nach Norden und kundschaftet eine Bucht nach Anzeichen dafür aus, was die Blutsegelbukaniere treiben."},{t="Spuren in der Bucht",b="In der Bucht findet Ihr ein Fass, auf dem eine Karte liegt. Hastig gekritzelte Notizen bedecken sie, und daneben liegen einige Münzen."}},faq={{q="Wer ist Erster Maat Crazz?",a="Erster Maat Crazz ist ein Offizier der Blackwater Raiders in Beutebucht. Gerüchte über rivalisierende Piraten machen die Runde, und seine Besatzung ist an Land beschäftigt, also heuert er vorbeiziehende Abenteurer an, um die Küste auszukundschaften.",al={"erster maat crazz","wer vergibt die quest","wer ist crazz"}},{q="Warum braucht Erster Maat Crazz einen Außenstehenden?",a="Die Blackwater-Besatzung hat gerade erst angelegt und ist an Land zu sehr mit Zechen beschäftigt, um selbst die Küste auszukundschaften.",al={"warum einen abenteurer anheuern","warum kann seine besatzung es nicht tun","warum crazz helfen"}},{q="Wohin schickt Euch Crazz zur Erkundung?",a="Crazz schickt Euch zu einer Bucht unmittelbar nördlich von Beutebucht, an der ungezähmten Küste.",al={"wohin gehen","wo ist die bucht","wo sind die blutsegelbukaniere"}},{q="Welche Rivalität bereitet den Blackwater Raiders Sorgen?",a="Die Blackwater Raiders liegen in einer erbitterten Fehde mit den Blutsegelbukanieren, die kürzlich im gesamten südlichen Schlingendorntal gesichtet wurden.",al={"wer sind die rivalen","warum hassen sie die blutsegelbukaniere","rivalität mit den blutsegelbukanieren"}}},fp="24,190,30.324.0,17.121.1,24.193.0,43.104.0,41.81.0,49.138.0"}
P.entries["quest:596"] = {n="Blutige Knochenhalskette",s="Im Basislager Grom'gol macht Kin'weelay den Konflikt mit den Bloodscalp zu einem persönlichen Kampf.",h="Im Basislager Grom'gol macht Kin'weelay den Konflikt mit den Bloodscalp zu einem persönlichen Kampf.",kw={"bloodscalp","dunkelspeer","grom'gol","kin'weelay","halsketten","nimboya","schlingendorntal"},ang={["faction:Horde"]="Kin'weelay kam ins Basislager Grom'gol, um Nimboya zu helfen. Er nutzt seine Zeit dort, um die Bloodscalp im Norden zu jagen.",["race:Troll"]="Für einen Dunkelspeer bedeutet die Jagd auf die Bloodscalp, Macht über einen feindlichen Stamm zu gewinnen."},sec={{t="Trophäen des Krieges",b="Kin'weelay kam ins Basislager Grom'gol, um Nimboya zu helfen, doch er verfolgt eigene Ziele. Die Bloodscalptrolle im Norden sind Feinde der Dunkelspeere. Kin'weelay glaubt, dass Trophäen gefallener Feinde spirituelle Macht über sie verleihen. Deshalb bittet er Reisende, Bloodscalpkrieger zu jagen und die blutigen Knochenhalsketten zu erbeuten, die sie tragen."},{t="Die Geister auslaugen",b="Kin'weelay plant, die Knochenhalsketten auszukochen und auszulaugen, bis sie zu Brei zerfallen. Durch dieses Ritual hofft er, die verbliebenen Geister getöteter Bloodscalp verkümmern zu lassen und zu schwächen."}},faq={{q="Wer bittet um die Knochenhalsketten?",a="Kin'weelay bittet im Basislager Grom'gol im Schlingendorntal um die Knochenhalsketten. Er kam, um Nimboya zu helfen, verfolgt jedoch seinen eigenen spirituellen Rachefeldzug.",al={"questgeber","wer vergibt blutige knochenhalskette","kin'weelay quest"}},{q="Warum will Kin'weelay Trophäen vom Bloodscalp-Stamm?",a="Die Bloodscalp sind erbitterte Feinde der Darkspear tribe. Kin'weelay glaubt, dass Trophäen getöteter Feinde Macht über sie verleihen und den Dunkelspeeren so ermöglichen, ihre Vorherrschaft über ihre Rivalen zu behaupten.",al={"warum halsketten sammeln","bloodscalp halsketten zweck","warum bloodscalp jagen"}},{q="Wo sind die Bloodscalp zu finden?",a="Die Bloodscalptrolle leben nördlich des Basislagers Grom'gol, über das nördliche Schlingendorntal verteilt.",al={"wo bloodscalp finden","bloodscalp aufenthaltsort","wo sind die trolle"}},{q="Was kommt nach dieser Jagd?",a="Nach der Jagd schickt Kin'weelay Euch zu Split Bone Necklace weiter.",al={"nächste quest","blutige knochenhalskette folgequest","was nach blutige knochenhalskette"}}},fp="21,88,15.332.0,20.167.1,32.147.0,60.193.0,34.92.0,32.63.0"}
P.entries["quest:597"] = {n="Die Blutsegelbukaniere",s="In Beutebucht deuten die Pläne der Blutsegelbukaniere nun auf ein Lager und ein Angriffssignal hin.",h="In Beutebucht deuten die Pläne der Blutsegelbukaniere nun auf ein Lager und ein Angriffssignal hin.",kw={"blutsegelbukaniere","korrespondenz der blutsegelbukaniere","beutebucht","erster maat crazz","südlicher kommandoposten","schlingendorntal"},sec={{t="Ein Komplott enthüllt",b="Eine Karte markiert das geplante Lager der Blutsegelbukaniere in Beutebucht mit einem roten X. Ihre Befehle verlangen Stille. Die Mannschaft muss jeden töten, der sich nähert, und vor dem Angriff auf ein Signal vom südlichen Kommandoposten warten."},{t="Bericht im Hafen",b="Ihr bringt die Erkenntnisse zurück zum Ersten Maat Crazz in Beutebucht. Er hat Euch zum Kundschaften ausgesandt, und die Piraten warten noch immer auf das Signal, bevor sie angreifen."}},faq={{q="Was steht in der Korrespondenz der Blutsegelbukaniere?",a="Die sichergestellte Korrespondenz der Blutsegelbukaniere befiehlt der Mannschaft, an der markierten Stelle still ihr Lager aufzuschlagen, jeden zu töten, der sich nähert, und vor dem Angriff auf ein Signal von ihrem südlichen Kommandoposten zu warten.",al={"blutsegelbefehle text","was steht in der notiz","blutsegelkarte details"}},{q="Wohin weist die Karte?",a="Ein rotes X auf der Karte von Beutebucht markiert das geplante Lager der Piraten.",al={"blutsegelkarte x","was bedeutet das rote x","wo ist das lager"}},{q="Wer muss von dieser Entdeckung erfahren?",a="Erster Maat Crazz in Beutebucht muss von der Entdeckung erfahren. Er hat Euch ausgesandt, um das Gebiet auszukundschaften.",al={"bei wem abgeben","wer bekommt die blutsegelkarte","erster maat crazz bericht"}},{q="Was geschah vor dem Fund dieser Korrespondenz?",a="Erster Maat Crazz hat Euch zunächst von Beutebucht ausgesandt, um Nachforschungen über die Blutsegelbukaniere anzustellen.",al={"vorausgesetzte quest","vorherige quest blutsegel","blutsegel questreihe anfang"}}},fp="24,89,15.223.0,23.152.0,48.202.0,25.67.0,39.92.0,45.87.0"}
P.entries["quest:598"] = {n="Spaltknochenhalskette",s="Kin'weelay im Basislager Grom'gol schickt Euch nach Südosten, um die Schädelspalter zu jagen. Die Dunkelspeere haben das Schlingendorntal verlassen, doch ihre alte Fehde mit diesen Rivalen des Dschungels dauert an. Bringt fünfundzwanzig Trophäen aus gespaltenen Knochen zurück, um den Dunkelspeeren zu helfen und ihre Freundschaft zu gewinnen.",h="Kin'weelay im Basislager Grom'gol schickt Euch nach Südosten, um die Schädelspalter zu jagen.",kw={"dunkelspeer","basislager grom'gol","kin'weelay","schädelspalter","spaltknochenhalskette","schlingendorntal"},ang={["faction:Horde"]="Als Verbündeter der Horde gewinnt Ihr die Freundschaft der Dunkelspeere, indem Ihr Kin'weelay im Basislager Grom'gol im Krieg gegen die Schädelspalter helft.",["race:Troll"]="Als Troll der Dunkelspeere führt Ihr mit Trophäen von den Schädelspaltern einen langen Krieg fort, der nicht endete, als Euer Stamm das Schlingendorntal verließ."},sec={{t="Eine ungebrochene Fehde",b="Nach der Jagd auf die Bloodscalp wendet sich Kin'weelay einem weiteren alten Feind zu. Südöstlich des Basislagers Grom'gol kämpft der Stamm der Schädelspalter seit vielen Jahren gegen die Dunkelspeere. Die Dunkelspeere leben nicht mehr im Schlingendorntal, doch sie bleiben an diesen Krieg gebunden."},{t="Trophäen des Krieges",b="Ihr reist in das Gebiet der Schädelspalter, um fünfundzwanzig Spaltknochenhalsketten zu erbeuten und die Freundschaft und den Respekt der Dunkelspeere zu gewinnen. Kin'weelay erfüllt es mit Stolz, diese feindseligen Trolle wie junge Schösslinge von einem Basilisken niedergestreckt zu sehen. Jede Trophäe, die Ihr zurückbringt, zählt als Sieg für sein Volk."}},faq={{q="Wer bietet diese Jagd an, und wo ist er zu finden?",a="Kin'weelay bietet die Jagd im Basislager Grom'gol an, einem Außenposten der Horde an der Westküste des Schlingendorntals.",al={"wer vergibt spaltknochenhalskette","kinweelay standort","questgeber spaltknochenhalskette"}},{q="Was ging dieser Aufgabe voraus?",a="Diese Jagd folgt auf Bloody Bone Necklaces, als Kin'weelay Abenteurer ausschickte, um Trophäen vom Stamm der Bloodscalp zu erbeuten.",al={"spaltknochenhalskette voraussetzung","vorquest zu spaltknochenhalskette","vorheriger schritt"}},{q="Warum bekämpfen die Dunkelspeere die Schädelspalter, obwohl sie das Schlingendorntal verlassen haben?",a="Die Dunkelspeere und die Schädelspalter kämpften jahrelang im Dschungel gegeneinander. Obwohl die Dunkelspeere das Schlingendorntal verlassen haben, bleiben sie laut Kin'weelay an den Konflikt gebunden und wollen ihre Feinde bereuen lassen, ihn begonnen zu haben.",al={"warum hassen dunkelspeere schädelspalter","schädelspalter krieg hintergrund","dunkelspeer schädelspalter konflikt"}},{q="Wo ist der Stamm der Schädelspalter zu finden?",a="Der Stamm der Schädelspalter lebt südöstlich des Basislagers Grom'gol im Schlingendorntal.",al={"schädelspalter standort","wo sind schädelspalter","schädelspalter lager"}},{q="Welchen Beweis verlangt Kin'weelay von der Jagd?",a="Kin'weelay verlangt fünfundzwanzig Spaltknochenhalsketten von gefallenen Trollen der Schädelspalter.",al={"welche gegenstände braucht kinweelay","spaltknochenhalskette gegenstand","wie viele halsketten"}}},fp="19,267,16.252.0,15.291.0,46.106.0,27.115.0,79.210.0,43.84.0,48.92.0"}
P.entries["quest:599"] = {n="Die Blutsegelbukaniere",s="Erster Maat Crazz hat erfahren, dass die Blutsegelbukaniere Beutebucht angreifen wollen. Er schickt Euch, um Flottenmeister Seehorn, den Befehlshaber der Blackwater Raiders, zu warnen, bevor sie losschlagen.",h="Erster Maat Crazz hat erfahren, dass die Blutsegelbukaniere Beutebucht angreifen wollen.",kw={"blackwater raiders","blutsegelbukaniere","beutebucht","erster maat crazz","flottenmeister seehorn","schlingendorntal"},sec={{t="Eine Warnung für den Flottenmeister",b="Erster Maat Crazz schickt Euch, um Flottenmeister Seehorn vor einem Angriff auf Beutebucht zu warnen. Crazz hat erfahren, dass die Blutsegelbukaniere den Hafen direkt angreifen wollen, und die Bedrohung ist größer, als er zunächst dachte. Seehorn ist irgendwo in der Stadt. Er muss die Warnung hören, bevor die rivalisierenden Piraten losschlagen."},{t="Seehorns Trotz",b="Flottenmeister Seehorn tut den Plan der Blutsegelbukaniere, Beutebucht anzugreifen, als töricht ab. Er sagt, das sei ebenso töricht wie ein Sprung von den Klippen des Rundblicks. Dennoch erkennt er den Wert Eurer Warnung und dankt Euch im Namen der Blackwater Raiders."}},faq={{q="Wer schickt Euch, um Flottenmeister Seehorn zu warnen?",a="Erster Maat Crazz schickt Euch, um Flottenmeister Seehorn zu warnen, nachdem er erfahren hat, wie weit die feindseligen Pläne der Blutsegelbukaniere reichen.",al={"wer beginnt diese quest","erster maat crazz quest","blutsegelbukaniere questgeber"}},{q="Wo ist Flottenmeister Seehorn zu finden?",a="Flottenmeister Seehorn ist in Beutebucht, dem Piratenzufluchtsort im südlichen Schlingendorntal.",al={"wo ist seehorn","seehorn standort","flottenmeister seehorn stadt"}},{q="Was haben die Blutsegelbukaniere vor?",a="Die Blutsegelbukaniere bereiten einen offenen Angriff auf Beutebucht vor und stellen damit die Herrschaft der Blackwater Raiders über die Stadt infrage.",al={"was machen die blutsegelbukaniere","blutsegel angriffsplan","blutsegelbukaniere verschwörung"}},{q="Welche Fraktion kontrolliert Beutebucht?",a="Die Blackwater Raiders halten und betreiben Beutebucht und verteidigen den Hafen erbittert gegen ihre Rivalen von den Blutsegelbukanieren.",al={"wer leitet beutebucht","beutebucht piratenfraktion"}}},fp="24,182,30.294.0,18.237.1,43.125.0,40.86.0,41.127.0,33.109.0"}
P.entries["quest:6"] = {n="Kopfgeld auf Garrick Schleichfuß",s="Nahe der Abtei von Nordhain ruft ein Kopfgeld der Allianz Rekruten zur Jagd auf Garrick Padfoot bei den Weinbergen auf. Der berüchtigte Dieb und seine Bande bedrohen die Bauern und Händler des Tals.",h="Nahe der Abtei von Nordhain ruft ein Kopfgeld der Allianz Rekruten zur Jagd auf Garrick Padfoot bei den...",kw={"kopfgeld","halsabschneider","elwynn","garrick","nordhain","padfoot","diebe","weinberg","willem"},ang={["class:Rogue"]="Als Schurke seht Ihr, wie Gesetzlose in Elwynns Schatten vorgehen. Ein schlecht verborgenes Versteck lädt zu einer schnellen Klinge ein.",["faction:Alliance"]="Garrick Padfoot zur Strecke zu bringen, ist ein früher Dienst für einen aufstrebenden Abenteurer der Allianz und hilft, die Stabilität im Königreich Sturmwind wiederherzustellen.",["race:Human"]="Als Mensch, der im Königreich aufgewachsen ist, habt Ihr Grund, den heiligen Boden Eurer Heimat und die örtlichen Bauern vor Halsabschneidern wie Padfoot zu schützen."},sec={{t="Eine Plage für das Tal",b="Das Nordhaintal bot einen sicheren Ort, um Rekruten auszubilden und seine heiligen Weinberge zu pflegen. Doch während die Ordnung in ganz Elwynn ins Wanken gerät, sind Diebe bis ins Tal vorgedrungen. Garrick Padfoot, ein Halsabschneider, schwang sich rasch zu ihrem Anführer auf. Seit Wochen plündern er und seine Bande Lieferungen, überfallen Händler auf den Straßen und bedrohen die örtlichen Bauern."},{t="Deputy Willems Gerechtigkeit",b="Sturmwinds Wachen sind mit dem Schutz der Hauptstadt und ihrer Außengrenzen überlastet. Deshalb verlassen sich örtliche Marschälle und Deputys auf Freiwillige, um den Frieden in Nordhain zu wahren. Deputy Willem setzt ein öffentliches Kopfgeld auf Garricks Kopf aus, in der Hoffnung, das Tal von seiner Bande zu befreien. Padfoots heruntergekommene Hütte liegt östlich des Flusses. Ihn dort zur Strecke zu bringen, versetzt der Gesetzlosigkeit, die sich im Kernland der Menschen ausbreitet, einen Schlag."}},faq={{q="Wer ist Garrick Padfoot?",a="Garrick Padfoot ist ein Bandit und Halsabschneider im Nordhaintal. Seit Wochen drangsaliert er örtliche Bauern und überfällt Händler aus dem Hinterhalt, während er nahe den Weinbergen eine kleine Schar von Schlägern um sich sammelt.",al={"garrick padfoot","wer ist garrick","padfoot"}},{q="Wo ist Garrick Padfoot zu finden?",a="Garrick Padfoot versteckt sich in einer kleinen Holzhütte östlich der Abtei von Nordhain, jenseits der Brücke über den Fluss und nahe den Weinbergen. Andere Schläger bewachen ihn.",al={"wo ist garrick padfoot","garricks aufenthaltsort","garricks hütte"}},{q="Wer setzt das Kopfgeld auf Garrick aus?",a="Deputy Willem, der vor der Abtei von Nordhain stationiert ist, setzt das Kopfgeld aus. Da es zu wenige Stadtwachen gibt, um im Tal für Ordnung zu sorgen, ruft er umherziehende Rekruten auf, den Gesetzlosen seiner gerechten Strafe zuzuführen.",al={"wer setzt kopfgeld auf garrick padfoot aus","willems kopfgeld"}},{q="Warum schickt Sturmwind keine regulären Soldaten gegen ihn?",a="Sturmwinds Streitkräfte sind überlastet. Da König Varian Wrynn vermisst wird und die Spannungen im Wald von Elwynn und darüber hinaus zunehmen, kann die Hauptstadt nicht für jeden kleinen Schläger erfahrene Garnisonstruppen entbehren. Die örtlichen Deputys müssen Rekruten zu Hilfe rufen.",al={"warum töten die wachen garrick nicht","wo sind sturmwinds wachen"}},{q="Arbeitet Garrick Padfoot allein?",a="Nein. Garrick hat eine kleine Bande von Gesetzlosen und Banditen um sich geschart, die zum Schutz seiner Person um seine Hütte nahe den Weinbergen von Nordhain lagern.",al={"ist garrick allein","padfoots bande"}},{q="Welchen Beweis verlangt Deputy Willem?",a="Deputy Willem verlangt einen handfesten Beweis, bevor er das Geld auszahlt: Bringt Garrick Padfoots abgetrennten Kopf zur Abtei von Nordhain zurück.",al={"beweis für garricks tod","garricks kopf"}}},fx={["38d5a8ce"]={q="Warum will Deputy Willem, dass Garrick Padfoot getötet wird?",a="Garrick Padfoot hat Wochen damit verbracht, das Nordhaintal zu terrorisieren. Als Halsabschneider, der eine Bande von Dieben anführt, beutet er aktiv die lokalen Bauern und reisenden Händler aus, die das Tal ernähren. Deputy Willem will ihn tot sehen, um seinen Überfällen ein Ende zu bereiten, die Sicherheit in den Weinbergen und auf den Straßen wiederherzustellen und die Gemeinschaft der Abtei vor weiterer Gewalt zu schützen.",al={"warum garrick padfoot töten","deputy willems motiv","warum will willem, dass garrick stirbt"}}},fp="25,176,22.327.0,23.394.0,23.180.0,35.143.0,33.178.0,63.235.0,33.132.0,38.124.0"}
P.entries["quest:60"] = {n="Koboldkerzen",s="Koboldkerzen ist ein früher Botengang, der von William Pestle im Gasthaus \"Zur Höhle des Löwen\" in Goldhain angeboten wird. Als reisender Alchemist aus seinem Laden in Sturmwind sucht Pestle nach dem dicken Wachs der großen Kerzen, die von den Kobolden getragen werden, welche die hiesigen Minen im Wald von Elwynn überrannt haben. Für Abenteurer dient er als frühe Einführung in das unterirdische Ungeziefer, das die wertvollen Goldadern des Königreichs heimsucht.",h="Koboldkerzen ist ein früher Botengang, der von William Pestle im Gasthaus \"Zur Höhle des Löwen\" in Goldhain...",kw={"apotheker","kerze","elwynn","tiefenschacht","goldhain","jaspis","kobold","wachs","william pestle"},ang={["faction:Alliance"]="Da die königliche Armee durch interne politische Zwietracht und fehlende Streitkräfte der Krone überlastet ist, obliegt die Sicherung der örtlichen Infrastruktur zivilen Freiwilligen und reisenden Abenteurern.",["profession:Mining"]="Die Kobolde wegen ihrer Kerzen zu beseitigen, führt Schürfer direkt zu den reichsten Kupfer- und Goldadern Elwynns, die von menschlichen Bergleuten aufgegeben werden mussten.",["race:Human"]="Die Rückeroberung der gestohlenen Minen von Elwynn und die Versorgung der Handwerker in Sturmwind mit Gütern sind frühe Pflichten für junge Untertanen des Königreichs."},sec={{t="Botengänge des Apothekers",b="William Pestle betreibt zusammen mit seinem Bruder Pestle's Apothecary im Handelsdistrikt von Sturmwind. Beim Brauen von Heilmitteln, Salben und Gebräuen sind Rohstoffe wie Wachs stets Mangelware. Anstatt feine Kerzen von Händlern aus der Stadt zu beziehen, erkennt Pestle, dass das Ungeziefer, das Elwynn plagt, erstaunlich stattliche Klumpen aus Talg und Wachs auf der Stirn trägt – kostenlos zu haben, wenn ein Abenteurer bereit ist, sie ihnen zu entreißen."},{t="Die Minen von Elwynn",b="Kobolde haben sowohl die Tiefenschachtmine südlich von Goldhain als auch die Jaspismine im Nordosten vollständig befallen. Diese schnüffelnden unterirdischen Kreaturen schätzen ihre Kerzen über fast alles andere und nutzen deren flackerndes Licht, um durch dunkle Schächte zu navigieren, während sie nach Gold und glänzenden Schmuckstücken graben. Diese Kerzen zu erbeuten füllt nicht nur Pestles Alchemievorräte auf, sondern dezimiert auch das vordringende Ungeziefer, das die wertvollen Schürfrechte des Königreichs abriegelt."}},faq={{q="Warum braucht William Pestle Koboldkerzen?",a="William Pestle und sein Bruder betreiben eine Apotheke im Handelsdistrikt von Sturmwind. Sie verwenden den ausgelassenen Talg und das Wachs aus den großen Kerzen als Zutat zum Versiegeln sowie für Salben und verschiedene alchemistische Zubereitungen.",al={"warum pestle kerzen will","wofür werden kerzen verwendet","kerzenwachs verwendung"}},{q="Wo findet man die großen Kerzen?",a="Die Kerzen werden von den Koboldarbeitern, dem Ungeziefer und den Gräbern getragen, die in den Minen im Wald von Elwynn hausen, vor allem in den Tunneln der Tiefenschachtmine südlich von Goldhain und der Jaspismine im Osten.",al={"wo sind koboldkerzen","kerzen fundorte","wie man große kerzen bekommt"}},{q="Warum sind Kobolde so besessen von Kerzen?",a="Kobolde leben unterirdisch in pechschwarzen Tunneln und sind auf die kleinen, an ihren Köpfen befestigten Flammen angewiesen, um beim Graben sehen zu können. Sie hegen eine abergläubische, fast panische Angst vor der Dunkelheit und verteidigen ihre Kerzen verbissen gegen jeden, der versucht, sie ihnen wegzunehmen.",al={"warum kobolde kerzen haben","du nimmst nicht kerze bedeutung","koboldkerzen hintergrundgeschichte"}},{q="Wer ist William Pestle?",a="William Pestle ist ein menschlicher Händler und Alchemist aus Sturmwind. Wenn er nicht in seinem Laden im Handelsdistrikt der Stadt arbeitet, reist er nach Goldhain, um sich günstige Materialien von durchreisenden Abenteurern zu sichern.",al={"wer ist william pestle","william pestle hintergrund","goldhain pestle"}},{q="Steht diese Quest mit anderen Problemen in Elwynn in Verbindung?",a="Ja. Der Befall der Tiefenschachtmine und der Jaspismine stellt eine große wirtschaftliche Bedrohung für Goldhain und Sturmwind dar. Menschliche Bergleute wurden vertrieben, und die Sicherung der Tunnel gehört zu den obersten Prioritäten von Marshall Dughan.",al={"elwynn minen probleme","warum kobolde in minen sind","goldhain koboldbedrohung"}},{q="Gibt es in Elwynn noch andere Minen, die von Kobolden befallen sind?",a="Die Tiefenschachtmine und die Jaspismine sind die beiden Hauptschauplätze nahe Goldhain, doch die Aktivitäten der Kobolde greifen auch auf die Flussufer des Waldes und ostwärts in Richtung der Grenzen des Rotkammgebirges über.",al={"andere koboldminen","elwynn minen liste"}}},fx={["13eaf00c"]={q="Wofür wird die Große Kerze verwendet?",a="William Pestle benötigt die Großen Kerzen wegen ihres Wachses. Er und sein Bruder betreiben Pestle's Apothecary im Handelsdistrikt von Sturmwind. Die Quests geben nicht an, für welche speziellen Präparate sie dieses Wachs verwenden.",al={"verwendung der großen kerze","warum große kerzen","wozu sind die kerzen"}},decb568d={q="Warum sind Kobolde in den Minen von Elwynn?",a="Kobolde sind unterirdische Aasfresser, die von dunklen, mineralreichen Tunneln angezogen werden, in denen sie nach Gold und wertvollem Erz graben können. Da das Militär von Sturmwind überlastet ist und König Varian Wrynn vermisst wird, waren die lokalen Minen von Elwynn wie Fargodeep und Jasperlode nur schlecht verteidigt, was es den Kobolden ermöglichte, die Schächte zu überrennen und die menschlichen Bergleute zu vertreiben.",al={"warum sind kobolde hier","fargodeep kobolde warum","koboldplage elwynn"}},["27573e3c"]={q="Warum bittet William Pestle Euch anstelle der Wachen von Sturmwind um Hilfe?",a="William Pestle ist Alchemist, kein Soldat. Da Kobolde die Tunnel von Fargodeep und Jasperlode aggressiv bewachen, wäre es für ihn lebensgefährlich, sich selbst in die Minen zu wagen. Währenddessen sind die lokalen Wachen von Sturmwind und die Elwynn Marshals völlig überfordert damit, sich mit Defias-Banditen und Gnollen auseinanderzusetzen, weshalb sie triviale Besorgungen wie das Sammeln von Wachs vorbeiziehenden Abenteurern überlassen.",al={"warum holt william die kerzen nicht selbst","warum abenteurer für kerzen anheuern","warum keine sturmwindwachen"}}},fp="14,275,20.343.0,19.353.0,44.177.0,36.165.0,41.248.0,22.181.0,52.197.0,56.181.0"}
P.entries["quest:600"] = {n="Venture Company-Bergbau",s="Im nördlichen Schlingendorntal findet die Venture Company immer wieder Singing Blue Crystals. Crank Fizzlebub in Beutebucht will zehn davon aus den Hügeln nahe der Kristalladermine gebracht bekommen.",h="Im nördlichen Schlingendorntal findet die Venture Company immer wieder Singing Blue Crystals.",kw={"beutebucht","crank fizzlebub","kristalladermine","singing blue crystals","schlingendorntal","venture company"},sec={{t="Die Konkurrenz stören",b="Ihr habt Singing Blue Shards gesammelt, und nun verweist Euch Crank Fizzlebub auf einen größeren Konkurrenten. Die Arbeit der Venture Company im gesamten Dschungel schmälert die Gewinne unabhängiger Goblins. Basilisken halten ihre Minenarbeiter von der Kristalladermine fern, also graben sie in den umliegenden Hügeln nach Singing Blue Crystals. Crank bittet Euch, den Minenarbeitern zehn davon abzunehmen und sie als Beweis für ihren Rückschlag nach Beutebucht zu bringen."},{t="Nach Ankunft der Kristalle",b="Crank Fizzlebub bezeichnet seine Bitte als gerechte Vergeltung gegen ein skrupelloses Kartell. Als er die Singing Blue Crystals sieht, verrät seine Begeisterung sein wahres Interesse. Er will die Steine in Beutebucht für ein beträchtliches Vermögen verkaufen."}},faq={{q="Wer vergibt die Quest Venture Company-Bergbau?",a="Crank Fizzlebub, ein Goblin in Beutebucht, bittet Euch um Hilfe, nachdem Ihr Singing Blue Shards abgeschlossen habt.",al={"wer startet venture company-bergbau","venture company-bergbau questgeber"}},{q="Wo graben die Minenarbeiter nach diesen Kristallen?",a="Die Minenarbeiter der Venture Company graben in den Hügeln rund um die Kristalladermine im nördlichen Schlingendorntal.",al={"wo ist venture company-bergbau","venture company mine standort schlingendorntal"}},{q="Warum sind die Minenarbeiter der Venture Company nicht in der Mine?",a="Basilisken in der Kristalladermine halten die Minenarbeiter der Venture Company fern, also graben sie stattdessen in den umliegenden Hügeln.",al={"warum außerhalb der kristalladermine","kristalladermine basilisken"}},{q="Was sollt Ihr Crank Fizzlebub bringen?",a="Crank Fizzlebub bittet Euch, ihm zehn Singing Blue Crystals zu bringen, die Ihr den Minenarbeitern der Venture Company nahe der Kristalladermine abnehmt.",al={"venture company-bergbau benötigte gegenstände","welche gegenstände für crank fizzlebub"}},{q="Was kam vor Venture Company-Bergbau?",a="Singing Blue Shards kam zuerst. Crank bittet Euch, kleinere Kristallsplitter im Schlingendorntal zu sammeln.",al={"venture company-bergbau questreihe","voraussetzung für venture company-bergbau"}}},fp="22,173,26.400.0,25.235.1,43.98.0,48.95.0,54.112.0,47.120.0,40.102.0"}
P.entries["quest:6001"] = {n="Körper und Herz",s="In Darnassus steht ein Nachtelfeninitiand kurz vor dem Ende des Pfades der Klaue. Mathrengyl Bärenfährte schickt ihn zur Dunkelküste, wo Lunaclaw seinen Körper und sein Herz prüfen wird, bevor er die Gestalt des Bären annimmt.",h="In Darnassus steht ein Nachtelfeninitiand kurz vor dem Ende des Pfades der Klaue.",kw={"auberdine","bärengestalt","körper und herz","mondstaub des cenarius","druide der klaue","lunaclaw","mathrengyl bärenfährte","mondkinstein"},ang={["class:Druid"]="Für einen Druiden markiert dieser Ritus eine entscheidende Schwelle in der frühen Ausbildung. Er verwandelt einen unerfahrenen Zauberwirker in einen gestaltwandelnden Beschützer, der die mächtige Bärengestalt annehmen kann.",["race:NightElf"]="Als Nachtelf erneuert Ihr Eure Verbindung zu jahrtausendealten Bräuchen des Cenarius, indem Ihr mit uralten Tiergeistern Zwiesprache haltet und heilige Steine an der Dunkelküste ehrt."},sec={{t="Die Prüfung von Lunaclaw",b="Mathrengyl Bärenfährte schickt Nachtelfeninitianden östlich von Auberdine, der Küstensiedlung an der Dunkelküste. Dort bietet eine natürliche Höhle wilden Mondkins und einem uralten Mondkinstein Schutz. Wird der Stein mit Mondstaub des Cenarius gesalbt, erwacht Lunaclaw, sein uralter Verteidiger. Der Wächter fordert jeden Initianden heraus, der nach der heiligen Stärke der Klaue strebt."},{t="Stärke von Körper und Herz",b="Der Große Bärengeist vermittelt die ersten Lehren über die Wildheit der Natur. Die Gestalt des Bären anzunehmen, erfordert mehr als rohe Gewalt. Lunaclaws Prüfung stellt die Herzensstärke eines Initianden auf die Probe. Indem ein Druide den Wächter bezwingt und die verweilende Weisheit des Geistes beherzigt, beweist er seine Bereitschaft, die Bärengestalt zu nutzen, ohne sich in tierischen Instinkten zu verlieren."}},faq={{q="Wer ist Lunaclaw?",a="Lunaclaw ist ein uralter Mondkinwächter in einer Höhle östlich von Auberdine an der Dunkelküste. Er verteidigt den heiligen Mondkinstein und erwacht, wenn ein Initiand den Stein mit Mondstaub des Cenarius salbt.",al={"was ist lunaclaw","lunaclaws geschichte","mondkinboss auberdine"}},{q="Welchen Zweck hat diese Prüfung?",a="Diese Prüfung ist die letzte Bewährungsprobe für einen Nachtelfeninitianden, der sich den Druids of the Claw anschließen möchte. Ein Sieg über Lunaclaw beweist, dass der Initiand die körperliche Widerstandskraft und geistige Ruhe besitzt, um Geist und Gestalt des Bären anzunehmen.",al={"warum körper und herz","was bewirkt diese quest","geschichte der bärengestaltquest"}},{q="Wer vergibt diese Quest?",a="Mathrengyl Bärenfährte, ein erfahrener Druidenlehrer in der Enklave des Cenarius in Darnassus, gibt Initianden diese Prüfung auf, nachdem sie mit dem Großen Bärengeist Zwiesprache gehalten haben.",al={"questgeber körper und herz","wer vergibt die bärengestaltquest"}},{q="Was ist Mondstaub des Cenarius?",a="Mondstaub des Cenarius ist ein geweihtes Ritualpulver, das Initianden von ihren Ältesten erhalten. Auf den Mondkinstein gestreut, erweckt seine Magie Lunaclaw und leitet den rituellen Kampf ein.",al={"was ist mondstaub","geschichte des mondstaubs des cenarius"}},{q="Wo findet diese Prüfung statt?",a="Die Prüfung findet in einer Höhle östlich von Auberdine an der Dunkelküste statt. Dort leben wilde Mondkins um einen uralten, behauenen Mondkinstein.",al={"wo ist der mondkinstein","mondkinhöhle auberdine"}},{q="Was geschieht nach dem Sieg über Lunaclaw?",a="Nachdem Lunaclaw besiegt wurde, erscheint der Spirit of Lunaclaw über seiner körperlichen Hülle und spendet einen Segen. Der Segen würdigt die Stärke von Herz und Körper des Druiden, bevor dieser nach Darnassus zurückkehrt.",al={"was geschieht nach lunaclaws tod","spirit of lunaclaw"}}},fx={["26f3a5de"]={q="Warum schickt Mathrengyl Bärenfährte Euch, um sich Lunaclaw zu stellen?",a="Mathrengyl Bärenfährte dient als Euer Mentor in Darnassus und muss prüfen, ob Ihr würdig seid, den Pfad des Druid of the Claw zu beschreiten. Bevor er die Geheimnisse der Bärengestalt für Euch enthüllen kann, benötigt er den Beweis, dass Ihr nicht nur über körperliche Stärke verfügt, sondern auch über die Stärke des Herzens, die nötig ist, um die urzeitliche Macht zu führen, ohne Euch selbst zu verlieren.",al={"warum prüfung bei mathrengyl bärenfährte","mathrengyl bärenfährte beweggrund","warum körper und herz"}},d295d16d={q="Warum müsst Ihr diese Prüfung selbst absolvieren?",a="Dies ist ein heiliger Ritus des Übergangs, der den inneren Geist eines Druiden auf die Probe stellt. Kein Wächter, keine Wache und kein Mentor kann die Prüfung für Euch ablegen, da die Stärke von Körper und Herz durch Eure eigene Entschlossenheit bewiesen werden muss. Um mit dem Geist zu kommunizieren und die Gestalten der Wildnis zu meistern, müsst Ihr Euch Lunaclaw stellen und seinen Segen im persönlichen Kampf verdienen.",al={"warum können wachen lunaclaw nicht bekämpfen","warum ich körper und herz","warum druide allein"}}},fp="14,211,21.343.0,26.355.1,16.190.0,34.225.0,21.160.0,26.170.0,33.129.0,40.205.1"}
P.entries["quest:6002"] = {n="Körper und Herz",s="Am Mondkinstift erwartet Euch eine Prüfung von Stärke und Herz, um die Bärengestalt zu meistern. Turak Runentotem schickt junge Taurendruiden aus Donnerfels aus, um Mondklaue nahe der trockenen Grenze zwischen Mulgore und dem Brachland zu beschwören und zu besiegen.",h="Am Mondkinstift erwartet Euch eine Prüfung von Stärke und Herz, um die Bärengestalt zu meistern.",kw={"brachland","bärengestalt","körper und herz","camp taurajo","lunarstaub des cenarius","mondklaue","mondkinstift","mulgore","donnerfels","turak runentotem"},ang={["class:Druid"]="Für Euch als Druiden verbindet dieser Ritus cenarische Lehren mit dem Erbe der Tauren. Er lässt Euch die Bärengestalt und ihre wilde Widerstandskraft annehmen.",["faction:Horde"]="Als Taurendruide bringt Ihr Widerstandskraft an die Front der Horde und verankert ihre Magie im Schutz der Wildnis.",["race:Tauren"]="Für Euch als Shu'halo verbindet das Erwecken des inneren Bären die Zwiesprache mit Naturgeistern mit einer Möglichkeit, Mulg ores Ebenen gegen vordringende Bedrohungen zu verteidigen."},sec={{t="Der Weg der Klaue",b="Turak Runentotem prüft junge Taurendruiden, die den Pfad des Druiden der Klaue suchen. Ihr habt in Mondlichtung mit dem Großen Bärengeist Zwiesprache gehalten. Nun führt Euch Eure Ausbildung zu einer Prüfung der Stärke. Turak, der erfahrene Druidenlehrer auf der Anhöhe der Ältesten in Donnerfels, gibt würdigen Anwärtern Lunarstaub des Cenarius. Er schickt Euch zu einem heiligen Stein nahe der trockenen Grenze, an der Mulgore auf das Brachland trifft."},{t="Die Prüfung von Mondklaue",b="Westlich von Camp Taurajo kennzeichnet der Mondkinstift eine seltene cenarische Stätte im südlichen Kalimdor. Mondkins sind auf den sonnenverbrannten Ebenen des zentralen Kalimdor nicht heimisch, und Mondklaue bewacht den Stein. Streut den Lunarstaub über das uralte Monument, um Mondklaue zum Kampf zu rufen. Der Sieg über den Wächter beweist Eure Stärke und die Klarheit Eures Herzens. Sein Segen erweckt die innere Essenz des Bären."}},faq={{q="Welchen Zweck hat diese Prüfung?",a="Diese Prüfung ist der letzte Schritt für Druiden der Horde, die die Bärengestalt erlernen wollen. Wer ihre Herausforderung besteht, beweist seine Bereitschaft, unter Turak Runentotems Führung dem Pfad des Druiden der Klaue zu folgen.",al={"warum körper und herz","was bewirkt körper und herz","was gibt es für körper und herz"}},{q="Wo befindet sich der Mondkinstift?",a="Der Mondkinstift liegt im Brachland, westlich von Camp Taurajo an der Straße zum Tor nach Mulgore. Gleich südlich der Straße, hinter einem Baum nahe einem einzelnen Zelt, liegt der heilige Stein.",al={"mondkinstift standort","wo ist der mondkinstift","wo den mondkinstift finden"}},{q="Wer ist Mondklaue?",a="Mondklaue ist ein wilder Mondkinwächter, der an den Mondkinstift gebunden ist. Lunarstaub des Cenarius beschwört ihn, um zu prüfen, ob Ihr die nötige Entschlossenheit und Ruhe besitzt, um die Kraft des Bären zu führen.",al={"wer ist mondklaue","was ist mondklaue"}},{q="Was geschieht, wenn ich den Kampf gegen Mondklaue verliere?",a="Wenn Mondklaue Euch besiegt, ist Euer Lunarstaub des Cenarius verbraucht. Kehrt zu Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels zurück, um vor Eurem nächsten Versuch einen weiteren Beutel Staub zu erhalten.",al={"an mondklaue gescheitert","lunarstaub verloren","durch mondklaue gestorben"}},{q="Sind Mondkins im Brachland heimisch?",a="Nein. Mondkins sind weder im Brachland noch in Mulgore heimisch. Mondklaue ist ein ungewöhnlicher Anblick in der Savanne, gebunden an cenarische Riten und uralte Stätten himmlischer Macht.",al={"mondkins im brachland","warum sind hier mondkins","brachland mondkins"}},{q="Wer vergibt die Quest Körper und Herz?",a="Turak Runentotem stellt Initiaten, die aus Mondlichtung zurückkehren, diese Herausforderung. Er ist der ranghöchste Druidenlehrer auf der Anhöhe der Ältesten in Donnerfels.",al={"wer startet körper und herz","körper und herz questgeber"}}},fx={["928957c5"]={q="Warum möchte Turak Runentotem, dass Ihr Euch Lunaclaw stellt?",a="Turak Runentotem dient als Euer Mentor in Donnerfels und muss sicherstellen, dass Ihr wirklich bereit seid, den Pfad des Druid of the Claw zu beschreiten. Einem Druiden können die Geheimnisse der Verwandlung in einen Bären nicht einfach übergeben werden; Ihr müsst beweisen, dass Ihr sowohl über die innere Standhaftigkeit des Geistes als auch über die körperliche Leistungsfähigkeit verfügt, die notwendig ist, um die rohe Kraft der Gestalt zu beherrschen. Indem Ihr Lunaclaw heraufbeschwört und besiegt, beweist Ihr die Stärke von Herz und Körper, die erforderlich ist, bevor er Euch unterrichtet.",al={"turak runentotem beweggrund","warum lunaclaw besiegen","turak test beweggrund"}},ac0863bb={q="Warum müsst Ihr diese Prüfung alleine absolvieren, anstatt Wachen zu schicken?",a="Dies ist ein heiliger Ritus des Übergangs, der einzigartig für Eure spirituelle Reise als angehender Druide ist. Turak kann den Ritus nicht für Euch vollziehen, noch könnten die Tapferen von Donnerfels helfen, denn das Ziel ist nicht, eine Bedrohung zu beseitigen, sondern eine spirituelle Lektion aufzunehmen. Lunaclaw bietet eine Gemeinschaft der Stärke, die nur verdient werden kann, indem Ihr Euer eigenes Gleichgewicht, Eure Entschlossenheit und Eure Hingabe gegen den Wächter prüft.",al={"warum ich körper und herz","warum muss ich lunaclaw allein bekämpfen","können wachen bei lunaclaw helfen"}}},fp="14,227,19.385.0,21.383.0,34.185.0,35.178.0,16.175.0,51.169.0,34.161.0,35.142.0"}
P.entries["quest:601"] = {n="Wasserelementare",s="Auf der Insel vor der Küste könnten Wasserelementare Hinweise auf den Fluch des Steins der Gezeiten liefern. Baron Revilgaz will ihre Armschienen untersuchen lassen, um einen Weg zu finden, ihm entgegenzuwirken.",h="Auf der Insel vor der Küste könnten Wasserelementare Hinweise auf den Fluch des Steins der Gezeiten liefern.",kw={"beutebucht","armschienen","fluch","dalaran","gazban","revilgaz","stein der gezeiten","wasserelementar"},sec={{t="Den Fluch eindämmen",b="Baron Revilgaz vermutet, dass die magischen Rückstände der Wasserelementare helfen könnten, den Fluch des Steins der Gezeiten zu bekämpfen. Es heißt, der Stein lasse jeden, der ihn führt, in die Wirklichkeit hinein- und wieder hinausgleiten. Deshalb schickt er Euch zurück auf die Insel vor der Küste, um Armschienen zu sammeln, die die gelehrten Magier von Dalaran untersuchen sollen."},{t="Der Herr von Beutebucht",b="Baron Revilgaz gesteht, dass ihm das Fachwissen fehlt, um zu beurteilen, ob die Armschienen helfen können. Er weigert sich, Beutebucht zu verlassen, nur um mit lästigen alten Magiern zu sprechen. Deshalb schickt er Euch nach Norden, damit ein Magier sie untersucht."}},faq={{q="Wer will die Armschienen der Wasserelementare?",a="Baron Revilgaz, Anführer der Blackwater Raiders in Beutebucht, will die Armschienen auf Hinweise zur Magie untersuchen lassen, die den Stein der Gezeiten umgibt.",al={"wer gibt die quest wasserelementare","baron revilgaz quest","wer will armschienen"}},{q="Warum braucht Baron Revilgaz elementare Armschienen?",a="Revilgaz hofft, dass die magischen Rückstände der Armschienen offenbaren, wie sich dem Fluch des Steins der Gezeiten entgegenwirken lässt. Der Fluch lässt seinen Träger aus der Existenz verschwinden und wieder darin auftauchen.",al={"warum armschienen sammeln","zweck der wasserelementar-armschienen","fluch des steins der gezeiten"}},{q="Wer hat diese Wasserelementare beschworen?",a="Baron Revilgaz glaubt, dass Gazban, ein Goblinzauberer, der den Stein der Gezeiten gefunden haben soll, die Wasserelementare beschworen hat.",al={"wer hat die elementare beschworen","gazban hintergrundgeschichte","goblinzauberer"}},{q="Wohin führt diese Aufgabe als Nächstes?",a="Revilgaz schickt die Armschienen nach Norden nach Dalaran, wo ein Magier ihre Rückstände untersuchen kann.",al={"was kommt nach wasserelementare","nächste quest","wohin kommen die armschienen"}},{q="Warum bringt Revilgaz die Armschienen nicht selbst nach Dalaran?",a="Revilgaz weigert sich, Beutebucht zu verlassen, nur um mit lästigen alten Magiern zu sprechen. Er beharrt darauf, dass er von Möchtegernrivalen nichts zu befürchten hat.",al={"warum geht revilgaz nicht","revilgaz dalaran","warum in beutebucht bleiben"}}},fp="16,165,17.297.0,18.199.0,38.148.0,47.158.0,36.121.0,31.84.0,57.130.0"}
P.entries["quest:602"] = {n="Magische Analyse",s="Von Beutebucht schickt Baron Revilgaz Euch mit Wasserelementararmschienen nach Norden nach Dalaran. Er hofft, dass Erzmagier Ansirem Runenweber den Fluch untersuchen kann, der an den Stein der Gezeiten gebunden ist.",h="Von Beutebucht schickt Baron Revilgaz Euch mit Wasserelementararmschienen nach Norden nach Dalaran.",kw={"ansirem runenweber","baron revilgaz","beutebucht","dalaran","gurubashireich","magische analyse","stein der gezeiten","wasserelementararmschienen"},ang={["class:Mage"]="Als Magier bringt Ihr arkane Artefakte zu einem Erzmagier der Kirin Tor. Baron Revilgaz glaubt, dass Magier einem magischen Rätsel nicht widerstehen können."},sec={{t="Eine Bitte an Dalaran",b="Baron Revilgaz hat die Armschienen in Beutebucht, doch ihr Geheimnis bleibt ihm verborgen. In der Stadt gibt es keinen Magier, der den Fluch hinter dem Stein der Gezeiten entschlüsseln könnte, also verweist er Euch nach Dalaran. Dessen Zauberer arbeiten daran, ihr zerstörtes Königreich wiederaufzubauen. Revilgaz hatte schon früher mit Erzmagier Ansirem Runenweber zu tun und vertraut auf sein Wissen. Er glaubt, dass kein Magier einem faszinierenden Rätsel widerstehen kann."},{t="Das Wissen des Erzmagiers",b="In Dalaran unterbricht Erzmagier Ansirem Runenweber seine Arbeit, als Ihr ihm von dem Relikt erzählt. Vor Jahren schrieb er eine wissenschaftliche Abhandlung über die uralten Legenden des Gurubashireichs. Diese Studie gewährt ihm seltene Einblicke in die Vergangenheit des Relikts. Er untersucht die Armschienen und findet Spuren magischer Rückstände, die er erforschen kann. Er legt seine Arbeit beiseite und widmet sich der Aufgabe, das Wesen der Verzauberung zu ergründen."}},faq={{q="Wer schickt Euch für diese Untersuchung nach Dalaran?",a="Baron Revilgaz in Beutebucht gibt Euch einen Beutel mit Elemental Bracers und schickt Euch zu den Zauberern von Dalaran, um ihren Rat einzuholen.",al={"wer vergibt magische analyse","magische analyse questgeber","wer startet magische analyse"}},{q="Warum wählt Baron Revilgaz Erzmagier Ansirem Runenweber?",a="Revilgaz hatte schon früher mit Ansirem Runenweber zu tun und vertraut auf das umfassende Wissen des Erzmagiers. Er glaubt, dass Magier einem magischen Rätsel nicht widerstehen können.",al={"warum ansirem","verbindung zwischen revilgaz und ansirem","warum ansirem runenweber"}},{q="Was geschah vor dieser Reise nach Dalaran?",a="Bevor Ihr nach Dalaran reistet, habt Ihr in Water Elementals Wasserelementararmschienen für Baron Revilgaz gesammelt.",al={"vorherige quest","voraussetzung für magische analyse","welche quest führt hierher"}},{q="Was folgt, nachdem Ihr den Erzmagier erreicht habt?",a="Die Übergabe der Armschienen an Ansirem führt zu Ansirem’s Key.",al={"nächste quest","was folgt auf magische analyse","nach der abgabe der armschienen"}}},fp="16,176,17.400.0,19.379.1,40.110.0,57.143.0,41.105.0,44.55.0"}
P.entries["quest:6027"] = {n="Buch der Uralten",s="Am Turm von Ethel Rethor vertraut Euch Azore Aldamort den Edelstein der Schlange an. Legt ihn auf die Schlangenstatue auf der Insel Ranazjar nordwestlich des Turms, und der Beschützer des Buchs der Uralten erscheint.",h="Am Turm von Ethel Rethor vertraut Euch Azore Aldamort den Edelstein der Schlange an.",kw={"azore aldamort","buch der uralten","ethel rethor","edelstein der schlange","naga","die insel ranazjar","schlangenstatue"},sec={{t="Die Schlangenstatue",b="Nach Szepter des Lichts gibt Euch Azore Aldamort den Edelstein der Schlange. Die Insel Ranazjar liegt nordwestlich des Turms von Ethel Rethor, und dort wartet die Schlangenstatue. Legt den Edelstein auf ihre Hand, um den Beschützer des Buchs der Uralten herbeizurufen. Die Naga hüten die Geheimnisse des Buchs seit Jahrhunderten, und Azore hofft, dass es viel über ihre geschuppten Feinde lehren wird."}},faq={{q="Wer ist Azore Aldamort?",a="Azore Aldamort hütet den Turm von Ethel Rethor. Azore hofft, viel über die Naga zu erfahren, die Azore als geschuppte Feinde bezeichnet.",al={"azore aldamort","wer gibt das buch der uralten","typ im turm von ethel rethor"}},{q="Was ist das Buch der Uralten?",a="Das Buch der Uralten birgt Geheimnisse, die die Naga seit Jahrhunderten hüten. Jemand bewacht es.",al={"was ist das buch der uralten","geschichte des buchs","naga buch desolace"}},{q="Wo liegt die Insel Ranazjar?",a="Die Insel Ranazjar ist eine kleine Insel nordwestlich des Turms von Ethel Rethor.",al={"lage der insel ranazjar","wo liegt die insel ranazjar","wohin mit dem edelstein"}},{q="Wozu dient der Edelstein der Schlange?",a="Legt den Edelstein der Schlange auf die Hand der Schlangenstatue auf der Insel Ranazjar, um den Beschützer des Buchs der Uralten herbeizurufen.",al={"edelstein der schlange","hand der schlangenstatue","wie den beschützer herbeirufen"}},{q="Was kam davor?",a="Szepter des Lichts kommt vor diesem Schritt.",al={"vorherige quest","questreihe szepter des lichts","voraussetzung"}}},fp="20,212,18.355.0,22.119.0,33.91.0,23.68.0,35.134.0,22.40.0"}
P.entries["quest:603"] = {n="Ansirems Schlüssel",s="Ein uralter Trolldolch könnte die Magie schwächen, die den Stein der Gezeiten stärkt. Erzmagier Ansirem Runenweber fand die Klinge im Schlingendorntal und gab sie dann seiner Tochter Catelyn, die ihr Zuhause für die Piraten von Beutebucht verließ.",h="Ein uralter Trolldolch könnte die Magie schwächen, die den Stein der Gezeiten stärkt.",kw={"ansirem","beutebucht","catelyn","dolch","runenweber","stein der gezeiten","trollrelikt"},sec={{t="Eine eigensinnige Tochter",b="Erzmagier Ansirem Runenweber hat herausgefunden, dass ein Altar oder Fokuspunkt den Stein der Gezeiten verstärkt. Um diese Magie zu überwältigen, braucht er einen uralten Trolldolch, den er bei seinen Forschungen im Schlingendorntal entdeckte. Er gab die Klinge vor langer Zeit seiner Tochter Catelyn. Eigensinnig verließ sie ihr Zuhause für die Piraten von Beutebucht."},{t="Eine entwaffnete Kämpferin",b="In Beutebucht trägt Catelyn den Dolch nicht mehr an der Hüfte. Einst die geschickteste Messerkämpferin der Siedlung, verlor sie ein Duell gegen einen der Blutsegelbukaniere. Ihr Bezwinger nahm die Trollklinge als Trophäe an sich. Nun steht Catelyn entwaffnet und gedemütigt dem bitteren Spott ihrer Halsabschneidergefährten gegenüber."}},faq={{q="Warum braucht Erzmagier Ansirem den Trolldolch?",a="Der Magier, der den Stein der Gezeiten besitzt, kanalisiert dessen Magie durch einen Altar. Ansirem hofft, dass ein uralter Trolldolch diese Verstärkung stören kann, indem er sie überwältigt.",al={"warum dolch nötig","ansirems schlüssel zweck","wozu dient der dolch"}},{q="Wer ist Catelyn?",a="Catelyn ist die eigensinnige Tochter von Erzmagier Ansirem Runenweber. Sie verließ ihren Vater, um als Piratin in Beutebucht zu leben.",al={"wer ist catelyn","ansirems tochter","catelyn die klinge"}},{q="Wo hat Ansirem den Dolch ursprünglich gefunden?",a="Ansirem fand das Relikt bei seinen Forschungen in den Dschungeln des Schlingendorntals und gab es dann seiner Tochter.",al={"herkunft des dolches","wo fand ansirem den dolch"}},{q="Wo ist Catelyn zu finden?",a="Catelyn lebt in Beutebucht, dem Piratenzufluchtsort an der Südspitze des Schlingendorntals.",al={"wo ist catelyn","catelyns aufenthaltsort"}}},fp="13,223,18.317.0,18.289.1,48.163.0,15.128.0,45.109.0,27.87.0"}
P.entries["quest:604"] = {n="Die Blutsegelbukaniere",s="An den wilden Ufern haben die Blutsegelbukaniere einen südlichen Kommandoposten errichtet. Flottenmeister Seehorn schickt einen vertrauenswürdigen Blackwater Raider, um ihre Karten und Befehle zu erbeuten, damit die Flotte ihre Pläne erfährt.",h="An den wilden Ufern haben die Blutsegelbukaniere einen südlichen Kommandoposten errichtet.",kw={"blackwater raiders","blutsegelbukaniere","blutsegelkarten","blutsegelbefehle","beutebucht","flottenmeister seehorn","die wilden ufer"},sec={{t="Angriff auf die wilden Ufer",b="Crazz’ Lob hat Flottenmeister Seehorn auf Euch aufmerksam gemacht. Die Blutsegelbukaniere haben an den wilden Ufern einen südlichen Kommandoposten errichtet. Seehorn schickt Euch, um ihr Lager anzugreifen, ihre Haudegen niederzustrecken und ihre Seekarten sowie schriftlichen Befehle zu erbeuten. Die Flotte braucht diese Unterlagen, um die Absichten ihrer Rivalen zu erfahren."},{t="Der Plan der Flotte",b="Die Karten und Befehle der Blutsegel enthüllen den Plan der Piraten. Seehorn kommt zu dem Schluss, dass sie nahe am Kap vor Anker gegangen sind."}},faq={{q="Wer erteilt den Auftrag für diesen Angriff?",a="Flottenmeister Seehorn erteilt den Auftrag für den Angriff von Beutebucht aus, nachdem Crazz Eure Hingabe gelobt hat.",al={"wer vergibt die quest der blutsegelbukaniere","seehorn quest"}},{q="Wo liegt der Kommandoposten der Blutsegel?",a="Das südliche Kommandolager der Blutsegelbukaniere liegt an den wilden Ufern, südlich von Beutebucht im Schlingendorntal.",al={"standort des südlichen kommandopostens der blutsegel","wo sind die wilden ufer"}},{q="Welche Gegenstände werden aus dem Lager der Blutsegel benötigt?",a="Seehorn bittet Euch, die Blutsegelkarten und die schriftlichen Blutsegelbefehle zu bergen, um die Absichten der rivalisierenden Bukaniere zu erfahren.",al={"welche dokumente will seehorn","blutsegelbefehle und blutsegelkarten"}},{q="Warum will Flottenmeister Seehorn ihre Karten und Befehle?",a="Flottenmeister Seehorn will die Karten und Befehle, um zu erfahren, was die Blutsegelbukaniere planen.",al={"warum die wilden ufer angreifen","was will seehorn wissen"}}},fp="24,205,22.329.0,29.115.1,22.89.0,44.118.0,52.120.0,59.101.0"}
P.entries["quest:605"] = {n="Singende blaue Splitter",s="Im Schlingendorntal suchen Käufer nach Singenden blauen Splittern. Die Venture Company erschwert es Crank Fizzlebub, rohe Singende Kristalle zu sammeln, also bietet er Euch für zehn Splitter aus Basiliskenhäuten einen Gewinnanteil an.",h="Im Schlingendorntal suchen Käufer nach Singenden blauen Splittern.",kw={"basilisken","crank fizzlebub","singende blaue splitter","singende kristalle","schlingendorntal","venture company","zul'kunda"},sec={{t="Eine lukrative Gelegenheit",b="Crank Fizzlebub hat Käufer für Singende Kristalle, die nur im Schlingendorntal vorkommen. Die Venture Company erschwert ihm das Sammeln roher Kristalle. Also sucht er einen anderen Weg, an sie zu gelangen. Basilisken fressen die Kristalle, und das Mineral wird Teil ihrer verhärteten Häute. Daraus könnt Ihr brauchbare Splitter gewinnen."},{t="Jagd an der Küste",b="Basilisken im ganzen Dschungel können Kristallfragmente liefern. Fizzlebub verweist Euch auf die friedfertigeren Exemplare an den nördlichen Küsten südlich von Zul'Kunda. Bringt ihm zehn Splitter, damit er mit seinen Käufern ins Geschäft kommen kann. Dann richtet er seine Aufmerksamkeit auf die Aktivitäten der Venture Company."}},faq={{q="Warum will Crank Fizzlebub Singing Crystal Shards haben?",a="Singende Kristalle gibt es nur im Schlingendorntal, und ausgewählte Käufer schätzen sie sehr. Crank Fizzlebub sagt, dass er sie verkaufen kann, und bietet Euch einen Gewinnanteil an.",al={"warum singende kristalle","crank fizzlebubs absicht","wozu dienen singende kristalle"}},{q="Warum kann Crank Fizzlebub die Kristalle nicht direkt sammeln?",a="Fizzlebub sagt, die Venture Company erschwere es ihm, selbst rohe Kristalle zu sammeln.",al={"warum basilisken töten","problem mit der venture company","warum kristalle nicht abbauen"}},{q="Warum haben Basilisken diese Kristalle?",a="Basilisken im Schlingendorntal fressen die Kristalle. Das Mineral wird Teil ihrer Häute und verleiht ihnen ihre harte, felsige Haut.",al={"hintergrund zu basiliskenkristallen","warum hinterlassen basilisken kristalle"}},{q="Wo schlägt Crank Fizzlebub vor, nach Basilisken zu suchen?",a="Fizzlebub sagt, jeder Basilisk könne Splitter liefern. Friedfertigere Exemplare leben an den nördlichen Küsten südlich von Zul'Kunda.",al={"wo splitter finden","fundort der basilisken","zul kunda basilisken"}},{q="Was geschieht nach der Abgabe der Splitter?",a="Wenn Ihr Fizzlebub zehn Splitter bringt, zahlt er Euch den versprochenen Gewinnanteil aus. Dann richtet er seine Aufmerksamkeit auf die Aktivitäten der Venture Company.",al={"was folgt nach singende blaue splitter","folgequest von singende blaue splitter"}}},fp="19,221,23.301.0,17.264.0,53.162.0,57.88.0,37.128.0,57.109.0,41.143.1"}
P.entries["quest:606"] = {n="Zitterhand Angst einjagen",s="An den Docks von Beutebucht schuldet Zitterhand Phillipe Seewolf MacKinley noch Geld vom Spiel der letzten Woche. MacKinley schickt Euch vor die Stadt, um Innereien von Elder Mistvale Gorillas zu holen und Phillipe damit zur Zahlung zu schrecken.",h="An den Docks von Beutebucht schuldet Zitterhand Phillipe Seewolf MacKinley noch Geld vom Spiel der letzten...",kw={"beutebucht","spielschulden","mistvale innereien","mistvale gorillas","zitterhand angst einjagen","seewolf mackinley","zitterhand phillipe","schlingendorntal"},sec={{t="Schulden eintreiben",b="Seewolf MacKinley will seine Spielschulden eintreiben, und viele Leute schulden ihm Geld. Zitterhand Phillipe ist als Erster dran. Er wartet an den Docks in Beutebucht und schuldet noch eine große Summe vom Spiel der letzten Woche. MacKinley schickt Euch vor die Stadt, um Elder Mistvale Gorillas zu jagen und reichlich Innereien zurückzubringen. Verschweigt, dass sie von Tieren stammen, damit Phillipe sich das Schlimmste ausmalt."},{t="Phillipes Reaktion",b="Zitterhand Phillipe schreckt vor den Innereien zurück und will nichts über ihre Herkunft wissen. Dann fragt er, ob Seewolf Euch geschickt hat."}},faq={{q="Wer ist Seewolf MacKinley?",a="Viele Leute haben Spielschulden bei Seewolf MacKinley. Er möchte Hilfe beim Eintreiben, angefangen bei Zitterhand Phillipe.",al={"wer ist mackinley","seewolf mackinley","wer vergibt zitterhand angst einjagen"}},{q="Warum will MacKinley Zitterhand Phillipe Angst einjagen?",a="Phillipe schuldet MacKinley noch eine große Summe vom Spiel der letzten Woche. MacKinley hofft, dass ein Schrecken ihn zur Zahlung bewegt.",al={"warum zitterhand erschrecken","zitterhand phillipe schulden","warum phillipe ins visier nehmen"}},{q="Welche Kreaturen liefern die Innereien?",a="MacKinley sagt, die Innereien stammen von Elder Mistvale Gorillas vor der Stadt.",al={"woher stammen die innereien","mistvale innereien herkunft","was für innereien töten"}},{q="Wo ist Zitterhand Phillipe zu finden?",a="Zitterhand Phillipe ist an den Docks in Beutebucht zu finden.",al={"wo ist zitterhand phillipe","zitterhand aufenthaltsort","zitterhand phillipe finden"}},{q="Was sollt Ihr Phillipe über die Innereien sagen?",a="Sagt nichts darüber, woher die Innereien stammen. MacKinley will, dass Phillipe sich das Schlimmste ausmalt.",al={"zitterhand die herkunft der innereien verraten"}}},fp="13,203,17.353.0,19.134.1,28.131.0,50.108.0,35.74.0,36.60.0,48.93.0"}
P.entries["quest:6061"] = {n="Die Zähmung der Bestie",s="Im Dorf der Bluthufe beginnt Yaw Scharfmähne die Ausbildung eines jungen Taurenjägers mit „Die Zähmung der Bestie“. Die erste Prüfung führt nach Mulgore, wo der Jäger einen ausgewachsenen Ebenenschreiter zähmt und ein Band mit den Geschöpfen der Erdenmutter knüpft.",h="Im Dorf der Bluthufe beginnt Yaw Scharfmähne die Ausbildung eines jungen Taurenjägers mit „Die Zähmung der...",kw={"dorf der bluthufe","erdenmutter","jägerquest","mulgore","ebenenschreiter","zähmen","zähmerrute","yaw scharfmähne"},ang={["class:Hunter"]="Als Jäger beginnt Ihr unter der Führung der Erdenmutter zu lernen, ein Band mit Tieren zu knüpfen.",["race:Tauren"]="Als Tauren erbt Ihr Mulgores überlieferte Jagdtradition, in der das Zähmen die Verbindung zwischen Jäger und Natur stärkt."},sec={{t="Ein heiliges Band zur Wildnis",b="Taurenjäger suchen mehr als Fleisch und Felle. Ihre überlieferten Bräuche lehren, dass Begegnungen mit Mulgores wilden Geschöpfen sie der Erdenmutter näherbringen können. Ein gezähmter Gefährte mag einst ein Widersacher gewesen sein. Nun wirken Tier und Jäger als Partner im natürlichen Gleichgewicht der Ebenen zusammen."},{t="Die erste Prüfung",b="Yaw Scharfmähne beginnt die Ausbildung eines Jägers mit den Ebenenschreitern, die Mulgores Grasländer durchstreifen. Mit einer verzauberten Zähmerrute tritt der Jäger einem ausgewachsenen Ebenenschreiter entgegen und besänftigt dessen wilde Instinkte, um sein Vertrauen zu gewinnen. Diese erste Prüfung stellt die Entschlossenheit des Jägers auf die Probe und bereitet ihn auf anspruchsvollere Bestien vor."}},faq={{q="Welchen Zweck hat diese Prüfung?",a="Dies ist die erste praktische Prüfung für einen jungen Taurenjäger, der lernt, ein Band mit einem Tier zu knüpfen. Die Zähmerrute besänftigt einen ausgewachsenen Ebenenschreiter und vermittelt die Grundlagen einer spirituellen Verbindung und der Zusammenarbeit mit Bestien.",al={"warum einen ebenenschreiter zähmen","zweck der quest","zweck der taurenbegleiterquest"}},{q="Wer vergibt diese Quest und wo ist diese Person zu finden?",a="Yaw Scharfmähne, der Jägerlehrer, vergibt die Prüfung im Dorf der Bluthufe, im Herzen Mulgores.",al={"wer vergibt die quest","standort des questgebers","yaw scharfmähne standort"}},{q="Behalte ich den ausgewachsenen Ebenenschreiter dauerhaft?",a="Nein. Die Bestien in Yaw Scharfmähnes ersten drei Prüfungen sind vorübergehende Übungspartner. Nachdem Ihr die gesamte Ausbildung abgeschlossen und das Zähmen von Bestien gemeistert habt, könnt Ihr einen geeigneten Gefährten dauerhaft zähmen.",al={"ist dieser begleiter dauerhaft","ebenenschreiter behalten","bestie nach der quest behalten"}},{q="Warum betrachten Tauren das Zähmen von Bestien als spirituellen Akt?",a="Die Tradition der Tauren lehrt, dass Jäger durch die Begegnung mit wilden Geschöpfen und deren Bezwingen ihre Geister aufnehmen und sich mit der Natur verbinden können. Eine Bestie zu zähmen zeigt Respekt und Verbundenheit mit den Geschöpfen der Erdenmutter.",al={"hintergrund zu taurenbegleitern","hintergrund zu erdenmutter und zähmung","warum tauren bestien zähmen"}},{q="Wo sind ausgewachsene Ebenenschreiter zu finden?",a="Ausgewachsene Ebenenschreiter durchstreifen die Täler und Savannen rund um das Dorf der Bluthufe in Mulgore.",al={"wo sind ebenenschreiter","ebenenschreiter standort","ausgewachsenen ebenenschreiter finden"}},{q="Was folgt auf diese Quest?",a="Wenn Ihr die Zähmerrute zu Yaw Scharfmähne zurückbringt, schickt Euch die nächste Prüfung los, um einen stalker und dann einen aggressive swoop zu zähmen. Nach diesen Prüfungen lernt Ihr, Bestien dauerhaft auszubilden.",al={"was kommt als nächstes","questreihe nach dieser quest","nächster schritt beim zähmen"}}},fx={fd2667bc={q="Warum möchte Yaw Scharfmähne, dass ich einen Ebenenschreiter zähme?",a="Yaw Scharfmähne führt Euch durch die heiligen Traditionen des Tauren-Jägers. Für Tauren ist das Besiegen und Zähmen wilder Tiere eine spirituelle Disziplin, die den Jäger näher zur Erdenmutter bringt und ihn mit der natürlichen Welt in Einklang bringt. Er beginnt Euer Training mit den flinken erwachsenen Ebenenschreitern von Mulgore, damit Ihr die Geduld und den spirituellen Fokus meistern könnt, die nötig sind, bevor Ihr eine dauerhafte Bindung mit einem Begleiter eingeht.",al={"warum ebenenschreiter zähmen","yaw scharfmähne beweggrund","warum erwachsener ebenenschreiter"}},fe0439d7={q="Warum lässt Yaw Scharfmähne mich diese Prüfung ablegen, anstatt sie selbst zu machen?",a="Dies ist ein persönlicher Ritus des Übergangs, den jeder angehende Jäger selbst durchlaufen muss. Yaw Scharfmähne ist ein erfahrener Mentor, der damit betraut ist, uralte Bräuche zu lehren, nicht die Arbeit für Euch zu erledigen. Das Zähmen einer wilden Kreatur erfordert, dass Ihr Eure eigene spirituelle Verbindung zur Natur schmiedet und Euch der Präsenz der Erdenmutter öffnet. Kein Ältester oder Wächter kann diese Bindung in Eurem Namen aufbauen.",al={"warum schickt er mich","warum yaw scharfmähne mich braucht","warum muss ich das tier zähmen"}}},fp="16,235,27.287.0,14.313.0,34.202.0,48.92.0,45.199.0,52.210.0,39.87.0,28.177.0"}
P.entries["quest:6062"] = {n="Die Zähmung der Bestie",s="In Klingenhügel stellt Die Zähmung der Bestie junge Jäger der Horde erstmals mit einer Zähmerrute auf die Probe. Thotar schickt sie gegen einen wilden, bösartigen graugesprenkelten Eber.",h="In Klingenhügel stellt Die Zähmung der Bestie junge Jäger der Horde erstmals mit einer Zähmerrute auf die...",kw={"bösartiger graugesprenkelter eber","durotar","jägerquest","begleiter zähmen","klingenhügel","zähmerrute","thotar"},ang={["class:Hunter"]="Als Jäger lernt Ihr die Bindung zu tierischen Gefährten kennen, die einen Meister der Bestien auszeichnet.",["race:Orc"]="Als Orc beweist Ihr Willensstärke, indem Ihr eine Bestie in der rauen Wildnis Durotars, Eurer neuen Heimat, beherrscht.",["race:Troll"]="Als Jäger der Dunkelspeertrolle stimmt Ihr Euren Geist auf Kalimdors raue Tierwelt ein und führt die uralten Pirschtraditionen Eures Volkes fort."},sec={{t="Die Bewährungsprobe eines Jägers",b="In Durotar müssen Jäger der Orcs und Dunkelspeertrolle lernen, die Wildnis zu beherrschen und in ihr zu überleben. Thotar gibt jungen Jägern eine verzauberte Zähmerrute und schickt sie gegen einen wilden Eber. Sie müssen die Bestie unterwerfen, ohne sie zu töten, und sie dann zu einem treuen Verbündeten machen."},{t="Die Eber von Durotar",b="Bösartige graugesprenkelte Eber durchstreifen das trockene Gestrüpp rund um Klingenhügel. Ihre Stärke und ihr Temperament machen sie zu einer passenden ersten Prüfung für junge Jäger. Die Rute kann einen heranstürmenden Eber unterwerfen, doch ihr Einsatz erfordert Geduld und Entschlossenheit. Jeder Fährtenleser der Horde braucht diese Eigenschaften."}},faq={{q="Welchen Zweck hat diese Prüfung?",a="Die Prüfung gibt jungen Jägern in Durotar ihre erste praktische Lektion im Umgang mit einer Zähmerrute. Sie lernen, ein wildes Tier zu unterwerfen, statt es zu töten.",al={"warum diese quest machen","grund für die eberzähmungsquest","zweck der zähmung der bestie"}},{q="Wer vergibt diese Quest?",a="Thotar, der Jägerlehrer in Klingenhügel, gibt Euch diese Prüfung, nachdem Ihr Eure grundlegenden Überlebensfähigkeiten in ganz Durotar bewiesen habt.",al={"questgeber","wer vergibt die zähmung der bestie","wo gibt es die eberquest"}},{q="Wo findet man die bösartigen graugesprenkelten Eber?",a="Bösartige graugesprenkelte Eber durchstreifen das trockene Buschland vor den Palisaden von Klingenhügel im Zentrum Durotars.",al={"fundort der eber","wo ist der bösartige graugesprenkelte eber","wo eber finden"}},{q="Behaltet Ihr den Eber nach dieser Quest dauerhaft?",a="Nein. Der Eber, den Ihr zähmt, dient der Übung und verlässt Euch, wenn Ihr zu Thotar zurückkehrt. Ihr setzt Eure Ausbildung mit anderen Kreaturen fort, bevor Ihr eine dauerhafte Bindung eingeht.",al={"behalte ich den eber","ist der eber mein dauerhafter begleiter","bösartigen graugesprenkelten eber behalten"}},{q="Was folgt auf diese Aufgabe?",a="Nachdem Ihr zu Thotar zurückgekehrt seid, prüft er Eure Kontrolle über andere tödliche Raubtiere Durotars, darunter surf crawlers und armored scorpid beasts.",al={"nächste quest","was folgt nach der eberzähmung","nächster schritt der zähmungsquestreihe"}},{q="Warum eine Zähmerrute statt reinen Instinkts verwenden?",a="Angehende Jäger haben noch nicht die geistige und körperliche Disziplin erlangt, um sich unmittelbar mit Bestien zu verbinden. Die verzauberte Rute richtet ihren Willen auf den Geist einer wilden Bestie, bis sie diese Kunst beherrschen.",al={"warum eine zähmerrute","was bewirkt die rute","hintergrund der zähmerrute"}}},fx={["97dfd1bd"]={q="Warum möchte Thotar, dass Ihr einen gescheckten Schreckenseber zähmt?",a="Thotar bereitet Euch darauf vor, ein wahrer Jäger der Horde zu werden. In seinen Augen ist es für Eure Disziplin wesentlich, Autorität über die Natur auszuüben und die innewohnende Stärke wilder Tiere zu nutzen. Er beginnt mit einem lokalen gescheckten Schreckenseber, damit Ihr Eure Entschlossenheit beweisen und lernen könnt, an der Seite eines Begleiters zu kämpfen, bevor Ihr zu wilderen Raubtieren übergeht.",al={"thotar beweggrund","warum eber bei thotar zähmen","warum schickt thotar euch"}},["9ea8907b"]={q="Was sind gescheckte Schreckenseber?",a="Gescheckte Schreckenseber sind robuste, aggressive Schweine, die in den trockenen Ebenen von Durotar heimisch sind. Bekannt für ihre dicken Häute, sturen Temperamente und bösartigen Stoßzähne, durchstreifen sie die Felsen und Schluchten in der Nähe von Klingenhügel auf der Suche nach Nahrung. Ihre sture Natur macht sie zu robusten ersten Partnern für einen angehenden Jäger, der die Kunst der Tierherrschaft erlernt.",al={"gescheckter schreckenseber","was ist ein gescheckter schreckenseber","gescheckte eber in durotar"}},["81608777"]={q="Warum schickt Thotar Euch auf diese Prüfung, anstatt sie selbst zu erledigen?",a="Dies ist keine Besorgung oder ein Notfall für die Verteidiger von Klingenhügel; es ist Eure persönliche Initiation als Jäger. Die Kontrolle über ein Tier zu erlangen erfordert direkte Willenskraft, Übung und persönliche Entschlossenheit, die kein Mentor oder Kundschafter in Eurem Namen erbringen kann. Thotars Rolle ist es, Euer Training zu leiten, aber die Wildnis zu meistern ist eine Last, die Ihr alleine tragen müsst.",al={"warum ich thotar","warum muss ich ihn zähmen","warum zähmt thotar ihn nicht"}}},fp="16,149,26.265.0,20.252.0,34.148.0,21.121.0,39.95.0,50.146.0,27.138.0,46.193.0"}
P.entries["quest:6063"] = {n="Die Zähmung der Bestie",s="In Dolanaar stellt sich ein junger Nachtelfenjäger mit einem wilden Webwood Lurker der ersten Prüfung von Die Zähmung der Bestie. Dazalar leiht ihm eine verzauberte Zähmerrute, und der Jäger muss durch ein Band zur Natur das Vertrauen der Spinne gewinnen.",h="In Dolanaar stellt sich ein junger Nachtelfenjäger mit einem wilden Webwood Lurker der ersten Prüfung von Die...",kw={"dazalar","dolanaar","tiergefährte des jägers","kaldorei","zähmen","zähmerrute","teldrassil","webwood lurker"},ang={["class:Hunter"]="Als Jäger werdet Ihr vom einsamen Bogenschützen zum Partner der Wildnis, verbunden mit den Tieren des Waldes.",["race:NightElf"]="Als Nachtelf lernt Ihr, durch Zwiesprache und Ehrfurcht vor der Natur zu zähmen, statt durch Unterwerfung."},sec={{t="Ein heiliges Band",b="Für die Kaldorei verlangt die Jagd mehr als Geschick beim Aufspüren von Beute oder beim Überleben in der Wildnis. Sie verbindet einen Jäger mit der Natur, die jeden Sterblichen überragt. Tiere sind eigenständige Geschöpfe, keine Werkzeuge, die dem Willen eines Jägers unterworfen werden sollen. Dazalar lehrt angehende Jäger, ihnen mit Respekt zu begegnen. Bevor ein Jäger einen lebenslangen Tiergefährten gewinnt, muss er die heimische Tierwelt durch uralte Techniken meistern, niemals durch rohe Gewalt."},{t="Die erste Prüfung",b="Riesige Spinnentiere befallen das Geäst von Teldrassil, deshalb gibt Dazalar dem Jäger eine Zähmerrute. In schattigen Dickichten sucht der Jäger einen Webwood Lurker und stellt sich den Angriffen der giftigen Spinne. Um sie zu erreichen, muss der Jäger mit Einfühlungsvermögen reagieren. Ein kurzes geistiges Band beweist, dass der Jäger mit den unheimlichen, huschenden Raubtieren des Weltbaums Zwiesprache halten kann."}},faq={{q="Welchen Zweck hat diese Quest?",a="Mit dieser Prüfung beginnt die Ausbildung der Nachtelfenjäger im Zähmen von Tiergefährten. Der Einsatz einer Zähmerrute an heimischen Wildtieren prüft die Ruhe des Jägers und sein Geschick bei der Zwiesprache mit wilden Raubtieren.",al={"warum diese quest machen","zweck der tiergefährtenquest","was bringt die zähmung der bestie"}},{q="Wer vergibt diese Quest?",a="Dazalar, ein Jägerlehrer in Dolanaar auf Teldrassil, bietet die Prüfung jungen Nachtelfenjägern mit ausreichender Erfahrung an.",al={"questgeber","wo gibt es die zähmquest","wer startet die zähmung der bestie"}},{q="Welches Geschöpf muss in dieser Prüfung gezähmt werden?",a="Ihr müsst einen Webwood Lurker zähmen, eine giftige Riesenspinne aus den wilden Dickichten und Wäldern außerhalb von Dolanaar.",al={"welchen tiergefährten zähmen","webwood lurker als ziel","welches wildtier zähmen"}},{q="Behalte ich den Webwood Lurker dauerhaft?",a="Nein. Der Webwood Lurker ist ein vorübergehender Gefährte, mit dem Ihr die Grundlagen des Umgangs mit Wildtieren übt. Wenn Ihr zu Dazalar zurückkehrt, endet das Band, während Ihr Euch auf die nächste Prüfung vorbereitet.",al={"spinne behalten","ist der webwood lurker dauerhaft","tiergefährten behalten"}},{q="Warum prüfen Nachtelfen Jäger zuerst mit Spinnen?",a="Webwood Lurker sind räuberisch und aggressiv und stellen die Besonnenheit eines angehenden Jägers auf die Probe. Ein Spinnentier zu meistern zeigt, dass ein Jäger sein Bewusstsein mit feindseligen Formen der Natur verbinden kann.",al={"warum webwood lurker","warum eine spinne zähmen","hintergrund zum spinnenzähmen"}},{q="Was folgt nach der Rückkehr zu Dazalar?",a="Nach Eurer Rückkehr zu Dazalar schickt er Euch los, um Euer Band mit einem Nightsaber Stalker und einem Strigid Screecher zu erproben, beide auf Teldrassil heimisch. Dann gewährt er Euch dauerhafte Zähmfähigkeiten.",al={"was kommt danach","nach der zähmung der bestie","nächste prüfung"}}},fx={["641cd576"]={q="Warum möchte Dazalar, dass dies erledigt wird?",a="Dazalar glaubt, dass die Natur keine Kraft ist, die dem Willen eines Sterblichen unterworfen werden kann, sondern eine Macht, die tiefe Ehrfurcht und Respekt erfordert. Bevor er Euch die beständige Kunst des Zähmens wilder Tiere anvertraut, muss er sicherstellen, dass Ihr diese heilige Pflicht begreift. Die Prüfung testet, ob Ihr die Geduld und Demut besitzt, die von einem wahren Kaldorei-Jäger verlangt wird, anstatt wilde Kreaturen wie bloße Werkzeuge zu behandeln.",al={"warum prüft dazalar euch","dazalar beweggrund","zweck der dazalar prüfung"}},a645c3ca={q="Warum schickt Dazalar Euch, anstatt dies selbst zu erledigen?",a="Dies ist ein wesentlicher Ritus des Übergangs für Euer eigenes Wachstum als Jäger. Dazalar hat die Wildnis bereits gemeistert; seine Rolle ist es, Euren Fortschritt zu leiten und zu bewerten. Die Prüfung erfordert, dass Ihr aus eigenem Willen eine Bindung schmiedet und beweist, dass Ihr die notwendige Disziplin erlernt habt, um an der Seite der Kreaturen von Teldrassil als vertrauenswürdiger Wächter zu wandeln.",al={"warum muss ich die spinne zähmen","warum ich dazalar","warum macht dazalar es nicht selbst"}}},fp="16,220,13.403.0,15.339.0,34.176.0,21.124.0,42.106.0,41.161.0,51.182.0,38.180.1"}
P.entries["quest:6064"] = {n="Die Zähmung der Bestie",s="In Dun Morogh stellt Die Zähmung der Bestie einen Jäger vor die erste Prüfung im Umgang mit Tiergefährten. In Kharanos leitet Grif Wildherz junge Fährtenleser an, mit einer verzauberten Zähmerrute einen Großen Felseber zu besänftigen.",h="In Dun Morogh stellt Die Zähmung der Bestie einen Jäger vor die erste Prüfung im Umgang mit Tiergefährten.",kw={"bestie","eber","felseber","dun morogh","grif wildherz","jäger","kharanos","zähmung","zähmerrute"},ang={["class:Hunter"]="Als Jäger werdet Ihr vom unerfahrenen Schützen zum Meister der Tiere und beginnt die Prüfungen, die Euch dauerhafte Tiergefährten ermöglichen.",["race:Dwarf"]="Als Zwerg folgt Ihr den Gebirgsjägern von Eisenschmiede, die Tiere verehren, die der beißenden Kälte von Dun Morogh trotzen können. Mit dem widerstandsfähigen Felseber zu beginnen, spiegelt die zwergische Achtung vor Zähigkeit und Ausdauer wider."},sec={{t="Der Gefährte eines Jägers",b="Zwergische Gebirgsjäger und Fährtenleser verlassen sich in der Wildnis auf Gewehre, Fallen und ihren Verstand. Doch die Berufung eines Jägers ist es, einen lebenslangen Bund mit einem wilden Tier zu schließen. Vor der Brauerei Donnerbräu in Kharanos wacht Grif Wildherz über diesen Ritus. Er prüft Neulinge an mehreren in Dun Morogh heimischen Tierarten, bevor er sie auffordert, ein Tier dauerhaft an sich zu binden."},{t="Der Felseber",b="Ein Großer Felseber ist die erste Prüfung für einen jungen Fährtenleser. Diese dickhäutigen Schweine durchstreifen die verschneiten Ausläufer von Dun Morogh, wo ihr borstiges Fell und ihr zähes Fleisch sie störrisch und wild machen. Grif stellt eine verzauberte Zähmerrute bereit. Der Jäger stellt sich dem Ansturm des Ebers und versucht, dessen Wut zu besänftigen, bis er sich seinem Befehl unterwirft."}},faq={{q="Wer bietet diese Prüfung an?",a="Grif Wildherz bietet die Prüfung vor der Brauerei Donnerbräu in Kharanos an, wo er zwergische Jäger ausbildet.",al={"questgeber","wer startet die zähmung der bestie","grif wildherz standort"}},{q="Warum zähme ich zuerst einen Großen Felseber?",a="Große Felseber sind kräftig und störrisch, kommen aber auf den verschneiten Bergrücken von Dun Morogh in großer Zahl vor. Einen zu zähmen, gibt Euch erstmals Gelegenheit, einem angriffslustigen, dickhäutigen Tier mit Ruhe Befehle zu erteilen.",al={"warum felseber","welches tier zähmen","eber zähmen"}},{q="Darf ich diesen Eber für immer behalten?",a="Nein. Der mit der Zähmerrute geschlossene Bund ist vorübergehend. Ihr könnt dem Eber Befehle erteilen, dann die Rute zurückgeben und Euch an anderen Tierarten versuchen.",al={"ist dieser eber dauerhaft","felseber behalten","tiergefährten behalten"}},{q="Wo finde ich Große Felseber?",a="Große Felseber durchstreifen die offenen Schneefelder und Kiefernhainе rund um Kharanos sowie die gefrorenen Hänge von Dun Morogh.",al={"eber fundorte","wo sind große felseber","großer felseber erscheinungsort"}},{q="Was folgt nach der Zähmung des Felsebers?",a="Wenn Ihr zu Grif Wildherz zurückkehrt, ist die erste Lektion abgeschlossen und die zweite Prüfung beginnt: einen Snow Leopard zu zähmen.",al={"nächste prüfung","was folgt nach dieser quest","jäger questreihe fortsetzung"}},{q="Wie funktioniert die Zähmerrute?",a="Jägerlehrer stellen eine verzauberte Zähmerrute bereit, die Neulingen hilft, ihren Willen zu bündeln und wilde Instinkte zu besänftigen. Dafür braucht es weder eine fortgeschrittene magische Ausbildung noch lebenslange Erfahrung im Flüstern mit Tieren.",al={"zähmerrute hintergrund","was ist die rute","wie zähmen"}}},fx={["49cdd252"]={q="Warum möchte Grif Wildherz, dass Ihr ein Tier zähmt?",a="Grif Wildherz trainiert Euch in den Grundlagen, ein wahrer Zwergenjäger zu sein. In seinen Augen ist es genauso wichtig zu wissen, wie man eine Bindung zu einem tierischen Begleiter aufbaut und ihn befehligt, wie die Pflege Eurer Waffe. Anstatt Euch ein Haustier zu geben, glaubt er, dass der einzig richtige Weg zu lernen die praktische Erfahrung in der Wildnis ist, bei der Ihr Eure Geduld und Meisterschaft gegen verschiedene Arten lokaler Kreaturen testet, bevor Ihr Euch für einen dauerhaften Begleiter entscheidet.",al={"grif wildherz beweggrund","warum ein tier zähmen","grif wildherz training grund"}}},fp="16,210,20.345.0,13.318.0,22.112.0,38.179.0,35.122.0,34.113.0,38.115.0,29.192.0"}
P.entries["quest:6065"] = {n="Der Weg des Jägers",s="In Mulgore schickt Der Weg des Jägers junge Tauren zur weiterführenden Ausbildung ins Dorf der Bluthufe. Dort suchen sie Yaw Scharfmähne auf und beginnen die Prüfungen im Zähmen wilder Bestien und im Aufbau einer Bindung zu ihnen.",h="In Mulgore schickt Der Weg des Jägers junge Tauren zur weiterführenden Ausbildung ins Dorf der Bluthufe.",kw={"bestie","dorf der bluthufe","camp narache","weg des jägers","mulgore","begleiterquest","zähmen","yaw scharfmähne"},ang={["class:Hunter"]="Als Jäger macht Ihr Euren ersten Schritt vom Bogenschützen oder Gewehrschützen zum Meister der Bestien, mit einem treuen Begleiter an Eurer Seite.",["faction:Horde"]="Als Jäger der Horde verlasst Ihr Euch auf wilde Bestien aus den Grenzgebieten, um die Front zu verteidigen und in Kalimdors rauer Wildnis Fährten zu lesen.",["race:Tauren"]="Als Angehöriger der Shu'halo lernt Ihr, wilde Bestien zu zähmen, als Ausdruck der Ehrfurcht vor der Natur und der Schöpfung der Earth Mother."},sec={{t="Ein Übergangsritus",b="Bei den Shu'halo ist die Jagd heilig. Ein Jäger lernt das Gleichgewicht der Natur kennen, ehrt die Geister der Ebenen und achtet die Tiere, die die Stämme ernähren. Nachdem junge Jäger bewiesen haben, dass sie in der Wildnis überleben und mit Bogen oder Gewehr umgehen können, schicken ihre Ältesten sie zu erfahrenen Lehrmeistern. Die Reise markiert in der Kultur der Tauren ihren Schritt über das einsame Fährtenlesen hinaus und hin zum Erwachsensein."},{t="Zum Dorf der Bluthufe",b="Die Straße zum Dorf der Bluthufe führt durch Mulg ores Grasland und erreicht die Siedlung am Stonebullsee. Dort unterrichtet Yaw Scharfmähne Jäger über die einheimischen Bestien. Die Begegnung mit ihm zeigt, dass ein Jäger für die Prüfungen im Zähmen von Bestien bereit ist. Sie lernen, mit Raubtieren Zwiesprache zu halten und sie auch zu jagen."}},faq={{q="Welchem Zweck dient der Weg des Jägers?",a="Der Weg des Jägers schickt unerfahrene Taurenjäger ins Dorf der Bluthufe, um ihre Prüfungen im Zähmen von Bestien zu beginnen. Dort sprechen sie mit Yaw Scharfmähne, der die Rituale zur Bindung an einen tierischen Begleiter leitet.",al={"warum diese quest erhalten","zweck des wegs des jägers","start der jägerbegleiterquest"}},{q="Wer schickt Euch auf diese Quest?",a="Jägerlehrer der Tauren schicken angehende Jäger los, nachdem diese die Grundlagen des Überlebens und der Schießkunst gemeistert haben. Kary Thunderhorn in Donnerfels ist einer dieser Lehrer.",al={"wer vergibt den weg des jägers","jägerlehrerquest"}},{q="Wer ist Yaw Scharfmähne?",a="Yaw Scharfmähne ist ein angesehener Jägerlehrer der Tauren im Dorf der Bluthufe. Er lehrt junge Jäger, sich Mulg ores wilden Bestien zu nähern, sie zu beruhigen und zu zähmen.",al={"wer ist scharfmähne","yaw scharfmähnes rolle"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Nachdem Ihr mit Yaw Scharfmähne gesprochen habt, beginnt Ihr die Prüfungen von Taming the Beast. Ihr zieht mit einer Zähmerrute in die Wildnis und besänftigt mehrere einheimische Kreaturen, bevor Ihr das Recht erlangt, einen dauerhaften Begleiter auszubilden.",al={"what comes next","nächste quest nach dem weg des jägers"}},{q="Warum gehen Taurenjäger Bindungen mit Bestien ein, statt sie nur zu jagen?",a="Nach der Tradition der Tauren sind Bestien verwandte Geister der Earth Mother. Ein Tier, mit dem eine Bindung besteht, ist ein Begleiter und Jagdgefährte, verbunden durch gegenseitigen Respekt und das gemeinsame Überleben auf den Ebenen.",al={"hintergrund der taurenbegleiter","warum tauren begleiter zähmen"}},{q="Können Jäger anderer Völker diese bestimmte Quest annehmen?",a="Dieser Weg ist für Taurenjäger bestimmt, die in Mulgore ausgebildet werden. Andere Völker der Horde, etwa Orcs und Trolle, erhalten ähnliche Ausbildungsanweisungen in ihren Heimatgebieten in Durotar.",al={"nur für tauren","können orcs den weg des jägers für tauren machen"}}},fx={a380c02c={q="Warum schickt Euer Ausbilder Euch zu Yaw Scharfmähne?",a="Euer Ausbilder erkennt, dass Ihr in der Wildnis erfahren genug geworden seid, um den nächsten entscheidenden Schritt im Leben eines Jägers zu machen: die Bindung zu einem tierischen Begleiter und dessen Ausbildung. Sie schicken Euch zu Yaw Scharfmähne im Dorf der Bluthufe, weil er über das spezialisierte Wissen und die uralten Traditionen verfügt, die erforderlich sind, um Euch durch die Prüfungen des Tierzähmens zu führen.",al={"warum zu yaw scharfmähne","ausbilder beweggrund pfad des jägers","warum nach bloodhoof schicken"}}},fp="17,183,17.365.0,29.299.0,41.203.0,28.158.0,21.148.0,41.210.0,68.182.0,52.170.0"}
P.entries["quest:6068"] = {n="Der Weg des Jägers",s="In Durotar führt der Weg des Jägers junge Orc- und Trolljäger nach Klingenhügel. Dort lehrt Thotar sie, wilde Raubtiere an sich zu binden.",h="In Durotar führt der Weg des Jägers junge Orc- und Trolljäger nach Klingenhügel.",kw={"durotar","jägerlehrer","weg des jägers","begleiterquest","klingenhügel","tier zähmen","thotar"},ang={["class:Hunter"]="Als Jäger geht Ihr vom einsamen Kampf dazu über, das Befehligen von Tieren zu erlernen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr ihren Spähern und Fährtenlesern, Durotars Raubtiere zu zähmen und das raue Land zum Vorteil Eures Volkes zu nutzen.",["race:Orc"]="Als Orcjäger folgt Ihr einer Tradition, die mit den Wolfsreitern von Draenor verbunden ist, wenn Ihr einen wilden Begleiter an Euch bindet.",["race:Troll"]="Als Dunkelspeerjäger lernt Ihr, heimische Raptoren und Eber zu zähmen, um in Durotars gefährlicher Wildnis Fuß zu fassen."},sec={{t="Das Erwachen eines Jägers",b="In Durotar lernen junge Jäger, Beute mit Bogen und List zu verfolgen. Fährten durch rote Lehmschluchten und karges Buschland lehren sie Geduld. Um die Jagdweise der Horde zu meistern, müssen sie auch lernen, ein Band mit wilden Tieren zu knüpfen. Wenn Klassenlehrer einen Schüler für bereit halten, schicken sie ihn nach Klingenhügel."},{t="Der Meister in Klingenhügel",b="In Klingenhügel lehrt Thotar junge Jäger, Durotars wilde Tiere zu unterwerfen, ohne ihren Geist zu brechen. Seine Lektionen sind der Anfang ihres Weges, die Wildnis mit einem treuen Begleiter zu durchstreifen."}},faq={{q="Welchen Zweck hat der Weg des Jägers?",a="Junge Orc- und Trolljäger gehen nach Klingenhügel, um zu lernen, wie man Tiere zähmt.",al={"warum den weg des jägers machen","zweck der quest der weg des jägers","was bewirkt diese quest"}},{q="Wer ist Thotar?",a="Thotar ist ein erfahrener Jäger in Klingenhügel, der junge Fährtenleser der Horde lehrt, wilde Tiere an sich zu binden und zu befehligen.",al={"thotar wer ist er","wer ist thotar","thotar klingenhügel"}},{q="Warum können junge Jäger nicht sofort Begleiter zähmen?",a="Junge Jäger brauchen Disziplin, Geduld und eine besondere Ausbildung, um gefährliche Raubtiere zu kontrollieren. Ohne grundlegende Überlebensfertigkeiten laufen sie Gefahr, schwer verletzt oder getötet zu werden.",al={"warum kein begleiter auf stufe eins","warum müssen jäger auf begleiter warten","wann bekommen jäger begleiter"}},{q="Welche Völker stellen sich dieser besonderen Prüfung?",a="Orcs und Dunkelspeertrolle in Durotar stellen sich dieser Prüfung, während Taurenjäger in Mulgore eine ähnliche bestehen müssen.",al={"wer bekommt diese quest","ist das nur für orcs und trolle","welche völker machen das"}},{q="Was geschieht, nachdem Ihr Euch bei Thotar gemeldet habt?",a="Nachdem Ihr Euch bei Thotar gemeldet habt, schickt er Euch los, um in ganz Durotar heimische Raubtiere aufzuspüren und zu unterwerfen. Dort beweist Ihr Euer Geschick beim Zähmen von Tieren.",al={"what comes next","nach dem weg des jägers","nächste quest nach thotar"}},{q="Wo findet diese Ausbildung statt?",a="Die Ausbildung konzentriert sich auf Klingenhügel, die wichtigste Siedlung im Zentrum Durotars, zwischen dem Tal der Prüfungen und Orgrimmar.",al={"wo ist klingenhügel","thotar standort","wohin gehen"}}},fx={df5b309b={q="Warum schickt der Ausbilder Euch zu Thotar?",a="Eure anfänglichen Klassenausbilder erkennen, dass Ihr die grundlegenden Fähigkeiten in Bogenschießen und Überleben entwickelt habt, die notwendig sind, um größere Verantwortungen zu übernehmen. Um als wahrer Jäger der Horde voranzukommen, müsst Ihr eine Bindung mit einem tierischen Begleiter eingehen, und Thotar in Klingenhügel ist der Meister, der damit betraut ist, vielversprechende Orcs und Trolle durch die heiligen Prüfungen des Zähmens zu führen.",al={"warum zu thotar","warum thotar","ausbilder grund thotar"}}},fp="17,129,20.299.0,24.193.0,41.82.0,14.111.0,46.158.0,42.110.0,39.139.0,36.119.0"}
P.entries["quest:6069"] = {n="The Hunter's Path",s="Thotar in Klingenhügel kann Euch helfen, einen tierischen Begleiter zu gewinnen. Ihr werdet ausgesandt, um mit ihm zu sprechen.",h="Thotar in Klingenhügel kann Euch helfen, einen tierischen Begleiter zu gewinnen.",kw={"wildtier","gefährte","jäger","pfad des jägers","begleiter","klingenhügel","thotar"},ang={["class:Hunter"]="Als Jäger hält man Euch für geschickt genug, mit einem Wildtier umzugehen und es zu Eurem Begleiter auszubilden."},sec={{t="Ein tierischer Begleiter",b="Ein Ausbilder erkennt Euer Geschick im Umgang mit Wildtieren und schickt Euch zu Thotar in Klingenhügel. Er kann Euch dabei helfen, einen eigenen Begleiter zu gewinnen."}},faq={{q="Mit wem soll ich sprechen?",a="Sprecht mit Thotar in Klingenhügel.",al={"mit wem sprechen","wohin gehen","thotar quest"}},{q="Wobei kann Thotar mir helfen?",a="Thotar kann Euch dabei helfen, einen eigenen Begleiter zu gewinnen.",al={"was macht thotar","begleiter bekommen","jägerbegleiter"}},{q="Warum werde ich zu Thotar geschickt?",a="Ein Ausbilder glaubt, dass Ihr geschickt genug seid, mit einem Wildtier umzugehen und es als Begleiter auszubilden.",al={"warum thotar","wozu das ganze","pfad des jägers"}}},fp="17,100,17.138.0,24.32.0,29.54.0,30.85.0"}
P.entries["quest:607"] = {n="Rückkehr zu MacKinley",s="Ihr bringt Phillipes Beutel zu Seewolf MacKinley, dem noch Geld geschuldet wird. Phillipe sagt, er habe die ganze Zeit zahlen wollen, und bittet Euch um Nachsicht.",h="Ihr bringt Phillipes Beutel zu Seewolf MacKinley, dem noch Geld geschuldet wird.",kw={"schulden","mackinley","seewolf","zitterhand phillipe","schlingendorntal"},sec={{t="Zitterhands Bitte",b="Zitterhand Phillipe überreicht Euch einen Beutel mit der Bezahlung für Seewolf MacKinley. Er schwört, dass er die Schulden immer zurückzahlen wollte. Phillipe sagt, er sei ein wenig betrunken gewesen und habe den Weg verloren. Er glaubt, MacKinley werde das verstehen, und beteuert, es gebe keinen Grund, grob zu werden."},{t="Seewolf hört die Geschichte",b="Seewolf MacKinley kichert, als er sich daran erinnert, wie er Phillipe die Innereien gezeigt hat. Er fragt, wie heftig Phillipe gezittert hat. MacKinley sagt, Phillipe sei leicht zu durchschauen und beim Kartenspielen gewinne er mühelos gegen ihn."}},faq={{q="Wer gibt Euch den Beutel?",a="Zitterhand Phillipe gibt Euch einen Beutel mit der Bezahlung für Seewolf MacKinley.",al={"wer gibt rückkehr zu mackinley","wo beginnt rückkehr zu mackinley"}},{q="Welche Ausrede hat Phillipe dafür, dass er nicht gezahlt hat?",a="Phillipe sagt, er sei ein wenig betrunken gewesen und habe den Weg verloren, schwört aber, dass er die Schulden immer zurückzahlen wollte.",al={"warum hat zitterhand nicht gezahlt","phillipes ausrede","warum war zitterhand phillipe spät dran"}},{q="Was kam vor diesem Schritt?",a="Zuvor ließ MacKinley Euch Phillipe in Scaring Shaky mit Innereien erschrecken.",al={"was kommt vor rückkehr zu mackinley","vorherige quest"}}},fp="19,139,12.248.0,23.205.1,24.69.0,46.99.0,27.79.0"}
P.entries["quest:6074"] = {n="Der Weg des Jägers",s="In Dun Morogh schicken die Ausbilder bereite Jäger nach Kharanos, um das Zähmen wilder Bestien zu erlernen. Grif Wildherz leitet dort die Prüfungen.",h="In Dun Morogh schicken die Ausbilder bereite Jäger nach Kharanos, um das Zähmen wilder Bestien zu erlernen.",kw={"dun morogh","grif wildherz","jäger","kharanos","olmin burningbeard","begleiterquest","zähmen","tristane shadowstone"},ang={["class:Hunter"]="Als Jäger beginnt Ihr, das einsame Fährtenlesen hinter Euch zu lassen, und lernt, wilde Raubtiere zu befehligen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Gebirgsjäger schon lange Bären und Eber als vertraute Gefährten bei Erkundungen auf den verschneiten Gipfeln von Dun Morogh halten."},sec={{t="Die wahre Berufung eines Jägers",b="Unerfahrene Jäger durchstreifen die verschneiten Felsen von Dun Morogh allein, bis sie lernen, eine Bindung zu Bestien aufzubauen. Olmin Burningbeard und Tristane Shadowstone beobachten ihre Schüler genau. Sie warten, bis ein Jäger einer wilden Kreatur ruhig entgegentreten und ihr Leben verschonen kann. Dann schicken die Ausbilder den disziplinierten Neuling über die Bergstraßen hinab nach Kharanos."},{t="Bei Grif Wildherz melden",b="In Kharanos leitet Grif Wildherz die abschließenden Prüfungen der zwergischen Jagdkunst. Eine Bestie zu zähmen erfordert mehr, als sie für Fleisch oder Fell zu erlegen. Ein Jäger braucht Geduld, körperliche Ausdauer und eine instinktive Bindung zu den wilden Raubtieren der Berge. Wildheart bereitet jeden Jäger darauf vor, seinen Willen gegen die wildesten Tiere von Dun Morogh auf die Probe zu stellen."}},faq={{q="Welchen Zweck hat diese Quest?",a="Bereite Jäger reisen nach Kharanos, um unter Grif Wildherz mit den Zähmungsprüfungen zu beginnen.",al={"warum diese quest machen","was ist der weg des jägers","start der jägerbegleiterquest"}},{q="Wer schickt mich auf diesen Weg?",a="Jägerausbilder führen ihre Schüler auf diesen Weg. Zu ihnen gehören Olmin Burningbeard in der Hall of Arms von Eisenschmiede, Tristane Shadowstone und Einris Brightspear.",al={"questgeber","wer vergibt den weg des jägers","wo annehmen"}},{q="Wo finde ich Grif Wildherz?",a="Grif Wildherz wartet vor der Brauerei Donnerbräu in Kharanos, im verschneiten Tal von Dun Morogh.",al={"grif wildherz standort","wo ist grif","kharanos jägerausbilder"}},{q="Warum brauchen Jäger einen Ausbilder, um Bestien zu zähmen?",a="Jäger nutzen besondere Techniken und eine Zähmerrute, um mit wilden Bestien in Verbindung zu treten, ohne einen Kampf auf Leben und Tod heraufzubeschwören. Grif Wildherz lehrt diese Traditionen.",al={"warum zähmausbildung nötig","hintergrund zum zähmen von begleitern","warum zähmen noch nicht möglich"}},{q="Was geschieht, nachdem ich mich bei Grif Wildherz gemeldet habe?",a="Nachdem Ihr Euch bei Grif Wildherz gemeldet habt, stellt er Euch auf die Probe. Er schickt Euch mit einer Zähmerrute in die Wildnis, um mehrere unterschiedliche, in Dun Morogh heimische Bestien zu bändigen.",al={"nächste quest","was folgt auf den weg des jägers","questreihe danach"}},{q="Kann jeder Jäger diese bestimmte Quest annehmen?",a="Diese Aufforderung führt zwergische Jäger in Dun Morogh zum örtlichen Ausbilder in Kharanos.",al={"nur für zwerge","auch für nachtelfen möglich","volksbeschränkung"}}},fx={["5e8bda0f"]={q="Warum schicken die Jägerausbilder Euch zu Grif Wildherz?",a="Eure Ausbilder erkennen, dass Ihr die grundlegenden Fähigkeiten entwickelt habt, die notwendig sind, um mit wilden Tieren zu kommunizieren und sie zu verwalten. Anstatt die standardmäßige Kampfunterweisung fortzusetzen, verweisen sie Euch an Grif Wildherz in Kharanos, damit Ihr ein spezialisiertes Training durchlaufen könnt. In ihren Augen ist die Beherrschung der Kunst der tierischen Begleitung der wesentliche nächste Meilenstein in Eurem Wachstum als wahrer Jäger.",al={"warum zu grif schicken","jägerausbilder beweggrund","warum zu grif wildherz"}}},fp="17,143,23.329.0,27.347.0,34.77.0,26.159.0,32.98.0,45.156.0,47.164.0,40.84.0"}
P.entries["quest:608"] = {n="Die Blutsegelbukaniere",s="Im Schlingendorntal sammeln die Blutsegelbukaniere ihre Kräfte für einen Angriff. Flottenmeister Seehorn will nicht seine ganze Flotte bei einem Gegenschlag riskieren, also schickt er eine kleine Mannschaft gegen ihre Anführer, bevor sie losschlagen können.",h="Im Schlingendorntal sammeln die Blutsegelbukaniere ihre Kräfte für einen Angriff.",kw={"blackwater","blutsegel","beutebucht","firallon","keelhaul","piraten","seehorn","stillwater"},sec={{t="Die Piratenflotte enthaupten",b="Flottenmeister Seehorn will den Angriff der Blutsegelbukaniere aufhalten, bevor er an Stärke gewinnt. Er spottet über Flottenmeister Firallons seemännisches Können und beschließt dann, die Befehlshaber anzugreifen. Seehorn will keine große Seeschlacht riskieren. Stattdessen schickt er eine kleine Mannschaft in Firallons Landelager, um Firallon, Captain Stillwater und Captain Keelhaul zu töten. Ohne ihre Anführer werden die Bukaniere ohne Kommando dastehen."}},faq={{q="Wer befiehlt den Schlag gegen die Führung der Blutsegelbukaniere?",a="Flottenmeister Seehorn in Beutebucht befiehlt den Schlag. Er hofft, die feindliche Flotte zu zerschlagen, bevor sie angreifen kann.",al={"wer vergibt die quest zu den blutsegelbukanieren","questgeber der blutsegelbukaniere","wer schickt abenteurer gegen firallon"}},{q="Welche Befehlshaber der Bukaniere müssen ausgeschaltet werden?",a="Die Ziele sind Flottenmeister Firallon, Captain Stillwater und Captain Keelhaul, die Anführer der Blutsegelstreitkräfte.",al={"ziele für blutsegelbukaniere","zu tötende blutsegelbefehlshaber","wer sind die blutsegelanführer"}},{q="Warum schickt Flottenmeister Seehorn Abenteurer statt seiner Schiffe?",a="Seehorn glaubt, dass eine fähige Mannschaft das Landelager angreifen und die feindlichen Offiziere töten kann. Das könnte die Flotte zu Fall bringen, ohne seine Schiffe zu gefährden.",al={"warum abenteurer zu firallon schicken","warum nicht die blackwater fleet schicken","seehorns plan"}},{q="Wo fügt sich dieser Zusammenstoß in die größere Auseinandersetzung mit den Blutsegelbukanieren ein?",a="Der Zusammenstoß folgt auf die Entdeckung der schriftlichen Angriffspläne der Bukaniere während der früheren Nachforschungen zu den Blutsegelbukanieren im Schlingendorntal.",al={"vorherige blutsegelquest","welche quest kommt davor","reihenfolge der blutsegelquestreihe"}}},fp="24,214,29.399.0,50.110.0,49.113.0,68.147.0,85.151.0"}
P.entries["quest:6081"] = {n="Die Ausbildung des Tiers",s="In Durotar werden junge Jäger der Orcs und Trolle zum erfahrenen Meisterjäger Ormak Grimmschlag geschickt, um von ihm zu lernen. Nachdem sie sich im Umgang mit den Tieren der Ebenen bewährt haben, reisen sie von Klingenhügel nach Orgrimmar. Dort lernen sie, einen lebenslangen tierischen Begleiter zu pflegen, zu füttern und auszubilden.",h="In Durotar werden junge Jäger der Orcs und Trolle zum erfahrenen Meisterjäger Ormak Grimmschlag geschickt, um...",kw={"durotar","jägerbegleiter","orgrimmar","ormak grimmschlag","klingenhügel","thotar","die ausbildung des tiers","tal der ehre"},ang={["class:Hunter"]="Für Euch als Jäger macht diese Ausbildung Euer Tier zu einem dauerhaften, verlässlichen Verbündeten statt zu einer flüchtigen Beschwörung. Ihr erlernt die Fähigkeiten Feed Pet und Revive Pet.",["faction:Horde"]="Die Horde ist auf Späher und Tiere angewiesen, um die gefährdeten Grenzen Durotars und des Brachlands gegen Einfälle von Zentauren, Stachelebern und der Allianz zu sichern.",["race:Orc"]="Für einen Orc ist die Bindung zu einem Jagdbegleiter eine Frage kriegerischer Ehre und Pflicht, die sich im Kampf in Durotars rauen Grenzgebieten bewähren muss.",["race:Troll"]="Für Dunkelspeertrolle, die sich in Kalimdor eine neue Heimat schaffen, ist die Verständigung mit Durotars wilden Kreaturen entscheidend für die Erkundung und das Überleben auf unbekanntem Boden."},sec={{t="Jenseits der Wildnis",b="In Durotars trockenen Schluchten sind Geschick mit dem Bogen und das Überleben in der Wildnis nur ein Teil der Pflichten eines Jägers. Junge Jäger zähmen zunächst die Tiere der Ebenen: wilde Eber, Aaskrabben und gepanzerte Skorpidpirscher. Sobald sie ihre Zähigkeit bewiesen haben, schickt Thotar sie von Klingenhügel nach Norden durch die roten Lehmschluchten zu Orgrimmars befestigten Toren. Dort müssen sie Verantwortung für einen Begleiter übernehmen."},{t="Das Tal der Ehre",b="In Orgrimmars Tal der Ehre verfeinern erfahrene Pirscher und Krieger ihr Handwerk. Dort suchen junge Jäger Ormak Grimmschlag auf, einen der verehrten Meisterjäger der Horde. Er blickt über ihre Jugend hinweg und prüft, ob sie die Geduld haben, ein Tier zu befehligen und durch Hungersnot, Kampf und Verlust zu versorgen."},{t="Verbunden mit der Wildnis",b="Ein mit Gewalt bezwungenes Tier bleibt wild, bis Jäger und Begleiter einander verstehen. Ormak lehrt die Traditionen, die ihre Bindung erhalten: welche Nahrung den Geist jeder Kreatur nährt, wie Disziplin einem Tier tödliche Techniken vermittelt und welche geistige Konzentration nötig ist, um ein im Dienst gefallenes Tier wiederzubeleben."}},faq={{q="Wer vergibt die Quest „Die Ausbildung des Tiers“?",a="Thotar, der Jägerlehrer vor der Kaserne in Klingenhügel, bietet diese Ausbildung an, nachdem Ihr alle drei Prüfungstiere in Durotar bezwungen habt.",al={"questgeber","wer vergibt die ausbildung des tiers","wo beginnt die ausbildung des tiers"}},{q="Wo finde ich Ormak Grimmschlag?",a="Ormak Grimmschlag befindet sich in Orgrimmars Tal der Ehre, einem östlichen Viertel, unter erfahrenen Jägern und Kriegern, die dort als Lehrmeister dienen.",al={"ormak grimmschlag standort","ormak grimmschlag finden","wo ist ormak"}},{q="Welche Fähigkeiten lehrt Euch Ormak Grimmschlag?",a="Ormak lehrt Euch, Eurem Begleiter aktive und passive Fähigkeiten beizubringen, ihn zu füttern, damit er treu und zufrieden bleibt, und ihn wiederzubeleben, falls er im Kampf stirbt.",al={"was lerne ich","fähigkeiten als questbelohnung","fähigkeiten des jägerbegleiters"}},{q="Warum müssen Jäger der Orcs und Trolle dafür Orgrimmar aufsuchen?",a="Örtliche Lehrer wie Thotar vermitteln die Grundlagen des Überlebens in der Wildnis. Die älteren Späher und verehrten Fährtenleser der Horde, darunter Ormak Grimmschlag, bewahren in der Hauptstadt das höhere Wissen der Tierherrschaft.",al={"warum nach orgrimmar reisen","warum orgrimmar","besuch im tal der ehre"}},{q="Absolvieren andere Völker der Horde genau diese Quest?",a="Nein. Jäger der Orcs und Trolle, die in Durotar beginnen, durchlaufen diesen Ritus. Taurenjäger folgen in Mulgore unter ihren eigenen Stammesmeistern einem ähnlichen Ritual.",al={"können tauren das machen","nur für orcs","untoter jäger"}},{q="Was geschieht, wenn ein Jäger diese Ausbildung nicht abschließt?",a="Ohne diese Ausbildung kann ein Jäger einen Begleiter weder füttern noch richtig ausbilden oder wiederbeleben. Ein gefangenes Tier wird unzufrieden und schwach und verlässt seinen Jäger womöglich eines Tages.",al={"ist das erforderlich","kann ich die ausbildung des tiers überspringen"}}},fx={["3f046eec"]={q="Warum schickt Thotar Euch zu Ormak Grimmschlag?",a="Thotar hat Euch durch die Riten des Zähmens der wilden Tiere von Durotar geführt, aber zu wissen, wie man eine Bindung zu einer Kreatur aufbaut, ist nur die halbe Kunst des Jägers. Ein in der Wildnis gefangenes Tier wird verhungern oder Euch verlassen, wenn es vernachlässigt wird. Thotar schickt Euch weiter zu Ormak Grimmschlag, damit ein Veteran des Tal der Ehre Euch beibringen kann, wie Ihr Euren neuen Begleiter richtig füttert, pflegt und diszipliniert.",al={"warum will thotar dass dies erledigt wird","thotar beweggrund training des tieres","warum ormak besuchen"}}},fp="18,266,31.396.0,19.306.0,21.311.0,40.141.0,32.112.0,42.150.0,62.182.0,48.149.0,60.166.0"}
P.entries["quest:6082"] = {n="Die Zähmung der Bestie",s="In Durotar steht ein junger Jäger der Horde vor der letzten Prüfung der Zähmung der Bestie. Thotar in Klingenhügel schickt den Jäger aus, einen gepanzerten Skorpid zu zähmen. Wer besteht, erlangt die Fähigkeit, einen dauerhaften Gefährten zu zähmen, zu rufen und freizugeben.",h="In Durotar steht ein junger Jäger der Horde vor der letzten Prüfung der Zähmung der Bestie.",kw={"gepanzerter skorpid","durotar","jägerprüfung","begleiterquest","klingenhügel","bestie zähmen","zähmerrute","thotar"},ang={["class:Hunter"]="Für Euch als Jäger ist dieser Ritus ein früher Meilenstein. Er verleiht Euch die grundlegenden Fähigkeiten, tierische Gefährten zu zähmen, zu rufen und zu befehligen.",["faction:Horde"]="Als junger Angehöriger der Horde in Durotar stellt Ihr Euch den gefährlichsten Raubtieren des Landes, um Euch einen Platz unter den Kundschaftern und Versorgern der Fraktion zu verdienen.",["race:Orc"]="Als Orc ehrt Ihr durch das Unterwerfen von Durotars Skorpiden den Glauben, dass unnachgiebiger Wille und kriegerische Disziplin selbst unwirtliches Gelände bezwingen.",["race:Troll"]="Als Troll nutzt Ihr Eure scharfen Instinkte und Eure tiefe Verbundenheit mit wilden Geistern, um giftige Raubtiere zu besänftigen, die andere niederstrecken könnten."},sec={{t="Die letzte Prüfung",b="Ein Jäger muss zuerst beweisen, dass er Durotars raue Tierwelt beherrschen kann, bevor er mit einem tierischen Gefährten durch Kalimdor reist. Thotar bildet in Klingenhügel Jäger aus und schickt sie los, um drei Arten von Kreaturen mit einer verzauberten Zähmerrute zu unterwerfen. Grautatzeneber und flinke Brandungsgleiter haben sie bereits auf die Probe gestellt. Nun stehen sie einem gepanzerten Skorpid gegenüber, einem giftigen Raubtier mit schweren Panzerplatten, das für seine Widerstandskraft und Schnelligkeit bekannt ist."},{t="Verbunden mit der Wildnis",b="Einen gepanzerten Skorpid zu zähmen prüft Konzentration und Beherrschung unter Angriffen, nicht das Geschick eines Jägers beim Töten. Thotar fordert Jäger auf, sich den schnellen, sicheren Schlägen der Bestie zu stellen. Sobald der Skorpid gebändigt ist, kehrt der Jäger nach Klingenhügel zurück und gibt Thotar die Zähmerrute zurück. Dann lehrt Thotar die angeborenen Techniken der Wildnis, damit der Jäger einen dauerhaften Gefährten seiner Wahl aufspüren und an sich binden kann."}},faq={{q="Welche Kreatur muss ich für diese Prüfung zähmen?",a="Zähmt für diese Prüfung einen gepanzerten Skorpid mit Thotars Zähmerrute. Er streift durch Durotars trockene rote Felslandschaft.",al={"welche bestie zähmen","zielbestie","skorpidquest"}},{q="Darf ich den gepanzerten Skorpid nach Abschluss der Quest behalten?",a="Nein. Der gepanzerte Skorpid ist nur ein vorübergehender Gefährte und verschwindet, wenn Ihr die Zähmerrute zurückgebt. Durch den Abschluss der Prüfung lernt Ihr, eine wilde Bestie Eurer Wahl dauerhaft zu zähmen.",al={"skorpid behalten","kann ich den begleiter behalten","skorpid dauerhaft"}},{q="Wer leitet diesen Übergangsritus ein?",a="Thotar, der Jägerlehrer in Klingenhügel, leitet diesen Ritus für junge Orc- und Trolljäger.",al={"questgeber","wer vergibt die zähmung der bestie","thotars standort"}},{q="Warum sollen Jäger nach Thotars Willen gerade einen gepanzerten Skorpid zähmen?",a="Thotar sieht im gepanzerten Skorpid ein Vorbild für sichere, schnelle Schläge und Widerstandskraft. Ein so gefährliches Raubtier zu zähmen beweist, dass ein Jäger wilde Bestien beherrschen kann.",al={"warum skorpid","zweck des skorpids"}},{q="Welche Fähigkeiten erlernt man beim Abschluss dieser Quest?",a="Ihr erlernt Tame Beast, Call Pet und Dismiss Pet.",al={"belohnungen","welche zauber bekomme ich","freigeschaltete zähmfähigkeiten"}},{q="Was folgt auf diese Prüfung?",a="Nachdem Ihr gelernt habt, einen Gefährten zu zähmen und zu rufen, könnt Ihr Thotars Anweisung zu Training the Beast folgen. Dort lernt Ihr, Euren Verbündeten zu füttern und zu befehligen.",al={"nächste quest","wie geht es weiter","nach zähmung drei"}}},fx={["5a0a9a11"]={q="Warum lässt Thotar Euch Tiere selbst zähmen, anstatt es für Euch zu tun?",a="Dies ist ein Ritus des Übergangs, den jeder aufstrebende Jäger alleine durchstehen muss. Thotars Rolle in Klingenhügel ist es, Euch zu leiten und anzuleiten, aber die Beherrschung der Gemeinschaft mit der Wildnis kann nicht allein durch Worte gewährt werden. Das Zähmen einer aggressiven, giftigen Kreatur wie eines gepanzerten Skorpions beweist, dass Ihr den Willen, die Geduld und die Entschlossenheit besitzt, die erforderlich sind, um ein wildes Raubtier Eurem Befehl zu unterwerfen, bevor Euch ein dauerhafter Begleiter anvertraut wird.",al={"warum muss ich das tier zähmen","warum zähmt thotar ihn nicht","warum ich thotar skorpion"}}},fp="16,213,15.404.0,21.393.0,47.100.0,63.182.0,35.93.0,69.160.0,52.48.0,28.149.0"}
P.entries["quest:6083"] = {n="Die Zähmung der Bestie",s="An Durotars Küste schickt Die Zähmung der Bestie junge Jäger in ihre zweite Prüfung. Thotar, der Jägerlehrer in Klingenhügel, weist angehende Orc- und Trolljäger an, nahe den Echoinseln einen Brandungskriecher zu zähmen und ihre Bindung auf Küstentiere auszuweiten.",h="An Durotars Küste schickt Die Zähmung der Bestie junge Jäger in ihre zweite Prüfung.",kw={"durotar","die echoinseln","begleiter zähmen","klingenhügel","sen'jin","brandungskriecher","zähmerrute","thotar"},ang={["class:Hunter"]="Als Jäger erlernt Ihr die nötige Disziplin, um wehrhafte Tiere zu befehligen. Die natürliche Panzerung und Zähigkeit einer Kreatur können Euer Können als Fernkampfschütze ergänzen.",["race:Orc"]="Als Orc, der sich in Durotar eine dauerhafte Heimat schafft, festigt Ihr Eure Herrschaft über das raue Land, indem Ihr seine widerstandsfähigen Küstentiere unterwerft.",["race:Troll"]="Als Dunkelspeertroll kennt Ihr die Gewässer nahe den Echoinseln und Sen'jin gut. Diese Prüfung bringt Euch den wilden Tieren Eures Küstenrefugiums von Angesicht zu Angesicht gegenüber."},sec={{t="Die Bindung zur Küste",b="Ihr habt einen Schreckenseber gemeistert, und nun schickt Thotar Euch zum Meer. Durotars raue Küsten sind zerklüftet, und die seichten Riffe wimmeln von gepanzerten Krebstieren. Ein Brandungskriecher wehrt sich gegen Eindringlinge in sein Küstenrevier. Einen zu zähmen erfordert Geduld und Seelenstärke."},{t="Die Erweiterung des Willens",b="Thotar lehrt, dass ein gebundenes Tier die Stärke eines Jägers mehren sollte. Mit der Zähmerrute unterwerft Ihr einen Brandungskriecher und lernt, Kreaturen mit unterschiedlichen Gemütern in verschiedenen Umgebungen zu befehligen. Diese Prüfung beweist, dass Ihr für dauerhafte Gefährten bereit seid."}},faq={{q="Wo findet man Brandungskriecher?",a="Brandungskriecher huschen durch das seichte Wasser an Durotars Ostküste, gegenüber von Sen'jin und nahe den Gewässern, die zu den Echoinseln führen.",al={"brandungskriecher fundort","wo ist der brandungskriecher","krabbe fundort"}},{q="Welchen Zweck hat es, einen Brandungskriecher zu zähmen?",a="Thotar trägt Euch auf, einen Brandungskriecher zu zähmen, damit Ihr lernt, verschiedene Tierarten zu befehligen. Eine gepanzerte Wasserkreatur zu zähmen erweitert Eure Kontrolle und beweist, dass Ihr Tiere aus dem Wasser ebenso wie vom Festland meistern könnt.",al={"warum krabbe zähmen","brandungskriecher quest zweck"}},{q="Behalte ich den Brandungskriecher dauerhaft?",a="Nein. Die Tiere, die Ihr in diesen ersten Prüfungen zähmt, dienen vorübergehend der Übung und werden mit Thotars Zähmerrute unterworfen. Erst nach Abschluss der gesamten Reihe erlernt Ihr die Fähigkeit, Tiere dauerhaft zu zähmen.",al={"bleibt die krabbe","ist der brandungskriecher dauerhaft"}},{q="Wer vergibt diese Quest?",a="Thotar, der Jägerlehrer in Klingenhügel, gibt Euch diese Prüfung, nachdem Ihr bewiesen habt, dass Ihr einen Schreckenseber zähmen könnt.",al={"questgeber","wer startet die zähmung der bestie zwei"}},{q="Was folgt auf die Zähmung des Brandungskriechers?",a="Nachdem Ihr Thotar die Rute zurückgebracht habt, gibt er Euch eine dritte und letzte Prüfung: einen Armored Scorpid aufzuspüren und zu zähmen. Dann lehrt er Euch, Tiere dauerhaft zu meistern.",al={"nächste quest","was folgt in der questreihe"}},{q="Warum eine Zähmerrute statt natürlicher Fähigkeiten verwenden?",a="Jägernovizen haben noch nicht die geistige Autorität entwickelt, wilde Tiere dauerhaft an sich zu binden. Die Zähmerrute lässt Anfänger gefahrlos üben, ihren Willen zu bündeln, bevor sie die wahre Technik erlernen.",al={"warum zähmerrute","was ist eine zähmerrute"}}},fx={["4f8a703d"]={q="Warum will Thotar, dass ich einen Strandkrabbler zähme?",a="Thotar bildet Euch in den grundlegenden Künsten eines Jägers aus. Wenn Ihr die Kontrolle über Bestien erlangt, werden sie zu einer Erweiterung Eurer eigenen Stärke, was Euch einen deutlichen Vorteil gegenüber Euren Rivalen verschafft. Nachdem er Euch an Landtieren geprüft hat, möchte er, dass Ihr Euch den Gewässern zuwendet, um Euer Können zu erweitern und zu beweisen, dass Ihr auch temperamentvolle Wasserbewohner meistern könnt.",al={"thotars motiv","warum strandkrabbler zähmen","warum will thotar das"}},["5da4eb39"]={q="Was sind Strandkrabbler?",a="Strandkrabbler sind temperamentvolle, zähe Krabben, die in den Untiefen entlang der Ostküste von Durotar beheimatet sind und häufig in den Gewässern zwischen Sen'jin und den Echoinseln anzutreffen sind. Ihr gepanzerter Rückenpanzer und ihre aquatische Natur machen sie zu einem idealen Test, um die Meisterschaft eines angehenden Jägers über die landbewohnenden Tiere der Steppen hinaus zu erweitern.",al={"was ist ein strandkrabbler","strandkrabbler in durotar","über strandkrabbler"}}},fp="16,254,22.266.0,21.257.0,30.153.0,45.211.0,39.191.0,21.112.0,41.158.0,47.200.0"}
P.entries["quest:6084"] = {n="Die Zähmung der Bestie",s="Grif Wildherz schickt Euch in der zweiten Zähmungsprüfung zu einem Schneeleoparden. Die Prüfung geht über den Felseber hinaus.",h="Grif Wildherz schickt Euch in der zweiten Zähmungsprüfung zu einem Schneeleoparden.",kw={"dun morogh","grif wildherz","jägerquest","kharanos","schneeleopard","zähmerrute","die zähmung der bestie"},ang={["class:Hunter"]="Als Jäger lernt Ihr, wie Eber harte Treffer einstecken, während Katzen schnell und aggressiv zuschlagen.",["race:Dwarf"]="Als Zwerg teilt Ihr die eisigen Gipfel von Dun Morogh mit Schneeleoparden, deren Heimlichkeit und Jagdgeschick Respekt gebieten."},sec={{t="Eine Lektion in Finesse",b="Schneeleoparden streifen südöstlich von Kharanos umher. Der Felseber hat Eure Stärke gegen harte Schläge geprüft. Nun erwartet Grif, dass Ihr einem schnellen, anmutigen Raubtier zu dessen Bedingungen entgegentretet. Unter seinem weißen Fell ruht gefährliche Kraft, bereit zuzuschlagen."},{t="Die Zähmerrute meistern",b="Mit einer verzauberten Zähmerrute tretet Ihr einem wilden Schneeleoparden gegenüber und versucht, seine Jagdinstinkte in eine Partnerschaft zu lenken. Seine Schnelligkeit, Beweglichkeit und scharfen Reflexe stellen Euch auf andere Weise auf die Probe als der Felseber. Lernt, mit einem Raubtier zusammenzuarbeiten, das blitzschnell aus den verschneiten Felsen zuschlägt, und Ihr kommt der Beherrschung der Bestien der Wildnis näher."}},faq={{q="Welchen Zweck hat diese Quest?",a="Dies ist die zweite Prüfung im Initiationsritus der zwergischen Jäger. Grif Wildherz prüft Euer Geschick im Umgang mit verschiedenen Bestien, bevor er Euch lehrt, dauerhafte Bindungen zu tierischen Begleitern einzugehen.",al={"warum diese quest machen","schneeleopard quest zwerg","die zähmung der bestie zwei"}},{q="Wo finde ich die Schneeleoparden?",a="Schneeleoparden streifen über die felsigen Höhen und verschneiten Hänge südlich und östlich von Kharanos in Dun Morogh.",al={"schneeleopard fundort","wo sind schneeleoparden dun morogh","leopard fundort"}},{q="Warum will Grif Wildherz, dass ich einen Leoparden zähme?",a="Grif Wildherz möchte, dass Ihr sowohl Stärke als auch Finesse erlernt. Der Felseber verlässt sich auf seine Zähigkeit, während der Schneeleopard Euch lehrt, an der Seite eines schnellen, beweglichen und tödlichen Begleiters zu kämpfen.",al={"warum schneeleopard","grif wildherz leopard begründung"}},{q="Kann ich diesen Schneeleoparden dauerhaft behalten?",a="Nein. Die Bestien, die Ihr in diesen ersten Prüfungen zähmt, sind vorübergehende Partner, gebunden durch die Magie der Zähmerrute. Wenn Grif Eure Ausbildung für abgeschlossen hält, könnt Ihr jede wilde Bestie Eurer Wahl dauerhaft zähmen.",al={"kann ich den schneeleoparden behalten","ist der leopard dauerhaft"}},{q="Wer erteilt diese Prüfung?",a="Grif Wildherz, der zwergische Jägerlehrer vor dem Gasthaus in Kharanos, Dun Morogh, erteilt diese Prüfung.",al={"wer gibt die quest","questgeber","grif wildherz rolle"}},{q="Was kommt als Nächstes in der Questreihe?",a="Nachdem Ihr den Schneeleoparden gemeistert habt, schickt Grif Euch in der dritten und letzten Zähmungsprüfung zu einem Ice Claw Bear. Danach lehrt er Euch, wilde Bestien eigenständig zu zähmen und auszubilden.",al={"nächste quest","was kommt nach dem schneeleoparden"}}},fx={baf34ad8={q="Was für eine Bestie ist der Schneeleopard?",a="Schneeleoparden sind schnelle, flinke Raubtiere aus den verschneiten Bergrücken von Dun Morogh. Im Gegensatz zu den stämmigen und eigensinnigen Felsenebern aus Eurer ersten Prüfung verlassen sich diese großen weißen Katzen auf Finesse, Schnelligkeit und tödliche Angriffe. Grif Wildherz schickt Euch zu ihnen, damit Ihr lernt, mit einem empfindlichen, aggressiven Jagdpartner umzugehen, der sich ganz anders verhält als ein rohes Wildtier.",al={"schneeleoparden-kunde","warum schneeleopard zähmen","schneeleoparden in dun morogh"}},["4533de88"]={q="Warum lässt Grif Wildherz mich den Schneeleoparden selbst zähmen?",a="Dies ist Euer Initiationsritus als junger Jäger, keine lästige Aufgabe, die Grif für die Stadt erledigen muss. Zähmen erfordert die Etablierung persönlicher Dominanz und Empathie gegenüber wilden Bestien. Grif kennt das Handwerk bereits; Ihr seid derjenige, der lernen muss, die Magie der Zähmerrute zu kanalisieren und einem anstürmenden Raubtier standzuhalten, um zu beweisen, dass Ihr bereit seid, einen lebenslangen Gefährten zu befehligen.",al={"warum muss ich ihn zähmen","warum ich zähmerrute","warum schickt mich grif wildherz"}}},fp="16,114,19.236.0,24.331.0,34.184.0,34.94.0,50.184.0,47.198.0,23.101.0,29.174.1"}
P.entries["quest:6085"] = {n="Die Zähmung der Bestie",s="In Dun Morogh prüft Grif Wildherz Eure Kontrolle über einen Eiskrallenbären östlich von Kharanos. Mit einer verzauberten Rute unterwerft Ihr den Bären und lernt, ihn zu verstehen. Dann erlangt Ihr die Macht, einen dauerhaften wilden Begleiter zu zähmen, zu rufen und freizugeben.",h="In Dun Morogh prüft Grif Wildherz Eure Kontrolle über einen Eiskrallenbären östlich von Kharanos.",kw={"dun morogh","grif wildherz","jägerquest","eiskrallenbär","kharanos","begleiter zähmen","zähmerrute","die zähmung der bestie"},ang={["class:Hunter"]="Als Jäger beginnt Ihr als einzelgängerischer Bogenschütze und werdet zu einem wahren Bestienzähmer. Ihr erlangt die grundlegenden Fähigkeiten, Bestien zu zähmen und herbeizurufen.",["race:Dwarf"]="Als Zwerg kennt Ihr Bären als beliebte Begleiter der Gebirgsjäger von Dun Morogh. Sie sind dafür bekannt, ihren Meistern an sturer Widerstandskraft ebenbürtig zu sein."},sec={{t="Die Stärke der Wildnis",b="Die Gebirgsjäger und Kundschafter von Dun Morogh verlassen sich in den eisigen Felsen auf widerstandsfähige Bestien. Ihr habt an flinken, gerissenen Raubtieren geübt. Nun schickt Grif Wildherz Euch aus, um einen Eiskrallenbären in den Schneewehen östlich von Kharanos einzufangen. Seine Stärke und Ausdauer stellen die Kontrolle auf die Probe, die jeder Zwergenjäger erlernen muss."},{t="Einen Begleiter gewinnen",b="Die Zähmerrute hält den Bären gefügig, während Ihr lernt, wie wilde Instinkte auf Willenskraft und ruhige Entschlossenheit reagieren. Eure Bindung besteht nur für die Dauer der Prüfung, die Euch Disziplin lehrt. Bringt die Rute zu Grif zurück, und die Prüfungen sind abgeschlossen. Dann lehrt er Euch, eine empfängliche wilde Kreatur zu besänftigen und sie Euer ganzes Abenteurerleben lang herbeizurufen."}},faq={{q="Welches Tier muss ich für diese Quest zähmen?",a="Ihr müsst einen Eiskrallenbären in den gefrorenen Ausläufern östlich von Kharanos in Dun Morogh zähmen. Die Zähmerrute unterwirft ihn, während Ihr lernt, mit seiner rohen Kraft umzugehen.",al={"welcher bär","zieltier","zähmziel"}},{q="Behalte ich den Eiskrallenbären nach Abschluss der Quest?",a="Nein. Der mit der Zähmerrute unterworfene Eiskrallenbär dient nur als vorübergehende Prüfung Eurer Disziplin und Eures Geschicks. Wenn Ihr die Rute zu Grif Wildherz zurückbringt, verlässt Euch der Bär, und Ihr erhaltet die Fähigkeiten, jede wilde Bestie Eurer Wahl zu zähmen.",al={"bleibt der bär","begleiter behalten","bär dauerhaft"}},{q="Wo befindet sich Grif Wildherz?",a="Grif Wildherz steht vor der Brauerei Donnerbräu in Kharanos, Dun Morogh. Er bildet angehende Jäger in Treffsicherheit und Tierherrschaft aus.",al={"grifs standort","wo ist grif","jägerlehrer kharanos"}},{q="Welche Fähigkeiten lerne ich nach Abschluss dieser Prüfung?",a="Ihr lernt Tame Beast, Call Pet und Dismiss Pet. Mit diesen Fähigkeiten könnt Ihr mit einem dauerhaften Begleiter in die Welt hinausziehen.",al={"questbelohnungen","erlernte jägerfähigkeiten","tame beast belohnung"}},{q="Was ist der nächste Schritt nach Abschluss dieser Quest?",a="Grif schickt Euch weiter zu Training the Beast. Dort lernt Ihr, Euren neuen Begleiter zu füttern, zu pflegen und zu unterweisen, damit er Euch im Kampf treu bleibt.",al={"nächste quest","what comes next","training the beast"}},{q="Warum lässt Grif Jäger mehrere Arten von Bestien erproben?",a="Die drei Prüfungen machen Euch mit verschiedenen Kampfstilen vertraut: Beweglichkeit, List und rohe Kraft. Diese Wesenszüge helfen einem Gebirgsjäger, einen Begleiter zu wählen, der zu seinem Jagdstil passt.",al={"warum drei bestien","zweck der prüfungen","drei tiere"}}},fx={d0a90924={q="Was sind Eisklauenbären und warum treiben sie sich bei Kharanos herum?",a="Eisklauenbären sind stämmige, dickfellige Raubtiere, die in den verschneiten Felsen von Dun Morogh beheimatet sind und häufig in der Wildnis östlich von Kharanos umherstreifen. Grif Wildherz hält sie aufgrund ihrer rohen Zähigkeit und Kraft für einen idealen Begleiter für einen angehenden Jäger. Wenn Ihr einem von ihnen gegenübersteht, müsst Ihr beweisen, dass Ihr Euch gegen immense physische Kraft behaupten und ein wahrhaft zähes Bergwesen beherrschen könnt, bevor Ihr die volle Meisterschaft über wilde Kreaturen beansprucht.",al={"eisklauenbären-kunde","warum eisklauenbär zähmen","eisklauenbären in dun morogh"}}},fp="16,234,24.304.0,19.321.0,45.158.0,55.220.0,32.140.0,52.123.0,50.136.0,57.176.0"}
P.entries["quest:6086"] = {n="Die Ausbildung des Tiers",s="In Dun Morogh schickt Grif Wildherz junge Zwergenjäger nach Eisenschmiede, damit sie die Pflege eines dauerhaften Tierbegleiters erlernen. Nachdem sie die wilden Raubtiere des Gebirges gezähmt haben, lernen sie, ihre Tiere zu füttern und auszubilden.",h="In Dun Morogh schickt Grif Wildherz junge Zwergenjäger nach Eisenschmiede, damit sie die Pflege eines...",kw={"belia thundergranite","dun morogh","zwergenjäger","grif wildherz","hall of arms","eisenschmiede","tierausbildung","die ausbildung des tiers"},ang={["class:Hunter"]="Als Jäger lernt Ihr, einen dauerhaften Tierbegleiter zu füttern, zu befehligen und wiederzubeleben.",["faction:Alliance"]="Als Mitglied der Allianz verlasst Ihr Euch auf Eisenschmiedes Tiermeister. Ihre treuen Begleiter leisten einen großen Beitrag zu den Spähtruppen der Allianz und patrouillieren auf den eisigen Bergpässen.",["race:Dwarf"]="Als Zwerg erbt Ihr Khaz Modans Tradition, Bären, Eber und Bergkatzen als Partner bei der Erkundung und Verteidigung der gebirgigen Wildnis zu behandeln."},sec={{t="Aus der Wildnis zur Schmiede",b="Junge Jäger schließen ihre Prüfung nahe Kharanos unter Grif Wildherz' Aufsicht ab. Sie haben mit einer Zähmerrute große Klippeneber, Schneeleoparden und stämmige Eiskrallenbären gezähmt. Dann schickt Grif sie den Bergpass hinauf nach Eisenschmiede. Dort suchen sie die Hall of Arms im Militärviertel auf."},{t="Belia Thundergranites Lehren",b="Belia Thundergranite lehrt Tierpflege in Eisenschmiedes Hall of Arms. Als angesehene Meistertierausbilderin des Zwergenreichs zeigt sie jungen Jägern, wie sie ihre Tiere ernähren und ihnen neue Fähigkeiten für das Schlachtfeld beibringen. Sie lehrt sie auch, die Geister ihrer Tiere zurückzurufen, wenn diese bei der Verteidigung ihres Meisters fallen. Ihre Lehren machen aus einem verängstigten Wildtier einen treuen Partner."},{t="Der Bund des Zwergenjägers",b="Die zwergische Tradition verlangt Respekt zwischen Jäger und Tier, niemals Unterwerfung. Belia erinnert junge Jäger daran, dass ein Tierbegleiter die Fürsorge widerspiegelt, die er erhält. Gut gefüttert, respektiert und richtig ausgebildet kämpft ein Tier treu gegen Troggs, Frosttrolle und jede Bedrohung für Khaz Modan."}},faq={{q="Welchen Zweck hat diese Quest?",a="Die Ausbildung des Tiers schließt die Grundausbildung eines Zwergenjägers ab. Ihr lernt, einen dauerhaften Tierbegleiter zu pflegen, zu füttern und auszubilden, ihn an Eure Seite zu rufen und ihn zurückzubringen, wenn er stirbt.",al={"warum diese quest machen","die ausbildung des tiers zweck","jägertier questbelohnung"}},{q="Wer ist Belia Thundergranite?",a="Belia Thundergranite ist eine angesehene Meistertierausbilderin und leitende Lehrerin in Eisenschmiedes Hall of Arms. Sie lehrt Zwergenjäger die Pflege, Disziplin und Befehle, die gezähmte Tiere zu lebenslangen Verbündeten machen.",al={"wer ist belia","belia thundergranite hintergrund","jägerlehrer eisenschmiede"}},{q="Wo finde ich Belia Thundergranite?",a="Belia Thundergranite befindet sich in Eisenschmiedes Hall of Arms, dem Militärflügel der Stadt. Krieger, Jäger und Paladine der Zwerge und Gnome versammeln sich dort und trainieren.",al={"belia standort","wo ist belia thundergranite","wo ist hall of arms eisenschmiede"}},{q="Welche Tiere zähmen Zwergenjäger vor dieser Ausbildung?",a="Vor dieser Ausbildung besänftigen junge Jäger mit einer Zähmerrute einen großen Klippeneber, einen Schneeleoparden und einen Eiskrallenbären in Dun Morogh. Grif Wildherz beaufsichtigt diese Prüfungen.",al={"welche tiere werden gezähmt","zwerg tierprüfung tiere","tiere vorheriger quests"}},{q="Warum müssen Zwergenjäger ihre Tiere füttern?",a="Die zwergische Tierkunde betrachtet Tierbegleiter als Partner, nicht als Werkzeuge. Ein hungriges Tier wird missmutig und weniger kampfbereit. Haltet es gut genährt, um Euch seine entschlossene Treue zu verdienen und ihm zu helfen, im Kampf sein Bestes zu geben.",al={"warum tier füttern","tierz u friedenheit hintergrund","tiertreue zwerg"}},{q="Wer vergibt diese Quest?",a="Grif Wildherz ist ein erfahrener Jägerlehrer an der Straße östlich von Kharanos in Dun Morogh. Er bietet Euch diese Ausbildung an, nachdem Ihr Eure dritte Zähmprüfung abgeschlossen habt.",al={"wer startet die ausbildung des tiers","grif wildherz rolle","questgeber"}}},fx={["5ee43731"]={q="Warum schickt Grif Wildherz Euch nach Eisenschmiede?",a="Grif Wildherz hat Eure grundlegenden Prüfungen in den Felsen von Dun Morogh geleitet und Euch gelehrt, wilde Bestien zu zähmen. Doch das Meistern der Pflege, Fütterung und Disziplinierung eines Bestiengefährten erfordert fortgeschrittene Expertise. Grif schickt Euch nach Eisenschmiede, damit Belia Thundergranite, eine der angesehensten Meisterausbilderinnen der Zwerge in der Hall of Arms, Eure Ausbildung vervollständigen und sicherstellen kann, dass Euer Haustier zu einem treuen Verbündeten wird.",al={"warum schickt euch grif","grif wildherz' motiv","warum zum jägerlehrer nach eisenschmiede"}}},fp="18,205,26.281.0,32.371.0,25.293.0,34.191.0,28.210.0,37.154.0,67.171.0,41.195.0,21.157.0"}
P.entries["quest:6087"] = {n="Die Zähmung der Bestie",s="Im Dorf der Bluthufe stellt Yaw Scharfmähne einem jungen Taurenjäger eine neue Prüfung. Der Jäger muss den flinken Präriepirscher meistern.",h="Im Dorf der Bluthufe stellt Yaw Scharfmähne einem jungen Taurenjäger eine neue Prüfung.",kw={"dorf der bluthufe","jägerprüfung","mulgore","präriepirscher","zähmerrute","die zähmung der bestie","taurenjäger","yaw scharfmähne"},ang={["class:Hunter"]="Als Jäger lernt Ihr, Überlebensfertigkeiten mit abgestimmten Angriffen zu verbinden und an der Seite eines flinken Gefährten zu kämpfen.",["race:Tauren"]="Als Tauren folgt Ihr dem Weg der Shu'halo bei der Tierzähmung und knüpft unter der wachsamen Gnade der Earthmother eine heilige Verwandtschaft."},sec={{t="Die Lehren des Pirschers",b="Nachdem Ihr die Ausdauer des erwachsenen Ebenenschreiters gemeistert habt, begegnet Ihr einer neuen Art von Jäger. Präriepirscher setzen auf Schnelligkeit und ziehen in Rudeln umher. Sie greifen ohne Furcht an. Um einen zu zähmen, müsst Ihr Euch ihm nähern, ohne innezuhalten, und ebenso entschlossen handeln wie der Wolf."},{t="Muskel an Muskel",b="Yaw Scharfmähne lehrt Euch, dass die Jagd an der Seite eines Tieres weder Knechtschaft noch rohe Gewalt erfordert. Ihr und das Raubtier müsst als Einheit kämpfen, verbunden durch Respekt und einen gemeinsamen Rhythmus. Unter dem offenen Himmel von Mulgore lehrt Euch das Band mit einem Präriepirscher, die Angriffe Eures Gefährten zu ergänzen und Euch im Kampf mit ihm zu bewegen."}},faq={{q="Welches Tier soll ich in dieser Prüfung für Yaw Scharfmähne zähmen?",a="Yaw Scharfmähne fordert Euch auf, einen Präriepirscher zu zähmen, einen flinken Wolf, der durch die Ebenen von Mulgore streift.",al={"welches tier zähmen","welcher begleiter kommt als nächstes","präriepirscher zähmen"}},{q="Warum lernt ein Taurenjäger, Wölfe zu zähmen?",a="Yaw Scharfmähne lehrt, dass Präriepirscher Schnelligkeit und Furchtlosigkeit verkörpern. Das Band mit einem von ihnen hilft Euch, diese Eigenschaften zu erlernen und Eure Angriffe mit einem flinken Jagdgefährten abzustimmen.",al={"warum wölfe","geschichte der präriepirscher","warum einen wolf zähmen"}},{q="Wo findet man Präriepirscher gewöhnlich?",a="Präriepirscher durchstreifen die grasbewachsenen Ebenen im mittleren und nördlichen Mulgore, darunter die Prärien rund um das Dorf der Bluthufe.",al={"fundort der präriepirscher","wo sind präriepirscher","präriepirscher finden"}},{q="Darf ich den Präriepirscher nach der Quest behalten?",a="Nein. Die Zähmerrute knüpft nur ein vorübergehendes Band zur Ausbildung. Nach allen Prüfungen erlangt Ihr die dauerhafte Fähigkeit, einen beliebigen wilden Gefährten Eurer Wahl zu zähmen.",al={"wolf behalten möglich","präriepirscher behalten","ist dies ein dauerhafter begleiter"}},{q="Wer ist Yaw Scharfmähne?",a="Yaw Scharfmähne ist der Jägerausbilder im Dorf der Bluthufe. Er führt junge Tauren durch die geistigen und praktischen Schritte, mit denen sie die Wildnis von Mulgore meistern.",al={"wer ist yaw","geschichte von scharfmähne","yaw bluthufe"}},{q="Was folgt auf die Zähmung des Präriepirschers?",a="Nachdem Yaw Scharfmähne bestätigt hat, dass Ihr den Wolf gemeistert habt, schickt er Euch zur dritten und letzten Prüfung, in der Ihr dem verstohlenen swoop begegnet.",al={"nächste quest","was kommt nach dem präriepirscher","dritte zähmungsquest"}}},fx={f904daad={q="Warum schickt mich Yaw Scharfmähne los, um die Bestie zu zähmen, anstatt sich selbst darum zu kümmern?",a="Dies ist keine Aufgabe oder lästige Pflicht, die delegiert werden kann; es ist ein heiliger Initiationsritus in Eurer Ausbildung als Jäger. Yaw Scharfmähne kennt bereits die Wege der Wildnis und befehligt seine eigene Verbindung zur Natur. Um ein wahrer Jäger der Erdenmutter zu werden, müsst Ihr den Pfad selbst beschreiten und durch erste eigene Erfahrungen lernen, wie man einem schnellen, furchtlosen Raubtier gegenübertritt und Eure Geister zu einem vereinten Team verbindet.",al={"warum ich yaw scharfmähne","warum muss ich den präriepirscher zähmen","warum zähmt yaw ihn nicht"}}},fp="16,125,21.257.0,16.313.0,60.94.0,46.173.0,44.121.0,53.150.0,21.154.0,44.134.0"}
P.entries["quest:6088"] = {n="Die Zähmung der Bestie",s="In Mulgore stellt sich ein junger Taurenjäger bei Yaw Scharfmähne im Dorf der Bluthufe der letzten Prüfung. Mit einer verzauberten Rute zähmt Ihr einen wilden Swoop und beweist, dass Ihr den Himmel meistern könnt. Die Prüfung bringt Euch das Vertrauen der Erdenmutter und dauerhaftes Wissen, um einen Gefährten zu zähmen, zu rufen und wegzuschicken.",h="In Mulgore stellt sich ein junger Taurenjäger bei Yaw Scharfmähne im Dorf der Bluthufe der letzten Prüfung.",kw={"dorf der bluthufe","erdenmutter","tiergefährte des jägers","mulgore","swoop","zähmerrute","die zähmung der bestie","yaw scharfmähne"},ang={["class:Hunter"]="Als Jäger schließt Ihr die grundlegende Ausbildungsreihe ab und lernt, Wildtiere dauerhaft zu zähmen. Dies markiert Euren Übergang vom Lehrling zum eigenständigen Späher der Wildnis.",["race:Tauren"]="Als Shu'halo ist Eure Bindung zu einem wilden Tier eine spirituelle Gemeinschaft, gesegnet von der Erdenmutter. Sie hat überall auf den Ebenen von Mulgore eine tiefe kulturelle Bedeutung."},sec={{t="Meisterschaft über den Himmel",b="Nachdem Ihr Raubtiere auf den Ebenen von Mulgore bezwungen habt, richtet Yaw Scharfmähne Eure Ausbildung auf den offenen Himmel. Ein Swoop ist ein wilder Raubvogel mit scharfem Schnabel, weiten Sturzflügen und einschüchterndem Auftreten. Seine Klauen prüfen Eure Reflexe und Eure Ruhe, während Ihr mit der verzauberten Rute seine Instinkte mit Euren eigenen in Einklang bringt."},{t="Die Gabe der Erdenmutter",b="Für die Tauren sind die Jagd und die Gefährtenschaft mit Wildtieren spirituelle Bestrebungen, keine bloße Unterwerfung. Geschöpfe der Erde und des Himmels zu meistern, lehrt das Gleichgewicht und den Respekt, die nötig sind, um die Ebenen zu durchstreifen, ohne die Natur zu stören. Yaw Scharfmähne nimmt seine vorübergehend überlassene Zähmerrute zurück und lehrt Euch dann dauerhafte Methoden, um einen Gefährten Eurer Wahl zu rufen, wegzuschicken und dauerhaft zu zähmen."}},faq={{q="Warum muss ich für die letzte Prüfung einen Swoop zähmen?",a="Yaw Scharfmähne stellt Euch in dieser letzten Prüfung den Geschöpfen des Himmels gegenüber. Swoops greifen schnell und heftig an, und ihr imposantes Auftreten prüft, ob Ihr mit Raubtieren der Lüfte und des Bodens umgehen könnt, bevor Ihr Eigenständigkeit erlangt.",al={"warum swoop zähmen","zweck der swoopzähmung","warum ein swoop"}},{q="Behalte ich den Swoop, den ich während dieser Quest zähme?",a="Nein. Yaw Scharfmähnes Rute lässt Euch den Swoop während Eurer Ausbildung nur vorübergehend zähmen. Danach könnt Ihr jedes wilde Tier, das Ihr behalten möchtet, dauerhaft zähmen.",al={"bleibt der swoop","swoop als tiergefährte","vogel behalten möglich"}},{q="Wer vergibt diese Quest und wo ist diese Person zu finden?",a="Yaw Scharfmähne, der Jägerlehrer im Dorf der Bluthufe im Herzen von Mulgore, gibt Euch den dritten und letzten Schritt Eurer ersten Prüfungen im Zähmen von Wildtieren.",al={"questgeber","wer vergibt die quest","wo ist yaw scharfmähne"}},{q="Was geschieht, nachdem ich die Zähmerrute zurückgegeben habe?",a="Yaw Scharfmähne lehrt Euch die Euch innewohnenden Fähigkeiten, Wildtiere selbstständig zu zähmen, zu rufen und wegzuschicken. Er schickt Euch außerdem nach Donnerfels, damit Ihr lernt, Euren gewählten Gefährten auszubilden und zu versorgen.",al={"nächste lernschritte","belohnungen für den abschluss","was folgt nach dieser quest"}},{q="Wo finde ich wilde Swoops in Mulgore?",a="Wilde Swoops durchstreifen Mulg ores offenes Grasland und die Ränder der Tafelberge und kreisen oft über den Ebenen direkt vor dem Dorf der Bluthufe.",al={"swoopfundorte","wo sind swoops","swoop finden"}},{q="Warum gilt das Zähmen eines Tiergefährten bei den Tauren als Übergangsritus?",a="Tauren sehen Wildtiere als Mitgeschöpfe und Kinder der Erdenmutter, nicht als Werkzeuge. Eine Bindung zu einem Gefährten erfordert Geduld, gegenseitigen Respekt und spirituelles Gleichgewicht, nicht allein Gewalt.",al={"hintergrund der taurenjäger","spiritueller pfad des jägers","verbindung zur erdenmutter"}}},fx={["8301e163"]={q="Warum will Yaw Scharfmähne, dass ich einen Sturzflieger zähme?",a="Yaw Scharfmähne leitet Euch durch die letzte Prüfung Eurer Jägerausbildung. Indem Ihr lernt, eine Kreatur der Lüfte zu bezirzen, beweist Ihr Eure Meisterschaft über Bestien aller Bereiche. Sobald Ihr diese letzte Herausforderung unter der Gnade der Erdenmutter gemeistert habt, kann Yaw Euch endlich die dauerhafte Macht verleihen, einen Gefährten Eurer Wahl zu zähmen, zu beschwören und wieder fortzuschicken.",al={"yaw scharfmähnes motiv","warum einen sturzflieger zähmen","warum will yaw, dass das erledigt wird"}},fc772ddc={q="Warum lässt Yaw Scharfmähne mich diese Prüfung machen, anstatt sie selbst zu erledigen?",a="Yaw Scharfmähne hat den Weg des Jägers bereits gemeistert; seine Pflicht ist nun die eines Ausbilders und Ältestenführers im Dorf der Bluthufe. Zähmen ist keine Erledigung für Dorfwachen oder Mentoren, sondern ein wesentlicher, persönlicher Initiationsritus. Ihr müsst Euren eigenen Geist und Eure Bindung zur Natur beweisen, bevor man Euch einen lebenslangen tierischen Gefährten anvertrauen kann.",al={"warum ich zähmen der bestie","warum schickt mich yaw scharfmähne","warum muss ich den sturzflieger zähmen"}}},fp="16,283,18.312.0,22.371.0,50.219.0,45.157.0,48.146.0,43.190.0,40.118.0,58.164.0"}
P.entries["quest:6089"] = {n="Die Ausbildung des Tiers",s="In Mulgore führt Die Ausbildung des Tiers junge Taurenjäger beim Lernen an der Seite eines Tiers weiter. Nachdem sie die wilden Geschöpfe der Ebenen besänftigt haben, reisen sie nach Donnerfels, um die dauerhafte Bindung aus Fürsorge und Führung kennenzulernen.",h="In Mulgore führt Die Ausbildung des Tiers junge Taurenjäger beim Lernen an der Seite eines Tiers weiter.",kw={"tierausbildung","holt donnerhorn","die anhöhe der jäger","mulgore","taurenjäger","donnerfels","die ausbildung des tiers","yaw scharfmähne"},ang={["class:Hunter"]="Als Jäger lasst Ihr den einsamen Kampf hinter Euch und steht an der Seite eines treuen Begleiters. Dieser Ritus vollendet Eure erste Ausbildung zum Hüter der Wildnis.",["race:Tauren"]="Als Shu'halo zieht Ihr mit einem Tierbegleiter in den Kampf und tragt die heilige Pflicht, für ihn zu sorgen und die Geschöpfe der Erdenmutter zu achten."},sec={{t="Der Weg zum großen Fels",b="Taurenjäger in Mulgore haben sich Schreitern, Präriepirschern und Sturzfalken gestellt. Nun schickt Yaw Scharfmähne, ihr Mentor im Dorf der Bluthufe, jeden Neuling zur Anhöhe der Jäger in Donnerfels, um die volle Verantwortung eines Jägers zu übernehmen. Dort unterrichtet sie Holt Donnerhorn. Die Shu'halo ehren ihn für seinen Einklang mit der Wildnis, und seine Ehrfurcht vor der Erdenmutter ist noch größer."},{t="Ein heiliger Bund",b="Für die Tauren ist ein Tier ein Partner, verbunden durch Harmonie mit der Natur, niemals eine Waffe oder ein Knecht. Holt Donnerhorn lehrt Jäger, wie sie diese Bindung stark halten. Sie lernen, die Kampfinstinkte eines Geschöpfs zu lenken, es regelmäßig zu füttern und seine Verletzungen zu heilen. Fällt es bei der Verteidigung seines Gefährten auf den Ebenen, können sie seinen Geist zurückrufen."}},faq={{q="Mit wem spreche ich für diese Quest?",a="Sprecht mit Holt Donnerhorn oben auf der Anhöhe der Jäger in Donnerfels. Nach Euren ersten Prüfungen beim Zähmen wilder Tiere in Mulgore schickt Yaw Scharfmähne Euch zu ihm.",al={"quest abgeben","wer ist holt donnerhorn","wo ist holt"}},{q="Welche Fertigkeiten erlernen Taurenjäger beim Abschluss dieser Quest?",a="Holt Donnerhorn lehrt Euch, Eurem Begleiter neue Fähigkeiten beizubringen, ihn zu füttern, damit er treu und zufrieden bleibt, und ihn wiederzubeleben, falls er im Kampf stirbt.",al={"welche fähigkeiten gibt es","fertigkeiten als questbelohnung","was lehrt holt"}},{q="Wo steht diese Quest in der Questreihe für Taurenjäger?",a="Die Ausbildung des Tiers ist der letzte Schritt in der Questreihe für Jäger. Sie folgt auf „Der Weg des Jägers“ und die drei Prüfungen von „Die Zähmung der Bestie“, bei denen Ihr auf den Ebenen vorübergehend einen ausgewachsenen Schreiter, einen Präriepirscher und einen Sturzfalken besänftigt.",al={"jägerquestreihe","tierbegleiterquest mulgore","die ausbildung des tiers questreihe"}},{q="Warum genießt Holt Donnerhorn unter Taurenjägern so hohes Ansehen?",a="Holt hat sich ein Leben lang mit Azeroths wildesten Bestien gemessen und befehligt mehrere mächtige Begleiter. Er pflegt auch eine tiefe spirituelle Bindung zur Erdenmutter, und seine Weisheit macht ihn zum wichtigsten Lehrer junger Shu'halo-Jäger in Donnerfels.",al={"holt donnerhorn hintergrundgeschichte","wer ist holt"}},{q="Können Jäger ihren dauerhaften Tierbegleiter zähmen, bevor sie diese Quest abgeben?",a="Dank der vorherigen Prüfung könnt Ihr bereits wilde Tiere zähmen, doch bis Ihr mit Holt Donnerhorn sprecht, fehlt Euch das Wissen, Euren Begleiter zu füttern, wiederzubeleben oder ihm Fertigkeiten beizubringen.",al={"jetzt schon tierbegleiter zähmen","wann gibt es den tierbegleiter","ist die ausbildung des tiers nötig"}},{q="Warum ist die Pflege von Tierbegleitern in der Kultur der Tauren mit der Erdenmutter verbunden?",a="Tauren sehen jedes Lebewesen als Kind der Erdenmutter. Ein Jäger beherrscht ein Tier nicht durch bloße Willenskraft, sondern schließt einen spirituellen Bund und bietet Nahrung und Fürsorge im Austausch für Treue und Schutz.",al={"tauren tierbegleiter hintergrundgeschichte","erdenmutter tiere"}}},fx={["44ef2a73"]={q="Warum schickt Yaw Scharfmähne Euch zu Holt Donnerhorn?",a="Yaw Scharfmähne hat Euch gelehrt, wie man Bestien zähmt, aber sie zu befehligen und zu nähren erfordert tiefere Weisheit. Anstatt Eure Ausbildung halbfertig zu lassen, schickt er Euch zu Holt Donnerhorn auf der Anhöhe der Jäger in Donnerfels. Holt gehört zu den am meisten verehrten Jägern der Tauren, der bereits wilde Kreaturen in ganz Azeroth besiegt hat, und nur jemand mit seiner tiefen Bindung zur Erdenmutter kann die heiligen Verantwortungen der Aufzucht und Ausbildung eines tierischen Begleiters richtig vermitteln.",al={"warum schickt euch yaw weg","yaw scharfmähnes motiv","warum nach donnerfels"}}},fp="18,224,27.374.0,13.346.0,33.149.0,63.148.0,53.226.0,71.262.0,66.177.0,58.216.0"}
P.entries["quest:609"] = {n="Voodooschulden",s="In Beutebucht wartet „Seewolf“ MacKinley noch immer darauf, dass drei alte Schulden beglichen werden. Maury „Club Foot“ Wilkins, Jon-Jon the Crow und Chucky „Ten Thumbs“ schulden ihm Geld, doch Gerüchten zufolge irren sie durch Flüche und Verzauberungen in uralten Dschungelruinen umher. MacKinley will ihre wertvollsten Besitztümer, was auch immer ihr Schicksal sein mag.",h="In Beutebucht wartet „Seewolf“ MacKinley noch immer darauf, dass drei alte Schulden beglichen werden.",kw={"beutebucht","chucky ten thumbs","jon-jon the crow","maury club foot wilkins","ruinen von aboraz","ruinen von jubuwal","seewolf mackinley","schlingendorntal","voodooschulden"},sec={{t="Offene Rechnungen",b="Ihr habt bereits Schulden für „Seewolf“ MacKinley eingetrieben, doch drei Rechnungen sind noch offen. Maury „Club Foot“ Wilkins, Jon-Jon the Crow und Chucky „Ten Thumbs“ schulden ihm seit Monaten Geld. MacKinley dachte zunächst, sie hätten Beutebucht verlassen, um ihren Schulden zu entkommen. Dann hörte er, dass sie tief im Dschungel ein seltsameres, düstereres Schicksal ereilt hatte."},{t="Verhext in den Ruinen",b="Man munkelt, Flüche und Verzauberungen ließen die drei Männer durch uraltes Mauerwerk nordöstlich von Beutebucht irren. Sie sollen durch die Ruinen von Aboraz und die Ruinen von Jubuwal streifen. MacKinley will, dass Ihr jeden Mann findet und seine auffälligen Wertsachen an Euch nehmt: Jon-Jons goldenes Handfernrohr, Chuckys gewaltigen Ring und Maurys Klumpfuß."}},faq={{q="Wer bittet darum, diese Schulden einzutreiben?",a="„Seewolf“ MacKinley bittet Euch von seinem Posten in Beutebucht aus, die Schulden einzutreiben. Er arbeitet seine Liste von Schuldnern ab und wird ihre Schulden nicht unter den Tisch fallen lassen.",al={"wer vergibt voodooschulden","seewolf mackinley quest"}},{q="Wer sind die drei Schuldner?",a="Die drei Schuldner sind Maury „Club Foot“ Wilkins, Jon-Jon the Crow und Chucky „Ten Thumbs“. Ihre Zahlungen sind seit mehreren Monaten fällig.",al={"wer schuldet mackinley geld","voodooschulden ziele"}},{q="Wo sind die drei Schuldner zu finden?",a="Die drei Männer irren durch uralte Steinbauten nordöstlich von Beutebucht, in den Ruinen von Aboraz und den Ruinen von Jubuwal.",al={"wo sind die schuldner","wo sind aboraz und jubuwal"}},{q="Was ist den drei Männern zugestoßen?",a="MacKinley hat erfahren, dass die Männer verhext und verflucht wurden. Nun streifen sie durch die Dschungelruinen, statt in den Hafen zurückzukehren.",al={"warum sind sie verflucht","was stimmt mit ihnen nicht"}},{q="Welche Gegenstände müssen beschafft werden?",a="MacKinley will Jon-Jons goldenes Handfernrohr, Chuckys gewaltigen Ring und Maurys Klumpfuß.",al={"welche gegenstände will mackinley","voodooschulden gegenstände"}},{q="Was ging dieser Aufgabe in der Questreihe voraus?",a="Dies folgt auf Eure frühere Arbeit in Scaring Shaky und Return to MacKinley, bei der Ihr dem Piraten geholfen habt, seine Schulden einzutreiben.",al={"voodooschulden voraussetzungen","vorherige quest"}}},fp="11,316,15.341.0,22.321.0,37.164.0,26.149.0,37.118.0,31.124.0,38.88.0,40.110.0"}
P.entries["quest:61"] = {n="Lieferung nach Sturmwind",s="William Pestle schickt ein Paket aus Goldhain an seinen Bruder in Sturmwind. Mit den Kerzen darin gelangt Wachs von Kobolden im Wald von Elwynn zu Morgan in Pestle's Apothecary.",h="William Pestle schickt ein Paket aus Goldhain an seinen Bruder in Sturmwind.",kw={"wald von elwynn","goldhain","kobold candles","morgan pestle","pestle's apothecary","lieferung nach sturmwind","der handelsdistrikt","william pestle"},ang={["faction:Alliance"]="Als Streiter der Allianz bringt Ihr Vorräte auf der Königsstraße nach Sturmwind und zieht von Scharmützeln auf dem Land in Richtung Hauptstadt.",["profession:Herbalism"]="Das Familiengeschäft der Pestles hängt von örtlichen Reagenzien aus Elwynn ab. Ihr Laden in Sturmwind ist eine vertraute Anlaufstelle für Sammler und Trankbrauer."},sec={{t="Ein Familiengeschäft",b="William Pestle sammelt Kräuter, Reagenzien und Rohwaren in Goldhain. Sein Bruder Morgan führt Pestle's Apothecary im Handelsdistrikt von Sturmwind. William kann das Gasthaus \"Zur Höhle des Löwen\" nicht ohne Weiteres verlassen, also vertraut er Reisenden auf dem Weg in die Stadt seine Waren an."},{t="Vom Koboldwachs zu Hauptstadttränken",b="Williams Paket enthält große Kerzen, die von Kobolden in den Minen von Elwynn gesammelt wurden. Er sammelt sie wegen ihres Wachses, sagt aber nicht, wie die Brüder es verwenden. Ihr bringt die Lieferung zu Morgan in Pestle's Apothecary im Handelsdistrikt."}},faq={{q="Was enthält Williams Lieferung?",a="Die Lieferung enthält Kerzen, die von Kobolden im Wald von Elwynn gesammelt wurden. William sammelte sie wegen ihres Wachses und verpackte sie für Morgan in Pestle's Apothecary.",al={"inhalt der lieferung","was ist im paket","was hat william geschickt"}},{q="Wo finde ich Morgan Pestle?",a="Morgan Pestle arbeitet in Pestle's Apothecary im Handelsdistrikt von Sturmwind, nur einen kurzen Fußweg hinter den Haupttoren.",al={"morgan pestle standort","wo ist morgan","morgan pestle finden"}},{q="Wie sind William und Morgan Pestle miteinander verwandt?",a="William und Morgan Pestle sind Brüder, die gemeinsam ein alchemistisches Gewerbe betreiben. William sammelt Materialien im Wald von Elwynn, während Morgan ihren Laden in Sturmwind führt.",al={"pestle-brüder","wer ist william pestles bruder"}},{q="Warum liefert William das Paket nicht selbst aus?",a="William ist mit seinem Gewerbe und dem Sammeln alchemistischer Zutaten in Goldhain beschäftigt. Er verlässt sich auf Reisende, die ohnehin zur Hauptstadt unterwegs sind, um das Paket zu befördern.",al={"warum geht william nicht nach sturmwind","warum einen kurier anheuern"}},{q="Haben Koboldkerzen tatsächlich einen alchemistischen Nutzen?",a="William sagt, dass er und sein Bruder die Kerzen wegen ihres Wachses brauchen. Er erklärt nicht, wie sie es in der Apotheke verwenden.",al={"warum koboldkerzen","koboldwachs alchemie"}},{q="Was folgt nach der Ablieferung?",a="Mit der Ablieferung endet die kurze Questreihe, die mit dem Sammeln von Koboldkerzen im Wald von Elwynn begann. Morgan bezahlt Euch für den Transport des Pakets und heißt Euch als Kunden in seinem Laden willkommen.",al={"was folgt nach lieferung nach sturmwind","folgequest lieferung nach sturmwind"}}},fx={e0018b76={q="Warum möchte William Pestle, dass diese Lieferung zugestellt wird?",a="Morgan wartet in der Apotheke der Brüder in Sturmwind auf die Kerzenlieferung. William hat sie wegen ihres Wachses gesammelt, hat aber keine Zeit für die Reise, also bittet er einen Reisenden, die Vorräte zu befördern.",al={"warum die lieferung schicken","william pestles motiv","warum die kerzen liefern"}}},fp="21,168,14.254.0,34.230.0,34.157.0,30.116.0,42.168.0,48.165.0,48.118.0,41.183.0"}
P.entries["quest:610"] = {n="Schönling Duncan",s="Catelyn die Klinge hat den Dolch verloren, den sie auf Bitten ihres Vaters zurückgeben sollte. Sie will ihn von Schönling Duncan zurück, bevor sie Euch weiterhilft.",h="Catelyn die Klinge hat den Dolch verloren, den sie auf Bitten ihres Vaters zurückgeben sollte.",kw={"blutsegelbukaniere","beutebucht","catelyn die klinge","catelyns klinge","schönling duncan","schlingendorntal"},ang={["class:Mage"]="Als Magier hört Ihr vielleicht, wie Catelyn über arkane Gelehrte spottet. Sie sagt, sie sei von zu Hause geflohen, um ihre Tage nicht unter verstaubten, grauhaarigen Zauberwirkern verbringen zu müssen."},sec={{t="Der Groll eines Piraten",b="Catelyn die Klinge hat die Magier und ihre staubigen Wälzer hinter sich gelassen. Ansirem's Key hat Euch zu ihr geführt, doch sie kann Euch den Dolch nicht geben, den sie auf Bitten ihres Vaters zurückgeben sollte. Ein Blutsegelbukanier hat ihn ihr abgenommen. Solange ihre Klinge nicht wiederbeschafft ist, wird Catelyn nichts anderes herausgeben."},{t="Der gestohlene Stahl",b="Schönling Duncan schlug Catelyn bewusstlos und nahm ihr das Messer ab, das sie im Kampf trug. Sie verlässt sich auf diese Waffe. Nun besteht sie darauf, genau diese Klinge vom Bukanier zurückzubekommen, bevor sie Euch weiterhilft."}},faq={{q="Wer ist Schönling Duncan?",a="Schönling Duncan ist ein Blutsegelbukanier in der Nähe von Beutebucht. Er besiegte Catelyn die Klinge, schlug sie bewusstlos und nahm ihren Dolch an sich.",al={"schönling duncan","wer ist duncan","duncan pirat"}},{q="Warum will Catelyn ihren Dolch zurück?",a="Catelyn verlässt sich im Kampf auf ihr Messer und gibt sich mit keinem anderen zufrieden. Sie will den Dolch zurück, den Duncan ihr abgenommen hat, bevor sie jemandem hilft, der nach ihr sucht.",al={"catelyn dolch","catelyn messer","warum die klinge zurückholen"}},{q="Warum ist Catelyn von zu Hause fortgelaufen?",a="Catelyn verließ ihre Familie, um einem eintönigen Leben mit alten Büchern unter starren, betagten Magiern zu entkommen. Sie weigerte sich, ihre Tage so zu verbringen.",al={"warum catelyn fortlief","ansirems tochter","catelyns vorgeschichte"}},{q="Wo fügt sich dieser Schritt in die Suche ein?",a="Diese Begegnung folgt auf die Wiederbeschaffung von Ansirem's Key und findet statt, bevor die Suche The Curse of the Tides aufdeckt.",al={"questreihe","was führt zu schönling duncan"}}},fp="19,140,20.261.0,16.211.0,25.135.0,38.150.0,35.128.0,41.113.0"}
P.entries["quest:6101"] = {n="Die Zähmung der Bestie",s="In Dolanaar führt Dazalar Euch durch eine zweite Prüfung für Nachtelfenjäger. Mit einer verzauberten Zähmerrute unterwerft Ihr einen nightsaber stalker und lernt, wie sich wilde Tiere unterscheiden.",h="In Dolanaar führt Dazalar Euch durch eine zweite Prüfung für Nachtelfenjäger.",kw={"wildtiere zähmen","dazalar","dolanaar","jäger","nightsaber stalker","zähmerrute","teldrassil"},ang={["class:Hunter"]="Als Jäger lernt Ihr, die unterschiedlichen Temperamente der Tiere zu achten, bevor Ihr Euch einen lebenslangen Gefährten verdient.",["race:NightElf"]="Als Nachtelf erreicht Ihr einen traditionellen Meilenstein für Waldspäher: die Zähmung eines Nachtsäblers, eines Geschöpfs, das mit der Geschichte und Kultur der Kaldorei verwoben ist."},sec={{t="Die wechselhafte Natur der Tiere",b="Dazalar lehrt Euch, dass sich die Geschöpfe des Waldes nicht alle gleich verhalten. Jede Art hat ihr eigenes Temperament, und ein Jäger muss lernen, damit umzugehen. Unter Teldrassils Blätterdach stellt Euch diese Prüfung Tieren gegenüber, die gerissener und raubgieriger sind als Webspinner."},{t="Den Nachtsäbler unterwerfen",b="Kaldorei verehren Nachtsäbler als heilige Raubtiere, grimmige Wächter und Gefährten der Schildwachen. Mit der Zähmerrute tretet Ihr einem nightsaber stalker gegenüber und müsst dabei die Nerven bewahren und ruhige Autorität ausstrahlen. Sein Vertrauen zu gewinnen beweist, dass Ihr mit einem Raubtier umgehen könnt, ebenso wie mit den sanfteren Geschöpfen des Waldes."}},faq={{q="Was ist das Ziel dieser Quest?",a="Dazalar schickt Euch los, einen nightsaber stalker zu zähmen und zu lernen, wie sich verschiedene Raubtiere verhalten. Dies ist die zweite Prüfung in der Ausbildung eines Nachtelfenjägers; der Abschluss der gesamten dreiteiligen Prüfung schaltet das dauerhafte Zähmen von Wildtieren frei.",al={"warum diese quest machen","begleiter zähmen quest zwei","ziel der nachtsäblerzähmung"}},{q="Wo sind nightsaber stalker zu finden?",a="Nightsaber stalker streifen auf den Waldpfaden und im Unterholz südlich von Dolanaar im Zentrum von Teldrassil umher.",al={"wo sind nightsaber stalker","stalker fundort","wo die katze finden"}},{q="Darf ich den nightsaber stalker als dauerhaften Begleiter behalten?",a="Nein. Die Rute zähmt das Tier nur zur Übung. Nachdem Ihr alle drei Prüfungen abgeschlossen und die Rute zurückgegeben habt, lernt Ihr, Wildtiere dauerhaft zu zähmen und einen Gefährten auszuwählen.",al={"begleiter behalten","nachtsäbler behalten","begleiter für immer"}},{q="Wer vergibt diese Quest?",a="Dazalar, der Jägerlehrer in Dolanaar, erteilt Euch diese Aufgabe, nachdem Ihr Eure erste Zähmungsprüfung abgeschlossen habt.",al={"questgeber","wer startet die quest","dazalar standort"}},{q="Warum verehren Nachtelfen Nachtsäbler so sehr?",a="Kaldorei leben seit Jahrtausenden an der Seite von Nachtsäblern. Schildwachen und Priesterinnen von Elune haben sie als Gefährten, Späher und Kriegsreittiere eingesetzt, und einen zu zähmen bezeugt die stolze Beherrschung der Waldkünste.",al={"hintergrund zu nachtelfenkatzen","warum nachtsäbler wichtig sind","hintergrund zu nachtsäblern"}},{q="Was folgt nach dem Abschluss dieser Aufgabe?",a="Dazalar gibt Euch eine letzte Zähmungsaufgabe mit einem weiteren Geschöpf Teldrassils. Danach lehrt er Euch, überall in Azeroth dauerhafte Gefährten zu zähmen, zu füttern und zu versorgen.",al={"nächste quest","was folgt nach nightsaber stalker","nächste jägerprüfung"}}},fx={["878d77ca"]={q="Warum will Dazalar, dass Ihr einen Nachtsäbelpirscher zähmt?",a="Dazalar möchte Euch lehren, dass die Vielfalt der Natur sich ständig wandelt und doch verlässlich ist. Indem er Euch durch verschiedene Kreaturen führt, möchte er, dass Ihr das einzigartige Temperament und den Geist jedes Tieres wahrnehmt, um sicherzustellen, dass Ihr lernt, mit verschiedenen Gefährten auf ganz Teldrassil in Einklang zu kommen.",al={"warum nachtsäbelpirscher zähmen","dazalars motiv","warum nachtsäbelpirscher"}},a23887a1={q="Was ist ein Nachtsäbelpirscher und warum sucht Ihr ihn?",a="Nachtsäbelpirscher sind räuberische Großkatzen, die in den schattigen Ästen und Wäldern von Teldrassil beheimatet sind. Dazalar schickt Euch hinter einem her, damit Ihr lernt, eine Bindung mit einem schlauen, flinken Jäger einzugehen, und lernt, seinen Instinkt und sein Gleichgewicht innerhalb der Wildnis zu respektieren.",al={"was ist ein nachtsäbelpirscher","nachtsäbelpirscher in teldrassil","warum nachtsäbelpirscher jagen"}}},fp="16,173,29.251.0,23.296.0,34.218.0,39.99.0,60.161.0,21.110.0,48.196.0,38.170.0"}
P.entries["quest:6102"] = {n="Die Zähmung der Bestie",s="In Dolanaar führt „Die Zähmung der Bestie“ einen jungen Nachtelfenjäger zur letzten Prüfung seiner Grundausbildung. Unter Dazalars Anleitung zähmt der Jäger eine räuberische Eule der Lüfte, bevor er die Fähigkeit erlangt, einen lebenslangen Gefährten zu wählen.",h="In Dolanaar führt „Die Zähmung der Bestie“ einen jungen Nachtelfenjäger zur letzten Prüfung seiner...",kw={"bestie","dazalar","dolanaar","jägerbegleiter","screecher","strigid screecher","zähmung","zähmerrute","teldrassil"},ang={["class:Hunter"]="Für Euch als Jäger markiert dieser Ritus den Übergang vom einsamen Kampf zu einem lebenslangen Band mit einem wilden Gefährten.",["race:NightElf"]="Als Nachtelf folgt Ihr durch die Zähmung der heimischen Tierwelt Teldrassils dem Weg der Kaldorei, im Einklang mit der Natur zu leben, statt sie mit Gewalt zu beugen."},sec={{t="Meisterschaft im Blätterdach",b="Nachtelfenjäger müssen mit Kreaturen in ganz Teldrassil Frieden schließen, um ihre grundlegende Tierkunde abzuschließen. Nachdem sie sich Bestien des Unterholzes gestellt haben, begegnen sie dem Geist der Lüfte: dem Strigid Screecher. Diese wachsamen Raubvögel nisten hoch im Geäst westlich von Dolanaar. Geduld und ruhige Nerven sind nötig, um einen von ihnen mit der verzauberten Zähmerrute zu besänftigen."},{t="Das Band eines Jägers",b="Die Zähmung des Strigid Screecher vollendet die uralten Lehren des Einklangs zwischen Kaldoreijägern und der Natur. Der Lehrling bringt die verbrauchte Rute zu Dazalar zurück, und die Ausbildungsübungen enden. Dann erlernt der Jäger die vollständige Kunst, Bestien seiner Wahl in ganz Azeroth herbeizurufen, wegzuschicken und dauerhaft zu zähmen."}},faq={{q="Wo sind Strigid Screechers zu finden?",a="Strigid Screechers nisten in den Wäldern westlich von Dolanaar. Jäger suchen diese Raubvögel zwischen Blätterdach und Wurzeln außerhalb des Dorfes, um ihre Rute zu erproben.",al={"screecher fundort","wo ist strigid screecher","eule fundort"}},{q="Wer ist Dazalar?",a="Dazalar ist ein Nachtelf und Jägerlehrer in Dolanaar. Er leitet junge Kaldorei an, die die Grundlagen des Bogenschießens und der Fährtensuche erlernt haben. Er prüft sie an Bestien des Landes und der Lüfte, bevor er ihnen die Fähigkeit verleiht, einen echten tierischen Gefährten an sich zu binden.",al={"dazalars rolle","wer lehrt begleiterzähmung in dolanaar","jägerlehrer dolanaar"}},{q="Darf ich den Strigid Screecher als Begleiter behalten?",a="Nein. Der während dieser Prüfung gezähmte Strigid Screecher ist nur vorübergehend durch die Magie der Zähmerrute gebunden. Wenn die Prüfung endet, gibt der Jäger die Rute ab und lernt, in der Wildnis einen dauerhaften Gefährten seiner Wahl zu zähmen.",al={"eule behalten","ist screecher dauerhaft","bleibt dieser begleiter"}},{q="Was geschieht nach Abschluss dieser Prüfung?",a="Dazalar verleiht Euch die Fähigkeit, Bestien dauerhaft zu zähmen, herbeizurufen und wegzuschicken. Er verweist Euch zur weiteren Ausbildung nach Darnassus, wo Ihr lernen könnt, Euren Gefährten zu füttern und ihm das Kämpfen beizubringen.",al={"what comes next","nach der zähmung der bestie","jägerbegleiterquest abschließen"}},{q="Warum zähmen Nachtelfen gerade Eulen?",a="Eulen und andere Raubvögel haben für die Kaldorei als wachsame Jäger der Nacht und vertraute Späher eine tiefe kulturelle Bedeutung. Die Beherrschung eines Geschöpfs der Lüfte beweist, dass Ihr Raubtiere der Lüfte ebenso versteht wie Bestien am Boden.",al={"eulen hintergrund nachtelf","warum eulen","strigid screecher bedeutung"}},{q="Können Jäger nach dieser Quest jedes Tier wählen?",a="Ja. Sobald Ihr die Fähigkeit erlangt, Bestien dauerhaft zu zähmen, könnt Ihr in ganz Teldrassil und darüber hinaus nach jedem zähmbaren Geschöpf des Landes, des Wassers oder der Lüfte suchen.",al={"welche begleiter sind verfügbar","ersten begleiter wählen","jede bestie zähmbar"}}},fx={fcfecb3c={q="Warum lässt Dazalar Euch einen Strigidenschreier zähmen?",a="Dies ist Eure letzte Prüfung als angehender Jäger. Nachdem Ihr Eure Fähigkeit bewiesen habt, mit zwei verschiedenen Kreaturen des Landes umzugehen, verlangt Dazalar von Euch, dass Ihr eine meistert, die den Himmel beherrscht. Indem Ihr einen wilden Strigidenschreier zähmt, zeigt Ihr, dass Eure Empathie und Autorität über Bestien über die Erde hinausgehen, was beweist, dass Ihr bereit seid, eine dauerhafte Bindung mit einem eigenen Gefährten einzugehen.",al={"warum strigidenschreier zähmen","dazalars motiv","warum eulenprüfung"}},ebb229ae={q="Was sind Strigidenschreier?",a="Strigidenschreier sind große, räuberische Eulen, die in den Ästen von Teldrassil beheimatet sind. Sie werden von Nachtelfenjägern wegen ihrer scharfen Sicht und ihres lautlosen Fluges verehrt und jagen in den Wäldern westlich von Dolanaar. Ihre wilde Natur und ihre Anmut in der Luft machen sie zu einem idealen Test für die Geduld, den Fokus und den Befehl eines Jägers, bevor er eine dauerhafte Bindung zu einer Bestie eingeht.",al={"strigidenschreier","strigidenschreier-kunde","schreiereulen in teldrassil"}}},fp="16,230,21.353.0,15.316.0,35.156.0,15.231.0,49.231.0,41.190.0,42.231.0,47.146.0"}
P.entries["quest:6103"] = {n="Die Ausbildung des Tiers",s="In Teldrassil verlassen Nachtelfenjäger die Wildnis in Richtung Darnassus, nachdem sie im Geäst Tiere gezähmt haben. Dort lehrt Jocaste sie, einen Begleiter zu pflegen und zu disziplinieren.",h="In Teldrassil verlassen Nachtelfenjäger die Wildnis in Richtung Darnassus, nachdem sie im Geäst Tiere gezähmt...",kw={"die enklave des cenarius","darnassus","dazalar","jägerbegleiter","jocaste","teldrassil","die ausbildung des tiers"},ang={["class:Hunter"]="Als Jäger lernt Ihr, Euren Begleiter auszubilden, zu füttern und wiederzubeleben, während Ihr den Pfad des Anfängers hinter Euch lasst.",["race:NightElf"]="Als Nachtelf teilt Ihr eine Tradition der Gemeinschaft mit Tieren, die auf Respekt und Zusammenleben beruht. Ihr lernt sie in der Enklave des Cenarius in Darnassus."},sec={{t="Der Übergangsritus eines Jägers",b="Dazalar schickt Euch aus der Wildnis nahe Dolanaar nach Darnassus, nachdem Ihr bewiesen habt, dass Ihr ein Tier zähmen könnt. Bevor Ihr mit einem treuen Begleiter durch Kalimdor reist, braucht Ihr mehr als Geschick mit einer Zähmerrute. Eine wilde Kreatur zu unterwerfen, stellt Eure Stärke und Euren Willen auf die Probe, doch ein ungeschultes Tier kann noch immer unberechenbar sein."},{t="Unterweisung in der Enklave des Cenarius",b="In der Enklave des Cenarius in Darnassus lehrt Jocaste Euch, für einen Begleiter zu sorgen. Sie zeigt Euch, wie Ihr Euren Begleiter füttert, ihn zurückholt, wenn ein Unglück geschieht, und ihn für den Kampf ausbildet. Für Nachtelfen spiegelt diese Bindung Ehrfurcht vor der Natur wider, nicht bloße Kontrolle."}},faq={{q="Was ist der Zweck dieser Quest?",a="Ihr reist nach Darnassus, um zu lernen, wie Ihr einen dauerhaften tierischen Begleiter pflegt und ausbildet. Diese Lektionen schließen die ersten Schritte der Ausbildung eines Nachtelfenjägers im Umgang mit einem Begleiter ab.",al={"warum diese quest machen","quest begleiterausbildung nachtelf","was bewirkt die ausbildung des tiers"}},{q="Wo finde ich Jocaste?",a="Jocaste befindet sich in der Enklave des Cenarius in Darnassus, zwischen den Bäumen und Jägerhütten im Nordwesten der Stadt.",al={"wo ist jocaste","jocaste standort","jocaste finden"}},{q="Wer vergibt die Quest?",a="Dazalar, der Jägerlehrer in Dolanaar, schickt Euch los, nachdem Ihr alle drei Zähmprüfungen in ganz Teldrassil abgeschlossen habt.",al={"questgeber","wer vergibt die ausbildung des tiers","dazalar standort"}},{q="Welche Fertigkeiten lernt Ihr von Jocaste?",a="Jocaste lehrt Euch, Euren Begleiter zu füttern, ihn wiederzubeleben, wenn er im Kampf fällt, und ihm neue Fähigkeiten beizubringen.",al={"welche fähigkeiten erhält man","jocaste belohnungen","zauber für jägerbegleiter"}},{q="Warum legt die Kultur der Nachtelfen Wert auf die Ausbildung von Begleitern?",a="Nachtelfenjäger behandeln ihre Begleiter als Partner, nicht als Werkzeuge, denen sie Befehle erteilen. Ihre Fürsorge spiegelt Respekt vor der Natur und den Wunsch wider, im Einklang mit ihr zu leben.",al={"geschichte der nachtelfenjäger","warum bilden nachtelfen tiere aus"}},{q="Ist diese Quest auch für andere Völker verfügbar?",a="Diese Reise nach Darnassus ist für Nachtelfenjäger bestimmt. Jäger anderer Völker lernen ähnliche Fertigkeiten von Lehrmeistern ihres eigenen Volkes.",al={"können zwerge diese quest machen","kann die horde die ausbildung des tiers machen"}}},fx={["1a4b70d0"]={q="Warum schickt Dazalar Euch zu Jocaste?",a="Dazalar hat Euch gelehrt, wie man wilde Bestien zähmt, aber die Loyalität einer Kreatur zu gewinnen, ist nur der erste Schritt. Ohne richtige Anleitung bei der Fütterung, Pflege und Unterweisung Eures Gefährten kann die Bindung zwischen Jäger und Bestie nicht gedeihen. Er schickt Euch nach Darnassus, weil Jocaste zu den am meisten verehrten Jägern der Nachtelfen gehört und über die alte Weisheit verfügt, die erforderlich ist, um einen unerfahrenen Fährtenleser zu einem wahren Meister der Bestien zu erheben.",al={"warum will dazalar, dass das erledigt wird","dazalars motiv","warum zum jägerlehrer nach darnassus"}}},fp="18,168,26.297.0,32.248.0,34.166.0,24.102.0,21.112.0,38.107.0,50.141.0,39.127.0"}
P.entries["quest:611"] = {n="Der Fluch der Gezeiten",s="Vor der Küste des Schlingendorntals leiht Euch Catelyn die Klinge ihr wiederbeschafftes Messer, um damit auf einen versunkenen Altar einzuschlagen. Baron Revilgaz in Beutebucht sucht den Stein der Gezeiten für seine Sammlung alter Trollartefakte.",h="Vor der Küste des Schlingendorntals leiht Euch Catelyn die Klinge ihr wiederbeschafftes Messer, um damit auf...",kw={"altar of the tides","baron revilgaz","beutebucht","catelyn die klinge","gazban","stein der gezeiten","schlingendorntal","das finstere riff"},ang={["faction:Alliance"]="Als Abenteurer der Allianz schließt Ihr Baron Revilgaz' Suche nach dem alten Relikt in den Gewässern nahe dem Lager der Horde beim Basislager Grom'gol ab."},sec={{t="Der versunkene Altar",b="Catelyn die Klinge leiht Euch ihren wiederbeschafften Trolldolch, um einen Altar unter den Wellen zu zerstören. Sie weiß weniger über Trollruinen als ihr Vater, hat aber von einer versunkenen Trollstadt gehört. Deshalb weist sie Euch nach Nordwesten, vom Basislager Grom'gol aus. Dort, in den Unterwasserruinen des Finsteren Riffs, leuchtet der Altar of the Tides blau zwischen Meereslebewesen und Murlocs."},{t="Der gefangene Magier",b="Ein Schlag mit Catelyns Klinge gegen den Altar of the Tides bricht dessen Magie und lockt Gazban hervor, einen Goblinmagier, der den Stein der Gezeiten trägt. Wird Gazban herausgefordert, nimmt er die Gestalt eines Wasserelementars an. Sobald Ihr ihn bezwungen habt, könnt Ihr den Stein und den geliehenen Dolch nach Beutebucht zurückbringen. Baron Revilgaz hat inmitten seiner kostbaren Sammlung einen besonderen Ausstellungsständer für die im Relikt eingefangene Meeresmagie vorbereitet."}},faq={{q="Wo befindet sich der Altar of the Tides?",a="Der Altar of the Tides liegt unter dem Meer im Finsteren Riff, einer versunkenen Ruine nordwestlich des Basislagers Grom'gol. Sein blaues Leuchten ist unter Wasser leicht zu erkennen.",al={"wo ist der altar","altar of the tides standort","wo finde ich den altar"}},{q="Warum will Baron Revilgaz den Stein?",a="Baron Revilgaz sammelt alte Trollantiquitäten. Er hat Platz geschaffen und einen edlen Ständer gekauft, um das Relikt auszustellen.",al={"revilgaz stein","warum revilgaz den stein will","was macht revilgaz damit"}},{q="Warum verleiht Catelyn ihre Klinge?",a="Catelyn leiht Euch ihr wiederbeschafftes besonderes Messer, um den Altar zu zerschmettern, und bittet Euch, es nach vollbrachter Tat unversehrt zurückzubringen.",al={"catelyn messer","warum das messer verleihen","catelyn klinge"}}},fp="22,204,16.333.0,16.407.1,40.149.0,39.117.0,32.121.0"}
P.entries["quest:6121"] = {n="Neue Lektionen",s="Mathrengyl Bärenfährte schickt Allianz-Druiden von Darnassus nach Mondlichtung, um die Reinigung von Giften zu erlernen. Dort beginnt Dendrite Sternenschauer ihre Unterweisung über Gifte und Toxine.",h="Mathrengyl Bärenfährte schickt Allianz-Druiden von Darnassus nach Mondlichtung, um die Reinigung von Giften...",kw={"auberdine","cenarius","cure poison","dendrite sternenschauer","neue lektionen","mathrengyl bärenfährte","mondlichtung","nachthafen","power over poison"},ang={["class:Druid"]="Als Druide geht Ihr über die Grundlagen der Gestaltwandlung und des Überlebens hinaus, um für die Wildnis zu sorgen. Ihr lernt, die Natur von tödlichem Verderben und Giften zu befreien.",["faction:Alliance"]="Als Mitglied der Allianz erkennt Ihr, wie lebenswichtig druidische Hilfe für die gefährdeten nördlichen Siedlungen der Dunkelküste ist, darunter Auberdine.",["race:NightElf"]="Von der Enklave des Cenarius in Darnassus aus werdet Ihr zu den tieferen, althergebrachten Pflichten geführt, die mit Mondlichtung und der Dunkelküste verbunden sind."},sec={{t="Eine Gabe von Cenarius",b="Cenarius lehrt Druiden und segnet sie mit einer Verbindung zur lebendigen Welt. Zu seinen Gaben gehört die Macht, Gift mit einer einfachen Beschwörung zu reinigen. Solche Macht bringt eine Bürde mit sich. Bevor junge Druiden sie einsetzen, lernen sie die harte, gewöhnliche Arbeit kennen, Toxine ohne die Magie der Natur zu bekämpfen."},{t="Ruf nach Nachthafen",b="Mathrengyl Bärenfährte bildet Druiden in der Enklave des Cenarius in Darnassus aus. Nun schickt er seinen Schüler über die örtlichen Übungen hinaus nach Mondlichtung. In Nachthafen koordiniert Dendrite Sternenschauer die überregionalen Bemühungen des Zirkels des Cenarius. Er hat praktische Arbeit für den Novizen."},{t="Eine wirkliche Krise",b="Die Initianden von Nachthafen stehen vor einer wirklichen Krise, keiner inszenierten Prüfung und keinem Ritual. Auberdine an der Küste der Dunkelküste leidet unter einer Welle von Tiervergiftungen, die seine Bewohner nicht aufhalten können. Dendrite Sternenschauer schickt den Novizen los, um Nachforschungen anzustellen und der Dunkelküste beizustehen. Leben stehen auf dem Spiel."}},faq={{q="Wer bietet die Quest Neue Lektionen an?",a="Mathrengyl Bärenfährte, der nachtelfische Druidenlehrer in der Enklave des Cenarius in Darnassus, bietet sie an.",al={"wer vergibt neue lektionen","neue lektionen questgeber","mathrengyl bärenfährte quest"}},{q="Wohin muss ich gehen, um diese Quest abzuschließen?",a="Reist nach Mondlichtung und meldet Euch bei Dendrite Sternenschauer in Nachthafen.",al={"wohin geht es","wo ist dendrite sternenschauer","neue lektionen abgeben"}},{q="Warum müssen Druiden zunächst lernen, Gifte wie ein Laie zu heilen?",a="Druidenlehrer fürchten, dass Cenarius' Gabe, Gift mit einer Beschwörung zu heilen, zu Selbstzufriedenheit führen könnte. Indem Initianden zunächst gewöhnliche Wege erlernen, Gift zu bekämpfen, erfahren sie, welche Bürde und welches Leid es mit sich bringt.",al={"warum wie ein laie","warum gift ohne magie heilen","cenarius giftlektion"}},{q="Welches Problem gibt es in Auberdine?",a="Auberdine leidet unter schweren Tiervergiftungen entlang der Küste der Dunkelküste. Die örtlichen Nachtelfen können sie nicht heilen und haben den Zirkel des Cenarius in Mondlichtung um Hilfe gebeten.",al={"auberdine giftproblem","was geschieht in auberdine","dunkelküste tiervergiftungen"}},{q="Welche Fähigkeit gewährt diese Questreihe schließlich?",a="Die Reihe beginnt mit Power over Poison, wodurch Druiden Cure Poison erlernen, einen Zauber, der Verbündete auf magische Weise von Toxinen reinigt.",al={"welche belohnung gibt es","cure poison quest","power over poison questreihe"}},{q="Ist diese Quest für Druiden der Horde verfügbar?",a="Nein. Neue Lektionen beginnt für Allianz-Druiden in Darnassus. Tauren-Druiden erhalten einen entsprechenden Einstieg in Donnerfels, der sie ebenfalls nach Mondlichtung schickt, um die Heilung von Giften zu erlernen.",al={"horde neue lektionen","können tauren das machen","tauren neue lektionen"}}},fx={cb6ddbb8={q="Warum schickt Mathrengyl Bärenfährte Euch zur Mondlichtung?",a="Als Euer Mentor in Darnassus erkennt Mathrengyl Bärenfährte, dass Eure druidische Ausbildung den Punkt erreicht hat, an dem Ihr den Segen des Cenarius über Gifte ausüben könnt. Er kann diese heilige Kunst nicht beiläufig verleihen; die druidische Tradition verlangt, dass Ihr unter Dendrite Sternenschauer in der Mondlichtung lernt, um sicherzustellen, dass Ihr die schwere Last des Giftes versteht, bevor Ihr die Gabe meistert, es zu reinigen.",al={"warum schickt mich mathrengyl","warum druide zur mondlichtung","warum ich neue lektionen"}}},fp="12,182,20.286.0,21.255.0,19.265.1,34.94.0,45.67.0,58.198.0,42.166.0,52.126.0,40.178.0"}
P.entries["quest:6122"] = {n="Die eigentliche Ursache",s="An den Cliffspring Falls haben kranke Hirsche den Zirkel des Cenarius ans Wasser geführt. Dendrite Sternenschauer schickt junge Druiden aus Mondlichtung los, um eine Probe für die Naturforscherin Alanndarian Nachtweise aus Auberdine zu sammeln.",h="An den Cliffspring Falls haben kranke Hirsche den Zirkel des Cenarius ans Wasser geführt.",kw={"alanndarian nachtweise","auberdine","zirkel des cenarius","cliffspring falls","gift heilen","dunkelküste","dendrite sternenschauer","naga","power over poison"},ang={["class:Druid"]="Als Druide stellt Ihr Euch der Verderbnis an den Cliffspring Falls und helft bei der Herstellung von Heilmitteln. Diese Prüfung lehrt Euch, wie Ihr Gifte in der Wildnis heilt.",["race:NightElf"]="Als Nachtelf aus Auberdine seht Ihr, wie die Verderbnis der Cliffspring Falls Eure angestammten Wälder und die dort lebenden Geschöpfe bedroht."},sec={{t="Eine lebenswichtige Wasserader verdirbt",b="Die Cliffspring Falls versorgen den Norden von Dunkelküste mit Süßwasser. Als Hirsche an einer schleichenden Krankheit zu leiden begannen, suchte der Zirkel des Cenarius deren Ursache im Fluss. Dendrite Sternenschauer in Mondlichtung vermutet, dass das Wasser verunreinigt ist. Er schickt Druidenneulinge los, um am Höhleneingang unterhalb der Wasserfälle eine Probe zu sammeln."},{t="Schatten an den Wasserfällen",b="Boshafte Naga hausen in der Cliffspring River Cave, nahe dem Quellgebiet der Wasserfälle. Ihre Anwesenheit gefährdet jeden, der die Verderbnis untersuchen will. Der Zirkel des Cenarius braucht eine Probe vom Höhleneingang, um herauszufinden, was die Wildnis krank macht."},{t="Ein tieferes Leiden",b="In Auberdine stellt Alanndarian Nachtweise fest, dass die Wasserprobe die Befürchtungen des Zirkels bestätigt. Die verderbten Wasserfälle vergiften die Flussufer, doch auch abseits des unmittelbaren Wasserlaufs wurden kranke Hirsche gesichtet.\n\nDie Probe könnte helfen, mit der Herstellung eines Gegengifts zu beginnen. Alanndarian vermutet, dass sich eine weiter reichende Verderbnis im Grundwasser von Dunkelküste ausbreitet."}},faq={{q="Warum sind die Cliffspring Falls so wichtig für Dunkelküste?",a="Die Cliffspring Falls versorgen den Norden von Dunkelküste mit Süßwasser. Ihr Quellwasser speist die örtlichen Bäche und Flüsse, sodass sich Verunreinigungen im umliegenden Land und unter den Wildtieren ausbreiten können.",al={"warum cliffspring falls wichtig sind","bedeutung des klippenquells","wasserquelle von dunkelküste"}},{q="Warum erkranken die Hirsche in Dunkelküste?",a="Die Hirsche trinken aus den Cliffspring Falls und den Bächen, die sie speisen. Das Wasser ist an seiner Quelle verunreinigt, und der Schadstoff macht die Waldtiere krank.",al={"warum sind die hirsche krank","kranke hirsche in dunkelküste","was hat die hirsche vergiftet"}},{q="Wer ist Dendrite Sternenschauer?",a="Dendrite Sternenschauer ist ein altgedienter Druidenlehrer in Mondlichtung. Er leitet junge Druiden an, hält in ganz Kalimdor nach Störungen Ausschau und koordiniert die Maßnahmen des Zirkels des Cenarius bei Naturkrisen.",al={"geschichte von dendrite sternenschauer","wer hat mir diese quest gegeben","sternenschauer mondlichtung"}},{q="Wer ist Alanndarian Nachtweise?",a="Alanndarian Nachtweise ist eine Naturforscherin der Nachtelfen in Auberdine. Besorgt über die Verderbnis und die leidenden Wildtiere in Dunkelküste bat sie den Zirkel des Cenarius in Mondlichtung um Hilfe bei der Erforschung des Leidens und der Suche nach einem Heilmittel.",al={"wer ist alanndarian nachtweise","nachtweise auberdine"}},{q="Warum sind Naga an den Cliffspring Falls?",a="Naga von der Küste Dunkelküstes sind ins Landesinnere gezogen und haben das Höhlensystem hinter den Cliffspring Falls besetzt. Ihre Anwesenheit gefährdet jeden, der das Quellgebiet erreichen und das Wasser untersuchen will.",al={"naga in cliffspring cave","warum sind hier naga","cliffspring falls naga"}},{q="Welche Fähigkeit hilft diese Quest Druiden zu erlernen?",a="Die Untersuchung ist Teil der Prüfung Power over Poison. Indem Druidenanwärter die Krankheit der Wildtiere erforschen und mit Alanndarian Nachtweise an einem Gegengift arbeiten, lernen sie, Gifte zu heilen.",al={"welchen zauber gibt diese quest","druidenquest zu gift","questreihe zum heilen von gift"}}},fx={df1ca1a8={q="Warum will Dendrite Sternenschauer, dass das getan wird?",a="Als Abgesandter des Zirkels des Cenarius in der Mondlichtung ist Dendrite Sternenschauer daran gebunden, das natürliche Gleichgewicht von Kalimdor zu schützen. Alanndarian Nachtweise hat sich von Auberdine aus um Hilfe gegen eine virulente Krankheit bemüht, die die Tierwelt der Dunkelküste vergiftet. Dendrite vermutet, dass die Kontamination ihren Ursprung an den Klippenquellfällen hat, der wichtigsten Süßwasserquelle der Region, und muss deren Quelle bestätigen, um bei der Schaffung eines Heilmittels zu helfen.",al={"dendrites motiv","warum schickt mich dendrite","warum klippenquellfälle untersuchen"}},["87aa05d6"]={q="Wofür ist die Gefüllte Probe der Klippenquellfälle?",a="Die Probe enthält korrumpiertes Wasser, das direkt aus der Höhlenmündung bei den Klippenquellfällen entnommen wurde. Wenn Ihr sie zu Alanndarian Nachtweise in Auberdine bringt, kann sie die genaue Art des Giftes analysieren, das die Tierwelt der Dunkelküste befällt, und mit der Herstellung eines wirksamen Heilmittels beginnen.",al={"nutzen der gefüllten probe der klippenquellfälle","wofür ist die wasserprobe","warum klippenquellwasser sammeln"}},["00d3706a"]={q="Warum schickt Dendrite Sternenschauer Euch, anstatt es selbst zu erledigen?",a="Dendrite dient als wichtiger Verbindungsmann für den Zirkel des Cenarius in der Mondlichtung und koordiniert umfassendere druidische Bemühungen in ganz Kalimdor. Die Untersuchung der Quelle und die Zusammenarbeit mit Alanndarian vor Ort in der Dunkelküste bietet eine wesentliche Feldprüfung für einen aufsteigenden Druiden, der lernt, Macht über Gift auszuüben.",al={"warum ich dendrite","warum braucht dendrite druiden","warum einen lehrling schicken"}}},fp="20,196,26.307.0,20.240.0,15.334.1,51.178.0,42.152.0,26.190.0,29.222.0,34.192.0,47.185.0"}
P.entries["quest:6123"] = {n="Das Heilmittel sammeln",s="In der Dunkelküste brauchen kranke Rehe eine Salbe, und Alanndarian Nachtweise in Auberdine zeigt einem jungen Druiden, wie man sie herstellt. Das Heilmittel erfordert Wasser und Heilpflanzen, die in der Nähe gesammelt werden.",h="In der Dunkelküste brauchen kranke Rehe eine Salbe, und Alanndarian Nachtweise in Auberdine zeigt einem...",kw={"alanndarian nachtweise","auberdine","cure poison","dunkelküste","druidenquest","erdwurzel","das heilmittel sammeln","lunarfungus","mondkin höhlen"},ang={["class:Druid"]="Als Druide lernt Ihr, wie gewöhnliche Heilmittel gegen natürliche Gifte wirken. Dieses Wissen bereitet Euch darauf vor, heilende Kraft zu kanalisieren, ohne auf Hilfsmittel angewiesen zu sein.",["profession:Herbalism"]="Als Kräuterkundiger besitzt Ihr das geschulte Auge, das Alanndarian beim Aufspüren von Erdwurzel in der Wildnis schätzt.",["race:NightElf"]="Als Nachtelf teilt Ihr die Pflicht der Kaldorei, die heiligen Haine und die Tierwelt der Dunkelküste zu schützen, in Ehrfurcht vor Elune und den Geistern der Wildnis."},sec={{t="Ein Heilmittel für die Tierwelt der Dunkelküste",b="Alanndarian Nachtweise sucht ein Heilmittel für die kranken Rehe der Dunkelküste. Eine verunreinigte Wasserquelle hat der heimischen Tierwelt geschadet, daher soll eine Wasserprobe aus Cliffspring die Grundlage der Salbe bilden. Natürliche Zutaten mit heilender Wirkung müssen die Mischung vervollständigen. Die Rehe können sich nicht von selbst erholen, und der Zirkel des Cenarius braucht bald ein Heilmittel."},{t="Wurzeln und Mondblüten",b="Erdwurzel und Lunarfungus verleihen der Salbe Heilkraft. Erdwurzel wächst in felsigem Boden, wo das geschulte Auge eines Kräuterkundigen hilft, sie zu finden. Lunarfungus blüht in Höhlen östlich von Auberdine. Die Mondkin dort verteidigen ihr Revier inzwischen erbittert und sind aufgebracht, was das Sammeln gefährlicher macht."},{t="Der Weg zur Giftreinigung",b="Alanndarian Nachtweise lehrt den Lehrling, wie viel Sorgfalt es erfordert, ein Heilmittel gegen ein bestimmtes Gift zu brauen. Jeder Schritt beim Sammeln und Zubereiten der Zutaten verlangt Sorgfalt. Diese Lektion bereitet den Druiden darauf vor, Gifte mit Naturmagie zu reinigen, ohne für jedes ein eigenes Mittel brauen zu müssen."}},faq={{q="Welchen Zweck hat Das Heilmittel sammeln?",a="Ein Druidenlehrling sammelt Erdwurzel und Lunarfungus für Alanndarian Nachtweise in Auberdine. Aus den Zutaten entsteht eine heilende Salbe für die kranken Rehe der Dunkelküste, während die Arbeit lehrt, wie Heilmittel Giften entgegenwirken können.",al={"warum diese quest machen","das heilmittel sammeln ziel","wozu dient das heilmittel sammeln"}},{q="Wo wächst der Lunarfungus?",a="Lunarfungus wächst in Höhlen in den Hügeln direkt östlich von Auberdine. Wilde Mondkin dort verteidigen ihr Revier inzwischen erbittert und sind aggressiv geworden.",al={"wo ist lunarfungus","lunarfungus fundort","wie lunarfungus finden"}},{q="Muss ich Kräuterkundiger sein, um Erdwurzel zu bekommen?",a="Ihr braucht Herbalism nicht, um Erdwurzel zu erhalten, obwohl sie in wilden Kräutervorkommen wächst. Ohne diese Fertigkeit müsst Ihr mit einem Kräuterkundigen handeln oder das Kraut für Alanndarians Rezept von jemand anderem besorgen.",al={"herbalism für erdwurzel nötig","erdwurzel ohne kräuterkundiger zu sein","erdwurzel ohne beruf"}},{q="Wer ist Alanndarian Nachtweise?",a="Alanndarian Nachtweise ist eine Nachtelfe in Auberdine, die den Zirkel des Cenarius um Hilfe gebeten hat. Sie wacht über die Pflanzen und Tiere der Dunkelküste und führt junge Druiden durch ihre ersten Prüfungen zur Reinigung und zum Schutz der Wildnis.",al={"wer ist alanndarian","alanndarian nachtweise hintergrundgeschichte"}},{q="Warum sind die Rehe in der Dunkelküste krank?",a="Die Rehe der Dunkelküste haben Wasser getrunken, das durch eine verunreinigte Quelle vergiftet wurde. Das Gift lässt sie leiden, und ohne eine heilende Salbe können sie sich nicht erholen.",al={"warum sind rehe vergiftet","kranke rehe dunkelküste","was hat die rehe vergiftet"}},{q="Wie hilft mir diese Quest, Cure Poison zu erlernen?",a="Die Ausbildung lehrt Lehrlinge, mit welcher Sorgfalt pflanzliche Gegenmittel für einzelne Gifte zubereitet werden müssen. Der Zirkel des Cenarius nutzt diese Lektion, um Druiden darauf vorzubereiten, Naturmagie zu kanalisieren, die Gift neutralisieren kann.",al={"cure poison druidenquest","cure poison lernen","power over poison questreihe"}}},fx={["0cfb14cd"]={q="Warum möchte Alanndarian Nachtweise, dass dies getan wird?",a="Als Druidin, die in Auberdine über die Dunkelküste wacht, kann Alanndarian nicht untätig zusehen, wie die heimische Tierwelt leidet. Die örtlichen Hirsche sind einem schwächenden Leiden erlegen und können sich nicht von selbst erholen. Das Herstellen einer wirksamen Heilsalbe ist ihre unmittelbare Priorität, um ihr Leiden zu beenden und das Gleichgewicht in den korrumpierten Wäldern wiederherzustellen.",al={"alanndarian beweggrund","warum kranke hirsche heilen","warum kümmert sich alanndarian"}},e3b496ec={q="Wofür ist die Erdwurzel gut?",a="Alanndarian benutzt die Erdwurzel, um ihrer Heilsalbe wiederherstellende Eigenschaften zu verleihen. Vermischt mit der Wasserprobe aus den Cliffspring Falls, die als Basis für die Salbe dient, wirkt die natürliche medizinische Essenz des Krauts den Giften entgegen, die die Hirsche der Dunkelküste krank machen.",al={"warum erdwurzel","was bewirkt erdwurzel","erdwurzel salbe"}},["74e6ce3c"]={q="Wofür ist der Lunarfungus gut?",a="Der Lunarfungus verleiht der Salbe die notwendige Stärke. Seine wirksame, natürliche Blüte verstärkt die Heilkraft der Mischung und stellt sicher, dass das Mittel stark genug ist, um das tief sitzende Gift zu beseitigen, das die betroffenen Hirsche befällt.",al={"warum lunarfungus","zweck lunarfungus","fungus für salbe"}}},fp="18,176,33.319.0,22.279.0,28.277.1,42.213.0,33.126.0,46.199.0,29.225.0,35.140.0,46.205.0"}
P.entries["quest:6124"] = {n="Heilung der Kranken",s="An der ganzen Dunkelküste erkranken Hirsche, und „Heilung der Kranken“ gibt Euch die Möglichkeit, ihnen zu helfen. Alanndarian Nachtweise gibt Euch Salbe für die vergifteten Tiere, bevor Ihr dem Zirkel des Cenarius in der Mondlichtung Bericht erstattet.",h="An der ganzen Dunkelküste erkranken Hirsche, und „Heilung der Kranken“ gibt Euch die Möglichkeit, ihnen zu...",kw={"alanndarian nachtweise","auberdine","zirkel des cenarius","der klippenquell","heilende tiersalbe","heilung der kranken","dunkelküste","dendrite sternenschauer","gift","kränkliche hirsche"},ang={["class:Druid"]="Als Druide beweist Ihr Euren Einsatz für die Bewahrung des Gleichgewichts und bereitet Euch darauf vor, Gifte mit druidischer Magie zu beseitigen.",["race:NightElf"]="Als Nachtelf kennt Ihr die Dunkelküste als den Rand der besiedelten Gebiete Eures Volkes. Krankheit unter ihren Hirschen ist ein unheilvolles Zeichen für die kaldorei."},sec={{t="Eine Seuche in den Wäldern",b="An der ganzen Dunkelküste erkranken Hirsche, vom Klippenquell südwärts bis zur Grenze des Eschentals. Sie durchstreifen die nebligen Wälder, geschwächt von Giftstoffen im Boden und in den Bächen. Nachdem Ihr die nötigen Reagenzien gesammelt habt, gibt Euch Alanndarian Nachtweise frisch gebraute Tiersalbe, um sie zu behandeln."},{t="Geöffnete Augen in der Mondlichtung",b="Nachdem Ihr zehn Hirsche behandelt habt, erstattet Ihr Dendrite Sternenschauer in der Mondlichtung Bericht. Auberdine erfährt etwas Erleichterung, doch Dendrite sieht die Krankheit der Herden als Zeichen einer tieferen Verderbnis, die sich im Norden Kalimdors ausbreitet. Er warnt, dass die Anführer in Darnassus debattieren, während die Fäulnis voranschreitet. Der Zirkel des Cenarius muss wachsam verfolgen, wie weit sie sich über den Kontinent ausbreitet."}},faq={{q="Warum sind die Hirsche an der Dunkelküste krank?",a="Verderbnis im Boden und im Wasser der Dunkelküste macht die Hirsche krank, vom Klippenquell südwärts bis zum Eschental. Sie fressen verseuchte Pflanzen und trinken das verunreinigte Wasser, wodurch sie schwach und krank werden.",al={"warum sind hirsche krank","dunkelküste kränkliche hirsche","was hat die hirsche vergiftet"}},{q="Wer bereitet die heilende Salbe für die Hirsche zu?",a="Alanndarian Nachtweise bereitet in Auberdine die Heilende Tiersalbe aus Reagenzien zu, die Ihr sammelt. Ihre Zubereitung enthält zehn Dosen für die leidenden Tiere, während sie und die Stadtbewohner versuchen, mehr herzustellen.",al={"wer stellt das heilmittel her","alanndarian salbe","heilende tiersalbe hersteller"}},{q="Warum kümmert sich Dendrite Sternenschauer um die Hirsche?",a="Dendrite Sternenschauer beaufsichtigt die Druidenausbildung für den Zirkel des Cenarius in der Mondlichtung. Die Versorgung der Hirsche prüft das Pflichtbewusstsein eines Druiden und bestätigt, dass sich gefährliche Verderbnis in Kalimdors Wildnis ausbreitet.",al={"warum dendrite mondlichtung","interesse des zirkels des cenarius an hirschen","dendrite sternenschauer rolle"}},{q="Welche politischen Spannungen deutet Dendrite Sternenschauer an?",a="Dendrite sagt, dass einige nachtelfische Würdenträger in Darnassus die wachsende Fäulnis erkennen, während andere ihre Warnzeichen ignorieren. Er drängt Euch, Euch den harten Wahrheiten über die Natur zu stellen.",al={"darnassus spannungen","wer ignoriert die verderbnis","darnassus scheuklappen"}},{q="Wo sind die kränklichen Hirsche zu finden?",a="Kränkliche Hirsche durchstreifen die Dunkelküste, vom Gebiet südlich des Klippenquells, unmittelbar nördlich von Auberdine, bis zur Grenze des Eschentals.",al={"kränkliche hirsche fundort","wo sind die hirsche","dunkelküste hirsche fundort"}},{q="Was lernt ein Druide beim Erfüllen dieser Aufgabe?",a="Ihr lernt durch praktische Arbeit, Gift zu beseitigen. Leidende Waldtiere mit einem greifbaren Heilmittel zu behandeln, verbindet pflanzliche Heilmittel mit geistiger Macht über Gift.",al={"was lernen druiden daraus","gift heilen ausbildung druide","lehre aus heilung der kranken"}}},fx={["5b53be21"]={q="Warum möchte Alanndarian Nachtweise, dass die Hirsche geheilt werden?",a="Alanndarian sieht, wie die Tierwelt der Dunkelküste unter einem heimtückischen und sich ausbreitenden Leiden leidet. Während sie in Auberdine zurückbleibt, um die Dorfbewohner zu sammeln und mehr Medizin zu brauen, benötigt sie einen fähigen Druiden, der sofort im Feld handelt. Sich um die betroffenen Hirsche zu kümmern, beendet ihr Leiden, bevor die Krankheit die lokalen Herden vollständig auslöscht.",al={"alanndarian beweggrund","warum hirsche heilen alanndarian","alanndarian nachtweise dunkelküste hirsch"}},["73042015"]={q="Warum bittet Alanndarian Euch und nicht die Wachen von Auberdine, die Hirsche zu heilen?",a="Die Stadtbewohner und Späher von Auberdine sind damit beschäftigt, die Siedlung zu verteidigen und mit Alanndarian zusammenzuarbeiten, um mehr Salbe herzustellen. Außerdem erfordert das Beruhigen wilder, fiebriger Tiere die ruhige Hand und das Einfühlungsvermögen eines Eingeweihten des Zirkels des Cenarius. Als Druide in der Ausbildung seid Ihr besonders gut geeignet, Euch direkt um die Tiere der Wildnis zu kümmern.",al={"warum fragt alanndarian mich","warum nicht auberdine späher","warum druiden zum hirsche heilen schicken"}}},fp="15,209,25.286.0,26.345.1,35.200.0,49.192.0,48.208.0,55.181.0,35.124.0,50.167.0"}
P.entries["quest:6125"] = {n="Macht über Gift",s="In Darnassus kehrt ein junger Druide mit Macht über Gift zurück, um die Prüfung des Zirkels des Cenarius abzuschließen. Sie begann an der Dunkelküste, wo der Initiant lernte, von Hand ein Heilmittel zu brauen.",h="In Darnassus kehrt ein junger Druide mit Macht über Gift zurück, um die Prüfung des Zirkels des Cenarius...",kw={"auberdine","die enklave des cenarius","cure poison","darnassus","dendrite sternenschauer","mathrengyl bärenfährte","mondlichtung","macht über gift"},ang={["class:Druid"]="Als Druide beginnt Ihr mit einfacher Kräuterarbeit, bevor Ihr die Magie der Natur empfangt, um Gifte zu beseitigen.",["race:NightElf"]="Als Nachtelf stellt Ihr Euch dieser Prüfung in der Enklave des Cenarius in Darnassus. Sie spiegelt die Ehrfurcht der Kaldorei vor dem Gleichgewicht und ihre Fürsorge für ihre uralten Wälder wider."},sec={{t="Die Demut des Schülers",b="An der Dunkelküste schickt Alanndarian Nachtweise junge Druiden aus, um Erdwurzel und Lunarfungus von Hand zu sammeln. Daraus brauen sie eine Salbe für erkrankte Wildtiere. Bevor der Zirkel des Cenarius die Magie lehrt, die Giftstoffe austreibt, sollen Initianten lernen, wie beschwerlich die Behandlung von Vergiftungen ohne spirituellen Beistand ist. Diese Arbeit zeigt ihnen, was einfache Leute bei einer Vergiftung erdulden und warum ein Druide ihrem Leiden mit Fürsorge begegnen muss."},{t="Rückkehr zur Enklave",b="Das Heilmittel erweist sich in Auberdine als wirksam, und Starblaze schickt den Druiden über das Meer nach Darnassus. Mathrengyl Bärenfährte wartet in der Enklave des Cenarius. Erfreut über die Gelassenheit des Initianten unter Druck, lehrt er ihn, Giftstoffe durch die Kraft der Natur zu beseitigen. Doch die hochwirksamen Gifte in der Wildnis um Auberdine bereiten ihm Sorgen. Sie deuten auf eine unnatürliche Verderbnis hin, die das Gleichgewicht des Landes stört."}},faq={{q="Was ist der Zweck dieser Quest?",a="Die Prüfung bereitet einen Druiden darauf vor, Vergiftungen mit Magie zu heilen, nachdem er zunächst von Hand eine Salbe hergestellt hat. Von der Dunkelküste kehrt der Schüler zu Mathrengyl Bärenfährte in Darnassus zurück, um Cure Poison zu erlernen.",al={"warum macht über gift abschließen","macht über gift ziel","cure poison quest"}},{q="Wer ist Dendrite Sternenschauer?",a="Dendrite Sternenschauer ist ein Druidenältester in Nachthafen in der Mondlichtung. Er führt Initianten durch spirituelle Prüfungen, die ihre Geduld und Hingabe an die Natur auf die Probe stellen, und schickt sie dann zu ihren heimischen Lehrern.",al={"dendrite sternenschauer rolle","wer vergibt macht über gift"}},{q="Wer ist Mathrengyl Bärenfährte?",a="Mathrengyl Bärenfährte ist ein Meister der Druidenausbildung in der Enklave des Cenarius in Darnassus. Unter den Ästen Teldrassils unterweist er Nachtelfendruiden in Gestalten, Heilkunst und den Pflichten des Zirkels des Cenarius.",al={"mathrengyl bärenfährte hintergrund","bärenfährte darnassus"}},{q="Warum musste der Druide zuerst von Hand ein Heilmittel herstellen?",a="Dendrite Sternenschauer lehrt Druiden, die körperlichen Folgen einer Vergiftung und die Mühen ihrer Behandlung ohne Magie zu verstehen. Gewöhnliche Zutaten zu sammeln und Kranke von Hand zu pflegen, lehrt Demut und Dankbarkeit für die Gaben der Natur, die sie bald empfangen werden.",al={"warum ein kräuterheilmittel herstellen","lehre von macht über gift"}},{q="Was beunruhigt Mathrengyl an der Lage in Auberdine?",a="Mathrengyl hält die tödlichen Giftstoffe in der Wildnis der Dunkelküste um Auberdine für unnatürlich. Ihre Auswirkungen auf heimische Wildtiere und Pflanzen bedrohen das Gleichgewicht des Landes und deuten auf einen verderblichen Einfluss entlang der Küste hin.",al={"auberdine gift hintergrund","mathrengyls sorge"}}},fx={["92345f63"]={q="Warum schickt Euch Dendrite Sternenschauer zurück nach Darnassus?",a="Dendrite Sternenschauer möchte, dass Ihr Eure Initiation abschließt. Nachdem er Euch gezwungen hat, Kräuter zu sammeln und die Kranken in Auberdine von Hand zu heilen, hat er sichergestellt, dass Ihr die Mühen zu schätzen wisst, denen gewöhnliche Sterbliche beim Kampf gegen Gift ausgesetzt sind. Jetzt, da Ihr die Einsätze und die Demut versteht, die von einem Hüter der Natur verlangt werden, schickt er Euch zurück, damit Mathrengyl Bärenfährte Euch den wahren druidischen Zauber verleihen kann.",al={"warum zu mathrengyl schicken","dendrite sternenschauer beweggrund","warum zurück nach darnassus"}}},fp="17,172,22.416.0,21.391.0,34.184.0,26.200.0,29.203.0,56.253.0,58.210.0"}
P.entries["quest:6126"] = {n="Neue Lektionen",s="In Donnerfels schickt Turak Runentotem junge Taurendruiden in die heilige Mondlichtung, um die Reinigung von Giften zu erlernen. Unter Dendrite Sternenschauer, einem Nachtelfendruiden, beginnen Lehrlinge dieses Studium, während echte Vergiftungen mehr als bloße Übungen verlangen.",h="In Donnerfels schickt Turak Runentotem junge Taurendruiden in die heilige Mondlichtung, um die Reinigung von...",kw={"zirkel des cenarius","das wegekreuz","cure poison","dendrite sternenschauer","neue lektionen","mondlichtung","nachthafen","turak runentotem"},ang={["class:Druid"]="Als Druide führt Euch Euer Weg von grundlegender Gestaltwandlung und Scharmützeln hin zur Obhut über die Wildnis. Nun beginnt Euer Weg damit, Cure Poison zu erlernen.",["faction:Horde"]="Als Mitglied der Horde findet Ihr in Mondlichtung unter dem heiligen Schutz des Zirkels des Cenarius Zuflucht, selbst während Hordenkrieger im Eschental gegen Nachtelfen kämpfen.",["race:Tauren"]="Als Tauren zeigt Eure Pilgerreise, wie tief sich die Kinder der Earth Mother an der Seite ihrer nachtelfischen Gefährten wieder mit den Lehren des Cenarius verbunden haben."},sec={{t="Die Gabe des Cenarius",b="Cenarius schenkte den Druiden eine Beschwörungsformel zur Reinigung von gefährlichen Giften und trug ihnen auf, die Wildnis zu schützen. Turak Runentotem lehrt, dass solche Magie fundiertes Wissen erfordert. Bevor ein Druide damit eine Plage beseitigt, muss er die körperlichen Auswirkungen von Gift verstehen und lernen, es mit gewöhnlichen Mitteln zu behandeln."},{t="Ruf nach Nachthafen",b="Turak schickt vielversprechende Akolythen von Mulgore aus über heilige Pfade nordwärts nach Mondlichtung. Dort, im friedlichen Dorf Nachthafen, unterweisen uralte Nachtelfenmentoren wie Dendrite Sternenschauer Elfen und Tauren gleichermaßen. Ihr gemeinsames Studium spiegelt den empfindlichen Waffenstillstand des Zirkels des Cenarius wider, der über den politischen Streitigkeiten zwischen Horde und Allianz steht."},{t="Eine echte Krise im Brachland",b="Nahe dem Wegekreuz im Brachland breiten sich unkontrollierte Vergiftungen unter den Tieren aus. Dendrite Sternenschauer hat keine Zeit für Übungen: Ein Hilferuf vom Wegekreuz ist eingetroffen. Diese Bitte verwandelt einen Übergangsritus in einen dringenden Feldeinsatz, bei dem junge Druiden dem Leiden wilder Tiere gegenüberstehen."}},faq={{q="Wer bietet diese Quest an und wo finde ich ihn?",a="Turak Runentotem, der Druidenlehrer der Tauren, bietet den Ritus auf der Anhöhe der Ältesten in Donnerfels an. Er ruft Initianden zu sich, die sich schon früh den Lehren des Cenarius verschrieben haben.",al={"wer vergibt neue lektionen","wo gibt es neue lektionen","questgeber neue lektionen"}},{q="Wer ist Dendrite Sternenschauer?",a="Dendrite Sternenschauer ist ein betagter Nachtelfendruide, der in Nachthafen in Mondlichtung lebt. Trotz der Spannungen zwischen Nachtelfen und Tauren lehrt er junge Druiden beider Völker die Traditionen des Zirkels des Cenarius.",al={"wer ist dendrite","dendrite sternenschauer rolle","wer ist der nachtelf in mondlichtung"}},{q="Welche Kraft erlerne ich bei dieser Quest?",a="Eure Unterweisung beginnt mit Cure Poison. Die Lektionen behandeln die körperliche und magische Natur von Gift und lehren Druiden, Verbündete und ihnen anvertraute Wildtiere von schädlichen Leiden zu reinigen.",al={"welche fähigkeit wird erlernt","für welchen zauber ist das","quest zur giftheilung"}},{q="Warum muss ein Tauren bei einem Nachtelfen lernen?",a="Der Zirkel des Cenarius ist eine neutrale Bruderschaft, die sich dem Gleichgewicht der Natur verschrieben hat. Nachtelfen gaben dem modernen Druidentum unter Cenarius zunächst seine feste Form, nahmen dann die Tauren wieder in den Orden auf und teilten trotz des Fraktionskrieges heilige Orte wie Mondlichtung.",al={"warum ein nachtelf als lehrer","tauren und nachtelfen als druiden","zirkel des cenarius fraktion"}},{q="Was geschieht am Wegekreuz?",a="Die Tierwelt um das Wegekreuz im Brachland leidet unter einer heftigen Vergiftungswelle, die die örtlichen Tierbetreuer nicht eindämmen können. Dendrite Sternenschauer verlagert Eure Ausbildung ins Gelände, wo Ihr die Ursache finden und ein Heilmittel herstellen sollt.",al={"problem am wegekreuz","was vergiftet die tiere","krankheit am wegekreuz"}},{q="Wie komme ich für diese Quest am schnellsten nach Mondlichtung?",a="Als Druide verfügt Ihr über den angeborenen Zauber Teleport: Mondlichtung, der Euch direkt nach Nachthafen bringt. Er erspart Euch einen Fußmarsch durch gefährliche, umkämpfte Gebiete.",al={"wie nach mondlichtung gelangen","reise nach nachthafen","teleport mondlichtung"}}},fx={be063b64={q="Warum schickt Euch Turak Runentotem zur Mondlichtung?",a="Turak glaubt, dass Ihr endlich bereit seid, einen der größten Segnungen zu erben, die Cenarius den Druiden verliehen hat: die Kunst, tödliche Gifte durch Beschwörung zu heilen. Solch heilige Magie wird nicht beiläufig gewährt. Um sicherzustellen, dass Ihr diese Macht respektiert, verlangt Turak, dass Ihr zuerst Gift so versteht, wie es ein gewöhnlicher Heiler tun würde, und weist Euch an Dendrite Sternenschauer in der Mondlichtung, um Eure formelle Ausbildung zu beginnen.",al={"warum schickt mich turak","turak runentotem beweggrund","warum zur mondlichtung gehen"}}},fp="12,236,20.291.0,21.363.0,28.289.1,47.178.0,26.208.0,37.189.0,50.249.0,36.231.0,59.167.0"}
P.entries["quest:6127"] = {n="Die eigentliche Ursache",s="Von Mondlichtung aus schickt Dendrite Sternenschauer Druiden der Horde zum Glutnebelgipfel, um eine Wasserprobe zu holen. Sie bittet sie, diese zu Tonga Runentotem am Wegekreuz zu bringen, wo sie Aufschluss über das Gift geben könnte, das die Tierwelt schädigt.",h="Von Mondlichtung aus schickt Dendrite Sternenschauer Druiden der Horde zum Glutnebelgipfel, um eine...",kw={"brachland","zirkel des cenarius","das wegekreuz","dendrite sternenschauer","glutnebelgipfel","power over poison","die eigentliche ursache","kränkliche gazelle","tonga runentotem"},ang={["class:Druid"]="Als Druide verfolgt Ihr Verderbnis bis zu ihrer Quelle und isoliert magische Giftstoffe, bevor sie ein Ökosystem zerstören.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, das Wegekreuz zu schützen, ein wichtiges Zentrum des Lebens der Horde in Kalimdor. Dämonische Verderbnis bedroht dort Handel und Überleben.",["race:Tauren"]="Als Tauren helft Ihr, die Gazellenherden des Brachlands vor dämonischer Verderbnis zu bewahren. Dies sind die angestammten Gebiete der Stämme Kalimdors."},sec={{t="Ein verseuchter Berg",b="Dendrite Sternenschauer fürchtet, dass die Burning Blade den Glutnebelgipfel verseucht hat. Der Berg erhebt sich nordwestlich des Wegekreuzes über dem trockenen nördlichen Brachland. Quellen und Teiche krönen seine Höhen und prägen das örtliche Wetter und die Feuchtigkeit. Nun hat sich ein Dämonenkult auf den Felsen festgesetzt, und seine finstere Zauberei könnte das Becken vergiften."},{t="Eine Seuche der Ebenen",b="Kranke Gazellen taumeln durch die nördliche Savanne, nördlich des Hauptwegs, der von Osten nach Westen durch das Wegekreuz führt. Tonga Runentotem sucht Hilfe für die einheimischen Tauren und bittet den Zirkel des Cenarius, herauszufinden, was die Herde vergiftet. Mit einer Wasserprobe vom Gipfel kann er die Krankheit untersuchen und ein Gegengift brauen."}},faq={{q="Wo bekomme ich die Wasserprobe für diese Quest?",a="Entnehmt Wasser aus dem Teich auf dem Glutnebelgipfel, nordwestlich des Wegekreuzes im Brachland. Die Burning Blade versammelt sich dort, und Dendrite Sternenschauer gibt Euch einen Probenehmer.",al={"glutnebelgipfel teich standort","wo ist der wasserteich","die eigentliche ursache wasserprobe"}},{q="Warum ist das Wasser auf dem Glutnebelgipfel so wichtig für das Brachland?",a="Die hochgelegenen Teiche des Glutnebelgipfels beeinflussen das örtliche Wetter und den Nebel. Sobald die Burning Blade sie verunreinigt, breiten sich giftige Dämpfe und abfließendes Wasser über die Ebenen aus und machen die Wildtiere im nördlichen Brachland krank.",al={"warum der glutnebelgipfel wichtig ist","brachland wetter teich","glutnebelgipfel teiche"}},{q="Wer ist Tonga Runentotem?",a="Tonga Runentotem ist ein Taurendruide am Wegekreuz im Brachland. Beunruhigt über die seltsame Krankheit unter den örtlichen Gazellen, bat er den Zirkel des Cenarius in Mondlichtung, sie zu untersuchen und das Land zu reinigen.",al={"wer ist tonga","tonga runentotem rolle","wegekreuz druide"}},{q="Wer verdirbt das Wasser auf dem Gipfel?",a="Die Burning Blade hat die Gewässer verdorben. Ihre dämonenanbetenden Hexenmeister und Teufelsmagier besetzen die gewundenen Pfade und die Spitze des Glutnebelgipfels.",al={"wer hat den teich verseucht","glutnebelgipfel kultisten","burning blade glutnebelgipfel"}},{q="Welche Fähigkeit erlerne ich durch den Abschluss dieser Questreihe?",a="Der Ritus von Power over Poison vermittelt jungen Druiden der Horde das spirituelle und kräuterkundliche Wissen, um unterwegs Vergiftungen zu heilen.",al={"power over poison belohnung","druide giftheilungszauber","gift heilen quest brachland"}},{q="Können Druiden der Allianz diese Quest machen?",a="Nein. Die eigentliche Ursache schickt Druiden der Horde ins Brachland, um Tonga Runentotem zu helfen. Druiden der Allianz unternehmen eine ähnliche Reise an der Dunkelküste, um zu lernen, Vergiftungen zu heilen.",al={"allianz gegenstück","können nachtelfen die eigentliche ursache machen","allianz giftquest"}}},fx={["41ffa32f"]={q="Warum möchte Dendrite Sternenschauer, dass dies getan wird?",a="Tonga Runentotem hat sich an den Zirkel des Cenarius in der Mondlichtung gewandt, um Hilfe zu suchen, eine sich ausbreitende Krankheit im Brachland zu stoppen. Dendrite Sternenschauer vermutet, dass die dämonenanbetende Burning Blade die Tümpel auf dem Glutnebelgipfel vergiftet hat. Da diese Hochgewässer die Wettermuster der Region beeinflussen, bedroht ihre Verderbnis das empfindliche Gleichgewicht des gesamten nördlichen Brachlands.",al={"warum braucht dendrite dies","dendrite sternenschauer beweggrund","warum wasser untersuchen"}},["54ce2e01"]={q="Wofür ist die Gefüllte Glutnebelgipfelprobe gut?",a="Die gefüllte Probe enthält verseuchtes Wasser, das direkt aus dem höchsten Tümpel des Gipfels entnommen wurde. Tonga Runentotem benötigt diese üble Probe im Wegekreuz, um die schlimmen Gifte zu analysieren, die die lokale Tierwelt infizieren, was es ihm und dem Zirkel des Cenarius ermöglicht, die Verschmutzung zu untersuchen und ein wirksames Heilmittel für die betroffenen Gazellen zu brauen.",al={"verwendung gefüllte glutnebelgipfelprobe","wofür ist die wasserprobe","zweck probe"}},["2b67a7e4"]={q="Warum schickt Dendrite Sternenschauer Euch, anstatt selbst zu gehen?",a="Als Ältester des Zirkels des Cenarius, der in der heiligen Mondlichtung residiert, beaufsichtigt Dendrite viele Angelegenheiten und verlässt sich auf vielversprechende junge Druiden, die als Hände des Zirkels in ganz Kalimdor dienen. Tongas Bitte zu beantworten, bietet eine wesentliche Lektion im Reinigen von Verderbnis und dem Meistern natürlicher Heilmittel, wobei Eure Fähigkeit getestet wird, das Land zu heilen.",al={"warum mich schicken","warum geht dendrite nicht selbst","warum ein druidenschüler"}}},fp="20,208,18.328.0,22.305.0,47.173.0,63.192.0,23.200.0,40.145.0,46.121.0,34.164.0"}
P.entries["quest:6128"] = {n="Das Heilmittel sammeln",s="Am Wegekreuz führt Tonga Runentotem junge Taurendruiden durch einen heiligen Übergangsritus. Ihr sammelt Erdwurzeln und feste Kodohörner für eine Salbe zur Behandlung der vergifteten Gazellen des Brachlands.",h="Am Wegekreuz führt Tonga Runentotem junge Taurendruiden durch einen heiligen Übergangsritus.",kw={"brachland","das wegekreuz","druidenquest","erdwurzel","das heilmittel sammeln","gazelle","kodohorn","salbe","tonga runentotem"},ang={["class:Druid"]="Als Druide stellt Ihr Euch Prüfungen, die Euch lehren, über die sterbliche Kräuterkunst hinauszuwachsen und die Magie der Natur zu kanalisieren, um Gift direkt auszutreiben.",["faction:Horde"]="Als Mitglied der Horde helft Ihr Tonga, die Tierwelt rund um das Wegekreuz zu schützen und ein stabiles Ökosystem für den Außenposten im Kernland der Horde zu bewahren.",["profession:Herbalism"]="Als Kräuterkundiger kennt Ihr den Wert wild wachsender Heilwurzeln, die sich an den felsigen Hängen der Savanne sammeln lassen."},sec={{t="Ein Rezept zur Linderung",b="Tonga Runentotem braucht Zutaten für ein Gegengift auf Grundlage der Wasserprobe, die Ihr am Glutnebelgipfel gesichert habt. Erdwurzel verleiht der Salbe ihre heilenden Eigenschaften, während gemahlenes Kodohorn ihr die Kraft gibt, Gift aus dem Körper einer Kreatur zu treiben. Für einen jungen Druiden bedeutet das Sammeln dieser Zutaten, sich auf die Gaben der Erde zu verlassen und heimische Wildtiere zu jagen."},{t="Lehren der Reinigung",b="Während Tonga Runentotem die Salbe zubereitet, lehrt er die Grenzen physischer Heilmittel. Kräuterkunde und Alchemie können bestimmten Giftstoffen entgegenwirken, doch die meisten Gifte erfordern ein eigenes Heilmittel. Statt endlose Vorräte an Kräutern und Hörnern mitzuführen, lernen Druiden, sich auf die heilenden Energien der Natur einzustimmen. Diese Lehre führt zur druidischen Kunst Vergiftung heilen."}},faq={{q="Welche Zutaten benötigt Tonga Runentotem?",a="Tonga verlangt fünf Bündel Erdwurzeln und fünf unversehrte Kodohörner. Erdwurzel bringt heilende Eigenschaften mit, während die Hörner der Salbe Wirksamkeit gegen die Giftstoffe verleihen, die den heimischen Gazellen schaden.",al={"das heilmittel sammeln gegenstände","welche reagenzien werden benötigt","materialien für das heilmittel"}},{q="Wo sind die Kodohörner zu finden?",a="Kodos durchstreifen das nördliche und mittlere Brachland und grasen oft nahe den Straßen rund um das Wegekreuz. Tonga braucht ganze, feste Hörner für die Salbe, keine brüchigen Splitter.",al={"wo sind die kodos","kodohorn fundort","kodos im brachland finden"}},{q="Muss ich Kräuterkundiger sein, um Erdwurzeln zu beschaffen?",a="Nein, Ihr benötigt keine Kräuterkunde, um Erdwurzeln zu beschaffen. Kräuterkundige ernten sie an Klippen und Felsvorsprüngen im gesamten Brachland. Druiden, die sie nicht selbst sammeln können, erhalten sie von Mitreisenden oder an Handelsposten.",al={"ist kräuterkunde erforderlich","erdwurzeln ohne kräuterkunde sammeln","berufsvoraussetzung für erdwurzel"}},{q="Warum bereitet Tonga eine physische Salbe zu?",a="Tonga stellt ein physisches Gegengift für vergiftete Gazellen her, die im gesamten nördlichen Brachland leiden. Die sorgfältige Arbeit zeigt zugleich den Vorteil angeborener magischer Reinigungszauber.",al={"warum ein gegengift herstellen","zweck der salbe","warum keine magie verwenden"}},{q="Wer ist Tonga Runentotem?",a="Tonga Runentotem ist ein älterer Taurendruide am Wegekreuz im Brachland. Er untersucht die Verderbnis, die sich in den Wasserläufen der Region ausbreitet, und leitet junge Druiden an, das Gleichgewicht der Natur zu meistern.",al={"wer vergibt das heilmittel sammeln","tonga runentotems rolle","wer ist tonga"}},{q="Was folgt auf das Sammeln dieser Zutaten?",a="Nachdem Tonga die Salbe gebraut hat, schickt er Euch in die Savanne, um sie auf erkrankte Gazellen aufzutragen und das Heilmittel zu erproben. Dann lehrt er Euch die tiefere Kunst der magischen Reinigung.",al={"was folgt auf das heilmittel sammeln","das heilmittel sammeln folgequest","nach das heilmittel sammeln"}}},fx={["239606af"]={q="Warum möchte Tonga Runentotem diese Heilzutaten sammeln?",a="Tonga bemüht sich, die einheimische Gazellenpopulation des Brachlands zu retten, die einem gefährlichen Leiden erliegt. Die Tierwelt kann sich nicht von selbst erholen, was das natürliche Gleichgewicht der Ebenen bedroht. Durch die Kombination des Wassers, das vom Glutnebelgipfel entnommen wurde, mit starken wiederherstellenden Reagenzien beabsichtigt Tonga, eine Heilsalbe zu brauen, die in der Lage ist, die Krankheit zu stoppen, bevor weitere Herden zugrunde gehen.",al={"warum tonga runentotem helfen","tonga runentotem beweggrund","warum salbe herstellen"}},eb557efc={q="Wofür wird die Erdwurzel verwendet?",a="Die Erdwurzel liefert die wesentlichen Heileigenschaften für die Salbe. Tonga nutzt die natürliche Vitalität des widerstandsfähigen Krauts, um die Wasserbasis der Salbe mit der Kraft zu infundieren, die benötigt wird, um die betroffenen Gazellen zu beruhigen und das schwächende Gift abzuwehren.",al={"warum erdwurzel benötigt","zweck erdwurzel","erdwurzel salbe"}},["9baa8a2a"]={q="Wofür werden die Kodohörner verwendet?",a="Tonga benötigt robuste Kodohörner, um der Heilsalbe ausreichende Stärke zu verleihen. In die Mischung gemahlen, verleihen ganze und intakte Hörner der Medizin die Kraft, die benötigt wird, um aggressive Gifte wirksam zu bekämpfen.",al={"warum kodohörner benötigt","zweck kodohorn","kodohorn salbe"}}},fp="18,189,19.337.0,20.321.0,46.187.0,34.158.0,49.217.0,40.177.0,23.197.0,45.170.1"}
P.entries["quest:6129"] = {n="Heilung der Kranken",s="Kranke Gazellen leiden im gesamten nördlichen Brachland. Tonga Runentotem schickt junge Druiden der Horde aus, um sie mit einer frisch zubereiteten Kräutersalbe zu behandeln, und dann zum Zirkel des Cenarius in Mondlichtung.",h="Kranke Gazellen leiden im gesamten nördlichen Brachland.",kw={"brachland","zirkel des cenarius","das wegekreuz","heilende tiersalbe","gift heilen","heilung der kranken","dendrite sternenschauer","mondlichtung","kränkliche gazelle","tonga runentotem"},ang={["class:Druid"]="Für Euch als Druiden markiert dieser Heilungsritus den Übergang vom Kräuterkundeschüler zum aktiven Hüter der Natur. Er beweist, dass Ihr bereit seid, Lebensmagie gegen tödliche Gifte einzusetzen.",["faction:Horde"]="Indem Taurendruiden erkrankte Wildtiere nahe dem Wegekreuz behandeln, helfen sie, lebenswichtige Jagdgebiete und Reisewege zu schützen, die den Stützpunkt der Horde im zentralen Kalimdor sichern.",["race:Tauren"]="Während Euer Volk seine uralten Bande zum Zirkel des Cenarius erneuert, zeigt die Heilung des Brachlands, dass die Kinder der Earth Mother würdige Hüter des Gleichgewichts sind."},sec={{t="Eine Seuche unter Herden",b="Eine unnatürliche Krankheit breitet sich unter den Gazellen im nördlichen Brachland aus. Ihr habt Erdwurzeln und Kodohörner für ein Heilmittel gesammelt, und Tonga Runentotem am Wegekreuz vertraut die Tiere nun Eurer Fürsorge an. Sucht nördlich der Hauptkreuzung und versorgt zehn leidende Gazellen. Die Salbe verschafft ihnen Linderung, bevor das Leiden im Ökosystem tiefer Fuß fasst."},{t="Der Segen des Zirkels",b="Nachdem Ihr die Salbe aufgetragen habt, reist Ihr zum friedlichen Druidenheiligtum in Mondlichtung. Dendrite Sternenschauer erkennt dort Euer Mitgefühl und Eure Wachsamkeit an. Er sagt, das Leiden der Gazellen deute auf eine tiefere Verderbnis hin, die durch Kalimdors Wildnis schleicht. Indem Taurendruiden selbst die geringsten Tiere versorgen, zeigen sie, dass die Ehrfurcht vor Cenarius über Stammesgrenzen hinausreicht. Sie erlangen tiefere Geheimnisse der Giftreinigung und Naturmagie."}},faq={{q="Wo sind die kränklichen Gazellen zu finden?",a="Die erkrankten Gazellen durchstreifen die trockenen Ebenen des nördlichen Brachlands, hauptsächlich nördlich der großen Handelsstraße, die von Osten nach Westen durch das Wegekreuz verläuft.",al={"gazellen fundort","wo sind kranke gazellen","brachland gazellen"}},{q="Wer vergibt diese Quest?",a="Tonga Runentotem, ein Taurendruide am Wegekreuz im Brachland, gibt Euch diesen Auftrag und die Heilende Tiersalbe, nachdem Ihr die benötigten Reagenzien gesammelt habt.",al={"wer vergibt heilung der kranken","questgeber","tonga runentotem standort"}},{q="Bei wem muss ich mich nach der Heilung der Tiere melden?",a="Nachdem Ihr die Tiere geheilt habt, meldet Ihr Euch bei Dendrite Sternenschauer im Druidenheiligtum in Mondlichtung. Mit Eurer Teleportationsmagie erreicht Ihr den heiligen Hain.",al={"wo diese quest abgeben","quest abgeben","dendrite sternenschauer standort"}},{q="Warum interessiert sich der Zirkel des Cenarius für das Brachland?",a="Der Zirkel des Cenarius wacht über die Harmonie des Landes. Die Krankheit unter wilden Gazellen spiegelt die Verderbnis wider, die durch Kalimdor schleicht und ungehindert die natürliche Ordnung bedroht.",al={"warum dru hiden sich um das brachland kümmern","zirkel des cenarius brachland"}},{q="Welche Fähigkeit schaltet diese Questreihe frei?",a="Dieser Übergangsritus ist die zweite Hälfte einer druidischen Prüfung. Er verleiht Euch letztlich die Fähigkeit, Euch selbst und Eure Verbündeten von Giften und Giftstoffen zu reinigen.",al={"gift heilen questbelohnung","warum diese quest als druide machen"}},{q="Können auch Nichtdruiden diese Gazellen heilen?",a="Nein. Nur Druiden können diese Aufgaben übernehmen. Es ist eine Klassenprüfung unter direkter Aufsicht des Zirkels des Cenarius.",al={"nur für druiden","wer kann heilung der kranken machen"}}},fx={f2ed6f7d={q="Warum möchte Tonga Runentotem, dass Ihr die Gazellen heilt?",a="Eine sich ausbreitende Verderbnis verwüstet die Tierwelt im nördlichen Brachland und lässt die lokalen Gazellen an einer schwächenden Krankheit leiden. Tonga Runentotem hat eine Heilsalbe vorbereitet, um dem Unwohlsein entgegenzuwirken, aber die Natur kann nicht warten. Er braucht Euch, um den leidenden Tieren sofortige Linderung zu verschaffen und die Verseuchung einzudämmen, bevor sie einen tieferen Tribut für das fragile Gleichgewicht des Landes fordert.",al={"warum gazellen heilen","tonga runentotem beweggrund","warum kranke gazellen helfen"}},f6349169={q="Warum braucht Tonga Runentotem Euch, anstatt die Gazellen selbst zu heilen?",a="Tonga hat es nur geschafft, genug Salbe für zehn Dosen herzustellen und muss im Wegekreuz bleiben, um sich mit den lokalen Behörden abzustimmen und mehr vorzubereiten. Als angehender Druide, der auf dem Pfad des Cenarius wandelt, habt Ihr die Bindung zur Natur, die erforderlich ist, um die verstreuten, kranken Kreaturen aufzuspüren und das Heilmittel zu verabreichen, ohne ihnen weiteren Stress zu verursachen.",al={"warum ich tonga runentotem","warum braucht tonga hilfe","warum keine lokalen wachen"}}},fp="15,202,23.376.0,21.428.0,36.144.0,22.163.0,44.154.0,53.187.0,42.156.0,35.112.0"}
P.entries["quest:613"] = {n="Maurys Fuß aufbrechen",s="In Beutebucht kann MacKinley noch immer nicht einfordern, was Maury ihm schuldete. Maury schloss seine Schuld im eigenen Fuß ein, also schickt MacKinley Reisende zum Ogerhügel der Mosh'Ogg im Schlingendorntal, um den Schlüssel zu finden.",h="In Beutebucht kann MacKinley noch immer nicht einfordern, was Maury ihm schuldete.",kw={"beutebucht","schlüssel","mackinley","maury","mosh'ogg","oger","seewolf","schlingendorntal"},sec={{t="Ein verschlossener Schatz",b="Nachdem der Fuß in Voodoo Dues geborgen wurde, steht Seewolf MacKinley in Beutebucht vor einem weiteren Hindernis. Sein verstorbener Schuldner hat den Fuß verschlossen und die Wertsachen, die er ihm schuldet, darin eingeschlossen."},{t="Der Hügel der Oger",b="Maury spielte mit den Ogern am Ogerhügel der Mosh'Ogg nordöstlich von Beutebucht um Geld. MacKinley erinnert sich, dass Maury erzählte, sie hätten ihn vertrieben, nachdem er zu viel gewonnen hatte. Daher vermutet MacKinley, dass sie den Schlüssel haben, und schickt Euch auf die Suche danach."}},faq={{q="Warum braucht Seewolf MacKinley Maurys Schlüssel?",a="Maury schloss das, was er schuldete, im eigenen Fuß ein. MacKinley braucht den Schlüssel, um ihn zu öffnen und die Schuld einzutreiben.",al={"warum schlüssel nötig","wofür ist der schlüssel","maurys schlüssel zweck"}},{q="Wo wird Maurys Schlüssel vermutet?",a="MacKinley vermutet, dass die Oger der Mosh'Ogg den Schlüssel an ihrem Hügel nordöstlich von Beutebucht haben könnten.",al={"wo ist der schlüssel","fundort des schlüssels","wo maurys schlüssel finden"}},{q="Warum sollten die Oger der Mosh'Ogg den Schlüssel haben?",a="Maury spielte oft mit den Ogern der Mosh'Ogg um Geld. MacKinley erinnert sich, dass sie Maury nach einem großen Gewinn vertrieben, weshalb er vermutet, dass sie den Schlüssel haben könnten.",al={"warum haben die oger den schlüssel","verbindung zwischen maury und den ogern","kannte maury die oger"}},{q="Was geschieht davor bei MacKinleys Geschäften?",a="Das Eintreiben der Schulden in Voodoo Dues folgte auf Scaring Shaky und Return to MacKinley, als MacKinley Schulden rund um Beutebucht beglich.",al={"vorherige quest","reihenfolge der questreihe","was kommt zuerst"}}},fp="21,201,14.173.0,16.220.0,47.101.0,35.93.0,42.139.0,47.122.0"}
P.entries["quest:6130"] = {n="Macht über Gift",s="In Donnerfels kehrt ein junger Druide der Horde zurück, um die Gabe von Vergiftung heilen zu empfangen. Der Initiand hat vergiftete Gazellen nahe dem Wegekreuz mit Kräutermixturen behandelt und tritt nun vor Turak Runentotem auf der Anhöhe der Ältesten.",h="In Donnerfels kehrt ein junger Druide der Horde zurück, um die Gabe von Vergiftung heilen zu empfangen.",kw={"brachland","das wegekreuz","vergiftung heilen","dendrite sternenschauer","die anhöhe der ältesten","mondlichtung","donnerfels","turak runentotem"},ang={["class:Druid"]="Als Druide verbindet Ihr handwerkliche Kräuterkunde in Kalimdor mit Naturmagie und erlangt die dauerhafte Macht, Verbündete von Giften zu befreien.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Wildnis im Herzen Kalimdors vor unnatürlicher Verderbnis zu schützen.",["race:Tauren"]="Als Tauren beweist Ihr Eure Hingabe an den Zirkel des Cenarius und haltet die Weisheit der Earth Mother auf der Anhöhe der Ältesten lebendig."},sec={{t="Eine Lektion im Leiden",b="Der Zirkel des Cenarius verlangt von einem Druiden, Leiden kennenzulernen, bevor er ihm die Macht verleiht, Gift zu heilen. Dendrite Sternenschauer schickt den Novizen zum Wegekreuz, wo Tonga Runentotem ihn Zutaten für eine Salbe sammeln lässt. Indem der Druide die vergifteten Gazellen des Brachlands von Hand und ohne spirituelle Hilfe behandelt, sieht er gewöhnliche Geschöpfe gegen natürliche und unnatürliche Gifte kämpfen."},{t="Rückkehr zur Anhöhe der Ältesten",b="Nach der Prüfung schickt Dendrite den Initianden zu Turak Runentotem, dem Großdruidenlehrer auf der Anhöhe der Ältesten in Donnerfels. Turak warnt, dass seltsame, hochwirksame Gifte nahe dem Wegekreuz das natürliche Gleichgewicht der Ebenen bedrohen. Er lobt die Gelassenheit des Initianden unter Druck und verleiht ihm die spirituelle Kunst des Giftheilens. Die lebenden Geschöpfe Kalimdors stehen nun in der Obhut des Initianden."}},faq={{q="Welchen Zweck hat diese Quest?",a="Die Prüfung lehrt einen Druiden der Horde, Gift zu heilen. Nachdem der Initiand von Hand Heilmittel zubereitet hat, um leidende Gazellen zu retten, kehrt er zu Turak Runentotem zurück und erlernt durch druidische Zwiesprache Vergiftung heilen.",al={"warum macht über gift abschließen","was bewirkt diese quest","zweck der giftquest für druiden"}},{q="Wo befindet sich Turak Runentotem?",a="Turak Runentotem lebt oben auf der Anhöhe der Ältesten in Donnerfels. Er wohnt im Zelt und den ausgehöhlten Ruhestätten, wo Taurendruiden Zwiesprache halten und sich ausbilden lassen.",al={"turak runentotem standort","wo ist turak","turak runentotem finden"}},{q="Wer schickt den Druiden nach Donnerfels zurück?",a="Dendrite Sternenschauer schickt den Druiden nach Donnerfels zurück, nachdem dieser Wildtiere nahe dem Wegekreuz geheilt hat. Der Nachtelfendruide des Zirkels des Cenarius ist in der Mondlichtung stationiert.",al={"wer vergibt macht über gift","questgeber","dendrite sternenschauer"}},{q="Warum ließ der Zirkel des Cenarius den Druiden zunächst Tiere von Hand heilen?",a="Dendrite Sternenschauer lehrt den Druiden, den Aufwand und die Grenzen des Giftheilens zu verstehen, bevor er spirituelle Magie einsetzt. Leidende Geschöpfe kämpfen zu sehen, lehrt Mitgefühl und Achtung vor dem Gleichgewicht der Natur.",al={"warum kranke von hand heilen","warum zuerst salben verwenden","giftlektion für druiden"}},{q="Was beunruhigt Turak Runentotem am Wegekreuz?",a="Turak warnt, dass unnatürliche, aggressive Gifte die Wildtiere nahe dem Wegekreuz erreichen. Er sieht darin eine schwere Störung des Gleichgewichts des Landes, die Wachsamkeit erfordert.",al={"turaks sorge um das wegekreuz","wegekreuz gift gleichgewicht"}},{q="Ist diese Quest für Druiden der Allianz verfügbar?",a="Druiden der Allianz durchlaufen eine vergleichbare Prüfung gleichen Namens. Nachtelfische Initianden kehren zu Mathrengyl Bärenfährte in Darnassus zurück statt zu Turak Runentotem auf der Anhöhe der Ältesten.",al={"können nachtelfen dies machen","allianz macht über gift"}}},fp="17,212,21.384.0,24.381.0,34.197.0,33.141.0,42.172.0,70.206.0,51.171.0,43.166.0"}
P.entries["quest:6132"] = {n="Holt mich hier raus!",s="Im Tal der Speere fürchtet Melizza Brimbuzzle, dass die Maraudine sie fressen wollen. Sie bittet Euch, sie herauszuholen, und ihr Bruder Hornizz verspricht gute Bezahlung.",h="Im Tal der Speere fürchtet Melizza Brimbuzzle, dass die Maraudine sie fressen wollen.",kw={"zentaur","desolace","hornizz brimbuzzle","der kodofriedhof","maraudine","melizza brimbuzzle","das tal der speere"},sec={{t="Ärger im Tal",b="Melizza Brimbuzzle kam ins Tal der Speere und hoffte, mit den Maraudine ein Geschäft abzuschließen. Sie wollten nicht reden, und nun fürchtet sie, dass sie sie fressen wollen. Vor wenigen Minuten belauschte sie Zentauren, die über Holz für ihren Kochtopf sprachen. Sie will schnell fort."},{t="Das Lager ihres Bruders",b="Hornizz Brimbuzzle wartet im Lager der Familie östlich von Melizzas derzeitigem Aufenthaltsort. Es liegt neben dem Kodofriedhof. Melizza verspricht, dass ihr Bruder Euch gut bezahlen wird, wenn Ihr sie aus dem Tal bringt."},{t="Zurück im Lager",b="Hornizz sagt, Melizza habe ihm erzählt, dass Ihr kommen würdet. Er dankt Euch, dass Ihr ihr aus der Patsche geholfen habt, und vermutet dann, dass sie schon wieder in der nächsten steckt. Melizza eilt voraus und sagt, mit den Maraudine lasse sich nur schwer zusammenarbeiten. Sie macht sich zu den Gelkis auf, die sie als vernünftiger bezeichnet."}},faq={{q="Warum steckt Melizza Brimbuzzle in Schwierigkeiten?",a="Melizza ging ins Tal der Speere und hoffte, mit den Maraudine Geschäfte zu machen. Sie wollten nicht reden, und sie fürchtet, dass sie sie fressen wollen.",al={"warum ist melizza gefangen","melizza brimbuzzles geschichte","was ist mit melizza passiert"}},{q="Wer sind die Maraudine?",a="Die Maraudine sind Zentauren aus Desolace. Melizza ging ins Tal der Speere und hoffte, mit ihnen Geschäfte zu machen.",al={"maraudine zentaur","wer sind die maraudine","klan der maraudine"}},{q="Wo befindet sich Hornizz Brimbuzzle?",a="Hornizz Brimbuzzle wartet im Lager der Brimbuzzles in Desolace, neben dem Kodofriedhof und östlich von Melizzas derzeitigem Aufenthaltsort.",al={"hornizz aufenthaltsort","wo ist hornizz","hornizz brimbuzzles lager"}},{q="Warum sagt Melizza, dass ihr Bruder Euch bezahlen wird?",a="Melizza verspricht, dass ihr Bruder Hornizz Euch gut bezahlen wird, wenn Ihr sie aus dem Tal holt.",al={"melizzas belohnung","was zahlt hornizz"}}},fp="19,153,21.252.0,18.197.0,16.275.1,37.136.0,23.110.0,36.128.0,46.88.0"}
P.entries["quest:6134"] = {n="Geisterplasmasuche",s="Hornizz Brimbuzzle schickt Euch ins Tal der Knochen, um Geisterenergie zu sammeln, für die die Magram hoffentlich gut zahlen.",h="Hornizz Brimbuzzle schickt Euch ins Tal der Knochen, um Geisterenergie zu sammeln, für die die Magram...",kw={"dead goliaths","desolace","geistermagnet","ghost-o-plasm","hornizz brimbuzzle","magram","gespenster","tal der knochen"},sec={{t="Ein verwunschenes Tal",b="Hornizz Brimbuzzle schickt Euch nach Südosten ins Tal der Knochen, wo Magram-Geister wandeln. Das Tal klingt für ihn beängstigend. Doch er glaubt, dass die Geister den Magram noch mehr Angst einjagen müssen, und ist sicher, dass die Zentauren für dort eingefangene Geisterenergie gut zahlen würden."},{t="Zwischen den Dead Goliaths",b="Hornizz Brimbuzzle gibt Euch eine Kiste mit Geistermagneten. Stellt einen zwischen den beiden riesigen Skeletten namens Dead Goliaths auf, und er lockt die Geister an. Die Geister liefern Ghost-o-plasm, das Hornizz an die Magram verkaufen will. Er bittet Euch, ihm acht Portionen Ghost-o-plasm und die Kiste zu bringen."},{t="Zurück mit der Beute",b="Als Ihr zurückkehrt, sieht Hornizz Brimbuzzle, dass Ghost-o-plasm auf Euch abgefärbt hat, und nennt es schleimig. Er meint, damit ließe sich ein Vermögen machen, wenn sich die Zentauren davon überzeugen lassen, worum es sich handelt."}},faq={{q="Wer ist Hornizz Brimbuzzle?",a="Hornizz Brimbuzzle unterhält ein Lager südwestlich des Kodofriedhofs in Desolace. Er will Geisterenergie an die Magram-Zentauren verkaufen.",al={"hornizz","brimbuzzle","wer vergibt geisterplasmasuche"}},{q="Wo liegt das Tal der Knochen?",a="Das Tal der Knochen liegt südöstlich von Hornizz Brimbuzzle. Die beiden Dead Goliaths stehen am südlichen Ende des Tals. Es sind die riesigen Skelette, bei denen Ihr den Magneten aufstellt.",al={"tal der knochen lage","wo sind die geister","dead goliaths lage"}},{q="Warum will Hornizz Ghost-o-plasm?",a="Hornizz Brimbuzzle glaubt, dass die Magram-Zentauren für Geisterenergie aus dem verwunschenen Tal der Knochen gut zahlen werden. Er plant, ihnen Ghost-o-plasm zu verkaufen.",al={"warum geisterenergie sammeln","wer kauft ghost-o-plasm","zentauren geisterplasma"}},{q="Wie funktioniert der Geistermagnet?",a="Stellt einen Geistermagneten zwischen den beiden Dead Goliaths auf, und er lockt die Geister des Tals an. Die Geister liefern Ghost-o-plasm.",al={"geistermagnet verwenden","wo geistermagnet aufstellen","magram-geister anlocken"}}},fp="22,111,16.264.0,25.291.0,18.172.1,26.130.0,29.170.0,36.156.0,31.126.0"}
P.entries["quest:6141"] = {n="Bruder Anton",s="Auf der Nijelspitze sucht Bruder Anton Hilfe gegen die Untoten in Desolace. Er kam aus fernen Landen, nachdem er von der Bedrohung gehört hatte.",h="Auf der Nijelspitze sucht Bruder Anton Hilfe gegen die Untoten in Desolace.",kw={"bruder anton","bruder crowley","desolace","die nijelspitze","scharlachrot","untoter"},sec={{t="Ein Bruder in der Fremde",b="Gerüchte über Untote in Desolace erreichten Bruder Anton im fernen Kalimdor. Er buchte sofort eine Überfahrt, um sie aufzuspüren und zu vernichten. Nun sucht er nach Leuten mit Mut und Entschlossenheit. Wenn Euer Herz aufrichtig ist, schickt Bruder Crowley Euch zu ihm auf die Nijelspitze, die Stadt der Allianz in Desolace."},{t="Nachricht aus dem Osten",b="Bruder Anton hat gehört, dass Hilfe aus dem Osten kommt. Er fragt, ob Ihr diese Gerüchte mitgebracht habt und ob Ihr gekommen seid, um beim Kreuzzug des Scharlachroten Bruders zu helfen."}},faq={{q="Wer ist Bruder Anton?",a="Bruder Anton ist Bruder Crowleys Waffenbruder. Als er hörte, dass Untote Desolace heimsuchten, buchte er eine Überfahrt dorthin, um sie zu vernichten.",al={"wer ist anton","bruder anton geschichte","anton desolace"}},{q="Wo ist Bruder Anton zu finden?",a="Bruder Anton ist auf der Nijelspitze zu finden, der Stadt der Allianz in Desolace.",al={"wo ist bruder anton","anton aufenthaltsort","bruder anton fundort"}},{q="Warum ging Bruder Anton nach Kalimdor?",a="Gerüchte über Untote in Desolace in Kalimdor erreichten Bruder Anton. Er buchte sofort eine Überfahrt, um sie zu vernichten.",al={"warum ist anton in desolace","anton mission desolace","warum reiste anton"}}},fp="13,130,16.292.0,18.168.1,21.138.0,33.75.0,37.108.0"}
P.entries["quest:6142"] = {n="Muschelköder",s="In Schattenflucht vertraut Mail'Lahii einem Köder mehr als allen anderen. Er bittet um zehn Stücke weichschaliges Muschelfleisch von dem Schiffswrack weiter nördlich an der Küste.",h="In Schattenflucht vertraut Mail'Lahii einem Köder mehr als allen anderen.",kw={"muschelköder","desolace","angelköder","mail'lahii","schattenflucht","schiffswrack","weichschalige muschel"},sec={{t="Der beste Köder",b="Mail'Lahii bittet Euch um einen Köder, dem Fische nicht widerstehen können. Er hat sein ganzes Leben lang geangelt und vertraut weichschaligem Muschelfleisch mehr als allem anderen. Nördlich von Schattenflucht liegt ein Schiffswrack vor der Küste, und im ganzen Gebiet sind weichschalige Muscheln verstreut. Er möchte zehn Stücke des Fleisches."},{t="Was Mail'Lahii sagt",b="Mail'Lahii sagt, der Hexendoktor habe ihm geraten, gegen seine Kopfschmerzen angeln zu gehen, dann würde es ihm besser gehen. Er fühlt sich bereits besser."}},faq={{q="Wer ist Mail'Lahii?",a="Mail'Lahii ist ein Fischer in Schattenflucht an der Küste von Desolace. Sie hat ihr ganzes Leben lang geangelt.",al={"mailahii","wer bittet um muschelköder","fischer in schattenflucht"}},{q="Wo sind die weichschaligen Muscheln zu finden?",a="Weichschalige Muscheln liegen verstreut um ein Schiffswrack nördlich von Schattenflucht vor der Küste.",al={"muschelköder fundort","wo ist das schiffswrack","weichschaliges muschelfleisch fundort"}},{q="Warum möchte Mail'Lahii Muschelfleisch?",a="Mail'Lahii sagt, weichschaliges Muschelfleisch sei der beste Köder, und Fische könnten ihm nicht widerstehen.",al={"warum muschelköder","warum muschelfleisch"}},{q="Wie viel Muschelfleisch möchte Mail'Lahii?",a="Mail'Lahii möchte zehn Stücke weichschaliges Muschelfleisch.",al={"wie viele muscheln","muschelfleisch menge"}}},fp="9,160,13.279.0,19.127.1,17.98.0,42.98.0,34.82.0,39.53.0"}
P.entries["quest:6143"] = {n="Andere Fische zu grillen",s="In Schattenflucht bittet Euch Drulzegar Skraghook, gegen die Slitherblade zurückzuschlagen. Naga überfielen die Fischer nahe der Insel Ranazjar, und nur Drulzegar kehrte zurück.",h="In Schattenflucht bittet Euch Drulzegar Skraghook, gegen die Slitherblade zurückzuschlagen.",kw={"desolace","drulzegar","myrmidone","naga","andere fische zu grillen","die insel ranazjar","schattenflucht","skraghook","slitherblade","zauberin"},sec={{t="Eine verlorene Besatzung",b="Drulzegar Skraghook und die Besatzung fischten oft nahe der Insel Ranazjar. Die Insel liegt nördlich eines Wracks an der Küste. Eines Morgens griffen die Naga an und töteten alle außer Drulzegar. Nun erfüllen Rachegedanken Drulzegars Sinn, und die Schuldgefühle sind unerträglich."},{t="Die Naga grillen",b="Drulzegar bittet Euch, sieben Slitherblade Myrmidons, sieben Slitherblade Naga und fünf Slitherblade Sorceresses zu töten. Ein lädiertes Knie hindert Drulzegar daran, Euch zu begleiten. Die Naga lauern gewöhnlich tief unten zwischen Korallenriffen unter den Wellen, sagt Drulzegar. Eure Mühe wird belohnt werden."}},faq={{q="Wer ist Drulzegar Skraghook?",a="Drulzegar Skraghook ist ein Fischer in Schattenflucht in Desolace. Die Naga töteten die gesamte Besatzung nahe der Insel Ranazjar, und nur Drulzegar überlebte.",al={"drulzegar","drulzegar skraghook","wer vergibt andere fische zu grillen"}},{q="Wo wurde Drulzegars Besatzung angegriffen?",a="Die Naga griffen bei der Insel Ranazjar an, nördlich eines Wracks an der Küste. Die Besatzung fischte dort oft, und der Angriff erfolgte eines Morgens.",al={"wo wurden die fischer angegriffen","angriffsort der besatzung","hinterhalt bei der insel ranazjar"}},{q="Warum bekämpft Drulzegar die Naga nicht selbst?",a="Ein lädiertes Knie hindert Drulzegar daran, die Naga zu bekämpfen. Drulzegar sagt, er würde Euch helfen, sie zu töten, wenn die Verletzung nicht wäre. Schuldgefühle wegen der Besatzung lasten schwer auf Drulzegars Gewissen.",al={"warum kann drulzegar nicht kämpfen","drulzegars lädiertes knie"}},{q="Wo lauern die Naga der Slitherblade?",a="Drulzegar sagt, die Naga der Slitherblade lauern gewöhnlich tief unten zwischen Korallenriffen unter den Wellen. Die Besatzung wurde nahe der Insel Ranazjar angegriffen.",al={"aufenthaltsort der slitherblade","wo sind naga der slitherblade zu finden","aufenthaltsort der naga in desolace"}},{q="Welche Naga will Drulzegar beseitigt sehen?",a="Drulzegar will sieben Slitherblade Myrmidons, sieben Slitherblade Naga und fünf Slitherblade Sorceresses getötet sehen.",al={"welche naga müssen getötet werden","ziele für andere fische zu grillen","anforderungen für slitherblade"}}},fp="17,164,11.247.0,12.274.0,27.160.0,48.132.0,45.180.0,36.137.0,42.110.0"}
P.entries["quest:616"] = {n="Die Spukinsel",s="In Beutebucht hört Krazek von einer Insel, auf der ein Goblingeist spukt. Er sammelt ungewöhnliche Gerüchte für Baron Revilgaz, und dieses erinnert an eine alte Trolllegende.",h="In Beutebucht hört Krazek von einer Insel, auf der ein Goblingeist spukt.",kw={"baron revilgaz","beutebucht","goblingeist","krazek","stein der gezeiten","schlingendorntal","trolllegende","wasserelementare"},sec={{t="Tavernengeschichten in Beutebucht",b="Krazek sammelt für Baron Revilgaz Berichte über seltsame Geschehnisse im ganzen Schlingendorntal. In einer Taverne in Beutebucht erzählen ihm Seeleute von einer Insel vor der Küste, auf der Wasserelementare hausen. Sie sagen, der Geist eines rasenden Goblins gehe dort um. Krazek schenkt Geistergerüchten wenig Beachtung, doch diese Geschichte weckt seine Aufmerksamkeit. Er bittet Euch, sie dem Baron zu überbringen."},{t="Eine Trolllegende",b="Baron Revilgaz erinnert sich an eine alte Trolllegende aus einem Buch, als er Krazeks Bericht hört. Die Wasserelementare und die Goblinerscheinung lassen ihn vermuten, dass der Stein der Gezeiten in greifbarer Nähe sein könnte. Er hofft, das uralte Relikt seiner persönlichen Artefaktsammlung hinzuzufügen."}},faq={{q="Wer schickt Euch zu Baron Revilgaz?",a="Krazek bittet Euch, Baron Revilgaz das Gerücht zu überbringen, nachdem er Seeleute in einer Taverne in Beutebucht eine beunruhigende Geschichte erzählen hörte.",al={"wer vergibt die spukinsel","spukinsel questgeber","krazeks gerücht"}},{q="Welche Gerüchte erzählten die Seeleute?",a="Die Seeleute erzählen von einer Insel vor der Küste, auf der Wasserelementare hausen und der Geist eines rasenden Goblins umgeht.",al={"was ist auf der insel","gerücht über die spukinsel","seemannsgeschichten"}},{q="Warum interessiert sich Baron Revilgaz für eine Geistergeschichte?",a="Baron Revilgaz erinnert sich an eine alte Trolllegende aus einem Buch. Die Berichte deuten darauf hin, dass sich der uralte Stein der Gezeiten auf der Insel befinden könnte.",al={"warum revilgaz es wissen will","revilgaz' reaktion","interesse am stein der gezeiten"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Baron Revilgaz verweist Euch auf den Stein der Gezeiten und führt damit die Suche weiter.",al={"welche quest kommt als nächstes","folgequest der spukinsel","nächster schritt nach der spukinsel"}}},fp="16,159,25.358.0,14.275.0,43.121.0,34.114.0,49.133.0,40.86.0"}
P.entries["quest:6161"] = {n="Nehmt Rackmores Schatz!",s="Bei „Nehmt Rackmores Schatz!“ berichtet Rackmores Logbuch von einem Schiff, das auf dem Weg zur Mondfederfeste angegriffen wurde. Er versteckte seine Schatztruhe auf der Insel Ranazjar, um sie vor seinen Feinden zu schützen, doch beide Schlüssel zum Öffnen gingen verloren.",h="Bei „Nehmt Rackmores Schatz!“ berichtet Rackmores Logbuch von einem Schiff, das auf dem Weg zur...",kw={"truhe","desolace","mondfederfeste","goldener schlüssel","rackmore","die insel ranazjar","silberner schlüssel"},sec={{t="Eine verborgene Truhe",b="Rackmores Logbuch berichtet von seefahrenden Kreaturen, die sein Schiff auf dem Weg zur Mondfederfeste angriffen. Er versteckte seine Schatztruhe auf der Insel Ranazjar, um sie vor seinen Feinden zu schützen. Beide Schlüssel, die zum Öffnen benötigt werden, gingen verloren, einer aus Silber und einer aus Gold. Wer die Schlüssel und die Truhe findet, wird einen Schatz finden."}},faq={{q="Wohin segelte Rackmores Schiff, als es angegriffen wurde?",a="Rackmores Schiff war auf dem Weg zur Mondfederfeste, als seefahrende Kreaturen es angriffen.",al={"rackmores ziel","wohin wollte rackmore","rackmores schiffsroute"}},{q="Wo ist Rackmores Truhe versteckt?",a="Rackmore versteckte die Truhe auf der Insel Ranazjar.",al={"wo ist rackmores truhe","rackmores truhenversteck","truhe auf der insel ranazjar"}},{q="Was wird benötigt, um die Truhe aufzuschließen?",a="Zum Öffnen der Truhe werden zwei Schlüssel benötigt, einer aus Silber und einer aus Gold. Beide gingen verloren.",al={"schlüssel zu rackmores truhe","wie öffnet man rackmores truhe","was öffnet rackmores truhe"}},{q="Warum versteckte Rackmore seinen Schatz?",a="Rackmore versteckte die Truhe auf der Insel Ranazjar, um seinen Schatz vor seinen Feinden zu schützen, nachdem seefahrende Kreaturen sein Schiff angegriffen hatten.",al={"warum rackmores schatz verstecken","rackmores beweggrund für das schatzversteck"}}},fp="26,220,14.295.0,55.94.0,33.40.0,35.79.0,35.122.0"}
P.entries["quest:617"] = {n="Bündelweise Akiris",s="In Beutebucht sucht Freibeuter Bloads Akirisschilf für einen Geschäftspartner, der gut zahlt. Die Naga wurden zuletzt am nördlichen Strand gesichtet, wo Ihr ihnen das Schilf abnehmen müsst.",h="In Beutebucht sucht Freibeuter Bloads Akirisschilf für einen Geschäftspartner, der gut zahlt.",kw={"akirisschilf","beutebucht","groy","naga","freibeuter bloads","schilf","schlingendorntal"},sec={{t="Eine einträgliche Meerespflanze",b="Freibeuter Bloads bietet in Beutebucht Arbeit am Meer an. Sein Geschäftspartner Groy zahlt gut für Bündel aus Akirisschilf, einer Pflanze, die am Meer wächst und den Namen trägt, den die Naga ihr geben. Bloads weiß nicht, warum Groy das Schilf haben möchte. Er braucht zehn Stängel, und die Naga wurden zuletzt am nördlichen Strand gesichtet."}},faq={{q="Wer ist Freibeuter Bloads?",a="Freibeuter Bloads ist ein Freibeuter in Beutebucht, der allen Arbeit anbietet, die danach fragen.",al={"bloads","wer vergibt bündelweise akiris","wer ist bloads"}},{q="Was ist Akirisschilf?",a="Akirisschilf ist eine wertvolle Meerespflanze, die von den Naga so genannt wird. Freibeuter Bloads weiß nicht, wozu sie dient, aber Sammler zahlen gut für Bündel ihrer Stängel.",al={"akirisschilf","was ist akirisschilf","wofür wird akiris verwendet"}},{q="Wo sind die Naga zu finden, die das Schilf haben?",a="Die Naga mit den Stängeln streifen an der Küste nördlich von Beutebucht umher, entlang der Strände des Schlingendorntals.",al={"wo sind die naga","wo gibt es akirisschilf","akirisschilf fundort"}},{q="Wer kauft Freibeuter Bloads das Schilf ab?",a="Bloads sammelt die Bündel für einen Geschäftspartner namens Groy, der mit dem Verkauf des Meeresschilfs einen beträchtlichen Gewinn erzielt.",al={"wer ist groy","wer will akirisschilf","bloads käufer"}}},fp="20,169,24.293.0,24.78.0,23.161.0,46.105.0,41.114.0"}
P.entries["quest:618"] = {n="Negolash entgegentreten",s="An der Küste des Schlingendorntals setzt ein gestohlener Krummsäbel Ereignisse in Gang. Sprogger weiß, wie er Negolash mit den Lieblingsspeisen und -getränken des Riesen hervorlocken kann.",h="An der Küste des Schlingendorntals setzt ein gestohlener Krummsäbel Ereignisse in Gang.",kw={"ödland","bussardflügel","kapitän smotts","dschungelrankenwein","negolash","smotts' krummsäbel","sprogger","schlingendorntal"},ang={["profession:Cooking"]="Als Koch könnt Ihr Sproggers Handwerk würdigen. Er reiste ins Ödland, um das besondere Rezept für Barbecued Buzzard Wings zu lernen, das im Mittelpunkt seines Plans steht."},sec={{t="Ein hungriger Riese",b="Als Riesen das Schiff von Kapitän Smotts zerstörten, steuerte Negolash die Kombüse an. Er ließ die Mannschaft in Ruhe und machte sich über Wein und Barbecued Buzzard Wings her, Sproggers Spezialität. Sprogger war ins Ödland gereist, um das Rezept zu lernen."},{t="Die Falle im Rettungsboot",b="Sprogger plant, Negolash mit einem Festmahl anzulocken. Ihr bringt zehn Portionen Flügel und fünf Flaschen Wein zum zerstörten Rettungsboot von Kapitän Smotts an der südöstlichen Küste. Das Festmahl lockt den Riesen herbei. Dann könnt Ihr ihm entgegentreten und den Krummsäbel des Kapitäns zurückholen."}},faq={{q="Wer ist Negolash?",a="Negolash ist ein Riese, der an der Zerstörung des Schiffs von Kapitän Smotts beteiligt war. Er plünderte die Kombüse nach Speisen und Getränken, statt die Seeleute zu jagen.",al={"was ist negolash","wer ist der riese","negolash geschichte"}},{q="Woher weiß Sprogger, wie man Negolash anlockt?",a="Sprogger sah, wie Negolash beim Schiffbruch seine Küche plünderte. Der Riese bevorzugte Sproggers Barbecued Buzzard Wings und Flaschen mit Dschungelrankenwein, weshalb sich diese Vorräte als Köder eignen.",al={"wie negolash anlocken","warum bussardflügel","negolash essen"}},{q="Wo findet die Konfrontation statt?",a="Die Konfrontation findet im zerstörten Rettungsboot von Kapitän Smotts statt, das südöstlich von Sprogger an der Küste gestrandet ist.",al={"wo ist negolash","wo das essen platzieren","rettungsboot fundort"}},{q="Was ging dieser Aufgabe voraus?",a="Die Spur beginnt mit The Monogrammed Sash und führt über The Captain's Cutlass zu dieser Konfrontation.",al={"welche quest kommt zuerst","negolash entgegentreten vorherige quest","voraussetzungen für negolash"}}},fp="15,155,14.228.0,24.259.0,16.133.0,44.185.0,40.110.0,27.113.0"}
P.entries["quest:6181"] = {n="Eine eilige Nachricht",s="Rüstmeister Lewis braucht Rüstungen für Westfalls Miliz und schickt per Greif eine dringende Nachricht nach Sturmwind. Da die Streitkräfte des Königreichs kaum helfen, bittet er Euch, die Anforderung zu Thor an der Späherkuppe zu bringen, für den Flug in die Hauptstadt.",h="Rüstmeister Lewis braucht Rüstungen für Westfalls Miliz und schickt per Greif eine dringende Nachricht nach...",kw={"rüstung","flugmeister","greif","die altstadt","osric strang","volksmiliz","rüstmeister lewis","späherkuppe","sturmwind","thor"},ang={["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr die Spannungen zwischen der Hauptstadt Sturmwind und den bedrängten Grenzvorposten in Westfall.",["race:Human"]="Als Mensch aus dem Königreich tragt Ihr Lewis' Nachricht, während Sturmwinds Provinzen unter Druck stehen. Ihr lernt außerdem die Greifenrouten kennen, die die Gebiete des Königreichs verbinden."},sec={{t="Ein Hilferuf am Himmel",b="An der Späherkuppe stellt sich die Volksmiliz Defias-Gesetzlosen und Gnollen entgegen und erhält dabei kaum Hilfe von Sturmwinds Streitkräften. Rüstmeister Lewis verlässt sich für Waffen und Rüstungen auf private Kontakte in der Hauptstadt. Als die Vorräte der Miliz zur Neige gehen, wendet er sich an Osric Strang, einen Rüstungsschmied in der Altstadt. Lewis bittet Reisende, das dringende Anforderungsschreiben zu Thor zu bringen, Westfalls Greifenmeister."},{t="Das Flugnetz",b="Greifen befördern Menschen und Nachrichten rasch durch das Königreich Sturmwind. Thor betreut die Flugroute von der Späherkuppe in die Hauptstadt. Wenn Ihr ihm Lewis' Nachricht übergebt, bringt er die Anforderung auf dem Luftweg nach Sturmwind. Diese Route verbindet Westfalls Grenzgarnison trotz fehlender offizieller Hilfe mit der Hauptstadt."}},faq={{q="Warum muss Rüstmeister Lewis eine Nachricht nach Sturmwind schicken?",a="Sturmwind leistet Westfall kaum direkte militärische Hilfe, und der Volksmiliz gehen die Rüstungen aus. Lewis schickt eine Anforderung an Osric Strang, einen vertrauenswürdigen Rüstungsschmied in der Stadt, um Nachschub zu sichern.",al={"warum nachricht schicken","zweck von lewis' nachricht","warum sturmwind kontaktieren"}},{q="Wer ist Osric Strang?",a="Osric Strang ist ein Rüstungsschmied in Sturmwinds Altstadt, dessen Laden Limited Immunity heißt. Er versorgt Lewis privat, wenn die offiziellen Wege versagen.",al={"osric strang","wer ist osric","besitzer von limited immunity"}},{q="Wer ist Thor?",a="Thor ist der Greifenmeister an der Späherkuppe. Er befördert Lewis' Nachricht zwischen Westfall und Sturmwind und betreut die Greifenflüge, die beide verbinden.",al={"wer ist thor","flugmeister westfall","thor greifenmeister"}},{q="Warum schickt Sturmwind nicht direkt Soldaten und Ausrüstung nach Westfall?",a="König Varian Wrynn wird vermisst, und Sturmwinds Mittel sind knapp. Die Führung hat die abgelegenen Agrargebiete weitgehend vernachlässigt, sodass Orte wie die Späherkuppe auf freiwillige Milizen und private Absprachen angewiesen sind.",al={"warum keine hilfe aus sturmwind","warum ignoriert sturmwind westfall","wo ist die armee"}},{q="Kann jeder Abenteurer diese Aufgabe übernehmen?",a="Jeder Abenteurer der Allianz kann sie übernehmen. Abenteurern, die sich in Westfall bewährt haben, wird diese Arbeit anvertraut. Sie macht mit den Greifenrouten des Königreichs vertraut.",al={"wer kann diese quest annehmen","quest nur für menschen","können zwerge diese quest machen"}},{q="Wohin führt diese Kuriermission als Nächstes?",a="Nachdem Ihr Thor die Nachricht übergeben habt, bereitet er einen Greifenflug nach Sturmwind vor. Ihr landet am Greifenhorst der Hauptstadt und sucht dann Osric Strang in der Altstadt auf.",al={"nächster schritt","was passiert nach thor","wohin geht es als nächstes"}}},fx={be76534e={q="Warum bittet Rüstmeister Lewis Euch, seine Nachricht zu überbringen?",a="Die Verteidiger von Westfall sind überstrapaziert, von der Krone verlassen und werden von Defias-Banditen in den Ebenen belagert. Rüstmeister Lewis kann das Versorgungslager der Späherkuppe nicht aufgeben, und die Leute der Miliz können keine vereidigten Verteidiger entbehren, um als einfache Boten zu dienen, wenn jede Klinge an der Wachtlinie benötigt wird. Ein fähiger Reisender, der sich in Richtung der Hauptstadt bewegt, bietet den schnellsten, sichersten Weg, um lebenswichtige Vorräte zu arrangieren, ohne den Außenposten unterbesetzt zu lassen.",al={"warum braucht lewis mich","warum keine wache nach sturmwind schicken","warum lewis nachricht überbringen"}}},fp="15,244,23.376.0,18.312.0,62.196.0,20.146.0,12.149.0,67.224.0,39.164.0,42.155.0"}
P.entries["quest:619"] = {n="Negolash anlocken",s="An der Küste des Schlingendorntals bietet ein gekennzeichnetes Rettungsboot eine Möglichkeit, Negolash anzulocken. Zehn Barbecued Buzzard Wings und fünf Flaschen Dschungelrankenwein liegen auf dem Wrack.",h="An der Küste des Schlingendorntals bietet ein gekennzeichnetes Rettungsboot eine Möglichkeit, Negolash...",kw={"barbecued buzzard wing","dschungelrankenwein","negolash","ruined lifeboat","smotts revenge","schlingendorntal"},sec={{t="Eine verlockende Gabe",b="Das verlassene Rettungsboot trägt die verblassten Worte Smotts' Revenge. Während Ihr Negolash jagt, legt zehn Barbecued Buzzard Wings und fünf Flaschen Dschungelrankenwein auf das Wrack, um ihn hervorzulocken."}},faq={{q="Was ist das Ruined Lifeboat?",a="Das Ruined Lifeboat ist ein verlassenes, beschädigtes Boot mit den verblassten Worten Smotts' Revenge. Dort könnt Ihr Essen und Getränke anrichten, um Negolash anzulocken.",al={"smotts revenge boot","rettungsboot strangletorn","was ist smotts revenge"}},{q="Welche Vorräte werden für die Gabe benötigt?",a="Für die Gabe werden zehn Barbecued Buzzard Wings und fünf Flaschen Dschungelrankenwein benötigt, die auf dem Wrack aufgeschichtet werden.",al={"welches essen wird benötigt","negolash anlocken gegenstände","welche gegenstände für negolash"}},{q="Wann wird diese Aufgabe verfügbar?",a="Ihr könnt die Gabe nur vorbereiten, während Ihr Negolash jagt.",al={"wann ist negolash anlocken möglich","facing negolash voraussetzung","negolash anlocken freischalten"}}},fp="17,164,19.187.0,28.148.0,46.108.0,37.57.0"}
P.entries["quest:62"] = {n="Die Tiefenschachtmine",s="Südlich von Goldhain schickt Euch Marschall Dughan zur Erkundung der von Kobolden besetzten Tiefenschachtmine. Sie liegt zwischen den Bauernhöfen der Steinfelds und Maclures, und ihr Fall deutet auf Schwierigkeiten jenseits ihrer Stollen hin.",h="Südlich von Goldhain schickt Euch Marschall Dughan zur Erkundung der von Kobolden besetzten Tiefenschachtmine.",kw={"dughan","elwynn","tiefenschachtmine","goldhain","jaspismine","kobold","maclure","steinfeld"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr in der überrannten Mine ein weiteres Zeichen dafür, dass Sturmwind Mühe hat, Elwynns wichtige Stätten zu schützen.",["profession:Mining"]="Als Bergarbeiter könnt Ihr in der Tiefenschachtmine reiche Kupferadern finden, doch Kobolde, die ihr Revier verteidigen, stehen Euch im Weg."},sec={{t="Ärger südlich von Goldhain",b="Kobolde haben die Tiefenschachtmine südlich von Goldhain zwischen den Gehöften der verfeindeten Steinfelds und Maclures eingenommen. Einst lieferte sie Stein und Erz für das Reich. Nun hallt schrilles Geschnatter durch ihre feuchten Stollen, in denen Talgkerzen brennen. Marschall Dughan schickt Euch los, um die Tiefen auszukundschaften und herauszufinden, wie schlimm die Lage ist."},{t="Eine überlastete Wache",b="Als Dughan Euren Bericht hört, sorgt er sich um andere Abbaustätten, darunter die Jaspismine im Nordosten. Die Nachricht verschärft die angespannte Lage der Wache von Sturmwind. Ihre Truppen sind bereits durch die Abwehr von Defias-Banditen und Gnolleinfällen ausgelastet, sodass zu wenige bleiben, um die Stollen zu räumen."}},faq={{q="Wo liegt die Tiefenschachtmine?",a="Die Tiefenschachtmine liegt fast genau südlich von Goldhain im Wald von Elwynn, zwischen den Gehöften der Steinfelds und Maclures.",al={"tiefenschachtmine lage","wo ist die tiefenschachtmine","tiefenschachtmine karte"}},{q="Wer schickt Euch zur Erkundung der Tiefenschachtmine?",a="Marschall Dughan, der befehlshabende Offizier der Wache von Sturmwind in Goldhain, schickt Euch zur Erkundung der Stollen.",al={"wer vergibt die quest zur tiefenschachtmine","marschall dughan quest"}},{q="Welche Kreaturen haben die Mine eingenommen?",a="Kobolde haben die Mine überrannt, ihre Kerzen entzündet und die menschlichen Arbeiter vertrieben.",al={"wer ist in der tiefenschachtmine","welche monster sind in der tiefenschachtmine"}},{q="Warum braucht Marschall Dughan Abenteurer, um die Mine zu überprüfen?",a="Die Wache von Sturmwind ist durch örtliches Banditenunwesen, verbliebene Orktruppen und Gnollüberfälle so ausgelastet, dass Dughan selbst zur Bestätigung von Späherberichten keine Soldaten übrig hat.",al={"warum späher schicken","warum geht die wache nicht"}},{q="Was geschieht nach der Erkundung der Tiefenschachtmine?",a="Nachdem Ihr Marschall Dughan von den Schwierigkeiten berichtet habt, befürchtet er, dass sie weit verbreitet sind, und schickt Euch nach Nordosten zur Untersuchung der Jaspismine.",al={"nächste quest nach der tiefenschachtmine","what comes next"}},{q="Warum ist der Befall der Tiefenschachtmine bedeutsam?",a="Der Fall der Tiefenschachtmine zeigt, dass der Koboldbefall in Nordhain kein Einzelfall war. Bedrohungen aus der Wildnis dringen rasch auf das besiedelte Ackerland unmittelbar vor den Toren Sturmwinds vor.",al={"warum ist die tiefenschachtmine wichtig","geschichte der tiefenschachtmine"}}},fx={["88321243"]={q="Warum haben Kobolde die Tiefenschachtmine übernommen?",a="Kobolde sind natürliche Tunnelbewohner, die ständig unter der Erde nach Gold und wertvollen Mineralien suchen. Da die Wachen von Sturmwind überstrapaziert sind, um die Region vor Defias-Banditen und wilden Tieren zu schützen, wurden die lokalen Minen weitgehend unbewacht gelassen. Angelockt von reichen Erz- und Goldvorkommen, schwärmten die Ungeziefer in die Tiefenschachtmine, gruben sich tief ein und vertrieben alle Arbeiter.",al={"warum sind kobolde in der tiefenschachtmine","kobolde tiefenschachtmine warum","wer ist in der tiefenschachtmine"}}},fp="18,186,26.319.0,16.294.0,36.118.0,42.102.0,40.83.0,59.156.0,47.133.1,53.184.0"}
P.entries["quest:621"] = {n="Zanzils Geheimnis",s="Crank Fizzlebub sucht Zanzils Geheimnis in den Ruinen nordöstlich von Beutebucht. Das Gebräu des verbannten Trolls beugt den Willen und stärkt den Körper, und Crank will Proben für sich selbst.",h="Crank Fizzlebub sucht Zanzils Geheimnis in den Ruinen nordöstlich von Beutebucht.",kw={"aboraz","beutebucht","fizzlebub","jubuwal","mixtur","schlingendorntal","zanzil"},sec={{t="Willensbeugende Tränke",b="Nordöstlich von Beutebucht hat sich Zanzil in den Ruinen von Jubuwal und Aboraz niedergelassen. Seine früheren Stammesführer verstießen ihn, weil sie seine Macht über den Geist anderer fürchteten. Nun beherrscht er seine Anhänger mit Gebräuen aus Dschungelpflanzen. Die Mischungen betäuben ihren Willen und steigern ihre Kraft, sodass sie gefügig, aber widerstandsfähig werden."},{t="Eine einträgliche Mixtur",b="Crank Fizzlebub sieht in Zanzils Handwerk eine Einnahmequelle. Wer Macht über andere will, könnte für ein solches Gebräu fürstlich zahlen, also will der Goblin einen Vorrat aus den Ruinen. Liefert Ihr genügend Proben, bietet Crank den üblichen Lohn und einen stillen Bonus, wenn Ihr über den Handel schweigt."}},faq={{q="Wer ist Zanzil the Outcast?",a="Zanzil ist ein verbannter Troll, der in den Ruinen nordöstlich von Beutebucht lebt. Seine Anführer verbannten ihn, weil sie seine Macht über den Geist anderer fürchteten.",al={"wer ist zanzil","zanzils geschichte","warum wurde zanzil verbannt"}},{q="Was bewirkt Zanzils Mixtur eigentlich?",a="Zanzils Gebräu wird aus Dschungelpflanzen hergestellt, unterdrückt den freien Willen des Trinkenden und stärkt den Körper auf unnatürliche Weise.",al={"was ist zanzils mixtur","wirkung von zanzils mixtur","wirkung von zanzils trank"}},{q="Wo lebt Zanzil?",a="Zanzil und seine Anhänger leben in den Ruinen von Jubuwal und Aboraz, nordöstlich von Beutebucht im Schlingendorntal.",al={"zanzils aufenthaltsort","wo ist zanzil","wo sind die ruinen"}},{q="Warum will Crank Fizzlebub die Mixtur?",a="Crank Fizzlebub glaubt, dass jene, die Macht über andere wollen, gut für das Gebräu zahlen würden, und hat auch eigene Verwendungszwecke im Sinn.",al={"warum will crank die mixtur","was will crank mit zanzils mixtur machen"}},{q="Warum zahlte Crank bei der Übergabe mehr?",a="Crank zahlt einen Bonus, um Euer Stillschweigen zu erkaufen und die Beschaffung des willensbeugenden Gebräus geheim zu halten.",al={"crank fizzlebub zusatzlohn","cranks lohn für stillschweigen"}}},fp="15,171,21.317.0,19.270.0,26.143.0,39.111.0,25.111.0,42.122.0,38.100.1"}
P.entries["quest:622"] = {n="Rückkehr zu Corporal Kaleb",s="Im Rebellenlager wartet Corporal Kaleb auf den Topf, den Krazek in Beutebucht repariert hat. Er hat eine zweite Dampfpfeife und ein in seinen Boden eingebautes Hackmesser.",h="Im Rebellenlager wartet Corporal Kaleb auf den Topf, den Krazek in Beutebucht repariert hat.",kw={"beutebucht","corporal kaleb","kochtopf","krazek","rebellenlager","schlingendorntal"},sec={{t="Ein besserer Topf",b="Krazek hat den Topf fertig repariert, den Ihr ihm gebracht habt. Er hat eine weitere Dampfpfeife hinzugefügt und ein Hackmesser in den Boden eingebaut, scharf genug, um Beinknochen zu durchtrennen. Er nennt das einen sicheren Weg, den Koch zufriedenzustellen, und erwartet, dass sich der Besitzer über die Änderungen freut. Nun kann der Topf zu Corporal Kaleb im Rebellenlager zurückgebracht werden."},{t="Zurück im Lager",b="Corporal Kaleb ist begeistert, dass der Topf funktioniert, und endlich kann das Abendessen beginnen. Er hofft, dass Eure Zeit in Beutebucht gut verlaufen ist, auch wenn er die Stadt als rau bezeichnet. Er erzählt auch ein Gerücht: Goblins verschleppen manchmal betrunkene Seeleute auf Sklavenschiffe, die zu unbekannten Zielen aufbrechen."}},faq={{q="Wer ist Corporal Kaleb?",a="Corporal Kaleb wartet im Rebellenlager auf den Kochtopf, den Krazek in Beutebucht repariert.",al={"corporal kaleb","wer ist kaleb","kaleb rebellenlager","wo ist corporal kaleb","kaleb aufenthaltsort"}},{q="Was hat Krazek mit dem Topf gemacht?",a="Krazek hat den Topf repariert, eine weitere Dampfpfeife hinzugefügt und ein neues Hackmesser in den Boden eingebaut, scharf genug, um Beinknochen zu durchtrennen.",al={"krazek topf verbesserungen","was hat krazek repariert","krazek kochtopf"}},{q="Was kam vor diesem Schritt?",a="Favor for Krazek kam zuerst.",al={"vorherige quest","was führte zur rückkehr zu corporal kaleb"}}},fp="24,146,12.312.0,16.265.1,22.98.0,30.132.0,27.28.0"}
P.entries["quest:623"] = {n="Bündelweise Akiris",s="Im Schlingendorntal hat Bloads ein frisches Bündel Akirisschilfrohr für die Insel Theramore bereit. Sein Kontakt, Freibeuter Groy, hat einen Kunden, der dringend mehr möchte, doch Bloads kann erst in einer Woche in die Düstermarschen segeln.",h="Im Schlingendorntal hat Bloads ein frisches Bündel Akirisschilfrohr für die Insel Theramore bereit.",kw={"akiris","bloads","düstermarschen","groy","freibeuter","schilfrohr","schlingendorntal","theramore"},ang={["faction:Alliance"]="Die Insel Theramore ist eine Hochburg der Allianz in den Düstermarschen. Bloads warnt, dass Besucher dennoch Ärger bekommen können, wenn sie zum falschen Schlag gehören."},sec={{t="Überfahrt nach Theramore",b="Während Eurer Abwesenheit erreicht Euch eine Nachricht von jenseits des Meeres. Freibeuter Groy auf der Insel Theramore ist mit der letzten Lieferung Akirisschilfrohr zufrieden, und ein Kunde möchte sofort ein weiteres Bündel. Freibeuter Bloads kann erst in einer Woche in die Düstermarschen segeln. Also gibt er Euch das Paket, damit Ihr es persönlich über das Meer bringt."},{t="Lieferung an den Docks",b="Freibeuter Groy wartet an den Docks von Theramore. Zunächst weist er Fremde ab, doch als er erfährt, dass Bloads die Lieferung veranlasst hat, prüft er das Bündel genau. Zufrieden mit dem Schilfrohr zahlt er Euch für den Transport einen Anteil in Münzen. Dann warnt er Reisende davor, sich an seinen Docks aufzuhalten."}},faq={{q="Wer ist Freibeuter Groy?",a="Freibeuter Groy ist der Kontakt von Freibeuter Bloads auf der Insel Theramore in den Düstermarschen. Groy hat einen Kunden, der mehr Akirisschilfrohr möchte.",al={"wer ist groy","groy theramore","freibeuter groy"}},{q="Warum braucht Freibeuter Bloads einen Kurier?",a="Bloads hat gehört, dass Groys Kunde dringend ein weiteres Bündel Akirisschilfrohr möchte. Bloads kann erst in einer Woche in die Düstermarschen segeln, also bittet er Euch, es über das Meer zu bringen.",al={"warum schilfrohr transportieren","warum theramore","bloads lieferung"}},{q="Wohin muss diese Lieferung gebracht werden?",a="Das Bündel ist für die Insel Theramore bestimmt, einen Hafen der Allianz in den Düstermarschen.",al={"wohin das schilfrohr bringen","akiris lieferort","düstermarschen lieferung"}},{q="Was ging dieser Reise voraus?",a="Diese Lieferung folgt auf das erste Sammeln von Akirisschilfrohr im Schlingendorntal, bei dem Bündel zu Freibeuter Bloads gebracht wurden.",al={"vorherige quest","akirisschilfrohr questreihe","voraussetzung"}}},fp="20,209,23.311.0,21.279.1,22.128.0,41.182.0,36.77.0,30.127.0"}
P.entries["quest:624"] = {n="Cortellos Rätsel",s="Ein Pergament mit Cortellos Rätsel taucht an Bord von Schiffen der Blutsegelbukaniere entlang der wilden Ufer auf. Seine Verse führen Euch zu einem Hinweis unter einer verzierten Brücke.",h="Ein Pergament mit Cortellos Rätsel taucht an Bord von Schiffen der Blutsegelbukaniere entlang der wilden Ufer...",kw={"blutsegelbukaniere","brücke","cortello","rätsel","schriftrolle","sümpfe des elends","die wilden ufer"},sec={{t="Das Rätsel eines Bukaniers",b="Blutsegelbukaniere, die vor der Südküste des Schlingendorntals ankern, tragen verstreute Notizen mit einem Reim bei sich. Cortellos Verse beschreiben eine kunstvoll gearbeitete Brücke, abgenutzt von vielen Reisenden. Sie liegt östlich der Totenwinde und südlich des Rotkammgebirges. Folgt der Wegbeschreibung aus dem Dschungel hinaus und in die Sümpfe, wo darunter etwas wartet."},{t="Der Übergang im Sumpf",b="Die Verse führen unter eine verzierte Brücke, die die Sümpfe des Elends überspannt. Im trüben Wasser darunter liegt ein durchnässtes Pergament mit dem nächsten Schritt in Cortellos Rätsel."}},faq={{q="Wo beginnt dieses Geheimnis?",a="Das Geheimnis beginnt mit einem Pergamentfetzen in der Flotte der Blutsegelbukaniere, die vor den wilden Ufern südlich von Beutebucht ankert.",al={"wo beginnt cortellos rätsel","cortellos rätsel startort","wo findet sich cortellos rätsel"}},{q="Welchen Ort beschreibt das Rätsel?",a="Der Reim beschreibt eine viel genutzte, verzierte Brücke in den Sümpfen des Elends, östlich des Gebirgspasses der Totenwinde und südlich des Rotkammgebirges.",al={"welche brücke beschreibt cortellos rätsel","wohin weist das rätsel","brücke östlich der totenwinde südlich des rotkammgebirges"}},{q="Wonach sucht Ihr unter der Brücke?",a="Das Rätsel weist auf einen Hinweis hin, der unter der Brücke wartet.",al={"was findet sich in den sümpfen des elends","cortello hinweis unter der brücke","was liegt unter der brücke"}},{q="Wer hat das Rätsel geschrieben?",a="Das Rätsel trägt Cortellos Namen, doch das Pergament verrät nichts weiter darüber, wer er war.",al={"wer ist cortello","cortello hintergrundgeschichte","wer hat cortellos rätsel verfasst"}}},fp="17,163,20.319.0,18.160.1,30.131.0,41.134.0,46.55.0,21.87.0"}
P.entries["quest:625"] = {n="Cortellos Rätsel",s="Reisende folgen Cortellos zweitem Vers über das Meer nach Kalimdor. Seine Zeilen weisen Schatzsuchern den Weg zu einer Höhle im Südwesten der Düstermarschen.",h="Reisende folgen Cortellos zweitem Vers über das Meer nach Kalimdor.",kw={"blutsumpfbau","cortello","cortellos rätsel","düstermarschen","musty scroll","durchnässtes pergament","schlingendorntal"},sec={{t="Ein Vers übers Meer",b="Cortellos zweiter Vers schickt Suchende nach Kalimdor. Er beschreibt die Düstermarschen, ein düsteres Feuchtgebiet östlich des Brachlands."},{t="Die Höhle im Südwesten",b="Das Rätsel weist auf einen Hinweis in einer Höhle im Südwesten des Sumpfes hin."},{t="Wohin der Vers führt",b="Der Vers führt zum Blutsumpfbau, einer Höhle im Südwesten der Düstermarschen. Eine musty scroll wartet dort."}},faq={{q="Wohin schickt dieses Rätsel Reisende?",a="Der Vers schickt Suchende nach Kalimdor, in die Düstermarschen östlich des Brachlands.",al={"wohin bei cortellos rätsel","cortello teil zwei fundort","wo ist der zweite rätselhinweis"}},{q="Wo in den Düstermarschen ist der Hinweis versteckt?",a="Der Hinweis liegt in einer Höhle im Südwesten der Düstermarschen.",al={"wo ist die höhle in den düstermarschen","düstermarschen rätselhöhle","blutsumpfbau rätsel"}},{q="Welcher Gegenstand leitet diesen Schritt der Spurensuche ein?",a="Dieser Schritt beginnt mit einem durchnässten Pergament, das am Ende der Spur des ersten Rätsels in den Sümpfen des Elends gefunden wurde.",al={"wie beginnt diese quest","was startet cortellos rätsel zwei"}}},fp="17,149,31.125.0,20.68.0,21.104.1,38.79.0,45.57.0,43.106.0"}
P.entries["quest:626"] = {n="Cortellos Rätsel",s="Im Hinterland locken die letzten Verse von Cortellos Rätsel Schatzsucher an die Küste. Eine modrige Schriftrolle weist von den südlichen Tropen nach Norden, und die Spur endet unter den Wasserfällen.",h="Im Hinterland locken die letzten Verse von Cortellos Rätsel Schatzsucher an die Küste.",kw={"cortello","cortellos rätsel","hinterland","lordaeron","modrige schriftrolle","overlook cliffs","schatz","wasserfall"},sec={{t="Der letzte Hinweis",b="Der verwitterte Vers lenkt die Suche nach Norden, fort von den südlichen Tropen und hin nach Lordaeron. Dort, inmitten der großen Unruhen der umkämpften Lande, findet die lange Jagd an der Küste ihr Ende."},{t="Unter dem Wasserfall",b="Der letzte Hort liegt an der Küste des Hinterlands. Sucht unter Wasser am Fuße der großen Wasserfälle."}},faq={{q="Wohin führt dieses Rätsel?",a="Der Vers führt an die Küste des Hinterlands in Lordaeron. Sucht unter Wasser am Fuße des großen Wasserfalls, der von den Klippen herabstürzt.",al={"wo endet cortellos rätsel","wohin für cortellos rätsel teil drei","cortello hinterland fundort"}},{q="Was leitet diesen Teil der Suche ein?",a="Eine modrige Schriftrolle, die bei der früheren Suche nach Cortellos Schatz gefunden wurde, enthält das letzte Rätsel.",al={"wie beginnt cortellos rätsel teil drei","wo ist die schriftrolle zu finden"}},{q="Wer hat diese Verse geschrieben?",a="Cortello hinterließ die Rätsel und verborgenen Schriftrollen, die Suchende zu seinem Schatz führen.",al={"wer ist cortello","wer hat cortellos rätsel verfasst"}}},fp="17,191,14.198.0,19.99.0,28.139.0,36.94.0,23.81.0"}
P.entries["quest:6261"] = {n="Dungar Trinkfest",s="Am Horst im Handelsdistrikt von Sturmwind organisiert Dungar Trinkfest schnelle Greifenflüge mit Vorräten für Westfalls Verteidiger.",h="Am Horst im Handelsdistrikt von Sturmwind organisiert Dungar Trinkfest schnelle Greifenflüge mit Vorräten für...",kw={"dungar trinkfest","greifenmeister","osric strang","osrics kiste","späherkuppe","sturmwind","thor","der handelsdistrikt","westfall"},ang={["faction:Alliance"]="Die Verbindung zwischen Sturmwind und den umliegenden Siedlungen durch Greifen hilft, die Ordnung zu wahren, während die Hauptarmee des Königreichs fern ist.",["race:Dwarf"]="Als Zwerg bringt Ihr eine uralte Verbundenheit mit Greifen in das Menschenkönigreich mit, wo Betreuer wie Dungar Trinkfest und Thor sie führen.",["race:Human"]="Als Mensch verlasst Ihr Euch auf einzelne Händler und örtliche Greifenbetreuer, um die Grenzaußenposten mit Waffen zu versorgen, während das House of Nobles Westfall vernachlässigt."},sec={{t="Eine lebenswichtige Versorgungslinie",b="Gesetzlose der Defias und wilde Erntegolems haben Westfall an den Rand des Zusammenbruchs gebracht. Rüstmeister Lewis und die Volksmiliz brauchen dringend Vorräte. Lewis schickte Nachricht an die Hauptstadt, und der Rüstungsschmied Osric Strang packte die angeforderte Ausrüstung zusammen. Militärische Fracht zu Fuß durch das von Banditen heimgesuchte Elwynn und Westfall zu tragen, kostet wertvolle Zeit. Sturmwinds neue Flugrouten bieten eine lebenswichtige Verbindung zu den Grenzgebieten."},{t="Der Meister des Horstes",b="Im Handelsdistrikt von Sturmwind koordiniert Dungar Trinkfest vom Greifenhorst aus Kurier- und Passagierflüge. Wildhammerzwerge ziehen diese großen Tiere seit Langem auf und betreuen sie. Greifen befördern Menschen und Fracht durch die Länder der Menschen, wenn die Horste an beiden Enden die Route kennen. Osrics schwere Kiste direkt zu Dungar zu bringen, zeigt, wie der Lufttransport funktioniert. Er verbindet die Vorratslager der Hauptstadt mit Grenzaußenposten wie der Späherkuppe."}},faq={{q="Wer ist Dungar Trinkfest?",a="Dungar Trinkfest betreut Sturmwinds Greifen vom Horst im Handelsdistrikt aus. Er beaufsichtigt Kuriergreifen und Passagierflüge durch die Gebiete der Allianz im südlichen Lordaeron und in Azeroth.",al={"dungar","wer ist dungar","greifenmeister von sturmwind"}},{q="Warum schickt Osric diese Kiste mit einem Greifen?",a="Rüstmeister Lewis und der Volksmiliz in Westfall fehlt es im Kampf gegen die Banditen verzweifelt an Ausrüstung. Schwere Vorräte zu Fuß oder per Wagen zu transportieren, dauert Tage und birgt die Gefahr von Hinterhalten. Ein abgerichteter Greif kann Osrics Kiste in wenigen Minuten über Grenzen hinweg tragen.",al={"warum einen greifen nutzen","warum nicht zu fuß","osrics kiste liefern"}},{q="Wer ist Thor, und warum muss ich zuerst mit ihm sprechen?",a="Thor ist der Greifenmeister auf der Späherkuppe in Westfall. Greifen folgen bekannten Routen zwischen bestimmten Orten, daher können Dungars Reittiere Euch erst zurückfliegen, nachdem Ihr Euch bei Thor gemeldet und den Weg vom anderen Ende aus erkundet habt.",al={"wer ist thor","warum thor besuchen","thor greif"}},{q="Was geschieht, nachdem Dungar die Kiste angenommen hat?",a="Nachdem er die Kiste geprüft hat, macht Dungar einen Greifen bereit und weist Euch an, sie direkt zu Rüstmeister Lewis auf der Späherkuppe zu bringen.",al={"was kommt als nächstes","return to lewis","nächste quest"}},{q="Wo gehört diese Quest in die Flugquestreihe?",a="Dies ist der dritte Schritt einer Einführung in das Flugnetz. Sie beginnt in Westfall mit „A Swift Message“ und führt Euch dann mit „Continue to Sturmwind“ nach Sturmwind. Darauf folgt Dungars Teil, und die Reihe endet mit „Return to Lewis“.",al={"questreihe","flugquestreihe","wie viele quests"}},{q="Warum verlässt sich Sturmwind auf die Greifen der Zwerge?",a="Seit der Zweite Krieg die Allianz von Lordaeron mit dem Wildhammerklan aus dem Hinterland vereinte, sind Greifen die wichtigsten Kundschafter und Transporttiere der Allianzreiche. Sie ermöglichen schnelle Reisen an zerstörten Straßen und feindlichen Blockaden vorbei.",al={"warum greifen in sturmwind","hintergrund der greifen der allianz"}}},fx={["915b1473"]={q="Warum möchte Osric Strang, dass dies getan wird?",a="Osric hat die von Rüstmeister Lewis angeforderte Ausrüstung zusammengestellt und muss sie dringend nach Westfall liefern lassen. Die dort stationierten Soldaten sind schwer bedrängt und können es sich nicht leisten, ohne frische Vorräte und angemessene Ausrüstung auszukommen. Indem er Euch zu Dungar Longdrink schickt und die Greifenflüge nutzt, stellt Osric sicher, dass diese lebenswichtigen Proviantpakete so schnell wie möglich ankommen.",al={"osric strang beweggrund","warum kiste schicken","warum möchte osric dies"}}},fp="16,135,20.403.0,23.437.0,24.199.0,44.244.0,47.227.0,44.130.0,48.232.0,44.235.0"}
P.entries["quest:627"] = {n="Gefallen für Krazek",s="In Beutebucht unterbricht Krazek seine Arbeit an einem kaputten Schmortopf, um Euch um vier Ladungen Geringen Blutsteinerzes aus den nördlichen Hügeln zu bitten. Er gibt Euch das Kochgeschirr zurück, wenn Ihr sie bringt.",h="In Beutebucht unterbricht Krazek seine Arbeit an einem kaputten Schmortopf, um Euch um vier Ladungen Geringen...",kw={"arathihochland","blutstein","beutebucht","schlucht der trockenstoppel","gefallen für krazek","krazek","geringes blutsteinerz","schlingendorntal"},ang={["profession:Mining"]="Als Bergarbeiter könnt Ihr das Erz selbst fördern. Krazek warnt, dass Ihr jemanden braucht, der die Adern abbauen kann, falls Euch die Fertigkeit fehlt."},sec={{t="Ein Handel im Norden",b="Krazek unterbricht die Reparatur des kaputten Kochgeschirrs in Beutebucht, um einen Handel anzubieten. Er schickt Euch weit nach Norden ins Arathihochland. Dort birgt eine Höhle in der Schlucht der Trockenstoppel Geringes Blutsteinerz. Das Mineral ist minderwertig, doch wer seine Verwendung kennt, schätzt es."},{t="Erz aus der Schlucht",b="Krazek arbeitet weiter am Topf, während Ihr nach Norden reist. Er erwartet vier Ladungen Blutstein und verspricht eine Bezahlung, wenn Ihr genug zurückbringt. Das Erz muss abgebaut werden. Fehlt Euch die Fertigkeit, braucht Ihr jemanden, der es fördern kann."}},faq={{q="Wer ist Krazek und was will er?",a="Krazek ist ein Goblin in Beutebucht. Während er einen kaputten Schmortopf repariert, bittet er Euch, vier Ladungen seltenen Blutsteinerzes aus dem Norden mitzubringen.",al={"wer ist krazek","krazeks bitte"}},{q="Wo befindet sich das Blutsteinerz?",a="Geringes Blutsteinerz liegt in einer Berghöhle in der Schlucht der Trockenstoppel, weit im Norden im Arathihochland.",al={"wo ist blutsteinerz","blutstein fundort","schlucht der trockenstoppel lage"}},{q="Warum will Krazek minderwertiges Erz?",a="Der Blutstein aus der Höhle ist minderwertig, doch laut Krazek hat er für jene Wert, die das Handwerk und Wissen zu seiner Nutzung besitzen.",al={"warum geringes blutsteinerz","blutstein wert"}},{q="Was geschieht vor dieser Aufgabe?",a="Bevor Krazek seine Forderung stellt, bringt Ihr das beschädigte Gefäß in Krazek's Cookery nach Beutebucht.",al={"vorherige quest","was kam davor"}},{q="Was geschieht nach dem Sammeln des Blutsteins?",a="Nachdem Krazek die vier Ladungen Erz erhalten und Euch bezahlt hat, geht es mit Return to Corporal Kaleb weiter.",al={"nächste quest","what comes next"}}},fp="16,183,18.253.0,18.221.0,36.142.0,36.101.0,35.114.0,30.96.0,44.101.0"}
P.entries["quest:628"] = {n="Exzelsior",s="In Beutebucht ist Drizzlik bereit für das letzte Stück der Excelsior-Stiefel. Er braucht die Haut eines alten Salzwasserkrokilisken für ihre Außenschicht.",h="In Beutebucht ist Drizzlik bereit für das letzte Stück der Excelsior-Stiefel.",kw={"beutebucht","krokilisk","drizzlik","alter krokilisk","excelsior","salzwasserkrokilisk","schlingendorntal"},sec={{t="Die äußere Schicht",b="Drizzlik hat die Innenschicht der Stiefel fertiggestellt. Für die Außenseite verwendet er die feinsten Häute alter Krokilisken. Sie sind zäher und bieten eine bessere Oberfläche für die Verzierungen und Akzente der Excelsior-Linie. Nur die Haut eines alten Salzwasserkrokilisken passt zu seinem Plan.\n\nEinen solchen zu finden ist schwierig. Alte Krokilisken zeigen sich nur, um andere Salzwasserkrokilisken zu beschützen. Drizzlik hat außerdem gelesen, dass die Bestände der Salzwasserkrokilisken schwinden, was ihm Sorgen um sein Geschäft bereitet."},{t="Drizzliks Dank",b="Drizzlik kann die Bestellung ausführen und sie vorzeitig mit dem nächsten Schiff nach Undermine an Direktor Riddlevox schicken. Er hat zusätzliche Exemplare angefertigt und gibt Euch für Eure Mühen ein Paar. Kein Stiefel, betont er, ist so edel wie die der Excelsior-Linie."}},faq={{q="Wer ist Drizzlik?",a="Drizzlik fertigt in Beutebucht die Stiefel der Excelsior-Linie.",al={"drizzlik","stiefelmacher beutebucht","drizzlik npc"}},{q="Warum braucht Drizzlik die Haut eines alten Salzwasserkrokilisken?",a="Drizzlik sagt, die Häute alter Krokilisken seien zäher und böten eine bessere Oberfläche für die Verzierungen und Akzente der Excelsior-Linie. Nur die Haut eines alten Salzwasserkrokilisken passt zu seinem Plan.",al={"warum krokiliskenhaut","excelsior stiefelmaterialien","verwendung alter krokiliskenhaut"}},{q="Warum sind alte Salzwasserkrokilisken schwer zu finden?",a="Alte Salzwasserkrokilisken zeigen sich nur, um andere Salzwasserkrokilisken zu verteidigen, sagt Drizzlik.",al={"wo sind alte krokilisken","alten salzwasserkrokilisken finden","wie alten krokilisken beschwören"}},{q="Was kam vor dieser Bitte?",a="Some Assembly Required kam zuerst.",al={"vorherige quest","excelsior voraussetzung","some assembly required verknüpfung"}},{q="Welche Sorge hat Drizzlik wegen der Salzwasserkrokilisken?",a="Drizzlik hat gelesen, dass die Bestände der Salzwasserkrokilisken schwinden, was ihm Sorgen um sein Geschäft bereitet.",al={"sterben krokilisken aus","salzwasserkrokiliskenbestand","aussterben der krokilisken"}}},fp="9,140,15.430.0,17.222.1,16.56.0,57.152.0,48.93.0,30.34.0,59.93.0"}
P.entries["quest:6281"] = {n="Weiter nach Sturmwind",s="Ihr bringt eine Anforderung per Greif von der Späherkuppe nach Sturmwind, wo Osric Strang Euch in der Altstadt erwartet.",h="Ihr bringt eine Anforderung per Greif von der Späherkuppe nach Sturmwind, wo Osric Strang Euch in der...",kw={"flugroute","greif","lewis' notiz","limited immunity","die altstadt","osric strang","späherkuppe","thor"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Euch auf Greifenmeister verlassen, die verstreute Außenposten verbinden und abgelegene Garnisonen mit der Hauptstadt in Verbindung halten.",["race:Human"]="Als Mensch könnt Ihr in der Altstadt sehen, wie fern sich einfache Bürger und abgeschiedene Grenzlandbewohner der Politik des erhabenen House of Nobles fühlen."},sec={{t="Auf Schwingen",b="Rüstmeister Lewis bereitet auf der Späherkuppe ein Anforderungsschreiben vor. Thor, der örtliche Greifenmeister, bietet Euch den schnellsten Weg aus den umkämpften Ebenen. Für eine geringe Gebühr fliegt Ihr auf einem der ausgebildeten Greifen des Königreichs über staubiges Ackerland und die Flussgrenze des Waldes von Elwynn. Dann trägt Euch der Greif über die hohen weißen Stadtmauern von Sturmwind."},{t="Nachschubwege der Altstadt",b="Ihr landet an den Handelslandeplätzen der Hauptstadt und begebt Euch dann in die Altstadt. Dort findet Ihr Osric Strang in seinem Geschäft Limited Immunity. Osric versorgt das Grenzland, doch sein finsterer Empfang zeigt die wachsende Kluft zwischen Westfalls bedrängter Volksmiliz und den abgelenkten Herrschern in Burg Sturmwind."}},faq={{q="Welchen Zweck hat diese Quest?",a="Ihr bringt die Anforderung von Rüstmeister Lewis per Greif von der Späherkuppe nach Sturmwind. Unterwegs lernt Ihr die Route zwischen dem Außenposten und der Hauptstadt kennen.",al={"warum diese quest machen","zweck der quest","weiter nach sturmwind questziel"}},{q="Wo befindet sich Osric Strang?",a="Osric Strang betreibt Limited Immunity in der Altstadt von Sturmwind.",al={"wo ist osric strang","osric strang finden","limited immunity standort"}},{q="Warum braucht die Späherkuppe Vorräte aus Sturmwind?",a="Die Volksmiliz auf der Späherkuppe kämpft gegen die Bruderschaft der Defias und erhält kaum offizielle militärische Unterstützung aus der Hauptstadt. Rüstmeister Lewis muss Ausrüstung direkt bei zivilen Händlern kaufen.",al={"warum vorräte benötigt werden","westfall nachschubproblem","späherkuppe ausrüstung"}},{q="Wer ist Thor?",a="Thor ist der Greifenmeister auf der Späherkuppe. Er verwaltet Flugrouten, die Westfall mit Sturmwind und anderen verbündeten Knotenpunkten verbinden.",al={"wer ist thor","westfall greifenmeister","thor westfall"}},{q="Was steht in Lewis' Notiz?",a="Lewis' Notiz ist eine dringende Anforderung von Rüstmeister Lewis, die benötigte Ausrüstung und Vorräte zur Versorgung der Garnison auf der Späherkuppe aufführt.",al={"lewis' notiz","was steht in der notiz","inhalt der notiz"}},{q="Was geschieht nach der Übergabe der Notiz?",a="Nachdem Osric die Anforderung erhalten hat, schickt er Euch zu Dungar Longdrink, dem Greifenmeister von Sturmwind. Ihr organisiert den Rücktransport der bestellten Vorräte nach Westfall.",al={"was kommt als nächstes","folgequest","nach osric strang"}}},fx={["9888c0f8"]={q="Warum möchte Thor, dass dies getan wird?",a="Thor ist der Greifenmeister von Westfall, und seine Aufgabe ist es, die Kommunikation und den Transport zwischen der Grenze und der Hauptstadt aufrechtzuerhalten. Rüstmeister Lewis muss dringend Vorräte an die Späherkuppe liefern, aber Greifen fliegen nicht von selbst, ohne dass jemand die Zügel hält und die Anforderung in Osric Strangs Hände liefert. Indem er Euch an Bord eines seiner Reittiere schickt, stellt Thor sicher, dass der Hilferuf der Späherkuppe tatsächlich Sturmwind erreicht.",al={"warum schickt mich thor","thor beweggrund continue to stormwind","warum hilft greifenmeister thor"}},a35c3ce1={q="Warum braucht Thor mich, anstatt selbst nach Sturmwind zu fliegen?",a="Thor kann seinen Posten in der Späherkuppe nicht einfach verlassen. Als einziger Greifenmeister der Siedlung muss er vor Ort bleiben, um sich um den Horst zu kümmern, die Fluglinien zu verwalten und Westfall mit dem weiteren Königreich verbunden zu halten. Ein fähiger Kurier wie Ihr, der bereit ist, die Reisegebühr zu übernehmen und Lewis' Anforderung direkt an Osric Strang in der Altstadt zu überbringen, lässt die Späherkuppe ihre Nachricht nach Sturmwind bringen, ohne den Außenposten seines Betreuers zu berauben.",al={"warum ich continue to stormwind","warum kann thor die nachricht nicht liefern","warum braucht thor einen abenteurer"}}},fp="21,106,11.352.0,21.306.0,34.161.0,30.70.0,52.206.0,12.125.0,27.149.0,39.176.0"}
P.entries["quest:6282"] = {n="Harpyien drohen",s="Im Verbrannten Tal bedrohen Bloodfury-Harpyien die Straßen westlich von Sonnenfels. Maggran Erdbinder ruft Krieger der Horde auf, ihre wachsenden Reihen zu lichten und die Reisewege durch das Steinkrallengebirge offenzuhalten.",h="Im Verbrannten Tal bedrohen Bloodfury-Harpyien die Straßen westlich von Sonnenfels.",kw={"hinterkaltläufer","bloodfury","das verbrannte tal","zirkel","harpyien drohen","maggran erdbinder","schurkenfedern","schlächter","steinkrallengebirge","sonnenfels"},ang={["class:Druid"]="Als Druide seht Ihr, wie die verderbte Präsenz des Bloodfury-Zirkels das empfindliche, von Bränden verwüstete Ökosystem des Verbrannten Tals schändet.",["class:Shaman"]="Als Schamane folgt Ihr Maggran Erdbinders Ruf, aggressive Schänder zu vertreiben, die das natürliche Gleichgewicht der Elemente stören.",["faction:Horde"]="Als Mitglied der Horde stärkt Ihr durch die Säuberung des Himmels über dem Verbrannten Tal Euren Stützpunkt in Sonnenfels gegen die gefährlichen wilden Fraktionen des Steinkrallengebirges.",["race:Tauren"]="Als Tauren ist es für Euch ehrenvoll, die vordringenden Bloodfuries zu dezimieren und so Euer angestammtes Versprechen zu erfüllen, Kalimdors Wildnis zu beschützen."},sec={{t="Beschützer des Landes",b="Tauren in Sonnenfels beschützen das Steinkrallengebirge und seine friedlichen Reisenden. Maggran Erdbinder, das betagte Oberhaupt des Rückzugsortes, hat beobachtet, wie die Reihen der Harpyien wachsen. Der Bloodfury-Zirkel hat sich im versengten Verbrannten Tal ausgebreitet, bedrängt Tiere und versperrt Wege. Wenn die Schwärme weiter anwachsen, könnte Sonnenfels abgeschnitten werden."},{t="Säuberung des Verbrannten Tals",b="Westlich von Sonnenfels liegt das Verbrannte Tal, ein Ödland aus Asche, verbrannter Erde und schwelenden Bäumen, das verheerende Brände hinterlassen haben. Bloodfury-Harpyien nisten hoch in den verkohlten Überresten uralter Wälder, und das Tal ist ihre Hochburg. Maggran schickt Krieger der Horde in die feindselige Caldera, um Dutzende Harpyien zu töten: Bloodfury-Hinterkaltläufer, -Schlächter und -Schurkenfedern. Ihre Reihen zu lichten schwächt den Griff des Zirkels auf das Tal und ebnet den Weg, sich seiner matriarchalen Blutlinie zu stellen."}},faq={{q="Wer vergibt die Quest Harpyien drohen?",a="Maggran Erdbinder erteilt den Auftrag in Sonnenfels im Steinkrallengebirge, nahe dem zentralen Teich der Siedlung.",al={"questgeber harpyien drohen","wo harpyien drohen annehmen","maggran erdbinder quest"}},{q="Wo befinden sich die Bloodfury-Harpyien?",a="Bloodfury-Harpyien leben überall im Verbrannten Tal, westlich von Sonnenfels. Ein Bergpfad hinter dem Rückzugsort führt hinab ins Tal.",al={"wo sind bloodfury-harpyien","bloodfury-harpyien fundort","verbranntes tal harpyien"}},{q="Warum wollen die Tauren die Harpyien dezimieren?",a="Die Tauren sehen sich als Hüter des natürlichen Gleichgewichts im Steinkrallengebirge. Maggran Erdbinder fürchtet, dass sich die Bloodfuries aggressiv über Kalimdor ausbreiten, Unschuldige angreifen und Kreaturen daran hindern, sich frei zu bewegen.",al={"warum harpyien töten","tauren harpyien konflikt","warum hasst maggran harpyien"}},{q="Was folgt nach dem Abschluss von Harpyien drohen?",a="Nach dieser Aufgabe schickt Maggran Erdbinder Euch aus, um die herrschende Führung des Bloodfury-Zirkels auszuschalten.",al={"nächste quest harpyien drohen","harpyien drohen folgequest","was nach harpyien drohen"}},{q="Ist diese Quest nur für die Horde?",a="Ja. Nur Mitglieder der Horde können diesen Auftrag in Sonnenfels erhalten.",al={"kann allianz harpyien drohen machen","harpyien drohen nur horde","allianz harpyien drohen"}},{q="Welche Arten von Harpyien müssen getötet werden?",a="Ihr müsst im gesamten Verbrannten Tal sieben Bloodfury-Harpyien, sieben Bloodfury-Hinterkaltläufer, sieben Bloodfury-Schlächter und sieben Bloodfury-Schurkenfedern töten.",al={"welche harpyien töten","harpyienarten verbranntes tal","harpyien drohen questziele"}}},fx={["34ac97e1"]={q="Wer sind die Blutfurien-Harpyien und warum stellen sie eine Bedrohung dar?",a="Die Blutfurien sind ein bösartiger Zirkel von Harpyien, die das verbrannte Tal befallen haben. Laut Maggran Erdbinder sind sie die treibende Kraft hinter den ansteigenden Harpyienpopulationen in ganz Kalimdor. Ihre aggressive Expansion greift auf die umliegende Wildnis über und schließt unschuldige Reisende und Wildtiere in ihrem Territorium ein.",al={"blutfurien-harpyien","wer sind die blutfurien","warum blutfurien-harpyien töten"}}},fp="16,193,22.322.0,25.479.0,37.124.0,40.139.0,42.225.0,45.102.0,25.66.0,36.153.0"}
P.entries["quest:6283"] = {n="Blutfuriengeschlecht",s="Maggran Erdbinder schickt Euch ins Verbrannte Tal, um den Einfluss der Harpyien zu brechen und einen Beweis zurückzubringen.",h="Maggran Erdbinder schickt Euch ins Verbrannte Tal, um den Einfluss der Harpyien zu brechen und einen Beweis...",kw={"blutfuriengeschlecht","bloodfury ripper","das verbrannte tal","harpyien","maggran erdbinder","steinkrallengebirge","sonnenfels"},ang={["faction:Horde"]="Die Sicherung des Umlands von Sonnenfels schützt den einzigen Zufluchtsort der Horde tief im umkämpften Steinkrallengebirge.",["race:Tauren"]="Das vernarbte Land des Steinkrallengebirges schmerzt die Tauren. Ist die gewalttätige Harpyienkönigin erst beseitigt, können Älteste wie Maggran ihre Gedanken wieder auf Harmonie und Heilung richten."},sec={{t="Schlag gegen die Matriarchin",b="Harpyien vom Rand des Verbrannten Tals bedrohen Sonnenfels. Maggran Erdbinder glaubt, dass ihre Angriffe erst enden werden, wenn Bloodfury Ripper, ihre Matriarchin, tot ist. Der Schwarm behandelt sie wie eine Königin. Unter ihrer Führung handeln sie wie aus einem Guss und werden entlang des zerklüfteten westlichen Bergrückens immer kühner."},{t="Frieden in der Erde",b="Maggran bittet Euch, Bloodfury Rippers Überreste als Beweis zurückzubringen. Ohne ihre Brutkönigin verlieren die Harpyien ihre Ordnung und lassen sich leichter in Schach halten. Sonnenfels ist weniger bedroht, und Maggran kann seinen Zorn und seine ständige Wachsamkeit ablegen. Dann kann er wieder nach der Harmonie und dem Gleichgewicht streben, die den Tauren viel bedeuten."}},faq={{q="Wer vergibt die Quest Blutfuriengeschlecht?",a="Maggran Erdbinder vergibt sie. Er führt Sonnenfels an und ist dort nahe dem Wasserbecken zu finden.",al={"questgeber blutfuriengeschlecht","wer startet blutfuriengeschlecht","maggran erdbinder quest"}},{q="Welche Voraussetzung muss erfüllt sein, bevor diese Jagd verfügbar wird?",a="Zuerst müsst Ihr Harpies Threaten abschließen. Maggran schickt Euch ins Verbrannte Tal, um die Reihen der Bloodfury-Harpyien zu lichten.",al={"blutfuriengeschlecht vorquest","voraussetzung für blutfuriengeschlecht","harpies threaten folgequest"}},{q="Wo befindet sich Bloodfury Ripper?",a="Bloodfury Ripper streift durch die felsigen Hügel am nordwestlichen Rand des Verbrannten Tals. Ihre blaue Färbung hebt sie vom Schwarm ab.",al={"wo ist bloodfury ripper","bloodfury ripper finden","bloodfury ripper erscheinungsort"}},{q="Warum will Maggran Bloodfury Ripper tot sehen?",a="Maggran sieht in Bloodfury Ripper die Königin, die das ungestüme Vordringen der Harpyien in das Gebiet lenkt. Er glaubt, dass ihr Tod ihre Führung zerschlagen und ihren Einfluss auf das Tal schwächen wird.",al={"warum bloodfury ripper töten","harpyienanführerin verbranntes tal hintergrund","maggran erdbinder beweggrund"}},{q="Wie wirkt sich Bloodfury Rippers Tod auf die Tauren von Sonnenfels aus?",a="Bloodfury Rippers Tod schenkt Maggran innere Ruhe. Befreit von Zorn und der Furcht vor einem Angriff kann er sich darauf konzentrieren, das Land zu heilen.",al={"steinkrallengebirge harpyienbedrohung hintergrund","was passiert wenn bloodfury ripper stirbt","maggrans reaktion"}},{q="Was ist der schnellste Weg von Sonnenfels ins Verbrannte Tal?",a="Ein Bergpfad führt hinter Sonnenfels direkt hinunter ins Verbrannte Tal. Er umgeht die gewundenen Hauptstraßen des Steinkrallengebirges.",al={"wie von sonnenfels ins verbrannte tal gelangen","sonnenfels hinterer weg","verbranntes tal abkürzung"}}},fx={["174da5a4"]={q="Wozu dienen die Überreste der Blutfurienzerfetzerin?",a="Maggran Erdbinder verlangt die physischen Überreste der Blutfurienzerfetzerin rein als Beweis für Eure Tat. Da die Harpyienkönigin den Blutfurien-Schwarm aus den Tiefen des verbrannten Tals befehligt, benötigt Maggran einen handfesten Beweis dafür, dass sie tatsächlich gefallen ist, bevor er beruhigt wissen kann, dass die Bedrohung für Sonnenfels beendet ist.",al={"zweck der überreste der blutfurienzerfetzerin","warum harpyienüberreste aufbewahren","verwendung der blutfurienüberreste"}},["0ac0712d"]={q="Wer ist die Blutfurienzerfetzerin?",a="Die Blutfurienzerfetzerin ist die Anführerin und Matriarchin der Blutfurien-Harpyien, die in den westlichen Hügeln des verbrannten Tals nisten. Von ihrem Schwarm wie eine Königin behandelt, lenkt sie die bösartigen Kreaturen, die das Steinkrallengebirge bedrohen, und stellt sicher, dass deren Aggression trotz der Bemühungen der Horde, ihre Zahl zu dezimieren, bestehen bleibt.",al={"wer ist die blutfurien-anführerin","geschichte der blutfurienzerfetzerin","blutfurienkönigin"}}},fp="19,102,19.288.0,18.324.0,40.96.0,60.122.0,34.134.0,44.189.0,72.130.1,74.133.0"}
P.entries["quest:6284"] = {n="Arachnophobie",s="Ein Kopfgeld der Horde führt Euch westlich der Scherwindklippe zu Besseleth, der uralten Spinne, die das südliche Steinkrallengebirge heimsucht. Bringt ihren Fangzahn zu Maggran Erdbinder in Sonnenfels, und die Gebirgsstraßen könnten nach Einbruch der Dunkelheit für Reisende sicherer werden.",h="Ein Kopfgeld der Horde führt Euch westlich der Scherwindklippe zu Besseleth, der uralten Spinne, die das...",kw={"arachnophobia","besseleth","kopfgeld","maggran erdbinder","sishircanyon","spinne","steinkrallengebirge","sonnenfels","weberpass"},ang={["class:Hunter"]="Als Jäger stellt die Verfolgung einer gewaltigen Spinne durch die schattigen Felsen des Sishircanyons Eure Fähigkeiten beim Anschleichen im Gebirge auf die Probe.",["faction:Horde"]="Als Reisender der Horde helft Ihr durch Besseleths Beseitigung, die Reise nach Sonnenfels zu sichern und Euren Stützpunkt in den Felsen des zentralen Steinkrallengebirges zu schützen.",["race:Tauren"]="Als Taure könnt Ihr Maggran Erdbinder, der die schmerzhafte Narbe von Besseleths Gift trägt, bei seiner Jagd helfen."},sec={{t="Die Warnung am Straßenrand",b="Ein verwitterter Steckbrief warnt Reisende auf der Hauptstraße südlich der Scherwindklippe vor den Landstrichen westlich der Straße. Im Sishircanyon und am Weberpass wimmelt es von Spinnen. Besseleth, eine ungewöhnlich große orangefarbene Spinne, befehligt ihre Brut. Nach Sonnenuntergang überfällt sie jeden, der vom Pfad abkommt."},{t="Die Klage des Erdbinders",b="Maggran Erdbinder, ein Taure in Sonnenfels, hat das Kopfgeld auf Besseleth ausgesetzt. Bei einer früheren Begegnung traf ihn ihr gewaltiger, zwei Fuß langer Fangzahn und tötete ihn beinahe. Maggran wehrte sie ab und humpelte in Sicherheit, doch die Wunde erinnert ihn noch immer an die Gefahr in den Schatten der Schlucht. Er hofft, dass Ihr ihm Besseleths Fangzahn bringt und die Pässe sichert, damit Handel und Reisen nach Sonnenfels ohne Furcht weitergehen können."}},faq={{q="Wo beginnt die Quest Arachnophobia?",a="Untersucht den Steckbrief auf der Westseite der Hauptstraße im Steinkrallengebirge, direkt südlich des Eingangs zur Scherwindklippe.",al={"wo arachnophobia annehmen","besseleth steckbrief fundort","wie arachnophobia beginnen"}},{q="Wo ist Besseleth zu finden?",a="Besseleth haust im Sishircanyon, westlich des Steckbriefs am Straßenrand. Sie durchstreift den von Netzen überwucherten Boden der Schlucht inmitten ihrer Spinnenbrut.",al={"besseleth fundort","wo ist besseleth","spinne besseleth finden"}},{q="Wer ist Maggran Erdbinder?",a="Maggran Erdbinder ist ein Taure in Sonnenfels im Steinkrallengebirge. Er überlebte einen giftigen Angriff von Besseleth und setzte das Kopfgeld aus, um die Schlucht von ihrer Bedrohung zu befreien.",al={"wer ist maggran","maggran erdbinder rolle","wer hat arachnophobia abgegeben"}},{q="Warum ist Besseleth eine solche Bedrohung für die Region?",a="Besseleth ist eine außergewöhnlich große, erbarmungslose Spinne, die im Sishircanyon und am nahe gelegenen Weberpass auf Beute lauert. Nachts machen sie und ihre Brut Jagd auf Reisende, die nach Sonnenfels unterwegs sind.",al={"warum besseleth töten","was hat besseleth getan"}},{q="Welcher Beweis ist nötig, um das Kopfgeld zu erhalten?",a="Tötet Besseleth und nehmt einen ihrer gewaltigen, zwei Fuß langen Fangzähne an Euch. Bringt Besseleths Fangzahn zu Maggran Erdbinder in Sonnenfels, um das Kopfgeld zu erhalten.",al={"besseleth beweis","besseleth questgegenstand","was lässt besseleth fallen"}},{q="Ist diese Quest für die Allianz verfügbar?",a="Nein. Arachnophobia ist für die Horde bestimmt, da Maggran Erdbinder im Hordelager Sonnenfels das Kopfgeld aussetzt.",al={"kann die allianz arachnophobia machen","allianz arachnophobia quest"}}},fx={["28337efe"]={q="Warum ist ein Kopfgeld auf Besseleth ausgesetzt?",a="Besseleth und ihre Brut haben den Sishircanyon überrannt und jagen unschuldige Reisende, die sich nachts auf die nahe gelegenen Pfade wagen. Maggran Erdbinder selbst wurde von ihren Fängen angegriffen und verwundet und entkam nur knapp mit dem Leben. Er hat das Kopfgeld ausgesetzt, um die Bedrohung zu beseitigen, damit Reisende Sonnenfels sicher erreichen können.",al={"warum besseleth töten","warum will maggran, dass besseleth tot ist","motiv für das kopfgeld auf besseleth"}},["4849c04d"]={q="Wofür wird Besseleths Fangzahn verwendet?",a="Der Fangzahn dient als unbestreitbarer physischer Beweis für das Ableben der riesigen Spinne. Maggran Erdbinder verlangt von Euch, dass Ihr diese giftige Trophäe zurückbringt, bevor er Euch die Kopfgeldprämie gewährt und Euch zum Champion des Waldes erklärt.",al={"zweck von besseleths fangzahn","warum besseleths fangzahn sammeln","wozu dient der fangzahn"}},["9c85495e"]={q="Warum braucht Maggran Erdbinder einen Abenteurer, um Besseleth zu jagen?",a="Maggran hat bereits versucht, sich der großen Spinne selbst zu stellen, und wurde fast getötet, wobei er eine bleibende Wunde von ihrem giftigen Biss erlitt. Während er seine Verletzungen in Sonnenfels ausheilt, setzte er entlang der Straße ein offenes Kopfgeld aus, in der Hoffnung, dass ein fähiger Jäger dort Erfolg haben könnte, wo er gescheitert ist.",al={"warum tötet maggran besseleth nicht selbst","warum ich arachnophobia","warum einen abenteurer anheuern"}}},fp="13,242,20.292.0,27.420.0,41.130.0,29.138.0,27.176.0,45.183.0,43.146.0,40.124.0"}
P.entries["quest:6285"] = {n="Zurück zu Lewis",s="Eine Kiste mit Rüstungen ist für die Volksmiliz auf der Späherkuppe bestimmt, und Dungar Longdrink schickt sie per Greif aus Sturmwind. Der Flug führt über Elwynn und Westfall zu den bedrängten Verteidigern.",h="Eine Kiste mit Rüstungen ist für die Volksmiliz auf der Späherkuppe bestimmt, und Dungar Longdrink schickt...",kw={"dungar longdrink","flugroute","greif","osric","osrics kiste","volksmiliz","rüstmeister lewis","späherkuppe","thor","westfall"},ang={["class:Warrior"]="Als Krieger wisst Ihr, dass jede zur Späherkuppe geflogene Kiste mit Brustpanzern und Beinschienen einem weiteren Milizkämpfer eine Chance gibt, den Hieben der Defiasbanditen standzuhalten.",["faction:Alliance"]="Greifenrouten zwischen Sturmwind und abgelegenen Siedlungen wie der Späherkuppe helfen, ein zunehmend gespaltenes Königreich zusammenzuhalten.",["race:Dwarf"]="Als Zwerg kennt Ihr Greifen als die angestammten Reittiere Eures Volkes. Die Flugrouten des Königreichs führen sie von Dungar Longdrinks Horst in der Hauptstadt zu Thor in Westfall."},sec={{t="Eine Lebensader durch die Lüfte",b="Osric, ein Rüstungsschmied aus Sturmwinds Altstadt, hat eine schwere Kiste mit Rüstungen für die Freiwilligen der Volksmiliz auf der Späherkuppe gepackt. Defiasbanditen, hungrige Gnolle und mechanische Erntemaschinen bedrohen Westfall. Ein einzelner Wagen ist auf diesen Straßen ein leichtes Ziel, also bietet das Netz der Flugmeister den Rüstungen einen sichereren Weg zu den Verteidigern."},{t="Die Wege der Greifen",b="Greifen sind treu und gut ausgebildet, doch sie müssen ein Ziel kennen, bevor sie einen Reiter dorthin tragen. Dungar Longdrink erklärt, dass sie instinktiv zu ihrem Horst in der Hauptstadt Sturmwind zurückkehren. Für einen entlegenen Außenposten müsst Ihr zunächst dessen Flugmeister persönlich aufsuchen. Ihr habt Euch bereits bei Thor auf der Späherkuppe gemeldet und Euch damit den Himmel über dem Grenzland für schnelle Reisen erschlossen."},{t="Nachschub für die Miliz",b="Auf der Späherkuppe nimmt Rüstmeister Lewis die Kiste entgegen und beginnt, die Rüstungen unter den Verteidigern des Grenzlands zu verteilen. Er rüstet Gryan Starkmantels Freiwilligentruppe aus. Jede Lieferung hilft der Miliz, ihre Stellung gegen die Bruderschaft der Defias zu halten."}},faq={{q="Was enthält Osrics Kiste?",a="Osrics Kiste enthält frisch gefertigte Rüstungen, die der Sturmwinder Rüstungsschmied Osric zusammengestellt hat. Die Volksmiliz auf der Späherkuppe braucht sie dringend. Die Freiwilligen erhalten keinen regulären königlichen Nachschub und sind für ihre Ausrüstung auf Spenden und private Lieferungen angewiesen.",al={"osrics kiste inhalt","was ist in der kiste","was wird geliefert"}},{q="Wer ist Rüstmeister Lewis?",a="Rüstmeister Lewis ist der Versorgungsoffizier der Volksmiliz und neben dem Turm auf der Späherkuppe stationiert. Er verwaltet Rationen, Ausrüstung und Waffen für die freiwilligen Verteidiger, die sich in ganz Westfall der Bruderschaft der Defias entgegenstellen.",al={"lewis westfall","rüstmeister lewis aufgabe","wer ist lewis"}},{q="Wer ist Dungar Longdrink?",a="Dungar Longdrink ist Sturmwinds erfahrener menschlicher Greifenmeister am Horst im Handelsdistrikt der Hauptstadt. Er beaufsichtigt die Flugrouten des Königreichs für Kuriere und Reisende.",al={"dungar sturmwind","sturmwind greifenmeister","flugmeister sturmwind"}},{q="Warum fliegen Greifen nur an Orte, die Ihr bereits besucht habt?",a="Dungar sagt, Greifen seien darauf trainiert, auf direktem Weg zur Hauptstadt zurückzufinden. Sie sind auf feste Wegpunkte und persönliche Vertrautheit angewiesen, bevor sie Reiter zu entlegenen Grenzhorsten wie Thors Station auf der Späherkuppe tragen.",al={"greifenflug regel","wie flugrouten funktionieren","warum zuerst thor besuchen"}},{q="Wer ist Thor?",a="Thor ist der Flugmeister auf der Späherkuppe in Westfall. Er versorgt die Greifen des Außenpostens und empfängt Luftkuriere aus Sturmwind.",al={"thor westfall","späherkuppe greifenmeister","flugmeister thor"}},{q="Warum kann Sturmwind nicht einfach königliche Wagen mit Vorräten schicken?",a="Defiasbanditen, Riverpaw-Gnolle und Diebe machen die Straßen zwischen dem Wald von Elwynn und Westfall unsicher. Versorgungstrecks über Land drohen in Hinterhalte zu geraten und ihre Fracht zu verlieren, während die Greifenroute schneller und sicherer ist.",al={"warum greifen nutzen","warum keine lieferung über land","straßen in westfall"}}},fx={["24b76519"]={q="Warum möchte Dungar Longdrink, dass Osrics Kiste ausgeliefert wird?",a="Dungar beaufsichtigt das Greifennetzwerk von Sturmwind, das als lebenswichtige Verbindung zwischen der Hauptstadt und den bedrängten Grenzgebieten dient. Rüstmeister Lewis und die The People's Militia auf der Späherkuppe benötigen dringend Verstärkung und Rüstungen, um Westfall gegen Defias-Schläger und Gnolle zu halten. Dungar stellt sicher, dass kritische militärische Hilfe entlegene Außenposten schnell erreicht, indem er sich darauf verlässt, dass vertrauenswürdige Reisende die Vorräte per Flug befördern.",al={"motiv von dungar","warum osrics kiste schicken","warum dungar lewis hilft"}},["74eea5bf"]={q="Warum muss Dungar Euch die Kiste zustellen lassen, anstatt einen Boten zu schicken?",a="Dungar verwaltet den geschäftigen Flugpunkt der Hauptstadt und kann seinen Posten nicht verlassen, während die offizielle Garnison von Sturmwind nur selten Männer für die vernachlässigte Verteidigung von Westfall erübrigt. Da Lewis ursprünglich Euch geschickt hat, um diesen Versorgungstransport zu koordinieren, habt Ihr bereits das Vertrauen von sowohl Thor als auch der Miliz der Späherkuppe gewonnen. Die Kiste einem willigen Abenteurer anzuvertrauen, der auf dem Rücken eines Greifen zurückkehrt, ist der schnellste Weg, die Rüstung in die Hände zu bekommen, die sie benötigt.",al={"warum keinen boten schicken","warum ich dungar","warum die kiste selbst liefern"}}},fp="15,199,17.333.0,20.372.0,24.248.0,29.251.0,27.212.0,24.176.0,58.226.0,12.142.0,57.195.0"}
P.entries["quest:629"] = {n="Das Finstere Riff",s="Unter der ungezähmten Küste sucht Kin'weelay eine Scherbe aus der versunkenen Trollstadt. Er hofft, Gri'leks Geschichte nach Orgrimmar zu bringen, wo die Dunkelspeere sie bewahren können.",h="Unter der ungezähmten Küste sucht Kin'weelay eine Scherbe aus der versunkenen Trollstadt.",kw={"dunkelspeer","gri'lek","basislager grom'gol","kin'weelay","murloc","die ungezähmte küste","schlingendorntal","tafelscherbe","das finstere riff"},ang={["faction:Horde"]="Indem Ihr Kin'weelay helft, dieses Relikt für Orgrimmar zu bergen, stärkt Ihr das Band des Vertrauens zwischen der Horde und dem Stamm der Dunkelspeere.",["race:Troll"]="Für die Dunkelspeere hält dieses Fragment ihre uralten Traditionen und die Verehrung des großen Helden Gri'lek in ihrer neuen Heimat Orgrimmar lebendig."},sec={{t="Versunkene Legenden",b="Nordwestlich des Basislagers Grom'gol verbirgt die ungezähmte Küste eine uralte Trollstadt unter Wasser. Ein heftiges Erdbeben zerriss vor langer Zeit das Land und ließ die Stadt versinken. Heute werden ihre überfluteten Ruinen das Finstere Riff genannt und beherbergen feindselige Murlocs, die jeden angreifen, der sich in ihre Nähe wagt.\n\nAuf dem Meeresgrund ruht eine gewaltige Steintafel, in die Gri'leks Geschichte eingemeißelt ist. Er war ein legendärer Trollheld, und sein Andenken ist den Dunkelspeeren noch immer heilig."},{t="Ein Andenken für Orgrimmar",b="Das Monument ist zu gewaltig, um es aus der Tiefe zu bergen, also bittet Kin'weelay Euch, eine Scherbe abzubrechen. Er plant, das Fragment nach Orgrimmar zu bringen und es an einem heiligen Ort aufzustellen. Dort können die Dunkelspeere Gri'leks Stärke und Ehre in Erinnerung behalten."}},faq={{q="Wo liegt das Finstere Riff?",a="Das Finstere Riff liegt unter der ungezähmten Küste, nordwestlich des Basislagers Grom'gol im Schlingendorntal.",al={"finsteres riff lage","wo liegt das finstere riff","wie das finstere riff finden"}},{q="Warum will Kin'weelay die Tafelscherbe haben?",a="Die Tafel bewahrt die heilige Geschichte des Trollhelden Gri'lek. Kin'weelay plant, eine Scherbe nach Orgrimmar zu bringen und an einem heiligen Ort aufzustellen, damit die Dunkelspeere sein Andenken in ihrer neuen Heimat bewahren.",al={"warum tafelscherbe holen","tafelscherbe zweck","warum griklek tafel"}},{q="Was geschah mit der uralten Stadt am Finsteren Riff?",a="Vor langer Zeit erschütterte ein gewaltiges Erdbeben die ungezähmte Küste und ließ die gesamte Trollstadt im Meer versinken.",al={"was geschah mit dem finsteren riff","wie versank das finstere riff","versunkene trollstadt geschichte"}},{q="Welche Kreaturen bewohnen heute das Finstere Riff?",a="Feindselige Murlocs bewohnen die überfluteten Ruinen und greifen jeden an, der sich der versunkenen Stadt nähert.",al={"monster im finsteren riff","finsteres riff feinde","wer lebt im finsteren riff"}},{q="Wer ist Gri'lek?",a="Gri'lek ist ein legendärer Trollheld, dessen Geschichte in die Tafel unter der ungezähmten Küste eingemeißelt wurde. Den Dunkelspeeren ist sein Andenken heilig.",al={"wer ist griklek","grilek hintergrundgeschichte","held griklek"}},{q="Warum nur eine Scherbe statt der ganzen Tafel mitnehmen?",a="Das mit Inschriften versehene Monument auf dem Meeresgrund ist zu gewaltig, um es aus den Ruinen zu bergen. Eine einzelne Scherbe lässt sich nach Orgrimmar zurückbringen.",al={"warum nur eine scherbe","kann die ganze tafel mitgenommen werden","ganze tafel mitbringen"}}},fp="13,163,14.433.0,24.252.0,31.99.0,42.204.0,51.106.0,41.93.0,15.134.0,50.127.0"}
P.entries["quest:63"] = {n="Ruf des Wassers",s="Ruf des Wassers führt Schamanen aus dem Brachland über das Meer an ein verseuchtes Ufer im Silberwald. Dort stellt sich ein Initiand der Seuche an einem uralten Schrein, um Gemeinschaft mit den Wassergeistern zu erlangen.",h="Ruf des Wassers führt Schamanen aus dem Brachland über das Meer an ein verseuchtes Ufer im Silberwald.",kw={"brazier of everfount","brine","ruf des wassers","verderbte manifestation","islen wasserdeuter","das grabmal","silberwald","wassertotem"},ang={["class:Shaman"]="Als Schamane lernt Ihr, dass Eure Berufung über Stürme hinausreicht. Ihr könnt verwüstete Lande heilen und spirituelle Verderbnis bannen.",["faction:Horde"]="Als Orc oder Tauren reist Ihr von Kalimdor in den Silberwald und erlebt aus erster Hand die düsteren, seuchengeplagten Nöte Eurer verbündeten Verlassenen."},sec={{t="Eine Pilgerreise übers Meer",b="Ihr sammelt mit der Hilfe des Einsiedlers Brine reines Wasser und kehrt dann zu Islen Wasserdeuter an der Küste des Brachlands zurück. Sie schickt Euch mit der gereinigten Essenz über das Meer an die heimgesuchte Küste des Silberwalds. Der Schrein liegt direkt westlich der Zuflucht der Verlassenen, die das Grabmal genannt wird."},{t="Die Reinigung von Everfount",b="Lordaerons Seuche hat die Wasser des Brazier of Everfount verdorben, eines uralten Fokus der Elemente. Die Geister sind verstummt und wild geworden. Besiegt die verderbte Manifestation, die an die Feuerstelle gebunden ist, und bringt dann ihre Armschienen und das reinste Wasser der Flamme dar. Die Verderbnis schwindet, und ein unbefleckter Geist der Gezeiten erscheint, bereit, seinen Segen zu gewähren."}},faq={{q="Warum muss ein Schamane den weiten Weg bis in den Silberwald auf sich nehmen?",a="Islen Wasserdeuter schickt Euch aus, um Euch der Verderbnis zu stellen, nicht bloß den Frieden zu ergründen. Der Küstenschrein westlich des Grabmals wurde von Lordaerons Seuche verdorben. Seine Heilung könnte die Wassergeister erwecken, die sich weigern, mit irgendjemand anderem zu sprechen.",al={"warum in den silberwald","warum übers meer reisen","warum wasserquest im silberwald"}},{q="Was geschieht, wenn Ihr das Brazier of Everfount benutzt?",a="Legt die Armschienen des besiegten Elementars und das verbliebene reinste Wasser in die Flamme. Islen hat Euch diesen Reinigungsritus gelehrt. Er reinigt das Becken und ruft einen reinen Wassergeist herbei, der bereit ist, seinen Segen zu gewähren.",al={"brazier of everfount ereignis","was bewirkt die feuerstelle","wie das becken reinigen"}},{q="Wer verdirbt den Wasserschrein im Silberwald?",a="Lordaerons noch immer schwelende Seuche hat das Wasser des Schreins verdorben. Verderbnis sickert von den Hügeln herab, verseucht die Quelle und macht die dort heimischen Wassergeister wild und feindselig.",al={"wer hat den schrein verdorben","warum ist die manifestation verderbt","wasserverderbnis im silberwald"}},{q="Was erhaltet Ihr nach Abschluss dieser Prüfung?",a="Die Reinigung des Brazier of Everfount ermöglicht Euch die Gemeinschaft mit einem reinen Wassergeist, der bereit ist, seinen Segen zu gewähren. Bringt Islen Wasserdeuter im Brachland einen Beweis der Reinigung, um Euer Wassertotem zu erhalten und die lange Prüfung abzuschließen.",al={"ruf des wassers belohnung","wassertotem freischalten","was gibt es als belohnung"}},{q="Wo genau liegt der Schrein?",a="Der Schrein steht an der Westküste des Silberwalds, jenseits des verseuchten Bergrückens direkt westlich des Grabmals.",al={"brazier of everfount standort","wo ist der schrein","silberwald schrein koordinaten"}},{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter ist eine Taurenschamanin, die an der Händlerküste des Brachlands südlich von Ratschet lebt. Als verehrte spirituelle Führerin lehrt sie junge Schamanen der Horde die schwierigen Riten, die sie auf das Wasser einstimmen.",al={"wer ist islen","islen wasserdeuter hintergrund","wasserlehrerin im brachland"}}},fx={["43e73964"]={q="Warum möchte Islen Wasserdeuter, dass dies erledigt wird?",a="Islen Wasserdeuter versucht, das Gleichgewicht der Elemente wiederherzustellen und Eure Verbindung zu den Wassergeistern zu erweitern. Der Schrein im Silberwald ist der Seuche erlegen, was die Verbindung zu den Geistern der Region unterbrochen hat. Indem Ihr diesen Ort reinigt, helft Ihr den gepeinigten Elementaren und beweist Euren Wert als Schamane, der in der Lage ist, sich sein Wassertotem zu verdienen.",al={"motiv von islen wasserdeuter","warum den wasserschrein reinigen","warum schickt islen mich in den silberwald"}},["4cf42c2b"]={q="Wozu dienen die Verderbte Manifestationsarmschienen?",a="Die Armschienen dienen als physische Verbindung zu dem gefallenen Elementar. Wenn sie zusammen mit dem reinsten Wasser der Sole auf das Becken der ewigen Quelle gelegt werden, ermöglichen sie es dem Reinigungsritual, zu wirken, die Verderbnis zu beseitigen und einen reinen Wassergeist hervorzulocken, damit Ihr mit ihm kommunizieren könnt.",al={"verwendung der verderbten manifestationsarmschienen","was mit den armschienen tun","becken armschienen"}},["585e30b0"]={q="Was ist die Verderbte Manifestation des Wassers?",a="Es ist ein Elementargeist, der durch die Seuche, die in die Wasserwege des Silberwalds einsickert, verdreht und krank gemacht wurde. Feindselig und in Agonie bewacht er den verseuchten Schrein, unfähig, Frieden zu finden oder mit Schamanen zu kommunizieren, bis seine verderbte physische Form besiegt ist.",al={"verderbte manifestation des wassers","was bekämpfe ich im silberwald","verderbtes wasserelementar"}},["35c6941a"]={q="Warum müsst Ihr diese Reinigung durchführen anstatt jemand anderes?",a="Diese Reise ist eine wesentliche Prüfung Eures schamanischen Pfades. Gewöhnliche Wachen können nicht mit den Elementen kommunizieren oder spirituelle Prüfungen überstehen, und Islen muss bleiben, um andere Initianden zu führen. Ein Schamane muss sich dem Zorn des Elementars stellen und das Gleichgewicht persönlich wiederherstellen, um eine unzerbrechliche Bindung zum Wasser zu schmieden.",al={"warum muss ich den schrein reinigen","warum keine wachen zum silberwald schicken","warum muss der spieler gehen"}}},fp="13,190,27.271.0,23.363.1,66.227.0,51.203.0,49.174.0,48.228.0,36.107.0,23.209.0"}
P.entries["quest:630"] = {n="Flaschenpost",s="Die Flaschenpost führt Euch auf eine Insel vor der Küste des Schlingendorntals, wo Prinzessin Poobah in Ketten wartet. King Mukla befehligt die Bestien der Insel und hält sie gefangen. Um sie zu befreien, braucht Ihr den Schlüssel zu ihrer Fessel.",h="Die Flaschenpost führt Euch auf eine Insel vor der Küste des Schlingendorntals, wo Prinzessin Poobah in...",kw={"jaguero island","king mukla","prinzessin poobah","fesselschlüssel","skymane","schlingendorntal"},sec={{t="Eine Gefangene auf der Insel",b="Auf einer Insel vor der Küste des Schlingendorntals wartet Prinzessin Poobah in Ketten. Die Flaschenpost hat Euch zu ihr geführt. King Mukla ist ein großer Skymane-Gorilla, der die Kreaturen befehligt, die auf der Insel umherstreifen. Er hält Poobah gefangen, und sie vertraut darauf, dass Ihr Euch dem Affen stellt und ihren Fesselschlüssel zurückbringt."},{t="Die Bestie im Südosten",b="Prinzessin Poobah sagt, dass ihr Entführer oft im Südosten der Insel umherstreift. King Mukla ist ein furchterregender Gegner. Ihn zu besiegen ist der einzige Weg, den Fesselschlüssel zu erlangen und Poobah zu befreien."},{t="Befreiung und Dankbarkeit",b="Der Schlüssel befreit Prinzessin Poobah von ihren Ketten und bewahrt sie vor dem, was sie als tiefe Schande empfindet. Sie kann Euch nicht die vollständige Aufnahme in ihren Stamm gewähren. Stattdessen bietet sie Euch ein Zeichen des Dankes für Euren Mut an."}},faq={{q="Wer ist Prinzessin Poobah?",a="Prinzessin Poobah ist eine Stammesangehörige, die auf einer Insel vor der Küste des Schlingendorntals in Ketten gefangen gehalten wird. Sie hat einen Hilferuf in einer Flasche ausgesandt und wartet auf jemanden, der es wagt, ihren Entführer zu bezwingen und ihre Fessel aufzuschließen.",al={"poobah","wer ist poobah","prinzessin poobah hintergrundgeschichte"}},{q="Wer hält Prinzessin Poobah gefangen?",a="King Mukla hält Prinzessin Poobah gefangen. Er ist ein gewaltiger Skymane-Gorilla, der die Bestien um sich herum auf der Insel befehligt.",al={"wer hat poobah gefangen genommen","poobahs entführer","king muklas gefangene"}},{q="Wo ist King Mukla zu finden?",a="Prinzessin Poobah sagt, dass King Mukla oft im Südosten der Insel umherstreift.",al={"wo ist mukla","muklas aufenthaltsort","king mukla finden"}},{q="Was wird benötigt, um Prinzessin Poobah zu befreien?",a="Um Prinzessin Poobah zu befreien, besiegt King Mukla und nehmt den Schlüssel zu ihrer Fessel an Euch. Bringt ihn zurück, um ihre Kette aufzuschließen.",al={"poobahs fesselschlüssel","wie poobah befreien","schlüssel zur befreiung von prinzessin poobah"}},{q="Wo gehört dieser Schritt in die Geschichte?",a="Dieser Schritt folgt auf den Hilferuf aus einer Flasche und führt Euch King Mukla gegenüber. Danach könnt Ihr Prinzessin Poobah von ihren Ketten befreien.",al={"flaschenpost questreihe","flaschenpost teil zwei","poobah questreihe"}}},fp="19,226,21.304.0,26.182.0,25.206.1,23.208.0,34.123.0,26.81.0,39.110.0,38.135.0"}
P.entries["quest:6301"] = {n="Zyklus der Wiedergeburt",s="In Sonnenfels sucht Tammra Windfeld Gaeasamenkörner, um das Steinkrallengebirge zu heilen. Sie bittet die Horde, sie am Mirkfallonsee zu sammeln, damit sie sie segnen und den geschädigten Boden des Gebirges wiederherstellen kann.",h="In Sonnenfels sucht Tammra Windfeld Gaeasamenkörner, um das Steinkrallengebirge zu heilen.",kw={"das verbrannte tal","zyklus der wiedergeburt","erdenmutter","gaeasamenkorn","mirkfallonsee","new life","steinkrallengebirge","sonnenfels","tammra windfeld"},ang={["class:Druid"]="Druiden dürften den Schwerpunkt auf natürliche Kreisläufe und die Aufzucht von Samen wiedererkennen. Kargen Boden wiederherzustellen erinnert an die Fürsorge von Cenarion.",["class:Shaman"]="Tammras Arbeit folgt der Berufung der Schamanen, das ökologische Gleichgewicht wiederherzustellen. Die Geister und die Erdenmutter können erneuern, was industrielle Ausbeutung zerstört.",["race:Tauren"]="Für die Shu'halo ist es eine geistige Pflicht gegenüber der Erdenmutter, den verwundeten Boden des Steinkrallengebirges zu heilen. Damit begegnen sie den Schäden durch rücksichtslosen Holzeinschlag und Kriege zwischen den Fraktionen."},sec={{t="Eine gezeichnete Wildnis",b="Holzeinschlag und Zusammenstöße zwischen rivalisierenden Fraktionen haben die Gipfel des Steinkrallengebirges gezeichnet. Wälder wurden versengt, abgeholzt oder in Asche gelegt. Für die Tauren in Sonnenfels ist der rasche Verfall der Natur eine tiefe Wunde. Schamanen wie Tammra Windfeld wenden sich dem erneuernden Kreislauf der Erdenmutter zu, während sie daran arbeiten, das Land zu heilen."},{t="Die Samen von Mirkfallon",b="Tammra sucht am Mirkfallonsee nördlich von Sonnenfels nach seltenen Gaeasamenkörnern. Robuste Samenkapseln wachsen an den Ufern nahe dem Wasser und bergen eine Widerstandskraft, die es nur im Steinkrallengebirge gibt. Sobald die Körner gesammelt sind, versieht Tammra jedes mit einem überlieferten schamanischen Segen. Der Segen weckt seine Kraft und beschleunigt sein Wachstum."}},faq={{q="Wozu werden Gaeasamenkörner gesammelt?",a="Gaeasamenkörner bergen die Lebenskraft, die Tammra Windfeld braucht, um geschädigtes Land wiederherzustellen. Sie segnet sie mit der Macht der Erdenmutter, damit sie rasch sprießen und die durch Industrie und Krieg verwüsteten Teile des Steinkrallengebirges erneuern können.",al={"warum gaeasamenkörner","wozu dienen gaeasamenkörner","zweck von zyklus der wiedergeburt"}},{q="Wo befinden sich die Gaeasamenkörner?",a="Gaeasamenkörner wachsen am Ufer des Mirkfallonsees, nördlich von Sonnenfels im Steinkrallengebirge. Sucht rund um den See im Erdreich nahe dem Wasser.",al={"fundort gaeasamenkorn","wo gaeasamenkörner finden","mirkfallonsee samen"}},{q="Wer ist Tammra Windfeld?",a="Tammra Windfeld ist eine Taurenschamanin in Sonnenfels. Sie arbeitet daran, das Steinkrallengebirge mit Segnungen der Erdenmutter zu heilen, nachdem Holzeinschlag und kriegerische Konflikte das Land verwüstet haben.",al={"wer ist tammra","tammra windfeld hintergrund"}},{q="Was tut Tammra, sobald die Samen zurückgebracht werden?",a="Wenn Tammra die zehn Gaeasamenkörner erhält, besingt sie sie und erfüllt sie mit schamanischer Energie. Das beschleunigt ihr Wachstum und bereitet sie darauf vor, an verwüsteten Orten eingepflanzt zu werden.",al={"was geschieht mit den samen","zyklus der wiedergeburt abgeben"}},{q="Welche Quest folgt auf Zyklus der Wiedergeburt?",a="Auf Zyklus der Wiedergeburt folgt New Life. Die gesegneten Samen werden ins verwüstete Verbrannte Tal getragen, um dort die Pflanzenwelt wiederherzustellen.",al={"folgequest von zyklus der wiedergeburt","nächste quest nach zyklus der wiedergeburt","was folgt auf zyklus der wiedergeburt"}},{q="Warum muss das Land des Steinkrallengebirges geheilt werden?",a="Krieg und großflächige Kahlschläge durch industrielle Holzunternehmen haben das Steinkrallengebirge geschädigt. In versengten Ödlanden und gezeichneten Tälern kann die Natur nur schwer aus eigener Kraft nachwachsen.",al={"warum ist das steinkrallengebirge verwüstet","was geschah mit dem steinkrallengebirge"}}},fx={a7be4203={q="Warum möchte Tammra Windfeld, dass Gaea-Samen gesammelt werden?",a="Tammra ist zutiefst betrübt über die unerbittliche Zerstörung, die durch industrielle Gier und Kriegführung im gesamten Steinkrallengebirge verursacht wurde. Holzfäller und Schlachten haben die Landschaft vernarbt, und sie glaubt, dass nur die wiederherstellende Kraft der Erdenmutter solche tiefen Wunden heilen kann. Indem sie die Samen sammelt und segnet, hofft sie, den natürlichen Kreislauf der Wiedergeburt zu erneuern und die zerstörte Wildnis wieder aufzufrischen.",al={"motiv von tammra","warum samen für tammra sammeln","grund von tammra windfeld"}}},fp="16,195,20.334.0,23.304.0,45.214.0,33.165.0,24.167.0,48.181.0,36.132.0,49.177.0"}
P.entries["quest:631"] = {n="Der Thandolübergang",s="Am Thandolübergang sucht Rhag Garmason nach einem vermissten Zwergkundschafter, nachdem eine Explosion den nördlichen Übergang zerstört hat. Der Dunkeleisenklan hat Dun Modr angegriffen, die Nachrichtenverbindung unterbrochen und die Verteidiger ohne Verstärkung zurückgelassen. Ol' Rustlocke weiß vielleicht, was die Explosion verursacht hat.",h="Am Thandolübergang sucht Rhag Garmason nach einem vermissten Zwergkundschafter, nachdem eine Explosion den...",kw={"dunkeleisen","dun modr","garmason","langzopf","rustlocke","übergang","thandol","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass der Thandolübergang der einzige Versorgungsweg über Land ist, der Sturmwind und Eisenschmiede mit den Allianzstreitkräften in Arathi und Hillsbrad verbindet.",["race:Dwarf"]="Als Zwerg seht Ihr die Zerstörung des Thandolübergangs vielleicht als Beleidigung zwergischer Steinmetzkunst und als Schlag Eurer verhassten Verwandten vom Dunkeleisenklan gegen Khaz Modan."},sec={{t="Donner über dem Übergang",b="Eine Explosion hat die Brücke zwischen dem Sumpfland und dem Arathihochland zerrissen. Bronzenbartsoldaten an der Grenze wurden von der Zerstörung erfasst, als Dunkeleisenzwerge Dun Modr angriffen. Ihre Reihen sind ausgedünnt, und ihre Festungen werden belagert. Langzopf der Grimmige führt die Überlebenden an, während sie gegen die Angreifer standhalten."},{t="Ein Kundschafter gen Osten",b="Langzopf schickte den erfahrenen Kundschafter Ebenezer Rustlocke aus, um die östliche Brücke zu untersuchen. Er sollte herausfinden, ob noch ein Übergang oder ein Weg nach Norden nutzbar war. Seit Tagen fehlt jede Nachricht von ihm. Dun Modr wird belagert, und Rhag Garmason und die Garnison haben zu wenige Soldaten, um die vom Feind besetzten Trümmer zu durchsuchen."},{t="Ein grausiger Fund",b="Ebenezer Rustlocke liegt tot zwischen den Trümmern der östlichen Brücke. Sein Leichnam und das Pergament in seiner Faust zeigen, dass er auf seinem Erkundungsgang in einem Hinterhalt der Dunkeleisen getötet wurde. Die Dunkeleisen bedrohen weiterhin die Verbindung zwischen Khaz Modan und Lordaeron."}},faq={{q="Was ist der Thandolübergang?",a="Der Thandolübergang überspannt die Schlucht zwischen dem nördlichen Sumpfland und dem Arathihochland. Diese Zwergenbrücke ist der wichtigste Landweg von Khaz Modan in die nördlichen Gebiete Lordaerons.",al={"thandol-übergang","was ist die thandol-brücke","brücke im sumpfland"}},{q="Wer hat den Thandolübergang angegriffen?",a="Der Dunkeleisenklan der Zwerge hat die Brücke und das nahe Dun Modr angegriffen. Mit Sprengstoff zerstörten sie den Übergang, legten den Reiseverkehr der Allianz lahm und überraschten die Bronzenbartverteidiger.",al={"wer hat die brücke gesprengt","explosion am thandol-übergang","wer hat dun modr angegriffen"}},{q="Wer ist Ol' Rustlocke?",a="Ebenezer Rustlocke war ein vertrauenswürdiger Zwergkundschafter im Dienst von Langzopf dem Grimmigen. Langzopf schickte ihn nach der Explosion aus, um die östliche Brücke zu untersuchen, und Streitkräfte der Dunkeleisen töteten ihn während seines Auftrags.",al={"ebenezer rustlocke","wer ist rustlocke","vermisster kundschafter"}},{q="Wo befindet sich Rhag Garmason?",a="Rhag Garmason befindet sich nahe Dun Modr, unmittelbar südlich des Thandolübergangs im nördlichen Sumpfland. Er hilft, die Verteidigung zu koordinieren, während die Garnison von Eisenschmiede abgeschnitten ist.",al={"rhag garmason standort","wo ist rhag","questgeber dun modr"}},{q="Warum hat Eisenschmiede keine Hilfe nach Dun Modr geschickt?",a="Der Angriff kam plötzlich, die Brücke ist zerstört, und Dun Modr wird belagert. Die abgeschnittenen Verteidiger sind zu stark beansprucht, um Boten zu entsenden oder Truppen abzuziehen, und verlassen sich deshalb auf durchreisende Reisende als Nachrichtenüberbringer.",al={"warum keine verstärkung","eisenschmiede hilfe sumpfland","dun modr verstärkung"}},{q="Was geschieht nach dem Fund von Rustlockes Leichnam?",a="Bei Rustlockes Überresten findet sich ein Pergament, das zeigt, dass Kam Tiefenzorn gleich jenseits des Übergangs Sprengstoff versteckt hatte. Das Pergament gibt den Anstoß, das Lager zu zerstören, bevor der Sprengstoff die verbliebene Brücke erreicht, und anschließend im Allianzlager in der Zuflucht Hilfe zu suchen.",al={"nächste quest nach rustlocke","thandol-übergang fortsetzung","nach dem thandolübergang"}}},fx={["60853ee9"]={q="Warum möchte Rhag Garmason, dass Ol' Rustlocke gefunden wird?",a="Eine massive Explosion riss durch den Thandol-Übergang und forderte viele Zwergenverteidiger noch vor dem Angriff der Dunkeleisenzwerge. In dem Chaos entsandte Longbraid Ol' Rustlocke, um die östliche Brücke auszukundschaften und zu sehen, ob die Position gehalten oder gesichert werden konnte, aber es sind Tage vergangen, ohne ein einziges Wort. Rhag Garmason und die Überlebenden müssen unbedingt das Schicksal von Rustlocke erfahren und ob die Brücke noch ihrer Verteidigung dienen kann.",al={"warum rustlocke finden","motiv von rhag garmason","warum nach rustlocke suchen"}},["8b9f1c8c"]={q="Warum braucht Rhag Garmason die Hilfe eines Abenteurers?",a="Dun Modr wird aktiv von Dunkeleisenzwergen belagert, und die überlebende Garnison ist bis über ihre Grenzen hinaus beansprucht. Da keine Verstärkung aus Eisenschmiede eintrifft und die Verluste stündlich zunehmen, können Rhag Garmason und seine Kameraden keine einzige Wache von ihren Verteidigungslinien entbehren, um einen Suchtrupp über die Brücke zu schicken.",al={"warum ich rhag garmason","warum können die zwerge rustlocke nicht finden","warum dun modr helfen"}}},fp="16,263,21.335.0,17.301.0,14.234.1,25.176.0,30.181.0,21.196.1,31.162.0,43.204.0,46.254.1"}
P.entries["quest:632"] = {n="Der Thandolübergang",s="Am Thandol-Übergang wartet Rhag Garmason auf Nachricht von einem vermissten Späher. Er schickte Abenteurer los, um nach Ol' Ebenezer Rustlocke zu sehen, nachdem der Zwerg vom gewaltigen Steinübergang keine Meldungen mehr gesandt hatte. Die Suche unter seinen Bögen könnte eine Bedrohung für die nördlichen Nachschublinien aufdecken.",h="Am Thandol-Übergang wartet Rhag Garmason auf Nachricht von einem vermissten Späher.",kw={"arathi","dunkeleisen","tiefenzorn","ebenezer rustlocke","rhag garmason","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass der Thandol-Übergang Eisenschmiede und Sturmwind mit den nördlichen Festungen der Allianz verbindet. Der Fund von Rustlocke ist für die Sicherheit des Kontinents von Bedeutung.",["race:Dwarf"]="Als Zwerg erfahrt Ihr, dass die Streitkräfte der Dunkeleisenzwerge weit nördlich der Sengenden Schlucht vorgedrungen sind. Ihr Eindringen bedroht Eure Verwandten in Eisenschmiede."},sec={{t="Rustlockes Wacht",b="Langzopf der Grimmige schickte Ebenezer Rustlocke los, um über den Bauzustand und die Sicherheit des Thandol-Übergangs zu wachen. Als die Meldungen des Spähers ausblieben, befürchtete man ein Verbrechen."},{t="Tiefenzorns Befehle",b="Unter den Bögen des Übergangs findet Ihr Rustlocke tot auf. Dunkeleisen-Invasoren überfielen ihn aus den Schatten heraus. Nahe Rustlockes verkrampften Fingern liegen schriftliche Befehle, die den Namen Tiefenzorn tragen. Das Pergament deutet auf gezielte Operationen der Dunkeleisenzwerge hin, die den Übergang destabilisieren sollen, und nicht auf einen zufälligen Raubüberfall oder ein vereinzeltes Grenzscharmützel. Als Ihr Garmason die Beweise bringt, geht die Garnison von einer Routinesuche zur dringenden Verteidigung im Krieg über."}},faq={{q="Wer war Ebenezer Rustlocke?",a="Ebenezer 'Ol' Rustlocke war ein Zwerg der Allianz, der ausgesandt wurde, um den Thandol-Übergang auszukundschaften und dort Wache zu halten. Dunkeleisenzwerge überraschten ihn und töteten ihn unter der Brücke.",al={"wer ist rustlocke","ol rustlocke","ebenezer rustlocke"}},{q="Wer hat Rustlocke getötet?",a="Dunkeleisen-Agenten überfielen Rustlocke unter dem Thandol-Übergang auf Befehl von Kam Tiefenzorn.",al={"wer hat rustlocke getötet","wer hat rustlocke überfallen","rustlockes leiche"}},{q="Was findet man bei Rustlockes Leiche?",a="Ein Pergament mit Tiefenzorns Befehlen liegt neben Rustlockes geballter Faust. Es hält geheime Pläne der Dunkeleisenzwerge gegen die nördliche Brücke fest.",al={"was war in seiner hand","tiefenzorns befehle","pergament bei rustlocke"}},{q="Wer ist Rhag Garmason?",a="Rhag Garmason ist ein Offizier der Allianz, der südlich des Thandol-Übergangs im Sumpfland stationiert ist. Er sichert den Verkehr zwischen den Zwergengebieten und dem Norden.",al={"rhag garmason","wer ist garmason"}},{q="Warum ist der Thandol-Übergang so stark umkämpft?",a="Der Thandolübergang ist die einzige Landbrücke, die Khaz Modan und das Sumpfland mit dem Arathihochland und Lordaeron verbindet. Die Allianz braucht ihn für ihre Nachschublinien.",al={"warum ist der thandol-übergang wichtig","bedeutung des thandol-übergangs"}},{q="Was geschieht, nachdem Ihr Rhag Garmason die Befehle übergeben habt?",a="Nachdem Ihr Rhag Garmason die Befehle übergeben habt, schickt er Euch los, um gleich jenseits des Übergangs im Arathihochland ein Sprengstofflager der Dunkeleisenzwerge zu zerstören und ihre Sabotage zu vereiteln.",al={"was geschieht als nächstes","folgeauftrag am thandol-übergang"}}},fx={d453191c={q="Warum müsst Ihr die Befehle von Rustlockes Leiche zurückbringen?",a="Ebenezer Rustlocke kann nicht mehr sprechen oder Warnungen überbringen, aber das Pergament, das neben seiner geballten Faust liegt, enthüllt, dass die Dunkeleisenzwerge einen aktiven Komplott gegen den Thandol-Übergang gestartet haben. Wenn Rhag Garmason nicht von dem Hinterhalt erfährt und die schriftlichen Befehle von Tiefenzorn inspiziert, werden die Allianz-Streitkräfte, die die Brücke bewachen, blind für die Sabotage bleiben, die sich direkt unter ihren Füßen entfaltet.",al={"warum rustlockes leiche melden","warum tiefenzorns befehle nehmen","motiv von rustlockes leiche"}}},fp="16,267,17.155.0,17.446.1,27.172.1,21.96.1,34.142.1,21.155.0,45.165.0,54.168.1"}
P.entries["quest:6321"] = {n="Nachschub für Brill",s="Am Grabmal sucht Todeswache Podrig Waffen für eine Garnison, die von den Kämpfen zermürbt ist. Er schickt eine Anforderung nach Unterstadt, während Bestien, die Geißel und andere Bedrohungen ihre Vorräte aufzehren.",h="Am Grabmal sucht Todeswache Podrig Waffen für eine Garnison, die von den Kämpfen zermürbt ist.",kw={"fledermausführer","todeswache","gordon wendheim","hadrec","karos razok","podrig","anforderung","das grabmal","silberwald","unterstadt"},ang={["faction:Horde"]="Als Mitglied der Horde nutzt Ihr Flugrouten zwischen Garnisonen und Hauptstädten, um die Verteidigung in umkämpften Regionen zu koordinieren.",["race:Undead"]="Als Untoter helft Ihr, Außenposten der Verlassenen wie das Grabmal zu unterhalten. Sie erweitern den Einfluss der Verlassenen über Tirisfal hinaus und sichern die umliegende Wildnis für die Dark Lady."},sec={{t="Waffen für die Front",b="Todeswache Podrig sagt, das Grabmal habe ordentliche Vorräte, doch die Kämpfe im Silberwald zehren sie stetig auf. Wilde Bestien, Überreste der Geißel und andere örtliche Bedrohungen beschädigen Waffen und Rüstungen oder lassen sie nach Scharmützeln zurück. Auf Befehl von Executor Hadrec verfasst Podrig eine Anforderung an Gordon Wendheim, einen Waffenhändler in Unterstadt. Ersatzwaffen und Rüstungen helfen den Verlassenen, ihre gefährdeten Stützpunkte jenseits von Tirisfal zu halten."},{t="Das Flugnetz",b="Auf den Straßen des Silberwalds lassen sich wichtige Nachrichten und Vorräte nur langsam und unter großen Gefahren befördern. Deshalb verschicken die Verlassenen sie mit abgerichteten Vampirfledermäusen. Am Grabmal betreut Karos Razok die Fledermäuse und verbindet die dortigen Soldaten mit dem Flugnetz von Unterstadt. Diese Routen verbinden entlegene Garnisonen mit Sylvanas' Hauptstadt."}},faq={{q="Welchen Zweck hat Podrigs Anforderungsliste?",a="Executor Hadrec befahl Todeswache Podrig, Waffen für das Grabmal anzufordern. Allgemeine Vorräte waren ausreichend vorhanden, doch Waffen mussten jene ersetzen, die im Kampf gegen die Geißel und andere Bedrohungen des Waldes zerbrachen oder verloren gingen.",al={"warum podrigs anforderungsliste","was ist podrigs anforderung","zweck von nachschub für brill"}},{q="Wer ist Gordon Wendheim?",a="Gordon Wendheim ist ein Waffenhändler in Unterstadt. Podrig richtet die Anforderung neuer Waffen für das Grabmal an ihn.",al={"wer ist gordon wendheim","gordon wendheim unterstadt"}},{q="Wer ist Karos Razok?",a="Karos Razok betreut die Fledermäuse am Grabmal. Er beaufsichtigt die Schreckensfledermäuse, die Boten, Späher und Vorräte durch Lordaeron befördern.",al={"karos razoks aufgabe","wer ist der fledermausführer"}},{q="Warum Fledermäuse statt Straßenkuriere einsetzen?",a="Die Straßen des Silberwalds sind gefährlich, denn feindselige Bestien, die Geißel und andere Fraktionen bedrohen Kuriere. Fledermausrouten bieten eine schnellere und sicherere Verbindung nach Unterstadt.",al={"warum nach unterstadt fliegen","warum fledermäuse nutzen"}},{q="Welche Bedrohungen gibt es für das Grabmal?",a="Das Grabmal wird von verbliebenen Untoten der Geißel, Worgen, wilden Bestien und menschlichen Fraktionen der Region bedroht. Die Garnison braucht stetig Ersatzausrüstung, um kampfbereit zu bleiben.",al={"bedrohungen für das grabmal","warum brauchen todeswachen waffen"}},{q="Wohin führt diese Aufgabe als Nächstes?",a="Karos Razok kann einen Flug nach Unterstadt organisieren, wo die Anforderung an Gordon Wendheim gerichtet ist.",al={"welche quest folgt","was folgt nach nachschub für brill"}}},fx={f1c1132b={q="Warum muss Todeswache Podrig diesen Versorgungsbefehl ausgeliefert haben?",a="Todeswache Podrig führte auf Befehl von Exekutor Hadrec eine Bestandsaufnahme durch, um sicherzustellen, dass das Grabmal weiterhin vollständig bewaffnet bleibt. Während die allgemeinen Vorräte stabil sind, haben laufende Scharmützel im Silberwald gegen die Geißel und andere umherstreifende Bedrohungen die Wachen viele ihrer Waffen im Feld gekostet. Um zu verhindern, dass der Außenposten wehrlos wird, muss Podrig diese Anforderung dringend an Gordon Wendheim in der Unterstadt senden, damit Ersatzwaffen beschafft werden können.",al={"warum will podrig das erledigt haben","motiv von podrig","warum waffen bestellen"}},ade30847={q="Warum schickt Podrig Euch, anstatt die Lieferung selbst zu übernehmen?",a="Podrig ist im aktiven Wachdienst und erhält zusammen mit Exekutor Hadrec die Verteidigung des Grabmals aufrecht. Da feindselige Geißel in den umliegenden Wäldern umherstreifen, wird jede Todeswache benötigt, um den Perimeter zu sichern und das Lager zu halten. Ein rüstiger Reisender bietet sich als idealer Bote an, um mit dem Fledermausmeister in Kontakt zu treten, ohne einen Soldaten von seinem Posten abzuziehen.",al={"warum schickt er mich","warum geht podrig nicht selbst","warum auf einen abenteurer verlassen"}}},fp="23,178,21.436.0,18.305.0,38.219.0,22.115.0,19.134.0,38.175.0,37.161.0,31.112.0"}
P.entries["quest:6322"] = {n="Michael Garrett",s="In Unterstadt wartet Michael Garrett auf eine Kiste für das Grabmal. Gordon Wendheim packt im Handwerksviertel Feldvorräte, und Ihr bringt sie zu Garrett, damit die Fledermäuse der Verlassenen sie in Richtung Silberwald tragen.",h="In Unterstadt wartet Michael Garrett auf eine Kiste für das Grabmal.",kw={"fledermausführer","flugmeister","gordon wendheim","gordons kiste","michael garrett","das grabmal","silberwald","unterstadt"},ang={["faction:Horde"]="Für Reisende aus Kalimdor ist das Fledermausnetz der Verlassenen der schnellste Weg durch den Norden der Östlichen Königreiche.",["race:Undead"]="Die von Führern wie Michael Garrett betriebene Versorgung aus der Luft hilft, Sylvanas' Präsenz jenseits von Tirisfal aufrechtzuerhalten."},sec={{t="Versorgung der Außenposten",b="Die Verlassenen schicken Vorräte aus Unterstadt zu Außenposten wie dem Grabmal im Silberwald. Im Handwerksviertel packt Gordon Wendheim Feldvorräte in eine Kiste. Der Landweg durch verseuchte Wälder ist langsam, und Überreste der Geißel oder wilde Bestien könnten die Fracht überfallen."},{t="Schwingen der Verlassenen",b="Die Verlassenen umgehen gefährliche Straßen mit gefangenen Vampirfledermäusen, die von kundigen Führern gezüchtet und versorgt werden. Michael Garrett betreut die Fledermäuse von seinem Horst im Handwerksviertel von Unterstadt aus. Wenn Ihr ihm die Fracht bringt, kann er sie für den Flug über die Hügel in Richtung Silberwald auf eine Fledermaus schnallen. Die Fledermäuse verbinden die Hauptstadt mit ihren Außenposten."}},faq={{q="Wer ist Michael Garrett?",a="Michael Garrett betreut Fledermäuse im Handwerksviertel von Unterstadt. Er organisiert Reisen und Luftlieferungen zwischen der Hauptstadt der Verlassenen und verbündeten Flugmeistern in ganz Lordaeron.",al={"michael garrett","fledermausführer unterstadt","wer ist garrett"}},{q="Was ist in Gordons Kiste?",a="Gordon Wendheims Kiste enthält Feldvorräte für die Streitkräfte der Verlassenen, die am Grabmal im Silberwald stationiert sind.",al={"gordons kiste","welche vorräte","kiste grabmal"}},{q="Warum Fledermäuse statt Karren oder Pferde?",a="Die Straßen sind gefährlich, und abgerichtete Riesenfledermäuse fliegen viel schneller und umgehen dabei Hinterhalte am Boden.",al={"warum fledermausflug","warum fledermäuse nutzen","vorräte per lufttransport"}},{q="Wohin geht die Lieferung nach Michael Garrett?",a="Nachdem Michael Garrett Gordons Kiste erhalten hat, wird die Fracht für den Flug zum Fledermausführer am Grabmal im Silberwald vorbereitet.",al={"nächster schritt","nach michael garrett","wohin fliegen fledermäuse"}},{q="Wo ist Michael Garrett in Unterstadt zu finden?",a="Michael Garrett ist im südwestlichen Teil des Handwerksviertels zu finden, wo die Fledermäuse vom Grabmal landen.",al={"wo ist garrett","fledermausführer finden","standort flugmeister unterstadt"}},{q="Müsst Ihr zuvor schon am Grabmal gewesen sein?",a="Um die Lieferung auf einer Fledermaus zu begleiten, müsst Ihr mit dem Flugmeister am Grabmal gesprochen haben, um die Route freizuschalten. Andernfalls reist Ihr zu Fuß dorthin.",al={"flugroute zum grabmal erforderlich","sofort fliegen möglich"}}},fx={["2851daa3"]={q="Warum möchte Gordon Wendheim, dass dies erledigt wird?",a="Gordon Wendheim ist damit beauftragt, lebenswichtige logistische Nachschubgüter zu koordinieren, die für Das Grabmal bestimmt sind, den Außenposten der Verlassenen im Silberwald. Da er an seinem Handelsposten in der Unterstadt bleiben muss, um die Waren zu verwalten, benötigt er Euch, damit Ihr die gepackte Kiste an Michael Garrett übergebt, sodass sie schnell über deren Luftkurierroute verschickt werden kann.",al={"warum gordons kiste versenden","gordon wendheim motiv","warum kiste zu michael garrett bringen"}}},fp="15,221,22.281.0,21.321.0,23.175.0,26.112.0,40.103.0,49.146.0,48.120.0,60.155.0"}
P.entries["quest:6323"] = {n="Flug nach Unterstadt",s="Vom Grabmal bringt ein Kurier Podrigs Waffenanforderung nach Unterstadt. Eine Fledermaus der Furcht trägt die Nachricht über den Silberwald zur Hauptstadt der Verlassenen.",h="Vom Grabmal bringt ein Kurier Podrigs Waffenanforderung nach Unterstadt.",kw={"fledermaus der furcht","flugmeister","gordon wendheim","karos razok","podrigs anforderungsliste","flug nach unterstadt","das grabmal","handwerksviertel"},ang={["faction:Horde"]="Als Mitglied der Horde reist Ihr mithilfe ihrer Flugmeister schnell durch die Wildnis. Sie verbinden die Gebiete der Horde.",["profession:Blacksmithing"]="Als Schmied könnt Ihr sehen, wie Gordon Wendheim dabei hilft, Lordaerons Waffen scharf und kriegsbereit zu halten.",["race:Undead"]="Als Untoter könnt Ihr sehen, wie das Netz der Dunklen Fürstin den Silberwald mit der Hauptstadt verbindet. Es hält abgelegene Garnisonen mit der Industrie von Unterstadt in Verbindung."},sec={{t="Schwingen über dem Silberwald",b="Karos Razok betreut die Fledermäuse der Furcht beim Grabmal im Silberwald. Die Fledermäuse befördern Boten und Nachschub zwischen der Hauptstadt der Verlassenen und ihren Außenposten an der Front. Auf den Straßen darunter drohen Gefahren durch feindselige Bestien, Mondwutworgen und Überreste der Geißel. So bieten die Fledermäuse militärischen Anforderungen einen schnellen Weg in die Hauptstadt."},{t="Waffen für die Front",b="Im Handwerksviertel von Unterstadt überbringt der Kurier Podrigs Ausrüstungsanforderung an Gordon Wendheim. Der Waffenschmied bereitet Waffen für die Sache der Dunklen Fürstin vor. Er versorgt Außenposten wie das Grabmal mit kampfbereiten Waffen. Diese Außenposten verteidigen die junge Nation der Verlassenen gegen die Feinde, die sie umgeben."}},faq={{q="Welchen Zweck hat dieser Flug nach Unterstadt?",a="Der Flug bringt die Waffenanforderung von Todeswache Podrig vom Grabmal zu Gordon Wendheim im Handwerksviertel von Unterstadt. Er zeigt neuen Helden auch, wie sie das Flugnetz der Verlassenen nutzen.",al={"warum nach unterstadt fliegen","flug nach unterstadt ziel","podrigs anforderungsliste verwendung"}},{q="Wer ist Karos Razok?",a="Karos Razok betreut die Fledermäuse der Furcht beim Grabmal im Silberwald. Die Fledermäuse befördern Boten und Nachschub der Verlassenen nach Unterstadt und von dort zurück.",al={"karos razok aufgabe","wer ist der fledermausmeister beim grabmal"}},{q="Wer ist Gordon Wendheim?",a="Gordon Wendheim ist ein Waffenschmied der Verlassenen im Handwerksviertel von Unterstadt, nahe der Landeplattform des Fledermausführers. Er hält Waffen für Lady Sylvanas' Fronttruppen sauber, scharf und einsatzbereit.",al={"gordon wendheim","wo ist gordon wendheim"}},{q="Warum nutzen die Verlassenen Fledermäuse als Transportmittel?",a="Die Verlassenen nutzen Fledermäuse der Furcht, um gefährliches Gelände schnell zu überfliegen. Sie durchqueren Lordaerons verseuchten Himmel über Bedrohungen wie wilden Worgen, feindseligen rot hides und der Geißel.",al={"warum fledermäuse","flugreittiere der verlassenen"}},{q="Was geschieht nach der Lieferung?",a="Nachdem Gordon Wendheim die Anforderung erhalten hat, schickt er Kuriere zu Michael Garrett, dem Fledermausführer von Unterstadt. Sie richten eine Rückflugverbindung zum Grabmal ein.",al={"what comes next","folgequest zu flug nach unterstadt"}},{q="Wo landet die Fledermaus der Furcht in Unterstadt?",a="Die Fledermaus der Furcht landet auf dem erhöhten Fledermaushorst im Zentrum des Handwerksviertels von Unterstadt, nahe den Handwerkern und Versorgungshändlern der Stadt.",al={"fledermauslandeplatz unterstadt","wo landet die fledermaus"}}},fx={d629dc0f={q="Warum will Karos Razok, dass dies erledigt wird?",a="Als der Flugmeister, der im Grabmal stationiert ist, überwacht Karos Razok das Luftkuriernetzwerk, das den Silberwald mit der Hauptstadt verbindet. Außenposten wie Das Grabmal sind vollständig auf stetige Nachschubwege und schnelle Korrespondenz angewiesen, um gegen die umliegenden Bedrohungen zu überleben. Indem Ihr die Ausrüstungsanforderung von Todeswache Podrig direkt zu den Waffenlieferanten in der Unterstadt bringt, stellt Ihr sicher, dass die Wachen an der Front, die das Reich verteidigen, die dringend benötigten Waffen und Rüstungen erhalten.",al={"warum podrigs bestellung schicken","karos razok motiv","warum ritt zur unterstadt"}}},fp="21,158,21.325.0,16.313.0,52.193.0,19.148.0,22.194.0,41.178.0,43.156.0,47.139.0"}
P.entries["quest:6324"] = {n="Rückkehr zu Podrig",s="In Unterstadt tragt Ihr Waffen für das Grabmal, nachdem Ihr eine Depesche in die Hauptstadt gebracht habt. Fledermäuse der Verlassenen tragen Euch durch Lordaeron zu Todeswache Podrig.",h="In Unterstadt tragt Ihr Waffen für das Grabmal, nachdem Ihr eine Depesche in die Hauptstadt gebracht habt.",kw={"fledermausmeister","gordons kiste","karos razok","michael garrett","podrig","das grabmal","silberwald","unterstadt"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Versorgungswege aufrechtzuerhalten, die Unterstadt mit abgelegenen Außenposten auf dem gesamten nördlichen Kontinent verbinden.",["race:Undead"]="Als Untoter helft Ihr, die vorgeschobenen Garnisonen mit Waffen zu versorgen, um Lordaeron zu verteidigen und das junge Reich von Königin Sylvanas zu sichern."},sec={{t="Die Versorgungslinie von Unterstadt",b="Todeswache Podrigs Garnison im Grabmal braucht Waffen aus Unterstadt. Ihre Schildwachen im Silberwald stehen Worgen, Überresten aus Dalaran und Nachzüglern der Geißel gegenüber. Neue Waffen helfen den Verlassenen, die Region zu halten und den Außenposten einsatzbereit zu halten."},{t="Schwingen der Verlassenen",b="Fledermausmeister Michael Garrett betreut den zentralen Horst im Handwerksviertel von Unterstadt. Die Fledermäuse der Verlassenen kennen den Rückweg in die Hauptstadt, doch vor einem Flug zu einem entfernten Außenposten sprecht Ihr mit örtlichen Führern wie Karos Razok. Indem Ihr Gordons Kiste durch Lordaeron tragt, verbindet Ihr Unterstadts Versorgung mit seinen verstreuten Festungen."}},faq={{q="Was ist in Gordons Kiste?",a="Gordons Kiste enthält neue Waffen, die in Unterstadt für die Todeswachen im Grabmal gefertigt wurden. Sie stehen Bedrohungen in der Nähe gegenüber.",al={"inhalt von gordons kiste","was wird an podrig geliefert"}},{q="Wer ist Todeswache Podrig?",a="Todeswache Podrig ist ein Soldat der Verlassenen, der im Grabmal im Silberwald stationiert ist. Er beaufsichtigt die Versorgung und Verteidigung der Garnison.",al={"podrig","wer ist podrig"}},{q="Wer ist Michael Garrett?",a="Michael Garrett ist der Fledermausmeister der Verlassenen im Handwerksviertel von Unterstadt. Er koordiniert die Flugrouten durch Lordaeron.",al={"michael garrett","fledermausmeister in unterstadt"}},{q="Warum müsst Ihr mit einem Fledermausmeister sprechen, bevor Ihr irgendwohin fliegt?",a="Die Fledermäuse der Verlassenen kennen den Rückweg zum zentralen Horst in Unterstadt. Für einen Hinflug legt Ihr zuerst mit einem örtlichen Führer eine Route fest, damit die Fledermaus ihr Ziel sicher erreicht.",al={"regeln für flugrouten","wie funktionieren fledermausführer"}},{q="Warum ist die Versorgung des Grabmals so wichtig?",a="Das Grabmal ist der wichtigste vorgeschobene Stützpunkt der Verlassenen im Silberwald. Es sichert ihre Präsenz gegen Worgenrudel, Bedrohungen durch Moonrage und Streitkräfte aus Dalaran in der Gegend.",al={"warum ist das grabmal wichtig","bedeutung des grabmals"}},{q="Wer ist Karos Razok?",a="Karos Razok ist der Fledermausmeister im Grabmal im Silberwald. Er betreut die dort untergebrachten Fledermäuse, die den Außenposten mit Unterstadt verbinden.",al={"karos razok","fledermausmeister im grabmal"}}},fx={["02244cab"]={q="Warum möchte Michael Garrett, dass dies erledigt wird?",a="Als Fledermausmeister der Unterstadt überwacht Michael Garrett den Luftverkehr und die Kurierrouten durch die Gebiete der Verlassene. Todeswache Podrig und die Soldaten, die das Grabmal im Silberwald halten, benötigen dringend frische Rüstungen aus der Hauptstadt. Garrett stellt sicher, dass diese lebenswichtigen Waffen effizient über das Fledermausnetzwerk versandt werden, um die Vorposten der Dunklen Fürstin gegen nahe Bedrohungen zu stärken.",al={"warum michael garrett kiste","garrett motiv return to podrig","warum kiste an das grabmal senden"}},eed737b1={q="Warum schickt Michael Garrett Euch, anstatt selbst zu gehen?",a="Garrett muss am Fledermaushorst der Unterstadt stationiert bleiben, um sich um die Bestien zu kümmern und die Flüge in die Hauptstadt und aus ihr heraus zu koordinieren. Da Ihr ein fähiger Kurier seid, der ohnehin in Richtung Silberwald unterwegs ist, stellt das Anvertrauen der Kiste sicher, dass die Lieferung erfolgt, ohne wertvolle Flugmeister oder Wachen von ihren essenziellen Posten abzuziehen.",al={"warum ich","warum liefert garrett sie nicht selbst","warum ich return to podrig"}}},fp="16,163,25.241.0,21.324.0,26.120.0,25.138.0,23.122.0,65.184.0,44.169.0,19.139.0"}
P.entries["quest:633"] = {n="Der Thandolübergang",s="Am Thandol-Übergang gefährdet ein Mord Eisenschmiedes Straße nach Norden. Ebenezer Rustlocke ist tot, und Rhag Garmason hat Sprengstoff gefunden, den Kam Tiefenzorn versteckt hat.",h="Am Thandol-Übergang gefährdet ein Mord Eisenschmiedes Straße nach Norden.",kw={"arathihochland","dunkeleisenzwerge","ebon rustlocke","sprengstoff","kam tiefenzorn","magni bronzebart","rhag garmason","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Den Übergang zu halten, ist für die Sicherheit des Kontinents entscheidend. Fällt der Übergang, wird es weitaus gefährlicher, Armeen und Nachschub der Allianz nach Arathi und Lordaeron zu bringen.",["profession:Engineering"]="Als Ingenieur könnt Ihr die Zerstörungskraft von Deepfurys Munitionslager erkennen. Es wurde angelegt, um gewaltiges zwergisches Steinwerk im Stil der Titanen zu sprengen.",["race:Dwarf"]="Für die Söhne Eisenschmiedes sichert die Verteidigung des Thandol-Übergangs King Magnis Lebensader zu den Verbündeten im Norden. Sie versetzt auch den Unterwanderern der Dunkeleisenzwerge einen Schlag, die ihr eigenes Volk verraten haben."},sec={{t="Ein Komplott enthüllt",b="Ein geborgenes Dokument enthüllt das Verbrechen unter dem Thandol-Übergang. Ebenezer Rustlocke wurde im Unterbau der Brücke ermordet. Die Papiere enthüllen mehr: Kam Tiefenzorn, der Agitator der Dunkeleisenzwerge, der zuerst einen Teil der Brücke zerstörte, hat nicht aufgehört. Sein Netzwerk versteckte ein weiteres Lager schwerer Munition gleich jenseits der nördlichen Grenze im Arathihochland, bereit, die Zerstörung zu vollenden."},{t="Die Lebensader retten",b="Der Übergang verbindet Khaz Modan und Sturmwind mit den vom Krieg zerrütteten Gebieten im Norden. Rhag Garmason befiehlt einen sofortigen Angriff auf das Sabotagelager in Arathi, bevor Deepfurys Verschwörer es nutzen können. Die Zerstörung der Munition bannt die unmittelbare Gefahr und hält Eisenschmiedes Straße nach Norden offen. Doch Garmason hat noch immer zu wenige Truppen, um die Bresche zu verteidigen."}},faq={{q="Wer ist Kam Tiefenzorn?",a="Kam Tiefenzorn ist der Drahtzieher der Dunkeleisenzwerge hinter der Sabotage am Thandol-Übergang. Nachdem er den ersten Bogen zum Einsturz gebracht hatte, versteckte er jenseits der Schlucht im Arathihochland weiteren Sprengstoff, um den Rest der Brücke zu zerstören.",al={"kam tiefenzorn","wer sprengte den thandol-übergang","drahtzieher am thandol-übergang"}},{q="Warum ist der Thandol-Übergang strategisch so wichtig?",a="Der Übergang ist die einzige Landbrücke über die gewaltige Schlucht zwischen dem Sumpfland und dem Arathihochland. Fällt er, verliert die Allianz ihren wichtigsten Versorgungsweg über Land zwischen Eisenschmiede, Sturmwind und ihren Verbündeten, die im nördlichen Lordaeron ihre Stellungen halten.",al={"warum ist der thandol-übergang wichtig","geschichte des thandol-übergangs"}},{q="Was geschah mit Ebenezer Rustlocke?",a="Ebenezer Rustlocke war ein Verteidiger Eisenschmiedes, der unter der Brücke ermordet wurde. Seine Ermittlungen und die geborgenen Papiere führten Rhag Garmason zu Deepfurys verborgenem Sprengstofflager.",al={"ebon rustlockes tod","wer war rustlocke"}},{q="Wo ist das Sprengstofflager versteckt?",a="Der Sprengstoff war gleich jenseits des Übergangs auf der Seite des Arathihochlands versteckt. Deepfurys Verschwörer konnten ihn schnell zum verbliebenen Brückenbauwerk bringen.",al={"fundort des sprengstoffs","wo ist der sprengstoff","fundort des lagers"}},{q="Wer befiehlt die Zerstörung des Sprengstoffs?",a="Rhag Garmason, ein am Thandol-Übergang auf der Seite des Sumpflands stationierter Zwergenoffizier, befiehlt, das Lager zu finden und zu sprengen. Er will Rustlockes Opfer ehren und die verbliebene Brücke schützen.",al={"wer vergibt diese quest","rhag garmason"}},{q="Was geschieht nach der Zerstörung der Munition?",a="Mit der Zerstörung der Munition endet die unmittelbare Sabotagegefahr. Rhag Garmason weiß, dass seine Garnison die beschädigte Brücke ohne Hilfe nicht auf Dauer halten kann. Während er auf Eisenschmiedes Reserven wartet, schickt er ein Gesuch um Verstärkung an Captain Nials im Allianzlager in der Zuflucht im Arathihochland.",al={"was folgt nach dem thandol-übergang","quest hilfegesuch an die allianz"}}},fx={a60c1dfd={q="Warum möchte Rhag Garmason, dass die Sprengstoffe zerstört werden?",a="Rhag Garmason erfuhr aus Rustlockes geborgenem Pergament, dass Kam Tiefenzorn plante, eine weitere Explosion mit einem versteckten Vorrat auf der anderen Seite der Brücke auszulösen. Einer der Übergänge des Thandol-Übergangs ist bereits zerstört; wenn es den Dunkeleisen-Verschwörern gelingt, den verbleibenden Teil zu sprengen, wird die lebenswichtige Allianz-Versorgungsroute, die Khaz Modan mit Lordaeron und dem Arathihochland verbindet, vollständig unterbrochen werden.",al={"motiv von rhag garmason","warum sprengstoffe zerstören","warum sprengstoffe am thandol-übergang zerstören"}},b9ac4adc={q="Warum schickt Rhag Garmason einen Abenteurer anstatt seiner eigenen Wachen?",a="Rhag und die wenigen Zwergenverteidiger am Brückenkopf sind kritisch überbeansprucht und halten die Position gegen feindliche Einfälle, während sie verzweifelt auf das Eintreffen von Verstärkungen warten. Da Ebenezer Rustlocke bereits den Verschwörern zum Opfer gefallen ist, kann Rhag niemanden von der Linie entbehren, um in das von Feinden besetzte Gebiet in Arathi zu schlüpfen, was Euch zu ihrer einzigen Hoffnung macht, eine Katastrophe abzuwenden.",al={"warum ich","warum mich schicken","warum schickt rhag keine wachen"}}},fp="16,162,15.391.0,19.348.1,20.212.0,47.250.0,36.178.1,40.164.0,46.197.0,47.318.1"}
P.entries["quest:634"] = {n="Hilfegesuch an die Allianz",s="Am zerstörten Thandol-Übergang überbringt Hilfegesuch an die Allianz Dun Modrs verzweifelten Hilferuf. Infiltratoren der Dunkeleisen haben die Garnison niedergemetzelt, und die überlebenden Zwerge bitten die Menschenstreitkräfte in der Zuflucht um Hilfe, obwohl die Allianz kaum Kräfte entbehren kann.",h="Am zerstörten Thandol-Übergang überbringt Hilfegesuch an die Allianz Dun Modrs verzweifelten Hilferuf.",kw={"arathihochland","captain nials","dunkeleisen","dun modr","langzopf","die zuflucht","rhag garmason","stromgarde","thandol-übergang"},ang={["faction:Alliance"]="Für die Allianz zeigt dieser Austausch, wie zersplittert ihre Gebiete im Norden der Östlichen Königreiche weiterhin sind. Die örtlichen Garnisonen führen getrennte, verzweifelte Kämpfe ohne gemeinsame Reserven.",["race:Dwarf"]="Die Zwerge schmerzt Dun Modrs Isolation. Selbst ihre langjährigen menschlichen Verbündeten werden zu sehr bedrängt, um ihnen beizustehen.",["race:Human"]="Als menschlicher Reisender erlebt Ihr Captain Nials' Kummer, während er die Verbundenheit innerhalb der Allianz gegen Stromgardes Überleben abwägt."},sec={{t="Ein Ruf über die Kluft",b="Dun Modr liegt in Trümmern, und Zwerge der Dunkeleisen haben den Thandol-Übergang sabotiert. Die Überlebenden halten sich an einem Brückenkopf am nördlichen Rand des Sumpflands. Die Hauptreserven aus Eisenschmiede sind noch nicht eingetroffen, also blicken Rhag Garmason und Langzopf der Grimmige nach Norden ins Arathihochland. Dort erfahren sie, dass Streitkräfte der Allianz in der Zuflucht lagern. Garmason schickt einen Boten über die zerstörte Brücke, um Captain Nials um dringende militärische Hilfe zu bitten."},{t="Stromgardes Notlage",b="In der Zuflucht bekundet Captain Nials Langzopfs Soldaten sein Mitgefühl, kann aber keinen einzigen Kämpfer entbehren. Stromgarde liegt in Trümmern, überrannt von Schurken des Syndikats, Boulderfist-Ogern und Witherbark-Trollen. Die überlebenden Verteidiger widmen sich der Rückeroberung ihrer angestammten Hauptstadt. Durch seine Ehre gebunden und vom eigenen verzweifelten Kampf bedrängt, lässt Nials ausrichten, dass die Zwerge am Übergang allein standhalten müssen."}},faq={{q="Wer schickt das Hilfegesuch an die Zuflucht?",a="Nahe dem zerstörten Brückenkopf des Thandol-Übergangs an der Grenze zum Sumpfland schickt Rhag Garmason das Hilfegesuch für Langzopf den Grimmigen und Dun Modrs verbliebene Verteidiger.",al={"wer vergibt hilfegesuch an die allianz","rhag garmason quest","wer bittet um hilfe"}},{q="Warum brauchen die Zwerge Hilfe aus der Zuflucht?",a="Infiltratoren des Dunkeleisenklans haben Dun Modr angegriffen und den Thandol-Übergang sabotiert. Während die Überlebenden auf die starken Reservetruppen aus Eisenschmiede warten, fehlen ihnen die nötigen Kämpfer, um ihre Siedlung allein zurückzuerobern und den Übergang zu sichern.",al={"warum hilfe der allianz nötig","warum die zuflucht fragen","dun modr verstärkung"}},{q="Warum weigert sich Captain Nials, Soldaten zu schicken?",a="Captain Nials kann keine Truppen entbehren, weil Stromgarde in Trümmern liegt. Die Menschenstreitkräfte in der Zuflucht widmen sich der Rückeroberung der Stadt vom Syndikat, den Ogern und den Waldtrollen.",al={"warum keine hilfe von nials","warum die zuflucht ablehnt","captain nials antwort"}},{q="Wo liegt die Zuflucht?",a="Die Zuflucht liegt etwas abseits der Hauptstraße im zentralen Arathihochland, nördlich des Thandol-Übergangs zwischen dem Sumpfland und Arathi.",al={"zuflucht lage","wo ist captain nials","wie die zuflucht finden"}},{q="Was ist mit Dun Modr geschehen?",a="Nachdem sich der Dunkeleisenklan durch die Berge eingeschlichen hatte, um den Landweg zwischen den südlichen Zwergenlanden und den nördlichen Allianzgebieten zu kappen, überrannte und plünderte er Dun Modr.",al={"dun modr hintergrundgeschichte","was geschah mit dun modr","wer griff dun modr an"}},{q="Was geschieht, nachdem Captain Nials das Gesuch ablehnt?",a="Captain Nials übermittelt Langzopf dem Grimmigen sein Bedauern und bestätigt, dass keine Verstärkung der Menschen kommen wird. Die überlebenden Zwerge an der Brücke müssen sich auf ihren eigenen Einfallsreichtum, umherziehende Abenteurer und die ferne Verstärkung aus Eisenschmiede verlassen.",al={"was folgt auf hilfegesuch an die allianz","nächste quest nach dem hilfegesuch","fortsetzung der questreihe"}}},fx={["0e006c4d"]={q="Warum bittet Euch Rhag Garmason, das Gesuch zu überbringen, anstatt selbst zu gehen?",a="Rhag Garmason und die überlebenden Gebirgssoldaten sind am The Thandol Span eingekesselt und halten dort einen prekären Stützpunkt. Da Dun Modr überrannt wurde und die Reserven aus Eisenschmiede noch weit entfernt sind, können sie keinen einzigen Zwerg vom Wachdienst entbehren, um nach Norden durch gefährliches Land zu reisen.",al={"warum ich gesuch allianz","warum rhag schickt euch","warum kann rhag nicht zur die zuflucht"}}},fp="20,249,22.432.0,24.410.0,36.158.0,48.211.0,47.188.0,31.142.0,26.190.0,56.232.0"}
P.entries["quest:6341"] = {n="Auf nach Darnassus",s="Nessa Schattensang vergleicht die Fische Teldrassils mit dem Fang vom Festland. Sie schickt Proben aus Rut'theran nach Auberdine, um herauszufinden, ob die Inselfische größer und zahlreicher sind.",h="Nessa Schattensang vergleicht die Fische Teldrassils mit dem Fang vom Festland.",kw={"auberdine","bounty of teldrassil","dunkelküste","hippogryph","laird","nessa shadowsong","rut'theran","vesprystus"},ang={["faction:Alliance"]="Für die Allianz verbindet die Route zwischen Rut'theran und Auberdine die Hauptstadt der Nachtelfen mit dem übrigen nördlichen Kalimdor.",["race:NightElf"]="Für Nachtelfen führt die Reise von den Höhen Teldrassils zu den Festlandufern der Dunkelküste."},sec={{t="Die Untersuchung einer Fischerin",b="Nessa Schattensang bittet Euch, Fischgräten und Schuppen zu Laird in Auberdine zu bringen. Die Fischer in Rut'theran machen reiche Fänge mit großen Fischen. Nessa möchte herausfinden, ob die Gewässer des Festlands dieselbe Art von Fischen hervorbringen. Anhand der Proben kann Laird den Inselfang mit Fischen von der Küste der Dunkelküste vergleichen."},{t="Die Überfahrt vorbereiten",b="Nessa Schattensang schickt Euch mit der Sammlung für Auberdine zu Vesprystus, dem Hippogryphenmeister in Rut'theran. Übergebt ihm die Proben, und er organisiert Eure Überfahrt zur Dunkelküste."}},faq={{q="Was möchte Nessa untersuchen?",a="Nessa Schattensang möchte die großen, zahlreichen Fische aus den Gewässern um Rut'theran mit Fischen von der Festlandküste der Dunkelküste vergleichen. Sie schickt Gräten und Schuppen, damit Laird sie vergleichen kann.",al={"nessas ziel","warum fische vergleichen","bounty of teldrassil zweck"}},{q="Wer erhält die Fischproben in Auberdine?",a="Laird, ein Fischhändler in Auberdine, erhält die Sammlung von Nessa Schattensang.",al={"wer bekommt nessas sammlung","laird dunkelküste","auberdine fischhändler"}},{q="Warum soll das Paket zu Vesprystus gebracht werden, statt direkt nach Auberdine zu reisen?",a="Vesprystus ist der Hippogryphenmeister in Rut'theran. Nessa schickt Euch mit der Sammlung zu ihm, damit er die Überfahrt zur Dunkelküste organisieren kann.",al={"warum vesprystus","wer ist vesprystus","hippogryphenmeister rut'theran"}},{q="Wo liegt Rut'theran im Verhältnis zu Teldrassil?",a="Rut'theran liegt am südlichen Fuß Teldrassils auf Meereshöhe. Ein smaragdgrünes Portal verbindet den Ort mit Darnassus, und sein Hafen dient Schiffen und Hippogryphen auf dem Weg zum großen Baum und zurück.",al={"rut'theran lage","wo ist nessa shadowsong","wie rut'theran erreichen"}},{q="Was geschieht, nachdem die Sammlung an Vesprystus übergeben wurde?",a="Nachdem Vesprystus die Sammlung angenommen hat, bietet er Flight to Auberdine an. Ein Hippogryph trägt Euch über die Meerenge zur Dunkelküste.",al={"nach flight to auberdine","nach bounty of teldrassil","was macht vesprystus"}},{q="Gehört dies zum Verlassen des Startgebiets der Nachtelfen?",a="Ja. Diese Questreihe macht junge Nachtelfenabenteurer mit Flugrouten vertraut und führt sie von Teldrassil zur Dunkelküste, wo sie ihre Reisen fortsetzen.",al={"teldrassil verlassen","nachtelfenquest stufe zehn","weiter zur dunkelküste"}}},fx={["4163d491"]={q="Warum benötigt Nessa Schattensang Euch, um die Sammlung zu überbringen?",a="Nessa Schattensang geht ihren Pflichten und Nachforschungen an den Docks von Rut'theran nach. Da ständig Reisende die Insel verlassen, ist es weit einfacher, ihr Paket mit Proben einem fähigen Abenteurer zu übergeben, der ohnehin zur Dunkelküste reist, als ihre Arbeit zu unterbrechen, um den Transport über das Meer selbst zu organisieren.",al={"warum ich nessa","warum braucht nessa hilfe","warum abenteurer zu vesprystus schicken"}}},fp="24,191,19.308.0,17.203.0,36.189.0,47.81.0,77.158.0,62.199.0,55.128.0,58.152.0"}
P.entries["quest:6342"] = {n="Ein unerwartetes Geschenk",s="Ihr bringt ungewöhnliche Fischexemplare aus Teldrassil zu Laird nach Auberdine. Vesprystus schickt Euch von Rut'theran aus auf einem Hippogryphen los.",h="Ihr bringt ungewöhnliche Fischexemplare aus Teldrassil zu Laird nach Auberdine.",kw={"auberdine","dunkelküste","flugroute","ein unerwartetes geschenk","hippogryph","laird","nessa shadowsong","rut'theran","teldrassil","vesprystus"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr auf Hippogryphen zwischen den Küstenaußenposten im Norden Kalimdors und der Hauptstadt reisen.",["race:NightElf"]="Als Nachtelf fliegt Ihr auf einem Hippogryphen nach Auberdine, ein Übergangsritus für junge kaldorei, die Teldrassil in Richtung des angestammten Festlands verlassen."},sec={{t="Auf Schwingen zur Dunkelküste",b="Von Rut'theran aus fliegt Ihr auf einem Hippogryphen mit Fischexemplaren für Nessa Schattensang zur Dunkelküste. Das Dorf ist für junge Abenteurer, die Teldrassil verlassen, eine Zuflucht an der Schwelle zur weiten Welt. Eine Fähre überquert auch die Meerenge zwischen der Insel und dem Festland von Kalimdor, während Nachtelfen auf Hippogryphen reisen, mit denen sie verbunden sind."},{t="Sonderbare Fänge",b="An den Docks von Auberdine untersucht Laird Nessas Funde. Die Schuppen sind faustgroß, und der Kieferknochen ist beinahe doppelt so groß wie Exemplare vom Festland. Die Gewässer rund um den Fuß des Weltbaums scheinen veränderte oder ungewöhnlich große Lebewesen hervorzubringen. Die seltsamen Fänge könnten mit Teldrassils mächtigem, rastlosem Wesen zusammenhängen."}},faq={{q="Welchen Zweck hat dieser Flug?",a="Ihr bringt ungewöhnliche Fischexemplare aus den Gewässern um Rut'theran zu Laird nach Auberdine, auf einem Hippogryphenflug zwischen den Siedlungen.",al={"warum nach auberdine fliegen","ein unerwartetes geschenk questziel","warum fliegen"}},{q="Wer schickt das Paket, und was ist darin?",a="Nessa Schattensang, eine Fischerin, schickt das Paket. Es enthält Fischexemplare aus den Gewässern von Rut'theran, darunter gewaltige Schuppen und einen übergroßen Kieferknochen.",al={"nessas sammlung","was ist im paket","wer hat das paket geschickt"}},{q="Warum sind die Fische aus Teldrassil so groß?",a="Laird findet faustgroße Schuppen und einen Kieferknochen, der beinahe doppelt so groß ist wie gewöhnlich. Die Gewässer um Teldrassils Weltbaum scheinen im Vergleich zum Festland der Dunkelküste größere Tiere hervorzubringen.",al={"warum sind die fische groß","fischgröße rut'theran","riesige schuppen"}},{q="Wer ist Vesprystus?",a="Vesprystus ist der Hippogryphenmeister in Rut'theran. Er versorgt die Reittiere der Nachtelfen und organisiert Flüge über das Wasser zum Festland von Kalimdor.",al={"vesprystus hintergrund","wer ist der hippogryphenmeister"}},{q="Wer ist Laird?",a="Laird ist ein Nachtelfenfischer in Auberdine an der Dunkelküste. Er erforscht die örtlichen Wasserlebewesen und vergleicht Fänge vom Festland mit denen aus der Nähe von Teldrassil.",al={"laird hintergrund","wer ist laird","laird dunkelküste"}},{q="Könnt Ihr zwischen Rut'theran und Auberdine reisen, ohne zu fliegen?",a="Ja. Eine regelmäßige Fähre verkehrt zwischen den Docks von Rut'theran und dem Anleger von Auberdine und bietet eine Alternative zum Hippogryphenflug.",al={"boot nach auberdine","fähre zur dunkelküste","anderer weg nach auberdine"}}},fx={ddbceafb={q="Warum schickt Euch Vesprystus nach Auberdine?",a="Als Hippogryphenmeister von Rut'theran überwacht Vesprystus den wichtigen Reiseverkehr zwischen Teldrassil und dem Festland von Kalimdor. Er hat zwar Nessa Shadowsongs Paket mit ungewöhnlichen Fischproben für Laird in Auberdine bei sich, doch sein Hauptanliegen ist es, Reisende mit dem Flugnetzwerk der Nachtelfen vertraut zu machen. Indem er Euch auf dem Rücken eines Hippogryphen über das Wasser schickt, stellt er sicher, dass Ihr eine Verbindung zum Flugmeister von Auberdine aufbaut und so schnellen Transport über die Dunkelküste für Eure zukünftigen Reisen ermöglicht.",al={"warum möchte vesprystus dies erledigt haben","vesprystus motiv","warum paket auberdine schicken"}}},fp="19,132,24.326.0,15.314.0,35.135.0,44.162.0,42.181.0,18.150.0,13.158.0,63.142.0"}
P.entries["quest:6343"] = {n="Rückkehr zu Nyoma",s="Laird schickt Euch mit seinen Erkenntnissen von Auberdine zu Nessa Schattensang in Rut'theran. Dieser einführende Botengang lehrt junge Reisende, zwischen Kalimdor und Teldrassil überzusetzen.",h="Laird schickt Euch mit seinen Erkenntnissen von Auberdine zu Nessa Schattensang in Rut'theran.",kw={"auberdine","caylais moonfeather","dunkelküste","laird","nessa shadowsong","rückkehr zu nyoma","rut'theran","teldrassil"},ang={["faction:Alliance"]="Als Reisende der Allianz seid Ihr zwischen Auberdine und Rut'theran unterwegs. Dieses Tor zur See verbindet die Nachtelfensiedlungen im Norden Kalimdors mit den Interessen der Allianz in ganz Azeroth.",["race:NightElf"]="Als Nachtelf, der Teldrassils Äste zum ersten Mal verlässt, übernehmt Ihr Euren ersten offiziellen Botengang zwischen der Inselzuflucht und dem uralten Festland der Dunkelküste."},sec={{t="Ein Bote übers Meer",b="Laird schickt Euch mit seinen schriftlichen Beobachtungen zurück übers Wasser. Fische vor der Dunkelküste unterscheiden sich deutlich von denen nahe Teldrassil. Er vermutet, dass der große Weltbaum das Leben in diesen Gewässern verändert. Ihr könnt beim Hippogryphenmeister Caylais Moonfeather einen Flug buchen oder die regelmäßig verkehrende Fähre vom Pier in Auberdine nach Rut'theran nehmen."},{t="Wundersame Fänge",b="In Rut'theran erhält Nessa Schattensang Lairds Antwort und ist fasziniert von den Unterschieden im Meeresleben. Fische nahe dem Weltbaum werden so groß, dass die örtlichen Fischer unmittelbar davon profitieren, doch die Kaldorei wissen nicht, warum. Nessa plant, die Erkenntnisse mit ihren Mitdorfbewohnern zu teilen. Vorerst schöpft sie aus dem reichen Meeresleben und hält nach Kräften Ausschau, die dafür verantwortlich sein könnten."}},faq={{q="Bei wem beginnt und endet diese Quest?",a="Laird, der Fischer in Auberdine an der Dunkelküste, schickt Euch zu Nessa Schattensang in Rut'theran am Fuße Teldrassils.",al={"questgeber","wo abgeben","wer vergibt die quest"}},{q="Wie gelangt man am schnellsten zurück nach Rut'theran?",a="Ihr könnt mit Caylais Moonfeather, dem Hippogryphenmeister in Auberdine, fliegen oder die regelmäßig verkehrende Passagierfähre vom langen Pier nach Rut'theran nehmen.",al={"wie zurückkommen","reise nach rut'theran","fähre oder hippogryph"}},{q="Warum untersucht Laird die Fische?",a="Laird untersucht die Fische, weil sich die Fänge entlang der Dunkelküste stark von denen rund um Teldrassil unterscheiden. Er vermutet, dass das Wachstum und die einzigartigen Energien des Weltbaums die Tierwelt der Umgebung verändern.",al={"warum fische untersuchen","unterschied zwischen den fischen","hintergrund zu lairds antwort"}},{q="Findet Nessa heraus, warum die Fische so seltsam sind?",a="Nessa erfährt nicht sofort, warum die Fische so seltsam sind. Sie bemerkt den Unterschied und stimmt zu, dass er weitere Untersuchungen verdient. Sie teilt den Bericht mit den Dorfbewohnern und erfreut sich vorerst an den reichen Fängen.",al={"warum sind die fische groß","teldrassils fischrätsel"}},{q="Was kommt vor dieser Quest?",a="'Flight to Auberdine' geht dieser Reise voraus. Dabei wird Nessas ursprünglicher Brief von Rut'theran zu Laird an der Dunkelküste gebracht.",al={"voraussetzung","vorherige quest","flight to auberdine"}},{q="Welchen Zweck hat diese Questreihe?",a="Die Questreihe führt in Teldrassils geheimnisvollen Einfluss auf die örtliche Tierwelt ein. Sie lehrt junge Nachtelfenabenteurer, wie sie mithilfe von Schiffen und Flugmeistern zwischen ihrer Inselheimat und dem Festland von Kalimdor reisen.",al={"warum diese quest machen","reisequest"}}},fx={c6069b83={q="Warum möchte Laird, dass dieser Brief an Nessa überbracht wird?",a="Laird möchte Nessa Schattensang umgehend über den dramatischen Unterschied zwischen dem Meeresleben entlang der Küste der Dunkelküste und den Gewässern von Teldrassil informieren. Er vermutet, dass Teldrassil selbst einen ungewöhnlichen Einfluss auf die umliegende Meeresfauna ausübt, und das Teilen seiner Beobachtungen hilft den Dorfbewohnern, die seltsame Beute zu verstehen, die sie ernten.",al={"warum antwort an nessa schicken","laird antwort zweck","warum möchte laird dies erledigt haben"}}},fp="15,182,26.346.0,16.385.0,36.137.0,51.151.0,31.187.0,48.205.0,29.130.0,40.204.0"}
P.entries["quest:6344"] = {n="Nessa Schattensang",s="Unterhalb des Weltbaums in Darnassus schickt Mydrannul einen Kurier zu Nessa Schattensang. Die Lieferung führt von Rut'theran zur Dunkelküste und verbindet die Stadt im Blätterdach mit der Küste.",h="Unterhalb des Weltbaums in Darnassus schickt Mydrannul einen Kurier zu Nessa Schattensang.",kw={"auberdine","kurier","dunkelküste","darnassus","mydrannul","nessa schattensang","portal","rut'theran","die tempelgärten"},ang={["faction:Alliance"]="Als Abenteurer der Allianz lernt Ihr, wie Teldrassil mit den anderen Gebieten der Allianz auf Kalimdor verbunden ist.",["race:NightElf"]="Als Nachtelf verlasst Ihr die Höhen von Darnassus und folgt den Küstenrouten, die Eure Heimat mit den uralten Ufern der Dunkelküste verbinden."},sec={{t="Ein Auftrag jenseits des Blätterdachs",b="In Darnassus hält Mydrannul Ausschau nach Reisenden, die Arbeit und eine Bestimmung suchen. Die Angelhändlerin Nessa Schattensang muss ein Paket über das Meer zur Dunkelküste bringen lassen, also schickt Mydrannul fähige Kuriere zur Küste. Viele junge Nachtelfen beginnen ihre Reisen zwischen den Ästen von Teldrassil. Diese Lieferung führt sie über den Baum hinaus."},{t="Hinab zu den Anlegestegen",b="Von den Tempelgärten aus führt das westliche Portal in Darnassus durch den Weltbaum hinab nach Rut'theran. An den Wurzeln auf Meereshöhe verbinden Angelstege und Hippogryphenlandeplätze Teldrassil mit dem Rest von Kalimdor. Nessa Schattensang geht dort ihrem Handel nach und bereitet Lieferungen für Auberdine vor."}},faq={{q="Wer vergibt diese Quest?",a="Mydrannul bietet den Lieferauftrag in Darnassus auf der Terrasse der Krieger an.",al={"questgeber","wo beginnt die quest nessa schattensang","mydrannul standort"}},{q="Wie gelange ich nach Rut'theran?",a="Geht von den Tempelgärten aus nach Westen und tretet durch das große, leuchtende Baumportal. Es bringt Euch hinab nach Rut'theran am Fuße von Teldrassil.",al={"wie nach rut'theran gelangen","rut'theran portal","darnassus verlassen"}},{q="Wer ist Nessa Schattensang?",a="Nessa Schattensang bietet an den Anlegestegen von Rut'theran Angelbedarf an. Sie beaufsichtigt den Transport von Waren und Paketen zwischen Teldrassil und der Dunkelküste.",al={"nessa schattensang rolle","was macht nessa","nessa schattensang npc"}},{q="Wohin führt diese Questreihe?",a="Das Gespräch mit Nessa führt zu 'The Bounty of Teldrassil'. Dabei lernt Ihr den Flugmeister kennen und unternehmt Euren ersten Flug über das Wasser nach Auberdine.",al={"was kommt nach nessa schattensang","nächste quest der reihe","teldrassil flugquestreihe"}},{q="Ist Nessa mit Maiev Shadowsong verwandt?",a="Nessa und Maiev Shadowsong tragen denselben Nachnamen, doch eine persönliche Verbindung zwischen ihnen ist nicht überliefert. Nessa ist eine Angelhändlerin am Hafen, während Maiev eine legendäre Wächterin ist.",al={"nessa maiev verwandtschaft","familie shadowsong","ist nessa mit maiev verwandt"}},{q="Warum ist dieser Auftrag für junge Abenteurer wichtig?",a="Auf dieser Reise lernen junge Abenteurer, die Krone von Teldrassil zu verlassen, die Anlegestege darunter zu erreichen und über Hippogryphenflugrouten zum Festland von Kalimdor zu gelangen.",al={"warum diese quest machen","bedeutung der quest"}}},fx={feb9b9a4={q="Warum möchte Mydrannul, dass dies erledigt wird?",a="Mydrannul tut lediglich einem Freund einen Gefallen. Nessa Schattensang arbeitet unten in Rut'theran als Fischereilieferantin und benötigt einen zuverlässigen Boten, um ein Paket über das Meer zur Dunkelküste zu befördern. Mydrannul nutzt seinen Posten in Darnassus, um nach fähigen Reisenden Ausschau zu halten, die bereit sind, die Äste hinunterzugehen und ihr zu helfen.",al={"warum nessa helfen","mydrannul grund","warum zu nessa shadowsong schicken"}}},fp="16,189,26.330.0,23.299.0,22.69.0,35.149.0,24.147.0,33.151.0,37.169.0,51.154.0"}
P.entries["quest:635"] = {n="Kristall in den Bergen",s="In Arathis nördlichen Bergen zieht Euch eine Vision zu einem schimmernden Kristall. Der Anhänger von Myzrael pulsiert in Eurer Hand, während Euch ein Hilferuf erreicht.",h="In Arathis nördlichen Bergen zieht Euch eine Vision zu einem schimmernden Kristall.",kw={"arathihochland","kristall","kristall in den bergen","anhänger von myzrael","shards of myzrael","vision"},sec={{t="Ein stummes Flehen",b="Der Anhänger von Myzrael pulsiert in Eurer Hand und trägt das Flehen von jemandem zu Euch, der Hilfe braucht. Dann zeigt Euch eine Vision einen schimmernden Kristall, der in den Bergen nördlich von Arathi aus dem Boden ragt. Ihr fühlt Euch dorthin gezogen."},{t="Am Kristall",b="Am Kristall deutet sein Pulsieren darauf hin, dass eine lebendige Kraft in ihm gefangen ist."}},faq={{q="Was setzt diese Reise in Gang?",a="Der Anhänger von Myzrael setzt diese Reise in Gang. Während Ihr ihn haltet, pulsiert er mit dem Flehen von jemandem, der verzweifelt Hilfe braucht.",al={"wie erhält man kristall in den bergen","woher kommt der anhänger von myzrael","kristall in den bergen start"}},{q="Wohin führt die Vision?",a="Die Vision führt Euch zu einem schimmernden Kristall in Arathis nördlichen Bergen. Ihr fühlt Euch dorthin gezogen.",al={"wo ist der kristall","kristall in den bergen fundort","kristall aus der vision finden"}}},fp="24,152,13.210.0,14.68.1,25.121.0,27.96.0"}
